window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["商务部"] = {"guanyuwaishangtouzijubantouzixinggongsideguidingde198ea7":[],"duiwailaowuhezuojingyingzigeguanlibanfabuchongguid62b3c5":[],"kuajingfuwumaoyitebieguanlicuoshiheziyoumaoyishiya8753e8":[],"bukekaoshitiqingdanguiding":[{"i":1,"n":"第一条","txt":"为了维护国家主权、安全、发展利益，维护公平、自由的国际经贸秩序，保护中国企业、其他组织或者个人的合法权益，根据《中华人民共和国对外贸易法》、《中华人民共和国国家安全法》等有关法律，制定本规定。"},{"i":2,"n":"第二条","txt":"国家建立不可靠实体清单制度，对外国实体在国际经贸及相关活动中的下列行为采取相应措施： （一）危害中国国家主权、安全、发展利益； （二）违反正常的市场交易原则，中断与中国企业、其他组织或者个人的正常交易，或者对中国企业、其他组织或者个人采取歧视性措施，严重损害中国企业、其他组织或者个人合法权益。 本规定所称外国实体，包括外国企业、其他组织或者个人。"},{"i":3,"n":"第三条","txt":"中国政府坚持独立自主的对外政策，坚持互相尊重主权、互不干涉内政和平等互利等国际关系基本准则，反对单边主义和保护主义，坚决维护国家核心利益，维护多边贸易体制，推动建设开放型世界经济。"},{"i":4,"n":"第四条","txt":"国家建立中央国家机关有关部门参加的工作机制（以下简称工作机制），负责不可靠实体清单制度的组织实施。工作机制办公室设在国务院商务主管部门。"},{"i":5,"n":"第五条","txt":"工作机制依职权或者根据有关方面的建议、举报，决定是否对有关外国实体的行为进行调查；决定进行调查的，予以公告。"},{"i":6,"n":"第六条","txt":"工作机制对有关外国实体的行为进行调查，可以采取询问有关当事人、查阅或者复制相关文件、资料以及其他必要的方式。调查期间，有关外国实体可以陈述、申辩。 工作机制可以根据实际情况决定中止或者终止调查；中止调查决定所依据的事实发生重大变化的，可以恢复调查。"},{"i":7,"n":"第七条","txt":"工作机制根据调查结果，综合考虑以下因素，作出是否将有关外国实体列入不可靠实体清单的决定，并予以公告： （一）对中国国家主权、安全、发展利益的危害程度； （二）对中国企业、其他组织或者个人合法权益的损害程度； （三）是否符合国际通行经贸规则； （四）其他应当考虑的因素。"},{"i":8,"n":"第八条","txt":"有关外国实体的行为事实清楚的，工作机制可以直接综合考虑本规定第七条规定的因素，作出是否将其列入不可靠实体清单的决定；决定列入的，予以公告。"},{"i":9,"n":"第九条","txt":"将有关外国实体列入不可靠实体清单的公告中可以提示与该外国实体进行交易的风险，并可以根据实际情况，明确该外国实体改正其行为的期限。"},{"i":10,"n":"第十条","txt":"对列入不可靠实体清单的外国实体，工作机制根据实际情况，可以决定采取下列一项或者多项措施（以下称处理措施），并予以公告： （一）限制或者禁止其从事与中国有关的进出口活动； （二）限制或者禁止其在中国境内投资； （三）限制或者禁止其相关人员、交通运输工具等入境； （四）限制或者取消其相关人员在中国境内工作许可、停留或者居留资格； （五）根据情节轻重给予相应数额的罚款； （六）其他必要的措施。 前款规定的处理措施，由有关部门按照职责分工依法实施，其他有关单位和个人应当配合实施。"},{"i":11,"n":"第十一条","txt":"将有关外国实体列入不可靠实体清单的公告中明确有关外国实体改正期限的，在期限内不对其采取本规定第十条规定的处理措施；有关外国实体逾期不改正其行为的，依照本规定第十条的规定对其采取处理措施。"},{"i":12,"n":"第十二条","txt":"有关外国实体被限制或者禁止从事与中国有关的进出口活动，中国企业、其他组织或者个人在特殊情况下确需与该外国实体进行交易的，应当向工作机制办公室提出申请，经同意可以与该外国实体进行相应的交易。"},{"i":13,"n":"第十三条","txt":"工作机制根据实际情况，可以决定将有关外国实体移出不可靠实体清单；有关外国实体在公告明确的改正期限内改正其行为并采取措施消除行为后果的，工作机制应当作出决定，将其移出不可靠实体清单。 有关外国实体可以申请将其移出不可靠实体清单，工作机制根据实际情况决定是否将其移出。 将有关外国实体移出不可靠实体清单的决定应当公告；自公告发布之日起，依照本规定第十条规定采取的处理措施停止实施。"},{"i":14,"n":"第十四条","txt":"本规定自公布之日起施行。"}],"liangyongwuxianghejishuchukoutongyongxukeguanlibanb36d31":[{"i":1,"n":"第一条","txt":"为维护国家安全和社会公共利益，完善两用物项和技术出口管理，依据《中华人民共和国对外贸易法》和有关行政法规规章的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称有关行政法规规章是指《中华人民共和国核两用品及相关技术出口管制条例》、《中华人民共和国生物两用品及相关设备和技术出口管制条例》、《中华人民共和国导弹及相关物项和技术出口管制条例》、《有关化学品及相关设备和技术出口管制办法》等。 本办法所称两用物项和技术是指前款有关行政法规规章管制的物项和技术。"},{"i":3,"n":"第三条","txt":"本办法所称两用物项和技术出口通用许可是指商务部根据两用物项和技术出口经营者的申请，依照有关行政法规规章和本办法的规定进行审查，准予其持商务部签发的两用物项和技术出口通用许可批复，依据许可有效期和范围，在《两用物项和技术进出口许可证管理办法》（商务部、海关总署2005年第29号令）规定的发证机构多次申领两用物项和技术出口许可证的行为。 未取得两用物项和技术出口通用许可，出口经营者应当依据有关行政法规规章的规定，逐单申请出口许可。"},{"i":4,"n":"第四条","txt":"商务部是全国两用物项和技术出口通用许可的主管部门。 商务部委托的省级商务主管部门按照本办法的规定，负责本地区两用物项和技术出口通用许可的日常监督管理。"},{"i":5,"n":"第五条","txt":"两用物项和技术出口通用许可分为甲类通用许可和乙类通用许可。 甲类通用许可允许出口经营者在许可有效期内向一个或多个特定国家（或地区）的一个或多个最终用户，出口一种或多种特定两用物项和技术。 乙类通用许可允许出口经营者在许可有效期内向同一特定国家（或地区）的固定最终用户多次出口同种类特定两用物项和技术。"},{"i":6,"n":"第六条","txt":"两用物项和技术出口通用许可有效期不超过三年。"},{"i":7,"n":"第七条","txt":"国家对两用物项和技术出口通用许可的实施进行严格审查。两用物项和技术出口通用许可经营者（以下简称\"通用许可经营者\"）应当满足以下条件： （一） 是合法的对外贸易经营者； （二） 建立企业两用物项和技术内部控制机制； （三）从事两用物项和技术出口业务两年以上（含两年）； （四）申请甲类通用许可的，应当连续两年以上（含两年）年申领两用物项和技术出口许可数量超过40份（含40份）；申请乙类通用许可的，应当连续两年以上（含两年）年申领同种类两用物项和技术出口许可数量超过30份（含30份）； （五） 近3年内未受过刑事处罚或受过有关部门行政处罚； （六） 有相对固定的两用物项和技术销售渠道及最终用户。"},{"i":8,"n":"第八条","txt":"两用物项和技术通用许可经营者应当向商务部提出通用许可申请，并向商务部委托的省级商务主管部门提交下列申请材料： （一）两用物项和技术出口通用许可申请表； （二） 企业两用物项和技术内部控制机制建立和运行情况说明及相关证明文件； （三）近3年内未受过刑事处罚或受过有关部门行政处罚的保证文书； （四） 合法的对外贸易经营者的证明文件； （五）从事两用物项和技术出口业务情况说明，包括：近两年两用物项和技术出口许可证申领及使用情况说明；两用物项和技术销售渠道及用户情况说明，包括与交易各方关系、交易情况及进口商和最终用户说明； （六） 拟申请出口通用许可的物项和技术的种类及相关技术说明文件； （七）依照有关行政法规规章规定，每份合同执行前向最终用户索取相关保证文书或最终用户和最终用途说明文件的保证文件； （八）主管部门要求提交的其他文件。 两用物项和技术出口通用许可申请表由商务部统一制定。"},{"i":9,"n":"第九条","txt":"商务部委托的省级商务主管部门自收到本办法第八条规定的文件之日起10个工作日内将申请材料送商务部。商务部自收到申请材料之日起，依照有关行政法规规章的规定进行审查或会同有关部门进行审查，并做出许可或者不予许可的决定。予以许可的，由商务部签发两用物项和技术出口通用许可批复；不予许可的，应当说明理由。 在审查过程中，商务部或其委托的省级商务主管部门可以根据需要约谈企业主要管理人员，了解企业内部出口控制机制建立和执行情况。必要时，可对企业进行实地考察验证。 在审查过程中，商务部可以委托专家咨询机构对企业内部出口控制机制的建立及运行情况进行评估。专家咨询机构由商务部确定，并以公告形式对外发布。"},{"i":10,"n":"第十条","txt":"下列情形不适用通用许可： （一）企业已建立完备的内部出口控制机制但无法确认其有效执行的； （二）有关行政主管部门认为出口存在扩散风险以及其他不适宜通用许可的。"},{"i":11,"n":"第十一条","txt":"通用许可经营者无法判断拟出口的物项和技术是否符合有关行政法规规章规定，或者无法判断拟出口的物项和技术是否属于通用许可范围，应当依照有关行政法规规章的规定，逐单申请出口许可。"},{"i":12,"n":"第十二条","txt":"严禁伪造、变造、买卖或者转让两用物项和技术出口通用许可批复；严禁超出许可范围使用两用物项和技术出口通用许可批复或者利用两用物项和技术通用许可批复从事扰乱市场竞争秩序的违法违规行为。"},{"i":13,"n":"第十三条","txt":"通用许可经营者获得商务部签发的两用物项和技术出口通用许可批复后，凭加盖企业公章的批复文件到《两用物项和技术进出口许可证管理办法》规定的两用物项和技术出口许可证发证机构申领两用物项和技术出口许可证。 两用物项和技术出口许可证申领的其他程序依照《两用物项和技术进出口许可证管理办法》执行。"},{"i":14,"n":"第十四条","txt":"通用许可经营者应当按照国家有关出口管制政策、法规要求，有效执行企业内部控制机制。"},{"i":15,"n":"第十五条","txt":"通用许可经营者应当如实提供申请材料并妥善保存依照有关行政法规规章规定的保证文书或最终用户和最终用途说明以及合同、发票、账册、单据、记录、文件、业务函电、录音录像制品和其他资料五年。"},{"i":16,"n":"第十六条","txt":"通用许可经营者知道或者应当知道，或者得到商务部或其委托的省级商务主管部门通知，或者在从事相关两用物项和技术出口过程中发现，其拟出口的物项和技术存在危害国家安全和社会公共利益风险时，应当立即暂停或停止相关出口活动，采取必要的补救措施，并及时向商务部及其委托的省级商务主管部门报告。"},{"i":17,"n":"第十七条","txt":"通用许可经营者应当在通用许可有效期内，主动了解两用物项和技术出口管制政策、法规，参加商务主管部门举办的相关培训。"},{"i":18,"n":"第十八条","txt":"通用许可经营者应当依照企业内部控制机制的要求，检查机制执行情况，如实向商务部及其委托的省级商务主管部门报告本企业出现的违法违规行为，并积极配合商务部及其委托的省级商务主管部门做好相关工作。"},{"i":19,"n":"第十九条","txt":"通用许可经营者应当在通用许可有效期内每六个月及通用许可有效期截止之日起30日内向商务部及其委托的省级商务部主管部门报告通用许可使用情况，包括两用物项和技术的出口时间、物项种类、规格型号、数量、贸易方式、出口国（地区）、进口商、最终用户、最终用途以及运输途径和报关口岸等。"},{"i":20,"n":"第二十条","txt":"商务部应当及时通过\"出口管制政务平台\"或其他媒介发布相关出口管制政策、法规，对通用许可经营者进行政策、法规培训。"},{"i":21,"n":"第二十一条","txt":"商务部、商务部委托的省级商务主管部门以及商务部委托的专家咨询机构可以根据通用许可经营者的要求，提供相关培训和技术指导。"},{"i":22,"n":"第二十二条","txt":"商务部或其委托的省级商务主管部门可以对通用许可经营者进行监督检查。必要时，可进行实地检查。通用许可经营者应当予以配合、协助，如实提供有关情况和材料、物品。"},{"i":23,"n":"第二十三条","txt":"实地检查时，商务部或其委托的省级商务主管部门可以通过询问相关工作人员、查询复制本办法第十四条规定保存的资料等方式对企业内部控制机制的执行情况进行检查，并提出整改意见。"},{"i":24,"n":"第二十四条","txt":"实地检查时，检查人员不得少于2人，并出示合法证件。检查人员少于2人或者未出示合法证件的，通用许可经营者有权拒绝检查。"},{"i":25,"n":"第二十五条","txt":"对存在危害国家安全和社会公共利益风险的出口行为，商务部或其委托的省级商务主管部门依照有关行政法规规章和本办法的规定，可以要求两用物项和技术出口通用许可经营者暂停或停止相关物项和技术的出口，必要时，可以撤销通用许可或采取任何必要措施，维护国家安全和社会公共利益。"},{"i":26,"n":"第二十六条","txt":"未取得通用许可出口两用物项和技术的，或者伪造、变造、买卖或转让两用物项和技术出口通用许可批复的，或者以欺骗及其他不正当手段获取两用物项和技术出口通用许可的，或者超出通用许可范围出口两用物项和技术的，依照有关行政法规规章处罚；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"通用许可经营者违反本办法第四章规定的，商务部可以要求其限期改正；情节严重的，可以取消其出口通用许可，并依照有关行政法规规章规定予以处罚。"},{"i":28,"n":"第二十八条","txt":"本办法由商务部负责解释。"},{"i":29,"n":"第二十九条","txt":"本办法自2009年7月1日起施行。"}],"liangyongwuxianghejishujinchukouxukezhengguanlibane02665":[{"i":1,"n":"第一条","txt":"为维护国家安全和社会公共利益，履行我国在缔结或者参加的国际条约、协定中所承担的义务，加强两用物项和技术进出口许可证管理，依据《中华人民共和国对外贸易法》、《中华人民共和国海关法》和有关行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称有关行政法规系指《中华人民共和国核出口管制条例》、《中华人民共和国核两用品及相关技术出口管制条例》、《中华人民共和国导弹及相关物项和技术出口管制条例》、《中华人民共和国生物两用品及相关设备和技术出口管制条例》、《中华人民共和国监控化学品管理条例》、《中华人民共和国易制毒化学品管理条例》及《有关化学品及相关设备和技术出口管制办法》。 本办法所称两用物项和技术是指前款有关行政法规管制的物项和技术。"},{"i":3,"n":"第三条","txt":"商务部是全国两用物项和技术进出口许可证的归口管理部门，负责制定两用物项和技术进出口许可证管理办法及规章制度，监督、检查两用物项和技术进出口许可证管理办法的执行情况，处罚违规行为。"},{"i":4,"n":"第四条","txt":"商务部会同海关总署制定和发布《两用物项和技术进出口许可证管理目录》（见附件1，以下简称 《管理目录》）。商务部和海关总署可以根据情况对《管理目录》进行调整，并以公告形式发布。"},{"i":5,"n":"第五条","txt":"商务部委托商务部配额许可证事务局(以下简称许可证局)统一管理、指导全国各发证机构的两用物项和技术进出口许可证发证工作，许可证局对商务部负责。 许可证局和商务部委托的省级商务主管部门为两用物项和技术进出口许可证发证机构(以下简称发证机构)，省级商务主管部门在许可证局的统一管理下，负责委托范围内两用物项和技术进出口许可证的发证工作。《两用物项和技术进出口许可证发证机构名单》附后（见附件2）。"},{"i":6,"n":"第六条","txt":"以任何方式进口或出口，以及过境、转运、通运《管理目录》中的两用物项和技术，均应申领两用物项和技术进口或出口许可证（许可证格式见附件3）。 两用物项和技术在境外与保税区、出口加工区等海关特殊监管区域、保税场所之间进出的，适用前款规定。 两用物项和技术在境内与保税区、出口加工区等海关特殊监管区域、保税场所之间进出的，或者在上述海关监管区域、保税场所之间进出的，无需办理两用物项和技术进出口许可证。"},{"i":7,"n":"第七条","txt":"两用物项和技术进出口时，进出口经营者应当向海关出具两用物项和技术进出口许可证，依照海关法的有关规定，海关凭两用物项和技术进出口许可证接受申报并办理验放手续。"},{"i":8,"n":"第八条","txt":"根据有关行政法规的规定，出口经营者知道或者应当知道，或者得到国务院相关行政主管部门通知，其拟出口的物项和技术存在被用于大规模杀伤性武器及其运载工具风险的，无论该物项和技术是否列入《管理目录》，都应当申请出口许可，并按照本办法办理两用物项和技术出口许可证。 出口经营者在出口过程中，如发现拟出口的物项和技术存在被用于大规模杀伤性武器及其运载工具风险的，应及时向国务院相关行政主管部门报告，并积极配合采取措施中止合同的执行。"},{"i":9,"n":"第九条","txt":"两用物项和技术的进出口经营者应当主动向海关出具两用物项和技术进出口许可证，进出口经营者未向海关出具两用物项和技术进出口许可证而产生的相关法律责任由进出口经营者自行承担。 海关有权对进出口经营者进口或者出口的商品是否属于两用物项和技术提出质疑，进出口经营者应按规定向相关行政主管部门申请进口或者出口许可，或者向商务主管部门申请办理不属于管制范围的相关证明。省级商务主管部门受理其申请，提出处理意见后报商务部审定。对进出口经营者未能出具两用物项和技术进口或者出口许可证或者商务部相关证明（格式见附件4）的，海关不予办理有关手续。"},{"i":10,"n":"第十条","txt":"实施临时进出口管制的两用物项和技术的进出口许可证管理，适用本办法。"},{"i":11,"n":"第十一条","txt":"进出口经营者获相关行政主管部门批准文件后，凭批准文件到所在地发证机构申领两用物项和技术进口或者出口许可证（在京的中央企业向许可证局申领），其中： （一）核、核两用品、生物两用品、有关化学品、导弹相关物项、易制毒化学品和计算机进出口的批准文件为商务主管部门签发的两用物项和技术进口或者出口批复单。其中，核材料的出口凭国防科工委的批准文件办理相关手续。 外商投资企业进出口易制毒化学品凭《商务部外商投资企业易制毒化学品进口批复单》或《商务部外商投资企业易制毒化学品出口批复单》申领进出口许可证。 （二）监控化学品进出口的批准文件为国家履行禁止化学武器公约工作领导小组办公室签发的监控化学品进口或者出口核准单。监控化学品进出口经营者向许可证局申领两用物项和技术进出口许可证。"},{"i":12,"n":"第十二条","txt":"通过对外交流、交换、合作、赠送、援助、服务等形式出口两用物项和技术的，视为正常出口，出口经营者应按规定申请出口许可，并按本办法办理两用物项和技术出口许可证。"},{"i":13,"n":"第十三条","txt":"两用物项和技术进出口许可证实行网上申领。申领两用物项和技术进出口许可证时应提交下列文件： （一）本办法第十一条规定的有关批准文件。 （二）进出口经营者公函（介绍信）原件、进出口经营者领证人员的有效身份证明以及网上报送的两用物项和技术进出口许可证申领表。 如因异地申领等特殊情况，需要委托他人申领两用物项和技术进出口许可证的，被委托人应提供进出口经营者出具的委托公函（其中应注明委托理由和被委托人身份）原件和被委托人的有效身份证明。"},{"i":14,"n":"第十四条","txt":"发证机构收到相关行政主管部门批准文件（含电子文本、数据）和相关材料并经核对无误后，应在3个工作日内签发两用物项和技术进口或者出口许可证。"},{"i":15,"n":"第十五条","txt":"两用物项和技术进口许可证实行“非一批一证”制和“一证一关”制，同时在两用物项和技术进口许可证备注栏内打印“非一批一证”字样。 两用物项和技术出口许可证实行“一批一证”制和“一证一关”制。同一合同项下的同一商品如需分批办理出口许可证，出口经营者应在申领时提供相关行政主管部门签发的相应份数的两用物项和技术出口批准文件。同一次申领分批量最多不超过十二批。 “非一批一证”制是指每证在有效期内可多次报关使用，但最多不超过十二次，由海关在许可证背面“海关验放签注栏”内逐批核减数量；“一批一证”制是指每证只能报关使用一次；“一证一关”制是指每证只能在一个海关报关使用。"},{"i":16,"n":"第十六条","txt":"两用物项和技术进出口许可证一式四联。第一联为办理海关手续联；第二联为海关留存核对联；第三联为银行办理结汇联；第四联为发证机构留存联。"},{"i":17,"n":"第十七条","txt":"进出口经营者在申领两用物项和技术进出口许可证时，应如实申报，不得弄虚作假，严禁以假合同、假文件等欺骗或其他不正当手段获取两用物项和技术进出口许可证。"},{"i":18,"n":"第十八条","txt":"“一批一证”制的大宗、散装的两用物项在报关时溢装数量不得超过两用物项和技术出口许可证所列出口数量的5%。“非一批一证”制的大宗、散装两用物项，每批进口时，按其实际进口数量进行核扣，最后一批进口物项报关时，其溢装数量按该两用物项和技术进口许可证实际剩余数量并在规定的溢装上限5%内计算。"},{"i":19,"n":"第十九条","txt":"赴境外参加或举办展览会运出境外的展品，参展单位（出口经营者）应凭出境经济贸易展览会审批部门批准办展的文件，按规定申请两用物项和技术出口许可，并按本办法办理两用物项和技术出口许可证。 对于非卖展品，应在两用物项和技术出口许可证备注栏内注明“非卖展品”字样。参展单位应在展览会结束后六个月内，将非卖展品如数运回境内，由海关凭有关出境时的单证予以核销。在特殊情况下，可向海关申请延期，但延期最长不得超过六个月。"},{"i":20,"n":"第二十条","txt":"运出境外的两用物项和技术的货样或实验用样品，视为正常出口，出口经营者应按规定申请两用物项和技术出口许可，并按本办法办理两用物项和技术出口许可证。"},{"i":21,"n":"第二十一条","txt":"进出境人员随身携带药品类易制毒化学品药品制剂和高锰酸钾的，按照《易制毒化学品管理条例》中的规定执行，并接受海关监管。"},{"i":22,"n":"第二十二条","txt":"对于民用航空零部件等两用物项和技术以特定海关监管方式出口的管理另有规定的，依照其规定。"},{"i":23,"n":"第二十三条","txt":"凡两用物项和技术出口涉及国营贸易管理和出口配额管理商品的，出口经营者须具备相应的资格条件。"},{"i":24,"n":"第二十四条","txt":"两用物项和技术进出口许可证仅限于申领许可证的进出口经营者使用。 两用物项和技术进出口许可证不得买卖、转让、涂改、伪造和变造。"},{"i":25,"n":"第二十五条","txt":"两用物项和技术进出口许可证应在批准的有效期内使用，逾期自动失效，海关不予验放。"},{"i":26,"n":"第二十六条","txt":"两用物项和技术进出口许可证有效期一般不超过一年。 两用物项和技术进出口许可证跨年度使用时，在有效期内只能使用到次年3月31日，逾期发证机构将根据原许可证有效期换发许可证。"},{"i":27,"n":"第二十七条","txt":"两用物项和技术进出口许可证一经签发，任何单位和个人不得更改证面内容。 如需对证面内容进行更改，进出口经营者应当在许可证有效期内向相关行政主管部门重新申请进出口许可，并凭原许可证和新的批准文件向发证机构申领两用物项和技术进出口许可证。"},{"i":28,"n":"第二十八条","txt":"两用物项和技术进口许可证证面的进口商、收货人应分别与海关进口货物报关单的经营单位、收货单位相一致；两用物项和技术出口许可证证面的出口商、发货人应分别与海关出口货物报关单的经营单位、发货单位相一致。"},{"i":29,"n":"第二十九条","txt":"已领取的两用物项和技术进出口许可证发生遗失的，进出口经营者应当立即向相关行政主管部门和原发证机构及许可证证面注明的口岸地海关书面报告，并在全国性经济类报刊登载“遗失声明”。发证机构凭遗失声明，并核实该证确未通关后，可注销该许可证，并依据原许可证内容签发新证。"},{"i":30,"n":"第三十条","txt":"进出口经营者应妥善保存两用物项和技术进出口的文件和有关资料五年，以备相关行政主管部门检查。"},{"i":31,"n":"第三十一条","txt":"任何单位和个人均可向商务部或海关举报进出口经营者违反国家有关法律、行政法规和本办法规定的行为。商务部和海关应为举报者保密，并依法对违规行为予以查处。对查证属实的，主管机关按有关规定可给予举报者奖励。"},{"i":32,"n":"第三十二条","txt":"发证机构应及时传送发证数据，保证进出口经营者顺利报关和海关核查；对海关反馈的核查数据应认真核对，定时检查两用物项和技术进出口许可证的使用情况并找出存在的问题。许可证局应当每季度将核对后的海关反馈核查数据报商务部。"},{"i":33,"n":"第三十三条","txt":"各发证机构不得越权或者超范围发放两用物项和技术进出口许可证。越权或者超范围发放的两用物项和技术进出口许可证无效。 对于前款所涉进出口许可证，一经查实，商务部予以吊销。对海关在实际监管或者案件处理过程中发现的涉及上述许可证的问题，发证机构应当给予明确回复。"},{"i":34,"n":"第三十四条","txt":"商务部授权许可证局对各发证机构进行检查。检查的内容为发证机构执行本办法的情况，重点是检查是否有越权或者超发证范围违章发证以及其他违反本办法的问题。检查的方式，实行各发证机构定期或者不定期自查与许可证局抽查相结合的办法。 许可证局应当将检查的情况向商务部报告。"},{"i":35,"n":"第三十五条","txt":"未经许可，或者超出许可范围进出口两用物项和技术的，依照有关法律、行政法规处罚；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"违反本办法规定，走私两用物项和技术的，由海关依照《中华人民共和国海关法》、《中华人民共和国海关行政处罚实施条例》的有关规定给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"伪造、变造或者买卖两用物项和技术进出口许可证的，依照刑法关于非法经营罪或者伪造、变造、买卖国家机关公文、证件、印章罪的规定，依法追究刑事责任；尚不够刑事处罚的，依照《中华人民共和国海关法》及有关法律、行政法规的规定给予行政处罚。 以欺骗或者其他不正当手段获取两用物项和技术进出口许可证的，商务部依法吊销其许可证，并可给予警告，或处三万元以下罚款。"},{"i":38,"n":"第三十八条","txt":"对违反第十九条规定，未将属于两用物项和技术出口许可证管理的非卖展品按期如数运回由海关核销的，由海关按有关规定处理，并将有关情况通知商务部和出境经济贸易展览会审批机构。 商务部可给予该组展单位和参展单位警告，或对组展单位处一万元以下罚款。"},{"i":39,"n":"第三十九条","txt":"依据《中华人民共和国对外贸易法》，商务部可自第三十五条至三十八条规定的行政处罚决定生效之日起或者刑事处罚判决生效之日起一年以上三年以下的期限内，禁止违法行为人从事有关的对外贸易经营活动。"},{"i":40,"n":"第四十条","txt":"对违反本办法第三十三条，越权或者超范围发证的发证机构，商务部可暂停或者取消对其发证委托。"},{"i":41,"n":"第四十一条","txt":"发证机构工作人员玩忽职守、徇私舞弊或者滥用职权，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，应当调离工作岗位，并依法给予行政处分。"},{"i":42,"n":"第四十二条","txt":"商务部对委托的发证机构进行调整时，自调整之日起，原发证机构不得再签发两用物项和技术进出口许可证。进出口经营者在发证机构调整前申领的两用物项和技术进出口许可证在有效期内继续有效。"},{"i":43,"n":"第四十三条","txt":"本办法由商务部和海关总署按照各自职责负责解释。"},{"i":44,"n":"第四十四条","txt":"本办法自二○○六年一月一日起施行。 《敏感物项和技术出口许可证暂行管理办法》（商务部、海关总署2003年第9号令），商务部、海关总署2003年第74号公告，《海关总署关于保税区内企业经营航空发动机修理等业务出境监管问题的通知》（署法发〔2004〕235号），《海关总署办公厅 外经贸部办公厅关于敏感物项和技术出口证件海关验放问题的通知》（署办发〔2002〕89号），《政法司、监管司关于明确敏感物项和技术出口许可证海关监管问题的通知》（政法函〔2004〕2号）同时废止。 《货物出口许可证管理办法》（商务部2004年27号令）和《货物进口许可证管理办法》（商务部2004年28号令）与本办法不一致的，以本办法为准。 　　附件：1、两用物项和技术进出口许可证管理目录 　　　　　2、两用物项和技术进出口许可证发证机构名单 　　　　　3、中华人民共和国两用物项和技术进口许可证 　　　　　　　中华人民"}],"guojihuowuyunshudailiyeguanliguidingshishixize":[{"i":1,"n":"第一条","txt":"为维护国际货运代理市场秩序，加强对国际货运代理业的监督管理，促进我国国际货运代理业的健康发展，经国务院批准、根据原外经贸部一九九五年六月二十九日发布的《中华人民共和国国际货物运输代理业管理规定》(以下简称《规定》)制订本细则。"},{"i":2,"n":"第二条","txt":"国际货物运输代理企业(以下简称国际货运代理企业)可以作为进出口货物收货人、发货人的代理人，也可以作为独立经营人，从事国际货运代理业务。 国际货运代理企业作为代理人从事国际货运代理业务，是指国际货运代理企业接受进出口货物收货人、发货人或其代理人的委托，以委托人名义或者以自己的名义办理有关业务，收取代理费或佣金的行为。 国际货运代理企业作为独立经营人从事国际货运代理业务，是指国际货运代理企业接受进出口货物收货人、发货人或其代理人的委托，签发运输单证、履行运输合同并收取运费以及服务费的行为。"},{"i":3,"n":"第三条","txt":"国际货运代理企业的名称、标志应当符合国家有关规定，与其业务相符合，并能表明行业特点，其名称应当含有\"货运代理\"、\"运输服务\"、\"集运\"或\"物流\"等相关字样。"},{"i":4,"n":"第四条","txt":"《规定》第四条第二款中\"授权的范围\"是指省、自治区、直辖市、经济特区、计划单列市人民政府商务主管部门在商务部的授权下，负责对本行政区域内国际货运代理业实施监督管理(商务部和地方商务主管部门以下统称行业主管部门)，该授权范围包括：对企业经营国际货运代理业务项目申请的初审、国际货运代理企业的年审和换证审查、业务统计、业务人员培训、指导地方行业协会开展工作以及会同地方有关行政管理部门规范货运代理企业经营行为、治理货运代理市场经营秩序等工作。 国务院部门直属企业和异地企业在计划单列市(不含经济特区)设立的国际货运代理子公司、分支机构及非营业性办事机构，根据前款的授权范围，接受省对外贸易主管部门的监督管理。 任何其他单位，未经商务部授权，不得从事国际货运代理业的审批或管理工作。"},{"i":5,"n":"第五条","txt":"商务部负责对国际货运代理企业人员的业务培训并对培训机构的资格进行审查。未经批准的单位不得从事国际货运代理企业人员的资格培训。培训机构的设立条件及培训内容、培训教材等由商务部另行规定。 从事国际货运代理业务的人员接受前款规定的培训，经考试合格后，取得国际货物运输代理资格证书。"},{"i":6,"n":"第六条","txt":"国际货代企业的股东可由企业法人、自然人或其他经济组织组成。与进出口贸易或国际货物运输有关、并拥有稳定货源的企业法人应当为大股东，且应在国际货代企业中控股。企业法人以外的股东不得在国际货代企业中控股。"},{"i":7,"n":"第七条","txt":"国际货运代理企业应当依据取得中华人民共和国企业法人资格。企业组织形式为有限责任公司或股份有限公司。禁止具有行政垄断职能的单位申请投资经营国际货运代理业务。承运人以及其他可能对国际货运代理行业构成不公平竞争的企业不得申请经营国际货运代理业务。"},{"i":8,"n":"第八条","txt":"《规定》第七条规定的营业条件包括： (一)具有至少5名从事国际货运代理业务3年以上的业务人员，其资格由业务人员原所在企业证明；或者，取得商务部根据本细则第五条颁发的资格证书； (二)有固定的营业场所，自有房屋、场地须提供产权证明；租赁房屋、场地，须提供租赁契约； (三)有必要的营业设施，包括一定数量的电话、传真、计算机、短途运输工具、装卸设备、包装设备等； (四)有稳定的进出口货源市场，是指在本地区进出口货物运量较大，货运代理行业具备进一步发展的条件和潜力，并且申报企业可以揽收到足够的货源。"},{"i":9,"n":"第九条","txt":"企业申请的国际货运代理业务经营范围中如包括国际多式联运业务，除应当具备《规定》第七条及本细则第六条、第七条、第八条中的条件外，还应当具备下列条件： (一)从事本细则第三十二条中有关业务3年以上； (二)具有相应的国内、外代理网络； (三)拥有在商务部登记备案的国际货运代理提单。"},{"i":10,"n":"第十条","txt":"国际货运代理企业每申请设立一个分支机构，应当相应增加注册资本50万元人民币。如果企业注册资本已超过《规定》中的最低限额(海运500万元，空运300万元，陆运、快递200万元)，则超过部分，可作为设立分支机构的增加资本。"},{"i":11,"n":"第十一条","txt":"《规定》及本细则中所称分支机构是指分公司。"},{"i":12,"n":"第十二条","txt":"经营国际货运代理业务，必须取得商务部颁发的《中华人民共和国国际货物运输代理企业批准证书》(以下简称批准证书)。 申请经营国际货运代理业务的单位应当报送下列文件： (一)申请书，包括投资者名称、申请资格说明、申请的业务项目； (二)可行性研究报告，包括基本情况、资格说明、现有条件、市场分析、业务预测、组建方案、经济预算及发展预算等； (三)投资者的企业法人营业执照(影印件)； (四)董事会、股东会或股东大会决议； (五)企业章程(或草案)； (六)主要业务人员情况(包括学历、所学专业、业务简历、资格证书)； (七)资信证明(会计师事务所出具的各投资者的验资报告)； (八)投资者出资协议； (九)法定代表人简历； (十)国际货运代理提单(运单)样式； (十一)企业名称预先核准函(影印件，工商行政管理部门出具)； (十二)国际货运代理企业申请表1(附表1)； (十三)交易条款。 以上文件除("},{"i":13,"n":"第十三条","txt":"行业主管部门应当对申请项目进行审核，该审核包括： (一)项目设立的必要性； (二)申请文件的真实性和完整性； (三)申请人资格； (四)申请人信誉； (五)业务人员资格。"},{"i":14,"n":"第十四条","txt":"地方商务主管部门对申请项目进行审核后，应将初审意见(包括建议批准的经营范围、经营地域、投资者出资比例等)及全部申请文件按照《规定》第十一条第一款的时间要求，报商务部审批。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，商务部驳回申请，并说明理由： (一)文件不齐； (二)申报程序不符合要求； (三)商务部已经通知暂停受理经营国际货运代理业务的申请。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，商务部经过调查核实后，给予不批准批复： (一)申请人不具备从事国际货运代理业务的资格； (二)申请人自申报之日前5年内非法从事代理经营活动，受到国家行政管理部门的处罚； (三)申请人故意隐瞒、谎报申报情况； (四)其他不符合《规定》第五条有关原则的情况。"},{"i":17,"n":"第十七条","txt":"申请人收到商务部同意的批复的，应当于批复之日起60天内持修改后的企业章程(正本)，凭地方商务主管部门介绍信到商务部领取批准证书。"},{"i":18,"n":"第十八条","txt":"企业成立并经营国际货运代理业务1年后，可申请扩大经营范围或经营地域。地方商务主管部门经过审查后，按《规定》第十一条规定的程序向商务部报批。 企业成立并经营国际货运代理业务1年后，在形成一定经营规模的条件下，可申请设立子公司或分支机构，并由该企业持其所在地地方商务主管部门的意见(国务院部门在京直属企业持商务部的征求意见函)，向拟设立子公司或分支机构的地方商务主管部门(不含计划单列市)进行申报，后者按照本细则第十四条的规定向商务部报批。子公司或分支机构的经营范围不得超出其母公司或总公司。 国际货运代理企业设立非营业性的办事机构，必须报该办机构所在地行业主管部门备案并接受管理。"},{"i":19,"n":"第十九条","txt":"企业根据本细则第十八条第一款、第二款提出的申请，除报送本细则第十二条中有关文件外，还应当报送下列文件： (一)原国际货运代理业务批复(影印件)； (二)批准证书(影印件)； (三)营业执照(影印件)； (四)国际货运代理企业申请表2(附表2，设立子公司的为附表1)； (五)经营情况报告(含网络建设情况)； (六)子公司法定代表人或分支机构负责人简历； (七)上一年度年审登记表。"},{"i":20,"n":"第二十条","txt":"企业申请设立分支机构，申请人收到同意的批复后，应当于批复之日起９０天内持总公司根据本细则第十条规定增资后具有法律效力的验资报告及修改后的企业章程(正本)，凭分支机构所在地地方商务主管部门介绍信到商务部领取批准证书。"},{"i":21,"n":"第二十一条","txt":"申请人逾期不办理领证手续或者自领取批准证书之日起超过１８０天无正当理由未开始营业的，除申请延期获准外，其国际货运代理业务经营资格自动丧失。"},{"i":22,"n":"第二十二条","txt":"商务部可以根据国际货运代理业行业发展、布局等情况，决定在一定期限内停止受理经营国际货物运输代理业务的申请或者采取限制性措施。 商务部依照前款规定作出的决定，应当予以公告。"},{"i":23,"n":"第二十三条","txt":"国际货运代理企业发生以下变更，必须报商务部审批，并换领批准证书： (一)企业名称； (二)企业类型； (三)股权关系； (四)注册资本减少； (五)经营范围； (六)经营地域。 发生以下变更，在报商务部备案后，直接换领批准证书： (一)通讯地址或营业场所； (二)法定代表人； (三)注册资本增加； (四)隶属部门。"},{"i":24,"n":"第二十四条","txt":"国际货运代理企业应当持批准证书向工商、海关部门办理注册登记手续。 任何未取得批准证书的单位，不得在工商营业执照上使用\"国际货运代理业务\"或与其意思相同或相近的字样。"},{"i":25,"n":"第二十五条","txt":"商务部对国际货运代理企业实行年审、换证制度。"},{"i":26,"n":"第二十六条","txt":"商务部负责国务院部门在京直属企业的年审及全国国际货运代理企业的换证工作。地方商务主管部门负责本行政区域内国际货运代理企业(含国务院部门直属企业及异地企业设立的子公司、分支机构)的年审工作。"},{"i":27,"n":"第二十七条","txt":"国际货运代理企业于每年３月底前向其所在地地方商务主管部门(国务院部门在京直属企业直接向商务部)报送年审登记表(附表３)、验资报告及营业执照(影印件)，申请办理年审。 年审工作的重点是审查企业的经营及遵守执行《规定》和其他有关法律、法规、规章情况。企业年审合格后，由行业主管部门在其批准证书上加盖年审合格章。"},{"i":28,"n":"第二十八条","txt":"批准证书的有效期为３年。 企业必须在批准证书有效期届满的６０天前，向地方商务主管部门申请换证。企业申请换领批准证书应当报送下列文件： (一)申请换证登记表(附表4)； (二)批准证书(正本)； (三)营业执照(影印件)。"},{"i":29,"n":"第二十九条","txt":"企业连续三年年审合格，地方商务主管部门应当于批准证书有效期届满的３０天前报送商务部，申请换领批准证书。"},{"i":30,"n":"第三十条","txt":"行业主管部门在国际货运代理企业申请换证时应当对其经营资格及经营情况进行审核，有下列情形之一的，不予换发批准证书： (一)不符合本细则第二十七条规定； (二)不按时办理换证手续； (三)私自进行股权转让； (四)擅自变更企业名称、营业场所、注册资本等主要事项而不按有关规定办理报备手续。"},{"i":31,"n":"第三十一条","txt":"企业因自身原因逾期未申请换领批准证书，其从事国际货运代理业务的资格自批准证书有效期届满时自动丧失。商务部将对上述情况予以公布。工商行政管理部门对上述企业予以注销或责令其办理经营范围变更手续。 丧失国际货运代理业务经营资格的企业如欲继续从事该项业务，应当依照有关规定程序重新申报。"},{"i":32,"n":"第三十二条","txt":"国际货运代理企业可以作为代理人或者独立经营人从事经营活动。其经营范围包括： (一)揽货、订舱(含租船、包机、包舱)、托运、仓储、包装； (二)货物的监装、监卸、集装箱装拆箱、分拨、中转及相关的短途运输服务； (三)报关、报检、报验、保险； (四)缮制签发有关单证、交付运费、结算及交付杂费； (五)国际展品、私人物品及过境货物运输代理； (六)国际多式联运、集运(含集装箱拼箱)； (七)国际快递(不含私人信函)； (八)咨询及其他国际货运代理业务。"},{"i":33,"n":"第三十三条","txt":"国际货运代理企业应当按照批准证书和营业执照所列明的经营范围和经营地域从事经营活动。"},{"i":34,"n":"第三十四条","txt":"商务部根据行业发展情况，可委托行业协会参照国际惯例制订国际货运代理标准交易条款，国际货运代理企业无需商务部同意即可引用。国际货运代理企业也可自己制订交易条款，但必须在商务部备案后方可使用。"},{"i":35,"n":"第三十五条","txt":"国际货运代理企业应当向行业主管部门报送业务统计，并对统计数字的真实性负责。业务统计的编报办法由商务部另行规定。"},{"i":36,"n":"第三十六条","txt":"国际货运代理企业作为代理人接受委托办理有关业务，应当与进出口收货人、发货人签订书面委托协议。双方发生业务纠纷，应当以所签书面协议作为解决争议的依据。 国际货运代理企业作为独立经营人，从事本细则第三十二条中有关业务，应当向货主签发运输单证。与货主发生业务纠纷，应当以所签运输单证作为解决争议的依据；与实际承运人发生业务纠纷，应当以其与实际承运人所签运输合同作为解决争议的依据。"},{"i":37,"n":"第三十七条","txt":"国际货运代理企业使用的国际货运代理提单实行登记编号制度。凡在我国境内签发的国际货运代理提单必须由国际货运代理企业报商务部登记，并在单据上注明批准编号。 国际货运代理企业应当加强对国际货运代理提单的管理工作。禁止出借。如遇遗失、版本修改等情况应当及时向商务部报备。 国际货运代理提单的转让依照下列规定执行： (一)记名提单：不得转让； (二)指示提单：经过记名背书或者空白背书转让； (三)不记名提单：无需背书，即可转让。 国际货运代理提单实行责任保险制度，须到经中国人民银行批准开业的保险公司投保责任保险。"},{"i":38,"n":"第三十八条","txt":"国际货运代理企业作为独立经营人，负责履行或组织履行国际多式联运合同时，其责任期间自接收货物时起至交付货物时止。其承担责任的基础、责任限额、免责条件以及丧失责任限制的前提依照有关法律规定确定。"},{"i":39,"n":"第三十九条","txt":"国际货运代理企业应当使用批准证书上的企业名称和企业编号从事国际货运代理业务，并在主要办公文具及单证上印制企业名称及企业编号。"},{"i":40,"n":"第四十条","txt":"国际货运代理企业不得将规定范围内的注册资本挪作他用。"},{"i":41,"n":"第四十一条","txt":"国际货运代理企业不得将国际货运代理经营权转让或变相转让；不得允许其他单位、个人以该国际货运代理企业或其营业部名义从事国际货运代理业务；不得与不具有国际货运代理业务经营权的单位订立任何协议而使之可以单独或与之共同经营国际货运代理业务，收取代理费、佣金或者获得其他利益。"},{"i":42,"n":"第四十二条","txt":"国际货运代理企业作为代理人，可向货主收取代理费，并可从承运人处取得佣金。国际货运代理企业不得以任何形式与货主分享佣金。 国际货运代理企业作为独立经营人，从事本细则第三十二条中有关业务，应当依照有关运价本向货主收取费用。此种情况下，不得从实际承运人处接受佣金。"},{"i":43,"n":"第四十三条","txt":"外国企业(包括香港、澳门、台湾地区企业，以下同)驻华代表机构只能从事非直接经营性活动，代表该企业进行其经营范围内的业务联络、产品介绍、市场调研、技术交流等业务活动。"},{"i":44,"n":"第四十四条","txt":"国际货运代理企业应当凭批准证书向税务机关领购发票，并按照税务机关的规定使用发票。"},{"i":45,"n":"第四十五条","txt":"国际货运代理企业不得以发布虚假广告、分享佣金、退返回扣或其他不正当竞争手段从事经营活动。"},{"i":46,"n":"第四十六条","txt":"国际货运代理企业违反《规定》第十九条、第二十一条、以及本细则第二十三条第二款、第三十四条、第三十五条规定的，商务部授权地方商务主管部门予以警告并责令限期改正；未在限期内改正的，地方商务主管部门可以建议商务部撤销其批准证书。"},{"i":47,"n":"第四十七条","txt":"国际货运代理企业违反《规定》第十七条第二款、第二十条、第二十二条及本细则第十八条第三款、第二十三条第一款、第二十四条、第二十七条、第三十三条、第三十六条、第三十七条、第三十九条、第四十条、第四十一条、第四十二条、第四十三条、第四十四条、第四十五条规定的，地方商务主管部门经商务部授权，可视情节予以警告、责令停业整顿等处罚，情节严重者，可以建议商务部撤销其批准证书。 受到撤销经营批准证书处罚的企业应当到工商行政管理部门进行相应的变更或注销登记。该企业５年内不得再次提出经营国际货运代理业务的申请。 受到停业整顿处罚的企业恢复开展业务应当具备下列条件： (一)进行整顿； (二)主要责任人受到处理或处分； (三)符合行业主管部门要求的其他条件。 行业主管部门在收到企业恢复开展业务的申请及相关书面材料后应当进行审查，决定是否同意其恢复开展业务。"},{"i":48,"n":"第四十八条","txt":"对违反《规定》和本细则的规定擅自从事国际货运代理业务的单位，由行业主管部门取缔其非法经营活动，并由工商行政管理机关依照有关法律、行政法规的规定予以处罚，行业主管部门对此应予以公告。地方商务主管部门公告后应当报商务部备案。该单位５年之内不得独立或者参与申请经营国际货运代理业务。"},{"i":49,"n":"第四十九条","txt":"国际货运代理企业可根据自愿原则，依法成立国际货运代理协会(以下简称行业协会)。"},{"i":50,"n":"第五十条","txt":"行业协会是以服务会员为目的的非盈利性民间社团组织，在行业主管部门的监督和指导下根据协会章程开展活动。其宗旨是推动会员企业间加强横向联系、交流信息、增进相互间协作，鼓励和监督会员企业依法经营、规范竞争，依法代表本行业利益，维护会员的合法权益，协助政府有关部门加强行业管理，促进行业的健康有序发展。"},{"i":51,"n":"第五十一条","txt":"行业协会根据本细则第三十四条的规定制定国际货运代理标准交易条款，报商务部批准后，供本行业企业使用。"},{"i":52,"n":"第五十二条","txt":"外商投资国际货运代理企业适用《规定》及本细则，但外商投资企业有关法律、法规、规章另有规定的，从其规定。"},{"i":53,"n":"第五十三条","txt":"本细则由商务部负责解释。"},{"i":54,"n":"第五十四条","txt":"本细则自发布之日起施行。"}],"zhongguoqiyejingwaishangwutousufuwuzanxingbanfa":[{"i":1,"n":"第一条","txt":"为保障和促进中国企业公平、正当开展境外商务活动，维护中国企业的合法权益，根据《中华人民共和国对外贸易法》及有关法律、行政法规和规定，结合开展境外商务活动的实际情况，特制定本办法。"},{"i":2,"n":"第二条","txt":"商务部中国企业境外商务投诉服务中心（下称投诉服务中心）根据本办法规定，负责无偿提供中国企业境外商务投诉服务，其工作经费由政府资助。 投诉服务中心具有法人资格，对其行为依法独立承担责任。"},{"i":3,"n":"第三条","txt":"本办法所称中国企业境外商务投诉服务，是指符合本办法规定的服务请求人，反映情况，请求提供政策信息服务、法律咨询服务，或者认为其合法权益受到损害或不法侵害或可能将要受到损害或不法侵害，请求协调解决，由投诉服务中心进行协调处理、答复的服务。"},{"i":4,"n":"第四条","txt":"服务请求人应遵循诚实、自愿、合法的原则，按照本办法的规定，如实反映情况，并对投诉服务中心的相关工作提供积极协助。"},{"i":5,"n":"第五条","txt":"本办法所称服务请求人包括： （一）依据《中华人民共和国对外贸易法》有关规定，从事对外贸易经营活动的法人、其他组织或个人； （二）依法从事境外投资活动的中国投资者。"},{"i":6,"n":"第六条","txt":"中国企业境外商务投诉服务事项范围包括： （一）货物进出口； （二）技术进出口； （三）国际服务贸易； （四）与对外贸易有关的知识产权； （五）对外劳务合作； （六）对外承包工程； （七）境外投资； （八）境外其他商务活动。 中国企业境外商务投诉服务事项不包括外交领事管辖的事项。"},{"i":7,"n":"第七条","txt":"投诉服务中心的服务内容和主要职责包括： （一）为降低境内企业和个人在开展境外商务活动中合法权益受到损害和不法侵害的风险，提供力所能及的政策信息服务； （二）针对一般民商事法律纠纷的请求，提供咨询服务； （三）针对境外政府或组织不公平政策、措施或市场壁垒的投诉，受理后提请政府有关部门通过多双边机制等渠道进行交涉、磋商或诉诸相关争端解决机制，推动解决问题； （四）依照本办法对符合规定程序和条件的服务请求进行审核、登记、整理和初步分析处理； （五）依照本办法，将受理的服务请求事项提请有关方面核实、处理，并跟踪查询、协调催办； （六）在本办法规定的时限内将有关进程或结果反馈服务请求人； （七）分析整理服务请求情况，定期发布分析报告； （八）就重大敏感案件或普遍问题，向有关政府部门报告并提出建议； （九）为有关政府部门提供法律协助； （十）组建并管理特约专家和法律顾问库； （十一）受商务部委托，"},{"i":8,"n":"第八条","txt":"投诉服务中心应建立重大事件应急机制，并纳入商务部应急管理体系。 本办法中重大事件是指损害严重、涉及面广或受社会广泛关注的事件。"},{"i":9,"n":"第九条","txt":"投诉服务中心工作人员应熟悉对外经济贸易法律制度和国际经贸规则，恪尽职守，及时妥善协调处理服务事项。"},{"i":10,"n":"第十条","txt":"投诉服务中心及其工作人员应保守工作中知悉的服务请求人的商业秘密，法律、行政法规规定的特殊情形除外。"},{"i":11,"n":"第十一条","txt":"服务请求人可通过以下方式向投诉服务中心提出相关服务需求： （一）登陆12335.mofcom.gov.cn； （二）拨打投诉服务中心热线12335； （三）发送传真，号码12335； （四）邮寄信函； （五）来访面谈。"},{"i":12,"n":"第十二条","txt":"请求提供政策信息服务的，服务请求人应提供以下材料： （一）说明服务请求人基本信息的材料。 服务请求人为个人的，包括姓名、身份证件名称及号码、地址、邮政编码、联系电话以及证明服务请求人符合本办法第五条规定的相关文件等； 服务请求人为法人或其他组织的，包括名称、代码、住所地、邮政编码、法定代表人（或主要负责人）、联系电话以及证明服务请求人符合本办法第五条规定的相关文件等。 （二）明确请求提供的政策信息事项。 （三）投诉服务中心为提供政策信息服务需要的其他材料。"},{"i":13,"n":"第十三条","txt":"请求提供一般民商事法律纠纷咨询服务的，服务请求人应提供以下材料： （一）说明服务请求人基本信息的材料。 服务请求人为个人的，包括姓名、身份证件名称及号码、地址、邮政编码、联系电话以及证明服务请求人符合本办法第五条规定的相关文件等； 服务请求人为法人或其他组织的，包括名称、代码、住所地、邮政编码、法定代表人（或主要负责人）、联系电话以及证明服务请求人符合本办法第五条规定的相关文件等。 （二）简要案情，包括各当事方简要情况、国别（或地区）、案由、纠纷标的、案件进展情况等。 （三）相关证明材料。 （四）明确请求提供咨询的事项。 （五）投诉服务中心为提供咨询服务需要的其他材料。"},{"i":14,"n":"第十四条","txt":"投诉境外政府或组织的不公平的政策、措施或市场壁垒的，服务请求人应当提供以下材料： （一）说明服务请求人基本信息的材料。 服务请求人为个人的，包括姓名、身份证件名称及号码、地址、邮政编码、联系电话以及证明服务请求人符合本办法第五条规定的相关文件等； 服务请求人为法人或其他组织的，包括名称、代码、住所地、邮政编码、法定代表人（或主要负责人）、联系电话以及证明服务请求人符合本办法第五条规定的相关文件等。 （二）被投诉方基本信息，被投诉的境外政府部门或组织名称、地址、邮政编码、联系人、联系电话等。 （三）被投诉的政策、措施或市场壁垒及相关证明材料。 （四）被投诉的政策、措施或市场壁垒导致投诉人合法权益遭受损害或不法侵害的事实（事实发生的时间、地点、过程、程度等），或者导致投诉人合法权益将会受到损害或不法侵害的可能性分析。 （五）明确、具体的诉求。 （六）投诉服务中心为提供投诉服务需要的其他材料"},{"i":15,"n":"第十五条","txt":"服务请求人提交的材料应当使用中文书写。"},{"i":16,"n":"第十六条","txt":"投诉服务中心接到服务请求后，在10个工作日内进行审查，依据下列情况分别作出处理： （一）符合受理条件的，应予以受理并向服务请求人发出受理通知书； （二）不符合受理条件的，向服务请求人发出不予受理通知书，并说明不予受理的原因； （三）需要进一步补充完善材料的，通知服务请求人予以补充完善。"},{"i":17,"n":"第十七条","txt":"投诉服务中心可以不受理的请求包括： （一）不符合本办法第五条规定的服务请求人主体资格的； （二）不符合本办法第六条规定的投诉服务事项范围的； （三）没有明确的服务请求事项的； （四）不能提供第十三条第（二）项、第（三）项或第十四条第（三）项、第（四）项规定的材料的； （五）以匿名方式提出服务请求的； （六）已经或正在由投诉服务中心受理的； （七）没有提供新的材料，就投诉服务中心处理终结的事项再次提出请求的； （八）应当由外商投资企业投诉中心受理的； （九）应当由中国外派劳务人员投诉中心受理的； （十）已由境内法院或者仲裁机构受理或者作出裁决的； （十一）其他不符合有关法律、行政法规规定的。"},{"i":18,"n":"第十八条","txt":"对于请求提供政策信息服务的，投诉服务中心应在受理之日起10个工作日内予以答复。"},{"i":19,"n":"第十九条","txt":"对于请求提供一般民商事法律纠纷咨询服务的，投诉服务中心应在受理之日起20个工作日内提供咨询服务。"},{"i":20,"n":"第二十条","txt":"对涉及境外政府或组织不公平的政策、措施或市场壁垒的投诉，投诉服务中心应在受理之日起3个工作日内转商务部处理，并将投诉转送情况告服务请求人。"},{"i":21,"n":"第二十一条","txt":"投诉服务中心征得服务请求人同意后，可视情将投诉咨询内容转有关行业商会、协会等参考使用。"},{"i":22,"n":"第二十二条","txt":"有下列情况之一的，服务请求处理终结： （一）按照第十八条、第十九条、第二十条的规定处理完毕的； （二）经核实，服务请求事项与事实不符的； （三）服务请求人不予配合，并拒绝提供真实情况的； （四）服务请求人申请撤回请求的； （五）其他应当处理终结的情形。 投诉处理终结，投诉服务中心应及时进行结案登记。"},{"i":23,"n":"第二十三条","txt":"投诉服务中心应分析整理服务请求情况，每个季度以网站发布和印刷发表的形式发布分析报告。"},{"i":24,"n":"第二十四条","txt":"投诉服务中心应按规定格式进行登记，受理、转办投诉、通知、答复等事项也应尽量使用格式化文书，并加盖投诉服务中心公章或投诉专用章。"},{"i":25,"n":"第二十五条","txt":"投诉服务中心受理服务请求的相关材料应按期分类编号，装订归档，专人保管，录入投诉服务中心服务请求电子处理系统。未经相关领导批准，不得外借和查阅。存档期限一般为三年，对于重要的档案应适当延长存档期限。"},{"i":26,"n":"第二十六条","txt":"本办法由商务部负责解释。"},{"i":27,"n":"第二十七条","txt":"本办法自公布之日起施行。"}],"zhongyangchubeirouguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强中央储备肉（以下简称储备肉）管理，确保储备肉数量真实、质量合格和储存安全，做到储得进、管得好、调得动、用得上，有效发挥其作用，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称储备肉，是指国家用于应对重大自然灾害、公共卫生事件、动物疫情或者其他突发事件引发市场异常波动和市场调控而储备的肉类产品,包括储备活畜（含活猪、活牛、活羊,下同）和储备冻肉（含冻猪肉、冻牛肉、冻羊肉,下同）。"},{"i":3,"n":"第三条","txt":"储备肉实行常年储备、定期轮换制度。"},{"i":4,"n":"第四条","txt":"从事储备肉管理、监督、储存、加工等活动的单位和个人，适用本办法。"},{"i":5,"n":"第五条","txt":"商务部负责储备肉的行政管理，审定储备肉区域布局及代储企业、储存库、活畜储备基地场（统称承储单位）和加工企业的资质，对储备肉数量、质量和储存安全实施监督检查；负责储备肉财政补贴的预算编制和资金的申领。"},{"i":6,"n":"第六条","txt":"财政部负责储备肉财政财务管理，安排和管理储备肉财政补贴资金，会同财政部驻各地财政监察专员办事处（以下简称专员办）监督检查有关财务秩序和财政补贴资金使用情况等。"},{"i":7,"n":"第七条","txt":"中国农业发展银行负责按照国家有关信贷政策和储备肉计划安排储备肉贷款，对储备肉贷款实施信贷监管，确保资金安全。"},{"i":8,"n":"第八条","txt":"商务部委托的操作单位按照本办法的有关规定组织实施储备肉入储、加工、更新轮换及动用工作，负责储备肉日常管理和台账系统的建设、运行与维护，及时上报储备肉业务、财务报表和报告,并提出储备肉计划安排建议。"},{"i":9,"n":"第九条","txt":"商务部委托的质检单位按照国家有关规定和卫生质量安全标准组织实施储备肉公证检验和全程卫生质量安全监控工作，出具公证检验报告，并对检验结果负责，确保检验结果真实、准确。"},{"i":10,"n":"第十条","txt":"承储单位负责储备肉在库（栏）管理工作，接受有关部门和单位监督；严格执行储备肉计划等有关管理规定，及时报送储备信息业务、财务报表和报告；在规定的保管期限内确保储备肉数量真实、质量合格及储存安全，及时办理储备肉财政补贴申领等有关事项。"},{"i":11,"n":"第十一条","txt":"有关省、自治区、直辖市、计划单列市及新疆生产建设兵团商务主管部门应支持和配合储备肉管理工作，按有关要求择优推荐承储单位和加工企业，督促承储单位和加工企业及时落实储备肉计划。"},{"i":12,"n":"第十二条","txt":"代储企业应具备下列条　件：具有独立法人资格的肉类行业企业；具有符合国家有关标准和技术规范要求的全资储存冷库、活畜储备基地场（以下简称基地场），或持有储存冷库、基地场所在企业5%以上股份；地方代储企业与基地场（分公司除外）必须在同一省（自治区、直辖市）；具有组织、管理基地场的能力及稳定的销售网络，能够承担储备肉的安全责任；自身及基地场财务状况良好，具有较好的商业信誉、较强的抗风险能力和健全的财务管理制度，资产负债率低于70%。 储存冷库应符合中央储备冻肉储存冷库有关资质标准。牛羊肉储存冷库应是经国家有关部门批准确认的清真库。冷库储存能力在3000吨以上。 基地场应符合中央储备肉活畜储备基地场有关资质标准。"},{"i":13,"n":"第十三条","txt":"储备冻肉加工企业应具备下列条　件：冻猪肉加工企业应依法取得生猪定点屠宰加工企业资格，具备《生猪屠宰加工企业资质等级要求》（SB/T10396-2005）规定的四星级以上（含四星级）的资质条件，产品质量应符合《分割鲜、冻猪瘦肉》(GB99592-2001)要求；冻牛、羊肉加工企业应符合《畜类屠宰加工通用技术条　件》（GB/T17237-1998）及《牛羊屠宰产品品质检验规程》（GB18393-2001）的要求，冻牛肉产品质量符合《鲜、冻分割牛肉》（GB/T17238-1998）,冻羊肉产品质量符合《鲜、冻胴体羊肉》（GB9961-2001）。"},{"i":14,"n":"第十四条","txt":"商务部根据布局合理、成本和费用节省、便于集中管理和监督的原则，选择储备肉承储单位和加工企业。"},{"i":15,"n":"第十五条","txt":"根据储备肉储存规模、品种结构和市场调控工作需要，商务部会同财政部和中国农业发展银行向操作单位、有关省、自治区、直辖市、计划单列市及新疆生产建设兵团商务主管部门下达储备肉入储计划，并抄送财政部驻有关省（自治区、直辖市、计划单列市）专员办、质检单位和承储单位。"},{"i":16,"n":"第十六条","txt":"储备冻肉加工和入库原则上实行招标采购办法和送货到库制，采购上限价由商务部、财政部确定，操作单位负责组织实施。"},{"i":17,"n":"第十七条","txt":"储备活畜每吨分别按活猪20头、活牛6头、活羊60只折算。储备存栏活畜体重，活猪在60公斤以上，活牛在400公斤以上、活羊在20公斤以上。"},{"i":18,"n":"第十八条","txt":"承储单位根据储备肉入储计划向操作单位提供银行出具的担保证明，或以资产抵押，或缴纳保证金。储备冻肉资产抵押或保证金标准为入库成本的1%，储备活猪、活牛、活羊资产抵押或保证金标准，每头分别为40元、130元、13元和10元、30元、3元。"},{"i":19,"n":"第十九条","txt":"操作单位根据储备肉入储计划与承储单位签订合同，明确双方的权利、义务和责任等事项。自合同签订之日起15个工作日内办妥资产抵押、担保手续或足额交付保证金，并按计划入储。"},{"i":20,"n":"第二十条","txt":"操作单位和承储单位应按时落实储备肉入储计划。储备冻肉入库数与入储计划的差异不得超过1%。未经商务部、财政部同意，不得调整更改计划或拒绝、拖延执行。操作单位应及时将储备肉入储计划执行情况报商务部、财政部，并抄送中国农业发展银行。"},{"i":21,"n":"第二十一条","txt":"因承储单位没能按照规定完成储备计划需进行规模内调整计划的，由商务部会同财政部调减或取消其储备计划；因突发事件等特殊情况需超规模紧急收购储备肉的，由商务部会同财政部视情况按有关规定执行。"},{"i":22,"n":"第二十二条","txt":"储备肉实行专仓（专垛）或专栏储存、专人管理、专账记载和挂牌明示，确保账账相符、账实相符、质量良好和储存安全。"},{"i":23,"n":"第二十三条","txt":"承储单位不得擅自动用储备肉，不得虚报储备肉数量，不得自行变更储备冻肉堆码库、垛位和活畜饲养专栏。"},{"i":24,"n":"第二十四条","txt":"在库（栏）储备肉由北京市专员办监督操作单位通过招标方式统一办理财产保险。"},{"i":25,"n":"第二十五条","txt":"任何单位、企业和个人不得以储备肉对外进行质押、担保或者清偿债务。承储单位进入撤销、解散或者破产程序时，应立即书面告知操作单位，操作单位应及时报告商务部。"},{"i":26,"n":"第二十六条","txt":"操作单位和承储单位依照本办法及国家有关规定，建立健全内部各项管理制度，严格在库（栏）管理。承储单位应加强储备肉日常管理，发现问题，及时报告操作单位，操作单位应提出处理意见并及时报告商务部、财政部。"},{"i":27,"n":"第二十七条","txt":"承储单位应在规定的时间内完成储备肉轮换。冻猪肉原则上每年储备3轮，每轮储存4个月左右。冻牛、羊肉原则上不轮换，每轮储存8个月左右。活畜原则上每年储备3轮，每轮储存4个月左右。"},{"i":28,"n":"第二十八条","txt":"储备冻猪肉由操作单位按计划组织承储单位及时轮换。储备活畜应根据育肥情况适时轮换。"},{"i":29,"n":"第二十九条","txt":"储备肉轮出后，承储单位应按计划及时、同品种、保质、等量轮入。特殊情况不能按时轮入的，须报商务部、财政部批准同意，否则按擅自动用储备肉处理。"},{"i":30,"n":"第三十条","txt":"操作单位应对承储单位的轮换情况进行督促和检查，并将有关情况报商务部、财政部，抄送中国农业发展银行、所在地专员办。"},{"i":31,"n":"第三十一条","txt":"操作单位根据储备肉出库（栏）计划，组织承储单位按时出库（栏）。"},{"i":32,"n":"第三十二条","txt":"储备冻肉出库采取公开竞卖、就地销售或者商务部和财政部批准的其他方式进行。公开竞卖底价由商务部商财政部确定，操作单位组织实施，实行到库提货制；就地销售按结算价格对承储单位包干，由其自行销售。结算价格原则上由当地专员办参照当地市场批发价格和品质差价核定。"},{"i":33,"n":"第三十三条","txt":"储备活畜出栏由承储单位根据计划自行组织。"},{"i":34,"n":"第三十四条","txt":"出现下列情况之一时，商务部提出动用储备肉计划，商财政部后及时下达动用品种、数量、价格和使用安排： （一）发生重大自然灾害、事故灾难、突发公共卫生事件和突发社会安全事件等其他突发事件； （二）全国或者部分地区肉类市场出现异常波动； （三）其他需要动用的情形。"},{"i":35,"n":"第三十五条","txt":"动用储备活畜的结算价格，原则上按基地场所在省级行政区域平均饲养成本确定。动用储备冻肉的结算价格，参照入库成本、品质差价随行就市，并经当地专员办核定。"},{"i":36,"n":"第三十六条","txt":"操作单位应及时落实储备肉动用计划，并将执行情况上报商务部、财政部，并抄送中国农业发展银行和所在地专员办。任何单位、企业和个人不得拒绝执行或者擅自改变储备肉动用计划。"},{"i":37,"n":"第三十七条","txt":"储备肉应符合国家有关卫生质量安全标准。储备冻肉应在入库前30天内生产。"},{"i":38,"n":"第三十八条","txt":"质检单位应在收到商务部委托检验通知后，依据国家储备肉质量公检有关规定在储备活畜出栏前完成公证检验；依据国家储备冻肉质量公检有关规定在储备冻肉入库时进行公证检验。"},{"i":39,"n":"第三十九条","txt":"质检单位应向承储单位出具检验报告书；同时，将储备肉公证检验结果报告商务部，抄送财政部。商务部应对储备肉质量情况进行抽查。"},{"i":40,"n":"第四十条","txt":"承储单位如对公证检验结果有异议，应在7个工作日内向商务部反映，商务部按有关规定进行处理。"},{"i":41,"n":"第四十一条","txt":"商务部建立储备肉监测系统，对承储单位的基本情况、储备肉动态管理信息和活畜及其产品、饲养原料市场信息进行管理监控。操作单位、承储单位应建立计算机储备肉台账，按有关规定通过台账系统及时向商务部、财政部、操作单位和所在地专员办报送有关信息。"},{"i":42,"n":"第四十二条","txt":"建立储备肉月份统计报表制度。操作单位应在每月后的5个工作日内编制《中央储备肉进销存月份统计报表》，及时报送商务部、财政部、中国农业发展银行，并抄送所在地专员办。"},{"i":43,"n":"第四十三条","txt":"商务部、财政部按照各自职责，对储备肉管理进行监督检查。"},{"i":44,"n":"第四十四条","txt":"中国农业发展银行应按照信贷政策有关规定，加强对储备肉贷款的信贷监管，并将监管情况通报商务部、财政部，抄送操作单位。"},{"i":45,"n":"第四十五条","txt":"专员办对承储单位执行储备肉收储、轮换、动用、管理等情况进行检查，并将检查情况上报财政部，抄报商务部、中国农业发展银行。"},{"i":46,"n":"第四十六条","txt":"操作单位应对承储单位执行储备肉计划等情况进行检查，发现问题及时解决，重大问题应报请商务部、财政部处理。"},{"i":47,"n":"第四十七条","txt":"承储单位对商务部、财政部及专员办、中国农业发展银行和操作单位的监督检查，应予以配合，不得拒绝、阻挠。"},{"i":48,"n":"第四十八条","txt":"国家机关工作人员或企业工作人员违反本办法的规定，应依照《中华人民共和国公务员法》、《财政违法行为处罚处分条例》、《行政机关公务员处分条例》和《企业职工奖惩条例》等有关规定给予处理、处分。"},{"i":49,"n":"第四十九条","txt":"操作单位和质检单位违反本办法的规定，由商务部商财政部给予警告，并责令其限期整改；情节严重的，扣拨其管理费和公证检验费补贴，直至取消其业务操作和公证检验单位资格。"},{"i":50,"n":"第五十条","txt":"加工企业和承储单位违反本办法的规定，由有关部门责成其限期改正，并按规定予以处理。其违法违纪所得由财政部或专员办按有关规定收缴。"},{"i":51,"n":"第五十一条","txt":"本办法由商务部、财政部负责解释。"},{"i":52,"n":"第五十二条","txt":"本办法自2007年9月15日起施行。"}],"ershoucheliutongguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加强二手车流通管理，规范二手车经营行为，保障二手车交易双方的合法权益，促进二手车流通健康发展，依据国家有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事二手车经营活动或者与二手车相关的活动，适用本办法。 本办法所称二手车，是指从办理完注册登记手续到达到国家强制报废标准之前进行交易并转移所有权的汽车（包括三轮汽车、低速载货汽车，即原农用运输车,下同）、挂车和摩托车。"},{"i":3,"n":"第三条","txt":"二手车交易市场是指依法设立、为买卖双方提供二手车集中交易和相关服务的场所。"},{"i":4,"n":"第四条","txt":"二手车经营主体是指经工商行政管理部门依法登记,从事二手车经销、拍卖、经纪、鉴定评估的企业。"},{"i":5,"n":"第五条","txt":"二手车经营行为是指二手车经销、拍卖、经纪、鉴定评估等。 （一）二手车经销是指二手车经销企业收购、销售二手车的经营活动； （二）二手车拍卖是指二手车拍卖企业以公开竞价的形式将二手车转让给最高应价者的经营活动； （三）二手车经纪是指二手车经纪机构以收取佣金为目的,为促成他人交易二手车而从事居间、行纪或者代理等经营活动； （四）二手车鉴定评估是指二手车鉴定评估机构对二手车技术状况及其价值进行鉴定评估的经营活动。"},{"i":6,"n":"第六条","txt":"二手车直接交易是指二手车所有人不通过经销企业、拍卖企业和经纪机构将车辆直接出售给买方的交易行为。二手车直接交易应当在二手车交易市场进行。"},{"i":7,"n":"第七条","txt":"国务院商务主管部门、工商行政管理部门、税务部门在各自的职责范围内负责二手车流通有关监督管理工作。 省、自治区、直辖市和计划单列市商务主管部门（以下简称省级商务主管部门）、工商行政管理部门、税务部门在各自的职责范围内负责辖区内二手车流通有关监督管理工作。"},{"i":8,"n":"第八条","txt":"二手车交易市场经营者、二手车经销企业和经纪机构应当具备企业法人条件,并依法到工商行政管理部门办理登记。"},{"i":9,"n":"第九条","txt":"设立二手车拍卖企业（含外商投资二手车拍卖企业）应当符合《中华人民共和国拍卖法》和《拍卖管理办法》有关规定,并按《拍卖管理办法》规定的程序办理。"},{"i":10,"n":"第十条","txt":"外资并购二手车交易市场和经营主体及已设立的外商投资企业增加二手车经营范围的，应当按第九条规定的程序办理。"},{"i":11,"n":"第十一条","txt":"二手车交易市场经营者和二手车经营主体应当依法经营和纳税，遵守商业道德，接受依法实施的监督检查。"},{"i":12,"n":"第十二条","txt":"二手车卖方应当拥有车辆的所有权或者处置权。二手车交易市场经营者和二手车经营主体应当确认卖方的身份证明，车辆的号牌、《机动车登记证书》、《机动车行驶证》，有效的机动车安全技术检验合格标志、车辆保险单、交纳税费凭证等。 国家机关、国有企事业单位在出售、委托拍卖车辆时，应持有本单位或者上级单位出具的资产处理证明。"},{"i":13,"n":"第十三条","txt":"出售、拍卖无所有权或者处置权车辆的，应承担相应的法律责任。"},{"i":14,"n":"第十四条","txt":"二手车卖方应当向买方提供车辆的使用、修理、事故、检验以及是否办理抵押登记、交纳税费、报废期等真实情况和信息。买方购买的车辆如因卖方隐瞒和欺诈不能办理转移登记，卖方应当无条件接受退车，并退还购车款等费用。"},{"i":15,"n":"第十五条","txt":"二手车经销企业销售二手车时应当向买方提供质量保证及售后服务承诺，并在经营场所予以明示。"},{"i":16,"n":"第十六条","txt":"进行二手车交易应当签订合同。合同示范文本由国务院工商行政管理部门制定。"},{"i":17,"n":"第十七条","txt":"二手车所有人委托他人办理车辆出售的，应当与受托人签订委托书。"},{"i":18,"n":"第十八条","txt":"委托二手车经纪机构购买二手车时，双方应当按以下要求进行： （一）委托人向二手车经纪机构提供合法身份证明； （二）二手车经纪机构依据委托人要求选择车辆，并及时向其通报市场信息； （三）二手车经纪机构接受委托购买时，双方签订合同； （四）二手车经纪机构根据委托人要求代为办理车辆鉴定评估,鉴定评估所发生的费用由委托人承担。"},{"i":19,"n":"第十九条","txt":"二手车交易完成后，卖方应当及时向买方交付车辆、号牌及车辆法定证明、凭证。车辆法定证明、凭证主要包括： （一）《机动车登记证书》； （二）《机动车行驶证》； （三）有效的机动车安全技术检验合格标志； （四）车辆购置税完税证明； （五）养路费缴付凭证； （六）车船使用税缴付凭证； （七）车辆保险单。"},{"i":20,"n":"第二十条","txt":"下列车辆禁止经销、买卖、拍卖和经纪： （一）已报废或者达到国家强制报废标准的车辆； （二）在抵押期间或者未经海关批准交易的海关监管车辆； （三）在人民法院、人民检察院、行政执法部门依法查封、扣押期间的车辆； （四）通过盗窃、抢劫、诈骗等违法犯罪手段获得的车辆； （五）发动机号码、车辆识别代号或者车架号码与登记号码不相符，或者有凿改迹象的车辆； （六）走私、非法拼（组）装的车辆； （七）不具有第十九条所列证明、凭证的车辆； （八）在本行政辖区以外的公安机关交通管理部门注册登记的车辆； （九）国家法律、行政法规禁止经营的车辆。 二手车交易市场经营者和二手车经营主体发现车辆具有（四）、（五）、（六）情形之一的，应当及时报告公安机关、工商行政管理部门等执法机关。 对交易违法车辆的，二手车交易市场经营者和二手车经营主体应当承担连带赔偿责任和其他相应的法律责任。"},{"i":21,"n":"第二十一条","txt":"二手车经销企业销售、拍卖企业拍卖二手车时，应当按规定向买方开具税务机关监制的统一发票。 进行二手车直接交易和通过二手车经纪机构进行二手车交易的，应当由二手车交易市场经营者按规定向买方开具税务机关监制的统一发票。"},{"i":22,"n":"第二十二条","txt":"二手车交易完成后,现车辆所有人应当凭税务机关监制的统一发票,按法律、法规有关规定办理转移登记手续。"},{"i":23,"n":"第二十三条","txt":"二手车交易市场经营者应当为二手车经营主体提供固定场所和设施,并为客户提供办理二手车鉴定评估、转移登记、保险、纳税等手续的条件。二手车经销企业、经纪机构应当根据客户要求,代办二手车鉴定评估、转移登记、保险、纳税等手续。"},{"i":24,"n":"第二十四条","txt":"二手车鉴定评估应当本着买卖双方自愿的原则，不得强制进行；属国有资产的二手车应当按国家有关规定进行鉴定评估。"},{"i":25,"n":"第二十五条","txt":"二手车鉴定评估机构应当遵循客观、真实、公正和公开原则，依据国家法律法规开展二手车鉴定评估业务，出具车辆鉴定评估报告；并对鉴定评估报告中车辆技术状况，包括是否属事故车辆等评估内容负法律责任。"},{"i":26,"n":"第二十六条","txt":"二手车鉴定评估机构和人员可以按国家有关规定从事涉案、事故车辆鉴定等评估业务。"},{"i":27,"n":"第二十七条","txt":"二手车交易市场经营者和二手车经营主体应当建立完整的二手车交易购销、买卖、拍卖、经纪以及鉴定评估档案。"},{"i":28,"n":"第二十八条","txt":"设立二手车交易市场、二手车经销企业开设店铺,应当符合所在地城市发展及城市商业发展有关规定。"},{"i":29,"n":"第二十九条","txt":"二手车流通监督管理遵循破除垄断，鼓励竞争，促进发展和公平、公正、公开的原则。"},{"i":30,"n":"第三十条","txt":"建立二手车交易市场经营者和二手车经营主体备案制度。凡经工商行政管理部门依法登记,取得营业执照的二手车交易市场经营者和二手车经营主体，应当自取得营业执照之日起2个月内向省级商务主管部门备案。省级商务主管部门应当将二手车交易市场经营者和二手车经营主体有关备案情况定期报送国务院商务主管部门。"},{"i":31,"n":"第三十一条","txt":"建立和完善二手车流通信息报送、公布制度。二手车交易市场经营者和二手车经营主体应当定期将二手车交易量、交易额等信息通过所在地商务主管部门报送省级商务主管部门。省级商务主管部门将上述信息汇总后报送国务院商务主管部门。国务院商务主管部门定期向社会公布全国二手车流通信息。"},{"i":32,"n":"第三十二条","txt":"商务主管部门、工商行政管理部门应当在各自的职责范围内采取有效措施,加强对二手车交易市场经营者和经营主体的监督管理,依法查处违法违规行为,维护市场秩序,保护消费者的合法权益。"},{"i":33,"n":"第三十三条","txt":"国务院工商行政管理部门会同商务主管部门建立二手车交易市场经营者和二手车经营主体信用档案，定期公布违规企业名单。"},{"i":34,"n":"第三十四条","txt":"本办法自2005年10月1日起施行，原《商务部办公厅关于规范旧机动车鉴定评估管理工作的通知》（商建字[2004]第70号）、《关于加强旧机动车市场管理工作的通知》（国经贸贸易[2001]1281号）、《旧机动车交易管理办法》（内贸机字[1998]第33号）及据此发布的各类文件同时废止。"}],"ershoucheliutongguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强二手车流通管理，规范二手车经营行为，保障二手车交易双方的合法权益，促进二手车流通健康发展，依据国家有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事二手车经营活动或者与二手车相关的活动，适用本办法。 本办法所称二手车，是指从办理完注册登记手续到达到国家强制报废标准之前进行交易并转移所有权的汽车（包括三轮汽车、低速载货汽车，即原农用运输车，下同）、挂车和摩托车。"},{"i":3,"n":"第三条","txt":"二手车交易市场是指依法设立、为买卖双方提供二手车集中交易和相关服务的场所。"},{"i":4,"n":"第四条","txt":"二手车经营主体是指经工商行政管理部门依法登记，从事二手车经销、拍卖、经纪、鉴定评估的企业。"},{"i":5,"n":"第五条","txt":"二手车经营行为是指二手车经销、拍卖、经纪、鉴定评估等。 （一）二手车经销是指二手车经销企业收购、销售二手车的经营活动； （二）二手车拍卖是指二手车拍卖企业以公开竞价的形式将二手车转让给最高应价者的经营活动； （三）二手车经纪是指二手车经纪机构以收取佣金为目的，为促成他人交易二手车而从事居间、行纪或者代理等经营活动； （四）二手车鉴定评估是指二手车鉴定评估机构对二手车技术状况及其价值进行鉴定评估的经营活动。"},{"i":6,"n":"第六条","txt":"二手车直接交易是指二手车所有人不通过经销企业、拍卖企业和经纪机构将车辆直接出售给买方的交易行为。二手车直接交易应当在二手车交易市场进行。"},{"i":7,"n":"第七条","txt":"国务院商务主管部门、工商行政管理部门、税务部门在各自的职责范围内负责二手车流通有关监督管理工作。 省、自治区、直辖市和计划单列市商务主管部门（以下简称省级商务主管部门）、工商行政管理部门、税务部门在各自的职责范围内负责辖区内二手车流通有关监督管理工作。"},{"i":8,"n":"第八条","txt":"二手车交易市场经营者、二手车经销企业和经纪机构应当具备企业法人条件，并依法到工商行政管理部门办理登记。"},{"i":9,"n":"第九条","txt":"设立二手车拍卖企业（含外商投资二手车拍卖企业）应当符合《中华人民共和国拍卖法》和《拍卖管理办法》有关规定，并按《拍卖管理办法》规定的程序办理。"},{"i":10,"n":"第十条","txt":"外资并购二手车交易市场和经营主体及已设立的外商投资企业增加二手车经营范围的，应当按第十一条、第十二条规定的程序办理。"},{"i":11,"n":"第十一条","txt":"二手车交易市场经营者和二手车经营主体应当依法经营和纳税，遵守商业道德，接受依法实施的监督检查。"},{"i":12,"n":"第十二条","txt":"二手车卖方应当拥有车辆的所有权或者处置权。二手车交易市场经营者和二手车经营主体应当确认卖方的身份证明，车辆的号牌、《机动车登记证书》、《机动车行驶证》，有效的机动车安全技术检验合格标志、车辆保险单、交纳税费凭证等。 国家机关、国有企事业单位在出售、委托拍卖车辆时，应持有本单位或者上级单位出具的资产处理证明。"},{"i":13,"n":"第十三条","txt":"出售、拍卖无所有权或者处置权车辆的，应承担相应的法律责任。"},{"i":14,"n":"第十四条","txt":"二手车卖方应当向买方提供车辆的使用、修理、事故、检验以及是否办理抵押登记、交纳税费、报废期等真实情况和信息。买方购买的车辆如因卖方隐瞒和欺诈不能办理转移登记，卖方应当无条件接受退车，并退还购车款等费用。"},{"i":15,"n":"第十五条","txt":"二手车经销企业销售二手车时应当向买方提供质量保证及售后服务承诺，并在经营场所予以明示。"},{"i":16,"n":"第十六条","txt":"进行二手车交易应当签订合同。合同示范文本由国务院工商行政管理部门制定。"},{"i":17,"n":"第十七条","txt":"二手车所有人委托他人办理车辆出售的，应当与受托人签订委托书。"},{"i":18,"n":"第十八条","txt":"委托二手车经纪机构购买二手车时，双方应当按以下要求进行： （一）委托人向二手车经纪机构提供合法身份证明； （二）二手车经纪机构依据委托人要求选择车辆，并及时向其通报市场信息； （三）二手车经纪机构接受委托购买时，双方签订合同； （四）二手车经纪机构根据委托人要求代为办理车辆鉴定评估，鉴定评估所发生的费用由委托人承担。"},{"i":19,"n":"第十九条","txt":"二手车交易完成后，卖方应当及时向买方交付车辆、号牌及车辆法定证明、凭证。车辆法定证明、凭证主要包括： （一）《机动车登记证书》； （二）《机动车行驶证》； （三）有效的机动车安全技术检验合格标志； （四）车辆购置税完税证明； （五）养路费缴付凭证； （六）车船使用税缴付凭证； （七）车辆保险单。"},{"i":20,"n":"第二十条","txt":"下列车辆禁止经销、买卖、拍卖和经纪： （一）已报废或者达到国家强制报废标准的车辆； （二）在抵押期间或者未经海关批准交易的海关监管车辆； （三）在人民法院、人民检察院、行政执法部门依法查封、扣押期间的车辆； （四）通过盗窃、抢劫、诈骗等违法犯罪手段获得的车辆； （五）发动机号码、车辆识别代号或者车架号码与登记号码不相符，或者有凿改迹象的车辆； （六）走私、非法拼（组）装的车辆； （七）不具有第二十二条所列证明、凭证的车辆； （八）在本行政辖区以外的公安机关交通管理部门注册登记的车辆； （九）国家法律、行政法规禁止经营的车辆。 二手车交易市场经营者和二手车经营主体发现车辆具有（四）、（五）、（六）情形之一的，应当及时报告公安机关、工商行政管理部门等执法机关。 对交易违法车辆的，二手车交易市场经营者和二手车经营主体应当承担连带赔偿责任和其他相应的法律责任。"},{"i":21,"n":"第二十一条","txt":"二手车经销企业销售、拍卖企业拍卖二手车时，应当按规定向买方开具税务机关监制的统一发票。 进行二手车直接交易和通过二手车经纪机构进行二手车交易的，应当由二手车交易市场经营者按规定向买方开具税务机关监制的统一发票。"},{"i":22,"n":"第二十二条","txt":"二手车交易完成后，现车辆所有人应当凭税务机关监制的统一发票，按法律、法规有关规定办理转移登记手续。"},{"i":23,"n":"第二十三条","txt":"二手车交易市场经营者应当为二手车经营主体提供固定场所和设施，并为客户提供办理二手车鉴定评估、转移登记、保险、纳税等手续的条件。二手车经销企业、经纪机构应当根据客户要求，代办二手车鉴定评估、转移登记、保险、纳税等手续。"},{"i":24,"n":"第二十四条","txt":"二手车鉴定评估应当本着买卖双方自愿的原则，不得强制进行；属国有资产的二手车应当按国家有关规定进行鉴定评估。"},{"i":25,"n":"第二十五条","txt":"二手车鉴定评估机构应当遵循客观、真实、公正和公开原则，依据国家法律法规开展二手车鉴定评估业务，出具车辆鉴定评估报告；并对鉴定评估报告中车辆技术状况，包括是否属事故车辆等评估内容负法律责任。"},{"i":26,"n":"第二十六条","txt":"二手车鉴定评估机构和人员可以按国家有关规定从事涉案、事故车辆鉴定等评估业务。"},{"i":27,"n":"第二十七条","txt":"二手车交易市场经营者和二手车经营主体应当建立完整的二手车交易购销、买卖、拍卖、经纪以及鉴定评估档案。"},{"i":28,"n":"第二十八条","txt":"设立二手车交易市场、二手车经销企业开设店铺，应当符合所在地城市发展及城市商业发展有关规定。"},{"i":29,"n":"第二十九条","txt":"二手车流通监督管理遵循破除垄断，鼓励竞争，促进发展和公平、公正、公开的原则。"},{"i":30,"n":"第三十条","txt":"建立二手车交易市场经营者和二手车经营主体备案制度。凡经工商行政管理部门依法登记，取得营业执照的二手车交易市场经营者和二手车经营主体，应当自取得营业执照之日起2个月内向省级商务主管部门备案。省级商务主管部门应当将二手车交易市场经营者和二手车经营主体有关备案情况定期报送国务院商务主管部门。"},{"i":31,"n":"第三十一条","txt":"建立和完善二手车流通信息报送、公布制度。二手车交易市场经营者和二手车经营主体应当定期将二手车交易量、交易额等信息通过所在地商务主管部门报送省级商务主管部门。省级商务主管部门将上述信息汇总后报送国务院商务主管部门。国务院商务主管部门定期向社会公布全国二手车流通信息。"},{"i":32,"n":"第三十二条","txt":"商务主管部门、工商行政管理部门应当在各自的职责范围内采取有效措施，加强对二手车交易市场经营者和经营主体的监督管理，依法查处违法违规行为，维护市场秩序，保护消费者的合法权益。"},{"i":33,"n":"第三十三条","txt":"国务院工商行政管理部门会同商务主管部门建立二手车交易市场经营者和二手车经营主体信用档案，定期公布违规企业名单。"},{"i":34,"n":"第三十四条","txt":"本办法自2005年10月1日起施行，原《商务部办公厅关于规范旧机动车鉴定评估管理工作的通知》（商建字[2004]第70号）、《关于加强旧机动车市场管理工作的通知》（国经贸贸易[2001]1281号）、《旧机动车交易管理办法》（内贸机字[1998]第33号）及据此发布的各类文件同时废止。"}],"chanyesunhaidiaochaxinxichayueyuxinxipiluguiding":[{"i":1,"n":"第一条","txt":"为保证产业损害调查工作公开、公平和公正，保障利害关系方的合法权益，根据《中华人民共和国反倾销条例》和《中华人民共和国反补贴条例》的规定，制订本规定。"},{"i":2,"n":"第二条","txt":"反倾销和反补贴中有关产业损害调查的信息查阅和披露活动应当遵守本规定。"},{"i":3,"n":"第三条","txt":"中华人民共和国商务部负责实施本规定。"},{"i":4,"n":"第四条","txt":"本规定所称的利害关系方包括以下范围： （一）被调查产品的外国（地区）生产者、出口经营者、国内进口经营者，或者该产品生产者、出口经营者、进口经营者的行业组织或者其他组织； （二）被调查产品的出口国（地区）的政府； （三）国内同类产品的生产者，或者该产品生产者的行业组织或者其他组织； （四）其他。"},{"i":5,"n":"第五条","txt":"本规定所称信息查阅，是指案件的所有利害关系方可以到商务部贸易救济措施公开信息查阅室（以下简称公开信息查阅室）查找、阅览、摘抄、复印与案件产业损害调查有关的公开信息。"},{"i":6,"n":"第六条","txt":"本规定所称信息披露，是指在案件最终裁定作出前的合理时间内，商务部向利害关系方告知案件产业损害裁定所依据的基本事实。"},{"i":7,"n":"第七条","txt":"所有利害关系方可以查阅与案件产业损害调查有关的公开信息，但本规定第九条规定的信息除外。"},{"i":8,"n":"第八条","txt":"本规定第七条所称的公开信息包括： （一）申请书及其附件的公开文本或非保密概要； （二）利害关系方登记参加产业损害调查活动的申请材料的公开文本或非保密概要； （三）利害关系方提供的产业损害调查问卷及补充问卷答卷的公开文本或非保密概要； （四）利害关系方在产业损害调查过程中向商务部提交的其他申请材料的公开文本或非保密概要，包括召开产业损害调查听证会、延期递交答卷、产品范围调整、国内生产者排除等申请材料；其他利害关系方对相关申请提出的意见或评论的公开文本或非保密概要； （五）相关利害关系方对其他利害关系方有关保密信息申请及其提供的保密信息的公开文本或非保密概要所提出的评论意见的公开文本或非保密概要； （六）产业损害调查听证会等的会议记录或纪要的公开文本或非保密概要； （七）商务部发布的公告、通知，包括立案、初裁和终裁等公告；参加产业损害调查活动申请登记、发放调查问卷、实地核查、举行听证会、采"},{"i":9,"n":"第九条","txt":"任何信息如不能在公开渠道获得，且一旦被公布，将会导致其他竞争者实质性的获利，或对信息提供者或信息来源者造成实质性的不利影响，或造成其他不利影响，该信息应被视为是保密信息。 任何本质上具有保密性质的信息或者利害关系方要求作为保密信息的信息，在利害关系方说明正当理由后，商务部应对此类信息按保密信息处理。"},{"i":10,"n":"第十条","txt":"利害关系方向商务部提供相关信息时，应注明为公开信息还是保密信息。未注明保密与否的，商务部可以将该信息视为公开信息。"},{"i":11,"n":"第十一条","txt":"利害关系方在提供保密信息时应书面说明申请保密的理由并同时提供此类信息的公开文本或非保密概要。利害关系方要求对已提供材料中的部分内容进行修改或补充的，也应同时提供有关修改或补充内容的公开文本或非保密概要，并附修改说明。 公开文本或非保密概要应当合理表达保密信息的实质内容。特殊情况下，利害关系方在得到商务部批准后，可以不提供公开文本或非保密概要，但应书面说明无法提供公开文本或非保密概要的充分理由。"},{"i":12,"n":"第十二条","txt":"利害关系方不提供保密信息的公开文本或非保密概要，或者提供的公开文本或非保密概要不足以合理表达保密信息的实质内容，或者利害关系方无法提供公开文本或非保密概要的申请理由不充分的，商务部可以要求其撤回申请。利害关系方不撤回申请的，商务部可以对该信息不予考虑，除非商务部能自其他适当来源充分证实该信息是正确的。"},{"i":13,"n":"第十三条","txt":"商务部认为利害关系方申请保密的理由不符合本规定要求的，应自收到有关公开文本或非保密概要之日起7日内向利害关系方说明理由并给予其合理的时间对此进行评论。如商务部决定对利害关系方提供的信息不予考虑的，应及时以书面的方式通知该利害关系方，商务部自其他适当的来源充分证实该信息为正确的除外。"},{"i":14,"n":"第十四条","txt":"商务部应在收到利害关系方提供本规定第八条所列的相关材料后7个工作日内，将此类材料的公开文本或非保密概要提交公开信息查阅室1份供查阅。 商务部制作或获得的本规定第八条所列的其他相关信息的公开文本或非保密概要，如无特殊情形，一般应当在文件形成后10日内送交公开信息查阅室。"},{"i":15,"n":"第十五条","txt":"在产业损害调查过程中，案件的所有利害关系方可以在工作时间内到公开信息查阅室查阅与案件产业损害调查有关的所有公开信息。 最终裁定公布后的6个月内，案件的利害关系方也可以查阅相关公开信息。"},{"i":16,"n":"第十六条","txt":"利害关系方在查阅公开信息时，应当出具能够证明其身份的文件，并进行登记。"},{"i":17,"n":"第十七条","txt":"利害关系方可以查找、阅览、摘抄、复印公开信息，但不得将公开信息原件带离公开信息查阅室。"},{"i":18,"n":"第十八条","txt":"在遵守保护保密信息要求的前提下，在案件最终裁定作出前的合理时间内，商务部应告知已参加产业损害调查活动登记的利害关系方和国内申请人有关产业损害最终裁定所依据的基本事实，并告知其他未登记的利害关系方可以到公开信息查阅室查阅有关披露材料。"},{"i":19,"n":"第十九条","txt":"本规定第十八条所称基本事实的内容通常包括： （一）产业损害调查期及产业损害调查程序； （二）国内同类产品认定所依据的因素或数据； （三）国内产业认定所依据的因素或数据； （四）累积评估认定所依据的因素或数据； （五）倾销或补贴产品的进口数量（绝对数量及或相对数量）和进口价格的数据； （六）评估国内产业是否受到损害的有关经济因素或数据； （七）有关被调查的国家（地区）存在进一步对国内产业影响的因素或数据； （八）利害关系方提供的相关信息的采信情况，包括可获得最佳信息的使用及其理由等； （九）其他对裁决产生实质影响的信息。"},{"i":20,"n":"第二十条","txt":"商务部通常应在作出最终裁定30日之前进行信息披露。特殊情况下，如在上述时间内不适合作出部分事实披露的，商务部应于其后的最终裁定作出前的合理时间内作出披露。"},{"i":21,"n":"第二十一条","txt":"信息披露应采用书面形式。信息披露可以直接向各有关利害关系方作出，也可以向其代理人作出。"},{"i":22,"n":"第二十二条","txt":"信息披露后，利害关系方可以在10日内以书面方式向商务部提出评论意见。"},{"i":23,"n":"第二十三条","txt":"对利害关系方在规定时间内提供的评论，商务部应予以考虑，合理的内容应在最终裁定中予以采纳。最终裁定所依据的基本事实因此有所不同的，在不影响案件调查程序正常进行的情况下，商务部仍应迅速将此信息予以披露，相关利害关系方可以对此提出评论。"},{"i":24,"n":"第二十四条","txt":"涉及复审案件有关的产业损害调查信息查阅和信息披露参照本规定执行。"},{"i":25,"n":"第二十五条","txt":"本规定由商务部负责解释。"},{"i":26,"n":"第二十六条","txt":"本规定自公布之日起30日后实施。"}],"dikaichukoufapiaoxingweichufazanxingbanfa":[{"i":1,"n":"第一条","txt":"为规范对外贸易秩序，维护国家对外贸易利益，根据《中华人民共和国对外贸易法》、《行政处罚法》和其他相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"出口发票可分为监制出口发票和自制出口发票。监制出口发票是指由各地税务部门统一印制和监管的出口发票；自制出口发票是指对外贸易经营者自行打印的出口发票。"},{"i":3,"n":"第三条","txt":"本办法所指的“低开出口发票”是指对外贸易经营者在对外贸易中，向进口商提供的自制出口发票的票面价值低于出口报关时所提供发票票面价值的行为。"},{"i":4,"n":"第四条","txt":"在出现以下情况时，商务部会同税务总局进行调查，海关总署予以配合： 1、国内企业、相关行业组织等关于涉嫌存在低开出口发票行为的举报； 2、进口国相关政府部门正式提出的关于涉嫌存在低开出口发票行为的通报； 3、通过海关互助合作，发现对外贸易经营者涉嫌存在低开出口发票的行为； 4、其他关于涉嫌低开出口发票行为的举报。"},{"i":5,"n":"第五条","txt":"商务部在接到调查请求之日起10日内，对调查请求情况进行初步审核。根据审核结果，对于危害国家对外贸易秩序和对外贸易利益的，将有关材料移交海关总署，海关总署在接到商务部移交材料起50日内将对是否存在涉嫌低开出口发票行为进行核对,并将核对结果移交商务部。 商务部在接到海关总署核对结果之日起10日内，对初步认定存在涉嫌低开出口发票行为事实的，将有关材料移交税务总局；税务总局在接到商务部移交材料起50日内对对外贸易经营者是否从事该涉嫌低开出口发票行为进行调查并将调查结果移交商务部，但凡涉嫌偷逃骗税需移送稽查部门立案调查的，不受此限。对初步认定不存在涉嫌低开出口发票行为事实的，商务部应终止调查。 根据上述调查结果，商务部在确认存在低开出口发票行为时，自收到税务总局的调查结果之日起15日内依法对低开出口发票行为进行初步裁定，并将裁定结果在10日内书面送达相关对外贸易经营者；对确认不存在低开出口发票行"},{"i":6,"n":"第六条","txt":"在初步裁定送达相关对外贸易经营者之日起7日内，相关对外贸易经营者如有异议可向商务部提交书面申辩材料，并可提出听证申请。"},{"i":7,"n":"第七条","txt":"商务部对相关对外贸易经营者低开出口发票行为的处罚进行听证的，应当遵照《行政处罚法》的规定。"},{"i":8,"n":"第八条","txt":"自初步裁定做出之日起50日内，由商务部对相关对外贸易经营者的涉嫌低开出口发票行为进行最终裁定。"},{"i":9,"n":"第九条","txt":"对存在低开出口发票行为的对外贸易经营者，商务部依据《行政处罚法》的有关规定，对初次违反的企业予以警告；对第一次警告后2年内再次违反的企业除予以警告外，可以并处3万元人民币以下的罚款；以上违法行为，对外贸经营秩序造成严重影响的，可视其情节，给予违法企业禁止其在1年以上3年以下期限内从事有关对外贸易经营活动的处罚。 对于负有主要责任的企业法定代表人，可视情节，禁止其在1年以上3年以下期限内担任外贸企业法定代表人。 以上处罚，将依据《对外贸易法》及相关规定进行公告。 行政处罚决定书应自行政处罚做出之日起7日内送达相关对外贸易经营者。"},{"i":10,"n":"第十条","txt":"当事人对第九条所列行政处罚不服的，可以依法申请行政复议，也可以依法向人民法院提起诉讼。"},{"i":11,"n":"第十一条","txt":"有关单位和个人应当对商务部、海关总署和税务总局的相关调查给予配合、协助。 商务部、海关总署和税务总局对调查中知悉的国家秘密和商业秘密负有保密义务。 商务部、海关总署和税务总局的调查人员在调查过程中应该遵守国家相关的法律、法规和规章。"},{"i":12,"n":"第十二条","txt":"在调查过程中，如发现对外贸易经营者涉嫌低开监制出口发票的行为，由税务总局依据《中华人民共和国发票管理办法》的有关规定进行调查和处罚。如发现有走私及违反海关监管规定的行为的，由海关依据《中华人民共和国海关法》及《中华人民共和国海关行政处罚实施条例》的规定进行处罚。"},{"i":13,"n":"第十三条","txt":"本办法中调查程序的日期均指工作日。"},{"i":14,"n":"第十四条","txt":"本办法由商务部、海关总署和税务总局负责解释。"},{"i":15,"n":"第十五条","txt":"本办法自发布之日起3个月后施行。"}],"gongganghuojiaqinchukouguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为加强对供应香港活家禽的出口管理工作，维护出口经营秩序，提高产品质量，根据外经贸部《关于供应港澳鲜活冷冻商品主动配额管理暂行规定》，特制定本暂行规定。"},{"i":2,"n":"第二条","txt":"供港活家禽是指：活鸡（包括竹丝鸡、珍珠鸡）、活鸭（包括野鸭）、活鹅、活乳鸽。冰鲜家禽出口管理规定另行制定。"},{"i":3,"n":"第三条","txt":"出口配额的管理 （一）供港活家禽实行配额许可证管理，外经贸部根据香港市场需求和国内货源供应情况，安排供港活家禽年度配额。 （二）外经贸部驻广州特派员办事处（以下简称“广办”）依据外经贸部下达的年度配额和市场需求情况，安排分月出口配额。 （三）广办在代理机构提出的每周及每日要货建议的基础上，根据货源情况、市场需求和价格水平确定供港活家禽日配额总量，按比例下达给有关省市外经贸管理部门，并抄报有关口岸动植物检疫机关和海关等部门。广东省对外经济贸易委员会和深圳市贸易发展局根据广办下达的日配额总量，分别负责本地管辖范围内的供港活家禽日配额的安排，并报广办备案，同时抄送有关部门。其他省市的供港活家禽日配额安排由广办下达。 （四）广办应根据本暂行规定，商有关省市外经贸管理部门制订活家禽日配额具体实施细则并报外经贸部备案；代理机构须将活家禽在港查验的具体办法及相关协议报外经贸部和广办备案。"},{"i":4,"n":"第四条","txt":"出口配额的分配原则 （一）配额的分配与调整本着“公平、公正、效益”的原则进行。 （二）鼓励规模化、效益型、高质量经营。根据各地方和有关部委直属公司（以下简称“各单位”）配额使用、出口卖价和商品质量等情况实行奖优罚劣的配额分配机制。 （三）配额的分配按以下依据进行： 1．在确定下年配额总量的基础上，按各单位在当年年度配额总量中所占比重，计算出各单位的配额基数。 2．对当年1—8月份配额使用率（代理机构统计，下同）低于全国平均配额使用率的单位，扣减其配额基数的10—30％（具体扣减比例视各单位配额使用总体情况而定）。确定后的扣减比例适用于所有被扣减的单位。扣减的配额按比例奖励给配额使用率高于全国配额使用率的单位。 各单位的配额使用率均在80％（含80％）以上或均未达到80％时，不再进行配额的奖罚。 3．对当年1—8月份出口卖价低于活家禽出口价格协调小组商定的卖价的单位，扣减其配额基数的5—"},{"i":5,"n":"第五条","txt":"广办会同有关省市外经贸管理部门，共同组成由主营出口企业和代理机构参加的活家禽出口协调小组，及时制定和协调市场价格。"},{"i":6,"n":"第六条","txt":"出口许可证的管理 （一）供港活家禽出口许可证由外经贸部授权的发证机关发放，许可证有效期不得超过31天。 （二）出口企业在申领出口许可证时，须提供活家禽的生产企业注册登记代号、生产企业出具的保证书及出口合同等文件。 （三）发证机关须审核本条第二款的有关文件核发出口许可证。 （四）各出口企业应严格按日配额申领出口许可证，不得转让或倒卖出口许可证。"},{"i":7,"n":"第七条","txt":"活家禽出口的检疫 （一）供港活家禽须在经过口岸动植物检疫机关注册登记的生产场生产。 （二）出口的活家禽须由口岸动植物检疫机关实施产地检疫，检疫合格后签发动物检疫证书。有关供港活家禽生产场注册登记和出口检疫具体实施办法，由国家动植物检疫局另行制定。 （三）有关口岸动植物检疫局应定期将其检疫的有关情况报国家动植物检疫局，同时抄报外经贸部、广办和有关省市外经贸主管部门。"},{"i":8,"n":"第八条","txt":"海关凭有效出口许可证和动物检疫证书验放。"},{"i":9,"n":"第九条","txt":"代理机构的职责"},{"i":10,"n":"第十条","txt":"出口企业应严格按本暂行规定做好对港活家禽出口工作。对违反本规定者，一经查实，外经贸部将视情节轻重给予扣减配额、暂停直至取消其对港活家禽出口经营资格的处罚。 （一）香港华润（集团）五丰行是内地鲜活冷冻商品在香港的统一代理机构，负责协调管理市场销售工作。香港粤海（集团）广南行在接受统一代理机构协调的前提下，负责代理广东省和深圳市的活家禽出口；香港华润（集团）五丰行负责代理广东省和深圳市以外的其他省市的活家禽出口。出口企业须接受代理机构的市场协调，并与有关代理机构签定相应的代理协议，明确双方各自的责、权、利。 （二）代理机构负责确定香港的经销商和运输工具的审定，并将客户名单和运输工具登记名录报外经贸部和广办备案。 （三）代理机构应根据市场的实际需求，在广办安排的月度配额内，向广办提出每周及每日的要货建议并同时抄报有关省市外经贸管理部门。 （四）代理机构应严格按照有关省市外经贸管理部门下达的日"},{"i":11,"n":"第十一条","txt":"本暂行规定自发文之日起执行，由外经贸部负责解释。原我部制订下发的《进一步加强供港活鹅、活鸭出口经营管理暂行办法》同时废止。"}],"gonggangxianhuolengdongshangpinguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为加强对供港鲜活冷冻商品的管理，保证对香港市场的稳定供应，按照建立社会主义市场经济的总体要求，依照《中华人民共和国对外贸易法》，特制定本办法。"},{"i":2,"n":"第二条","txt":"商品品种范围：活畜（活大猪、活中猪、活乳猪、活牛）、活鸡、冻肉禽（冻猪肉〔包括冻猪付产品〕、冻乳猪、冻牛肉、冻鸡）、水产品（大闸蟹、活塘鱼）。除活塘鱼外，供港鲜活冷冻商品实行出口配额许可证管理。出口许可证由外经贸部授权的发证机关发放。许可证当月有效。"},{"i":3,"n":"第三条","txt":"管理机构及职责。外经贸部统一负责供港鲜活冷冻商品的出口管理工作。外经贸部驻广州特派员办事处（以下简称广州特办）根据外经贸部授权，负责供港鲜活冷冻商品的部分管理工作。各省、自治区、直辖市及计划单列市外经贸委、厅（以下简称地方外经贸管理部门）负责本地区供港鲜活冷冻商品的综合管理工作。香港华润（集团）五丰行（以下简称五丰行）是内地鲜活冷冻商品在香港的总代理，负责市场的协调、管理工作。香港粤海（集团）广南行（以下简称广南行）在接受总代理统一协调的前提下，负责代理广东省（含深圳市）出口的鲜活商品。"},{"i":4,"n":"第四条","txt":"供港活塘鱼实行配额放行证管理。出口配额由广东省对外经济贸易委员会（以下简称广东省外经贸委）商广州特办确定。其中，广东省外经贸委负责广东省供港活塘鱼的配额下达和出口放行证的签发工作，广州特办负责除广东省以外其他省市供港活塘鱼的配额下达和出口放行证的签发工作。"},{"i":5,"n":"第五条","txt":"外经贸部以相关商品香港市场的容量、市场供应的格局以及我远近期市场份额目标等为依据，参考总代理的建议，确定每年的配额总量。"},{"i":6,"n":"第六条","txt":"代理机构在提出配额总量建议时应提供以下资料： （一）相关商品香港市场前三年的市场需求情况。 （二）相关商品当年的市场供应情况及供应者各自的市场份额、经营状况及经营成本。 （三）代理机构１－３年的经营目标，包括年销量及市场份额目标。 （四）对市场可变因素的分析，包括消费习惯的变化、替代消费品的出现、市场突发事件对供求关系的影响等情况。"},{"i":7,"n":"第七条","txt":"外经贸部在确定配额总量后，将配额下达给有关地方外经贸管理部门和有关公司。 （一）活畜／活鸡：按经营能力，将配额下达给承担供应任务的地方外经贸管理部门和有关公司。 （二）冻肉禽：在现有经营能力的基础上，突出规模经营，以扩大出口为中心，配额向有经营实力并有出口潜力的地方倾斜。"},{"i":8,"n":"第八条","txt":"为避免市场、货源、运输等发生变化而影响供应，外经贸部将根据各地配额的完成情况和货源情况，对配额实行动态调整。 如遇突发性事件并明显影响市场供应，外经贸部将对相关商品的配额总量进行调整。"},{"i":9,"n":"第九条","txt":"地方外经贸管理部门和中国粮油食品进出口（集团）有限公司、中国出口商品基地建设总公司及有关公司（以下简称有关公司）按外经贸部的规定负责配额的二次分配。 （一）活畜／大闸蟹 １、分配给有相关商品出口经营能力的出口企业。 ２、鼓励规模经营。出口企业所获得的配额数量不得低于相关商品出口配额的最低分配标准。活大猪１５０００头，活中猪１００００头，活乳猪２５００头，活牛１０００头，大闸蟹３０吨。年出口配额总量达不到上述标准的口岸和有关公司，由１家经营。 ３、外经贸部将按本办法第十条的规定，试点审批有实力的生产场（厂）自营供港活大猪业务。经外经贸部批准的生产场（厂）可向地方外经贸管理部门申请出口配额。 （二）活鸡：按外经贸部《供港活鸡出口管理暂行规定》（〔１９９８〕外经贸管发１６６号）进行配额的二次分配，实行规模经营。 （三）冻肉禽 １、分配给有出口经营能力和出口实绩的出口企业。 ２、地方外经贸管理"},{"i":10,"n":"第十条","txt":"地方外经贸管理部门可根据以下标准向外经贸部申报１－２家生产企业自营供港活大猪出口业务。 （一）生产场（厂）的卫生防疫条件合格并经国家出入境检验检疫局注册登记。 （二）单个生产场（厂）母猪存栏达２０００头，年产活大猪３００００头以上；或前三年供港活大猪的供货实绩年均在１５０００头以上的生产场（厂）。 （三）企业具备独立法人资格，资产负债、销售及利润状况良好（附资产负债表和损益表）。 （四）生产场（厂）的活大猪须实行自繁自养，其品种、规格符合香港市场的要求。"},{"i":11,"n":"第十一条","txt":"香港代理机构、国内出口企业和供货企业应按照市场经济的要求确立彼此之间代理与被代理的关系。 （一）活畜 １、代理机构和出口企业必须按照责、权、利统一的原则签定出口代理协议。出口企业有义务保质保量提供委托代理出口的商品，同时也有权了解被代理商品在市场销售的详细情况。五丰行在保证完成市场占有率目标的前提下，履行其总代理的权利。 ２、出口代理协议应对双方的供销数量、代理佣金及其他费用等有关内容明确各自应尽的义务和享受的权利。 ３、地方外经贸管理部门和有关公司应提供符合本办法第十五条规定的供货猪场名单并报外经贸部核准。出口企业在获得出口配额后，必须从经外经贸部核准公布的供货猪场收购出口。出口企业和供货猪场须签定相应的供货代理协议，明确双方的权利和义务。 （二）活鸡及冻肉禽 １、五丰行和广南行负责内地活鸡对香港的出口代理工作。其中，广南行负责代理广东省（含深圳市）的供港活鸡，五丰行负责代理除广东省"},{"i":12,"n":"第十二条","txt":"代理机构应认真调查、落实有关客户的资信状况和经营状况，保证及时、安全收汇。"},{"i":13,"n":"第十三条","txt":"供港鲜活冷冻商品的质量必须符合国家有关法律法规和标准的要求，任何商品均须经过国家出入境检验检疫机关的法定检验检疫并获得相应的检验检疫证书后方可供港。 （一）活畜／活鸡 １、各有关供港活畜、活鸡的饲养、屠宰、加工场（厂）必须遵守国家出入境检验检疫局和各产地出入境检验检疫机关制定的供港活畜、活鸡的检验检疫管理及生产场（厂）注册登记的有关规定，并接受各产地及离境口岸出入境检验检疫机关的监督管理。 ２、供港活畜、活鸡须为在产地出入境检验检疫机关注册登记的生产场（厂）出生并育成的。 ３、各类出口企业供港的活畜、活鸡，须向产地出入境检验检疫机关报检。经检验检疫合格后，由产地出入境检验检疫机关签发动物检验检疫证书。活畜、活禽运抵离境口岸时，经离境地出入境检验检疫机关进行离境前检验检疫。合格者，换证或验证放行；不合格者不得供港。 （二）冻肉禽 １、出口企业应严格按照外经贸部和原国家商检局《关于内地对港"},{"i":14,"n":"第十四条","txt":"为推动规模生产，保证质量，同时鼓励科学饲养、品种改良等，对港出口活大猪试行供货猪场认可制度。外经贸部根据生产场（厂）的生产能力、资产负债、销售及利润、卫生防疫水平以及产品的品种规格是否符合香港市场的要求等标准，认定并赋予生产场（厂）供货资格。任何出口企业只能出口经认可的猪场的活大猪。"},{"i":15,"n":"第十五条","txt":"符合以下条件的猪场均可通过地方外经贸管理部门向外经贸部申请供货资格。 １、生产场（厂）卫生防疫条件合格并经出入境检验检疫机关注册登记。 ２、以前无供货实绩的单个生产场（厂），实际年产活大猪５０００头以上；或前三年供港活大猪的供货实绩年均在３０００头以上的生产场（厂）。 ３、具备企业独立法人资格，资产负债、销售及利润状况良好（附资产负债表和损益表）。 ４、生产场（厂）的活大猪须实行自繁自养，其品种、规格符合香港市场的要求。"},{"i":16,"n":"第十六条","txt":"外经贸部将根据香港市场的需求状况和内地生产水平、出口规模经营等要求，适时调整有关标准，动态管理并公布供港活大猪认可猪场。其他活畜（活中猪、活乳猪、活牛），待条件成熟时也将采取供货资格认可制度。"},{"i":17,"n":"第十七条","txt":"市场销售情况的反馈。代理机构应在每月的中旬将上月有关商品的市场情况包括市场总的供需状况、外货、内地货及港产货的到货和销售情况报外经贸部。"},{"i":18,"n":"第十八条","txt":"地方外经贸管理部门和出口企业须按我部《进出口商品配额执行情况核查反馈办法》的有关要求，定期将有关商品的配额使用、出口等情况报外经贸部。"},{"i":19,"n":"第十九条","txt":"质量的反馈 （一）外经贸部定期向国家出入境检验检疫局了解产地出入境检验检疫机关对供港鲜活冷冻商品的检验检疫情况。 （二）代理机构每月须向外经贸部反映上月所有出口企业的出口商品质量状况。如有特殊的质量违规情况，应及时报告外经贸部。"},{"i":20,"n":"第二十条","txt":"代理机构、出口企业和供货企业有义务随时向外经贸部报告业务中出现的其他问题及情况。"},{"i":21,"n":"第二十一条","txt":"外经贸部将按照下达的年度配额以及对市场份额的目标等要求检查代理机构和出口企业的工作。"},{"i":22,"n":"第二十二条","txt":"当代理机构不能完成外经贸部下达的活大猪全年出口配额，活大猪市场份额目标不能实现时，代理机构须部分退还所收收入。当销量达到全年配额的９９．５％或以上时，视作全部完成。如未能完成的数量占全年配额总量的０．５－１０％以内，代理机构须将全年销售金额的０．５％退还给有关出口企业，如不能完成的数量占全年配额总量的１０－２０％以内，退还金提高到１％，依此类推。代理机构连续两年不能完成规定的销量，代理机构在退还部分销售金额的同时，外经贸部在下一年的配额安排时，将把原代理机构不能完成的数量安排第二家代理机构出口。"},{"i":23,"n":"第二十三条","txt":"出口企业的配额完成率是安排企业下年度出口配额的重要依据。对配额完成率低于全国平均水平或达不到８０％（当平均完成率超出８０％时）的企业，按所欠比例扣减配额。"},{"i":24,"n":"第二十四条","txt":"对达不到本办法第九条冻肉禽最低出口标准的企业，三年内不再安排相关商品的出口配额。"},{"i":25,"n":"第二十五条","txt":"供港活大猪、活鸡质量出现问题并经查实，问题出在供货猪场或鸡场的，对负直接责任的猪场或鸡场，立即取消其供货资格，对负间接责任的出口企业扣减相关出口企业下二个月三分之一的配额。经查实，问题出在猪场或鸡场以外，对负直接责任的出口企业扣减下二个月配额的二分之一，两年内累计违规达３次者，取消其该项商品的出口配额，不再恢复。"},{"i":26,"n":"第二十六条","txt":"对违反规定收购非注册生产场（厂）生产的活畜、活鸡的出口企业，经查实，外经贸部取消其供港活畜、活鸡的出口配额，不再恢复。"},{"i":27,"n":"第二十七条","txt":"对出现质量问题的其他商品，经查实，按所出货物的三倍数量扣减配额。"},{"i":28,"n":"第二十八条","txt":"对未经外经贸部批准超配额出口的出口企业，外经贸部将取消其全年出口配额。"},{"i":29,"n":"第二十九条","txt":"严禁出口企业以任何方式自行转让、买卖出口配额许可证。如出现上述情况，一经查实取消其出口经营权。"},{"i":30,"n":"第三十条","txt":"代理机构的代理行为明显有失公平竞争原则，造成香港市场鲜活冷冻商品销售秩序混乱；或代理机构不能保证出口收汇，造成出口企业的经济利益受到损失，经查实，外经贸部将终止该代理机构的代理。"},{"i":31,"n":"第三十一条","txt":"目前国内牲畜饲养水平及集约化经营水平基本达到国外同类水平，而且已能充分满足香港市场的需要，外经贸部原则上不再审批新的对港出口鲜活冷冻商品的合资企业。对在本文实施前未经外经贸部批准的合资生产场（厂），也不再受理补报申请。"},{"i":32,"n":"第三十二条","txt":"外经贸部已批准的外商投资企业，其出口的产品必须是自产产品。外商投资企业的出口数量不得超过外经贸部核定的出口规模。"},{"i":33,"n":"第三十三条","txt":"广州特办根据本办法制定、修改相应商品的月度配额或日配额管理规定，并报外经贸部备案。"},{"i":34,"n":"第三十四条","txt":"本办法由外经贸部负责解释。"},{"i":35,"n":"第三十五条","txt":"本办法自公布之日起执行，以前的有关管理规定与本办法不符之处，以本办法为准。"}],"baozhangcuoshichanyesunhaidiaochaguiding":[{"i":1,"n":"第一条","txt":"为规范保障措施产业损害调查，根据《中华人民共和国保障措施条例》（以下简称保障措施条例），制定本规定。"},{"i":2,"n":"第二条","txt":"依据保障措施条例进行的保障措施产业损害调查相关活动，适用本规定。"},{"i":3,"n":"第三条","txt":"中华人民共和国商务部（以下简称商务部）负责保障措施产业损害的调查。涉及农产品的保障措施产业损害调查，由商务部会同农业部进行。"},{"i":4,"n":"第四条","txt":"损害，是指由于进口产品数量增加，对生产同类产品或者直接竞争产品的国内产业造成严重损害或者严重损害威胁。 严重损害是国内产业受到的全面的和重大的减损。 严重损害威胁是明显迫近的严重损害，如果不采取措施将导致严重损害的发生。"},{"i":5,"n":"第五条","txt":"在确定进口产品数量增加对国内产业造成的严重损害或严重损害威胁时，应当考虑以下因素： （一）进口产品增长情况，包括进口产品的绝对和相对增长率和增长量； （二）增加的进口产品在国内市场中所占的份额； （三）进口产品对国内产业的影响，包括对国内产业在产量、销售水平、市场份额、生产率、设备利用率、利润与亏损、就业等方面的影响； （四）造成国内产业损害的其他因素。 对严重损害威胁的确定，应当依据事实，审查被调查产品出口国的生产能力、库存情况、出口能力和对中国出口继续增加的可能性等因素，而不得仅依据指控、推测或者极小的可能性。"},{"i":6,"n":"第六条","txt":"商务部在确定进口增长对国内产业的影响时，应当依据确实的证据，客观、综合地评估影响国内产业状况的各种可量化的指标，而不得仅根据个别指标作出裁决。"},{"i":7,"n":"第七条","txt":"同类产品，是指与被调查进口产品相同的产品；没有相同产品的，以与被调查进口产品的特性最相似的产品为同类产品。 直接竞争产品，是指与被调查进口产品虽然不是同类产品，但是与被调查进口产品具有相近的用途和较强的可替代性，且具有直接竞争关系的产品。"},{"i":8,"n":"第八条","txt":"在确定同类产品和直接竞争产品时，可以考虑以下因素：产品的物理特征、化学性能、生产设备和工艺、产品用途、产品的可替代性、消费者和生产者的评价、销售渠道、价格等。"},{"i":9,"n":"第九条","txt":"商务部在进行产业损害调查时，应当为进口产品的使用者、消费者等提供陈述意见、提交证据的机会。"},{"i":10,"n":"第十条","txt":"保障措施案件的产业损害调查期通常为立案调查开始前的三至五年。"},{"i":11,"n":"第十一条","txt":"利害关系方申请参加保障措施产业损害调查活动的，应当自保障措施调查立案公告发布之日起20日内向商务部提出参加调查活动的申请，办理有关登记。同时，可以对保障措施产业损害调查中的产业损害发表意见，提供相应证据。"},{"i":12,"n":"第十二条","txt":"利害关系方包括以下范围： （一）被调查产品的外国（地区）生产者、出口经营者、国内进口经营者，或者该产品生产者、出口经营者、进口经营者的行业组织或者其他组织； （二）被调查产品的原产国（地区）、出口国（地区）的政府及其代表； （三）国内同类产品的生产者、经营者，或者该产品生产者、经营者的行业组织或者其他组织； （四）其他。"},{"i":13,"n":"第十三条","txt":"利害关系方参加调查活动，应当出具相关身份证明。利害关系方为企业或者其他组织的，应当出具营业执照等登记证明、法定代表人身份证明。 委托代理人参加调查活动的，应当出具代理人身份证明及授权委托书；委托律师作代理人的，应当委托中国律师事务所及中国执业律师，并应当出具授权委托书、律师事务所营业执照、律师执业证明。"},{"i":14,"n":"第十四条","txt":"商务部保障措施产业损害调查的对象包括国内生产者、国内进口经营者、国内购买者、国内最终消费者、国外出口经营者、国外生产者等。"},{"i":15,"n":"第十五条","txt":"商务部认为有必要的，可以聘请有关产业、财会、经贸、法律等方面的专家提供咨询意见。有关专家应当承担相应的保密责任。"},{"i":16,"n":"第十六条","txt":"商务部采取问卷、抽样、听证、技术鉴定、实地核查等调查方式进行产业损害调查。"},{"i":17,"n":"第十七条","txt":"商务部向利害关系方发放的调查问卷包括国内生产者调查问卷，国内进口商调查问卷，国内用户调查问卷，国外生产者、国外出口商调查问卷或者其他类型的调查问卷。"},{"i":18,"n":"第十八条","txt":"利害关系方应当按问卷规定的方式和时间返回答卷。如需延期，应当在答卷截止日期的7日前向商务部提出书面申请并说明理由。是否同意延期，由商务部决定。"},{"i":19,"n":"第十九条","txt":"商务部可以对利害关系方进行实地核查。实地核查前，应当将核查的主要目的和内容提前通知有关利害关系方。"},{"i":20,"n":"第二十条","txt":"应利害关系方请求或者根据调查需要，经有关国家（地区）同意，商务部可以派出人员赴该国家（地区）对有关产品的生产能力、投资扩产、库存、原产或转口及企业间的关联关系等情况进行调查。"},{"i":21,"n":"第二十一条","txt":"商务部可以要求利害关系方按照规定提交或者补充书面材料，利害关系方也可以主动向商务部提交书面材料。"},{"i":22,"n":"第二十二条","txt":"应利害关系方的请求，或者商务部认为有必要的，可以举行产业损害听证。"},{"i":23,"n":"第二十三条","txt":"参加产业损害调查的利害关系方认为其所提供的资料及相关证据有必要保密的，应当在提交资料的同时向商务部提交该资料的非保密概要，或者分别提交该资料的保密文本和公开文本。"},{"i":24,"n":"第二十四条","txt":"参加产业损害调查的利害关系方不提供资料及相关证据的非保密概要或公开文本的，或者不提交非保密概要或公开文本理由不充分的，商务部可以对该资料不予考虑。商务部如果认为提供的资料不需要保密时，可以要求利害关系方撤销保密申请。"},{"i":25,"n":"第二十五条","txt":"在产业损害调查过程中，应诉产业损害调查的利害关系方应当如实反映情况，提供有关资料。利害关系方不如实反映情况、提供有关资料的，或者没有在合理时间内提供必要信息的，或者以其他方式严重妨碍调查的，商务部可以根据已经获得的事实和可获得的最佳信息作出裁定。"},{"i":26,"n":"第二十六条","txt":"参加产业损害调查的利害关系方在向商务部提交任何文件及证据材料时，均应提交中文正本一式5份，并同时提交相应的电子文本（计算机软盘或光盘）一式3份。"},{"i":27,"n":"第二十七条","txt":"商务部产业损害调查，依据国家语言文字主管部门规定的规范中文为正式语言和文字。利害关系方所提供的任何文件、资料、信息应当为规范中文。非中文资料应提交中文译文及原文，并以中文译文为准。非中文资料如未附有中文译文将不被视为有效的和合法的证据材料。"},{"i":28,"n":"第二十八条","txt":"本规定由商务部负责解释。"},{"i":29,"n":"第二十九条","txt":"本规定自公布之日起30日后施行。本规定施行之日，原国家经贸委颁布的《保障措施产业损害调查与裁决规定》（国家经贸委令[2002]第47号）同时废止。"}],"baozhangcuoshidiaochatingzhenghuizanxingguize":[{"i":1,"n":"第一条","txt":"为保证保障措施调查的公平、公正，维护利害关系方的合法权益，根据《中华人民共和国保障措施条例》的有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"本规则适用于对外贸易经济合作部在保障措施调查程序中举行的为确定进口产品数量增加及其与损害之间因果关系而进行的听证会。"},{"i":3,"n":"第三条","txt":"对外贸易经济合作部进出口公平贸易局（以下简称“进出口公平贸易局”）具体组织本规则所称听证会。"},{"i":4,"n":"第四条","txt":"本规则所称听证会应公开举行。但涉及国家秘密、商业秘密或个人隐私的，进出口公平贸易局决定后可采取其他方式举行。"},{"i":5,"n":"第五条","txt":"进出口公平贸易局应利害关系方的申请举行听证会。进出口公平贸易局如认为必要时，可以自行决定举行听证会。"},{"i":6,"n":"第六条","txt":"进出口公平贸易局自行举行听证会的，应当事先通知利害关系方，并适用本规则的相关规定。"},{"i":7,"n":"第七条","txt":"本规则所指利害关系方为保障措施调查的申请人、出口国（地区）政府、原产国（地区）政府、已知的出口经营者和进口经营者，以及其他有利害关系的组织或个人。"},{"i":8,"n":"第八条","txt":"利害关系方要求举行听证会的，应当向进出口公平贸易局提出要求举行听证会的书面申请。 申请书应当包括下列内容： （一）听证会申请人的名称、地址和有关情况； （二）申请的事项； （三）申请的理由。"},{"i":9,"n":"第九条","txt":"进出口公平贸易局应当在收到利害关系方的听证会书面申请后15天内决定是否举行听证会，并应及时通知有关利害关系方。"},{"i":10,"n":"第十条","txt":"进出口公平贸易局决定举行听证会的通知应包括如下内容： （一）决定举行听证会； （二）决定举行听证会的理由； （三）各利害关系方在听证会前的登记的时间、地点及相关要求； （四）其他与听证会有关的事项。"},{"i":11,"n":"第十一条","txt":"各利害关系方在收到决定举行听证会的通知后，应根据通知的内容和要求及时向进出口公平贸易局登记，并提交听证会发言的书面概要和有关证据。"},{"i":12,"n":"第十二条","txt":"进出口公平贸易局应当在决定举行听证会的通知所确定的登记截止之日起20天内对听证会举行的时间、地点、听证会主持人、听证会会议议程做出决定，并通知已登记的利害关系方。"},{"i":13,"n":"第十三条","txt":"听证会主持人在听证会中行使下列职权： （一）主持听证会会议的进行； （二）确认参加听证会人员的身份； （三）维护听证会秩序； （四）向各利害关系方发问； （五）决定是否允许各利害关系方提交补充证据，是否对已出示的证据进行鉴定； （六）决定中止或者终止听证会； （七）需要在听证会中决定的其他事项。"},{"i":14,"n":"第十四条","txt":"参加听证会的利害关系方可以由其法定代表人或主要负责人参加听证会，也可委托1至2名代理人参加听证会。"},{"i":15,"n":"第十五条","txt":"参加听证会的利害关系方应当承担下列义务： （一）按时到达指定地点出席听证会； （二）遵守听证会纪律，服从听证会主持人安排； （三）如实回答听证会主持人的提问。"},{"i":16,"n":"第十六条","txt":"听证会应当遵照下列程序进行： （一）听证会主持人宣布听证会开始，宣读听证会纪律； （二）核对听证会参加人； （三）利害关系方陈述； （四）听证会主持人询问利害关系方； （五）利害关系方作最后陈述； （六）主持人宣布听证会结束。"},{"i":17,"n":"第十七条","txt":"听证会旨在为调查机关提供进一步收集信息和为各利害关系方提供陈述意见及提交证据的机会，不设辩论程序。"},{"i":18,"n":"第十八条","txt":"听证会应当制作笔录，听证会主持人、笔录记录人、参加听证会的各利害关系方应当当场签名或者盖章。利害关系方拒绝签名或者盖章的，听证会主持人应当在听证笔录上载明有关情况。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，经进出口公平贸易局决定可以延期或取消举行听证会： （一）听证会申请人因不可抗力的事件或行为，且已提交延期或取消听证会的书面申请的； （二）保障措施调查终止； （三）其他应当延期或取消的事项。"},{"i":20,"n":"第二十条","txt":"听证会延期举行的原因消除后，进出口公平贸易局应当立即恢复听证会，并通知已登记的利害关系方"},{"i":21,"n":"第二十一条","txt":"本规则所指通知形式为对外贸易经济合作部公告，特殊情况下进出口公平贸易局可以采取其他形式。"},{"i":22,"n":"第二十二条","txt":"听证会使用的工作语言为中文。"},{"i":23,"n":"第二十三条","txt":"对外贸易经济合作部负责本规则的解释。"},{"i":24,"n":"第二十四条","txt":"本规则自2002年3月13日施行。"}],"baozhangcuoshidiaochalianzanxingguize":[{"i":1,"n":"第一条","txt":"为规范保障措施调查申请及立案程序，根据《中华人民共和国保障措施条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"外经贸部可以应申请人的申请决定立案，进行保障措施调查；也可以自行决定立案，进行保障措施调查。"},{"i":4,"n":"第四条","txt":"与国内产业有关的自然人、法人或者其他组织（以下统称申请人），可以向外经贸部提出保障措施调查申请。"},{"i":5,"n":"第五条","txt":"保障措施调查申请应以书面形式提出。申请书应载明正式请求外经贸部立案进行保障措施调查的意思表示，并由申请人或其合法授权人盖章或签字。"},{"i":6,"n":"第六条","txt":"申请应当包括下列各项内容： （一）申请人情况的说明； （二）申请调查进口产品、国内同类产品或直接竞争产品的说明； （三）已知的申请调查进口产品出口国（地区）、出口商、生产商以及进口商的情况； （四）国内产业情况的说明； （五）申请调查进口产品数量增长情况的说明； （六）损害情况的说明； （七）进口增长与损害之间因果关系的说明； （八）请求； （九）申请人认为需要说明的其他事项。"},{"i":7,"n":"第七条","txt":"关于申请人情况，申请人应当提供下列资料： 申请人的名称、法定代表人、地址、电话k政编码、传真、联系人等。 申请人聘请了委托代理人的，还应当说明代理人的名称及身份等事项并提供授权委托书。"},{"i":8,"n":"第八条","txt":"关于申请调查进口产品、国内同类产品或直接竞争产品，申请人应当提供下列证据资料： （一）申请调查进口产品的详细说明包括名称、种类、规格、产品用途、市场情况、中华人民共和国进口关税税则号等； （二）国内同类或者直接竞争产品的名称、种类、规格、产品用途、市场情况等； （三）申请调查进口产品与国内同类或者直接竞争产品的异同点比较，包括产品的物理特征、化学性能、生产工艺、用途以及可替代性等方面。 （四）外经贸部认为需要提供的其他证据资料。"},{"i":9,"n":"第九条","txt":"申请人应当提供申请调查进口产品出口国（地区）、原产国（地区）名称，已知的申请调查进口产品的出口商、生产商和进口商的名称、地址和联系方式。"},{"i":10,"n":"第十条","txt":"关于国内产业情况，申请人应当提供下列证据资料： （一）所有已知的国内生产商以及相关协会、商会的名称。地址和联系方式； （二）申请提出前五年内，所有生产商每年生产的同类或者直接竞争产品的国内生产总量； （三）提出申请前五年内，申请人每年所生产的同类或者直接竞争产品的产量以及所占国内生产总量的份额； （四）外经贸部认为需要提供的其他证据资料。"},{"i":11,"n":"第十一条","txt":"关于申请调查进口产品数量增长情况，申请人应当提供下列证据资料： （一）提出申请前至少五年内该产品每年进口的数量及金额并以变动曲线图表予以表明； （二）提出申请前至少五年内申请调查进口产品各出口国（地区）出口的绝对数量以及各国（地区）出口量占申请调查进口产品全部进口量的百分比； （三）提出申请前至少五年内，从数量和金额两方面说明申请调查进口产品和国内同类产品或直接竞争产品各自在国内消费总量中所占份额； （四）进口增长的原因的分析，考虑因素包括但不限于过去五年里针对该产品所征收的进口关税税率、申请调查进口产品可能享有的减让或优惠待遇的资料以及申请调查进口产品的出口价格等； （五）外经贸部认为需要提供的其他证据资料。"},{"i":12,"n":"第十二条","txt":"以进口增加已经导致国内产业严重损害为由提出申请的，申请人应当提供下列证据资料： （一）影响国内产业状况的所有相关的客观和可量化的因素或指标，特别是：申请调查进口产品按绝对值和相对值计算的进口增加的比率和数量，增加的进口所占国内市场的份额，以及销售水平、产量、生产率、设备利用率、利润和亏损以及就业的变化； （二）申请调查进口产品价格对国内同类产品或直接竞争产品价格的影响的证据资料； （三）外经贸部认为需要提供的其他证据资料。"},{"i":13,"n":"第十三条","txt":"以进口增加造成国内产业严重损害威胁为由提出申请的，申请人应当提供下列证据资料： （一）申请调查进口产品出口国的出口能力、库存情况以及进口将可能继续增加的证据资料； （二）本规则第十二条（一）项所列因素或指标的明显迫近的变化趋势。"},{"i":14,"n":"第十四条","txt":"申请人在主张申请调查进口产品对国内产业的影响及提供证据材料时，应当针对国内同类产品或直接竞争产品的生产进行单独确定；不能针对国内同类产品或直接竞争产品的生产进行单独确定的，应当以包括国内同类产品或直接竞争产品在内的最窄产品组或者范围的生产确定。"},{"i":15,"n":"第十五条","txt":"关于进口增长与损害之间的因果关系，申请人应当分析所提交的上述资料，说明进口增长与国内产业损害二者之间的因果关系。 申请人在证明进口增长与国内产业损害之间的因果关系时，应当分析进口增长以外的同时导致产业损害的任何已知因素，这些因素包括但不限于需求的减少或消费模式的变化、外国和国内生产商的限制贸易做法以及它们之间的竞争、技术发展以及国内产业的出口实绩和生产率。申请人认为上述个别因素不适用的，应当予以说明。"},{"i":16,"n":"第十六条","txt":"申请人应当在申请书中说明要求采取保障措施的请求，可以说明要求采取措施的形式、具体内容、期限及理由等。"},{"i":17,"n":"第十七条","txt":"申请人同时申请实施临时保障措施的，应提供进口增长对国内产业已经造成严重损害或者正在造成严重损害威胁、如迟延采取措施将会造成难以补救的损害的证据，并说明关税应予提高的幅度。"},{"i":18,"n":"第十八条","txt":"申请人在提供本章所规定的证据材料时，应当说明证据来源。"},{"i":19,"n":"第十九条","txt":"申请中如涉及保密材料的，申请人应当提出保密申请；对于保密材料，申请人应当提交使案件其他利害关系方能够对保密材料有合理了解的非保密概要；如果申请人不能提供非保密概要，须说明理由。"},{"i":20,"n":"第二十条","txt":"保障措施调查申请书及有关证据资料应以简体中文印刷体形式提交。国家有统一规定术语的，应当采用规范用语。 如果申请人所提供的证据材料是外文的，申请人应当提供该材料的外文全文，并提供相关部分的中文翻译件。"},{"i":21,"n":"第二十一条","txt":"申请书及附具的证据资料应当包括保密文本（申请人提出保密申请的）和公开文本；其中，申请人应当提供保密文本正本1套，副本6套，公开文本除了正本1套，副本6套外，申请人还应当按申请调查进口产品的出口国（地区）的数量提供副本，如果申请调查进口产品出口国（地区）数量过多，则可以适当减少，但不得少于5份。"},{"i":22,"n":"第二十二条","txt":"申请人应当按照进出口公平贸易局要求的计算机程序提供申请书及其证据资料的电子数据载体。"},{"i":23,"n":"第二十三条","txt":"申请人应当以邮寄或直接送达等方式将申请书及证据材料递交进出口公平贸易局。"},{"i":24,"n":"第二十四条","txt":"申请人正式递交申请书及证据资料的，进出口公平贸易局应予以签收，签收之日为进出口公平贸易局收到申请书及有关证据资料之日。"},{"i":25,"n":"第二十五条","txt":"在做出立案调查决定并予公告之前，外经贸部应对申请人所提交的资料予以保密。"},{"i":26,"n":"第二十六条","txt":"进出口公平贸易局可以采取问卷或实地核查等方式对申请书及证据材料中包括申请人的资格、申请调查进口产品等问题进行调查。"},{"i":27,"n":"第二十七条","txt":"外经贸部通常应在正式收到要求采取保障措施的书面申请后60日内做出是否立案的决定，情况特别复杂的，可以适当延长审查期限。"},{"i":28,"n":"第二十八条","txt":"进出口公平贸易局在本规则第二十七条规定的期间内可以要求申请人对其保障措施调查申请进行调整或补充，申请人不做调整或补充或未按要求的内容和时间调整或补充的，可以驳回申请人的申请，并通知申请人。"},{"i":29,"n":"第二十九条","txt":"外经贸部决定不予立案的，则应当将不立案的决定通知申请人，并告之不予立案的理由。"},{"i":30,"n":"第三十条","txt":"外经贸部决定立案的，应当发布立案公告。 公告应载明下列内容： （一）申请调查进口产品的名称及说明； （二）申请调查进口产品的出口国（地区）： （三）立案依据材料的概要说明； （四）发起保障措施调查的日期； （五）保障措施调查期限； （六）允许利害关系方提出意见的时限； （七）调查机关的联系方式。"},{"i":31,"n":"第三十一条","txt":"外经贸部应当在作出立案调查的决定后7个工作日内通知世界贸易组织保障措施委员会。"},{"i":32,"n":"第三十二条","txt":"保障措施调查的立案日期为立案调查决定公告之日。"},{"i":33,"n":"第三十三条","txt":"外经贸部没有收到采取保障措施的书面申请，但有充分证据认为国内产业因申请调查进口产品数量增加而受到严重损害或者严重损害威胁的，可以自行决定立案，进行保障措施调查。"},{"i":34,"n":"第三十四条","txt":"外经贸部自行立案，发起保障措施调查，其所掌握的证据资料应当符合本规则第二章的有关规定。"},{"i":35,"n":"第三十五条","txt":"本规则由外经贸部负责解释。"},{"i":36,"n":"第三十六条","txt":"本规则自2002年3月13日起实施。"}],"qingxiaojiqingxiaofuduqijianfushenguize":[{"i":1,"n":"第一条","txt":"为保证反倾销期间复审的公平、公正、公开，根据《中华人民共和国反倾销条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"商务部（以下称调查机关）在反倾销措施有效期间内，根据反倾销措施生效后变化了的正常价值、出口价格对继续按照原来的形式和水平实施反倾销措施的必要性进行复审（以下简称期间复审），适用本规则。"},{"i":3,"n":"第三条","txt":"调查机关可以应原反倾销调查申请人、国内产业或代表国内产业的自然人、法人或有关组织（以下统称国内产业）、涉案国（地区）的出口商、生产商、国内进口商的申请立案，进行期间复审。 调查机关有正当理由的，可以自行立案，进行期间复审。"},{"i":4,"n":"第四条","txt":"期间复审申请应当自反倾销措施生效后每届满十二个月之日起三十日内提出。 对经复审的反倾销措施申请期间复审的，应当自复审后的裁决生效后每届满十二个月之日起三十日内提出。 在特殊情况下，经调查机关允许，期间复审申请可以在上述规定以外的其他时间提出。"},{"i":5,"n":"第五条","txt":"期间复审申请应当以书面形式提出，并由申请人本人、法定代表人或经其依法授权的人签署。 期间复审申请应当分为保密文本（如申请人提出保密申请）和公开文本。保密文本和公开文本均应提交书面正本一份，副本两份。除书面文本外，还应同时提供电子数据载体。"},{"i":6,"n":"第六条","txt":"出口商、生产商提出期间复审申请的，应当提交下列证据材料： （一）申请人的名称、地址和其他有关情况； （二）申请前十二个月内申请人的国内销售情况的数据； （三）申请前十二个月内申请人对中国出口情况的数据； （四）为计算倾销幅度而必须作出的各种调整及倾销幅度的初步计算结果； （五）正常价值、出口价格及倾销幅度所发生的重大变化将会持续的原因； （六）申请人认为需要说明的其他内容。 前款第（一）至（五）项规定的材料应当按照原反倾销调查问卷所要求的内容及形式提交。"},{"i":7,"n":"第七条","txt":"原反倾销措施为征收反倾销税的，未征收反倾销税的出口不得作为提出期间复审申请的依据。"},{"i":8,"n":"第八条","txt":"调查机关应当自收到出口商、生产商的期间复审申请之日起七个工作日内通知原反倾销调查申请人，原反倾销调查申请人可自收到通知之日起二十一日内对应否立案进行复审发表意见。"},{"i":9,"n":"第九条","txt":"国内产业提出期间复审申请的，应当提交下列证据和材料： （一）申请人的名称、地址及有关情况； （二）与原反倾销措施水平相比，正常价值、出口价格及倾销幅度的变化情况； （三）申请人认为需要说明的其他内容。 国内产业提出期间复审申请的，应当符合《中华人民共和国反倾销条例》第十七条关于产业代表性的规定。原反倾销调查申请人提出期间复审申请的，无须重新证明产业代表性。"},{"i":10,"n":"第十条","txt":"国内产业提出的期间复审申请可以针对原反倾销调查涉及的所有或部分国家（地区）的全部出口商、生产商，也可明确将复审范围限于指明的部分出口商、生产商。"},{"i":11,"n":"第十一条","txt":"调查机关应当在收到国内产业的期间复审申请后七个工作日内将复审申请公开文本及保密资料的非保密概要递交有关出口国（地区）政府。"},{"i":12,"n":"第十二条","txt":"出口商、生产商可以自调查机关将国内产业的期间复审申请的公开文本及保密资料的非保密概要递交有关出口国（地区）政府之日起二十一日内对应否立案进行复审发表意见。"},{"i":13,"n":"第十三条","txt":"进口商提出的期间复审申请，应当提交本规则第六条规定的出口商、生产商应当提交的证据材料。"},{"i":14,"n":"第十四条","txt":"如果进口商与出口商、生产商无关联关系，无法直接提供本规则第六条规定的有关正常价值和出口价格的证据和材料，或出口商、生产商不愿向进口商提供上述证据和材料，则进口商应当提供出口商、生产商的声明。声明应当明确表示倾销幅度已经降低或消除，且有关证据和材料将按照规定的内容和形式自进口商提出期间复审申请之日起三十日内直接提交给调查机关。"},{"i":15,"n":"第十五条","txt":"出口商、生产商根据本规则第十四条提供的证据和材料应当符合本规则第五条第二款的规定。"},{"i":16,"n":"第十六条","txt":"调查机关应当自收到进口商的期间复审申请之日起七个工作日内通知原反倾销调查申请人；原反倾销调查申请人可以自收到通知之日起二十一日内对应否立案进行复审发表意见。"},{"i":17,"n":"第十七条","txt":"调查机关通常应当在收到期间复审申请后六十日内作出立案或不立案的决定。"},{"i":18,"n":"第十八条","txt":"调查机关经审查发现期间复审申请及所附证据和材料不符合本规则要求的，可以要求申请人在规定期限内补充和修改。申请人未在规定期限内补充和修改，或补充和修改后仍不符合本规则要求的，调查机关可以驳回申请，以书面形式通知申请人并说明理由。"},{"i":19,"n":"第十九条","txt":"调查机关决定立案进行期间复审的，应当发布公告。期间复审的立案公告应当包括以下内容： （一）被调查产品的描述； （二）被调查的出口商、生产商的名称及其所属国（地区）名称； （三）立案日期； （四）复审调查期； （五）主张倾销幅度有所提高或降低或倾销已被消除的依据概述； （六）利害关系方表明意见和提交相关材料的时限； （七）调查机关进行实地核查的意向； （八）利害关系方不合作将承担的后果； （九）调查机关的联系方式。"},{"i":20,"n":"第二十条","txt":"出口商、生产商提出期间复审申请的，调查机关仅对申请人被调查产品的正常价值、出口价格和倾销幅度进行调查。"},{"i":21,"n":"第二十一条","txt":"国内产业提出期间复审申请的，调查机关应当对所申请的涉案国（地区）的所有出口商、生产商被调查产品的正常价值、出口价格和倾销幅度进行调查。 国内产业仅申请对原反倾销调查涉案国（地区）的部分出口商、生产商进行期间复审的，调查机关应当仅对指明的出口商、生产商被调查产品的正常价值、出口价格和倾销幅度进行调查。 原反倾销调查确定倾销幅度为零或微量的，调查机关不对其进行复审调查，但可以依法对其采取其他反倾销调查措施。经复审调查确定倾销幅度为零或微量的，仍可以进行复审调查。"},{"i":22,"n":"第二十二条","txt":"进口商提出期间复审申请的，调查机关应当仅对声明将向调查机关提交有关证据材料的出口商、生产商被调查产品的正常价值、出口价格和倾销幅度进行调查。"},{"i":23,"n":"第二十三条","txt":"期间复审的调查期通常为复审申请提交前的十二个月。"},{"i":24,"n":"第二十四条","txt":"出口商、生产商的数量或所涉及的产品型号过多，为每一出口商或生产商单独确定倾销幅度或调查全部型号或交易会带来过分负担并妨碍倾销调查及时完成的，调查机关可以根据反倾销抽样调查相关规则，采用抽样的办法进行调查。"},{"i":25,"n":"第二十五条","txt":"期间复审调查中，正常价值和出口价格的确定、调整和比较及倾销幅度的计算应当按照《中华人民共和国反倾销条例》第四条、第五条和第六条的有关规定进行。"},{"i":26,"n":"第二十六条","txt":"期间复审调查中，出口价格根据该进口产品首次转售给独立购买人的价格推定的，如果出口商、生产商提供充分的证据证明，反倾销税已适当地反映在进口产品首次转售给独立购买人的价格中和此后在中国的售价中，则调查机关在计算推定的出口价格时，不应扣除已缴纳的反倾销税税额。"},{"i":27,"n":"第二十七条","txt":"调查机关可以根据反倾销调查实地核查相关规则，对出口商、生产商的有关信息和材料的准确性和完整性进行实地核查。"},{"i":28,"n":"第二十八条","txt":"期间复审无须作出初步裁决，但调查机关作出最终裁决前，应当按照《中华人民共和国反倾销条例》第二十五条第二款及反倾销调查信息披露相关规则，将考虑中的、构成是否实施最终措施决定依据的基本事实进行披露，并给予利害关系方通常不少于十日的时间提出评论。"},{"i":29,"n":"第二十九条","txt":"本规则第二十八条规定的披露一经作出，期间复审申请人不得撤回申请。"},{"i":30,"n":"第三十条","txt":"出口商、生产商可以在本规则第二十八条规定的披露作出后的十五日内提出价格承诺申请。 商务部决定接受价格承诺的，应当按照《中华人民共和国反倾销条例》第三十三条的规定，向国务院关税税则委员会提出建议，国务院关税税则委员会根据商务部的建议作出决定，由商务部予以公告。"},{"i":31,"n":"第三十一条","txt":"期间复审应当自复审立案之日起十二个月内结束。"},{"i":32,"n":"第三十二条","txt":"商务部应当在复审期限届满十五日前向国务院关税税则委员会提出保留、修改或者取消反倾销税的建议。商务部在复审期限届满前根据国务院关税税则委员会的决定发布公告。"},{"i":33,"n":"第三十三条","txt":"期间复审期间，原反倾销措施继续有效。复审裁决自复审裁决公告规定之日起执行，不具有追溯效力。"},{"i":34,"n":"第三十四条","txt":"在反倾销措施届满时期间复审仍未完成，且国内产业未提出期终复审申请，调查机关也未决定自行立案进行期终复审的，调查机关应当发布公告终止期间复审；发起期终复审的，调查机关可以将期间复审与期终复审合并进行。"},{"i":35,"n":"第三十五条","txt":"本规则由商务部负责解释。"},{"i":36,"n":"第三十六条","txt":"本规则自2018年5月4日起施行。《倾销及倾销幅度期中复审暂行规则》（对外贸易经济合作部令2002年第23号）同时废止。"}],"guanyugonggangaodongrouqindebaozhuangxiangmatoujisa7bb68":[],"guanyubaozhangcuoshichanpinfanweitiaozhengchengxud756b54":[{"i":1,"n":"第一条","txt":"为保证保障措施工作的公平、公正、公开，根据《中华人民共和国保障措施条例》的有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"根据《中华人民共和国保障措施条例》第五条、第十五条、第十六条、第十八条、第二十一条的规定，对外贸易经济合作部（以下简称外经贸部）在保障措施立案公告以及保障措施裁定公告（以下简称保障措施公告）中确定保障措施立案调查的产品范围和适用保障措施的产品范围（以下简称保障措施产品范围），海关自公告规定之日起实施。"},{"i":3,"n":"第三条","txt":"保障措施公告实施期间，保障措施产品范围的调整均需在外经贸部相关对外公告中确定，海关自公告规定之日起实施。"},{"i":4,"n":"第四条","txt":"外经贸部保障措施公告产品范围的调整程序按本规则进行。 保障措施公告产品范围的调整程序包括申请程序和外经贸部受理申请、调查、决定及相关公告的程序。"},{"i":5,"n":"第五条","txt":"申请程序： （一）保障措施立案公告后，有关利害关系方对调查产品范围提出异议，应在公告规定的时间内或经外经贸部同意延长的期限内向外经贸部提出调整调查产品范围的申请。 （二）保障措施初裁公告后，有关利害关系方对适用保障措施产品范围提出异议，应在公告规定的时间内或经外经贸部同意延长的期限内向外经贸部提出调整适用保障措施产品范围的申请。 （三）本规则所称利害关系方是指保障措施申请人、国外生产商、出口商、进口商以及其他有利害关系的组织、个人。 （四）申请应以书面形式提出。"},{"i":6,"n":"第六条","txt":"申请书包括以下内容： （一）申请人名称及其简况，申请调整的产品； （二）要求调整的理由、理由的详细说明及相关证据； （三）申请调整产品的详细描述和说明。产品按如下顺序依次描述：税则号、物理特征、化学特性等，描述至能够体现该产品的唯一性和排他性；上述描述方式无法体现该产品的唯一性和排他性时，需详细说明产品的用途； （四）申请调整的进口产品与国内同类产品或直接竞争产品的异同点和可替代性的详细描述和说明； （五）申请调整的进口产品前五年的进口量和进口金额以及对后三年预测的进口量； （六）国外生产商、出口商、进口商及下游用户； （七）申请人法定代表人或其合法授权人的盖章或签字。"},{"i":7,"n":"第七条","txt":"受理、调查、决定和公告程序： （一）外经贸部对申请人递交的申请书进行核对，对符合第六条要求的申请，予以受理； （二）外经贸部通过问卷、实地核查、听证会等方式对申请内容的真实性进行调查和核查； （三）外经贸部对申请内容的合理性和包括保障措施申请人在内的各利害关系方的利益进行调查，对产品的描述和说明等情况进行核查。必要时，可以聘请专家进行论证； （四）按照上述程序规定，对符合保障措施产品范围调整条件的申请，外经贸部可以决定对保障措施产品范围进行调整并予以公告； （五）外经贸部没有收到调整产品范围的申请，根据对利害关系方提交材料的审查，也可以决定调整产品范围； （六）最终保障措施终裁决定实施后，如有必要对公告内容进行调整的，可以参照上述程序决定后，均由外经贸部予以公告。"},{"i":8,"n":"第八条","txt":"涉及有关保障措施复审的，产品范围的调整参照本规则执行。"},{"i":9,"n":"第九条","txt":"本规则由外经贸部负责解释。"},{"i":10,"n":"第十条","txt":"本规则自公布之日后30天开始实施。"}],"guanyuxiugaijinchukoushangpinxukezhengfazhengjigou6455c6":[{"i":1,"n":"第一条","txt":"为加强进出口商品许可证签发工作的管理，使签发管理工作实现制度化、规范化、技术化，维护正常的外经贸经营秩序，依据《中华人民共和国对外贸易法》及国家许可证管理有关规定，特制定本办法。"},{"i":2,"n":"第二条","txt":"配额许可证事务局（以下简称许可证局）经商务部授权统一管理全国的许可证签发工作，向商务部负责。"},{"i":3,"n":"第三条","txt":"许可证局负责监督、检查、管理商务部驻各地特派员办事处（以下简称各特办）、各省、自治区、直辖市、计划单列市及部分省会城市外经贸委（厅、局）所属发证机构（以下简称各地方发证机构）的进出口商品许可证签发工作，并进行业务指导。"},{"i":4,"n":"第四条","txt":"许可证局负责按本办法的规定签发国家重点管理商品的许可证。各特办、各地方发证机构（以下简称各发证机构）受许可证局委托负责签发授权范围内部分进出口商品许可证。其发证业务接受许可证局的管理和指导，对许可证局负责。"},{"i":5,"n":"第五条","txt":"许可证局根据商务部对许可证管理的宏观要求，按照方便企业、减少机构重叠的原则，研究制定发证机构设置和调整方案。"},{"i":6,"n":"第六条","txt":"地方发证机构原则上应与地方配额管理部门在机构或人员上实行分离。发证机构设置及其工作人员配备由地方外经贸委（厅、局）负责根据地方实际情况调整或分离。"},{"i":7,"n":"第七条","txt":"地方设立发证机构的原则及条件： 原则上一个省级行政区设立一个发证机构。地方设立发证机构应具备以下条件： （一）根据工作实际需要，确有一定的发证工作量。 （二）配置计算机等发证专用设备，并实行了统一的网络化管理。 （三）配备有一定的政治、业务素质，熟悉外经贸方针、政策、许可证管理规章制度、签证规范的专职工作人员及管理人员。"},{"i":8,"n":"第八条","txt":"各地方发证机构根据发证工作量制定人员配置方案，人员配置方案须报许可证局备案。"},{"i":9,"n":"第九条","txt":"许可证局会同商务部主管业务司对各特办发证业务处、各地方发证机构进行验收。经验收合格方能从事发证工作。"},{"i":10,"n":"第十条","txt":"接受许可证局委托按照许可证管理商品发证目录签发部分进出口商品许可证。"},{"i":11,"n":"第十一条","txt":"严格按照许可证管理规章制度、签证规范受理签发进出口商品许可证，不得越权或超范围发证，严禁无配额或超配额发证。"},{"i":12,"n":"第十二条","txt":"严格按规定及时准确通过中国国际电子商务网上报进出口商品许可证签发数据。"},{"i":13,"n":"第十三条","txt":"负责本地区或联系地区各类进出口商品许可证签发及配额使用情况的统计分析工作，并将情况综合上报许可证局，由许可证局将各地情况汇总分析，按月向商务部反馈发证情况及配额使用情况。"},{"i":14,"n":"第十四条","txt":"各发证机构须根据商务部规定，建立健全下列各项内部管理制度： （一）许可证内部审核签发工作制度 （二）印章使用保管制度 （三）许可证发放登记制度 （四）发证程序管理制度 （五）发证专用设备管理制度 （六）空白证书保管、使用登记制度 （七）档案管理制度 （八）许可证收费财务管理制度"},{"i":15,"n":"第十五条","txt":"各发证机构应建立进出口商品许可证受理、审批、打印、审（复）核、交接以及数据传输等各项工作的岗位责任制。进出口商品许可证必须经两人以上的工作程序签发。"},{"i":16,"n":"第十六条","txt":"各发证机构应研究分析许可证管理商品进出口情况，对在处理许可证签发工作中遇到的问题应及时向许可证局请示报告。"},{"i":17,"n":"第十七条","txt":"各发证机构接受许可证局委托，负责收缴许可证手续费。"},{"i":18,"n":"第十八条","txt":"各发证机构要面向企业宣传贯彻国家的外经贸方针政策，并对企业提供服务。"},{"i":19,"n":"第十九条","txt":"各发证机构发证专用设备由许可证局按照各发证机构业务量统筹配置统一管理。发证专用设备属国有固定资产，列入许可证局固定资产进行管理。"},{"i":20,"n":"第二十条","txt":"各发证机构应建立计算机设备管理制度及日常维护保养制度，确保许可证发证专用设备及发证局域网的安全性、可靠性。"},{"i":21,"n":"第二十一条","txt":"各发证机构发证计算机设备必须使用商务部下发的进出口许可证管理系统软件和纺配证书系统软件，不允许使用其他软件、软盘。不允许自行改动代码和许可证发证数据。对纺配证书企业上报的软盘必须进行防病毒处理后再进行操作。要防范计算机“黑客”侵入发证局域网。"},{"i":22,"n":"第二十二条","txt":"各发证机构对商务部下发的发证程序软件、上报数据软件及密钥盘应按保密文件规定实行专人专柜管理并监督使用。软件需拷贝备份时，应在处长监督下进行。拷贝备份应存入专柜。发证程序软件只能安装在发证专用计算机。各发证机构对发证程序及上报数据程序应按规定重新设置密码，密码每季度更换一次，并做好保密工作。"},{"i":23,"n":"第二十三条","txt":"许可证发证专用设备只能用于进出口商品许可证签发工作，不得挪作他用。"},{"i":24,"n":"第二十四条","txt":"各发证机构工作人员应严格按照签证规范操作使用计算机发证设备，不得用发证计算机从事许可证签发管理工作以外的事情。"},{"i":25,"n":"第二十五条","txt":"严格执行国家及有关部门制定的财务规章制度。根据国家行政性收费管理规定，许可证收费实行“收支两条线”管理。"},{"i":26,"n":"第二十六条","txt":"许可证局受财政部和商务部委托作为执收单位，对许可证收费实行统—管理。各发证机构受许可证局委托负责收缴许可证手续费，是委托执收单位。"},{"i":27,"n":"第二十七条","txt":"各发证机构应严格按照国家批准的进出口商品许可证收费项目和收费标准收费，并使用财政部监制，许可证局统一发放的“进出口货物许可证专用收费收据”。"},{"i":28,"n":"第二十八条","txt":"各发证机构应严格按照许可证局的有关规定按时、足额上缴许可证手续费收入，并按照规定的范围和标准使用许可证局下拨的业务经费。"},{"i":29,"n":"第二十九条","txt":"各发证机构应严格管理财务、财产档案。财务、财产档案包括：许可证证款专用票据、会计帐簿、会计报表、各种会计凭证、专用设备帐卡及相关资料。"},{"i":30,"n":"第三十条","txt":"各发证机构的“进、出口许可证专用章”及“纺织品配额证书专用章”由许可证局统一刻制并核发。各种签证专用章应专人保管并监督使用。"},{"i":31,"n":"第三十一条","txt":"空白许可证书的征订印制、发放工作由许可证局统一管理。各发证机构接收空白许可证书后应立即组织验收，验收工作需由二人同时在场，验收无误后登入台帐并填写验收记录报许可证局。凡包装箱铅封损坏的应开箱对箱内许可证进行检查，发现丢失应立即封存，做出书面纪录并书面报许可证局进行处理。"},{"i":32,"n":"第三十二条","txt":"各发证机构要加强空白许可证书管理，并建立空白证书及错、废证入库、出库台帐登记签收制度。空白证书出库需二人同时在场开箱并检查箱内证书号码段及份数，核对无误后方办理出库登记手续。发现异常情况（缺失、错号、无防伪标志等）应立即封存做出书面记录并报许可证局进行处理。"},{"i":33,"n":"第三十三条","txt":"对已签发的许可证要及时将原始材料造册、归档。保证许可证档案的完整性。—经签发的许可证，其原始档案任何人不得更改。任何人不得私自收藏许可证档案。复印或借阅归档的许可证须履行登记手续。"},{"i":34,"n":"第三十四条","txt":"签证专用章、空白证书、错、废证及许可证档案实行专人专柜（室）保管，严防丢失、损坏、盗用。"},{"i":35,"n":"第三十五条","txt":"许可证档案指： （一）许可证的存底联 （二）有审批意见的申领许可证申请表（更改表） （三）签发许可证的依据（批件、配额或登记证明，招标商品的领证证明书，合同，介绍信或证明信等） （四）发证软盘 （五）发证登记本 （六）空白证书领用核销登记本 （七）需要保存的其他资料 （八）许可证档案、空白证书、废、错证销毁登记帐册"},{"i":36,"n":"第三十六条","txt":"许可证空白证书及许可证档案的保管、销毁按保密文件的有关规定执行。许可证档案保存期限五年，未使用的空白证书保存期限二年。销毁时必须详细登记证号，并履行报批手续。未经领导批准，任何人不得擅自作转移、销毁处理。"},{"i":37,"n":"第三十七条","txt":"许可证局负责统一管理各发证机构工作人员的业务培训工作，编写发证人员培训教材。培训内容包括外经贸政策、配额许可证管理规章制度、签证规范、计算机操作及软件使用。"},{"i":38,"n":"第三十八条","txt":"各发证机构工作人员必须经过上述培训后方可上岗。 各特办工作人员派出前由许可证局负责组织培训。各地方发证机构工作人员由地方发证机构负责组织培训。许可证局将根据需要不定期举办发证工作人员培训班。"},{"i":39,"n":"第三十九条","txt":"对于严格遵守许可证业务、设备、财务、印章、档案管理各项规章制度，切实为企业提供优质服务，在许可证管理工作中成绩显著的发证机构或个人，将予以表彰和奖励。"},{"i":40,"n":"第四十条","txt":"对下列行为之一者，视情节轻重分别给予通报批评，停止单项商品发证权，直至取消全部商品发证权的处罚： （一）无配额、超配额签发许可证 （二）违反配额许可证管理规定，擅自延长许可证有效期 （三）超越管辖范围签发、更改许可证 （四）不按规定上报许可证签发数据或上报数据不及时、不准确，经批评后不改正或上报数据弄虚作假的 （五）未按本办法要求建立内部管理制度或虽有制度不认真执行，以至发生空白许可证证书、签证专用章、许可证档案，计算机发证和数据管理程序及密码丢失、泄密或被非法盗用，造成责任事故的 （六）违反“许可证收费收入财务管理办法”不按时及足额上缴许可证收费收入或不使用许可证收费专用单据，擅自提高收费标准的"},{"i":41,"n":"第四十一条","txt":"各发证机构发生上述行为，对直接责任者应调离岗位，并视情节轻重由各发证机构上级主管单位分别给予通报批评、警告、记过、记大过、降级、撤职、开除公职等处分，并追究主管领导责任；触犯刑律的依法追究其刑事责任。"},{"i":42,"n":"第四十二条","txt":"许可证局负责对发证机构的违规行为进行调查和处罚，取消发证机构发证权的处罚在报商务部批准后执行。"},{"i":43,"n":"第四十三条","txt":"本办法由商务部配额许可证事务局负责解释，过去有关规定凡与本规定不一致的，以本规定为准。"},{"i":44,"n":"第四十四条","txt":"本办法自发布之日起执行。"}],"guanyuyinfaguifanjinchukoudailiyewuderuoganguiding63fc9b":[{"i":1,"n":"第一条","txt":"为进一步规范进出口代理业务，打击和防范各种走私违规，骗汇、逃套汇和骗税行为，防止出卖或变相出卖进出口经营权和许可证，特制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于外贸企业（指各类经批准具有进出口经营权的企业，以下均同）以自已名义从事的进出口代理业务。"},{"i":3,"n":"第三条","txt":"从事进出口代理业务的外贸企业，必须经对外贸易经济合作部或其授权的地方外经贸主管部门批准具有进出口代理经营范围。 对国家实行核定公司经营的进口商品和国家组织统一联合经营的出口商品，无该项商品进口或出口经营权的外贸企业不得以任何方式从事代理业务。 自营进出口生产企业和科研院所。外商投资企业（经批准允许从事进出口代理业务的投资性公司和合资外贸公司除外）等均不得以任何方式从事进出口代理业务。"},{"i":4,"n":"第四条","txt":"代理人要加强对代理合同。进出口合同和各种单证的审核、管理，建立健全合同、单证的登记、备案、保存制度和代理进口购汇，付汇内部审批制度，并对所办单证的真实性负责。"},{"i":5,"n":"第五条","txt":"从事进出口代理业务，代理人必须与委托人签订书面代理合同，并由代理人根据代理合同与外商签订进出口合同。 代理合同和进出口合同的条款内容，必须符合国家法律、法规规定。"},{"i":6,"n":"第六条","txt":"代理人要加强对外商资信情况（如注册情况、经营能力、信誉等）进行调查。 对由委托人联系的外商，资信调查费用由委托人承担，代理人可以预收。对经调查资信不良的外商，代理人有权停止代理业务。"},{"i":7,"n":"第七条","txt":"代理人必须按照本规定认真履行其职责。进出口代理业务的合同、有关单证的以下项目（栏目），均必须为代理人： （一）进出口合同：对外签约人； （二）进出口许可证：进口商或出口商； （三）进口证明或登记表：对外签订合同单位； （四）海关报关单：经营单位； （五）结汇、购付汇及核销单证：进口单位或出口单位。"},{"i":8,"n":"第八条","txt":"对国家实行进出口许可证管理的商品，一律由代理人负责按规定办理许可证，不得交由委托人（包括配额持有单位）或其他第三方代办。 对国家实行进口证明，进口登记管理的产品，由委托人或由代理人（凭委托人的委托书）按规定办理进口证明、登记表。"},{"i":9,"n":"第九条","txt":"海关报关和纳税手续，由代理人或由代理人委托经海关批准注册的专业报关单位（凭代理人的委托书）按规定办理，不得交由委托人或其他第三方代办。"},{"i":10,"n":"第十条","txt":"海关查验货物时，代理人应到场，或通知委托人到场，接受海关查验。"},{"i":11,"n":"第十一条","txt":"代理人、委托人的外汇收支活动必须按有关外汇管理规定办理。 进口代理业务，一律由代理人负责对外付汇，不得由委托人对外付汇。进口货款由委托人及时向代理人支付。 出口代理业务，一律由代理人负责收汇。委托人为经批准允许保留现汇的企业，代理人凭有关外汇管理法规规定的有效凭证和商业单据将原市划转给委托人；委托人为不允许保留现汇的企业，代理人结汇后将货款按有关规定支付给委托人。"},{"i":12,"n":"第十二条","txt":"代理人要全过程参与和跟踪进出口代理业务和合同执行。 对在执行进出口合同中所出现的问题，代理人应及时与委托人联系。涉及对外索赔、理赔，代理人和委托人应按合同约定，积极处理。 在对外索赔过程中，如委托人拒绝顶付索赔所需费用（指应由委托人承担的），代理人可以自行承担费用和风险，索赔所得归代理人所有。"},{"i":13,"n":"第十三条","txt":"违反本规定从事进出口代理业务，各外经贸主管部门，外汇管理部门不予办理审批、发证。售付汇及其他有关手续。"},{"i":14,"n":"第十四条","txt":"对违反本规定从事进出口代理业务构成走私、违反海关监管规定、逃套汇和骗税、出卖或变相出卖进出口经营权、许可证的，由海关、外汇管理机关、外经贸主管部门分别依据有关法律。法规给予处罚。构成犯罪的，依法追究其刑事责任。"},{"i":15,"n":"第十五条","txt":"本规定自１９９８年１２月１日起施行。"}],"guanyufanqingxiaochanpinfanweitiaozhengchengxudezabe1e5a":[{"i":1,"n":"第一条","txt":"为保证反倾销工作的公平、公正、公开，根据《中华人民共和国反倾销条例》的有关规定，制定本规则。"},{"i":2,"n":"第二条","txt":"根据《中华人民共和国反倾销条例》第十九条、第二十四条、第二十五条、第二十九条、第三十八条的规定，对外贸易经济合作部（以下简称外经贸部）在反倾销立案公告以及反倾销裁定公告（以下简称反倾销公告）中确定反倾销立案调查的产品范围和适用反倾销措施的产品范围（以下简称反倾销产品范围），海关自公告规定之日起实施。"},{"i":3,"n":"第三条","txt":"反倾销公告实施后，反倾销产品范围的调整均需在外经贸部相关对外公告中确定，海关自公告规定之日起实施。"},{"i":4,"n":"第四条","txt":"外经贸部反倾销公告产品范围的调整程序按本规则进行。 反倾销公告产品范围的调整程序包括申请程序和外经贸部受理申请、调查、决定及公告程序。"},{"i":5,"n":"第五条","txt":"申请程序： （一）反倾销立案公告后，有关利害关系方对调查产品范围提出异议，应在公告规定的时间内或经外经贸部同意延长的期限内向外经贸部提出调整调查产品范围的申请。 （二）反倾销初裁公告后，有关利害关系方对适用反倾销措施的产品范围提出异议，应在公告规定的时间内或经外经贸部同意延长的期限内向外经贸部提出调整适用反倾销措施的产品范围的申请。 （三）本规则所称利害关系方是指反倾销申请人、国外生产商、出口商、进口商以及其他有利害关系的组织、个人。 （四）申请应以书面形式提出。"},{"i":6,"n":"第六条","txt":"申请书包括以下内容： （一）申请人名称及其简况，申请调整的产品； （二）要求调整的理由、理由的详细说明及相关证据； （三）申请调整产品的详细描述和说明。产品按如下顺序依次描述：税则号、物理特征、化学特性等，描述至能够体现该产品的唯一性和排他性；上述描述方式无法体现该产品的唯一性和排他性时，需详细说明产品的用途； （四）申请调整的进口产品与国内同类产品异同点的详细描述和说明； （五）国外生产商、出口商、进口商及下游用户； （六）申请人法定代表人或其合法授权人的盖章或签字。"},{"i":7,"n":"第七条","txt":"受理、调查、决定和公告程序： （一）外经贸部对申请人递交的申请书进行核对，对符合第六条要求的申请，予以受理； （二）外经贸部通过问卷、实地核查、听证会等方式对申请内容的真实性进行调查和核查； （三）外经贸部对申请内容的合理性和包括反倾销申请人在内的各利害关系方的利益进行调查，对产品的描述和说明等情况进行核查。必要时，可以聘请专家进行论证； （四）按照上述程序规定，对符合反倾销产品范围调整条件的申请，外经贸部可以对反倾销产品范围进行调整，最迟应在最终裁定公告中对外公布； （五）外经贸部没有收到调整产品范围的申请，根据对利害关系方提交材料的审查，也可以决定调整产品范围。"},{"i":8,"n":"第八条","txt":"涉及有关反倾销复审的，产品范围的调整参照本规则执行。"},{"i":9,"n":"第九条","txt":"本规则由外经贸部负责解释。"},{"i":10,"n":"第十条","txt":"本规则自发布之日起第30天实施。"}],"guanyujingneiqiyechengjiefuwuwaibaoyewuxinxibaohud9c2dba-2":[{"i":1,"n":"第一条","txt":"为促进承接服务外包业务的中国境内企业（以下称接包方）妥善保护保密信息，维护公平竞争环境，促进我国服务外包产业的进一步发展，根据《中华人民共和国合同法》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的承接服务外包业务是指接包方通过合同向境内外的企业、机构、组织或个人（以下称发包方）提供的信息技术外包服务、技术性业务流程外包服务等服务的行为。"},{"i":3,"n":"第三条","txt":"本规定所称保密信息是指符合以下条件的业务资料或数据： （一）接包方在承接服务外包业务过程中从发包方所获取； （二）发包方采取了保密措施且不为公众知悉； （三）接包方根据合同约定应当承担保密义务。"},{"i":4,"n":"第四条","txt":"接包方及其股东、董事、监事、经理和员工不得违反服务外包合同的约定，披露、使用或者允许他人使用其所掌握的发包方的保密信息。"},{"i":5,"n":"第五条","txt":"接包方应成立信息保护机构或指定专职人员负责制定本企业的信息保护规章制度，对保密信息采取合理的、具体的、有效的保密措施，包括： （一）限定涉密人员的范围； （二）对保密信息载体及其存储场所采取技术物理控制，以避免信息被他人不当访问或获取； （三）对保密信息的记录载体进行分级管理； （四）对配方含量和程序步骤等重要信息加密保存或保存于受限区域； （五）对保密信息载体使用密码； （六）对存有保密信息的厂房、车间、办公室等场所限制来访者或者对他们提出保密要求； （七）对存有保密信息的计算机建立有效的网络管理和数据保护措施，建立严格的身份认证和访问授权体系，采用完善的系统备份和故障恢复手段，定期进行安全补丁和病毒库的升级； （八）接包方与发包方约定的其他措施。"},{"i":6,"n":"第六条","txt":"接包方应通过与员工，特别是涉密人员签订保密协议、竞业禁止协议，以及与涉密的第三方人员签订保密协议等措施确保信息安全。"},{"i":7,"n":"第七条","txt":"接包方应当加强对员工的信息安全培训，增强员工的保密意识，避免泄漏保密信息事故的发生。"},{"i":8,"n":"第八条","txt":"鼓励接包方积极借鉴国内外信息安全认证要求、行业最佳实践来制定企业内部信息安全管理体系，并获取国内、国际信息安全认证。"},{"i":9,"n":"第九条","txt":"接包方应积极开展对内部信息安全管理体系的检查及维护，持续改进企业内部信息安全体系。"},{"i":10,"n":"第十条","txt":"接包方违反与发包方之间的保密协议或服务外包合同中的保密条款，发包方可以根据保密协议或服务外包合同的约定提起仲裁或向有管辖权的法院起诉。"},{"i":11,"n":"第十一条","txt":"接包方应与发包方明确约定接包方在为发包方提供服务、履行信息保密义务的过程中所产生的知识产权或技术成果的归属。"},{"i":12,"n":"第十二条","txt":"接包方不得侵犯发包方依法享有的商标、专利、著作权等知识产权权利。"},{"i":13,"n":"第十三条","txt":"相关行业协会等中介组织应加强行业自律管理，可根据需要定期公布接包方的信息保密工作情况。"},{"i":14,"n":"第十四条","txt":"本规定由商务部、工业和信息化部负责解释。"},{"i":15,"n":"第十五条","txt":"本规定自2010年2月1日起施行。"}],"guanyuwaishangtouzijubantouzixinggongsideguiding":[{"i":1,"n":"第一条","txt":"为了促进外国投资者来华投资，引进国外先进技术和管理经验，允许外国投资者根据中国有关外国投资的法律、法规及本规定，在中国设立投资性公司。"},{"i":2,"n":"第二条","txt":"本规定中投资性公司系指外国投资者在中国以独资或与中国投资者合资的形式设立的从事直接投资的公司。公司形式为有限责任公司或股份有限公司。"},{"i":3,"n":"第三条","txt":"申请设立投资性公司应符合下列条件： （一）1、外国投资者资信良好，拥有举办投资性公司所必需的经济实力，申请前一年该投资者的资产总额不低于四亿美元，且该投资者在中国境内已设立了外商投资企业，其实际缴付的注册资本的出资额超过一千万美元，或者；2、外国投资者资信良好，拥有举办投资性公司所必需的经济实力，该投资者在中国境内已设立了十个以上外商投资企业，其实际缴付的注册资本的出资额超过三千万美元； （二）以合资方式设立投资性公司的，中国投资者应为资信良好，拥有举办投资性公司所必需的经济实力，申请前一年该投资者的资产总额不低于一亿元人民币。 申请设立投资性公司的外国投资者应为一家外国的公司、企业或经济组织，若外国投资者为两个以上的，其中应至少有一名占大股权的外国投资者符合本条第一款第（一）项的规定。"},{"i":4,"n":"第四条","txt":"符合本规定第三条第一款第（一）项规定的条件的外国投资者可以其全资拥有的子公司的名义投资设立投资性公司。"},{"i":5,"n":"第五条","txt":"申请设立投资性公司的外国投资者符合本规定第三条第一款第（一）项规定的条件的，该外国投资者须向审批机关出具保证函，保证其所设立的投资性公司在中国境内投资时注册资本的缴付和属于该外国投资者或关联公司的技术转让。 以全资拥有的子公司的名义投资设立投资性公司的，其母公司须向审批机关出具保证函，保证其子公司按照审批机关批准的条件完成对所设立的投资性公司的注册资本的缴付，并保证该投资性公司在中国境内投资时的注册资本的缴付和属于该母公司及其所属公司的技术转让。"},{"i":6,"n":"第六条","txt":"申请设立投资性公司，投资者应将下列文件经拟设立投资性公司所在地的省、自治区、直辖市、计划单列市商务主管部门审核同意后，报商务部审查批准。 （一）设立合资的投资性公司投资各方签署的申请报告、合同、章程； 设立独资的投资性公司外国投资者签署的外资企业申请表、可行性研究报告、章程； （二）投资各方的资信证明文件、注册登记证明文件（复印件）和法定代表人证明文件（复印件）； （三）外国投资者已投资企业的批准证书（复印件）和营业执照（复印件）； （四）依法审计的投资各方近三年的资产负债表； （五）依据本规定第五条应提交的保证函； （六）商务部要求的其他文件。 上述文件除已注明为复印件的，一律应为正式文件。 非法定代表人签署文件的，应出具法定代表人的委托授权书。 委托依法设立的中介机构代为办理申请手续的，应出具由投资者法定代表人签署的委托授权书。"},{"i":7,"n":"第七条","txt":"外国投资者须以可自由兑换的货币或其在中国境内获得的人民币利润或因转股、清算等活动获得的人民币合法收益作为其向投资性公司注册资本的出资。中国投资者可以人民币出资。外国投资者以其人民币合法收益作为其向投资性公司注册资本出资的，应当提交相关证明文件及税务凭证。"},{"i":8,"n":"第八条","txt":"投资性公司的注册资本中至少应有三千万美元作为向其投资新设立的外商投资企业的出资，或作为向其母公司或关联公司已投资设立外商投资企业（已依法办理完毕股权转让手续）未缴付完毕的出资额的出资，或增资部分的出资，或用于设立研发中心等机构的投资，或用于购买中国境内公司股东的股权（不包括投资性公司母公司或其关联公司已缴付完毕的出资额形成的股权）。"},{"i":9,"n":"第九条","txt":"投资性公司的注册资本不低于三千万美元，其贷款额不得超过已缴付注册资本额的四倍。投资性公司的注册资本不低于一亿美元，其贷款额不得超过已缴付注册资本额的六倍。投资性公司因经营需要，贷款额拟超过上述规定，应当报商务部批准。"},{"i":10,"n":"第十条","txt":"投资性公司经商务部批准设立后，可以依其在中国从事经营活动的实际需要，经营下列业务： （一）在国家允许外商投资的领域依法进行投资； （二）受其所投资企业的书面委托（经董事会一致通过），向其所投资企业提供下列服务： 1、协助或代理其所投资的企业从国内外采购该企业自用的机器设备、办公设备和生产所需的原材料、元器件、零部件和在国内外销售其所投资企业生产的产品，并提供售后服务； 2、在外汇管理部门的同意和监督下，在其所投资企业之间平衡外汇； 3、为其所投资企业提供产品生产、销售和市场开发过程中的技术支持、员工培训、企业内部人事管理等服务； 4、协助其所投资企业寻求贷款及提供担保。 （三）在中国境内设立科研开发中心或部门，从事新产品及高新技术的研究开发，转让其研究开发成果，并提供相应的技术服务； （四）为其投资者提供咨询服务，为其关联公司提供与其投资有关的市场信息、投资政策等咨询服务； （五）承接"},{"i":11,"n":"第十一条","txt":"投资性公司从事货物进出口或者技术进出口的,应符合商务部《对外贸易经营者备案登记办法》的规定。 投资性公司从事佣金代理、批发、零售和特许经营活动的，应符合商务部《外商投资商业领域管理办法》的相关规定，并依法变更相应的经营范围。"},{"i":12,"n":"第十二条","txt":"本规定所称投资性公司所投资企业系指符合下列条件的企业： （一）投资性公司直接投资或与其他外国投资者和/或中国投资者共同投资，投资性公司中折算出的外国投资者的投资单独或与其他外国投资者一起投资的比例占其所投资设立企业注册资本的25％以上的企业； （二）投资性公司将其投资者或其关联公司、其他外国投资者以及中国境内投资者在中国境内已投资设立的企业的股权部分或全部收购，投资性公司中折算出的外国投资者的投资单独或与其他外国投资者的投资额共同占该已设立企业的注册资本25％以上的企业； （三）投资性公司的投资额不低于其所投资设立企业的注册资本的10％。"},{"i":13,"n":"第十三条","txt":"经中国银行业监督管理委员会批准，投资性公司可向其所投资设立的企业提供财务支持。"},{"i":14,"n":"第十四条","txt":"投资性公司可以作为发起人发起设立外商投资股份有限公司或持有外商投资股份有限公司未上市流通的法人股。投资性公司也可以根据国家有关规定持有境内其他股份有限公司未上市流通的法人股。投资性公司应视为股份有限公司境外发起人或股东。"},{"i":15,"n":"第十五条","txt":"投资性公司设立后，依法经营，无违法纪录，注册资本按照章程的规定按期缴付，投资者实际缴付的注册资本额不低于三千万美元且已用于本规定第八条所规定的用途，投资性公司经所在地的省、自治区、直辖市或计划单列市商务主管部门审核同意，向商务部提出申请，并获批准的，还可依其在中国从事经营活动的实际需要，依照国家有关规定，经营下列业务： （一）受所投资企业的书面委托（经董事会一致通过），开展下列业务： 1、在国内外市场以经销的方式销售其所投资企业生产的产品； 2、为其所投资企业提供运输、仓储等综合服务。 （二）以代理、经销或设立出口采购机构（包括内部机构）的方式出口境内商品，并可按有关规定办理出口退税； （三）购买所投资企业生产的产品进行系统集成后在国内外销售，如所投资企业生产的产品不能完全满足系统集成需要，允许其在国内外采购系统集成配套产品，但所购买的系统集成配套产品的价值不应超过系统集成所需全部产品"},{"i":16,"n":"第十六条","txt":"投资性公司根据第十五条第三款和第五款规定进口产品应依照国家有关规定办理手续。上述进口金额每年累计不超过公司已缴付的注册资本额。"},{"i":17,"n":"第十七条","txt":"投资性公司申请经营本规定第十五条规定业务的，应当向商务部报送下列文件： （一）投资性公司法定代表人签署的申请书； （二）投资性公司董事会决议； （三）修改后的投资性公司章程； （四）投资性公司的批准证书（复印件）和营业执照（复印件）； （五）商务部要求的其他文件。"},{"i":18,"n":"第十八条","txt":"根据投资性公司拟设立的项目性质，按照国家有关外商投资企业经营期限的规定核定投资性公司的期限。"},{"i":19,"n":"第十九条","txt":"投资性公司投资设立企业，按外商投资企业的审批权限及审批程序另行报批。"},{"i":20,"n":"第二十条","txt":"投资性公司投资设立企业，投资性公司中折算出的外国投资者的投资单独或与其他外国投资者一起投资的比例一般不低于其所投资设立企业的注册资本的25％，其投资设立的企业享受外商投资企业待遇，发给外商投资企业批准证书和外商投资企业营业执照；出资比例低于25%的，除法律、行政法规另有规定外，均应按照现行设立外商投资企业的审批登记程序进行审批和登记。"},{"i":21,"n":"第二十一条","txt":"投资性公司设立分支机构应报商务部审批。投资性公司申请设立分公司，必须符合以下条件： （一）投资性公司的注册资本已按照合同、章程的规定按期缴付并且已缴付的出资额不低于三千万美元；或投资性公司已投资设立或拥有十个以上外商投资企业； （二）拟设立分公司的地区应为投资性公司投资集中地区或产品销售集中的地区。"},{"i":22,"n":"第二十二条","txt":"符合条件的投资性公司可申请被认定为跨国公司地区总部（以下简称地区总部），并依法办理变更手续。 （一）投资性公司申请被认定为地区总部应符合下列条件： 1、已缴付注册资本不低于一亿美元，或者；已缴付注册资本不低于五千万美元，申请前一年其所投资企业资产总额不低于三十亿人民币，且利润总额不低于一亿元人民币（按合并报表相关规定计）； 2、符合本规定第八条的规定； 3、根据有关规定，已设立研发机构。 （二）被认定为地区总部的投资性公司，可依其在中国从事经营活动的实际需要，经营下列业务： 1、本规定第十条、第十五条所规定的业务； 2、进口并在国内销售（不含零售）跨国公司及其控股的关联公司的产品； 3、进口为所投资企业、跨国公司的产品提供维修服务所需的原辅材料及零、配件； 4、承接境内外企业的服务外包业务； 5、根据有关规定，从事物流配送服务； 6、经中国银行业监督管理委员会批准，设立财务公司，向投资"},{"i":23,"n":"第二十三条","txt":"投资性公司在中国境内的投资活动不受公司注册地点的限制。"},{"i":24,"n":"第二十四条","txt":"投资性公司的税收按中国有关法律、法规办理。"},{"i":25,"n":"第二十五条","txt":"投资性公司应切实履行项目投资计划，并将第一年度的投资、经营情况于下一年度的前三个月内，按照规定的内容和格式报商务部备案。"},{"i":26,"n":"第二十六条","txt":"投资性公司与其所投资设立的企业是彼此独立的法人或实体，其业务往来应按独立企业之间业务往来关系处理。"},{"i":27,"n":"第二十七条","txt":"投资性公司与其投资设立的企业应遵守中国的法律、法规和规章，不得采用任何手段逃避管理和纳税。"},{"i":28,"n":"第二十八条","txt":"投资性公司不得直接从事生产活动。"},{"i":29,"n":"第二十九条","txt":"台湾、香港和澳门地区的投资者在大陆投资举办投资性公司的，准用本规定。"},{"i":30,"n":"第三十条","txt":"本规定由商务部负责解释。"},{"i":31,"n":"第三十一条","txt":"本规定自公布之日(2004年11月17日）起三十日后施行。"}],"guanyuwaishangtouziqiyehebingyufenlideguiding":[{"i":1,"n":"第一条","txt":"为了规范涉及外商投资企业合并与分立的行为，保护企业投资者和债权人的合法权益，根据《中华人民共和国公司法》和有关外商投资企业的法律和行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于依照中国法律在中国境内设立的中外合资经营企业、具有法人资格的中外合作经营企业、外资企业、外商投资股份有限公司(以下统称公司)之间合并或分立。 公司与中国内资企业合并，参照有关法律、法规和本规定办理。"},{"i":3,"n":"第三条","txt":"本规定所称合并，是指两个以上公司依照公司法有关规定，通过订立协议而归并成为一个公司。 公司合并可以采取吸收合并和新设合并两种形式。 吸收合并，是指公司接纳其他公司加入本公司，接纳方继续存在，加入方解散。 新设合并，是指两个以上公司合并设立一个新的公司，合并各方解散。"},{"i":4,"n":"第四条","txt":"本规定所称分立，是指一个公司依照公司法有关规定，通过公司最高权力机构决议分成两个以上的公司。 公司分立可以采取存续分立和解散分立两种形式。 存续分立，是指一个公司分离成两个以上公司，本公司继续存在并设立一个以上新的公司。 解散分立，是指一个公司分解为两个以上公司，本公司解散并设立两个以上新的公司。"},{"i":5,"n":"第五条","txt":"公司合并或分立，应当遵守中国的法律、法规和本规定，遵循自愿、平等和公平竞争的原则，不得损害社会公共利益和债权人的合法权益。 公司合并或分立，应符合《指导外商投资方向暂行规定》和《外商投资产业指导目录》的规定，不得导致外国投资者在不允许外商独资、控股或占主导地位的产业的公司中独资、控股或占主导地位。 公司因合并或分立而导致其所从事的行业或经营范围发生变更的，应符合有关法律、法规及国家产业政策的规定并办理必要的审批手续。"},{"i":6,"n":"第六条","txt":"公司合并或分立，应当符合海关、税务和外汇管理等有关部门颁布的规定。合并或分立后存续或新设的公司，经审批机关、海关和税务等机关核定，继续享受原公司所享受的各项外商投资企业待遇。"},{"i":7,"n":"第七条","txt":"公司合并或分立，须经公司原审批机关批准并到登记机关办理有关公司设立、变更或注销登记。 拟合并公司的原审批机关或登记机关有两个以上的，由合并后公司住所地对外经济贸易主管部门和国家工商行政管理总局(以下简称国家工商总局)授权的登记机关作为审批和登记机关。 拟合并公司的投资总额之和超过公司原审批机关或合并后公司住所地审批机关审批权限的，由具有相应权限的审批机关审批。 拟合并的公司至少有一家为股份有限公司的，由中华人民共和国对外贸易经济合作部(以下简称外经贸部)审批。"},{"i":8,"n":"第八条","txt":"因公司合并或分立而解散原公司或新设异地公司，须征求拟解散或拟设立公司的所在地审批机关的意见。"},{"i":9,"n":"第九条","txt":"有限责任公司之间合并后为有限责任公司。股份有限公司之间合并后为股份有限公司。 上市的股份有限公司与有限责任公司合并后为股份有限公司。非上市的股份有限公司与有限责任公司合并后可以是股份有限公司，也可以是有限责任公司。"},{"i":10,"n":"第十条","txt":"股份有限公司之间合并或者公司合并后为有限责任公司的，合并后公司的注册资本为原公司注册资本额之和。 有限责任公司与股份有限公司合并后为股份有限公司的，合并后公司的注册资本为原有限责任公司净资产额根据拟合并的股份有限公司每股所含净资产额折成的股份额与原股份有限公司股份总额之和。"},{"i":11,"n":"第十一条","txt":"根据本规定第十条第一款合并的，各方投资者在合并后的公司中的股权比例，根据国家有关规定，由投资者之间协商或根据资产评估机构对其在原公司股权价值的评估结果，在合并后的公司合同、章程中确定，但外国投资者的股权比例不得低于合并后公司注册资本的百分之二十五。"},{"i":12,"n":"第十二条","txt":"分立后公司的注册资本额，由分立前公司的最高权力机构，依照有关外商投资企业法律、法规和登记机关的有关规定确定，但分立后各公司的注册资本额之和应为分立前公司的注册资本额。"},{"i":13,"n":"第十三条","txt":"各方投资者在分立后的公司中的股权比例，由投资者在分立后的公司合同、章程中确定，但外国投资者的股权比例不得低于分立后公司注册资本的百分之二十五。"},{"i":14,"n":"第十四条","txt":"公司合并，采取吸收合并形式的，接纳方公司的成立日期为合并后公司的成立日期；采取新设合并形式的，登记机关核准设立登记并签发营业执照的日期为合并后公司的成立日期。 因公司分立而设立新公司的，登记机关核准设立登记并签发营业执照的日期为分立后公司的成立日期。"},{"i":15,"n":"第十五条","txt":"涉及上市的股份有限公司合并或分立的，应当符合有关法律、法规和国务院证券监督管理部门对上市公司的规定并办理必要的审批手续。"},{"i":16,"n":"第十六条","txt":"公司与中国内资企业合并必须符合我国利用外资的法律、法规规定和产业政策要求并具备以下条件： (一)拟合并的中国内资企业是依照《中华人民共和国公司法》规范组建的有限责任公司或股份有限公司； (二)投资者符合法律、法规和部门规章对合并后公司所从事有关产业的投资者资格要求； (三)外国投资者的股权比例不得低于合并后公司注册资本的百分之二十五； (四)合并协议各方保证拟合并公司的原有职工充分就业或给予合理安置。"},{"i":17,"n":"第十七条","txt":"公司与中国内资企业合并后为外商投资企业，其投资总额为原公司的投资总额与中国内资企业财务审计报告所记载的企业资产总额之和，注册资本为原公司的注册资本额与中国内资企业的注册资本额之和。合并后的公司注册资本与投资总额比例，应当符合国家工商总局《关于中外合资经营企业注册资本与投资总额比例的暂行规定》；在特殊情况下，不能执行该规定的，须经外经贸部会同国家工商总局批准。"},{"i":18,"n":"第十八条","txt":"与公司合并的中国内资企业已经投资设立的企业，成为合并后公司所持股的企业，应当符合中国利用外资的产业政策要求和《关于外商投资企业境内投资的暂行规定》。合并后的公司不得在禁止外商投资产业的企业中持有股权。"},{"i":19,"n":"第十九条","txt":"公司吸收合并，由接纳方公司作为申请人，公司新设合并，由合并各方协商确定一个申请人。 申请人应向审批机关报送下列文件： (一)各公司法定代表人签署的关于公司合并的申请书和公司合并协议； (二)各公司最高权力机构关于公司合并的决议； (三)各公司合同、章程； (四)各公司的批准证书和营业执照复印件； (五) 各公司的资产负债表及财产清单； (六) 各公司上一年度的审计报告； (七) 各公司的债权人名单； (八) 合并后的公司合同、章程； (九) 合并后的公司最高权力机构成员名单； (十) 审批机关要求报送的其他文件。 公司与中国内资企业合并的，申请人还应向审批机关报送拟合并的中国内资企业已投资设立企业的营业执照复印件。"},{"i":20,"n":"第二十条","txt":"公司合并协议应包括下列主要内容： (一)合并协议各方的名称、住所、法定代表人； (二)合并后公司的名称、住所、法定代表人； (三)合并后公司的投资总额和注册资本； (四)合并形式； (五)合并协议各方债权、债务的承继方案； (六)职工安置办法； (七)违约责任； (八)解决争议的方式； (九)签约日期、地点； (十)合并协议各方认为需要规定的其他事项。"},{"i":21,"n":"第二十一条","txt":"拟合并的公司有两个以上原审批机关的，拟解散的公司应当在依照本规定第十九条向审批机关报送有关文件之前，向其原审批机关提交因公司合并而解散的申请。 原审批机关应自接到前款有关解散申请之日起十五日内做出是否同意解散的批复。超过十五日，原审批机关未作批复的，视作原审批机关同意该公司解散。 如果原审批机关在前款规定期限内，作出不同意有关公司解散的批复，拟解散公司可将有关解散申请提交原审批机关与公司合并的审批机关共同的上一级对外经济贸易主管部门，该部门应自接到有关公司解散申请之日起三十日内作出裁决。 如果审批机关不同意或不批准公司合并，则有关公司解散的批复自行失效。"},{"i":22,"n":"第二十二条","txt":"拟分立的公司应向审批机关报送下列文件： (一)公司法定代表人签署的关于公司分立的申请书； (二)公司最高权力机构关于公司分立的决议； (三)因公司分立而拟存续、新设的公司(以下统称分立协议各方)签订的公司分立协议； (四)公司合同、章程； (五)公司的批准证书和营业执照复印件； (六) 公司的资产负债表及财产清单； (七) 公司的债权人名单； (八) 分立后的各公司合同、章程； (九) 分立后的各公司最高权力机构成员名单； (十) 审批机关要求报送的其他文件。 因公司分立而在异地新设公司的，公司还必须向审批机关报送拟设立公司的所在地审批机关对因分立而新设公司签署的意见。"},{"i":23,"n":"第二十三条","txt":"公司分立协议应包括下列主要内容： (一)分立协议各方拟定的名称、住所、法定代表人； (二)分立后公司的投资总额和注册资本； (三)分立形式； (四)分立协议各方对拟分立公司财产的分割方案； (五)分立协议各方对拟分立公司债权、债务的承继方案； (六)职工安置办法； (七)违约责任； (八)解决争议的方式； (九)签约日期、地点； (十)分立协议各方认为需要规定的其他事项。"},{"i":24,"n":"第二十四条","txt":"合并后存续的公司或者新设的公司全部承继因合并而解散的公司的债权、债务。 分立后的公司按照分立协议承继原公司的债权、债务。"},{"i":25,"n":"第二十五条","txt":"审批机关应自接到本规定第十九条或第二十二条规定报送的有关文件之日起四十五日内，以书面形式作出是否同意合并或分立的初步批复。 公司合并的审批机关为外经贸部的，如果外经贸部认为公司合并具有行业垄断的趋势或者可能形成就某种特定商品或服务的市场控制地位而妨碍公平竞争，可于接到前款所述有关文件后，召集有关部门和机构，对拟合并的公司进行听证并对该公司及其相关市场进行调查。前款所述审批期限可延长至一百八十天。"},{"i":26,"n":"第二十六条","txt":"拟合并或分立的公司应当自审批机关就同意公司合并或分立作出初步批复之日起十日内，向债权人发出通知书，并于三十日内在全国发行的省级以上报纸上至少公告三次。 公司应在上述通知书和公告中说明对现有公司债务的承继方案。"},{"i":27,"n":"第二十七条","txt":"公司债权人自接到本规定第二十六条所述通知书之日起三十日内、未接到通知书的债权人自第一次公告之日起九十日内，有权要求公司对其债务承继方案进行修改，或者要求公司清偿债务或提供相应的担保。 如果公司债权人未在前款规定期限内行使有关权利，视为债权人同意拟合并或分立公司的债权、债务承继方案，该债权人的主张不得影响公司的合并或分立进程。"},{"i":28,"n":"第二十八条","txt":"拟合并或分立的公司自第一次公告之日起九十日后，公司债权人无异议的，拟合并公司的申请人或拟分立的公司应向审批机关提交下列文件： (一)公司在报纸上三次登载公司合并或分立公告的证明； (二)公司通知其债权人的证明； (三)公司就其有关债权、债务处理情况的说明； (四)审批机关要求提交的其他文件。"},{"i":29,"n":"第二十九条","txt":"审批机关应自接到本规定第二十八条所列文件之日起三十日内，决定是否批准公司合并或分立。"},{"i":30,"n":"第三十条","txt":"公司采取吸收合并形式的，接纳方公司应到原审批机关办理外商投资企业批准证书变更手续并到登记机关办理公司变更登记；加入方公司应到原审批机关缴销外商投资企业批准证书并到登记机关办理公司注销登记。 公司采取新设合并形式的，合并各方公司应到原审批机关缴销外商投资企业批准证书并到登记机关办理公司注销登记；新设立的公司应通过申请人到审批机关领取外商投资企业批准证书并到登记机关办理公司设立登记。 公司采取存续分立形式的，存续的公司应到审批机关办理外商投资企业批准证书变更手续并到登记机关办理公司变更登记；新设立的公司应到审批机关领取外商投资企业批准证书并到登记机关办理公司设立登记。 公司采取解散分立形式的，原公司应到原审批机关缴销外商投资企业批准证书并到登记机关办理公司注销登记；新设立的公司应到审批机关领取外商投资企业批准证书并到登记机关办理公司设立登记。 公司与中国内资企业合并的仅由公司办理有关外商投"},{"i":31,"n":"第三十一条","txt":"公司合并的申请人或拟分立的公司，应自审批机关批准合并或分立之日起三十日内，就因合并或分立而解散、存续或新设公司的事宜，到相应的审批机关办理有关缴销、变更或领取外商投资企业批准证书手续。"},{"i":32,"n":"第三十二条","txt":"公司应自缴销、变更或领取外商投资企业批准证书之日起，依照《中华人民共和国企业法人登记管理条例》和《中华人民共和国公司登记管理条例》等有关规定，到登记机关办理有关注销、变更或设立登记手续。 设立登记应当在有关公司变更、注销登记办理完结后进行。 公司合并或分立协议中载明的有关公司财产处置方案及债权、债务承继方案和审批机关批准公司合并或分立的文件，视为注销登记所需提交的清算报告。"},{"i":33,"n":"第三十三条","txt":"公司为新设合并或分立办理注销、变更登记后，当事人不依法办理有关公司设立登记的，应承担相应的法律责任。"},{"i":34,"n":"第三十四条","txt":"公司投资者因公司合并或分立而签署的修改后的公司合同、章程自审批机关变更或核发外商投资企业批准证书之日起生效。"},{"i":35,"n":"第三十五条","txt":"合并或分立后存续或新设的公司应自变更或领取营业执照之日起三十日内，向因合并或分立而解散的公司之债权人和债务人发出变更债务人和债权人的通知并在全国发行的省级以上报纸上公告。"},{"i":36,"n":"第三十六条","txt":"合并或分立后存续或新设的公司应自换发或领取营业执照之日起三十日内，到税务、海关、土地管理和外汇管理等有关机关办理相应的登记手续。 公司与中国内资企业合并的，存续或新设的公司，还应根据有关外商投资企业的规定，到税务、海关、土地管理和外汇管理等机关，办理相关的审核手续。"},{"i":37,"n":"第三十七条","txt":"在公司合并或分立过程中发生股权转让的，依照有关法律、法规和外商投资企业投资者股权变更的规定办理。 在公司与中国内资企业合并过程中，外国投资者购买内资企业股东股权的，其股权购买金的支付条件，依照《<中外合资经营企业合营各方出资的若干规定>的补充规定》执行。"},{"i":38,"n":"第三十八条","txt":"香港、澳门、台湾地区的投资者在中国其他地区投资举办的公司合并或分立，参照本规定办理。"},{"i":39,"n":"第三十九条","txt":"本规定由外经贸部和国家工商总局负责解释。"},{"i":40,"n":"第四十条","txt":"本规定自发布之日起执行。"}],"guanyuwaishangtouziqiyejingneitouzidezanxingguidina32171":[{"i":1,"n":"第一条","txt":"为规范外商投资企业的投资行为，根据《中华人民共和国公司法》(以下简称\"《公司法》\")以及有关外商投资的法律、法规的有关规定，制订本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外商投资企业境内投资，是指在中国境内依法设立，采取有限责任公司形式的中外合资经营企业、中外合作经营企业和外资企业以 及外商投资股份有限公司，以本企业的名义，在中国境内投资设立企业或购买其他企业(以下简称\"被投资公司\")投资者股权的行为。 外商投资举办的投资性公司境内投资，依照国家有关外商投资的法律、法规以及《关于外商投资举办投资性公司的暂行规定》办理。 外国投资者与外商投资企业共同在中国境内投资，按照国家有关外商投资的法律、法规办理，其中外国投资者的出资比例一般不得低于被投资企业注册资本的百分之二十五。"},{"i":3,"n":"第三条","txt":"外商投资企业境内投资，应遵守国家法律、法规。 外商投资企业境内投资比照执行《指导外商投资方向暂行规定》和《外商投资产业指导目录》的规定。外商投资企业不得在禁止外商投资的领域投资。"},{"i":4,"n":"第四条","txt":"被投资公司应为有限责任公司或股份有限公司。"},{"i":5,"n":"第五条","txt":"外商投资企业应符合下列条件，方可投资： 1．开始盈利； 2．依法经营，无违法经营记录。"},{"i":6,"n":"第六条","txt":"外商投资企业在鼓励类或允许类领域投资设立公司，应向被投资公司所在地公司登记机关提出申请，并应提供下列材料： 1．外商投资企业关于投资 的一致通过的董事会决议； 2．外商投资企业的批准证书和营业执照(复印件)； 3．外商投资企业经审计的资产负债表； 4．外商投资企业缴纳所得税或减免所得税的证明材料； 5．法律、法规及规章规定的 其他材料。"},{"i":7,"n":"第七条","txt":"公司登记机关依《公司法》、《中华人民共和国 公司登记管理条例》(以下简称《公司登记管理条例》)的有关规定，决定准予登记或不予登 记。准予登记的，发给《企业法人营业执照》，并在企业类别栏目加注\"外商投资企业投资 \"字样(以下简称\"《(加注)营业执照》\")。"},{"i":8,"n":"第八条","txt":"外商投资企业在限制类领域投资设立公司的，应向被投资公司所在地省级外经贸主管部门(以下称\"省级审 批机关\")提出申请，并应提供下列材料： 1．依照第六条规定提供的材料； 2．被投资公司的章程。 被投资公司的章程应当载明下列事项： (1)公司名称和住所； (2)公司经营范围及产品国内外销售比例； (3)公司注册资本； (4)投资者的名称或姓名； (5)投资者的权利和义务； (6)投资者的出资方式和出资额； (7)投资者转让出资的条件； (8)公司的机构及其产生办法、职权、议事规则； (9)公司的法定代表人； (10)公司的解散事由与清算办法； (11)投资者认为需要规定的其他事项。 投资者应当在公司章程上签名、盖章。"},{"i":9,"n":"第九条","txt":"省级审批机关接到上述申请后，按照被投资公司的经营范围，征求同级或国家行业管理部门的意见。 省级审批机关应自收到同级或国家管理 行业部门同意或不同意的意见起十日之内，作出书面批复。"},{"i":10,"n":"第十条","txt":"省级审批机关对外商投资企业作出同意批复的，外商投资企业凭该批复文件向被投资公司 所在地公司登记机关申请设立登记。 公司登记机关依《公司登记管理条例》的有关规定， 决定准予登记或不予登记。准予登记的，发给《(加注)营业执照》。"},{"i":11,"n":"第十一条","txt":"自被投资公司设立之日起三十日内，外商投资企业应向原审批机关备案。备案材料包括： 1．外商投资企业投资备案表； 2．被投资公司的营业执照(复印件)； 3．被投资公司经营范围涉及限制类领域的，还应提交省级审批机关作出的同意设立被投资公司的批复。"},{"i":12,"n":"第十二条","txt":"外商投资企业以其固定资产投资而改变原经营规模或内容的，投资前应向原审批机关申请并征得原审批机关的同意。 原审批机关应自接到申 请之日起十五日之内予以答复；逾期不答复的，视作同意。 原审批机关不同意的，外商投资企业可向其上级审批机关或对外贸易经济合作部(以下简称\"外经贸部\")提出申诉。该上级审批机关或外经贸部应自收到申诉之日起三十日内，对外商投资企业作出书面答复。"},{"i":13,"n":"第十三条","txt":"按照本规定第六条、第七条设立的公司变更经营范围，涉及 限制类领域的，应按照本规定第八条、第九条规定的程序办理，并向其原公司登记机关申请变更登记。"},{"i":14,"n":"第十四条","txt":"外商投资企业购买被投资公司投资者的股权，被投资公司经营范围属于鼓励类或允许类领域的，被投资公司应向原公司登记机关报送本规定第六条所列的材料，并按照《公司登记管理条例》等有关规定，申请变更登记。 被投资公司经营范围涉及限制类领域的，外商投资企业应按照本规定第八条、第九条规定的程序办理后，被投资公司凭省级审批机关的同意批复，按照《公司登记管理条例》等有关规定，向原公司登记机关申请变更登记。 公司登记机关依《公司登记管理条例》的有关规定，决定予以登记或不予登记。准予登记的，发给\"（加注）营业执照\"。 被投资公司属于外商投资企业的，按照《外商投资企业投资者股权变更的规定》办理。"},{"i":15,"n":"第十五条","txt":"外商投资企业向中西部地区投资，被投资公司注册资本中外资比例不低于百分之二十五 的，可享受外商投资企业待遇。"},{"i":16,"n":"第十六条","txt":"被投资公司享受外商投资 企业待遇，应按有关外商投资企业设立程序的规定，向被投资公司所在地的省级审批机关提出申请。申请人应提供下列材料： 1．依照第六条规定应提供的材料； 2．被投资公司的名称、住所； 3．被投资公司的投资合同及章程； 4．被投资公司经营范围涉及限制类领域的，还应提交设立被投资公司的项目建议书和可行性研究报告。 其投资者出让股权的被 投资公司享受外商投资企业待遇的，申请人除向被投资公司所在地的省级审批机关提供上款所列材料之外，还应提交相应的投资者股权转让协议。"},{"i":17,"n":"第十七条","txt":"省级审批机关确认外商投资企业的投资符合国家有关法律、法规且被投资公司注册资本中外资比例不低于百分之二十五的，向申请人下发批准文件，颁发《外商投资企业批准证书》，并 加注\"外商投资企业投资\"字样。 被投资公司经营范围涉及限制类领域的，省级审批机关批准之前，应依照本规定第九条的规定，征求有关行业管理部门的意见。"},{"i":18,"n":"第十八条","txt":"申请人凭《外商投资企业批准证书》向被投资公司所在地公司登记机关申请登记注册。 公司登记机关依《公司登记管理条例》的有关规定，决定准予登记或不予登记。准予登记的，发给《(加注)营业执照》。 被投资公司经营范围未涉及限制类领域的，按本规定第六条办理。"},{"i":19,"n":"第十九条","txt":"中西部地区的被投资公司凭《外商投 资企业批准证书》和《(加注)营业执照》享受国家法律、法规规定的外商投资企业待遇。"},{"i":20,"n":"第二十条","txt":"在中西部地区设立的被投资公司投资总额超过其所在省、自治区、直辖市审批机关审批权限的，应报外经贸部审批。"},{"i":21,"n":"第二十一条","txt":"被投资公司属于法律、法规和部门规章明确规定的应由外经贸部审批的特定类型或行业的外商投资企业的，省级审批机关应将有关申请材料转报外经贸部审批。外经贸部根据有关法律、法规和部门规章的规定决定批准或不批准。"},{"i":22,"n":"第二十二条","txt":"本规定颁布前，根据有关规定已设立的外商投资企业参股企业，符合本规定要求的，可参照本规定补办有关手续，享受外商投资企业待遇。"},{"i":23,"n":"第二十三条","txt":"本规定由外经贸部和国家工商行政管理局负责解释。"},{"i":24,"n":"第二十四条","txt":"本规定自2000年9月1日起施行。"}],"guanyuwaiguotouzizhebinggoujingneiqiyedeguiding":[{"i":1,"n":"第一条","txt":"为了促进和规范外国投资者来华投资，引进国外的先进技术和管理经验，提高利用外资的水平，实现资源的合理配置，保证就业、维护公平竞争和国家经济安全，依据外商投资企业的法律、行政法规及《公司法》和其他相关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外国投资者并购境内企业，系指外国投资者购买境内非外商投资企业（以下称“境内公司”）股东的股权或认购境内公司增资，使该境内公司变更设立为外商投资企业（以下称“股权并购”）；或者，外国投资者设立外商投资企业，并通过该企业协议购买境内企业资产且运营该资产，或，外国投资者协议购买境内企业资产，并以该资产投资设立外商投资企业运营该资产（以下称“资产并购”）。"},{"i":3,"n":"第三条","txt":"外国投资者并购境内企业应遵守中国的法律、行政法规和规章，遵循公平合理、等价有偿、诚实信用的原则，不得造成过度集中、排除或限制竞争，不得扰乱社会经济秩序和损害社会公共利益，不得导致国有资产流失。"},{"i":4,"n":"第四条","txt":"外国投资者并购境内企业，应符合中国法律、行政法规和规章对投资者资格的要求及产业、土地、环保等政策。 依照《外商投资产业指导目录》不允许外国投资者独资经营的产业，并购不得导致外国投资者持有企业的全部股权；需由中方控股或相对控股的产业，该产业的企业被并购后，仍应由中方在企业中占控股或相对控股地位；禁止外国投资者经营的产业，外国投资者不得并购从事该产业的企业。 被并购境内企业原有所投资企业的经营范围应符合有关外商投资产业政策的要求；不符合要求的，应进行调整。"},{"i":5,"n":"第五条","txt":"外国投资者并购境内企业涉及企业国有产权转让和上市公司国有股权管理事宜的，应当遵守国有资产管理的相关规定。"},{"i":6,"n":"第六条","txt":"外国投资者并购境内企业设立外商投资企业，应依照本规定经审批机关批准，向登记管理机关办理变更登记或设立登记。 如果被并购企业为境内上市公司，还应根据《外国投资者对上市公司战略投资管理办法》，向国务院证券监督管理机构办理相关手续。"},{"i":7,"n":"第七条","txt":"外国投资者并购境内企业所涉及的各方当事人应当按照中国税法规定纳税，接受税务机关的监督。"},{"i":8,"n":"第八条","txt":"外国投资者并购境内企业所涉及的各方当事人应遵守中国有关外汇管理的法律和行政法规，及时向外汇管理机关办理各项外汇核准、登记、备案及变更手续。"},{"i":9,"n":"第九条","txt":"外国投资者在并购后所设外商投资企业注册资本中的出资比例高于25％的，该企业享受外商投资企业待遇。 外国投资者在并购后所设外商投资企业注册资本中的出资比例低于25%的，除法律和行政法规另有规定外，该企业不享受外商投资企业待遇，其举借外债按照境内非外商投资企业举借外债的有关规定办理。审批机关向其颁发加注“外资比例低于25%”字样的外商投资企业批准证书（以下称“批准证书”）。登记管理机关、外汇管理机关分别向其颁发加注“外资比例低于25%”字样的外商投资企业营业执照和外汇登记证。 境内公司、企业或自然人以其在境外合法设立或控制的公司名义并购与其有关联关系的境内公司，所设立的外商投资企业不享受外商投资企业待遇，但该境外公司认购境内公司增资，或者该境外公司向并购后所设企业增资，增资额占所设企业注册资本比例达到25%以上的除外。根据该款所述方式设立的外商投资企业，其实际控制人以外的外国投资者在企业注"},{"i":10,"n":"第十条","txt":"本规定所称的审批机关为中华人民共和国商务部或省级商务主管部门(以下称“省级审批机关”)，登记管理机关为中华人民共和国国家工商行政管理总局或其授权的地方工商行政管理局，外汇管理机关为中华人民共和国国家外汇管理局或其分支机构。 并购后所设外商投资企业，根据法律、行政法规和规章的规定，属于应由商务部审批的特定类型或行业的外商投资企业的，省级审批机关应将申请文件转报商务部审批，商务部依法决定批准或不批准。"},{"i":11,"n":"第十一条","txt":"境内公司、企业或自然人以其在境外合法设立或控制的公司名义并购与其有关联关系的境内的公司，应报商务部审批。 当事人不得以外商投资企业境内投资或其他方式规避前述要求。"},{"i":12,"n":"第十二条","txt":"外国投资者并购境内企业并取得实际控制权，涉及重点行业、存在影响或可能影响国家经济安全因素或者导致拥有驰名商标或中华老字号的境内企业实际控制权转移的，当事人应就此向商务部进行申报。 当事人未予申报，但其并购行为对国家经济安全造成或可能造成重大影响的，商务部可以会同相关部门要求当事人终止交易或采取转让相关股权、资产或其他有效措施，以消除并购行为对国家经济安全的影响。"},{"i":13,"n":"第十三条","txt":"外国投资者股权并购的，并购后所设外商投资企业承继被并购境内公司的债权和债务。 外国投资者资产并购的，出售资产的境内企业承担其原有的债权和债务。 外国投资者、被并购境内企业、债权人及其他当事人可以对被并购境内企业的债权债务的处置另行达成协议，但是该协议不得损害第三人利益和社会公共利益。债权债务的处置协议应报送审批机关。 出售资产的境内企业应当在投资者向审批机关报送申请文件之前至少15日，向债权人发出通知书，并在全国发行的省级以上报纸上发布公告。"},{"i":14,"n":"第十四条","txt":"并购当事人应以资产评估机构对拟转让的股权价值或拟出售资产的评估结果作为确定交易价格的依据。并购当事人可以约定在中国境内依法设立的资产评估机构。资产评估应采用国际通行的评估方法。禁止以明显低于评估结果的价格转让股权或出售资产，变相向境外转移资本。 外国投资者并购境内企业，导致以国有资产投资形成的股权变更或国有资产产权转移时，应当符合国有资产管理的有关规定。"},{"i":15,"n":"第十五条","txt":"并购当事人应对并购各方是否存在关联关系进行说明，如果有两方属于同一个实际控制人，则当事人应向审批机关披露其实际控制人，并就并购目的和评估结果是否符合市场公允价值进行解释。当事人不得以信托、代持或其他方式规避前述要求。"},{"i":16,"n":"第十六条","txt":"外国投资者并购境内企业设立外商投资企业，外国投资者应自外商投资企业营业执照颁发之日起3个月内向转让股权的股东，或出售资产的境内企业支付全部对价。对特殊情况需要延长者，经审批机关批准后，应自外商投资企业营业执照颁发之日起6个月内支付全部对价的60%以上，1年内付清全部对价，并按实际缴付的出资比例分配收益。 外国投资者认购境内公司增资，有限责任公司和以发起方式设立的境内股份有限公司的股东应当在公司申请外商投资企业营业执照时缴付不低于20%的新增注册资本，其余部分的出资时间应符合《公司法》、有关外商投资的法律和《公司登记管理条例》的规定。其他法律和行政法规另有规定的，从其规定。股份有限公司为增加注册资本发行新股时，股东认购新股，依照设立股份有限公司缴纳股款的有关规定执行。 外国投资者资产并购的，投资者应在拟设立的外商投资企业合同、章程中规定出资期限。设立外商投资企业，并通过该企业协议购买境内"},{"i":17,"n":"第十七条","txt":"作为并购对价的支付手段，应符合国家有关法律和行政法规的规定。外国投资者以其合法拥有的人民币资产作为支付手段的，应经外汇管理机关核准。外国投资者以其拥有处置权的股权作为支付手段的，按照本规定第四章办理。"},{"i":18,"n":"第十八条","txt":"外国投资者协议购买境内公司股东的股权，境内公司变更设立为外商投资企业后，该外商投资企业的注册资本为原境内公司注册资本，外国投资者的出资比例为其所购买股权在原注册资本中所占比例。 外国投资者认购境内有限责任公司增资的，并购后所设外商投资企业的注册资本为原境内公司注册资本与增资额之和。外国投资者与被并购境内公司原其他股东，在境内公司资产评估的基础上，确定各自在外商投资企业注册资本中的出资比例。 外国投资者认购境内股份有限公司增资的，按照《公司法》有关规定确定注册资本。"},{"i":19,"n":"第十九条","txt":"外国投资者股权并购的，除国家另有规定外，对并购后所设外商投资企业应按照以下比例确定投资总额的上限： （一） 注册资本在210万美元以下的，投资总额不得超过注册资本的10/7； （二） 注册资本在210万美元以上至500万美元的，投资总额不得超过注册资本的2倍； （三） 注册资本在500万美元以上至1200万美元的，投资总额不得超过注册资本的2.5倍； （四） 注册资本在1200万美元以上的，投资总额不得超过注册资本的3倍。"},{"i":20,"n":"第二十条","txt":"外国投资者资产并购的，应根据购买资产的交易价格和实际生产经营规模确定拟设立的外商投资企业的投资总额。拟设立的外商投资企业的注册资本与投资总额的比例应符合有关规定。"},{"i":21,"n":"第二十一条","txt":"外国投资者股权并购的，投资者应根据并购后所设外商投资企业的投资总额、企业类型及所从事的行业，依照设立外商投资企业的法律、行政法规和规章的规定，向具有相应审批权限的审批机关报送下列文件： （一） 被并购境内有限责任公司股东一致同意外国投资者股权并购的决议，或被并购境内股份有限公司同意外国投资者股权并购的股东大会决议； （二） 被并购境内公司依法变更设立为外商投资企业的申请书； （三） 并购后所设外商投资企业的合同、章程； （四） 外国投资者购买境内公司股东股权或认购境内公司增资的协议； （五） 被并购境内公司上一财务年度的财务审计报告； （六） 经公证和依法认证的投资者的身份证明文件或注册登记证明及资信证明文件； （七） 被并购境内公司所投资企业的情况说明； （八） 被并购境内公司及其所投资企业的营业执照(副本)； （九） 被并购境内公司职工安置计划； （十） 本规定第十三条、第十四条、"},{"i":22,"n":"第二十二条","txt":"股权购买协议、境内公司增资协议应适用中国法律，并包括以下主要内容： （一） 协议各方的状况，包括名称（姓名），住所，法定代表人姓名、职务、国籍等； （二） 购买股权或认购增资的份额和价款； （三） 协议的履行期限、履行方式； （四） 协议各方的权利、义务； （五） 违约责任、争议解决； （六） 协议签署的时间、地点。"},{"i":23,"n":"第二十三条","txt":"外国投资者资产并购的，投资者应根据拟设立的外商投资企业的投资总额、企业类型及所从事的行业，依照设立外商投资企业的法律、行政法规和规章的规定，向具有相应审批权限的审批机关报送下列文件： （一） 境内企业产权持有人或权力机构同意出售资产的决议； （二） 外商投资企业设立申请书； （三） 拟设立的外商投资企业的合同、章程； （四） 拟设立的外商投资企业与境内企业签署的资产购买协议，或外国投资者与境内企业签署的资产购买协议； （五） 被并购境内企业的章程、营业执照(副本)； （六） 被并购境内企业通知、公告债权人的证明以及债权人是否提出异议的说明； （七） 经公证和依法认证的投资者的身份证明文件或开业证明、有关资信证明文件； （八） 被并购境内企业职工安置计划； （九） 本规定第十三条、第十四条、第十五条要求报送的文件。 依照前款的规定购买并运营境内企业的资产，涉及其他相关政府部门许可的，有关"},{"i":24,"n":"第二十四条","txt":"资产购买协议应适用中国法律，并包括以下主要内容： （一） 协议各方的状况，包括名称（姓名），住所，法定代表人姓名、职务、国籍等； （二） 拟购买资产的清单、价格； （三） 协议的履行期限、履行方式； （四） 协议各方的权利、义务； （五） 违约责任、争议解决； （六） 协议签署的时间、地点。"},{"i":25,"n":"第二十五条","txt":"外国投资者并购境内企业设立外商投资企业，除本规定另有规定外，审批机关应自收到规定报送的全部文件之日起30日内，依法决定批准或不批准。决定批准的，由审批机关颁发批准证书。 外国投资者协议购买境内公司股东股权，审批机关决定批准的，应同时将有关批准文件分别抄送股权转让方、境内公司所在地外汇管理机关。股权转让方所在地外汇管理机关为其办理转股收汇外资外汇登记并出具相关证明，转股收汇外资外汇登记证明是证明外方已缴付的股权收购对价已到位的有效文件。"},{"i":26,"n":"第二十六条","txt":"外国投资者资产并购的，投资者应自收到批准证书之日起30日内，向登记管理机关申请办理设立登记，领取外商投资企业营业执照。 外国投资者股权并购的，被并购境内公司应依照本规定向原登记管理机关申请变更登记，领取外商投资企业营业执照。原登记管理机关没有登记管辖权的，应自收到申请文件之日起10日内转送有管辖权的登记管理机关办理，同时附送该境内公司的登记档案。被并购境内公司在申请变更登记时，应提交以下文件，并对其真实性和有效性负责： （一）变更登记申请书； （二）外国投资者购买境内公司股东股权或认购境内公司增资的协议； （三）修改后的公司章程或原章程的修正案和依法需要提交的外商投资企业合同； （四）外商投资企业批准证书； （五）外国投资者的主体资格证明或者自然人身份证明； （六）修改后的董事会名单，记载新增董事姓名、住所的文件和新增董事的任职文件； （七）国家工商行政管理总局规定的其他有关文件和证件"},{"i":27,"n":"第二十七条","txt":"本章所称外国投资者以股权作为支付手段并购境内公司，系指境外公司的股东以其持有的境外公司股权，或者境外公司以其增发的股份，作为支付手段，购买境内公司股东的股权或者境内公司增发股份的行为。"},{"i":28,"n":"第二十八条","txt":"本章所称的境外公司应合法设立并且其注册地具有完善的公司法律制度，且公司及其管理层最近3年未受到监管机构的处罚；除本章第三节所规定的特殊目的公司外，境外公司应为上市公司，其上市所在地应具有完善的证券交易制度。"},{"i":29,"n":"第二十九条","txt":"外国投资者以股权并购境内公司所涉及的境内外公司的股权，应符合以下条件： （一） 股东合法持有并依法可以转让； （二） 无所有权争议且没有设定质押及任何其他权利限制； （三） 境外公司的股权应在境外公开合法证券交易市场（柜台交易市场除外）挂牌交易； （四） 境外公司的股权最近1年交易价格稳定。 前款第（三）、（四）项不适用于本章第三节所规定的特殊目的公司。"},{"i":30,"n":"第三十条","txt":"外国投资者以股权并购境内公司，境内公司或其股东应当聘请在中国注册登记的中介机构担任顾问（以下称“并购顾问”）。并购顾问应就并购申请文件的真实性、境外公司的财务状况以及并购是否符合本规定第十四条、第二十八条和第二十九条的要求作尽职调查，并出具并购顾问报告，就前述内容逐项发表明确的专业意见。"},{"i":31,"n":"第三十一条","txt":"并购顾问应符合以下条件： （一） 信誉良好且有相关从业经验； （二） 无重大违法违规记录； （三） 应有调查并分析境外公司注册地和上市所在地法律制度与境外公司财务状况的能力。"},{"i":32,"n":"第三十二条","txt":"外国投资者以股权并购境内公司应报送商务部审批，境内公司除报送本规定第三章所要求的文件外，另须报送以下文件： （一） 境内公司最近1年股权变动和重大资产变动情况的说明； （二） 并购顾问报告； （三） 所涉及的境内外公司及其股东的开业证明或身份证明文件； （四） 境外公司的股东持股情况说明和持有境外公司5％以上股权的股东名录； （五） 境外公司的章程和对外担保的情况说明； （六） 境外公司最近年度经审计的财务报告和最近半年的股票交易情况报告。"},{"i":33,"n":"第三十三条","txt":"商务部自收到规定报送的全部文件之日起30日内对并购申请进行审核，符合条件的，颁发批准证书，并在批准证书上加注“外国投资者以股权并购境内公司，自营业执照颁发之日起6个月内有效”。"},{"i":34,"n":"第三十四条","txt":"境内公司应自收到加注的批准证书之日起30日内，向登记管理机关、外汇管理机关办理变更登记，由登记管理机关、外汇管理机关分别向其颁发加注“自颁发之日起8个月内有效”字样的外商投资企业营业执照和外汇登记证。 境内公司向登记管理机关办理变更登记时，应当预先提交旨在恢复股权结构的境内公司法定代表人签署的股权变更申请书、公司章程修正案、股权转让协议等文件。"},{"i":35,"n":"第三十五条","txt":"自营业执照颁发之日起6个月内，境内公司或其股东应就其持有境外公司股权事项，向商务部、外汇管理机关申请办理境外投资开办企业核准、登记手续。 当事人除向商务部报送《关于境外投资开办企业核准事项的规定》所要求的文件外，另须报送加注的外商投资企业批准证书和加注的外商投资企业营业执照。商务部在核准境内公司或其股东持有境外公司的股权后，颁发中国企业境外投资批准证书，并换发无加注的外商投资企业批准证书。 境内公司取得无加注的外商投资企业批准证书后，应在30日内向登记管理机关、外汇管理机关申请换发无加注的外商投资企业营业执照、外汇登记证。"},{"i":36,"n":"第三十六条","txt":"自营业执照颁发之日起6个月内，如果境内外公司没有完成其股权变更手续，则加注的批准证书和中国企业境外投资批准证书自动失效。登记管理机关根据境内公司预先提交的股权变更登记申请文件核准变更登记，使境内公司股权结构恢复到股权并购之前的状态。 并购境内公司增发股份而未实现的，在登记管理机关根据前款予以核准变更登记之前，境内公司还应当按照《公司法》的规定，减少相应的注册资本并在报纸上公告。 境内公司未按照前款规定办理相应的登记手续的，由登记管理机关按照《公司登记管理条例》的有关规定处理。"},{"i":37,"n":"第三十七条","txt":"境内公司取得无加注的外商投资企业批准证书、外汇登记证之前，不得向股东分配利润或向有关联关系的公司提供担保，不得对外支付转股、减资、清算等资本项目款项。"},{"i":38,"n":"第三十八条","txt":"境内公司或其股东凭商务部和登记管理机关颁发的无加注批准证书和营业执照，到税务机关办理税务变更登记。"},{"i":39,"n":"第三十九条","txt":"特殊目的公司系指中国境内公司或自然人为实现以其实际拥有的境内公司权益在境外上市而直接或间接控制的境外公司。 特殊目的公司为实现在境外上市，其股东以其所持公司股权，或者特殊目的公司以其增发的股份，作为支付手段，购买境内公司股东的股权或者境内公司增发的股份的，适用本节规定。 当事人以持有特殊目的公司权益的境外公司作为境外上市主体的，该境外公司应符合本节对于特殊目的公司的相关要求。"},{"i":40,"n":"第四十条","txt":"特殊目的公司境外上市交易，应经国务院证券监督管理机构批准。 特殊目的公司境外上市所在国家或者地区应有完善的法律和监管制度，其证券监管机构已与国务院证券监督管理机构签订监管合作谅解备忘录，并保持着有效的监管合作关系。"},{"i":41,"n":"第四十一条","txt":"本节所述的权益在境外上市的境内公司应符合下列条件： （一）产权明晰，不存在产权争议或潜在产权争议； （二）有完整的业务体系和良好的持续经营能力； （三）有健全的公司治理结构和内部管理制度； （四）公司及其主要股东近3年无重大违法违规记录。"},{"i":42,"n":"第四十二条","txt":"境内公司在境外设立特殊目的公司，应向商务部申请办理核准手续。办理核准手续时，境内公司除向商务部报送《关于境外投资开办企业核准事项的规定》要求的文件外，另须报送以下文件： （一）特殊目的公司实际控制人的身份证明文件； （二）特殊目的公司境外上市商业计划书； （三）并购顾问就特殊目的公司未来境外上市的股票发行价格所作的评估报告。 获得中国企业境外投资批准证书后，设立人或控制人应向所在地外汇管理机关申请办理相应的境外投资外汇登记手续。"},{"i":43,"n":"第四十三条","txt":"特殊目的公司境外上市的股票发行价总值，不得低于其所对应的经中国有关资产评估机构评估的被并购境内公司股权的价值。"},{"i":44,"n":"第四十四条","txt":"特殊目的公司以股权并购境内公司的，境内公司除向商务部报送本规定第三十二条所要求的文件外，另须报送以下文件： （一）设立特殊目的公司时的境外投资开办企业批准文件和证书； （二）特殊目的公司境外投资外汇登记表； （三）特殊目的公司实际控制人的身份证明文件或开业证明、章程； （四）特殊目的公司境外上市商业计划书； （五）并购顾问就特殊目的公司未来境外上市的股票发行价格所作的评估报告。 如果以持有特殊目的公司权益的境外公司作为境外上市主体，境内公司还须报送以下文件： （一）该境外公司的开业证明和章程； （二）特殊目的公司与该境外公司之间就被并购的境内公司股权所作的交易安排和折价方法的详细说明。"},{"i":45,"n":"第四十五条","txt":"商务部对本规定第四十四条所规定的文件初审同意的，出具原则批复函，境内公司凭该批复函向国务院证券监督管理机构报送申请上市的文件。国务院证券监督管理机构于20个工作日内决定是否核准。 境内公司获得核准后，向商务部申领批准证书。商务部向其颁发加注“境外特殊目的公司持股，自营业执照颁发之日起1年内有效”字样的批准证书。 并购导致特殊目的公司股权等事项变更的，持有特殊目的公司股权的境内公司或自然人，凭加注的外商投资企业批准证书，向商务部就特殊目的公司相关事项办理境外投资开办企业变更核准手续，并向所在地外汇管理机关申请办理境外投资外汇登记变更。"},{"i":46,"n":"第四十六条","txt":"境内公司应自收到加注的批准证书之日起30日内，向登记管理机关、外汇管理机关办理变更登记，由登记管理机关、外汇管理机关分别向其颁发加注“自颁发之日起14个月内有效”字样的外商投资企业营业执照和外汇登记证。 境内公司向登记管理机关办理变更登记时，应当预先提交旨在恢复股权结构的境内公司法定代表人签署的股权变更申请书、公司章程修正案、股权转让协议等文件。"},{"i":47,"n":"第四十七条","txt":"境内公司应自特殊目的公司或与特殊目的公司有关联关系的境外公司完成境外上市之日起30日内，向商务部报告境外上市情况和融资收入调回计划，并申请换发无加注的外商投资企业批准证书。同时，境内公司应自完成境外上市之日起30日内，向国务院证券监督管理机构报告境外上市情况并提供相关的备案文件。境内公司还应向外汇管理机关报送融资收入调回计划，由外汇管理机关监督实施。境内公司取得无加注的批准证书后，应在30日内向登记管理机关、外汇管理机关申请换发无加注的外商投资企业营业执照、外汇登记证。 如果境内公司在前述期限内未向商务部报告，境内公司加注的批准证书自动失效，境内公司股权结构恢复到股权并购之前的状态，并应按本规定第三十六条办理变更登记手续。"},{"i":48,"n":"第四十八条","txt":"特殊目的公司的境外上市融资收入，应按照报送外汇管理机关备案的调回计划，根据现行外汇管理规定调回境内使用。融资收入可采取以下方式调回境内： （一）向境内公司提供商业贷款； （二）在境内新设外商投资企业； （三）并购境内企业。 在上述情形下调回特殊目的公司境外融资收入，应遵守中国有关外商投资及外债管理的法律和行政法规。如果调回特殊目的公司境外融资收入，导致境内公司和自然人增持特殊目的公司权益或特殊目的公司净资产增加，当事人应如实披露并报批，在完成审批手续后办理相应的外资外汇登记和境外投资登记变更。 境内公司及自然人从特殊目的公司获得的利润、红利及资本变动所得外汇收入，应自获得之日起6个月内调回境内。利润或红利可以进入经常项目外汇帐户或者结汇。资本变动外汇收入经外汇管理机关核准，可以开立资本项目专用帐户保留，也可经外汇管理机关核准后结汇。"},{"i":49,"n":"第四十九条","txt":"自营业执照颁发之日起1年内，如果境内公司不能取得无加注批准证书，则加注的批准证书自动失效，并应按本规定第三十六条办理变更登记手续。"},{"i":50,"n":"第五十条","txt":"特殊目的公司完成境外上市且境内公司取得无加注的批准证书和营业执照后，当事人继续以该公司股份作为支付手段并购境内公司的，适用本章第一节和第二节的规定。"},{"i":51,"n":"第五十一条","txt":"依据《反垄断法》的规定，外国投资者并购境内企业达到《国务院关于经营者集中申报标准的规定》规定的申报标准的，应当事先向商务部申报，未申报不得实施交易。"},{"i":52,"n":"第五十二条","txt":"外国投资者在中国境内依法设立的投资性公司并购境内企业，适用本规定。 外国投资者购买境内外商投资企业股东的股权或认购境内外商投资企业增资的，适用现行外商投资企业法律、行政法规和外商投资企业投资者股权变更的相关规定，其中没有规定的，参照本规定办理。 外国投资者通过其在中国设立的外商投资企业合并或收购境内企业的，适用关于外商投资企业合并与分立的相关规定和关于外商投资企业境内投资的相关规定，其中没有规定的，参照本规定办理。 外国投资者并购境内有限责任公司并将其改制为股份有限公司的，或者境内公司为股份有限公司的，适用关于设立外商投资股份有限公司的相关规定，其中没有规定的，适用本规定。"},{"i":53,"n":"第五十三条","txt":"申请人或申报人报送文件，应依照本规定对文件进行分类，并附文件目录。规定报送的全部文件应用中文表述。"},{"i":54,"n":"第五十四条","txt":"被股权并购境内公司的中国自然人股东，经批准，可继续作为变更后所设外商投资企业的中方投资者。"},{"i":55,"n":"第五十五条","txt":"境内公司的自然人股东变更国籍的，不改变该公司的企业性质。"},{"i":56,"n":"第五十六条","txt":"相关政府机构工作人员必须忠于职守、依法履行职责，不得利用职务之便牟取不正当利益，并对知悉的商业秘密负有保密义务。"},{"i":57,"n":"第五十七条","txt":"香港特别行政区、澳门特别行政区和台湾地区的投资者并购境内其他地区的企业，参照本规定办理。"},{"i":58,"n":"第五十八条","txt":"本规定自公布之日起施行。"}],"guanyuduizousiweiguiqiyejiyujinggaohuozantingchexi3ff7a3":[{"i":1,"n":"第一条","txt":"为严厉打击走私、违规活动，维护对外贸易秩序，根据《中华人民共和国对外贸易法》及其他有关法律、行政法规，特制定本规定。"},{"i":2,"n":"第二条","txt":"本《规定》所指走私、违规企业，系指经人民法院判决认定构成走私罪，或经海关认定构成走私行为或违反海关监管规定行为的各类外经贸企业。"},{"i":3,"n":"第三条","txt":"对走私、违规企业给予警告、暂停或撤销对外贸易、国际货运代理经营许可的行政处罚的基本前提是：违规、走私行为事实成立，由海关作出行政处罚并已生效；或构成走私罪，由法院已作出判决并已生效。对外贸易经济合作部或其授权的地方外经贸主管部门在接到海关或法院通知后，有权对走私、违规企业作出警告或暂停、撤销对外贸易、国际货运代理经营许可的行政处罚。"},{"i":4,"n":"第四条","txt":"外经贸企业有下列情形之一的，由对外贸易经济合作部或其授权的地方外经贸主管部门给予警告的行政处罚： （一）走私进出口货物、物品，偷逃税款在人民币3万元以上，不满人民币25万元的； （二）走私国家限制进出口货物、物品，案值在人民币1O万元以上，不满人民币100万元的； （三）违反海关监管规定进出口货物、物品，漏缴税款在人民币30万元以上，不满人民币300万元的； （四）违反海关监管规定进出口货物、物品，案值在人民币100万元以上，不满人民币1000万元的。"},{"i":5,"n":"第五条","txt":"外经贸企业有下列情形之一的，由对外贸易经济合作部或其授权的地方外经贸主管部门给予暂停3个月对外贸易、国际货运代理经营许可的行政处罚： （一）走私进出口货物、物品，偷逃税款在人民币25万元以上，不满人民币300万元的； （二）走私国家限制进出口货物、物品，案值在人民币100万元以上，不满人民币1000万元的； （三）违反海关监管规定进出口货物、物品，漏缴税款在人民币300万元以上，不满人民币1000万元的； （四）违反海关监管规定进出口货物、物品，案值在人民币1000万元以上，不满人民币3000万元的。"},{"i":6,"n":"第六条","txt":"外经贸企业有下列情形之一的，由对外贸易经济合作部或其授权的地方外经贸主管部门给予撤销对外贸易、国际货运代理经营许可的行政处罚： （一）走私进出口货物、物品，偷逃税款在人民币300万元以上的； （二）走私国家限制进出口货物、物品，案值在人民币1000万元以上的； （三）违反海关监管规定进出口货物、物品，漏缴税款在人民币1000万元以上的； （四）违反海关监管规定进出口货物、物品，案值在人民币3000万元以上的； （五）走私国家禁止进出口货物、物品，构成犯罪的。"},{"i":7,"n":"第七条","txt":"外经贸企业的行为符合上述处罚条款中两种以上情形的，择其重者进行处罚。"},{"i":8,"n":"第八条","txt":"当事人有下列情形之一的，对外贸易经济合作部或其授权的地方外经贸主管部门可依法对其从轻、减轻或免于行政处罚： （一）主动消除或者减轻违法行为危害后果的； （二）受他人胁迫有违法行为的； （三）配合行政机关查处违法行为有立功表现的； （四）其他依法从轻或者减轻行政处罚的。"},{"i":9,"n":"第九条","txt":"对外贸易经济合作部或其授权的地方外经贸主管部门在作出行政处罚前，应告知当事人，当事人有权进行陈述和申辩。对暂停或撤销对外贸易、国际货运代理经营许可的行政处罚，当事人有要求举行听证的权利；当事人要求听证的，对外贸易经济合作部或其授权的地方外经贸主管部门应组织听证。听证结束后，对外贸易经济合作部或其授权的地方外经贸主管部门依据有关法律、法规及听证情况，作出行政处罚决定。"},{"i":10,"n":"第十条","txt":"对外贸易经济合作部或其授权的地方外经贸主管部门作出行政处罚决定后，应于7日内将处罚决定书送达当事人；无法直接或邮寄送达的，公告送达。"},{"i":11,"n":"第十一条","txt":"当事人对行政处罚决定不服的，可以依照《中华人民共和国行政复议法》提起行政复议，或依照《中华人民共和国行政诉讼法》提起行政诉讼。"},{"i":12,"n":"第十二条","txt":"本《规定》适用于外商投资企业。对外贸易经济合作部或其授权的地方外经贸主管部门可根据本《规定》，对走私、违规外商投资企业分别给予警告、通知海关暂停或停止其办理进出口业务和国际货运代理业务的行政处罚，并通知外方母公司。"},{"i":13,"n":"第十三条","txt":"本《规定》由对外贸易经济合作部负责解释。"},{"i":14,"n":"第十四条","txt":"本《规定》于2002年3月15日发布，自发布之日起30日后施行。对外贸易经济合作部和海关总署1998年12月1日联合发布的《对违规、走私企业给予警告、暂停或撤销对外贸易、国际货运代理经营许可行政处罚的暂行规定》（[1998]外经贸政发第929号）同时废止。"}],"guanyuquerenhekaohewaishangtouzidechanpinchukouqiy5f1e69":[{"i":1,"n":"第一条","txt":"在中国境内依法设立的中外合资经营企业、中外合作经营企业和外资企业（以下统称外商投资企业），凡符合《国务院规定》和本实施办法关于“两类企业”条件的，经确认考核领取证书后，均可享受《国务院规定》中的有关优惠待遇。"},{"i":2,"n":"第二条","txt":"凡同时具备下列条件的外商投资企业可确认为产品出口企业： 一、必须是生产出口产品的企业； 二、年出口额（包括企业自行出口，外贸公司代理出口等方式）达到当年企业全部产品销售额的50％以上； 三、当年实现营业外汇收支平衡有余（当年实现营业外汇收入大于当年营业外汇支出，不包括上年结转余额）。 四、企业当年实现盈利。"},{"i":3,"n":"第三条","txt":"符合第二条规定的产品出口企业，凡当年出口额达到企业全部产品销售额70％以上的，经年度考核合格后，可按《国务院规定》第八条享受优惠待遇。"},{"i":4,"n":"第四条","txt":"凡同时具备下列条件的，可确认为先进技术企业： 一、属于国家鼓励外商投资的生产性项目； 二、采用国际先进和适用的工艺、技术和设备； 三、生产的产品质量、技术性能处于国内领先地位。"},{"i":5,"n":"第五条","txt":"一个企业同时被确认为产品出口企业和先进技术企业的，可择一申请享受相应的优惠待遇。"},{"i":6,"n":"第六条","txt":"两类企业”的审核确认机关为各省、自治区、直辖市、计划单列市、经济特区的对外经济贸易部门（以下简称审核确认机关）。 对外贸易经济合作部批准设立的限额以上的外商投资企业申请确认为先进技术企业，须向审核确认机关提交国务院行业主管部门认可的技术鉴定部门的鉴定意见。"},{"i":7,"n":"第七条","txt":"符合本规定第二条条件的企业，在其投产一年后，可向审核确认机关提交下列文件，申请确认为产品出口企业。 一、产品出口企业确认申请书（格式见附件一）； 二、企业批准证书、营业执照、合同、章程及其批准文件（副本）； 三、注册会计师出具的关于投资各方注册资本投入的验资报告； 四、企业申请确认前一年的产品出口实绩报表（格式见附件二）； 五、企业申请确认前一年的外汇收支平衡表（格式见附件三）； 六、注册会计师出具的申请确认前一年产品出口及外汇收支平衡情况的审计报告； 七、审核确认机关要求的其它文件。"},{"i":8,"n":"第八条","txt":"被确认为产品出口企业的外商投资企业须在每一个日历年度的前4个月内向审核确认机关申请考核。申请考核须报送下列文件： 一、上一年度的产品出口实绩报表； 二、上一年度的企业外汇收支平衡表； 三、经注册会计师审计的上一年度的财务报表及注册会计师出具的对上一年度的产品出口实绩和外汇收支平衡情况的审计报告； 四、审核确认机关要求的其它文件。"},{"i":9,"n":"第九条","txt":"审核确认机关对产品出口企业的考核，每年进行一次。届时企业不申请考核的，视为考核不合格。"},{"i":10,"n":"第十条","txt":"符合本规定第四条条件的企业，在其投产6个月后，可向审核确认机关提交下列文件，申请确认为先进技术企业。 一、先进技术企业确认申请书（格式见附件一）； 二、项目可行性研究报告及其批准文件； 三、企业批准证书、营业执照、合同、章程及其批准文件（副本）； 四、注册会计师出具的关于投资各方注册资本投入的验资报告； 五、企业技术转让协议（技术转让协议内容应包括：技术转让的详细内容、步骤、技术和产品的标准、达到标准的期限以及零部件、元器件的国产化进度等）及其批准文件； 六、企业生产线验收合格报告； 七、待业主管部门、科学技术管理部门对技术的评估意见； 八、审核确认机关要求的其它文件。 仅是进口机器设备的性能、效率优于国产设备的一般加工项目或主要从事来件组装的项目不能确认为先进技术企业。 如属从事高新技术开发的企业，虽不生产有形产品，也可申请确认为先进技术企业。"},{"i":11,"n":"第十一条","txt":"审核确认机关对先进技术企业的确认考核应会同同级行业主管部门、科学技术管理部门进行，必要时可委托行业主管部门组织专家评估。"},{"i":12,"n":"第十二条","txt":"除审核确认机关认为有必要复核外，先进技术企业可不逐年进行考核。"},{"i":13,"n":"第十三条","txt":"审核确认机关如需对已被确认的先进技术企业进行考核，应在距考核一个月前发出考核通知。企业接通知后，应准备下列文件： 一、技术转让的实施进度报告； 二、企业生产、经营情况报告； 三、审核确认机关要求的其他文件； 考核不合格的企业应于一年后再次申请考核，不申请考核或虽经考核仍不合格的，撤销其先进技术企业称号。"},{"i":14,"n":"第十四条","txt":"除需要组织专家评估的先进技术企业的确认考核外，审核确认机关收到确认考核申请后，应在45天内完成确认考核工作。"},{"i":15,"n":"第十五条","txt":"“两类企业”确认证书由外经贸部统一印制。确认证书由各审核确认机关编号、颁发。"},{"i":16,"n":"第十六条","txt":"审核确认机关应及时将确认和年度考核合格与不合格的“两类企业”名单通知同级人民政府的财政、税务、海关、银行、外汇、土地管理等部门，并于每年6月30日前将确认和考核上年度“两类企业”的名单报外经贸部备案。"},{"i":17,"n":"第十七条","txt":"外商投资企业自被确认为“两类企业”之日起，享受有关优惠待遇。但考核不合格的企业，应补缴或取消考核年度享受的“两类企业”减免税等优惠待遇。"},{"i":18,"n":"第十八条","txt":"香港、澳门、台湾投资者投资的企业参照本实施办法执行。"},{"i":19,"n":"第十九条","txt":"本实施办法由对外贸易经济合作部解释。"},{"i":20,"n":"第二十条","txt":"本实施办法自1997年1月1日起实行。1987年和1992年颁布的《对外经济贸易部关于确认和考核外商投资的产品出口企业和先进技术企业的实施办法》和核办法的“补充规定”同时废止。"}],"diandangguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范典当行为，加强监督管理，促进典当业规范发展，根据有关法律规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内设立典当行，从事典当活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称典当，是指当户将其动产、财产权利作为当物质押或者将其房地产作为当物抵押给典当行，交付一定比例费用，取得当金，并在约定期限内支付当金利息、偿还当金、赎回当物的行为。 本办法所称典当行，是指依照本办法设立的专门从事典当活动的企业法人，其组织形式与组织机构适用《中华人民共和国公司法》的有关规定。"},{"i":4,"n":"第四条","txt":"商务主管部门对典当业实施监督管理，公安机关对典当业进行治安管理。"},{"i":5,"n":"第五条","txt":"典当行的名称应当符合企业名称登记管理的有关规定。典当行名称中的行业表述应当标明“典当”字样。其他任何经营性组织和机构的名称不得含有“典当”字样,不得经营或者变相经营典当业务。"},{"i":6,"n":"第六条","txt":"典当行从事经营活动，应当遵守法律、法规和规章，遵循平等、自愿、诚信、互利的原则。"},{"i":7,"n":"第七条","txt":"申请设立典当行，应当具备下列条件： （一）有符合法律、法规规定的章程； （二）有符合本办法规定的最低限额的注册资本； （三）有符合要求的营业场所和办理业务必需的设施； （四）有熟悉典当业务的经营管理人员及鉴定评估人员； （五）有两个以上法人股东，且法人股相对控股； （六）符合本办法第九条和第十条规定的治安管理要求； （七）符合国家对典当行统筹规划、合理布局的要求。"},{"i":8,"n":"第八条","txt":"典当行注册资本最低限额为300万元；从事房地产抵押典当业务的，注册资本最低限额为500万元；从事财产权利质押典当业务的，注册资本最低限额为1000万元。 典当行的注册资本最低限额应当为股东实缴的货币资本，不包括以实物、工业产权、非专利技术、土地使用权作价出资的资本。"},{"i":9,"n":"第九条","txt":"典当行应当建立、健全以下安全制度： （一）收当、续当、赎当查验证件（照）制度； （二）当物查验、保管制度； （三）通缉协查核对制度； （四）可疑情况报告制度； （五）配备保安人员制度。"},{"i":10,"n":"第十条","txt":"典当行房屋建筑和经营设施应当符合国家有关安全标准和消防管理规定，具备下列安全防范设施： （一）经营场所内设置录像设备（录像资料至少保存2个月）； （二）营业柜台设置防护设施； （三）设置符合安全要求的典当物品保管库房和保险箱（柜、库）； （四）设置报警装置； （五）门窗设置防护设施； （六）配备必要的消防设施及器材。"},{"i":11,"n":"第十一条","txt":"设立典当行，申请人应当向拟设典当行所在地设区的市（地）级商务主管部门提交下列材料： （一）设立申请（应当载明拟设立典当行的名称、住所、注册资本、股东及出资额、经营范围等内容）及可行性研究报告； （二）典当行章程、出资协议及出资承诺书； （三）典当行业务规则、内部管理制度及安全防范措施； （四）具有法定资格的验资机构出具的验资证明； （五）档案所在单位人事部门出具的个人股东、拟任法定代表人和其他高级管理人员的简历； （六）具有法定资格的会计师事务所出具的法人股东近期财务审计报告及出资能力证明、法人股东的董事会（股东会）决议及营业执照副本复印件； （七）符合要求的营业场所的所有权或者使用权的有效证明文件； （八）工商行政管理机关核发的《企业名称预先核准通知书》。"},{"i":12,"n":"第十二条","txt":"具备下列条件的典当行可以跨省（自治区、直辖市）设立分支机构： （一）经营典当业务三年以上，注册资本不少于人民币1500万元； （二）最近两年连续盈利； （三）最近两年无违法违规经营记录。 典当行的分支机构应当执行本办法第九条规定的安全制度，具备本办法第十条规定的安全防范设施。"},{"i":13,"n":"第十三条","txt":"典当行应当对每个分支机构拨付不少于500万元的营运资金。 典当行各分支机构营运资金总额不得超过典当行注册资本的50%。"},{"i":14,"n":"第十四条","txt":"典当行申请设立分支机构，应当向拟设分支机构所在地设区的市（地）级商务主管部门提交下列材料： （一）设立分支机构的申请报告（应当载明拟设立分支机构的名称、住所、负责人、营运资金数额等）、可行性研究报告、董事会（股东会）决议； （二）具有法定资格的会计师事务所出具的该典当行最近两年的财务会计报告； （三）档案所在地人事部门出具的拟任分支机构负责人的简历； （四）符合要求的营业场所的所有权或者使用权的有效证明文件； （五）省级商务主管部门及所在地县级人民政府公安机关出具的最近两年无违法违规经营记录的证明。"},{"i":15,"n":"第十五条","txt":"收到设立典当行或者典当行申请设立分支机构的申请后，设区的市（地）级商务主管部门应当报省级商务主管部门审核，省级商务主管部门将审核意见和申请材料报送商务部，由商务部批准并颁发《典当经营许可证》。省级商务主管部门应当在收到商务部批准文件后5日（工作日，下同）内将有关情况通报同级人民政府公安机关。省级人民政府公安机关应当在5日内将通报情况通知设区的市（地）级人民政府公安机关。"},{"i":16,"n":"第十六条","txt":"申请人领取《典当经营许可证》后，应当在10日内向所在地县级人民政府公安机关申请典当行《特种行业许可证》，并提供下列材料： （一）申请报告； （二）《典当经营许可证》及复印件； （三）法定代表人、个人股东和其他高级管理人员的简历及有效身份证件复印件； （四）法定代表人、个人股东和其他高级管理人员的户口所在地县级人民政府公安机关出具的无故意犯罪记录证明； （五）典当行经营场所及保管库房平面图、建筑结构图； （六）录像设备、防护设施、保险箱（柜、库）及消防设施安装、设置位置分布图； （七）各项治安保卫、消防安全管理制度； （八）治安保卫组织或者治安保卫人员基本情况。"},{"i":17,"n":"第十七条","txt":"所在地县级人民政府公安机关受理后应当在10日内将申请材料及初步审核结果报设区的市（地）级人民政府公安机关审核批准，设区的市（地）级人民政府公安机关应当在10日内审核批准完毕。经批准的，颁发《特种行业许可证》。 设区的市（地）级人民政府公安机关直接受理的申请，应当在20日内审核批准完毕。经批准的，颁发《特种行业许可证》。 设区的市（地）级人民政府公安机关应当在发证后5日内将审核批准情况报省级人民政府公安机关备案；省级人民政府公安机关应当在5日内将有关情况通报同级商务主管部门。 申请人领取《特种行业许可证》后，应当在10日内到工商行政管理机关申请登记注册，领取营业执照后，方可营业。"},{"i":18,"n":"第十八条","txt":"典当行变更机构名称、注册资本（变更后注册资本在5000万元以上的除外）、法定代表人、在本市（地、州、盟）范围内变更住所、转让股份（对外转让股份累计达50%以上的除外）的，应当经省级商务主管部门批准。省级商务主管部门应当在批准后20日内向商务部备案。商务部于每年6月、12月集中换发《典当经营许可证》。 典当行分立、合并、跨市（地、州、盟）迁移住所、对外转让股份累计达50%以上、以及变更后注册资本在5000万元以上的，应当经省级商务主管部门同意，报商务部批准，并换发《典当经营许可证》。 申请人领取《典当经营许可证》后，依照本办法第十七条的有关规定申请换发《特种行业许可证》和营业执照。"},{"i":19,"n":"第十九条","txt":"典当行增加注册资本应当符合下列条件： （一）与开业时间或者前一次增资相隔的时间在一年以上; （二）一年内没有违法违规经营记录。"},{"i":20,"n":"第二十条","txt":"典当行变更注册资本或者调整股本结构，新进入的个人股东和拟任高级管理人员应当接受资格审查；新进入的法人股东及增资的法人股东应当具备相应的投资能力与投资资格。"},{"i":21,"n":"第二十一条","txt":"无正当理由未按照规定办理《特种行业许可证》及营业执照的，或者自核发营业执照之日起无正当理由超过6个月未营业，或者营业后自行停业连续达6个月以上的，省级商务主管部门、设区的市（地）级人民政府公安机关应当分别收回《典当经营许可证》、《特种行业许可证》，原批准文件自动撤销。收回的《典当经营许可证》应当交回商务部。 省级商务主管部门收回《典当经营许可证》，或者设区的市（地）级人民政府公安机关收回《特种行业许可证》的，应当在10日内通过省级人民政府公安机关相互通报情况。 许可证被收回后，典当行应当依法向工商行政管理机关申请注销登记。"},{"i":22,"n":"第二十二条","txt":"典当行解散应当提前3个月向省级商务主管部门提出申请，经批准后，应当停止除赎当和处理绝当物品以外的其他业务，并依法成立清算组，进行清算。"},{"i":23,"n":"第二十三条","txt":"典当行清算结束后，清算组应当将清算报告报省级商务主管部门确认，由省级商务主管部门收回《典当经营许可证》，并在5日内通报同级人民政府公安机关。 省级人民政府公安机关应当在5日内通知作出原批准决定的设区的市（地）级人民政府公安机关收回《特种行业许可证》。 典当行在清算结束后，应当依法向工商行政管理机关申请注销登记。"},{"i":24,"n":"第二十四条","txt":"省级商务主管部门对终止经营的典当行应当予以公告，并报商务部备案。"},{"i":25,"n":"第二十五条","txt":"经批准，典当行可以经营下列业务： （一）动产质押典当业务； （二）财产权利质押典当业务； （三）房地产（外省、自治区、直辖市的房地产或者未取得商品房预售许可证的在建工程除外）抵押典当业务； （四）限额内绝当物品的变卖； （五）鉴定评估及咨询服务； （六）商务部依法批准的其他典当业务。"},{"i":26,"n":"第二十六条","txt":"典当行不得经营下列业务： （一）非绝当物品的销售以及旧物收购、寄售； （二）动产抵押业务； （三）集资、吸收存款或者变相吸收存款； （四）发放信用贷款； （五）未经商务部批准的其他业务。"},{"i":27,"n":"第二十七条","txt":"典当行不得收当下列财物： （一）依法被查封、扣押或者已经被采取其他保全措施的财产； （二）赃物和来源不明的物品； （三）易燃、易爆、剧毒、放射性物品及其容器； （四）管制刀具，枪支、弹药，军、警用标志、制式服装和器械； （五）国家机关公文、印章及其管理的财物； （六）国家机关核发的除物权证书以外的证照及有效身份证件； （七）当户没有所有权或者未能依法取得处分权的财产； （八）法律、法规及国家有关规定禁止流通的自然资源或者其他财物。"},{"i":28,"n":"第二十八条","txt":"典当行不得有下列行为： （一）从商业银行以外的单位和个人借款； （二）与其他典当行拆借或者变相拆借资金； （三）超过规定限额从商业银行贷款； （四）对外投资。"},{"i":29,"n":"第二十九条","txt":"典当行收当国家统收、专营、专卖物品，须经有关部门批准。"},{"i":30,"n":"第三十条","txt":"当票是典当行与当户之间的借贷契约，是典当行向当户支付当金的付款凭证。 典当行和当户就当票以外事项进行约定的，应当补充订立书面合同，但约定的内容不得违反有关法律、法规和本办法的规定。"},{"i":31,"n":"第三十一条","txt":"当票应当载明下列事项： （一）典当行机构名称及住所； （二）当户姓名（名称）、住所（址）、有效证件（照）及号码； （三）当物名称、数量、质量、状况； （四）估价金额、当金数额； （五）利率、综合费率； （六）典当日期、典当期、续当期； （七）当户须知。"},{"i":32,"n":"第三十二条","txt":"典当行和当户不得将当票转让、出借或者质押给第三人。"},{"i":33,"n":"第三十三条","txt":"典当行和当户应当真实记录并妥善保管当票。 当票遗失，当户应当及时向典当行办理挂失手续。未办理挂失手续或者挂失前被他人赎当，典当行无过错的，典当行不负赔偿责任。"},{"i":34,"n":"第三十四条","txt":"典当行不得委托其他单位和个人代办典当业务,不得向其他组织、机构和经营场所派驻业务人员从事典当业务。"},{"i":35,"n":"第三十五条","txt":"办理出当与赎当，当户均应当出具本人的有效身份证件。当户为单位的，经办人员应当出具单位证明和经办人的有效身份证件；委托典当中，被委托人应当出具典当委托书、本人和委托人的有效身份证件。 除前款所列证件外，出当时，当户应当如实向典当行提供当物的来源及相关证明材料。赎当时，当户应当出示当票。 典当行应当查验当户出具的本条第二款所列证明文件。"},{"i":36,"n":"第三十六条","txt":"当物的估价金额及当金数额应当由双方协商确定。 房地产的当金数额经协商不能达成一致的，双方可以委托有资质的房地产价格评估机构进行评估，估价金额可以作为确定当金数额的参考。 典当期限由双方约定，最长不得超过6个月。"},{"i":37,"n":"第三十七条","txt":"典当当金利率，按中国人民银行公布的银行机构6个月期法定贷款利率及典当期限折算后执行。 典当当金利息不得预扣。"},{"i":38,"n":"第三十八条","txt":"典当综合费用包括各种服务及管理费用。 动产质押典当的月综合费率不得超过当金的42‰。 房地产抵押典当的月综合费率不得超过当金的27‰。 财产权利质押典当的月综合费率不得超过当金的24‰。 当期不足5日的，按5日收取有关费用。"},{"i":39,"n":"第三十九条","txt":"典当期内或典当期限届满后5日内，经双方同意可以续当，续当一次的期限最长为6个月。续当期自典当期限或者前一次续当期限届满日起算。续当时，当户应当结清前期利息和当期费用。"},{"i":40,"n":"第四十条","txt":"典当期限或者续当期限届满后，当户应当在5日内赎当或者续当。逾期不赎当也不续当的，为绝当。 当户于典当期限或者续当期限届满至绝当前赎当的，除须偿还当金本息、综合费用外，还应当根据中国人民银行规定的银行等金融机构逾期贷款罚息水平、典当行制定的费用标准和逾期天数，补交当金利息和有关费用。"},{"i":41,"n":"第四十一条","txt":"典当行在当期内不得出租、质押、抵押和使用当物。 质押当物在典当期内或者续当期内发生遗失或者损毁的，典当行应当按照估价金额进行赔偿。遇有不可抗力导致质押当物损毁的，典当行不承担赔偿责任。"},{"i":42,"n":"第四十二条","txt":"典当行经营房地产抵押典当业务，应当和当户依法到有关部门先行办理抵押登记，再办理抵押典当手续。 典当行经营机动车质押典当业务，应当到车辆管理部门办理质押登记手续。 典当行经营其他典当业务，有关法律、法规要求登记的，应当依法办理登记手续。"},{"i":43,"n":"第四十三条","txt":"典当行应当按照下列规定处理绝当物品： （一）当物估价金额在3万元以上的，可以按照《中华人民共和国担保法》的有关规定处理，也可以双方事先约定绝当后由典当行委托拍卖行公开拍卖。拍卖收入在扣除拍卖费用及当金本息后，剩余部分应当退还当户，不足部分向当户追索。 （二）绝当物估价金额不足3万元的，典当行可以自行变卖或者折价处理，损溢自负。 （三）对国家限制流通的绝当物，应当根据有关法律、法规，报有关管理部门批准后处理或者交售指定单位。 （四）典当行在营业场所以外设立绝当物品销售点应当报省级商务主管部门备案，并自觉接受当地商务主管部门监督检查。 （五）典当行处分绝当物品中的上市公司股份应当取得当户的同意和配合，典当行不得自行变卖、折价处理或者委托拍卖行公开拍卖绝当物品中的上市公司股份。"},{"i":44,"n":"第四十四条","txt":"典当行的资产应当按照下列比例进行管理： （一）典当行自初始营业起至第一次向省级商务主管部门及所在地商务主管部门报送年度财务会计报告的时期内从商业银行贷款的，贷款余额不得超过其注册资本。典当行第一次向省级商务主管部门及所在地商务主管部门报送财务会计报告之后从商业银行贷款的，贷款余额不得超过上一年度向主管部门报送的财务会计报告中的所有者权益。典当行不得从本市（地、州、盟）以外的商业银行贷款。典当行分支机构不得从商业银行贷款。 （二）典当行对同一法人或者自然人的典当余额不得超过注册资本的25％。 （三）典当行对其股东的典当余额不得超过该股东入股金额，且典当条件不得优于普通当户。 （四）典当行净资产低于注册资本的90%时，各股东应当按比例补足或者申请减少注册资本，但减少后的注册资本不得违反本办法关于典当行注册资本最低限额的规定。 （五）典当行财产权利质押典当余额不得超过注册资本的50%。房地产"},{"i":45,"n":"第四十五条","txt":"典当行应当依照法律和国家统一的会计制度，建立、健全财务会计制度和内部审计制度。 典当行应当按照国家有关规定，真实记录并全面反映其业务活动和财务状况，编制月度报表和年度财务会计报告，并按要求向省级商务主管部门及所在地设区的市（地）级商务主管部门报送。 典当行年度财务会计报告须经会计师事务所或者其他法定机构审查验证。"},{"i":46,"n":"第四十六条","txt":"商务部对典当业实行归口管理，履行以下监督管理职责： （一）制定有关规章、政策； （二）负责典当行市场准入和退出管理； （三）负责典当行日常业务监管； （四）对典当行业自律组织进行业务指导。"},{"i":47,"n":"第四十七条","txt":"商务部参照省级商务主管部门拟定的年度发展规划对全国范围内典当行的总量、布局及资本规模进行调控。"},{"i":48,"n":"第四十八条","txt":"《典当经营许可证》由商务部统一印制。《典当经营许可证》实行统一编码管理，编码管理办法由商务部另行制定。 当票由商务部统一设计，省级商务主管部门监制。省级商务主管部门应当每半年向商务部报告当票的印制、使用情况。任何单位和个人不得伪造和变造当票。"},{"i":49,"n":"第四十九条","txt":"省级商务主管部门应当按季度向商务部报送本地典当行经营情况。具体要求和报表格式由商务部另行规定。"},{"i":50,"n":"第五十条","txt":"典当行的从业人员应当持有有效身份证件；外国人及其他境外人员在典当行就业的，应当按照国家有关规定，取得外国人就业许可证书。 典当行不得雇佣不能提供前款所列证件的人员。"},{"i":51,"n":"第五十一条","txt":"典当行应当如实记录、统计质押当物和当户信息，并按照所在地县级以上人民政府公安机关的要求报送备查。"},{"i":52,"n":"第五十二条","txt":"典当行发现公安机关通报协查的人员或者赃物以及本办法第二十七条所列其他财物的，应当立即向公安机关报告有关情况。"},{"i":53,"n":"第五十三条","txt":"对属于赃物或者有赃物嫌疑的当物，公安机关应当依法予以扣押，并依照国家有关规定处理。"},{"i":54,"n":"第五十四条","txt":"省级商务主管部门以及设区的市（地）级商务主管部门应当根据本地实际建立定期检查及不定期抽查制度，及时发现和处理有关问题；对于辖区内典当行发生的盗抢、火灾、集资吸储及重大涉讼案件等情况，应当在24小时之内将有关情况报告上级商务主管部门和当地人民政府，并通报同级人民政府公安机关。"},{"i":55,"n":"第五十五条","txt":"全国性典当行业协会是典当行业的全国性自律组织，经国务院民政部门核准登记后成立，接受国务院商务、公安等部门的业务指导。 地方性典当行业协会是本地典当行业的自律性组织，经当地民政部门核准登记后成立，接受所在地商务、公安等部门的业务指导。"},{"i":56,"n":"第五十六条","txt":"商务部授权省级商务主管部门对典当行进行年审。具体办法由商务部另行制定。 省级商务主管部门应当在年审后10日内将有关情况通报同级人民政府公安机关和工商行政管理机关。"},{"i":57,"n":"第五十七条","txt":"国家推行典当执业水平认证制度。具体办法由商务部会同国务院人事行政部门制定。"},{"i":58,"n":"第五十八条","txt":"非法设立典当行及分支机构或者以其他方式非法经营典当业务的，依据国务院《无照经营查处取缔办法》予以处罚。"},{"i":59,"n":"第五十九条","txt":"典当行违反本办法第二十六条第（三）、（四）项规定，构成犯罪的，依法追究刑事责任。"},{"i":60,"n":"第六十条","txt":"典当行违反本办法第二十八条第（一）、（二）、（三）项或者第四十四条第（一）、（二）、（五）项规定的，由省级商务主管部门责令改正，并处5000元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":61,"n":"第六十一条","txt":"典当行违反本办法第三十七条第一款或者第三十八条第二、三、四款规定的，由省级商务主管部门责令改正，并处5000元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":62,"n":"第六十二条","txt":"典当行违反本办法第四十五条规定，隐瞒真实经营情况，提供虚假财务会计报告及财务报表，或者采用其他方式逃避税收与监管的，由省级商务主管部门责令改正，并通报相关部门依法查处；构成犯罪的，依法追究刑事责任。"},{"i":63,"n":"第六十三条","txt":"典当行违反本办法第二十七条规定的，由县级以上人民政府公安机关责令改正，并处5000元以上3万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":64,"n":"第六十四条","txt":"典当行违反本办法第二十六条第（一）、（二）、（五）项，第二十八条第（四）项或者第三十四条规定的，由所在地设区的市（地）级商务主管部门责令改正，单处或者并处5000元以上3万元以下罚款。 典当行违反本办法第二十九条或者第四十三条第（三）、（五）项的规定，收当限制流通物或者处理绝当物未获得相应批准或者同意的，由所在地设区的市（地）级商务主管部门责令改正，并处1000元以上5000元以下罚款。 典当行违反本办法第四十四条第（三）、（四）项规定，资本不实，扰乱经营秩序的，由所在地设区的市（地）级商务主管部门责令限期补足或者减少注册资本，并处以5000元以上3万元以下罚款。"},{"i":65,"n":"第六十五条","txt":"典当行违反本办法第三十五条第三款或者第五十一条规定的，由县级以上人民政府公安机关责令改正，并处200元以上1000元以下罚款。"},{"i":66,"n":"第六十六条","txt":"典当行违反本办法第五十二条规定的，由县级以上人民政府公安机关责令改正，并处2000元以上1万元以下罚款；造成严重后果或者屡教不改的，处5000元以上3万元以下罚款。 对明知是赃物而窝藏、销毁、转移的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":67,"n":"第六十七条","txt":"典当行采用暴力、威胁手段强迫他人典当，或者以其他不正当手段侵犯当户合法权益，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"},{"i":68,"n":"第六十八条","txt":"在调查、侦查典当行违法犯罪行为过程中，商务主管部门与公安机关应当相互配合。商务主管部门和公安机关发现典当行有违反本办法行为的，应当进行调查、核实，并相互通报查处结果；涉嫌构成犯罪的，商务主管部门应当及时移送公安机关处理。"},{"i":69,"n":"第六十九条","txt":"商务主管部门、公安机关工作人员在典当行设立、变更及终止审批中违反法律、法规和本办法规定，或者在监督管理工作中滥用职权、徇私舞弊、玩忽职守的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":70,"n":"第七十条","txt":"各省、自治区、直辖市商务主管部门、公安机关可以依据本办法，制定具体实施办法或者就有关授权委托管理事项作出规定，并报商务部、公安部备案。"},{"i":71,"n":"第七十一条","txt":"外商及港、澳、台商投资典当行的管理办法由商务部会同有关部门另行制定。"},{"i":72,"n":"第七十二条","txt":"本办法由商务部、公安部负责解释。"},{"i":73,"n":"第七十三条","txt":"本办法自2005年4月1日起施行。《典当行管理办法》(国家经贸委令第22号)、《典当业治安管理办法》(公安部第26号令)同时废止。"}],"zaishengziyuanhuishouguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为促进再生资源回收，规范再生资源回收行业的发展，节约资源，保护环境，实现经济与社会可持续发展，根据《中华人民共和国清洁生产 促进法》、《中华人民共和国固体废物污染环境防治法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称再生资源，是指在社会生产和生活消费过程中产生的，已经失去原有全部或部分使用价值，经过回收、加工处理，能够使其 重新获得使用价值的各种废弃物。 再生资源包括废旧金属、报废电子产品、报废机电设备及其零部件、废造纸原料（如废纸、废棉等）、废轻化工原料（如橡胶、塑料、农药包装物、动物杂骨、毛 发等）、废玻璃等。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事再生资源回收经营活动的企业和个体工商户（统称“再生资源回收经营者”）应当遵守本办法。 法律法规和规章对进口可用作原料的固体废物、危险废物、报废汽车的回收管理另有规定的，从其规定。"},{"i":4,"n":"第四条","txt":"国家鼓励全社会各行各业和城乡居民积攒交售再生资源。"},{"i":5,"n":"第五条","txt":"国家鼓励以环境无害化方式回收处理再生资源，鼓励开展有关再生资源回收处理的科学研究、技术开发和推广。"},{"i":6,"n":"第六条","txt":"从事再生资源回收经营活动，必须符合工商行政管理登记条　件，工商注册登记后，方可从事经营活动。 再生资源回收经营者备案事项整合到营业执照上，市场监管部门核准工商注册登记后，通过省级共享平台将企业信息共享给各相关部门。"},{"i":7,"n":"第七条","txt":"回收生产性废旧金属的再生资源回收企业和回收非生产性废旧金属的再生资源回收经营者，还应当在取得营业执照后15日内，向所在地 县级人民政府公安机关备案。 备案事项发生变更时，前款所列再生资源回收经营者应当自变更之日起15日内（属于工商登记事项的自工商登记变更之日起15日内）向县级人民政府公安机关办理 变更手续。"},{"i":8,"n":"第八条","txt":"生产企业应当通过与再生资源回收企业签订收购合同的方式交售生产性废旧金属。收购合同中应当约定所回收生产性废旧金属的名称、 数量、规格，回收期次，结算方式等。"},{"i":9,"n":"第九条","txt":"再生资源回收企业回收生产性废旧金属时，应当对物品的名称、数量、规格、新旧程度等如实进行登记。 出售人为单位的，应当查验出售单位开具的证明，并如实登记出售单位名称、经办人姓名、住址、身份证号码；出售人为个人的，应当如实登记出售人的姓名、住址、身份证号码。 登记资料保存期限不得少于两年。"},{"i":10,"n":"第十条","txt":"再生资源回收经营者在经营活动中发现有公安机关通报寻查的赃物或有赃物嫌疑的物品时，应当立即报告公安机关。 公安机关对再生资源回收经营者在经营活动中发现的赃物或有赃物嫌疑的物品应当依法予以扣押，并开列扣押清单。有赃物嫌疑的物品经查明不是赃物的，应当依法及时退还；经查明确属赃物的，依照国家有关规定处理。"},{"i":11,"n":"第十一条","txt":"再生资源的收集、储存、运输、处理等全过程应当遵守相关国家污染防治标准、技术政策和技术规范。"},{"i":12,"n":"第十二条","txt":"再生资源回收经营者从事旧货收购、销售、储存、运输等经营活动应当遵守旧货流通的有关规定。"},{"i":13,"n":"第十三条","txt":"再生资源回收可以采取上门回收、流动回收、固定地点回收等方式。 再生资源回收经营者可以通过电话、互联网等形式与居民、企业建立信息互动，实现便民、快捷的回收服务。"},{"i":14,"n":"第十四条","txt":"商务主管部门是再生资源回收的行业主管部门，负责制定和实施再生资源回收产业政策、回收标准和回收行业发展规划。 发展改革部门负责研究提出促进再生资源发展的政策，组织实施再生资源利用新技术、新设备的推广应用和产业化示范。 公安机关负责再生资源回收的治安管理。 工商行政管理部门负责再生资源回收经营者的登记管理和再生资源交易市场内的监督管理。 环境保护行政管理部门负责对再生资源回收过程中环境污染的防治工作实施监督管理，依法对违反污染环境防治法律法规的行为进行处罚。 建设、城乡规划行政管理部门负责将再生资源回收网点纳入城市规划，依法对违反城市规划、建设管理有关法律法规的行为进行查处和清理整顿。"},{"i":15,"n":"第十五条","txt":"商务部负责制定和实施全国范围内再生资源回收的产业政策、回收标准和回收行业发展规划。 县级以上商务主管部门负责制定和实施本行政区域内具体的行业发展规划和其他具体措施。 县级以上商务主管部门应当设置负责管理再生资源回收行业的机构，并配备相应人员。"},{"i":16,"n":"第十六条","txt":"县级以上城市商务主管部门应当会同发展改革（经贸）、公安、工商、环保、建设、城乡规划等行政管理部门，按照统筹规划、合理 布局的原则，根据本地经济发展水平、人口密度、环境和资源等具体情况，制定再生资源回收网点规划。 再生资源回收网点包括社区回收、中转、集散、加工处理等回收过程中再生资源停留的各类场所。"},{"i":17,"n":"第十七条","txt":"跨行政区域转移再生资源进行储存、处置的，应当依照《中华人民共和国固体废物污染环境防治法》第二十三条的规定办理行政许可。"},{"i":18,"n":"第十八条","txt":"再生资源回收行业协会是行业自律性组织，履行如下职责： （一）反映企业的建议和要求，维护行业利益； （二）制定并监督执行行业自律性规范； （三）经法律法规授权或主管部门委托，进行行业统计、行业调查，发布行业信息； （四）配合行业主管部门研究制定行业发展规划、产业政策和回收标准。 再生资源回收行业协会应当接受行业主管部门的业务指导。"},{"i":19,"n":"第十九条","txt":"未依法取得营业执照而擅自从事再生资源回收经营业务的，由工商行政管理部门依照《无证无照经营查处办法》予以处罚。 凡超出工商行政管理部门核准的经营范围的，由工商行政管理部门按照有关规定予以处罚。"},{"i":20,"n":"第二十条","txt":"违反本办法第八条规定，由县级人民政府公安机关给予警告，责令其限期改正；逾期拒不改正的，可视情节轻重 ，对再生资源回收经营者处500元以上2000元以下罚款，并可向社会公告。"},{"i":21,"n":"第二十一条","txt":"再生资源回收企业违反本办法第十条第一、二款规定，收购生产性废旧金属未如实进行登记的，由 公安机关依据《废旧金属收购业治安管理办法》的有关规定予以处罚。"},{"i":22,"n":"第二十二条","txt":"违反本办法第十条第三款规定的，由公安机关责令改正，并处500元以上1000元以下罚款。"},{"i":23,"n":"第二十三条","txt":"违反本办法第十一条规定，发现赃物或有赃物嫌疑的物品而未向公安机关报告的，由公安机关给予警告，处500 元以上1000元以下罚款；造成严重后果或屡教不改的，处以1000元以上5000元以下罚款。"},{"i":24,"n":"第二十四条","txt":"有关行政管理部门工作人员严重失职、滥用职权、徇私舞弊、收受贿赂，侵害再生资源回收经营者合法权益的，有关主管部门应当 视情节给予相应的行政处分; 构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"本办法所称“生产性废旧金属”，是指用于建筑、铁路、通讯、电力、水利、油田、市政设施及其他生产领域，已失去原有全部或部分使 用价值的金属材料和金属制品。"},{"i":26,"n":"第二十六条","txt":"本办法由商务部、发展改革委、公安部、市场监管总局、生态环境部、住房和城乡建设部负责解释。 　　各省、自治区、直辖市商务、发展改革（经贸）、公安、工商、环保、建设、城乡规划主管部门可依据本办法，根据当地经济发展客观实际，制定实施细则。"},{"i":27,"n":"第二十七条","txt":"本办法自2007年5月1日起施行。"}],"zaishengziyuanhuishouguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进再生资源回收，规范再生资源回收行业的发展，节约资源，保护环境，实现经济与社会可持续发展，根据《中华人民共和国清洁生产促进法》、《中华人民共和国固体废物污染环境防治法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称再生资源，是指在社会生产和生活消费过程中产生的，已经失去原有全部或部分使用价值，经过回收、加工处理，能够使其重新获得使用价值的各种废弃物。 再生资源包括废旧金属、报废电子产品、报废机电设备及其零部件、废造纸原料（如废纸、废棉等）、废轻化工原料（如橡胶、塑料、农药包装物、动物杂骨、毛发等）、废玻璃等。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事再生资源回收经营活动的企业和个体工商户（统称“再生资源回收经营者”）应当遵守本办法。 法律法规和规章对进口可用作原料的固体废物、危险废物、报废汽车的回收管理另有规定的，从其规定。"},{"i":4,"n":"第四条","txt":"国家鼓励全社会各行各业和城乡居民积攒交售再生资源。"},{"i":5,"n":"第五条","txt":"国家鼓励以环境无害化方式回收处理再生资源，鼓励开展有关再生资源回收处理的科学研究、技术开发和推广。"},{"i":6,"n":"第六条","txt":"从事再生资源回收经营活动，必须符合工商行政管理登记条件，工商注册登记后，方可从事经营活动。 再生资源回收经营者备案事项整合到营业执照上，市场监管部门核准工商注册登记后，通过省级共享平台将企业信息共享给各相关部门。"},{"i":7,"n":"第八条","txt":"回收生产性废旧金属的再生资源回收企业和回收非生产性废旧金属的再生资源回收经营者，还应当在取得营业执照后15日内，向所在地县级人民政府公安机关备案。 备案事项发生变更时，前款所列再生资源回收经营者应当自变更之日起15日内（属于工商登记事项的自工商登记变更之日起15日内）向县级人民政府公安机关办理变更手续。"},{"i":8,"n":"第九条","txt":"生产企业应当通过与再生资源回收企业签订收购合同的方式交售生产性废旧金属。收购合同中应当约定所回收生产性废旧金属的名称、数量、规格，回收期次，结算方式等。"},{"i":9,"n":"第十条","txt":"再生资源回收企业回收生产性废旧金属时，应当对物品的名称、数量、规格、新旧程度等如实进行登记。 出售人为单位的，应当查验出售单位开具的证明，并如实登记出售单位名称、经办人姓名、住址、身份证号码；出售人为个人的，应当如实登记出售人的姓名、住址、身份证号码。 登记资料保存期限不得少于两年。"},{"i":10,"n":"第十一条","txt":"再生资源回收经营者在经营活动中发现有公安机关通报寻查的赃物或有赃物嫌疑的物品时，应当立即报告公安机关。 公安机关对再生资源回收经营者在经营活动中发现的赃物或有赃物嫌疑的物品应当依法予以扣押，并开列扣押清单。有赃物嫌疑的物品经查明不是赃物的，应当依法及时退还；经查明确属赃物的，依照国家有关规定处理。"},{"i":11,"n":"第十二条","txt":"再生资源的收集、储存、运输、处理等全过程应当遵守相关国家污染防治标准、技术政策和技术规范。"},{"i":12,"n":"第十三条","txt":"再生资源回收经营者从事旧货收购、销售、储存、运输等经营活动应当遵守旧货流通的有关规定。"},{"i":13,"n":"第十四条","txt":"再生资源回收可以采取上门回收、流动回收、固定地点回收等方式。 再生资源回收经营者可以通过电话、互联网等形式与居民、企业建立信息互动，实现便民、快捷的回收服务。"},{"i":14,"n":"第十五条","txt":"商务主管部门是再生资源回收的行业主管部门，负责制定和实施再生资源回收产业政策、回收标准和回收行业发展规划。 发展改革部门负责研究提出促进再生资源发展的政策，组织实施再生资源利用新技术、新设备的推广应用和产业化示范。 公安机关负责再生资源回收的治安管理。 工商行政管理部门负责再生资源回收经营者的登记管理和再生资源交易市场内的监督管理。 环境保护行政管理部门负责对再生资源回收过程中环境污染的防治工作实施监督管理，依法对违反污染环境防治法律法规的行为进行处罚。 建设、城乡规划行政管理部门负责将再生资源回收网点纳入城市规划，依法对违反城市规划、建设管理有关法律法规的行为进行查处和清理整顿。"},{"i":15,"n":"第十六条","txt":"商务部负责制定和实施全国范围内再生资源回收的产业政策、回收标准和回收行业发展规划。 县级以上商务主管部门负责制定和实施本行政区域内具体的行业发展规划和其他具体措施。 县级以上商务主管部门应当设置负责管理再生资源回收行业的机构，并配备相应人员。"},{"i":16,"n":"第十七条","txt":"县级以上城市商务主管部门应当会同发展改革（经贸）、公安、工商、环保、建设、城乡规划等行政管理部门，按照统筹规划、合理布局的原则，根据本地经济发展水平、人口密度、环境和资源等具体情况，制定再生资源回收网点规划。 再生资源回收网点包括社区回收、中转、集散、加工处理等回收过程中再生资源停留的各类场所。"},{"i":17,"n":"第十八条","txt":"跨行政区域转移再生资源进行储存、处置的，应当依照《中华人民共和国固体废物污染环境防治法》第二十三条的规定办理行政许可。"},{"i":18,"n":"第十九条","txt":"再生资源回收行业协会是行业自律性组织，履行如下职责： （一）反映企业的建议和要求，维护行业利益； （二）制定并监督执行行业自律性规范； （三）经法律法规授权或主管部门委托，进行行业统计、行业调查，发布行业信息； （四）配合行业主管部门研究制定行业发展规划、产业政策和回收标准。 再生资源回收行业协会应当接受行业主管部门的业务指导。"},{"i":19,"n":"第二十条","txt":"未依法取得营业执照而擅自从事再生资源回收经营业务的，由工商行政管理部门依照《无证无照经营查处办法》予以处罚。 凡超出工商行政管理部门核准的经营范围的，由工商行政管理部门按照有关规定予以处罚。"},{"i":20,"n":"第二十二条","txt":"违反本办法第八条规定，由县级人民政府公安机关给予警告，责令其限期改正；逾期拒不改正的，可视情节轻重，对再生资源回收经营者处500元以上2000元以下罚款，并可向社会公告。"},{"i":21,"n":"第二十三条","txt":"再生资源回收企业违反本办法第十条第一、二款规定，收购生产性废旧金属未如实进行登记的，由公安机关依据《废旧金属收购业治安管理办法》的有关规定予以处罚。"},{"i":22,"n":"第二十四条","txt":"违反本办法第十条第三款规定的，由公安机关责令改正，并处500元以上1000元以下罚款。"},{"i":23,"n":"第二十五条","txt":"违反本办法第十一条规定，发现赃物或有赃物嫌疑的物品而未向公安机关报告的，由公安机关给予警告，处500元以上1000元以下罚款；造成严重后果或屡教不改的，处以1000元以上5000元以下罚款。"},{"i":24,"n":"第二十六条","txt":"有关行政管理部门工作人员严重失职、滥用职权、徇私舞弊、收受贿赂，侵害再生资源回收经营者合法权益的，有关主管部门应当视情节给予相应的行政处分；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十七条","txt":"本办法所称“生产性废旧金属”，是指用于建筑、铁路、通讯、电力、水利、油田、市政设施及其他生产领域，已失去原有全部或部分使用价值的金属材料和金属制品。"},{"i":26,"n":"第二十八条","txt":"本办法由商务部、发展改革委、公安部、市场监管总局、生态环境部、住房和城乡建设部负责解释。 各省、自治区、直辖市商务、发展改革（经贸）、公安、工商、环保、建设、城乡规划主管部门可依据本办法，根据当地经济发展客观实际，制定实施细则。"},{"i":27,"n":"第二十九条","txt":"本办法自2007年5月1日起施行。"}],"nongchanpinjinkouguanshuipeieguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为有效实施农产品进口关税配额管理，建立统一、公平、公正、透明、可预见和非歧视的农产品进口关税配额管理体制，根据《中华人民共和国对外贸易法》、《中华人民共和国海关法》、《中华人民共和国货物进出口管理条例》和《中华人民共和国进出口关税条例》制定本办法。"},{"i":2,"n":"第二条","txt":"在公历年度内，根据中国加入世界贸易组织货物贸易减让表所承诺的配额量，确定实施进口关税配额管理农产品的年度市场准入数量。 关税配额量内进口的农产品适用关税配额税率，配额量外进口的农产品按照《中华人民共和国进出口关税条例》的有关规定执行。 散装货物溢装部分按照本《办法》第十九条第二款的规定执行。"},{"i":3,"n":"第三条","txt":"实施进口关税配额管理的农产品品种为：小麦（包括其粉、粒，以下简称小麦）、玉米（包括其粉、粒，以下简称玉米）、大米（包括其粉、粒，以下简称大米）、食糖、棉花、羊毛以及毛条。 实施关税配额管理农产品相应的税目及适用税率另行公布。"},{"i":4,"n":"第四条","txt":"小麦、玉米、大米、食糖、棉花进口关税配额分为国营贸易配额和非国营贸易配额。国营贸易配额须通过国营贸易企业进口；非国营贸易配额通过有贸易权的企业进口，有贸易权的最终用户也可以自行进口。"},{"i":5,"n":"第五条","txt":"农产品进口关税配额为全球配额。"},{"i":6,"n":"第六条","txt":"符合第三条规定的农产品所有贸易方式的进口均纳入关税配额管理范围。"},{"i":7,"n":"第七条","txt":"食糖、羊毛、毛条进口关税配额由商务部分配。 小麦、玉米、大米、棉花进口关税配额由国家发展和改革委员会（以下简称“发展改革委”）会同商务部分配。"},{"i":8,"n":"第八条","txt":"商务部、发展改革委分别委托省级商务主管部门和省级发展改革主管部门（以下简称委托机构）负责下列事项： （一）接收申请者的申请并将申请材料转报商务部、发展改革委； （二）受理咨询并将其转达商务部、发展改革委； （三）通知申请者其申请中不符合要求之处，并提醒其修正； （四）向经过批准的申请者发放《中华人民共和国农产品进口关税配额证》（以下简称为《农产品进口关税配额证》）。 委托机构名单另行公布。"},{"i":9,"n":"第九条","txt":"《农产品进口关税配额证》适用于一般贸易、加工贸易、易货贸易、边境小额贸易、援助、捐赠等贸易方式进口。 由境外进入保税监管场所、海关特殊监管区域的产品，免予领取《农产品进口关税配额证》。"},{"i":10,"n":"第十条","txt":"农产品进口关税配额的申请期为每年10月15日至30日（凭合同先来先领分配方式除外）。商务部、发展改革委于申请期前1个月，分别在商务部网站(网址为http://www.mofcom.gov.cn，下同)、发展改革委网站(网址为http://www.ndrc.gov.cn,下同)上公布每种农产品下一年度进口关税配额总量、申请条件及国务院关税税则委员会确定的当年度关税配额农产品税目和适用税率。 食糖、羊毛、毛条由商务部公布。小麦、玉米、大米、棉花由发展改革委公布。"},{"i":11,"n":"第十一条","txt":"商务部委托机构负责接收本地区内食糖、羊毛、毛条进口关税配额的申请。 发展改革委委托机构负责接收本地区内小麦、玉米、大米、棉花进口关税配额的申请。"},{"i":12,"n":"第十二条","txt":"商务部委托机构根据公布的条件，接收申请者提交的食糖、羊毛、毛条申请及有关资料，并于11月15日前将申请材料转报商务部（凭合同先来先领分配方式除外），同时抄报发展改革委。 发展改革委委托机构根据公布的条件，接收申请者提交的小麦、玉米、大米、棉花申请及有关资料，并于11月15日前将申请材料转报发展改革委，同时抄报商务部。"},{"i":13,"n":"第十三条","txt":"农产品进口关税配额将根据申请者的申请数量和以往进口实绩、生产能力、其他相关商业标准或根据先来先领的方式进行分配。分配的最小数量将以每种农产品商业上可行的装运量确定。"},{"i":14,"n":"第十四条","txt":"每年1月1日前，商务部、发展改革委通过各自委托机构向最终用户发放《农产品进口关税配额证》，并加盖“商务部农产品进口关税配额证专用章”或“国家发展和改革委员会农产品进口关税配额证专用章”。 国营贸易配额在《农产品进口关税配额证》上注明。"},{"i":15,"n":"第十五条","txt":"年度农产品进口关税配额于每年1月1日开始实施，并在公历年度内有效。《农产品进口关税配额证》自每年1月1日起至当年12月31日有效。 实行凭合同先来先领分配方式的《农产品进口关税配额证》有效期，按公布的实施细则执行。"},{"i":16,"n":"第十六条","txt":"当年12月31日前从始发港出运，需在下一年到货的进口关税配额农产品，最终用户需持《农产品进口关税配额证》及有关证明单证到原发证机构申请延期。原发证机构审核情况属实后可予以办理延期，但延期最迟不得超过下一年2月底。"},{"i":17,"n":"第十七条","txt":"最终用户按国家相关商品进口经营的有关规定，自行或委托签订进口合同。"},{"i":18,"n":"第十八条","txt":"加工贸易进口实行关税配额管理的农产品，海关凭企业提交的在“贸易方式”栏目中注明“加工贸易”的《农产品进口关税配额证》办理通关验放手续。 加工贸易企业未能按规定期限加工复出口的，应在到期后30天内办理加工贸易核销手续。海关按加工贸易的有关规定执行。"},{"i":19,"n":"第十九条","txt":"《农产品进口关税配额证》实行一证多批制，即最终用户需分多批进口的，凭《农产品进口关税配额证》可多次办理通关手续。最终用户须如实填写《农产品进口关税配额证》“最终用户进口填写栏”，填满后，需持该证到原发证机构换领未办理通关部分的配额证。 散装货物每批次进口溢装量不得超过该批次的5％。"},{"i":20,"n":"第二十条","txt":"自境外进入保税监管场所、海关特殊监管区域的关税配额农产品由海关按现行规定验放并实施监管。 从保税监管场所、海关特殊监管区域出库或出区进口的关税配额农产品，海关凭《农产品进口关税配额证》按进口货物管理的有关规定办理进口手续。"},{"i":21,"n":"第二十一条","txt":"最终用户完成《农产品进口关税配额证》标明配额量的最后一批次进口报关后，于20个工作日内将海关签章的《农产品进口关税配额证》第一联（收货人办理海关手续联）原件交原发证机构。 最终用户将本年度未使用完的《农产品进口关税配额证》第一联（收货人办理海关手续联）原件于下一年1月底前交原发证机构。"},{"i":22,"n":"第二十二条","txt":"分配给最终用户的国营贸易农产品进口关税配额量，在当年8月15日前未签订合同的，最终用户可以委托有贸易权的任何企业进口；有贸易权的最终用户可以自行进口。"},{"i":23,"n":"第二十三条","txt":"持有农产品进口关税配额的最终用户当年无法将已申领到的全部配额量签订进口合同或已签订合同无法完成，须在9月15日前将无法完成的配额量交还原发证机构。"},{"i":24,"n":"第二十四条","txt":"农产品进口关税配额再分配量的申请期为每年9月1日至15日（凭合同先来先领分配方式除外）。申请者的申请材料需由委托机构分别转报并同时抄报商务部或发展改革委。 商务部、发展改革委于申请期前1个月，分别在商务部网站、发展改革委网站上公布农产品进口关税配额再分配量的申请条件。 食糖、羊毛、毛条由商务部公布。小麦、玉米、大米、棉花由发展改革委公布。"},{"i":25,"n":"第二十五条","txt":"当年8月底前已完成所分配的全部农产品进口关税配额量，且将海关签章的《农产品进口关税配额证》第一联（收货人办理海关手续联）原件交原发证机构的最终用户，可申请关税配额再分配量。"},{"i":26,"n":"第二十六条","txt":"每年9月30日前，商务部将食糖、羊毛、毛条进口关税配额再分配量分配到最终用户（凭合同先来先领分配方式除外）；发展改革委会同商务部将小麦、玉米、大米、棉花关税配额再分配量分配到最终用户。 关税配额再分配量根据公布的申请条件，按照先来先领方式进行分配。分配的最小数量将以每种农产品商业上可行的装运量确定。 获得再分配配额量的最终用户可以通过有贸易权的企业进口，有贸易权的企业也可以自行进口。"},{"i":27,"n":"第二十七条","txt":"加工贸易企业未经许可，擅自将关税配额农产品保税进口料件或其制成品在国内销售的，按《中华人民共和国海关法》和《中华人民共和国海关行政处罚实施条例》的有关规定处理。"},{"i":28,"n":"第二十八条","txt":"对伪造、变造或者买卖《农产品进口关税配额证》的，依照有关法律对非法经营罪或者伪造、变造、买卖国家机关公文、证件、印章罪的规定，依法追究刑事责任。持有关税配额的最终用户有上述行为的，商务部、发展改革委两年内不再受理其进口农产品关税配额的申请。"},{"i":29,"n":"第二十九条","txt":"对伪造有关资料骗取《农产品进口关税配额证》的，除依法收缴其《农产品进口关税配额证》，两年内不再受理其进口关税配额的申请。"},{"i":30,"n":"第三十条","txt":"最终用户违反本办法第二十三条规定，于当年未能完成分配其全部农产品进口关税配额量进口，截止到9月15日又未将当年不能实现进口的配额量交还原发证机构的，其下年度分配的关税配额量将按未完成的比例相应扣减。"},{"i":31,"n":"第三十一条","txt":"最终用户连续两年未能完成分配其全部农产品进口关税配额量进口，并在该两年内每年9月15日前将当年不能使用的关税配额量交还受委托的原发证机构的，其下年度分配的关税配额量将按其最近一年未完成的比例相应扣减。"},{"i":32,"n":"第三十二条","txt":"最终用户违反本办法第二十一条规定，未在规定时间将海关签章的《农产品进口关税配额证》第一联（收货人办理海关手续联）原件交原发证机构的，视同未完成进口，相应扣减其下年度关税配额量。"},{"i":33,"n":"第三十三条","txt":"走私进口关税配额农产品，按关税配额量外进口适用的税率计算偷逃税金额，并按有关法律、行政法规的规定进行处罚。"},{"i":34,"n":"第三十四条","txt":"有关农产品进口关税配额分配和再分配的咨询需以书面形式向商务部、发展改革委或委托机构提出，商务部、发展改革委或委托机构将在10个工作日内作出答复。"},{"i":35,"n":"第三十五条","txt":"《农产品进口关税配额证》及“农产品进口关税配额证专用章”分别由商务部、发展改革委监制。"},{"i":36,"n":"第三十六条","txt":"《农产品进口关税配额证》证面以下栏目：最终用户注册地区、关税配额证编号、最终用户名称、关税配额证有效期、贸易方式、商品名称、安排数量、国营贸易量、发证日期、报关口岸须用计算机打印。需要更改证面报关口岸的最终用户，到原发证机构修改换证。"},{"i":37,"n":"第三十七条","txt":"关税配额农产品的进口购汇按国家有关规定执行。"},{"i":38,"n":"第三十八条","txt":"本办法中的国营贸易企业指政府授予某些产品进口专营特权的企业。 国营贸易企业名单由商务部核定并公布。"},{"i":39,"n":"第三十九条","txt":"本办法中的最终用户为直接申领到农产品进口关税配额的生产企业、贸易商、批发商和分销商等。"},{"i":40,"n":"第四十条","txt":"本办法自公布之日起施行，2003年度农产品进口关税配额依照原《农产品进口关税配额管理暂行办法》（国家发展计划委员会令第19号）执行。"}],"chukouchanpinfanqingxiaoanjianyingsuguiding":[{"i":1,"n":"第一条","txt":"为做好国外针对中国出口产品发起的反倾销案件的应诉工作，维护企业的正当权益,根据《中华人民共和国对外贸易法》、《中华人民共和国货物进出口管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于针对中国出口产品发起的反倾销案件的应诉工作，包括新立案调查、复审调查、反吸收调查、反规避调查等。"},{"i":3,"n":"第三条","txt":"在反倾销案件调查期内生产和向调查国或地区出口涉案产品的企业应积极应诉。"},{"i":4,"n":"第四条","txt":"进出口商会等行业组织应依照章程，加强行业自律，维护行业经营秩序，负责反倾销案件应诉工作的行业协调，促进会员企业应诉国外反倾销案件。"},{"i":5,"n":"第五条","txt":"商务部可制定有关促进反倾销案件应诉工作的政策和措施。"},{"i":6,"n":"第六条","txt":"商务部应及时公布与反倾销案件调查或应诉工作相关的信息，地方商务主管部门和行业组织在获知有关信息后应立即通知涉案企业。 前款规定的信息主要包括： （一）有关发起反倾销案件新立案调查的信息； （二）有关发起反倾销案件复审调查的信息； （三）有关发起反倾销案件反吸收、反规避等调查的信息； （四）对案件应诉工作有重大影响的其他信息。"},{"i":7,"n":"第七条","txt":"在获知有关可能发起反倾销案件新立案调查的信息后，行业组织应根据涉案产品的出口情况，做好应诉协调准备。"},{"i":8,"n":"第八条","txt":"企业应依法规范出口行为，维护行业出口秩序，做好反倾销案件信息的搜集、整理工作，及时向行业组织报送。"},{"i":9,"n":"第九条","txt":"参加应诉的涉案企业享有如下权利： （一）决定应诉方式； （二）自主选聘律师； （三）从行业组织获知案件调查整体进展和其他企业的应诉情况等信息； （四）获得行业组织对应诉工作的指导和帮助； （五）针对反倾销案件调查机关存在的歧视性做法等，向政府提出应对意见或建议。"},{"i":10,"n":"第十条","txt":"应诉企业不得从事任何可能影响其他应诉企业合法权益的活动，不得从事任何可能影响行业整体应诉工作的活动。"},{"i":11,"n":"第十一条","txt":"行业组织应定期组织有关反倾销法律知识的培训，可从会费中设立促进会员企业应诉的专项资金。"},{"i":12,"n":"第十二条","txt":"行业组织协调反倾销案件应诉工作的职责主要有： （一）建立出口商品统计监管系统和贸易救济案件信息收集反馈机制； （二）根据应诉企业的要求，就有关替代国、市场经济地位和分别裁决等技术问题的抗辩、国外调查机关的实地核查等问题予以协助； （三）组织应诉企业参加听证会、与国外调查机关和相关行业组织或企业进行磋商、谈判等工作； （四）根据应诉企业的要求，就价格承诺协议谈判的有关问题予以协助； 如需以政府名义签订“价格承诺协议”或“中止协议”的，可向商务部提出方案建议； （五）协助应诉企业就反倾销裁决结果在调查国或地区寻求司法救济； （六）提供律师信息的服务，建立律师信息库； （七）应定期在《国际商报》和本单位的网站上公布年度到期的行政复审案件等信息； （八）其他需要行业组织协调的工作。"},{"i":13,"n":"第十三条","txt":"行业组织应根据第十二条的规定，制定并公布行业组织应诉协调工作的操作规程。"},{"i":14,"n":"第十四条","txt":"根据应诉企业的要求，行业组织统一协调聘请律师的，应遵循公开、公正、透明的原则，择优选择律师。 应诉企业自行选聘律师出现两家以上律师事务所代理同一案件时，行业组织应在应诉工作全程协调各律师事务所的工作，以保证行业整体应诉工作的效果。"},{"i":15,"n":"第十五条","txt":"反倾销案件立案前3年内曾代理过调查国或地区企业，申请发起针对中国产品的贸易救济措施调查的律师和律师事务所不得参加律师竞聘。 行业组织应将在代理行为中曾严重影响或损害我企业、行业利益的律师和律师事务所通知应诉企业。"},{"i":16,"n":"第十六条","txt":"行业组织就下列案件的应诉协调工作应征询商务部意见： （一）涉案产品在调查期内出口金额较大； （二）涉案产品在调查国或地区市场份额较大，存在较大影响的； （三）行业组织之间就组织协调应诉工作无法形成一致意见，可能影响案件应诉结果的； （四）调查机关对我企业实施歧视性政策和调查方法的； （五）其他需要征询的重要案件。"},{"i":17,"n":"第十七条","txt":"地方商务主管部门应做好涉及本地区企业反倾销案件信息统计工作、建立信息报送系统、评估国外反倾销对本地区出口贸易的影响；定期组织有关反倾销法律知识的培训、根据本地区实际制定促进反倾销案件应诉工作的政策和措施；应行业组织的要求，对本地区涉案企业应诉工作进行协调。"},{"i":18,"n":"第十八条","txt":"各驻外使（领）馆、使团经商处（室）应及时跟踪和搜集国外反倾销立法修订情况和反倾销案件立案或复审动态及有关信息。"},{"i":19,"n":"第十九条","txt":"本规定由商务部负责解释。"},{"i":20,"n":"第二十条","txt":"本规定自2006年8月14日起执行。《出口产品反倾销应诉规定》（〔2001〕外经贸部令第5号）同时废止。"}],"chukoujiagongqujiagongmaoyiguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为促进加工贸易健康发展，引导加工贸易升级，进一步规范出口加工区管理，根据《中华人民共和国对外贸易法》、《国务院关于修改〈中华人民共和国海关对出口加工区监管的暂行办法〉的决定》及其他法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"出口加工区是经国务院批准设立的，由海关实行封闭监管的特定区域。"},{"i":3,"n":"第三条","txt":"出口加工区的加工贸易，是指出口加工区内企业从境外或从境内采购原材料、零部件、元器件、包装物料等，经加工、装配后将制成品复运出境的生产经营活动。"},{"i":4,"n":"第四条","txt":"出口加工区内企业，是指符合我国产业发展要求，按国家有关法律、法规或规章规定，在出口加工区内依法成立，且具有独立法人资格的企业。其中，外商投资企业须按国家关于外商投资管理的法律法规办理有关手续。"},{"i":5,"n":"第五条","txt":"商务部是出口加工区加工贸易的政策业务主管部门。出口加工区管理委员会（以下简称管委会）负责出口加工区加工贸易业务管理工作，出口加工区所在省、自治区、直辖市、计划单列市、新疆生产建设兵团及哈尔滨、长春、沈阳、南京、广州、成都、西安、武汉市商务主管部门（以下简称省级商务主管部门）归口管理其加工贸易业务。"},{"i":6,"n":"第六条","txt":"出口加工区要遵循国家有关产业政策导向，着力吸引技术水平高、增值含量大的加工贸易企业和带动配套能力强的大型下游企业入区。出口加工区内禁止开展高耗能、高污染等不符合国家产业政策发展要求的加工贸易业务。东部沿海地区的出口加工区要提高产业层次，不再新批低水平、低附加值的劳动密集型企业入区；中西部地区的出口加工区要结合本地区自身优势，有选择地发展当地特色出口加工业，并积极承接东部沿海地区梯度转移的产业。"},{"i":7,"n":"第七条","txt":"出口加工区内企业开展加工贸易业务，须凭企业设立的有效批准文件，向管委会提交开展加工贸易业务的书面申请报告，对有特殊规定的项目，须提供有关部门出具的相关批准文件。申请报告要说明企业开展加工贸易业务的方式和内容，并附需要进口的加工生产用设备、料件或需要出口的制成品清单。"},{"i":8,"n":"第八条","txt":"管委会收到企业申请后，要按照国家有关规定进行审核，对符合条件的加工贸易业务，在10个工作日内签发《出口加工区加工贸易业务批准证》和所附清单（格式附后），海关凭加盖管委会印章的《出口加工区加工贸易业务批准证》为企业进行注册备案。"},{"i":9,"n":"第九条","txt":"在具备条件的地区，企业应通过\"口岸电子执法系统\"向管委会报送申请报告和所附清单，管委会通过\"口岸电子执法系统\"核准企业报送的申请和所附清单，海关凭管委会核准的电子文件进行注册备案。"},{"i":10,"n":"第十条","txt":"出口加工区内企业在海关办理注册备案后，方可在管委会批准的范围内开展加工贸易业务。如需开展超出原批准范围的加工贸易业务，须按本办法第七条规定到管委会办理核准手续。"},{"i":11,"n":"第十一条","txt":"管委会要在每年1月15日前将上一年度出口加工区审批情况汇总，并报省级商务主管部门，省级商务主管部门将相关材料报商务部。"},{"i":12,"n":"第十二条","txt":"出口加工区与境外之间进、出的货物，除国家另有规定外，不实行进出口配额、许可证件管理。"},{"i":13,"n":"第十三条","txt":"国家禁止进、出口的商品，不得进、出出口加工区。出口加工区外禁止开展的加工贸易业务也不得在出口加工区内开展，法律、法规另有规定的除外。"},{"i":14,"n":"第十四条","txt":"出口加工区内不得开展拆解、翻新业务。"},{"i":15,"n":"第十五条","txt":"在出口加工区可以开展我国出口机电产品的售后维修业务。企业在出口加工区开展机电产品维修业务前，除须按本办法第七条规定到管委会办理核准手续外，还需向管委会提供维修产品属原产于中国，企业属生产该产品的生产厂商或由该生产厂商授权或委托开展维修业务的相关证明材料。"},{"i":16,"n":"第十六条","txt":"出口加工区企业与区外境内企业之间的货物往来（包括出口加工区货物内销），按照进出口货物的有关规定办理，涉及进出口许可证件管理的，须向管理部门提供相关证件。区内企业在加工生产过程中产生的边角料、残次品和废品按有关规定处理。"},{"i":17,"n":"第十七条","txt":"本办法所指出口加工区货物出区深加工结转是指区内加工贸易企业（以下简称转出企业）将本企业生产的产品直接转入其他出口加工区等海关特殊监管区域内或区外加工贸易企业（以下简称转入企业）进一步加工后复出口的经营活动。"},{"i":18,"n":"第十八条","txt":"未经实质性加工的保税料件，不得进行出口加工区货物出区深加工结转。"},{"i":19,"n":"第十九条","txt":"转出企业在开展出口加工区货物出区深加工结转前，应事先将结转料件等情况报管委会，管委会审核后为企业出具《出口加工区深加工结转业务批准证》和所附清单（格式附后），海关凭加盖管委会印章的《出口加工区深加工结转业务批准证》为转出企业办理货物出区深加工结转备案手续。"},{"i":20,"n":"第二十条","txt":"转入企业在其他出口加工区等海关特殊监管区域的,开展深加工结转转入业务之前，需按上款规定凭加盖所在区管委会印章的《出口加工区深加工结转业务批准证》在海关办理结转手续。"},{"i":21,"n":"第二十一条","txt":"在海关特殊监管区域外的转入企业，应按照现行加工贸易审批管理规定，向商务主管部门提出申请，商务主管部门要审核转入企业的加工贸易企业生产能力证明，按保税进口料件方式为企业出具《加工贸易业务批准证》，海关凭商务主管部门出具的《加工贸易业务批准证》办理备案手续，结转产品如属加工贸易进口涉证商品，转入企业须向有关主管部门提供相关的进口许可证件。"},{"i":22,"n":"第二十二条","txt":"转入区外的深加工结转产品应全部加工复出口，如确有特殊原因需内销的，按加工贸易内销管理有关规定办理。 附则"},{"i":23,"n":"第二十三条","txt":"本办法由商务部负责解释。"},{"i":24,"n":"第二十四条","txt":"本办法自2006年1月1日起执行。原《对外贸易经济合作部关于印发<出口加工区加工贸易管理暂行办法>的通知》（〔2001〕外经贸管发第141号）自本办法执行之日起废止。"}],"chukoushangpinpeiezhaobiaobanfa":[{"i":1,"n":"第一条","txt":"为了完善出口商品配额管理制度，建立公平竞争机制，保障国家的整体利益和出口企业的合法权益，维护对外贸易的正常秩序，根据《中华人民共和国对外贸易法》和《中华人民共和国货物进出口管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"对于实行配额管理的出口商品，可以实行招标。出口企业通过自主投标竞价，有偿取得和使用国家确定的出口商品配额。"},{"i":3,"n":"第三条","txt":"商务部统一管理出口商品配额招标工作，负责确定并公布招标商品种类及招标商品的配额总量。 商务部对申请、使用出口招标配额的活动进行监督检查。"},{"i":4,"n":"第四条","txt":"出口商品配额招标遵循\"效益、公正、公开、公平竞争\"的原则。"},{"i":5,"n":"第五条","txt":"本办法适用于对全球市场以各种贸易方式出口的招标商品，包括通过一般贸易、进料加工、来料加工、易货贸易、边境贸易、补偿贸易等贸易方式出口以及通过承包工程和劳务输出带出的招标商品。但国务院另有规定者除外。"},{"i":6,"n":"第六条","txt":"确定招标商品的原则是： (一) 属不可再生的大宗资源性商品； (二) 属在国际市场上占主导地位且价格变化对出口量影响较小的商品； (三) 属供大于求，经营相对分散，易于发生低价竞销，招致国外反倾销诉讼的商品； (四) 属我国与设限国家签订的多、双边协议中规定需要实行出口配额管理的商品。"},{"i":7,"n":"第七条","txt":"商务部通过出口商品配额招标委员会（以下简称招标委员会）负责对招标工作的领导和监督，招标委员会对商务部负责。招标委员会由商务部有关司局组成。"},{"i":8,"n":"第八条","txt":"招标委员会履行下列职责： (一) 根据不同商品的情况确定具体商品招标次数、每次招标的配额数量、招标方式以及各招标方式占招标总量的比例； (二) 审定具体出口商品配额招标方案，主持开标及评标工作，并审定配额招标的中标结果； (三) 发布配额招标的各类通知、公告、决定等； (四) 受理企业上交配额以及配额转受让备案； (五) 审查中标保证金和中标金的收取及配额使用情况； (六) 根据投标资格标准核定投标企业名单； （七）有关出口配额招标投标的其他事务。 招标委员会根据工作需要，可以委托进出口商会或相关行业组织等有关单位（以下简称委托服务单位）承担出口配额招标投标服务相关事务。 商务部主管业务司负责招标委员会的日常工作。"},{"i":9,"n":"第九条","txt":"投标资格 出口商品配额招标采取公开招标、协议招标等方式。对于不同的商品可采取不同的招标方式。 凡具有进出口经营资格、在工商行政管理部门登记注册、办理对外贸易经营者备案登记、相关商品的出口额或出口供货额达到一定规模的各类出口企业（含外商投资企业），符合招标条件，可参加投标。具体办法由商务部另行规定。"},{"i":10,"n":"第十条","txt":"各省、自治区、直辖市、计划单列市及新疆生产建设兵团商务主管部门（以下简称地方商务主管部门）负责对本地区投标企业资格进行核查并向商务部报送有关材料。"},{"i":11,"n":"第十一条","txt":"投标企业的出口实绩以海关统计数为基准。"},{"i":12,"n":"第十二条","txt":"出口商品配额招标工作由招标委员会主持。"},{"i":13,"n":"第十三条","txt":"电子标书出现下列情况之一者即作为废标处理： (一) 在开标前企业自动向招标委员会申请废标的标书； (二) 超过规定的截标时间送达的标书； (三) 同一企业在规定的时点前成功送达两份（含两份）以上的标书，不论内容相同与否； (四) 其他根据本办法应被确认为废标的情况。"},{"i":14,"n":"第十四条","txt":"公开招标时，投标企业自主决定投标价格。招标委员会可视具体情况事先确定并公布最低投标价格。 企业投标价格过高，明显背离价格规律的，标书作为废标处理。 对于协议招标的最低投标价格，招标委员会可参考具体商品出口的平均利润、出口商品市场情况、往年配额中标价格及其它因素来确定。"},{"i":15,"n":"第十五条","txt":"为了防止中标配额过分集中或分散，招标委员会根据具体商品情况设定最高投标数量和最低投标数量。高于最高投标量或低于最低投标量的标书视为废标。"},{"i":16,"n":"第十六条","txt":"企业须在规定的时点前以电子标书的方式投标，投标时以电子数据为准。对于同一商品的同一种招标方式只能投标一次。企业无法在规定的时点前发出电子标书，视为自动放弃投标资格。"},{"i":17,"n":"第十七条","txt":"中标企业的确定 公开招标：将所有合格投标企业的投标价格由高到低进行排列，按照排序先后累计投标企业的投标数量，当累计投标数量与招标总量相等时，计入累计投标总量（即招标总量）的企业，即为中标企业。 如果在最低中标价位的企业投标数量之和超过剩余配额数量时，此价位的企业全部中标。 协议招标：投标价格不低于招标委员会规定的最低投标价格水平的企业均为中标企业。"},{"i":18,"n":"第十八条","txt":"中标价格和中标数量的确定 (一) 公开招标企业的中标价格为其投标价格。协议招标的中标价格由招标委员会根据不同商品的具体情况另行确定。 (二) 中标数量的确定 1、 在公开招标中，中标企业的中标数量为其投标数量。如果在最低中标价位的企业投标数量之和超过剩余配额数量时，在此价位上的企业按其投标数量比例分配剩余配额。企业中标数量低于最低投标数量的，按未中标处理； 2、 协议招标中标数量： （1）企业中标数量按照下列公式计算： 企业中标数量=招标总量×[该企业投标金额（投标配额价格×投标数量）/各中标企业投标金额（投标配额价格×投标数量）总和] 或（2）企业的最高中标数量为其投标数量。"},{"i":19,"n":"第十九条","txt":"商务部按照规定发布招标公告。"},{"i":20,"n":"第二十条","txt":"招标委员会应在评标结束后规定的时间内公布初步中标结果。投标企业如有疑问，可于公布初步中标结果日起2个工作日内向招标委员会提出。"},{"i":21,"n":"第二十一条","txt":"招标委员会审定中标结果后，公布中标企业名单。"},{"i":22,"n":"第二十二条","txt":"中标金的交纳 根据评标规则确定的中标企业须按照规定交纳中标保证金和中标金。招标收入纳入一般公共预算管理并上缴中央国库。 收取中标保证金和中标金的有关事务可委托委托服务单位办理，按规定上缴中央国库。 委托服务单位须在中标保证金收取截止日后五个工作日内向招标委员会报告收取情况。"},{"i":23,"n":"第二十三条","txt":"中标企业须按下列规定交纳中标保证金和中标金，且不得由其他企业代交： (一) 中标企业须在规定时间内以支票、汇票、汇款等形式将中标保证金汇到指定银行帐户。中标保证金的具体比例由招标委员会根据具体商品的情况另行确定。无论中标配额使用情况如何，中标保证金不予退还。 (二) 在每次申领出口许可证前，中标企业应按领证配额数量到指定银行帐户交纳相应配额的中标金余额。"},{"i":24,"n":"第二十四条","txt":"在收到企业交纳的中标金后，招标委员会向企业发放用于申领《中华人民共和国出口许可证》（简称为出口许可证）的出口商品配额招标中标证明文件（以下简称中标证明文件）。"},{"i":25,"n":"第二十五条","txt":"中标企业无法使用中标配额或配额使用不完时，应按规定程序将其上交或转让。"},{"i":26,"n":"第二十六条","txt":"出口商品招标配额上交的时间由招标委员会根据不同的商品具体确定。"},{"i":27,"n":"第二十七条","txt":"中标企业对于出口商品招标配额的转让，须按招标委员会规定的比例向指定银行帐户交纳中标金后方可提出申请。转受让企业必须将双方同意进行配额转受让的申请报招标委员会审批。受让企业必须具有投标资格。对不同商品的中标配额转受让的鼓励或限制办法，由招标委员会另行确定。"},{"i":28,"n":"第二十八条","txt":"对于逾期未交纳全部中标金的中标配额，招标委员会可视为无法使用予以收回，且不退还已缴纳的中标保证金。收回配额的具体日期由招标委员会另行规定，收回配额的一定比例作为浪费配额计入浪费率。"},{"i":29,"n":"第二十九条","txt":"对于收回的、上交的配额以及其他剩余配额，招标委员会可以根据其数量大小决定实行再次招标，或采取经商务部批准的其他方式进行处置。"},{"i":30,"n":"第三十条","txt":"中标配额当年有效。企业获得配额后应在配额有效期内到指定的发证机构申领出口许可证。 配额招标的中标企业名单及其中标数量，由商务部核准并转发各有关许可证发证机构及各地方外经贸主管部门。"},{"i":31,"n":"第三十一条","txt":"各有关许可证发证机构按照有关规定和中标证明文件核发出口许可证。"},{"i":32,"n":"第三十二条","txt":"对违反本办法扰乱招标工作的个人、团体或企业，商务部视情节轻重予以行政处罚；对触犯刑律的，移交司法部门追究其刑事责任。"},{"i":33,"n":"第三十三条","txt":"任何企业或个人都有权利检举、投诉配额招标过程中发生的违反本办法的作弊行为。对于上述行为，一经查实，商务部有权否决该次招标结果。"},{"i":34,"n":"第三十四条","txt":"对于违反本办法的招标委员会和招标办公室的成员，商务部视情节轻重予以处分，直至移交司法部门追究其刑事责任。"},{"i":35,"n":"第三十五条","txt":"对串标、虚报投标资格条件及以其它手段扰乱配额招标工作的企业，招标委员会将收回其中标配额，并取消其一至三年的该商品配额投标资格。"},{"i":36,"n":"第三十六条","txt":"对已中标而不按规定交纳中标保证金的企业，招标委员会将收回其中标配额，并取消其一至两年有关商品的投标资格。"},{"i":37,"n":"第三十七条","txt":"对于企业未按规定上交、转让，又未在配额有效期截止日前领取的配额，以及虽领取但实际未使用的配额，视为被浪费的配额。对浪费中标配额超过一定比例的企业，按浪费情节的轻重予以取消其一至三年该项出口商品配额投标资格的处罚。具体由招标委员会视不同商品的具体情况确定。"},{"i":38,"n":"第三十八条","txt":"对于有本章以上各条所列情形的违规企业，如果其行为构成故意破坏招标工作且情节严重，招标委员会可取消其单项直至所有招标商品的永久投标资格，并移交司法部门处理。"},{"i":39,"n":"第三十九条","txt":"如因不可抗力事件而未能按规定交纳中标金（包括中标保证金）的，中标企业应在合理的时间内及时提供有关机构出具的证明，经招标委员会核准，可免除其部分或者全部责任。"},{"i":40,"n":"第四十条","txt":"如因国际市场等原因出现某商品中标配额领证率普遍较低的情况，经招标委员会核准，可免除相关中标企业的部分乃至全部责任。"},{"i":41,"n":"第四十一条","txt":"商务部、招标委员会、招标办公室及各地方外经贸主管部门因出口配额招标工作本身而发生的开支，按收支两条线的管理原则，每年由商务部审核汇总编报预算，由财政部从外经贸发展专项资金中核拨，年终清算。"},{"i":42,"n":"第四十二条","txt":"未经商务部或招标委员会批准，任何单位、组织或个人均不得发布与出口商品配额招标有关的规定、公告或通知等。"},{"i":43,"n":"第四十三条","txt":"本办法由商务部负责解释。"},{"i":44,"n":"第四十四条","txt":"本办法自2002年1月1日起实施。原《出口商品配额招标办法》及《出口商品配额招标办法实施细则》（[1998]外经贸管发第974号）同时废止。"}],"chukoushangpinpeieguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范出口商品配额管理，保证出口商品配额管理工作符合效益、公正、公开和透明的原则，维护配额管理商品的正常出口，根据《中华人民共和国对外贸易法》（以下简称《对外贸易法》）和《中华人民共和国货物进出口管理条例》（以下简称《货物进出口条例》）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）负责全国出口商品配额管理工作。各省、自治区、直辖市及计划单列市外经贸委（厅、局）（以下简称地方外经贸主管部门）根据外经贸部的授权，负责本地区出口商品配额管理工作。"},{"i":3,"n":"第三条","txt":"根据《货物进出口条例》第三十五条、第三十六条的规定, 外经贸部对部分国家限制出口的商品实行出口配额管理。"},{"i":4,"n":"第四条","txt":"下列出口配额管理商品不适用本办法： （一）实行配额招标或有偿使用管理的出口商品； （二）根据多、双边协议的规定，实行被动配额管理的出口商品； （三）本办法附件中所列商品。"},{"i":5,"n":"第五条","txt":"本办法适用于各种贸易方式下配额管理商品的出口。"},{"i":6,"n":"第六条","txt":"出口商品配额有效期截止到当年12月31日。"},{"i":7,"n":"第七条","txt":"实行配额管理的出口商品目录，由外经贸部制定、调整并公布。"},{"i":8,"n":"第八条","txt":"实行配额管理的出口商品目录，应当至少在实施前21天公布；在紧急情况下，应当不迟于实施之日公布。"},{"i":9,"n":"第九条","txt":"出口商品配额总量，由外经贸部确定并公布。"},{"i":10,"n":"第十条","txt":"外经贸部确定出口商品配额总量时，应当考虑以下因素： （一）保障国家经济安全的需要； （二）保护国内有限资源的需要； （三）国家对有关产业的发展规划、目标和政策； （四）国际、国内市场的需求及产销状况。"},{"i":11,"n":"第十一条","txt":"外经贸部应当于每年10月31日前公布下一年度出口配额总量。"},{"i":12,"n":"第十二条","txt":"外经贸部可以根据实际需要对本年度出口商品配额总量作出调整，但有关调整应当不晚于当年9月30日完成并公布。"},{"i":13,"n":"第十三条","txt":"依法享有进出口经营许可或资格，并且近三年内在经济活动中无违法、违规行为的出口企业可以申请出口商品配额。"},{"i":14,"n":"第十四条","txt":"地方管理企业向地方外经贸主管部门提出配额申请；地方外经贸主管部门对本地区企业的申请审核、汇总后，按外经贸部的要求，上报外经贸部。中央管理企业直接向外经贸部申请出口商品配额。"},{"i":15,"n":"第十五条","txt":"出口企业应当以正式书面方式提出配额申请，并按要求提交相关文件和资料。"},{"i":16,"n":"第十六条","txt":"外经贸部于每年11月1日至11月15日受理各地方外经贸主管部门和中央管理企业提出的下一年度出口商品配额的申请；其他时间申请的，不予受理。"},{"i":17,"n":"第十七条","txt":"外经贸部将出口商品配额分配给各地方外经贸主管部门和中央管理企业；各地方外经贸主管部门在外经贸部分配给本地区的配额数量内，按本办法及国家关于货物出口经营管理的有关规定，及时将配额分配给本地区提出申请的出口企业。"},{"i":18,"n":"第十八条","txt":"外经贸部应当于每年12月15日前将下一年度的出口配额分配给各地方外经贸主管部门和中央管理企业；各地方外经贸主管部门应当及时将外经贸部下达的配额分配给本地区的申请企业。 当国际市场存在不稳定因素时，外经贸部可将下一年度出口配额分两次分配。第一次分配应当于每年12月15日前将下一年度不少于总量70%的配额下达分配；剩余部分将不晚于当年6月30日下达。"},{"i":19,"n":"第十九条","txt":"外经贸部和各地方外经贸主管部门进行配额分配时，应当充分考虑申请企业或地区最近三年内该项商品的出口业绩、配额使用率、经营能力、生产规模、资源状况等。"},{"i":20,"n":"第二十条","txt":"如发生下列情况时，外经贸部可以对已分配给各地方外经贸主管部门或中央管理企业的配额进行增加或减少的调整： （一）国际市场发生重大变化； （二）国内资源状况发生重大变化； （三）各地区或中央管理企业配额使用进度明显不均衡。"},{"i":21,"n":"第二十一条","txt":"各地方外经贸主管部门应当本着提高配额使用率的原则，定期对本地区出口商品配额执行情况进行核查，对配额使用率达不到规定要求的，应当及时收回已分配的配额并重新分配。"},{"i":22,"n":"第二十二条","txt":"地方企业应当及时将其无法使用的年度配额交还地方外经贸主管部门，地方外经贸主管部门可将其在本地区内重新分配或于当年10月31日前上交外经贸部。 中央管理企业应当于当年10月31日前将无法使用的年度配额直接交还外经贸部。"},{"i":23,"n":"第二十三条","txt":"地方外经贸主管部门或中央管理企业未按本办法第二十二条规定交还配额，并且未能在当年年底前将本企业或本地区配额全部执行完的，外经贸部可以在下一年度扣减其相应的配额。"},{"i":24,"n":"第二十四条","txt":"外经贸部和各地方外经贸主管部门应当将配额分配及调整结果同时通知有关出口许可证发证机构；各地方外经贸主管部门的分配结果及调整方案应当于该决定公布之日起30天内上报外经贸部备案。"},{"i":25,"n":"第二十五条","txt":"出口企业凭外经贸部或地方外经贸主管部门发放的配额证明文件，按照有关出口许可证管理规定，向外经贸部授权的许可证发证机构申领出口配额许可证，凭出口配额许可证向海关办理报关验放手续。"},{"i":26,"n":"第二十六条","txt":"出口经营者以伪报商品名称、少报出口数量等方式超出批准、许可的范围或未经批准出口实行配额管理的出口商品的，依照《货物进出口条例》第六十五条规定处罚，外经贸部并可以取消其已获得的出口商品配额。"},{"i":27,"n":"第二十七条","txt":"伪造、变造或者买卖出口商品配额证明、批准文件或出口配额许可证的，依照《货物进出口条例》第六十六条规定处罚，外经贸部并可以取消其已获得的出口商品配额。"},{"i":28,"n":"第二十八条","txt":"出口经营者以欺骗或者其他不正当手段获取出口商品配额、批准文件或者出口配额许可证的，依照《货物进出口条例》第六十七条规定处罚，外经贸部并可以取消其已获得的出口商品配额。"},{"i":29,"n":"第二十九条","txt":"各地方外经贸主管部门的配额分配违反本办法规定或国家关于实行国营贸易管理或指定经营管理规定的，依照《行政处罚法》的有关规定处罚，外经贸部可以通知其纠正并给予警告。"},{"i":30,"n":"第三十条","txt":"对外经贸部作出的配额分配决定或处罚决定有异议的，可以依照《行政复议法》提起行政复议，也可以依法向人民法院提起诉讼。"},{"i":31,"n":"第三十一条","txt":"外商投资企业的出口商品配额按有关规定办理。"},{"i":32,"n":"第三十二条","txt":"本办法由外经贸部负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2002年1月1日起施行。1998年10月6日外经贸部发布的《对外贸易经济合作部关于出口商品配额编报下达和组织实施的暂行办法》、1999年1月2日外经贸部发布的《关于出口商品配额编报、下达和组织实施暂行办法的实施细则》同时废止。"}],"banlilaowurenyuanchuguoshouxudebanfa":[{"i":1,"n":"第一条","txt":"为适应我国改革开放和经济建设的需要，进一步简化劳务人员出国审批手续，逐步与国际通行做法接轨，促进我国对外经济合作业务发展，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称\"对外劳务合作经营公司\"（以下简称\"经营公司\"）系指经对外贸易经济合作部许可并持有对外经济合作经营资格证书的企业。"},{"i":3,"n":"第三条","txt":"本办法所称的\"劳务人员\"系指经营公司按照与国（境）外的机构、企业或个人（以下简称\"外方\"）所签订的劳务合作、承包工程、设计咨询等合同规定而派出的人员，经营公司的经营管理人员除外。"},{"i":4,"n":"第四条","txt":"劳务人员出国，应向公安机关申办中华人民共和国普通护照（以下简称\"护照\"）。"},{"i":5,"n":"第五条","txt":"申请办理劳务人员护照时，应向公安机关提交下列材料： （一）经营公司出具的对外劳务合作项目说明； （二）申请人的户籍证明和填写完整的《中国公民因私出国（境）申请审批表》； （三）经营公司的对外经济合作经营资格证书复印件。"},{"i":6,"n":"第六条","txt":"公安机关依据《中华人民共和国公民出境入境管理法》及其实施细则受理劳务人员出国申请，并主要审查以下内容： （一）经营公司是否具有对外经济合作经营资格； （二）劳务人员的身份资料； （三）劳务人员是否具有法定不准出境的情形。"},{"i":7,"n":"第七条","txt":"经营公司为跨省（自治区、直辖市和计划单列市）招聘的劳务人员申办护照时，劳务人员户口所在地的公安机关应按本办法予以办理。"},{"i":8,"n":"第八条","txt":"办理劳务人员护照，应当按国家物价部门核准的收费标准交费。"},{"i":9,"n":"第九条","txt":"劳务人员办妥出国手续后因故不能出国（境）的，经营公司应当向原发照机关登记备案。"},{"i":10,"n":"第十条","txt":"公安机关应在受理之日起15个工作日内完成护照办理工作。 对于外方要求时间紧迫的对外劳务合作项目，公安机关应当按急件在5个工作日内办结。"},{"i":11,"n":"第十一条","txt":"劳务人员的签证由经营公司统一通过外交部或其授权的地方外事办公室（以下简称\"外事部门\"）或自办单位办理。"},{"i":12,"n":"第十二条","txt":"外事部门在受理经营公司签证申请时，主要审查下列内容： （一）经营公司是否具有对外经济合作经营资格； （二）省、自治区、直辖市及计划单列市外经贸主管部门（以下简称\"地方外经贸主管部门\"）对经营公司的对外劳务合作项目的审查意见。"},{"i":13,"n":"第十三条","txt":"外事部门应公布经当地物价部门核准的签证代办费及各国签证的相应收费标准和收费项目。"},{"i":14,"n":"第十四条","txt":"外事部门受理经营公司签证申请后，应在5个工作日内送至外国驻华使（领）馆。如遇特殊情况，应向经营公司说明原因。"},{"i":15,"n":"第十五条","txt":"办理海员、渔工等特殊行业劳务人员的签证，经营公司应按我国及有关国家和地区的签证规定办理。"},{"i":16,"n":"第十六条","txt":"外事部门负责协调和管理劳务人员的签证申办工作。"},{"i":17,"n":"第十七条","txt":"经营公司违反本办法的，由地方外经贸主管部门给予警告处罚，有违法所得的，处以人民币30000元以下罚款；无违法所得的，处以人民币10000元以下罚款。构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"个人以出国劳务为名，弄虚作假，骗取出入境证件供本人使用的，依照《中华人民共和国公民出境入境管理法》及其实施细则的有关规定处罚。 单位和个人在对外劳务合作经营活动中，为他人骗取出入境证件编造情况、出具假证明，有违法所得的，由县级以上公安机关处以人民币30000元以下罚款；无违法所得的，由县级以上公安机关处以10000元以下罚款。 违反前两款规定，构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"在对外劳务合作工作中失职、渎职的国家工作人员，其所属单位应依法给予行政处分。构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"本办法适用于劳务性质的外派研修生。"},{"i":21,"n":"第二十一条","txt":"向我国香港、澳门特别行政区和台湾地区派出劳务人员，不适用本办法。"}],"jiagongmaoyibaoshuijinkouliaojianneixiaoshenpiguan0fe72f":[{"i":1,"n":"第一条","txt":"为加强加工贸易管理，规范加工贸易进口料件内销审批，保证加工贸易以及国内相关产业的健康发展，根据《国务院办公厅转发国家经贸委等部门关于进一步完善加工贸易银行保证金台帐制度意见的通知》（国办发〔1999〕35号）的规定，特制定本办法。"},{"i":2,"n":"第二条","txt":"加工贸易保税进口料件内销是指：经营企业因故不能按规定加工复出口，而需将保税进口料件或其制成品在国内销售，或转用于生产内销产品。"},{"i":3,"n":"第三条","txt":"加工贸易保税进口料件应全部加工复出口，如确有特殊原因需内销，须报省级外经贸主管部门批准。（属于一般贸易实行进口配额许可证或登记管理的商品除外。）"},{"i":4,"n":"第四条","txt":"经营企业申请加工贸易保税进口料件内销，必须具备下列条件之一： （一）外商因故与经营单位协商，要求中止执行原已签订的出口合同，经营企业能够提供有关证明，并且，从价格等方面考虑，很难再签订新的出口合同。 （二）因国际市场价格下跌，经营企业继续执行原已签订的开价出口合同，将遭受严重的经济损失，并且，能够提供已与外商达成的中止执行合同的协议。 （三）进口料件已投入加工使用，但加工的制成品质量不符合已签订的出口合同规定的标准，并且，经营企业能够提供出口商品质量检验部门或国内质量监督部门出具的相应证明。 （四）因改进加工工艺、降低单耗而产生一部分余料，或由于加工工艺的技术要求，而不可避免地产生了数量合理的边角料，并且，经营企业能够提供生产行业主管部门的有关证明。 （五）因不可抗力致使已签订的出口合同无法继续执行。 （六）具备其它要求内销的正当理由。"},{"i":5,"n":"第五条","txt":"经营企业申请加工贸易保税进口料件内销，必须在规定的制成品返销截止日期以前向规定的外经贸主管部门提出申请，并提供如下材料： （一）详细陈述已核销情况和转内销原因的内销申请报告（原件） （二）《加工贸易业务批准证》（正本） （三）加工贸易进出口合同（复印件） （四）《海关加工贸易登记手册》（正本） （五）《进口料件申请备案清单》和《出口制成品及对应进口料件消耗备案清单》（正本） （六）申请内销的加工贸易保税进口料件清单（需注明商品名称、商品代码、规格、数量、金额）"},{"i":6,"n":"第六条","txt":"对提交的材料齐全并且符合本办法第五条规定的经营单位，由外经贸主管部门颁发《加工贸易保税进口料件内销批准证》（格式见附件），并在批准证上注明批准内销的进口料件的商品名称、商品代码、规格、数量和金额，同时加盖“加工贸易业务审批专用章”。"},{"i":7,"n":"第七条","txt":"对不属于进口配额许可证或登记管理的加工贸易进口料件内销，海关根据外经贸主管部门颁发的《加工贸易保税进口料件内销批准证》，在依照国家有关规定对进口料件补征税款及税款利息后，办理加工贸易登记手册的核销手续。"},{"i":8,"n":"第八条","txt":"对属于进口配额许可证或登记管理的加工贸易进口料件内销，按下列规定办理加工贸易登记手册核销手续： （一）如经营企业能够在规定的核销期内提交相应的一般贸易进口许可证或登记证明，海关参照本办法第七条的规定办理加工贸易手册的核销手续。 （二）如经营企业不能按期提交相应的一般贸易进口许可证或登记证明，海关除按规定补征税款及税款利息外，同时按进口料件案值处以等值以下、30％以上的罚款，方予办理加工贸易登记手册的核销手续。"},{"i":9,"n":"第九条","txt":"对未经批准、擅自内销加工贸易进口料件或其制成品的，由海关按《中华人民共和国海关法》、《中华人民共和国海关法行政处罚实施细则》的规定处理。"},{"i":10,"n":"第十条","txt":"各省级外经贸主管部门须逐日汇总本地区加工贸易进口料件的内销审批情况，并通过中国国际电子商务网统一报外经贸部。"},{"i":11,"n":"第十一条","txt":"各级外经贸主管部门应严格按本办法的有关规定审批进行加工贸易进口料件内销审批，对违反本办法的，外经贸部将予以通报批评，或取消其加工贸易进口料件内销审批权，触犯刑律的，移交司法机关处理。"},{"i":12,"n":"第十二条","txt":"外商投资企业加工贸易进口料件内销审批，按本办法执行。"},{"i":13,"n":"第十三条","txt":"本办法由外经贸部负责解释。"},{"i":14,"n":"第十四条","txt":"本办法自1999年6月1日起执行。"}],"jiagongmaoyishenpiguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为进一步加强加工贸易管理，维护正常的经营秩序，保证加工贸易健康发展，根据《中华人民共和国外贸法》、《中华人民共和国海关法》、《国务院关于对加工贸易进口料件试行银行保证金台帐制度的批复》（国函[199]109号）和《国务院办公厅转发国家经贸委等部门关于进一步完善加工贸易银行保证金台账制度意见的通知》（下称国办发[1999]35号，特制定本办法）。"},{"i":2,"n":"第二条","txt":"本办法所称加工贸易，是指从境外保税进口全部或部分原辅材料、零部件、元器件、包装物料（下称进口料件），经境内企业加工或装配后，将制成品复出口的经营活动，包括来料加工和进料加工。 来料加工是指进口料件由外商提供，即不需付汇进口，也不需用加工费偿还，制成品由外商销售，经营企业收取加工费的加工贸易。 进料加工是指进口料件由经营企业付汇进口，制成品由经营企业外销出口的加工贸易。"},{"i":3,"n":"第三条","txt":"本办法所称经营企业是指负责对外签订加工贸易进出口合同的各类进出口企业和外商投资企业，以及经批准获得来料加工经营许可的对外加工装配服务公司。 本办法所称加工企业是指接受经营企业委托，负责对进口料件进行加工或装配，且具有法人资格的生产企业，以及由经营企业设立的虽不具有法人资格，但实行相对独立核算并已办理工商营业证（执照）的工厂。"},{"i":4,"n":"第四条","txt":"经营企业开展加工贸易，必须事先报外经贸主管部门审批。对外贸易经济合作部（以下简称外经贸部）负责管理全国的加工贸易业务审批工作。"},{"i":5,"n":"第五条","txt":"各省级外经贸主管部门负责管理、审批本地区的加工贸易业务，并可根据实际需要，授予部分地（市）和县（市）级外经贸主管部门加工贸易审批权，但需事先报外经贸部备案。"},{"i":6,"n":"第六条","txt":"经授权审批加工贸易业务的各级外经贸主管部门（简称加工贸易审批机关，下同）须按照外经贸部规定的统一规格、样式刻制加工贸易业务审批专用章，并由省级外经贸主管部门统一报外经贸部备案。"},{"i":7,"n":"第七条","txt":"各级加工贸易审批机关名单及其加工贸易业务审批专用章（印模）由外经贸部统一送海关总署备案。"},{"i":8,"n":"第八条","txt":"各级加工贸易审批机关，应具备使用计算机审批管理系统审批加工贸易的条件，须配备相应的计算机管理设备，加入中国国际电子商务网，并与外经贸部联网。"},{"i":9,"n":"第九条","txt":"开展进口原料属于国家对另工贸易进口实行总量平衡管理的棉花、食糖、植物油、羊毛、天然橡胶、原油和成品油等商品的加工贸易业务，由经营企业（包括原部委总公司及其子公司）注册地省级加工贸易审批机关审批，各省级审批机关不得将审批权下放。 其它加工贸易业务由经营企业（包括原部委总公司及其子公司）注册地的加工贸易审批机关审批。"},{"i":10,"n":"第十条","txt":"经营企业申请开展加工贸易业务时，必须提供下列证明文件和材料： （一）经营企业出具的书面申请报告及加盖经营企业公章的《加工贸易业务申请表》（格式见附件1）。 （二）经营企业进出口经营权批准文件（或外商投资企业批准证书）和工商营业执照（复印件）。 （三）加工企业注册地县级以上外经贸主管部门出具的加工企业生产能力证明正本（格式见附件3），加工企业的工商营业执照（复印件）。 （四）经营企业对外签定的进出口合同（正本）。 （五）经营企业与加工企业签定的加工协议（合同）正本。 （六）审批机关认为需要出具的其它证明文件和材料。"},{"i":11,"n":"第十一条","txt":"如经营企业或加工企业属于外商投资企业，除出具本办法第十条所规定的证明文件或材料外，须同时提供外经贸主管部门批准的能说明生产经营范围和规模的合同、章程，以及能确认已建成投产，投资方资金已如期到位，联合年检合格的证明文件。"},{"i":12,"n":"第十二条","txt":"开展下列特定商品的加工贸易，除按本办法第十条和第十一条规走出具证明文件和材料外，须同时按下列规定相应提供其它证明文件和材料： （一）开展进口料件属于废旧金属或物品的加工贸易，须按有关规定提供国家环保局出具的料件进口批准文件。 （二）开展进口料件或出口制成品属于易制毒化学品、军民通用化学品的加工贸易，须按有关规定提供有关部门出具的料件进口或制成品出口的批准文件。"},{"i":13,"n":"第十三条","txt":"各级加工贸易审批机关在审批加工贸易业务时，须严格按照本办法第十条、第十一条和第十二条的规定，审核经营企业提供的有关证明文件和材料，严禁“三无”（无工厂、无加工设备、无工人）企业开展加工贸易，防止企业以加工贸易名义进行走私等违法活动。"},{"i":14,"n":"第十四条","txt":"《加工贸易业务批准证》（格式见附2）是海关等部门据以办理加工贸易银行保证金台帐相关手续的有效证明文件。对能够按规定提交各项证明文件和材料，且确有加工复出口能力的经营企业，由加工贸易审批机关审核签发《加工贸易业务批准证》，并加盖加工贸易业务审批专用章。"},{"i":15,"n":"第十五条","txt":"加工贸易审批机关应认真填制《进口料件申请备案清单》和《出口制成品及对应进口料件消耗备案清单》（格式见附件2），并加盖加工贸易业务审批专用章。"},{"i":16,"n":"第十六条","txt":"加工贸易审批机关须严格按照海关总署、国家经贸委会同有关国家工业局制订并分批公布的全国统一单耗标准审批加工贸易。对尚没有全国统一单耗标准的，加工贸易审批机关要严格审核企业所申报的单耗，征求生产行业主管部门和主管海关的意见后予以审批，海关凭加工贸易审批机关签发的《加工贸易业务批准证》予以备案。海关监管中发现单耗不符的，将意见函告原审批机关，由原审批机关予以调整，海关也相应办理有关内容的变更手续。"},{"i":17,"n":"第十七条","txt":"加工贸易审批机关在审批时，必须认真审核《加工贸易加工企业生产能力证明》。《加工贸易加工企业生产能力证明》的有效期为一年。 加工企业注册地县级以上外经贸主管部门，应在严格查验加工企业生产能力和经营状况的基础上签发《加工贸易加工企业生产能力证明》，必要时，可征求生产行业主管部门的意见。"},{"i":18,"n":"第十八条","txt":"国家将加工贸易进口商品分为禁止类、限制类和允许类，将加工贸易企业分为A类、B类、C类、D类（具体分类原则和分类目录按照国办发[1999]35号文件的规定另行对外公布并进行动态调整）；国家对开展限制类商品的加工贸易和C类企业开展的加工贸易实行银行保证金台帐“实转”管理。 加工贸易审批机关在审批时，应认真审核加工贸易进口商品和企业的类别，如属于限制类商品或C类企业，应在《加工贸易业务批准证》备注栏内加注“实转”字样。"},{"i":19,"n":"第十九条","txt":"各级加工贸易审批机关均不得批准D类加工贸易企业（包括经营企业和加工企业）开展加工贸易业务，不得批准任何经营企业开展进口料件属于禁止类商品的加工贸易业务。"},{"i":20,"n":"第二十条","txt":"A类企业开展加工贸易，不实行银行保证金台帐制度，但其加工贸易合同事先仍需报加工贸易审批机关审批。"},{"i":21,"n":"第二十一条","txt":"《加工贸易业务批准证》上规定的出口制成品返销期限原则上按企业出口合同有效期审批，一般不得超过一年，其中，食糖、棉花、植物油、羊毛和天然橡胶加工贸易的制成品返销期限原则上不超过6个月。"},{"i":22,"n":"第二十二条","txt":"经营企业必须按《加工贸易业务批准证》规定的期限加工、返销制成品并办理核销手续。如因客观原因确需延长制成品返销朋限，须在规定的制成品返锗期限内报原审批机关批准，海关凭批件办理延期手续。"},{"i":23,"n":"第二十三条","txt":"延期一般不得超过两次，每次延长期限一般不超过6个月。"},{"i":24,"n":"第二十四条","txt":"经营企业必须按《加工贸易业务批准证》规定的内容加工出口，如因客观原因确需变更部分项目内容，须在《加工贸易业务批准证》规走的期限内报原审批机关批准，海关凭批件办理变更手续。"},{"i":25,"n":"第二十五条","txt":"加工贸易进口料件原则上不实行配额许可征管理，但另有规定的除外。"},{"i":26,"n":"第二十六条","txt":"国家对食糖、棉花、植物油、羊毛、天然橡胶和原油、成品油等加工贸易进口实行总量平衡和配额许可征管理。配额总量由国务院确定，具体分配管理办法按有关规定执行。"},{"i":27,"n":"第二十七条","txt":"加工贸易进口配额当年有效，不得跨年度使用。外经贸部驻各地特派员办事处和配额许可证事务局负责按照加工贸易进口配额和省级加工贸易审批机关签发的《加工贸易业务批准证》签发加工贸易进口许可证。 加工贸易进口许可证有效期不得超过《加工贸易业务批准证》规定的制成品返销期限，对需跨年度的，不得超过次年2月底。"},{"i":28,"n":"第二十八条","txt":"外经贸部驻各地特派员办事处应通过中国国际电子商务网，逐日向配额许可证事务局上报加工贸易进口发证数据。配额许可证事务局负责向外经贸部提供全国的加工贸易进口发证数据（包括配额许可证事务局的发证数据）。外经贸部将对发证情况进行定期或不定期检查，严禁越权、无配额或超配额等各种违规发证行为。"},{"i":29,"n":"第二十九条","txt":"加工贸易制成品如属出口配额管理的，经营企业应凭出口配额和《加工贸易业务批准证》申领出口许可证，海关凭有效出口许可证验放。"},{"i":30,"n":"第三十条","txt":"加工贸易进口料件或出口制成品如属于易制毒化学品、军民通用化学品，海关凭加工贸易业务批准证》和有关部门出具的料件进口或制成品出口的批准文件办理备案手续。"},{"i":31,"n":"第三十一条","txt":"各省级加工贸易审批机关须逐日汇总本地区加工贸易业务的审批情况和到期加工贸易业务的核销情况，并通过中国国际电子商务网，统一上报外经贸部。"},{"i":32,"n":"第三十二条","txt":"各级加工贸易审批机关要加强对本地区加工贸易核销情况的监督检查和跟踪管理，要求经营企业在出口核销后的30天内将海关的核销通知单报原审批机关核销备案。对逾期未能办理核销备案的企业，要查清原因，并暂停批准其开展新的加工贸易业务。"},{"i":33,"n":"第三十三条","txt":"外经贸部对各地的加工贸易审批槽况进行定期或不定期检查，严禁越权、无配额和超配额等违规审批行为。"},{"i":34,"n":"第三十四条","txt":"各级加工贸易审批机关要积极与海关、税务、银行和外汇等部门配合，加强部门间的信息交流与协作，加大对加工贸易的综合监管力度。"},{"i":35,"n":"第三十五条","txt":"加工贸易保税进口料件应全部加工后复出口。如确有特殊原因，需将保税进口料件（或其制成品）在国内销售或转用于生产内销产品，按《加工贸易保税进口料件内销审批暂行办法》的有关规定办理。"},{"i":36,"n":"第三十六条","txt":"国家允许开展加工贸易结转深加工复出口业务。但经营企业必须事先报经外经贸主管部门批准。具体管理办法另行制定。"},{"i":37,"n":"第三十七条","txt":"保税区内企业开展加工贸易不实行银行保证金台帐制度，按《保税区海关监管办法》执行。"},{"i":38,"n":"第三十八条","txt":"加工贸易项下进口，不受一般贸易进口经营分工管理规定的限制，经营企业可自行组织进口。"},{"i":39,"n":"第三十九条","txt":"外经贸部对违犯本办法的审批机关，将予以通报批评，暂停或取消其加工贸易审批权；对发证机关，将予以通报批评，暂停或取消其进口发证权。"},{"i":40,"n":"第四十条","txt":"对违犯本办法的加工贸易企业，将予以通报批评，并通知海关记录违规一次，对情节严惩的，暂停或取消其加工贸易经营权；对触犯刑律的，移交司法机关处理。"},{"i":41,"n":"第四十一条","txt":"本办法自1999年6月1日起执行。"},{"i":42,"n":"第四十二条","txt":"本办法由外经贸部负责解释。此前所发《对外贸易经济合作部关于印发对外加工装配业务有关问题的规定的通知》（[89]外经贸进出灵字第212号）等五个文件同时废止；此前所发其它有关文件规定凡与本办法不一致的，均以本办法为准。 附件： 1.加工贸易业务申请表 2.《进口料件申请备案清单》和《出口制成品及对应进口料件消耗备案清单》 3.加工企业生产能力证明"}],"huafeijinkouguanshuipeieguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为促进公平贸易，按照公开、公正、公平和非歧视的原则管理化肥进口，根据《中华人民共和国货物进出口管理条例》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称化肥进口关税配额是指在公历年度内，国家确定实行关税配额管理的化肥品种以及年度市场准入数量，在确定数量内的进口适用关税配额内税率，超过该数量的进口适用关税配额外税率。"},{"i":3,"n":"第三条","txt":"化肥进口关税配额为全球配额。"},{"i":4,"n":"第四条","txt":"商务部负责全国的化肥关税配额管理工作。"},{"i":5,"n":"第五条","txt":"实行关税配额管理的化肥品种和年度配额总量由商务部对外公布，并同时公布由国务院关税税则委员会确定的关税配额商品税目及配额内外税率。化肥关税配额税号目录见附件一。"},{"i":6,"n":"第六条","txt":"商务部负责化肥进口关税配额的总量管理、发放分配、组织实施和执行协调。 （一）商务部负责在化肥进口关税配额总量内，根据国民经济综合平衡及资源合理配置的要求，对化肥进口关税配额进行分配。 （二）商务部根据化肥关税配额的年度进口执行情况，对化肥进口关税配额的分配予以及时调整。 （三）商务部负责设立化肥进口关税配额咨询点，提供咨询。 （四）商务部对申请、使用化肥进口关税配额的活动进行监督检查。 商务部委托的化肥关税配额管理机构（以下简称\"委托机构\"）负责管辖范围内化肥进口关税配额的发证、统计、咨询和其他委托工作。委托机构名单另行公布。"},{"i":7,"n":"第七条","txt":"海关对化肥进口关税配额商品依法实行监管、征税、稽查和统计，并负责定期公布化肥进口关税配额商品进口情况。"},{"i":8,"n":"第八条","txt":"凡在中华人民共和国工商行政管理部门登记注册的企业（以下简称为\"申请单位\"），在其经营范围内均可向所在地区的委托机构申请化肥进口关税配额。"},{"i":9,"n":"第九条","txt":"商务部将于每年的9月15日至10月14日公布下一年度的关税配额数量。 申请单位应当在每年的10月15日至10月30日向商务部提出化肥关税配额的申请。 申请单位有关关税配额的咨询可向商务部及其委托机构提出，应在10个工作日内答复。"},{"i":10,"n":"第十条","txt":"尿素、磷酸二铵、复合肥的进口，依据本办法第十一条规定的原则进行分配。"},{"i":11,"n":"第十一条","txt":"商务部分配关税配额时，应当考虑下列因素： （一）申请单位以往的进口实绩； （二）申请单位的生产能力、经营规模、销售状况； （三）以往分配的配额是否得到充分使用； （四）新的进口经营者的申请情况； （五）申请配额的数量情况； （六）其他需要考虑的因素。"},{"i":12,"n":"第十二条","txt":"商务部根据各地区生产和市场需求，于每年12月31日前将化肥关税配额分配到进口用户。 商务部或者其委托机构依据本办法签发相应的《化肥进口关税配额证明》（式样格式见附件三），并加盖\"化肥进口关税配额专用章\"（式样格式见附件四）。《化肥进口关税配额证明》需要延期或变更的，一律重新办理，旧证同时撤消。"},{"i":13,"n":"第十三条","txt":"进口化肥关税配额产品时，进口单位向海关提供《化肥进口关税配额证明》的，海关按配额内税率征税。进口关税配额内化肥，海关凭《化肥进口关税配额证明》验放，并按照贸易方式分别统计进口。"},{"i":14,"n":"第十四条","txt":"《化肥进口关税配额证明》和\"化肥进口关税配额专用章\"由商务部统一监制。"},{"i":15,"n":"第十五条","txt":"化肥进口关税配额公历年度内有效，《化肥进口关税配额证明》在公历年度内有效期不超过180天。 化肥关税配额持有者，在配额证明有效期内未完成进口时，可以到原发证机构办理延期手续，最长期限不超过前款规定。"},{"i":16,"n":"第十六条","txt":"化肥关税配额持有者，如在当年无法完成进口的，应当在9月15日前将配额证明退还原发证机构。"},{"i":17,"n":"第十七条","txt":"商务部每年9月15日至30日受理重新分配关税配额的申请，并于当年10月15日前将退回的关税配额重新进行再分配。"},{"i":18,"n":"第十八条","txt":"国家对化肥进口实行国营贸易管理。国营贸易企业名单由商务部确定和公布。 国营贸易企业名单由国家经贸委会同外经贸部确定，由外经贸部对外公布。"},{"i":19,"n":"第十九条","txt":"国营贸易企业按照公开、公平和公正的原则，根据正常的商业条件从事进口经营，不得以非商业因素选择供应商，不得拒绝其他企业或者组织的委托，也不得歧视非国营贸易企业。"},{"i":20,"n":"第二十条","txt":"按照规定的资格和条件，有关企业可以向商务部申请成为非国营贸易企业，由商务部负责认定和公布。"},{"i":21,"n":"第二十一条","txt":"国家可以安排一定数量的关税配额，由非国营贸易企业进口经营。其中： （一）尿素每年不少于10％的关税配额安排非国营贸易企业进口经营； （二）磷酸二铵第一年不少于10％的关税配额安排非国营贸易企业进口经营，以后每年增加5个百分点，最终非国营贸易进口比例达到49％； （三）复合肥第一年不少于10％的关税配额安排非国营贸易企业进口经营，以后每年增加5个百分点，最终非国营贸易进口比例达到49％。"},{"i":22,"n":"第二十二条","txt":"进口关税配额仅限于申请单位自用，《化肥进口关税配额证明》不得转让或者倒卖。对违反规定的，商务部负责收回其《化肥进口关税配额证明》；情节严重的，取消其申请进口关税配额资格；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"配额证明持有者未能在配额证明有效期内完成进口，又未在规定期限内将配额证明退还原发证机构的，商务部将相应扣减其下年度关税配额。"},{"i":24,"n":"第二十四条","txt":"凡具有化肥进口经营权的企业均可按关税配额外税率进口化肥，没有数量限制，无须许可，海关凭进口合同按配额外税率征税验放。"},{"i":25,"n":"第二十五条","txt":"对原产于与中华人民共和国订有关税互惠协议的国家或地区的进口关税配额化肥，按《中华人民共和国海关进出口税则》规定的配额内税率或者配额外优惠税率征税。 对原产于与中华人民共和国未订有关税互惠协议的国家或地区的进口关税配额化肥，按配额外普通税率征税；经国务院关税税则委员会特别批准，也可以按配额内税率或者配额外优惠税率征税。"},{"i":26,"n":"第二十六条","txt":"化肥关税配额的进口经营、购汇等，按照国家有关规定执行。"},{"i":27,"n":"第二十七条","txt":"本办法由商务部、海关总署负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自二○○二年二月一日起施行。"}],"danyongtushangyeyufukaguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强单用途商业预付卡管理，维护当事人合法权益，防范资金风险，根据有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"从事零售业、住宿和餐饮业、居民服务业（具体行业分类表见附件1）的企业法人在中华人民共和国境内开展单用途商业预付卡业务适用本办法。 本办法所称单用途商业预付卡（以下简称单用途卡）是指前款规定的企业发行的，仅限于在本企业或本企业所属集团或同一品牌特许经营体系内兑付货物或服务的预付凭证，包括以磁条卡、芯片卡、纸券等为载体的实体卡和以密码、串码、图形、生物特征信息等为载体的虚拟卡。"},{"i":3,"n":"第三条","txt":"集团发卡企业是指发行在本集团内使用的单用途卡的集团母公司。集团是指由同一企业法人绝对控股的企业法人联合体。 品牌发卡企业是指发行在同一品牌特许经营体系内使用的单用途卡，且拥有该品牌的企业标志或注册商标，或者经授权拥有该企业标志或注册商标排他使用权的法人企业。同一品牌特许经营体系是指使用同一企业标志或注册商标的企业法人联合体。 售卡企业是指集团发卡企业或品牌发卡企业指定的承担单用途卡销售、充值、挂失、换卡、退卡等相关业务的本集团或同一品牌特许经营体系内的企业。"},{"i":4,"n":"第四条","txt":"规模发卡企业是指除集团发卡企业、品牌发卡企业之外的符合下列条件之一的企业： （一）上一会计年度年营业收入500万元以上； （二）工商注册登记不足一年、注册资本在100万元以上。 商务部可以根据具体情况调整规模发卡企业标准，以公告的形式公布。"},{"i":5,"n":"第五条","txt":"商务部负责全国单用途卡行业管理工作。县级以上地方人民政府商务主管部门负责本行政区域内单用途卡监督管理工作。"},{"i":6,"n":"第六条","txt":"单用途卡行业组织按照章程为其成员提供信息咨询和宣传培训等服务，发挥行业自律作用。"},{"i":7,"n":"第七条","txt":"发卡企业应在开展单用途卡业务之日起30日内按照下列规定办理备案： （一）集团发卡企业和品牌发卡企业向其工商登记注册地省、自治区、直辖市人民政府商务主管部门备案； （二）规模发卡企业向其工商登记注册地设区的市人民政府商务主管部门备案； （三）其他发卡企业向其工商登记注册地县（市、区）人民政府商务主管部门备案。"},{"i":8,"n":"第八条","txt":"发卡企业应向备案机关提交下列材料： （一）《单用途卡发卡企业备案表》； （二）《企业法人营业执照》（副本）复印件； 发卡企业为外商投资企业的，还应提交外商投资企业批准证书复印件。 《单用途卡发卡企业备案表》可以从备案机关处领取或通过商务部政府网站（www.mofcom.gov.cn）下载 （格式见附件2）。"},{"i":9,"n":"第九条","txt":"规模发卡企业除提交本办法第八条规定的材料外，还应向备案机关提交下列材料： （一）经审计机构审计的上一年度财务报表（加盖公章），但工商注册登记不足一年的规模发卡企业除外； （二）实体卡样本（正反面）、虚拟卡记载的信息样本； （三）单用途卡业务、资金管理制度； （四）单用途卡购卡章程、协议； （五）资金存管账户信息和资金存管协议。"},{"i":10,"n":"第十条","txt":"集团发卡企业和品牌发卡企业除提交本办法第八条规定的材料外，还应向备案机关提交下列材料： （一）经审计机构审计的上一年度财务报表及合并财务报表（加盖公章），但工商注册登记不足一年的集团发卡企业、品牌发卡企业除外； （二）实体卡样本（正反面）、虚拟卡记载的信息样本； （三）单用途卡业务、资金管理制度； （四）单用途卡购卡章程、协议； （五）资金存管账户信息和资金存管协议； （六）与售卡企业签订的协议文本及售卡企业清单； （七）集团发卡企业提交集团股权关系说明；品牌发卡企业提交企业标志、注册商标所有权或排他使用权证明。"},{"i":11,"n":"第十一条","txt":"备案机关对已备案的发卡企业予以编号，并在商务部和备案机关指定的媒体上公告，提供公众查询服务。"},{"i":12,"n":"第十二条","txt":"备案事项发生变更、发卡企业类型改变或单用途卡业务终止时，发卡企业应在变化之日起15个工作日内向备案机关办理变更、注销手续。"},{"i":13,"n":"第十三条","txt":"企业可发行记名卡和不记名卡，记名卡可挂失。 发卡企业应在实体卡卡面上记载发卡企业名称及联系方式、卡号、使用规则、注意事项等。集团发卡企业还应标明集团名称，品牌发卡企业应标明统一的企业标志或注册商标。虚拟卡也应记载上述信息。已备案的发卡企业可标明备案编号。"},{"i":14,"n":"第十四条","txt":"发卡企业或售卡企业应公示或向购卡人提供单用途卡章程，并应购卡人要求签订购卡协议。发卡企业或售卡企业应履行提示告知义务，确保购卡人知晓并认可单用途卡章程或协议内容。 单用途卡章程和购卡协议应包括以下内容： （一）单用途卡的名称、种类和功能； （二）单用途卡购买、充值、使用、退卡方式，记名卡还应包括挂失、转让方式； （三）收费项目和标准； （四）当事人的权利、义务； （五）纠纷处理原则和违约责任； （六）相关法律法规规章和规范性文件规定的其他事项。"},{"i":15,"n":"第十五条","txt":"个人或单位购买（含充值，下同）记名卡的，或一次性购买1万元（含）以上不记名卡的，发卡企业或售卡企业应要求购卡人及其代理人出示有效身份证件，并留存购卡人及其代理人姓名或单位名称、有效身份证件号码和联系方式。 个人有效身份证件包括居民身份证、户口簿、军人身份证件、武警身份证件、港澳台居民通行证、护照等。单位有效身份证件包括营业执照、事业单位法人证书等。"},{"i":16,"n":"第十六条","txt":"发卡企业和售卡企业应保存购卡人的登记信息5年以上。 发卡企业和售卡企业应对购卡人及其代理人的身份信息和交易信息保密，除法律另有规定外，不得向第三方提供。"},{"i":17,"n":"第十七条","txt":"单位一次性购买单用途卡金额达5000元（含）以上或个人一次性购卡金额达5万元（含）以上的，以及单位或个人采用非现场方式购卡的，应通过银行转账，不得使用现金，发卡企业或售卡企业应对转出、转入账户名称、账号、金额等进行逐笔登记。 发卡企业和售卡企业应严格按照国家有关规定开具发票。"},{"i":18,"n":"第十八条","txt":"单张记名卡限额不得超过5000元，单张不记名卡限额不得超过1000元。 单张单用途卡充值后资金余额不得超过前款规定的限额。"},{"i":19,"n":"第十九条","txt":"记名卡不得设有效期；不记名卡有效期不得少于3年。 发卡企业或售卡企业对超过有效期尚有资金余额的不记名卡应提供激活、换卡等配套服务。"},{"i":20,"n":"第二十条","txt":"使用单用途卡购买商品后需要退货的，发卡企业或受理企业应将资金退至原卡。原单用途卡不存在或退货后卡内资金余额超过单用途卡限额的，应退回至持卡人在同一发卡企业的同类单用途卡内。 退货金额不足100元（含）的，可支付现金。"},{"i":21,"n":"第二十一条","txt":"发卡企业或售卡企业应依单用途卡章程或协议约定，提供退卡服务。 办理退卡时，发卡企业或售卡企业应要求退卡人出示有效身份证件，并留存退卡人姓名、有效身份证件号码、退卡卡号、金额等信息。 发卡企业或售卡企业应将资金退至与退卡人同名的银行账户内，并留存银行账户信息。卡内资金余额不足100元（含）的，可支付现金。"},{"i":22,"n":"第二十二条","txt":"发卡企业终止兑付未到期单用途卡的，发卡企业和售卡企业应向持卡人提供免费退卡服务，并在终止兑付日前至少30日在备案机关指定的媒体上进行公示。"},{"i":23,"n":"第二十三条","txt":"发卡企业和售卡企业应定期核对与单用途卡业务相关的账务，及时对交易数据进行记录和清算。"},{"i":24,"n":"第二十四条","txt":"发卡企业应对预收资金进行严格管理。预收资金只能用于发卡企业主营业务，不得用于不动产、股权、证券等投资及借贷。"},{"i":25,"n":"第二十五条","txt":"主营业务为零售业、住宿和餐饮业的发卡企业，预收资金余额不得超过其上一会计年度主营业务收入的40%；主营业务为居民服务业的发卡企业的预收资金余额不得超过其上一会计年度主营业务收入；工商注册登记不足一年的发卡企业的预收资金余额不得超过其注册资本的2倍。 集团发卡企业预收资金余额不得超过其上一会计年度本集团营业收入的30%。 本办法所称预收资金是指发卡企业通过发行单用途卡所预收的资金总额，预收资金余额是指预收资金扣减已兑付商品或服务价款后的余额。"},{"i":26,"n":"第二十六条","txt":"规模发卡企业、集团发卡企业和品牌发卡企业实行资金存管制度。规模发卡企业存管资金比例不低于上一季度预收资金余额的20%；集团发卡企业存管资金比例不低于上一季度预收资金余额的30%；品牌发卡企业存管资金比例不低于上一季度预收资金余额的40%。"},{"i":27,"n":"第二十七条","txt":"规模发卡企业、集团发卡企业和品牌发卡企业应确定一个商业银行账户作为资金存管账户，并与存管银行签订资金存管协议。 资金存管协议应规定存管银行对发卡企业资金存管比例进行监督，对超额调用存管资金的指令予以拒绝，并按照备案机关要求提供发卡企业资金存缴情况。"},{"i":28,"n":"第二十八条","txt":"规模发卡企业、集团发卡企业和品牌发卡企业可以使用担保预收资金的保证保险、银行保函等方式冲抵全部或部分存管资金。"},{"i":29,"n":"第二十九条","txt":"规模发卡企业、集团发卡企业和品牌发卡企业应在境内建立与发行单用途卡规模相适应的业务处理系统，并保障业务处理系统信息安全和运行质量。 发生重大或不可恢复的技术故障时，规模发卡企业、集团发卡企业、品牌发卡企业应立即向备案机关报告。"},{"i":30,"n":"第三十条","txt":"发卡企业应将单用途卡业务纳入日常管理，制定预收资金结算、风险管理、日常监督、应急处置等制度。"},{"i":31,"n":"第三十一条","txt":"规模发卡企业应于每季度结束后15个工作日内，集团发卡企业和品牌发卡企业应于每季度结束后20个工作日内登录商务部“单用途商业预付卡业务信息系统”，填报上一季度单用途卡业务情况。其他发卡企业应于每年1月31日前填报《发卡企业单用途卡业务报告表》（格式见附件3）。 发卡企业填报的信息应当准确、真实、完整，不得故意隐瞒或虚报。"},{"i":32,"n":"第三十二条","txt":"省、自治区、直辖市人民政府商务主管部门应制定专项应急预案，积极预防、妥善处理本行政区域内涉及单用途卡业务的重大突发性事件，并及时上报商务部。"},{"i":33,"n":"第三十三条","txt":"商务部和地方人民政府商务主管部门应对发卡企业和售卡企业的单用途卡业务活动、内部控制和风险状况等进行定期或不定期的现场及非现场检查。发卡企业和售卡企业应配合商务主管部门的检查。"},{"i":34,"n":"第三十四条","txt":"商务部应建立健全“单用途商业预付卡业务信息系统”。地方人民政府商务主管部门应充分运用信息化手段加强对发卡企业的监督管理。"},{"i":35,"n":"第三十五条","txt":"商务部和地方人民政府商务主管部门应通过12312商务举报投诉服务平台接受与本办法有关的举报和投诉。"},{"i":36,"n":"第三十六条","txt":"发卡企业违反本办法第七条规定的，由违法行为发生地县级以上地方人民政府商务主管部门责令限期改正；逾期仍不改正的，处以1万元以上3万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"发卡企业或售卡企业违反本办法第十四条至第二十二条规定的，由违法行为发生地县级以上地方人民政府商务主管部门责令限期改正；逾期仍不改正的，处以1万元以上3万元以下罚款。 发卡企业违反本办法第二十四条至第二十七条、第三十一条规定的，由备案机关责令限期改正；逾期仍不改正的，处以1万元以上3万元以下罚款。 集团发卡企业、品牌发卡企业疏于管理，其隶属的售卡企业12个月内3次违反本办法规定受到行政处罚的，备案机关可以对集团发卡企业、品牌发卡企业处以3万元以下罚款。"},{"i":38,"n":"第三十八条","txt":"发卡企业违反本办法第二十九条规定，造成重大损失的，由备案机关处以1万元以上3万元以下罚款。"},{"i":39,"n":"第三十九条","txt":"发卡企业和售卡企业违反本办法受到行政处罚的，由实施处罚的商务主管部门在指定媒体上公示处罚信息。"},{"i":40,"n":"第四十条","txt":"已开展单用途卡业务的发卡企业应在本办法实施之日起90日内完成备案。"},{"i":41,"n":"第四十一条","txt":"动力燃料销售企业发行的，用于为确定的生产经营性车辆兑付动力燃料的记名预付凭证，不适用本办法。"},{"i":42,"n":"第四十二条","txt":"本办法自2012年11月1日起实施。 附件： 1.单用途卡发卡企业备案表 2.单用途商业预付卡行业分类表 3.发卡企业单用途卡业务报告表"}],"yuanyouchengpinyouhuafeiguoyingmaoyijinkoujingying934eed":[{"i":1,"n":"第一条","txt":"为规范原油、成品油、化肥的进口经营管理，维护正常的经营秩序，维护消费者利益，促进对外贸易发展，根据《中华人民共和国货物进出口管理条例》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家对原油、成品油、化肥进口实行国营贸易管理。原油、成品油、化肥具体税号由对外贸易经济合作部（以下简称“外经贸部”）会同国家经济贸易委员会（以下简称“国家经贸委”）、海关总署制定、调整，外经贸部负责公布。"},{"i":3,"n":"第三条","txt":"外经贸部负责原油、成品油、化肥国营贸易和非国营贸易的进口经营管理工作。"},{"i":4,"n":"第四条","txt":"国营贸易企业是经国家特许，获得从事某类国营贸易管理货物进口经营权的企业或机构。"},{"i":5,"n":"第五条","txt":"国营贸易企业名录由外经贸部确定、调整并公布。 外经贸部在确定和调整国营贸易企业名录时商国家经贸委。"},{"i":6,"n":"第六条","txt":"对实行国营贸易管理的货物，国家允许非国营贸易企业从事部分数量的进口。"},{"i":7,"n":"第七条","txt":"具有对外贸易经营资格以及经营国营贸易管理货物必备条件的企业，经外经贸部登记备案，可成为非国营贸易企业。外经贸部在办理登记备案手续前将征求国家经贸委的意见。 前款规定的条件由外经贸部会同国家经贸委制定，并由外经贸部公布。"},{"i":8,"n":"第八条","txt":"原油、成品油、化肥的进口数量包括国营贸易进口数量和非国营贸易进口数量。"},{"i":9,"n":"第九条","txt":"国营贸易企业在外经贸部和国家经贸委指导下从事国营贸易业务。"},{"i":10,"n":"第十条","txt":"国营贸易企业在每季度结束后10个工作日内将该季度国营贸易进口管理货物的市场供求情况、购买价格和销售价格等有关信息报送外经贸部和国家经贸委。 外经贸部负责向世界贸易组织有关机构通报相关信息。"},{"i":11,"n":"第十一条","txt":"非国营贸易企业应当根据正常的商业条件从事经营活动，接受外经贸部、国家经贸委的监督。"},{"i":12,"n":"第十二条","txt":"除本办法第二十条、第二十一条规定的情况外，国营贸易企业和非国营贸易企业以外的其他企业，不得从事原油、成品油、化肥的进口业务。"},{"i":13,"n":"第十三条","txt":"对化肥进口，国营贸易配额持有者必须委托国营贸易企业进口 非国营贸易配额持有者可以委托国营贸易企业或非国营贸易企业进口，具备非国营贸易企业资格的配额持有者也可以一自行进口。 海关凭化肥关税配额管理机构签发的《化肥进口关税配额证明》，初按关税配额内税率征税验放。"},{"i":14,"n":"第十四条","txt":"对成品油进口，国营贸易配额持有者必须委托国营贸易企业进口。 非国营贸易配额持有者可以委托国营贸易企业或非国营贸易企业进口，具备非国营贸易企业资格的配额持有者也可以自行进口。 海关凭许可证发证机构签发的成品油进口许可证验放。"},{"i":15,"n":"第十五条","txt":"对原油国营贸易进口，国营贸易企业按照有关规定向自动进口许可管理机构申领自动进口许可证明。 对原油非国营贸易进口，自动进口许可管理机构在公布的原油非国营贸易进口数量（包括结转的前一年度来使用完的非国营贸易进口数量）内发放自动进口许可证明，达到该数量后不再向非国营贸易企业发放原油的自动进口许可证明。 海关对原油进口凭自动进口许可管理机构签发的自动进口许可证办理验放手续。"},{"i":16,"n":"第十六条","txt":"国营贸易企业或非国营贸易企业接受委托后，必须与委托人签订书面委托合同，并据此与外商签订进口合同。 委托合同和进口合同的条款，必须符合国家法律、法规规定。 禁止国营贸易企业或非国营贸易企业以“四自三不见”（即自带客户，自带货源，自带汇票，自行报关和不见进口产品，不见供货货主，不见外商）的方式代理进口。"},{"i":17,"n":"第十七条","txt":"对未接本办法第十三条、第十四条、第十五条和第十六条规定执行的，关税配额、配额许可证和自动进口许可的管理机构不予签发关税配额证明、进口许可证或自动进口许可证明等证明文件。"},{"i":18,"n":"第十八条","txt":"国营贸易企业违反本办法第九条、第十条、第十六条规定的，由外经贸部会同国家经贸委予以警告，并责令限期改正；情节严重的，可以暂停直至取消其国营贸易企业资格。"},{"i":19,"n":"第十九条","txt":"对违反本办法第十一条、第十二条规定，擅自从事国营贸易管理货物进口贸易，扰乱市场秩序的企业，外经贸部可以暂停直至撤销其对外贸易经营资格。"},{"i":20,"n":"第二十条","txt":"凡具有对外贸易经营资格的企业都可以按关税配额外税率进口化肥。"},{"i":21,"n":"第二十一条","txt":"加工贸易方式进口原油、成品油、化肥按现行有关规定执行。 保税仓库、保税区、出口加工区进口原油、成品油、化肥不适用本办法，由海关按现行规定验放并实施监管。"},{"i":22,"n":"第二十二条","txt":"本办法由外经贸部负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自公布之日起3O天后实施。此前有关规定凡与本办法规定不一致的，一律以本办法为准。"}],"fanqingxiaochanyesunhaidiaochaguiding":[{"i":1,"n":"第一条","txt":"为规范反倾销产业损害调查，根据《中华人民共和国反倾销条例》（以下简称反倾销条例），制定本规定。"},{"i":2,"n":"第二条","txt":"依据反倾销条例进行的反倾销产业损害调查相关活动，适用本规定。"},{"i":3,"n":"第三条","txt":"中华人民共和国商务部（以下简称商务部）负责反倾销产业损害的调查。涉及农产品的反倾销产业损害调查，由商务部会同农业部进行。"},{"i":4,"n":"第四条","txt":"损害，是指倾销对已经建立的国内产业造成实质损害或者产生实质损害威胁，或者对建立国内产业造成实质阻碍。 实质损害是指对国内产业已经造成的、不可忽略的损害。 实质损害威胁是指对国内产业尚未造成实质损害，但有证据表明如果不采取措施将导致国内产业实质损害发生的明显可预见和迫近的情形。 实质阻碍是对国内产业未造成实质损害或者实质损害威胁，但严重阻碍了国内产业的建立。"},{"i":5,"n":"第五条","txt":"在确定倾销对国内产业造成的损害时，应当审查以下事项： （一）倾销进口产品的数量和倾销进口产品对国内同类产品价格的影响； （二）倾销进口产品对国内产业的影响。"},{"i":6,"n":"第六条","txt":"对倾销进口产品数量的审查，应包括倾销进口产品的绝对数量是否大量增加，或相对于国内同类产品生产或消费数量是否大量增加； 审查倾销进口产品对国内同类产品价格的影响，应考察与国内同类产品价格相比，倾销进口产品是否大幅削价销售，或者倾销进口产品是否大幅压低国内同类产品价格，或在很大程度上抑制国内同类产品本应发生的价格增长。"},{"i":7,"n":"第七条","txt":"审查倾销进口产品对国内产业的影响，应包括对影响国内产业状况的所有有关经济因素和指标的评估，包括销售、利润、产量、市场份额、生产率、投资收益状况或设备利用率存在的实际或潜在的下降；影响国内价格的因素；倾销幅度的大小；现金流、库存、就业、工资、产业增长、筹资或投资能力受到的实际或潜在的负面影响。"},{"i":8,"n":"第八条","txt":"实质损害威胁应当根据明显可预见和迫近的情形来判断，并且如果不采取措施，实质损害将会发生。对实质损害威胁的确定，应当依据事实，不得仅依据指控、推测或者极小的可能性。 确定实质损害威胁，还应审查但不限于以下因素： （一）表明进口很可能发生实质增长的倾销产品进口的大幅增长率； （二）出口商可充分自由使用的、或即将实质增加的能力，表明进入进口成员市场的倾销出口可能发生实质增长。在采用这一指标时应考虑是否存在其它出口市场吸收任何额外的出口； （三）进口产品是否正以将大幅压低或抑制国内同类产品价格的价格进口，并且将很可能导致对进口产品需求的增加； （四）被调查产品的库存情况。"},{"i":9,"n":"第九条","txt":"确定对建立国内产业的实质阻碍，除了第八条的因素外，还应审查但不限于以下因素： （一）国内产业的建立或筹建情况； （二）国内需求的增长情况及其影响； （三）倾销进口产品对国内市场状况的影响； （四）倾销进口产品的后续生产能力和在国内市场的发展趋势。"},{"i":10,"n":"第十条","txt":"同类产品，是指与倾销进口产品相同的产品；没有相同产品的，以与倾销进口产品的特性最相似的产品为同类产品。"},{"i":11,"n":"第十一条","txt":"在确定同类产品时，可以考虑以下因素：产品的物理特征、化学性能、生产设备和工艺、产品用途、产品的可替代性、消费者和生产者的评价、销售渠道、价格等。"},{"i":12,"n":"第十二条","txt":"倾销进口产品对国内产业的影响，应当根据对国内同类产品生产的单独界定进行评估。如果根据生产工艺、生产者的销售和利润等标准不能对国内同类产品的生产与其他产品的生产分别界定，则可以根据包括国内同类产品在内的最窄产品组或产品范围的产品生产来确定进口倾销产品的影响，只要这种产品组或产品范围能够提供足够的信息。"},{"i":13,"n":"第十三条","txt":"在确定国内产业时，应当考虑中国国内同类产品的全部生产者，或者其总产量占国内同类产品全部总产量的主要部分的生产者；但是，国内生产者与出口经营者或者进口经营者有关联，或者其本身就是倾销产品的进口经营者的，可以排除在国内产业之外。 前款所称有关联，是指其中的一方直接或者间接地控制或影响另一方，或者双方直接或者间接地受第三方的控制或影响，或者双方共同直接地或者间接地影响第三方等情形。"},{"i":14,"n":"第十四条","txt":"在确定区域产业时，应当考虑以下因素： （一）生产者在该区域市场出售全部或者几乎全部其所生产的同类产品； （二）该区域市场的需求不是由或者大部分不是由国内其他区域范围的同类产品的生产者提供； （三）其他因素。"},{"i":15,"n":"第十五条","txt":"倾销进口产品来自两个以上国家（地区），并且同时满足下列条件的，可以就倾销进口产品对国内产业造成的影响进行累积评估： （一）来自每一国家（地区）的倾销进口产品的倾销幅度不小于2％，并且其进口量不属于可忽略不计的； （二）根据倾销进口产品之间以及倾销进口产品与国内同类产品之间的竞争条件，进行累积评估是适当的。 前款所称可忽略不计，是指来自一个国家（地区）的倾销进口产品的数量占同类产品总进口量的比例低于3％；但是，低于3％的若干国家（地区）的总进口量超过同类产品总进口量7％的除外。"},{"i":16,"n":"第十六条","txt":"在进行累积评估时，可以考虑以下因素： （一）来自不同国家（地区）的倾销进口产品对国内产业损害的持续性和可能性等情况； （二）来自不同国家（地区）的倾销进口产品与国内同类产品之间的可替代程度，包括特定客户的要求及产品质量等相关因素； （三）来自不同国家（地区）的倾销进口产品和国内同类产品在同一地区的市场上的销售价格、卖方报价和实际成交价格； （四）来自不同国家（地区）的倾销进口产品和国内同类产品是否存在相同或者相似的销售渠道，是否在市场上同时出现； （五）倾销进口产品之间以及倾销进口产品与国内同类产品之间的其他竞争条件； （六）其他因素。"},{"i":17,"n":"第十七条","txt":"商务部在进行产业损害调查时，应当为倾销进口产品的使用者、消费者等提供陈述意见、提交证据的机会。"},{"i":18,"n":"第十八条","txt":"反倾销案件的产业损害调查期通常为立案调查开始前的三至五年。"},{"i":19,"n":"第十九条","txt":"利害关系方申请应诉产业损害调查的，应当自反倾销调查立案公告发布之日起20日内向商务部提出应诉申请，办理应诉登记；同时应提供产业损害调查期内应诉申请人的生产能力、产量、库存以及在建和扩建的计划；向中国出口该产品的数量及金额；进口经营者进口的数量及金额等情况。"},{"i":20,"n":"第二十条","txt":"利害关系方包括以下范围： （一）被调查产品的外国（地区）生产者、出口经营者、国内进口经营者，或者该产品生产者、出口经营者、进口经营者的行业组织或者其他组织； （二）被调查产品的原产国（地区）、出口国（地区）的政府及其代表； （三）国内同类产品的生产者、经营者，或者该产品生产者、经营者的行业组织或者其他组织； （四）其他。"},{"i":21,"n":"第二十一条","txt":"利害关系方参加调查活动，应当出具相关身份证明。利害关系方为企业或者其他组织的，应当出具营业执照等登记证明、法定代表人身份证明。 委托代理人参加调查活动的，应当出具代理人身份证明及授权委托书；委托律师作代理人的，应当委托中国律师事务所及中国执业律师，并应当出具授权委托书、律师事务所营业执照、律师执业证明。"},{"i":22,"n":"第二十二条","txt":"商务部反倾销产业损害调查的对象包括国内生产者、国内进口经营者、国内购买者、国内最终消费者、国外出口经营者、国外生产者等。"},{"i":23,"n":"第二十三条","txt":"商务部认为有必要的，可以聘请有关产业、财会、经贸、法律等方面的专家提供咨询意见。有关专家应当承担相应的保密责任。"},{"i":24,"n":"第二十四条","txt":"商务部采取问卷、抽样、听证、技术鉴定、实地核查等调查方式进行产业损害调查。"},{"i":25,"n":"第二十五条","txt":"商务部向利害关系方发放的调查问卷包括国内生产者调查问卷，国内进口商调查问卷，国外生产者、国外出口商调查问卷或者其他类型的调查问卷。"},{"i":26,"n":"第二十六条","txt":"利害关系方应按问卷规定的方式和时间返回答卷。如需延期，应当在答卷截止日期的7日前向商务部提出书面申请并说明理由。是否同意延期，由商务部决定。"},{"i":27,"n":"第二十七条","txt":"商务部可以对利害关系方进行实地核查。实地核查前，应当将核查的主要目的和内容提前通知有关利害关系方。"},{"i":28,"n":"第二十八条","txt":"应利害关系方请求或者根据调查需要，经有关国家（地区）同意，商务部可以派出人员赴该国家（地区）对有关产品的生产能力、投资扩产、库存、原产或转口及企业间的关联关系等情况进行调查。"},{"i":29,"n":"第二十九条","txt":"商务部可以要求利害关系方按照规定提交或者补充书面材料，利害关系方也可以主动向商务部提交书面材料。"},{"i":30,"n":"第三十条","txt":"应利害关系方的请求，或者商务部认为有必要的，可以举行产业损害听证。"},{"i":31,"n":"第三十一条","txt":"应诉产业损害调查的利害关系方认为其所提供的资料及相关证据有必要保密的，应当在提交资料的同时向商务部提交该资料的非保密概要，或者分别提交该资料的保密文本和公开文本。 非保密概要和公开文本应当合理表达保密信息的实质内容。未表达实质内容的，商务部可以要求其补充相关内容和证据资料。"},{"i":32,"n":"第三十二条","txt":"应诉产业损害调查的利害关系方不提供资料及相关证据的非保密概要或公开文本的，或者不提交非保密概要或公开文本理由不充分的，商务部可以对该资料不予考虑。商务部如果认为提供的资料不需要保密时，可以要求利害关系方撤销保密申请。"},{"i":33,"n":"第三十三条","txt":"在产业损害调查过程中，应诉产业损害调查的利害关系方应当如实反映情况，提供有关资料。利害关系方不如实反映情况、提供有关资料的，或者没有在合理时间内提供必要信息的，或者以其他方式严重妨碍调查的，商务部可以根据已经获得的事实和可获得的最佳信息作出裁定。"},{"i":34,"n":"第三十四条","txt":"应诉产业损害调查的利害关系方在向商务部提交任何文件及证据材料时，均应提交中文正本一式5份，并同时提交相应的电子文本（计算机软盘或光盘）一式3份。"},{"i":35,"n":"第三十五条","txt":"商务部产业损害调查，依据国家语言文字主管部门规定的通用语言文字为正式语言和文字。利害关系方所提供的任何文件、资料、信息应当为通用语言文字。非通用语言文字资料应提交规范汉字译文及原文，并以译文为准。非通用语言文字资料如未附有译文将不被视为有效的和合法的证据材料。"},{"i":36,"n":"第三十六条","txt":"本规定由商务部负责解释。"},{"i":37,"n":"第三十七条","txt":"本规定自公布之日起30日后施行。本规定施行之日，原国家经贸委颁布的《反倾销产业损害调查与裁决规定》（国家经贸委令[2002]第45号）同时废止。"}],"fanqingxiaojiagechengnuozanxingguize":[{"i":1,"n":"第一条","txt":"为保证反倾销措施合理、有效的实施，根据《中华人民共和国反倾销条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"本规则所指价格承诺，是指应诉出口商、生产商向外经贸部自愿作出的，改变价格或者停止以倾销价格出口被调查产品并经外经贸部接受而中止或终止调查的承诺。"},{"i":4,"n":"第四条","txt":"应诉出口商、生产商可向外经贸部提出价格承诺；外经贸部也可向应诉出口商、生产商提出价格承诺的建议。"},{"i":5,"n":"第五条","txt":"外经贸部不得强迫有关出口商、生产商作出价格承诺。出口商、生产商不作出价格承诺或者不接受价格承诺建议，不得对其倾销及倾销幅度的确定产生不利影响。"},{"i":6,"n":"第六条","txt":"价格承诺的提出不得晚于初步裁决公告后45天。"},{"i":7,"n":"第七条","txt":"在对倾销和损害作出肯定的初步裁决前，外经贸部不得向出口商、生产商提出价格承诺的建议或者接受其提出的价格承诺。"},{"i":8,"n":"第八条","txt":"有关出口商、生产商提出的价格承诺包含保密信息的，可以向外经贸部提出保密申请，并提供该保密信息的非保密概要。"},{"i":9,"n":"第九条","txt":"外经贸部收到有关出口商、生产商提出的价格承诺后应当通知其他利害关系方，并提供非保密文本供其评论。评论应当在通知中规定的期限内以书面方式提出。"},{"i":10,"n":"第十条","txt":"外经贸部在考虑是否接受价格承诺时，应当审查下列因素： （一）是否可以消除倾销所造成的损害； （二）是否具备行之有效的措施予以监控； （三）是否符合中华人民共和国的公共利益； （四）是否存在规避的可能性； （五）外经贸部认为需要审查的其他因素。"},{"i":11,"n":"第十一条","txt":"外经贸部只接受在调查期间充分合作的出口商、生产商提出的价格承诺。"},{"i":12,"n":"第十二条","txt":"外经贸部认为出口商、生产商作出的价格承诺可以接受的，经商国家经贸委后，可以决定中止或者终止对提出价格承诺的出口商、生产商的反倾销调查。 中止或者终止反倾销调查的决定由外经贸部予以公告。"},{"i":13,"n":"第十三条","txt":"外经贸部认为不宜接受价格承诺的，应当将拒绝 承诺的理由通知该出口商、生产商，并给予其对此充分发表意见的机会。 拒绝价格承诺的决定和理由应当在终裁决定中写明。"},{"i":14,"n":"第十四条","txt":"价格承诺应当包括但不限于以下内容： （一）产品范围； （二）参考价格，包括价格的确定，提价方式，提价幅度，分阶段调整等； （三）报告义务； （四）接受实地核查的明确表示； （五）不规避价格承诺的保证； （六）外经贸部认为应包含的其他内容。"},{"i":15,"n":"第十五条","txt":"承诺的提价幅度应当与初步裁决确定的倾销幅度相当；如果提价幅度低于倾销幅度，但足以消除国内产业损害，则提价幅度可低于倾销幅度。"},{"i":16,"n":"第十六条","txt":"价格承诺自中止或者终止反倾销调查决定公告之日起开始生效，有效期为五年。 如外经贸部仅接受了部分出口商、生产商提出的价格承诺，则上款规定的有效期应当自对其他出口商、生产商的反倾销调查结束之日起计算。"},{"i":17,"n":"第十七条","txt":"外经贸部可以通过下列方式对价格承诺的履行进行监督： （一）要求作出价格承诺的出口商、生产商定期提供履行承诺的有关情况，包括出口的实际数量和价格、进口商名称； （二）定期向海关核实作出承诺的出口商、生产商向中华人民共和国出口被调查产品的数据； （三）对作出承诺的出口商、生产商进行定期或不定期的实地核查； （四）向做出承诺的出口商、生产商的国内进口商了解、核实有关情况； （五）外经贸部认为适宜的其他方式。"},{"i":18,"n":"第十八条","txt":"依照《中华人民共和国反倾销条例》第三十三条第一款规定中止或者终止反倾销调查后，应有关出口商、生产商的请求或者调查机关认为有必要，调查机关可以对倾销和损害继续进行调查。"},{"i":19,"n":"第十九条","txt":"根据本规则第十八条继续调查的，如果根据调查结果作出倾销和损害的肯定裁决，价格承诺继续有效。"},{"i":20,"n":"第二十条","txt":"根据本规则第十八条继续调查的，如果根据调查结果作出倾销的否定裁决的，相关出口商、生产商的价格承诺自动失效。 如果根据调查结果作出损害的否定裁决的，依据《中华人民共和国反倾销条例》第二十七条第（二）款的规定，反倾销调查应当终止，出口商、生产商的价格承诺也应当自动失效。"},{"i":21,"n":"第二十一条","txt":"根据本规则第十八条继续调查的，如果因为存在价格承诺，调查机关才没有作出存在倾销或损害的肯定裁定的，外经贸部可以决定在一个合理的期限内维持该价格承诺。"},{"i":22,"n":"第二十二条","txt":"外经贸部如认为继续执行价格承诺不再符合中华人民共和国公共利益，可以撤销接受该价格承诺的决定。"},{"i":23,"n":"第二十三条","txt":"外经贸部应当在撤销生效前的合理时间内将此意向通知作出价格承诺的出口商、生产商，并给予该出口商、生产商充分的机会就此进行评论。"},{"i":24,"n":"第二十四条","txt":"作出价格承诺的出口商、生产商可以在价格承诺有效期内的任何时候撤回承诺，但应当提前三十天向外经贸部提出。"},{"i":25,"n":"第二十五条","txt":"外经贸部决定撤销接受价格承诺决定的，或作出承诺的国外出口商、生产商撤回价格承诺的，外经贸部应当通知海关自撤销或撤回生效之日起按原初步裁决实施临时反倾销措施，并立即恢复反倾销调查； 如果原反倾销调查已经完成并最终为该出口商、生产商确定了倾销幅度，应当自撤销或撤回生效之日起开始征收反倾销税。"},{"i":26,"n":"第二十六条","txt":"有下列情况之一的，为违反价格承诺： （一）以低于承诺的价格出口的； （二）未按承诺定期提供履行承诺有关情况的； （三）拒绝外经贸部对其所提供的数据和其他信息进行核查的； （四）提供的数据和其他信息存在严重不实的； （五）存在明显的规避行为的； （六）有其他违反价格承诺行为的。"},{"i":27,"n":"第二十七条","txt":"出口商、生产商违反价格承诺的，外经贸部应当立即恢复反倾销调查，并根据可获得的最佳信息，立即采取临时反倾销措施。 如果最终裁定确定存在倾销，应当根据《中华人民共和国反倾销条例》第三十八条的规定征收反倾销税，并可以对临时反倾销措施实施前90天内进口的被调查产品追溯征收反倾销税，但违反价格承诺前进口的产品除外。 终裁确定的反倾销税高于临时反倾销税或高于所交纳的保证金金额的，差额部分应当补征；终裁确定的反倾销税低于临时反倾销税或低于所交纳的保证金金额的，差额部分应当予以退还。"},{"i":28,"n":"第二十八条","txt":"出口商、生产商违反价格承诺的，如原反倾销调查已经完成，并为违反价格承诺的国外出口商、生产商确定了倾销幅度，应当立即按《中华人民共和国反倾销条例》第三十八条的规定征收反倾销税，并可以对征收反倾销税前9O天内进口的被调查产品追溯征收反倾销税，但违反价格承诺前进口的产品除外。"},{"i":29,"n":"第二十九条","txt":"价格承诺可以与有关出口国（地区）政府达成。"},{"i":30,"n":"第三十条","txt":"价格承诺应当在生效后7天内通知世贸组织反倾销措施委员会。"},{"i":31,"n":"第三十一条","txt":"本规则由外经贸部负责解释。"},{"i":32,"n":"第三十二条","txt":"本规则自2002年4月15日起实施。"}],"fanqingxiaohefanbutiediaochatingzhenghuiguize":[{"i":1,"n":"第一条","txt":"为了规范反倾销和反补贴调查听证程序，保障反倾销和反补贴调查的公平、公正，根据《中华人民共和国反倾销条例》和《中华人民共和国反补贴条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"商务部（以下称调查机关）在反倾销和反补贴案件调查程序中举行听证会，适用本规则。"},{"i":3,"n":"第三条","txt":"调查机关可以依申请举行听证会，以向所有利害关系方提供与具有相反利益的当事方见面的机会，以便陈述对立的观点和提出反驳的论据。 调查机关认为有必要时，可以自行决定举行听证会。"},{"i":4,"n":"第四条","txt":"《中华人民共和国反倾销条例》第十九条和《中华人民共和国反补贴条例》第十九条规定的利害关系方，包括反补贴调查中的出口国（地区）政府，均可申请举行听证会。"},{"i":5,"n":"第五条","txt":"利害关系方要求在初裁前举行听证会的，应在立案之日起四个月内向调查机关提出书面申请。 利害关系方要求在初裁后举行听证会的，应在初裁公告之日起三十日内向调查机关提出书面申请。"},{"i":6,"n":"第六条","txt":"听证会申请书应当包括下列内容： （一）申请人的名称、地址和联系方式等有关信息； （二）申请事项； （三）申请所依据的事实和理由。"},{"i":7,"n":"第七条","txt":"调查机关应当自收到利害关系方提交的申请书后十五个工作日内作出是否举行听证会的决定。"},{"i":8,"n":"第八条","txt":"调查机关举行听证会，应当考虑保密的需要和当事人的方便。"},{"i":9,"n":"第九条","txt":"申请书不符合本规则第六条规定，或者调查机关认为没有必要举行听证会、或者举行听证会将严重阻碍调查程序进行的，调查机关可以决定不举行听证会。"},{"i":10,"n":"第十条","txt":"调查机关决定不举行听证会的，应当书面通知听证会申请人，并说明理由。 调查机关决定不举行听证会、但利害关系方有正当理由要求口头表达意见的，调查机关应当以其他方式为其提供口头表达意见的机会。"},{"i":11,"n":"第十一条","txt":"调查机关决定举行听证会的，应当以适当形式通知各利害关系方，并将通知送交商务部贸易救济公开信息查阅室。该适当形式包括书面通知、网上公布及其他形式。"},{"i":12,"n":"第十二条","txt":"调查机关举行听证会的通知应当包括下列内容： （一）举行听证会的理由； （二）听证事项； （三）利害关系方报名参加听证会的时限和方式。"},{"i":13,"n":"第十三条","txt":"利害关系方均有权按照调查机关规定的时限和方式报名参加听证会。任何一方均无必须出席听证会的义务。未出席听证会不损害该利害关系方通过其他方式向调查机关表达意见并陈述理由的正当权利。"},{"i":14,"n":"第十四条","txt":"报名参加听证会的利害关系方，应当在调查机关规定的时限内将参加听证会的人员名单报送调查机关。"},{"i":15,"n":"第十五条","txt":"报名参加听证会并要求在听证会上发言的利害关系方，应当在调查机关规定的时限内提交发言概要。调查机关应当将发言概要送交商务部贸易救济公开信息查阅室供各利害关系方查阅。"},{"i":16,"n":"第十六条","txt":"调查机关应当在合理期限之前，将举行听证会的方式、时间、地点和听证会议程等事项通知已报名参加听证会的利害关系方。"},{"i":17,"n":"第十七条","txt":"参加听证会的利害关系方应当遵守听证会纪律。对违反听证会纪律的，听证会主持人有权提出警告、制止，必要时可责令退场。"},{"i":18,"n":"第十八条","txt":"在听证会上发言的利害关系方应当围绕听证事项进行陈述。对超出听证事项范围的，听证会主持人有权制止。"},{"i":19,"n":"第十九条","txt":"利害关系方对主持人的询问应当如实回答。"},{"i":20,"n":"第二十条","txt":"在听证会上发言的利害关系方应当在听证会结束后，按照调查机关要求的时限和方式，就其发言内容向调查机关提交书面材料。调查机关应当将书面材料送交商务部贸易救济公开信息查阅室供利害关系方查询。 利害关系方未按照前款规定以书面形式提交的听证会上的口头发言，调查机关可以不予考虑。"},{"i":21,"n":"第二十一条","txt":"听证会使用的工作语言为中文。以其他语言发言的，应当自行配备翻译，发言内容以翻译为准。"},{"i":22,"n":"第二十二条","txt":"本规则由商务部负责解释。"},{"i":23,"n":"第二十三条","txt":"本规则自2018年5月4日起施行。《反倾销调查听证会暂行规则》（对外贸易经济合作部令2002年第3号）、《反补贴调查听证会暂行规则》（对外贸易经济合作部令2002年第10号）和《产业损害调查听证规则》（国家经济贸易委员会令第44号）同时废止。"}],"fanqingxiaoxinchukoushangfushenzanxingguize":[{"i":1,"n":"第一条","txt":"为保证新出口商复审的公平、公正、公开，根据《中华人民共和国反倾销条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"本规则适用于原反倾销调查期内未向中华人民共和国出口过被调查产品的涉案国（地区）出口商、生产商（以下称新出口商）。在原反倾销措施生效后要求为其确定单独反倾销税率的复审。"},{"i":4,"n":"第四条","txt":"新出口商复审申请人不得与在原反倾销调查期内向中华人民共和国出口过被调查产品的出口商、生产商具有关联关系。 如果新出口商复审申请人为贸易商，除应符合前款规定外，其供应商也不得是在原反倾销调查期内向中华人民共和国出口过被调查产品的出口商、生产商或与上述出口商、生产商具有关联关系。"},{"i":5,"n":"第五条","txt":"新出口商复审申请人必须在原反倾销调查期后曾向中华人民共和国实际出口过被调查产品。 前款所述出口应达到一定的数量，足以构成确定正常出口价格的基础。该数量按被调查产品的正常商业交易量予以确定。"},{"i":6,"n":"第六条","txt":"如原反倾销措施为征收反倾销税，未征收反倾销税的出口不得作为提出新出口商复审的依据。"},{"i":7,"n":"第七条","txt":"新出口商复审申请人在原反倾销调查最终裁决生效后方可提出申请，且申请时间不得晚于实际出口后3个月。 就原反倾销调查期后最终裁决前的实际出口提出的申请不受前款规定限制，但仍须在原反倾销调查作出最终裁决后3个月内提出。 实际出口日期按发票日期确定。"},{"i":8,"n":"第八条","txt":"新出口商复审申请应该以书面形式提出，并由申请人的法定代表人或其授权人正式签署。"},{"i":9,"n":"第九条","txt":"新出口商复审申请应附下列证据和材料： （一）申请人的名称、地址及有关情况； （二）公司结构以及关联企业名称； （三）申请前6个月内被调查产品国内销售的平均价格、交易笔数、总金额，对中华人民共和国出口的平均价格、交易笔数、总金额，对第三国（地区）出口的平均价格、交易笔数周总金额； （四）对中华人民共和国出口被调查产品的合同、发票、提单、付款凭证的复印件以及进口商缴纳反倾销税的凭证； （五）申请人认为需要说明的其他内容。"},{"i":10,"n":"第十条","txt":"申请书应分为保密文本（如申请人提出保密申请）和公开文本。保密文本和公开文本均应提交1份正本、6份副本。"},{"i":11,"n":"第十一条","txt":"外经贸部自收到新出口商复审申请之日起7个工作日内通知原反倾销调查申请人。原反倾销调查申请人可在收到通知之日起14日内对应否立案进行复审发表意见。"},{"i":12,"n":"第十二条","txt":"外经贸部应自收到申请人提交的申请书及所附证据、材料之日起30个工作日内，决定立案或不立案。"},{"i":13,"n":"第十三条","txt":"如外经贸部决定不立案，应以书面形式通知申请人并说明理由。"},{"i":14,"n":"第十四条","txt":"如外经贸部决定立案，应发布公告。 立案公告应包括如下内容： （一）被调查产品的描述； （二）被调查的出口商、生产商及其所属国（地区）名称； （三）立案日期； （四）复审调查期； （五）利害关系方发表评论、提交相关材料的时限； （六）调查机关进行实地核查的意向； （七）利害关系方不合作的后果； （八）调查机关的联系方式。"},{"i":15,"n":"第十五条","txt":"外经贸部应在立案公告发布前通知海关，海关自公告发布之日起，停止对申请人出口的被调查产品征收反倾销税，但应要求申请人被调查产品的进口商按照原反倾销裁决中适用于“其他公司”的反倾销税率提交保证金。"},{"i":16,"n":"第十六条","txt":"新出口商复审的调查期为复审申请提交前的6个月。"},{"i":17,"n":"第十七条","txt":"外经贸部可根据需要向新出口商复审申请人进行问卷调查，问卷调查的程序遵循《反倾销问卷调查暂行规则》。"},{"i":18,"n":"第十八条","txt":"进口产品的正常价值、出口价格以及倾销幅度按照《中华人民共和国反倾销条例》第四条、第五条和第六条的规定确定。"},{"i":19,"n":"第十九条","txt":"出口价格根据进口产品首次转售给独立购买人的价格推定的，如果申请人有充分的证据证明，反倾销税已适当地反映在此价格及以后的国内销售价格中，则外经贸部在计算推定的出口价格时，不应扣除已缴纳的反倾销税税额。"},{"i":20,"n":"第二十条","txt":"外经贸部可决定就申请人所提交证据、材料的准确性和完整性进行实地核查。有关实地核查的程序遵循《反倾销调查实地核查暂行规则》。"},{"i":21,"n":"第二十一条","txt":"新出口商复审无须作出初步裁决，但外经贸部在得出初步调查结论后，应向有关利害关系方披露初步结论及所依据的事实和理由，并给予其不少于10天的时间提出评论和提交补充材料。"},{"i":22,"n":"第二十二条","txt":"初步结论披露后，新出口商复审的申请人可以在15日内向外经贸部提出价格承诺。"},{"i":23,"n":"第二十三条","txt":"外经贸部认为复审申请人提出的价格承诺能够接受的，经商国家经贸委后，可以决定中止或者终止复审调查；同时通知海关自承诺生效之日起停止对该新出口商出口的被调查产品征收反倾销税。 复审立案后价格承诺生效前该新出口商出口的被调查产品，按照所交保证金金额征收反倾销税。"},{"i":24,"n":"第二十四条","txt":"新出口商复审调查自立案之日起，不超过9个月。"},{"i":25,"n":"第二十五条","txt":"外经贸部应于复审期限届满15日前向国务院关税税则委员会提出适用于复审申请人的反倾销税建议，并在复审期限届满前根据国务院关税税则委员会的决定发布公告。"},{"i":26,"n":"第二十六条","txt":"复审裁决确定存在倾销的，应对复审立案之后作出裁决之前复审申请人出口的被调查产品追溯征收反倾销税。 复审裁决的反倾销税，高于已付保证金的，差额部分不予收取；低于已付保证金的，差额部分应予退还。"},{"i":27,"n":"第二十七条","txt":"本规则由外经贸部负责解释。"},{"i":28,"n":"第二十八条","txt":"本规则自2002年4月15日起实施。"}],"fanqingxiaodiaochaxinxipiluzanxingguize":[{"i":1,"n":"第一条","txt":"为保证反倾销调查的公平、公正、公开，根据《中华人民共和国反倾销条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"本规则所称披露，是指外经贸部向在反倾销调查过程中提供信息的利害关系方告知在裁定该利害关系方的倾销及倾销幅度时所采用的基本数据、信息、证据及理由的程序。"},{"i":4,"n":"第四条","txt":"披露包括初裁决定公布后的披露、实地核查结果的披露和终裁决定作出前的披露。"},{"i":5,"n":"第五条","txt":"初裁决定公布后披露和终裁决定作出前披露的内容包括： （一）正常价值方面：对正常价值的认定、计算正常价值所采用的交易数据及调整数据、计算正常价值时未采用的数据及其理由等； （二）出口价格方面：对出口价格的认定、计算出口价格所采用的交易数据及调整数据、计算出口价格时未采用的数据及其理由等； （三）成本方面：认定生产成本采用的数据、各项费用的分摊方法及采用的数据、利润的估计、 非正常项目的认定等； （四）现有最佳信息的使用及理由，但涉及其他利害关系方保密信息的除外； （五）倾销幅度的计算方法； （六）外经贸部认为需要披露的其他信息。"},{"i":6,"n":"第六条","txt":"披露应采用书面形式。"},{"i":7,"n":"第七条","txt":"外经贸部应自反倾销调查初裁决定公告发布之日起20天内向有关利害关系方披露。"},{"i":8,"n":"第八条","txt":"外经贸部在向有关利害关系方进行披露后，应给予该利害关系方不少于10天的时间，对初裁决定及披露的相关事项予以评论。 该评论应以书面方式在规定时间内提交外经贸部。"},{"i":9,"n":"第九条","txt":"外经贸部应在实地核查结束后的合理期限内向被核查出口商、生产商披露有关核查结果，包括： （一）被核查出口商、生产商是否合作； （二）被核查出口商、生产商提供数据、信息和材料的真实性、准确性和完整性情况； （三）被核查出口商、生产商是否存在欺骗、隐瞒的行为； （四）在被核查出口商、生产商所在国家（地区）进一步搜集信息的情况； （五）外经贸部认为需要披露的其他相关信息。"},{"i":10,"n":"第十条","txt":"外经贸部在终裁决定作出前进行披露时应给予被披露的有关利害关系方不少于10天的时间，对披露的有关事项进行评论。 该评论应以书面方式在规定的时间内提交外经贸部。"},{"i":11,"n":"第十一条","txt":"涉及复审方面的信息披露按照本规则执行。"},{"i":12,"n":"第十二条","txt":"本规则由外经贸部负责解释。"},{"i":13,"n":"第十三条","txt":"本规则自2002年4月15日起实施。"}],"fanqingxiaodiaochagongkaixinxichayuezanxingguize":[{"i":1,"n":"第一条","txt":"为保证反倾销调查的公平、公正、公开，根据《中华人民共和国反倾销条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"本规则所指公开信息查阅，是指与反倾销案件有关的利害关系方到外经贸部指定的地点查找、阅览、抄录并复印其他利害关系方就该案件所提交的非保密的信息和材料。"},{"i":4,"n":"第四条","txt":"外经贸部允许各利害关系方查阅与案件调查有关的全部公开信息。"},{"i":5,"n":"第五条","txt":"本规则第四条所指可查阅公开信息的内容包括： （一）申请人提交的反倾销调查申请书的非保密文本； （二）应诉国外出口商和生产商提交的答卷及补充答卷的非保密文本； （三）利害关系方向外经贸部提供的其他非保密信息； （四）有关利害关系方向外经贸部提出的请求，包括但不限于延期递交答卷、追加被调查国家（地区）、追溯征税、提出价格承诺、召开听证会、复审等申请； （五）其他利害关系方对上款的申请提出的意见及评论中涉及的非保密信息； （六）外经贸部对本条第（四）款中所提申请的答复； （七）外经贸部会见有关利害关系方的概要； （八）外经贸部发布的公告、通知； （九）外经贸部进行实地核查的概要； （十）外经贸部认为利害关系方可查阅的其他非保密信息。"},{"i":6,"n":"第六条","txt":"利害关系方在向外经贸部提供相关信息时，应注明为公开信息还是保密信息。 利害关系方提供的信息为保密信息的，可向外经贸部提出对该部分信息进行保密处理的请求，并应提供一份该保密信息的非保密概要，该非保密概要应包含在公开文本中。 未注明保密信息的，外经贸部可视其为公开信息，允许其他利害关系方查阅。"},{"i":7,"n":"第七条","txt":"在整个案件调查过程中，各利害关系方可以在外经贸部的工作时间内到外经贸部查阅公开信息。"},{"i":8,"n":"第八条","txt":"利害关系方在查阅公开信息前，应事前与外经贸部有关工作人员取得联系，并说明所查阅信息的内容和范围。"},{"i":9,"n":"第九条","txt":"利害关系方在查阅公开信息时，应向外经贸部有关工作人员出示能够证明其身份的证件或文件，并进行登记。"},{"i":10,"n":"第十条","txt":"利害关系方可以抄录、复印所查阅的公开信息，但不得将材料借出。"},{"i":11,"n":"第十一条","txt":"本规则由外经贸部负责解释。"},{"i":12,"n":"第十二条","txt":"本规则自2002年4月15日起实施。"}],"fanqingxiaodiaochashidihechazanxingguize":[{"i":1,"n":"第一条","txt":"为规范反倾销调查实地核查程序，根据《中华人民共和国反倾销条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"本规则所指实地核查，是指外经贸部在反倾销调查过程中派出工作人员赴有关出口国（地区），核实有关出口商、生产商所提交信息和材料的真实性、准确性和完整性及进一步搜集反倾销调查所需信息和材料的程序。"},{"i":4,"n":"第四条","txt":"外经贸部只对反倾销调查中充分合作的有关出口国（地区）的出口商、生产商进行实地核查。"},{"i":5,"n":"第五条","txt":"实地核查主要核查出口商、生产商所提交的信息和材料，包括： （一）出口商、生产商所提交答卷中涉及的所有信息和材料； （二）出口商、生产商应外经贸部要求所提供的补充答卷中涉及的信息和材料； （三）出口商、生产商主动向外经贸部提交的有关信息和材料； （四）外经贸部认为需要核实的其他信息和材料。"},{"i":6,"n":"第六条","txt":"外经贸部可根据案件的不同情况，作出是否进行实地核查的决定。"},{"i":7,"n":"第七条","txt":"外经贸部通常在作出初步裁定后进行实地核查，也可根据案件具体情况在作出初步裁定前进行实地核查。"},{"i":8,"n":"第八条","txt":"外经贸部决定进行实地核查的，应提前通知将被核查的出口商、生产商及其所在国（地区）政府。"},{"i":9,"n":"第九条","txt":"外经贸部在进行实地核查前，应取得被核查出口商、生产商的明确同意。"},{"i":10,"n":"第十条","txt":"实地核查获得被核查出口商、生产商同意的，外经贸部应将被核查出口商、生产商的名称、地址以及商定的核查日期等信息通知出口商、生产商所在国（地区）政府。 出口商、生产商所在国（地区）政府表示异议的，外经贸部不得进行实地核查。"},{"i":11,"n":"第十一条","txt":"在实地核查前，外经贸部应将具体行程预先通知被核查出口商、生产商。"},{"i":12,"n":"第十二条","txt":"核查小组由外经贸部负责组织，通常由负责反倾销调查的政府人员组成。 在特殊情况下，外经贸部可以邀请非政府专家参与核查，但应事前通知被核查的出口商、生产商及其所在国（地区）政府。该非政府专家应严格遵守保密义务。"},{"i":13,"n":"第十三条","txt":"核查小组应在进行实地核查前将需要核实信息的一般性质和需要进一步搜集的信息通知被核查出口商、生产商。 核查小组可以根据需要在实地核查前向被核查出口商、生产商发放具体的核查问题单。"},{"i":14,"n":"第十四条","txt":"被核查出口商、生产商应整理好支持其答卷和补充答卷中所提供信息的所有证据和材料，以备核查。 如前款提及的证据和材料的原始记录通过某种计算机程序以电子数据形式存在，被核查出口商、生产商应保证上述计算机程序能够正常运转，并且该电子数据可复制、打印。"},{"i":15,"n":"第十五条","txt":"被核查出口商、生产商应在核查过程中积极配合核查小组的工作，并应配备最初准备答卷的负责人员和其他相关主管人员，随时解释核查小组提出的问题。"},{"i":16,"n":"第十六条","txt":"核查的工作语言为中文或核查小组同意使用的其他语言。"},{"i":17,"n":"第十七条","txt":"核查小组可以视案件的复杂程度，采取全面核查或抽样核查的方法。"},{"i":18,"n":"第十八条","txt":"实地核查可以按照事前通知的范围进行，但该范围不妨碍核查小组根据所获得的信息和材料当场要求提供进一步的信息和材料。"},{"i":19,"n":"第十九条","txt":"核查结束后，外经贸部应在合理期间内向被核查出口商、生产商披露核查结果。外经贸部可以应其他利害关系方的请求披露该核查的概要情况，但不得披露被核查出口商、生产商的保密信息。"},{"i":20,"n":"第二十条","txt":"经过核实的答卷和补充答卷中所提供的信息和材料以及核查中进一步搜集的信息和材料将作为外经贸部裁定倾销和倾销幅度的依据。"},{"i":21,"n":"第二十一条","txt":"有下列情况之一的，外经贸部可以决定采用已经获得的事实和可获得的最佳信息确定倾销和倾销幅度： （一）出口商、生产商拒绝实地核查的； （二）被核查出口商、生产商所在国（地区）政府对实地核查提出异议的； （三）对核查小组提出的合理要求，被核查出口商、生产商不积极合作的； （四）被核查出口商、生产商拖延核查，致使核查未能如期完成的； （五）核查中发现被核查出口商、生产商所提供的信息和材料在真实性、准确性和完整性方面存在重大问题的； （六）被核查出口商、生产商存在明显欺骗、隐瞒行为的； （七）有其他阻碍实地核查行为的。"},{"i":22,"n":"第二十二条","txt":"反倾销调查涉及推定出口价格的，或外经贸部认为需要的，外经贸部可对有关被调查产品的国内进口商进行实地核查，具体核查办法参照本规则进行。"},{"i":23,"n":"第二十三条","txt":"应有关出口商、生产商的请求，且该出口商、生产商所在国（地区）政府未提出异议的，外经贸部可派出工作人员赴该出口国（地区）解释反倾销调查问卷。"},{"i":24,"n":"第二十四条","txt":"本规则由外经贸部负责解释。"},{"i":25,"n":"第二十五条","txt":"本规则自2002年4月15日起实施。"}],"fanqingxiaodiaochachouyangzanxingguize":[{"i":1,"n":"第一条","txt":"为保证反倾销调查的公平、公正、公开，根据《中华人民共和国反倾销条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"外经贸部应在全面调查的基础上为每一应诉出口商或生产商确定单独的倾销幅度。但因出口商、生产商、产品型号或交易过多，为每一出口商、生产商单独确定倾销幅度或调查全部产品型号、交易会带来过重负担并妨碍倾销调查及时完成的，外经贸部可采用抽样方法进行调查。"},{"i":4,"n":"第四条","txt":"外经贸部基于抽样时可获得的信息，采用统计学的有效抽样方法或按照出口数量选择调查样本。"},{"i":5,"n":"第五条","txt":"外经贸部选择的调查样本应当具有代表性。"},{"i":6,"n":"第六条","txt":"外经贸部根据报名登记应诉情况决定选取及备选的出口商、生产商。"},{"i":7,"n":"第七条","txt":"外经贸部初步决定选取及备选的出口商、生产商后，应及时通知各利害关系方。 利害关系方在收到通知后7日内，可以就出口商、生产商的选择发表评论。"},{"i":8,"n":"第八条","txt":"外经贸部应尽量选择同意被选的出口商、生产商；出口商、生产商不同意被选的，不妨碍外经贸部的选择。"},{"i":9,"n":"第九条","txt":"外经贸部只向选取及备选的出口商、生产商发放调查问卷，选取及备选的出口商、生产商应当按照问卷要求及时提供完整准确的答卷。"},{"i":10,"n":"第十条","txt":"未被选取及备选的出口商、生产商可以自愿向外经贸部提供信息。"},{"i":11,"n":"第十一条","txt":"外经贸部应对选取的出口商、生产商确定单独的倾销幅度。"},{"i":12,"n":"第十二条","txt":"选取的出口商、生产商不合作的，外经贸部可以用备选的出口商、生产商替代该出口商、生产商。"},{"i":13,"n":"第十三条","txt":"未单独审查的应诉出口商、生产商的倾销幅度按选取的出口商、生产商的加权平均倾销幅度确定。"},{"i":14,"n":"第十四条","txt":"加权平均倾销幅度的计算应排除： （一）零倾销幅度； （二）不足2%的微量倾销幅度； （三）根据《中华人民共和国反倾销条例》第二十一条做出的倾销幅度。"},{"i":15,"n":"第十五条","txt":"外经贸部应对未被选取但及时提供了必要信息并明确要求为其确定单独倾销幅度的出口商、生产商进行单独审查，除非该单独审查会妨碍倾销调查的及时完成。"},{"i":16,"n":"第十六条","txt":"未应诉的出口商、生产商的倾销幅度根据《中华人民共和国反倾销条例》第二十一条确定。"},{"i":17,"n":"第十七条","txt":"外经贸部收到应诉出口商、生产商的答卷后，如发现出口商、生产商的被调查产品涉及型号众多，外经贸部可采取抽样的方法选取部分型号的产品来确定该应诉公司被调查产品的倾销及倾销幅度。"},{"i":18,"n":"第十八条","txt":"外经贸部初步决定选取的产品型号后，应及时通知各利害关系方。 利害关系方在收到通知后7日内，可以就产品型号的选取发表评论。"},{"i":19,"n":"第十九条","txt":"外经贸部应尽量选择出口商、生产商同意的产品型号；出口商、生产商不同意的，不妨碍外经贸部的选择。"},{"i":20,"n":"第二十条","txt":"被调查产品的倾销幅度按照被选取型号的产品的加权平均倾销幅度确定。"},{"i":21,"n":"第二十一条","txt":"外经贸部在收到应诉出口商、生产商的答卷后， 如果被调查产品的国内销售或出口销售交易笔数过多，外经贸部可采取抽样的方法选取部分交易来确定该被调查产品的正常价值或出口价格。"},{"i":22,"n":"第二十二条","txt":"外经贸部进行抽样时应当采用统计学的有效抽样方法。"},{"i":23,"n":"第二十三条","txt":"外经贸部决定被选取的交易时应取得有关应诉出口商、生产商的同意。"},{"i":24,"n":"第二十四条","txt":"该被调查产品的正常价值或出口价格按被选取交易的加权平均值确定。"},{"i":25,"n":"第二十五条","txt":"统计学的有效抽样方法包括等距抽样、随机抽样或其他适当的统计抽样方法。"},{"i":26,"n":"第二十六条","txt":"本规则由外经贸部负责解释。"},{"i":27,"n":"第二十七条","txt":"本规则自2002年4月15日起实施。"}],"fanqingxiaodiaochalianzanxingguize":[{"i":1,"n":"第一条","txt":"为了规范反倾销调查申请及立案程序，根据《中华人民共和国反倾销条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"外经贸部可以应申请人的申请立案，进行反倾销调查；也可以自行立案，进行反倾销调查。"},{"i":4,"n":"第四条","txt":"国内产业或者代表国内产业的自然人、法人或者有关组织（以下统称申请人）可以提起反倾销调查申请。"},{"i":5,"n":"第五条","txt":"国内产业是指中华人民共和国国内同类产品的全部生产者，或者其总产量占国内同类产品全部总产量的50%以上的生产者。"},{"i":6,"n":"第六条","txt":"申请人的产量占国内同类产品总产量虽不足50%，但如果表示支持申请和反对申请的国内生产者中，支持者的产量占支持者和反对者的总产量的50%以上，并且表示支持申请的国内生产者的产量不低于同类产品总产量25%的，该申请应被视为代表国内产业提出。在确定本条第一款支持者的产量时，申请人的产量应当计算在内。"},{"i":7,"n":"第七条","txt":"国内产业十分分散而涉及生产者数量巨大的，外经贸部可以采用统计学上有效的抽样方式审查申请人的资格。"},{"i":8,"n":"第八条","txt":"国内生产者与出口商或者进口商有关联的，或者其本身为申请调查进口产品的进口商的，可以排除在国内产业之外。"},{"i":9,"n":"第九条","txt":"国内一个区域市场中的生产者，在该市场中销售其全部或者几乎全部的同类产品，并且该市场中同类产品的需求主要不是由国内其他地方的生产者供给的，可以视为一个单独产业。"},{"i":10,"n":"第十条","txt":"反倾销调查申请应以书面形式提出。申请书应载明正式请求外经贸部立案进行反倾销调查的意思表示，并由申请人或其合法授权人盖章或签字。"},{"i":11,"n":"第十一条","txt":"反倾销调查申请应包括下列内容并附具相关证据材料： （一）申请人的有关情况； （二）申请调查进口产品的已知生产商、出口商。进口商； （三）申请调查进口产品。国内同类产品的完整说明及二者的比较； （四）倾销及倾销幅度； （五）国内产业受到损害的情况； （六）倾销与损害之间的因果关系； （七）申请人认为需要说明的其他事项。"},{"i":12,"n":"第十二条","txt":"申请人有关情况的说明，应当包括以下的证据材料： （一）申请人的名称、法定代表人、地址、电话、传真、邮政编码、联系人等有关情况； （二）申请人委托代理人的，应当说明代理人的名称及身份等事项，并提供授权委托书； （三）申请提出前三年申请人生产的同类产品的产量及所占国内同类产品总产量的比例； （四）所有已知的国内同类产品的生产者的清单，如果国内同类产品的生产者组成了协会或商会，应提供该协会、商会的名称、地址、电话、传真、邮政编码、联系人等有关情况。"},{"i":13,"n":"第十三条","txt":"关于申请调查进口产品的已知生产商、出口商、进口商，申请人应当提供以下证据材料： （一）申请调查进口产品的初步描述； （二）申请调查进口产品的已知生产商、出口商、进口商的名称、法定代表人、地址、电话。传真、邮政编码、联系人等有关情况。"},{"i":14,"n":"第十四条","txt":"关于申请调查进口产品。国内同类产品的描述及二者的比较，申请人应当提供以下的证据材料： （一）申请调查进口产品的详细描述，包括产品名称、种类、规格、产品用途及市场情况、中华人民共和国关税税则号等； （二）申请调查进口产品的原产国（地区）或出口国（地区）； （三）国内同类产品的详细描述，包括该产品的名称、种类、规格、产品用途和市场情况等； （四）申请调查进口产品与国内同类产品异同点比较，包括产品的物理特征、化学性能、生产工艺、替代性、价格和用途等方面。"},{"i":15,"n":"第十五条","txt":"关于出口价格，申请人应当提供申请调查进口产品在申请提出前12个月中实际支付或应予支付的价格。 上述证据材料可以用实际成交价格、报价单、价格单、海关统计数据、有代表性机构或刊物的统计数据等方式提供。"},{"i":16,"n":"第十六条","txt":"关于正常价值，申请人应当提供国外同类产品在出口国（地区）或原产地国（地区）正常贸易中用于消费的可比价格；没有可比价格或可比价格不能获得的，申请人应当提供申请调查进口产品的结构价格或者向第三国出口的价格。 申请人在提供申请调查进口产品的结构价格的证据材料时，应包括该产品的生产成本及合理费用的证据材料；如果不能获得实际结构价格的，申请人可以按照其本身的生产要素及该要素在出口国（地区）的价格或国际市场的通行价格计算。 上述证据材料可以用实际成交价格、价格单或者有代表性机构或刊物的统计数据等方式提供。"},{"i":17,"n":"第十七条","txt":"关于价格调整和价格比较，申请人应当对正常价值、出口价格在销售条件、条款、税收、贸易环节、数量、物理特征等方面做适当调整，在对正常价值和出口价格进行比较时，应当尽可能在同一贸易环节、相同时间的销售、出厂前的水平上进行。"},{"i":18,"n":"第十八条","txt":"申请人应当对倾销幅度进行初步估算，估算应以调整后的正常价值的加权平均值减去调整后的出口价格的加权平均值除以到岸价（CIF）加权平均值的方法计算。 申请人以其他方法计算的，应当说明理由。"},{"i":19,"n":"第十九条","txt":"国内产业损害的情况，主要包括国内产业损害的类型（实质损害、实质损害威胁或实质阻碍国内产业建立）、申请调查进口产品的数量变化及价格变化、对国内同类产品的价格影响、对国内产业相关经济因素和指标的影响等方面。"},{"i":20,"n":"第二十条","txt":"以对国内产业造成实质损害为由提出申请的，申请人应当提供下列证据： （一）申请调查进口产品的绝对数量或相对国内同类产品的生产或消费的增长情况，自申请提出前三年的进口数量情况及变动幅度，上述数量变动幅度曲线图表等； （二）申请调查进口产品自申请提出前三年在中国国内销售的平均价格、平均价格变动图表等； （三）申请调查进口产品的价格对国内同类产品价格的影响情况，包括国内同类产品价格削减情况、对国内同类产品的价格压低和抑制情况、影响国内产品价格的变动值等； （四）申请调查进口产品对国内产业有关经济指标或因素的影响，包括销售、利润、产量、市场份额、生产率、投资收益或设备利用率实际和潜在的下降、影响国内价格的因素、倾销幅度的大小、现金流动、就业、工资、筹措资金或投资能力及库存等。 上述某个别指标、因素不适用的，申请人应当予以说明。"},{"i":21,"n":"第二十一条","txt":"以对国内产业造成实质损害威胁为由提出申请的，申请人应当提供下列证据： （一）申请调查进口产品以倾销价格进入国内市场的大幅增长的可能性，包括出口国（地区）现有及潜在的出口能力、出口国（地区）的库存等情况； （二）本规则第二十条第（四）项所列因素或指标的可明显预见和迫近的变化趋势。"},{"i":22,"n":"第二十二条","txt":"以对国内产业的建立造成实质阻碍为由提出申请的，申请人除应提供本规则第二十条、二十一条所列证据外，还应提供国内产业可能发展的相关证据，包括产业建立的计划以及实际实施的有关情况。"},{"i":23,"n":"第二十三条","txt":"申请人在主张申请调查进口产品对国内产业的影响及提供证据材料时，应当针对国内同类产品的生产进行单独确定；不能针对国内同类产品的生产进行单独确定的，应当以包括国内同类产品在内的最窄产品组或者范围的生产确定。"},{"i":24,"n":"第二十四条","txt":"关于倾销与损害之间的因果关系，申请人应当提供： （一）申请调查进口产品与国内产业损害存在因果关系的论证； （二）未以倾销价格销售的进口产品的数量和价格、需求的减少或消费模式的变化、国外或国内生产者的限制贸易的做法及它们之间的竞争、技术发展以及国内产业的出口实绩和生产率等对国内产业损害影响的说明。 申请人认为上述某个别因素不适用的，应予说明。"},{"i":25,"n":"第二十五条","txt":"申请人在提供本章所规定的证据材料时，应当说明证据来源。"},{"i":26,"n":"第二十六条","txt":"反倾销调查申请中如涉及保密材料的，申请人应当提出保密申请；对于保密材料，申请人应当提交使案件其他利害关系方能够对保密材料有合理了解的非保密概要；如果申请人不能提供非保密概要，应当说明理由。"},{"i":27,"n":"第二十七条","txt":"反倾销调查申请书及证据材料应当采用中文印刷体形式；国家有统一规定术语的，应当采用规范用语。 申请人所提供的证据材料是外文的，申请人应当提供该材料的外文全文，并提供相关部分的中文翻译件。"},{"i":28,"n":"第二十八条","txt":"反倾销调查申请应当分为保密文本（如果申请人提出保密申请）和公开文本。保密文本和公开文本均应提交正本1份，副本6份；公开文本除提交正本1份，副本6份外，还应当按已知的申请调查进口产品的出口国（地区）政府的数量提供副本，如涉及已知的申请调查进口产品的出口国（地区）政府的数量过多，可以适当减少但不能低于5份。"},{"i":29,"n":"第二十九条","txt":"进出口公平贸易局可以要求申请人提供申请书及证据材料的电子数据载体。"},{"i":30,"n":"第三十条","txt":"申请人应当以邮寄或直接送达等方式将书面申请书及证据材料递交进出口公平贸易局。"},{"i":31,"n":"第三十一条","txt":"申请人正式递交申请书及证据材料，进出口公平贸易局应予签收。签收之日为进出口公平贸易局收到申请书及证据材料之日。"},{"i":32,"n":"第三十二条","txt":"进出口公平贸易局可以采取问卷或实地核查等方式对申请书及证据材料中包括申请人的资格、申请调查进口产品等问题进行调查。"},{"i":33,"n":"第三十三条","txt":"进出口公平贸易局应当自对申请书及证据材料签收之日起60天内，对申请人的反倾销调查申请进行审查并提出意见，经商国家经贸委后，决定立案调查或者不立案调查。"},{"i":34,"n":"第三十四条","txt":"进出口公平贸易局应当自对申请书及证据材料签收之日起7日内将申请书及证据材料的副本1份转交国家经贸委；国家经贸委应当至少有20天的时间研究申请书及证据材料并对反倾销调查立案提出意见。"},{"i":35,"n":"第三十五条","txt":"进出口公平贸易局在本规则第三十三条规定的期间内可以要求申请人对其反倾销调查申请进行调整或补充。申请人不调整或补充的或者未按要求的内容和时间调整或补充的，外经贸部可以驳回申请，并通知申请人。"},{"i":36,"n":"第三十六条","txt":"外经贸部驳回申请的，不得公开调查申请。"},{"i":37,"n":"第三十七条","txt":"外经贸部决定立案进行反倾销调查的，应当发布公告。"},{"i":38,"n":"第三十八条","txt":"外经贸部应当在发布立案公告之前通知出口国（地区）政府。"},{"i":39,"n":"第三十九条","txt":"立案公告应当载明下列内容： （一）申请书概要及外经贸部对申请的审查结果； （二）发起调查的日期； （三）调查产品及出口国（地区）名称； （四）调查期间； （五）调查机关进行实地核查的意向； （六）利害关系方不应诉将承担的后果； （七）允许利害关系方提出意见的时限； （八）调查机关的联系方式。"},{"i":40,"n":"第四十条","txt":"立案决定一经公布，进出口公平贸易局应将申请书公开部分提供给已知的出口商和出口国（地区）政府。如果调查涉及大量出口商的，进出口公平贸易局只向出口国（地区）政府提供申请书公开部分。"},{"i":41,"n":"第四十一条","txt":"反倾销调查立案决定公布之日为立案日期。"},{"i":42,"n":"第四十二条","txt":"外经贸部有充分证据证明存在倾销和损害，以及二者之间有因果关系的，经商国家经贸委后，可以自行决定立案，进行反倾销调查。"},{"i":43,"n":"第四十三条","txt":"本规则由外经贸部负责解释。"},{"i":44,"n":"第四十四条","txt":"本规则自2002年3月13日起实施。"}],"fanqingxiaotuishuizanxingguize":[{"i":1,"n":"第一条","txt":"为规范反倾销退税程序，根据《中华人民共和国反倾销条例》规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"倾销产品的进口商有证据证明已经缴纳的反倾销税金额超过实际倾销幅度的，可以按照本规则向外经贸部提出退税申请。"},{"i":4,"n":"第四条","txt":"退税申请的提出不得晚于实际缴纳反倾销税后的3个月。 就反倾销调查立案后最终裁决前所进口的被调查产品提出的退税申请，不受前款限制，但仍须在反倾销调查作出最终裁决后的3个月内提出。"},{"i":5,"n":"第五条","txt":"退税申请应以书面形式提出，并由申请人的法定代表人或其授权人正式签署。"},{"i":6,"n":"第六条","txt":"退税申请应附下列证据和材料： （一）申请人及其供应商的名称、地址及有关情况； （二）申请前6个月内被调查产品的国内平均销售价格、交易笔数、总金额，对中华人民共和国的平均出口价格、交易笔数、总金额，对第三国（地区）的平均出口价格、交易笔数、总金额； （三）申请前6个月内被调查产品的正常价值、出口价格的数据； （四）为计算倾销幅度而必须作出的各种调整及倾销幅度的初步计算结果； （五）就其申请退税的被调查产品的进口合同、发票、提单、付款凭证的复印件以及申请人缴纳反倾销税的凭证； （六）申请人认为需要说明的其他内容。"},{"i":7,"n":"第七条","txt":"第六条（一）至（四）项应按原反倾销调查问卷所要求的内容及形式提交。 申请所附证据、材料应包括反倾销措施所适用产品全部型号的数据。出口价格的数据，应包括申请人的供应商对中华人民共和国的全部出口。"},{"i":8,"n":"第八条","txt":"如退税申请涉及多个供应商，应分别提出申请。"},{"i":9,"n":"第九条","txt":"如果进口商与出口商、生产商无关联关系，而上述证据、材料无法由进口商直接提供，则退税申请应包含出口商、生产商的声明。 前款所指声明应包括下列内容：被调查产品的倾销幅度已经降低或消除，且有关证据和材料将按照规定的内容和形式，在自退税申请提出之日起30日内，由出口商、生产商直接提交给外经贸部。 出口商、生产商在规定期间内，未能按申请人的声明提交证据、材料的，外经贸部可以驳回退税申请。"},{"i":10,"n":"第十条","txt":"申请书应分为保密文本（如申请人提出保密申请）和公开文本。保密文本和公开文本均应提交1份正本、6份副本。"},{"i":11,"n":"第十一条","txt":"外经贸部可以根据《反倾销调查实地核查暂行规则》，对出口商、生产商所提交证据、材料的准确性和完整性进行实地核查。 如果利害关系方拒绝核查，外经贸部可根据已经获得的事实和可获得的最佳信息作出裁决，或驳回申请。"},{"i":12,"n":"第十二条","txt":"外经贸部按照《中华人民共和国反倾销条例》第4条、第5条、第6条的规定，确定申请退税产品在申请前6个月内的正常价值、出口价格以及倾销幅度。"},{"i":13,"n":"第十三条","txt":"出口价格根据进口产品首次转售给独立购买人的价格推定的，如果申请人有充分的证据证明，反倾销税已适当地反映在此价格及以后的国内销售价格中，则外经贸部在计算推定的出口价格时，不应扣除已缴纳的反倾销税税额。"},{"i":14,"n":"第十四条","txt":"如外经贸部经过审查，倾销幅度与原裁决结果相比并未降低，外经贸部应驳回退税申请。"},{"i":15,"n":"第十五条","txt":"外经贸部驳回申请的，应通知申请人并说明理由。"},{"i":16,"n":"第十六条","txt":"外经贸部应自接到退税申请之日起于12个月内完成退税审查。"},{"i":17,"n":"第十七条","txt":"外经贸部应于退税审查期限届满15日前向国务院关税税则委员会提出退税建议，并在审查期限届满前将国务院关税税则委员会的决定通知申请人和海关。"},{"i":18,"n":"第十八条","txt":"退税金额为原反倾销调查所确定的倾销幅度与新确定的倾销幅度之间的差额。"},{"i":19,"n":"第十九条","txt":"退税申请的审查结果不影响原反倾销措施的效力。"},{"i":20,"n":"第二十条","txt":"如经审查，外经贸部发现倾销幅度有所提高，可自主决定发起期中复审。"},{"i":21,"n":"第二十一条","txt":"本规则由外经贸部负责解释。"},{"i":22,"n":"第二十二条","txt":"本规则自2002年4月15日起实施。"}],"fanqingxiaowenjuandiaochaguize":[{"i":1,"n":"第一条","txt":"为了保证反倾销问卷调查规范有序地进行，根据《中华人民共和国反倾销条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"商务部（以下称调查机关）通过问卷方式进行的反倾销调查，适用本规则。"},{"i":3,"n":"第三条","txt":"调查机关在反倾销调查过程中，可以向被调查国家（地区）的生产商或出口商、国内生产者、国内进口商和下游用户以及其他有利害关系的组织、个人（以下统称利害关系方）发放问卷。"},{"i":4,"n":"第四条","txt":"利害关系方应当按照调查机关的要求，完整、准确地填写调查问卷，并提交相应的证据材料。"},{"i":5,"n":"第五条","txt":"利害关系方应当自反倾销立案公告之日起二十日内，按照公告要求向调查机关报名登记参加反倾销调查。"},{"i":6,"n":"第六条","txt":"利害关系方向调查机关报名登记时，应当以书面形式表示参加反倾销调查的意愿，载明利害关系方的名称、地址、联系方式和联系人，并按下列要求提交信息： （一）被调查国家（地区）的生产商或出口商应当提交调查期内向中国出口被调查产品的数量、金额； （二）中国国内生产者应当提交调查期内的生产能力、产量、销售数量和销售金额； （三）中国国内进口商应当提交调查期内被调查产品的进口数量、进口金额； （四）调查机关要求的其他信息。 利害关系方本人、法定代表人或经其依法授权的人应当在报名登记文件上盖章和（或）签字。"},{"i":7,"n":"第七条","txt":"调查机关通常自报名登记截止之日起十个工作日内在调查机关官方网站发布调查问卷，并通知已报名登记的利害关系方和出口国（地区）政府。"},{"i":8,"n":"第八条","txt":"调查机关决定采取抽样方式进行反倾销调查的，可以适当延长发放问卷的期限。"},{"i":9,"n":"第九条","txt":"利害关系方在回答问卷时对问卷有疑问的，可以向问卷所列明的案件调查人员咨询。"},{"i":10,"n":"第十条","txt":"答卷应当以规范汉字和符合国家标准的数字符号填制，并按要求提供相关证据材料。所有证据材料均应注明来源和出处。证据材料原件是外文的，应当按照外文原文的格式提供中文翻译件，并附外文原件或复印件。"},{"i":11,"n":"第十一条","txt":"问卷中要求提交的销售单证、会计记录、财务报告和其他文件应随附答卷一并提交。"},{"i":12,"n":"第十二条","txt":"利害关系方按照问卷要求应当将调查问卷复制转交给关联贸易公司或者其他公司填制的，该关联贸易公司或者其他公司应当按照问卷要求独立提交答卷。"},{"i":13,"n":"第十三条","txt":"调查问卷的答卷应当自问卷发放之日起三十七日内送达调查机关。 利害关系方因正当理由在答卷到期日前不能完成答卷的，应当在答卷提交期限届满七日前向调查机关提出延期提交答卷的书面申请，并说明延期理由。 调查机关应当在答卷提交期限届满四日前，根据利害关系方的具体情况对延期申请作出书面答复。调查机关决定同意延期的，延长期限通常不超过十四日。"},{"i":14,"n":"第十四条","txt":"利害关系方认为其答卷中有需要保密内容的，应当提出保密处理申请，并说明需要保密的理由。 对要求保密处理的信息，利害关系方应当提供非保密概要。非保密概要应当包含充分的、有意义的信息，以使其他利害关系方对保密信息能有合理的理解。利害关系方在特殊情况下不能提供非保密概要的，应当书面说明理由。"},{"i":15,"n":"第十五条","txt":"调查机关应当对保密申请进行审查。保密理由不充分、或者非保密概要不符合本规则第十四条第二款规定、或者答卷的利害关系方不能提供非保密概要的理由不充分的，调查机关可以要求利害关系方在规定期限内补充和修改。 利害关系方未在规定期限内补充和修改，或者补充和修改后仍不符合本规则第十四条第二款规定的，除调查机关能够从适当来源证明该信息是正确的之外，调查机关可以对要求保密处理的信息不予考虑。"},{"i":16,"n":"第十六条","txt":"利害关系方应当制作含有保密信息的完整答卷和只包括公开信息的公开答卷等两种类型的答卷。利害关系方应当在每份答卷首页注明保密答卷或公开答卷。公开答卷中涉及保密部分的，应当用方括号（〔〕）标注，并注明相应的非保密概要的序号。"},{"i":17,"n":"第十七条","txt":"利害关系方应当书面提交公开答卷和保密答卷正本各一份、副本各两份。 答卷应当妥善装订成册。答卷正文和所附证据材料应当按顺序标注页码。答卷应当包含答卷目录和附件目录，每一份附件都应当列明序号。"},{"i":18,"n":"第十八条","txt":"利害关系方应当按照问卷要求提供一份申明书，声明答卷利害关系方提供的信息是准确和完整的，并由答卷利害关系方本人、法定代表人或经其依法授权的人签署。 调查机关不接受未附具申明书的答卷。"},{"i":19,"n":"第十九条","txt":"利害关系方提供书面答卷和数据表格的，应当按照问卷要求提交光盘或调查机关可接受的其他电子数据载体。 电子数据载体的内容和形式应当与书面答卷完全一致。表格中的数据涉及到计算的，应当保留计算公式。"},{"i":20,"n":"第二十条","txt":"利害关系方应当保证提交的电子数据载体不携带病毒。携带病毒的，可被视为妨碍调查，调查机关可以依据已经获得的事实和可获得最佳信息作出裁定。"},{"i":21,"n":"第二十一条","txt":"通常情况下，不提供电子数据载体，特别是不提供交易和财务数据的电子数据载体的答卷利害关系方将被视为不合作。 利害关系方无法提供电子数据载体或者按照本规则要求提供电子数据载体将给利害关系方造成不合理的额外负担的，利害关系方可以自问卷发放之日起十五日内向调查机关提交书面申请，并说明无法按要求提供电子数据载体的理由。调查机关在收到申请后五日内对是否同意申请作出书面答复。"},{"i":22,"n":"第二十二条","txt":"利害关系方通过律师代理递交答卷的，应当委托中国执业律师代理呈送并由代理律师处理相关事宜，并在答卷中提供有效的授权委托书及该代理律师有效的执业证书复印件。"},{"i":23,"n":"第二十三条","txt":"调查问卷的答卷应当在答卷提交期限届满当日17时前寄至或直接送至问卷所列的地址，以调查机关实际收到的时间为准。"},{"i":24,"n":"第二十四条","txt":"调查机关可以向有关利害关系方发放补充问卷，要求提供补充信息和材料。利害关系方应当按照补充问卷要求提交答卷。"},{"i":25,"n":"第二十五条","txt":"利害关系方未在规定时间内按要求提交必要信息或严重妨碍调查的，调查机关可以依据已经获得的事实和可获得的最佳信息作出初步裁定或者最终裁定。"},{"i":26,"n":"第二十六条","txt":"利害关系方提交的信息未被接受的，调查机关应当通知该利害关系方并说明理由，并为其提供在合理时间内作出进一步解释的机会。调查机关认为该解释理由不充分的，应当在裁定中说明拒绝接受的理由。"},{"i":27,"n":"第二十七条","txt":"本规则规定的\"日\"为自然日。期限届满的最后一日是中国法定节假日的，以节假日后的第一日为期限届满的日期。"},{"i":28,"n":"第二十八条","txt":"本规则由商务部负责解释。"},{"i":29,"n":"第二十九条","txt":"本规则自2018年5月4日起施行。《反倾销问卷调查暂行规则》（对外贸易经济合作部令2002年第14号）同时废止。"}],"fanbutiechanyesunhaidiaochaguiding":[{"i":1,"n":"第一条","txt":"为规范反补贴产业损害调查，根据《中华人民共和国反补贴条例》（以下简称反补贴条例），制定本规定。"},{"i":2,"n":"第二条","txt":"依据反补贴条例进行的反补贴产业损害调查相关活动，适用本规定。"},{"i":3,"n":"第三条","txt":"中华人民共和国商务部（以下简称商务部）负责反补贴产业损害的调查。涉及农产品的反补贴产业损害调查，由商务部会同农业部进行。"},{"i":4,"n":"第四条","txt":"损害，是指补贴对已经建立的国内产业造成实质损害或者产生实质损害威胁，或者对建立国内产业造成实质阻碍。 实质损害是指对国内产业已经造成的、不可忽略的损害。 实质损害威胁是指对国内产业尚未造成实质损害，但有证据表明如果不采取措施将导致国内产业实质损害发生的明显可预见和迫近的情形。 对建立国内产业的实质阻碍是指阻碍尚未建立的国内产业的形成和发展，致使该产业无法建立。"},{"i":5,"n":"第五条","txt":"在确定补贴对国内产业造成的损害时，应当审查以下事项： （一）补贴进口产品的数量和补贴进口产品对国内同类产品价格的影响； （二）补贴进口产品对国内产业的影响。 对补贴进口产品数量的审查，应包括补贴进口产品的绝对数量是否大量增加，或相对于国内同类产品生产或消费数量是否大量增加； 审查补贴进口产品对国内同类产品价格的影响，应考察与国内同类产品价格相比，补贴进口产品是否大幅削价销售，或者补贴进口产品是否大幅压低国内同类产品价格，或在很大程度上抑制国内同类产品本应发生的价格增长。"},{"i":6,"n":"第六条","txt":"审查补贴进口产品对国内产业的影响，应包括对影响国内产业状况的所有有关经济因素和指标的评估，包括销售、利润、产量、市场份额、生产率、投资收益状况或设备利用率存在的实际或潜在的下降；影响国内价格的因素；补贴幅度的大小；现金流、库存、就业、工资、产业增长、筹资或投资能力受到的实际或潜在的负面影响。对于农产品案件，还应当考虑是否给政府支持计划增加了负担。"},{"i":7,"n":"第七条","txt":"在确定补贴对国内产业造成的实质损害时，还应当审查补贴的性质及对贸易造成的影响。"},{"i":8,"n":"第八条","txt":"实质损害威胁应当根据明显可预见和迫近的情形来判断，并且如果不采取措施，实质损害将会发生。对实质损害威胁的确定，应当依据事实，不得仅依据指控、推测或者极小的可能性。 确定实质损害威胁，还应审查但不限于以下因素： （一）补贴的性质及可能对贸易造成的影响； （二）表明进口很可能发生实质增长的补贴产品进口的大幅增长率； （三）表明进口很可能发生实质增长的补贴进口产品生产者生产能力的增长。在采用这一指标时应考虑其他国家（地区）市场可能吸收的增加的出口量； （四）进口产品是否正以将大幅压低或抑制国内同类产品价格的价格进口，并且将很可能导致对进口产品需求的增加； （五）被调查产品的库存情况。"},{"i":9,"n":"第九条","txt":"确定对建立国内产业的实质阻碍，还应审查但不限于以下因素： （一）国内产业的建立或筹建情况； （二）国内需求的增长情况及其影响； （三）补贴进口产品对国内市场状况的影响； （四）补贴进口产品的后续生产能力和在国内市场的发展趋势。"},{"i":10,"n":"第十条","txt":"同类产品，是指与补贴进口产品相同的产品；没有相同产品的，以与补贴进口产品的特性最相似的产品为同类产品。"},{"i":11,"n":"第十一条","txt":"在确定同类产品时，可以考虑以下因素：产品的物理特征、化学性能、用途、生产设备和制造工艺、消费者和生产者的评价、产品的可替代性、销售渠道、价格等。"},{"i":12,"n":"第十二条","txt":"补贴进口产品对国内产业的影响，应当根据对国内同类产品生产的单独界定进行评估。如果根据生产工艺、生产者的销售和利润等标准不能对国内同类产品的生产与其他产品的生产分别界定，则可以根据包括国内同类产品在内的最窄产品组或产品范围的产品生产来确定进口补贴产品的影响，只要这种产品组或产品范围能够提供足够的信息。"},{"i":13,"n":"第十三条","txt":"在确定国内产业时，应当考虑中国国内同类产品的全部生产者，或者其总产量占国内同类产品全部总产量的主要部分的生产者；但是，国内生产者与出口经营者或者进口经营者有关联，或者其本身就是补贴产品的进口经营者的，可以排除在国内产业之外。 前款所称有关联，是指其中的一方直接或者间接地控制或影响另一方，或者双方直接或者间接地受第三方的控制或影响，或者双方共同直接地或者间接地影响第三方等情形。"},{"i":14,"n":"第十四条","txt":"在确定区域产业时，应当考虑以下因素： （一）生产者在该区域市场出售全部或者几乎全部其所生产的同类产品； （二）该区域市场的需求不是由或者大部分不是由国内其他区域范围的同类产品的生产者提供； （三）其他因素。"},{"i":15,"n":"第十五条","txt":"补贴进口产品来自两个以上国家（地区），并且同时满足下列条件的，可以就补贴进口产品对国内产业造成的影响进行累积评估： （一）来自每一国家（地区）的补贴进口产品的补贴金额不属于微量补贴，并且其进口量不属于可忽略不计的； （二）根据补贴进口产品之间的竞争条件以及补贴进口产品与国内同类产品之间的竞争条件，进行累积评估是适当的。 前款所称微量补贴，是指补贴金额不足产品价值１％的补贴；但是，来自发展中国家（地区）的补贴进口产品的微量补贴，是指补贴金额不足产品价值２％的补贴。"},{"i":16,"n":"第十六条","txt":"在进行累积评估时，可以考虑以下因素： （一）来自不同国家（地区）的补贴进口产品对国内产业损害的持续性和可能性等情况； （二）来自不同国家（地区）的补贴进口产品与国内同类产品之间的可替代程度，包括特定客户的要求及产品质量等相关因素； （三）来自不同国家（地区）的补贴进口产品和国内同类产品在同一地区的市场上的销售价格、卖方报价和实际成交价格； （四）来自不同国家（地区）的补贴进口产品和国内同类产品是否存在相同或者相似的销售渠道，是否在市场上同时出现； （五）补贴进口产品之间以及补贴进口产品与国内同类产品之间的其他竞争条件； （六）其他因素。"},{"i":17,"n":"第十七条","txt":"商务部在进行产业损害调查时，应当为补贴进口产品的使用者、消费者等提供陈述意见、提交证据的机会。"},{"i":18,"n":"第十八条","txt":"反补贴案件的产业损害调查期通常为立案调查开始前的三至五年。"},{"i":19,"n":"第十九条","txt":"利害关系方申请应诉产业损害调查的，应当自反补贴调查立案公告发布之日起20日内向商务部提出应诉申请，办理应诉登记；同时应提供产业损害调查期内应诉申请人的生产能力、产量、库存以及在建和扩建的计划；向 中国出口该产品的数量及金额；进口经营者进口的数量及金额等情况。"},{"i":20,"n":"第二十条","txt":"利害关系方包括以下范围： （一）被调查产品的外国（地区）生产者、出口经营者、国内进口经营者，或者该产品生产者、出口经营者、进口经营者的行业组织或者其他组织； （二）被调查产品的原产国（地区）、出口国（地区）的政府及其代表； （三）国内同类产品的生产者、经营者，或者该产品生产者、经营者的行业组织或者其他组织； （四）其他。"},{"i":21,"n":"第二十一条","txt":"利害关系方参加调查活动，应当出具相关身份证明。利害关系方为企业或者其他组织的，应当出具营业执照等登记证明、法定代表人身份证明。 委托代理人参加调查活动的，应当出具代理人身份证明及授权委托书；委托律师作代理人的，应当委托中国律师事务所及中国执业律师，并应当出具授权委托书、律师事务所营业执照、律师执业证明。"},{"i":22,"n":"第二十二条","txt":"商务部反补贴产业损害调查的对象包括国内生产者、国内进口经营者、国内购买者、国内最终消费者、国外出口经营者、国外生产者等。"},{"i":23,"n":"第二十三条","txt":"商务部认为有必要的，可以聘请有关产业、财会、经贸、法律等方面的专家提供咨询意见。有关专家应当承担相应的保密责任。"},{"i":24,"n":"第二十四条","txt":"商务部采取问卷、抽样、听证、技术鉴定、实地核查等调查方式进行产业损害调查。"},{"i":25,"n":"第二十五条","txt":"商务部向利害关系方发放的调查问卷包括国内生产者调查问卷，国内进口商调查问卷，国外生产者、国外出口商调查问卷或者其他类型的调查问卷。"},{"i":26,"n":"第二十六条","txt":"利害关系方应按问卷规定的方式和时间返回答卷。如需延期，应当在答卷截止日期的7日前向商务部提出书面申请并说明理由。是否同意延期，由商务部决定。"},{"i":27,"n":"第二十七条","txt":"商务部可以对利害关系方进行实地核查。实地核查前，应将核查的主要目的和内容提前通知有关利害关系方。"},{"i":28,"n":"第二十八条","txt":"应利害关系方请求或者根据调查需要，经有关国家（地区）同意，商务部可以派出人员赴该国家（地区）对有关产品的生产能力、投资扩产、库存、原产或转口及企业间的关联关系等情况进行调查。"},{"i":29,"n":"第二十九条","txt":"商务部可以要求利害关系方按照规定提交或者补充书面材料，利害关系方也可以主动向商务部提交书面材料。"},{"i":30,"n":"第三十条","txt":"应利害关系方的请求，或者商务部认为有必要的，可以举行产业损害听证。"},{"i":31,"n":"第三十一条","txt":"应诉产业损害调查的利害关系方认为其所提供的资料及相关证据有必要保密的，应当在提交资料的同时向商务部提交该资料的非保密概要，或者分别提交该资料的保密文本和公开文本。 非保密概要和公开文本应当合理表达保密信息的实质内容。未表达实质内容的，商务部可以要求其补充相关内容和证据资料。"},{"i":32,"n":"第三十二条","txt":"应诉产业损害调查的利害关系方不提供资料及相关证据的非保密概要或公开文本的，或者不提交非保密概要或公开文本理由不充分的，商务部可以对该资料不予考虑。商务部如果认为提供的资料不需要保密时，可以要求利害关系方撤销保密申请。"},{"i":33,"n":"第三十三条","txt":"在产业损害调查过程中，应诉产业损害调查的利害关系方应当如实反映情况，提供有关资料。利害关系方不如实反映情况、提供有关资料的，或者没有在合理时间内提供必要信息的，或者以其他方式严重妨碍调查的，商务部可以根据已经获得的事实和可获得的最佳信息作出裁定。"},{"i":34,"n":"第三十四条","txt":"应诉产业损害调查利害关系方在向商务部提交任何文件及证据材料时，均应提交中文正本一式5份，并同时提交相应的电子文本（计算机软盘或光盘）一式3份。"},{"i":35,"n":"第三十五条","txt":"商务部产业损害调查，依据国家语言文字主管部门规定的规范中文为正式语言和文字。利害关系方所提供的任何文件、资料、信息应当为规范中文。非中文资料应提交中文译文及原文，并以中文译文为准。非中文资料如未附有中文译文将不被视为有效的和合法的证据材料。"},{"i":36,"n":"第三十六条","txt":"本规定由商务部负责解释。"},{"i":37,"n":"第三十七条","txt":"本规定自公布之日起30日后施行。本规定施行之日，原国家经贸委颁布的《反补贴产业损害调查与裁决规定》（国家经贸委令[2002]第46号）同时废止。"}],"fanbutiediaochashidihechazanxingguize":[{"i":1,"n":"第一条","txt":"为规范反补贴调查实地核查程序，根据《中华人民共和国反补贴条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"本规则所指实地核查，是指外经贸部在反补贴调查过程中派出工作人员赴有关出口国（地区），核实有关出口商、生产商所提交的材料的真实性、准确性和完整性及进一步搜集信息材料的程序。"},{"i":4,"n":"第四条","txt":"外经贸部只对反补贴调查中充分合作的出口国（地区）的出口商、生产商进行实地核查。"},{"i":5,"n":"第五条","txt":"实地核查主要核查有关出口商、生产商所提交的信息和材料，包括： （一）出口商、生产商所提交答卷中涉及的所有信息和材料； （二）出口商、生产商应外经贸部的要求所提交的补充答卷中涉及的信息和材料； （三）出口商、生产商主动向外经贸部提交的有关信息和材料； （四）外经贸部认为需要核实的其他信息和材料。"},{"i":6,"n":"第六条","txt":"外经贸部可根据案件的不同情况，作出是否进行实地核查的决定。"},{"i":7,"n":"第七条","txt":"外经贸部通常在作出初步裁定后进行实地核查；也可根据案件的具体情况，在做出初步裁定前进行。"},{"i":8,"n":"第八条","txt":"外经贸部决定进行实地核查的，应当提前通知将要被核查的出口商、生产商及其所在国（地区）政府。"},{"i":9,"n":"第九条","txt":"外经贸部进行实地核查前，应取得被核查出口商、生产商的明确同意。"},{"i":10,"n":"第十条","txt":"实地核查获得被核查出口商、生产商同意的，外经贸部应将被核查的出口商、生产商的名称、地址以及商定的核查日期等信息通知其所在国（地区）政府。被核查出口商、生产商的所在国（地区）政府表示异议的，外经贸部不得进行实地核查。"},{"i":11,"n":"第十一条","txt":"外经贸部应在实地核查前将具体行程通知被核查的出口商、生产商。"},{"i":12,"n":"第十二条","txt":"核查小组由外经贸部负责组织，通常由负责反补贴案件调查的政府人员组成。 在特殊情况下，外经贸部可以邀请非政府专家参与核查。但应事前通知被核查的出口商、生产商及其所在国（地区）政府。该非政府专家应严格遵守保密义务。"},{"i":13,"n":"第十三条","txt":"核查小组应在实地核查前将需要核实的信息的一般性质和需要进一步搜集的信息通知被核查的出口商、生产商。 核查小组根据需要可以在实地核查前向被核查出口商、生产商发放具体的核查问题清单。"},{"i":14,"n":"第十四条","txt":"被核查的出口商、生产商应保存并整理好支持答卷和补充答卷中所提供信息的所有证据和材料，以备核查。 上述证据材料的原始记录通过某种电脑程序以电子数据的形式存在的，被核查出口商、生产商应保证在核查过程中该程序正常运转，并且该电子数据可复制、打印。"},{"i":15,"n":"第十五条","txt":"被核查的出口商、生产商在核查过程中应积极配合核查小组的工作；并应配备最初准备材料及答卷的负责人和其他主管人员，随时解释核查小组提出的问题。"},{"i":16,"n":"第十六条","txt":"实地核查的工作语言为中文或核查小组同意的其他语言。"},{"i":17,"n":"第十七条","txt":"核查小组可以根据案件的复杂程度，决定采取全面核查或抽样核查的方法。"},{"i":18,"n":"第十八条","txt":"实地核查可以按照事先通知的范围进行，但该范围不妨碍核查小组根据所获得的信息和材料当场要求提供进一步的信息和材料。"},{"i":19,"n":"第十九条","txt":"核查结束后，外经贸部应在合理期间内向被核查出口商、生产商披露核查结果；外经贸部可以应其他利害关系方的请求披露该核查的概要情况，但不得披露被核查出口商、生产商的保密信息。"},{"i":20,"n":"第二十条","txt":"经过核实的答卷或补充答卷中提供的信息和材料以及核查中进一步搜集的信息和材料将作为外经贸部裁定补贴和补贴金额的依据。"},{"i":21,"n":"第二十一条","txt":"有下列情况之一的，外经贸部可以根据已经获得的事实和可获得的最佳信息确定补贴和补贴金额。 （一）有关出口商、生产商拒绝实地核查的； （二）被核查出口商、生产商所在国（地区）政府对实地核查提出异议的； （三）对核查小组提出的合理要求，被核查出口商、生产商不积极合作的； （四）被核查出口商、生产商拖延核查，致使核查未能如期完成的； （五）核查中发现被核查出口商、生产商所提供的信息和材料在真实性、准确性和完整性等方面存在重大问题的； （六）被核查出口商、生产商存在明显的欺骗、隐瞒行为的； （七）有其它阻碍实地核查行为的。"},{"i":22,"n":"第二十二条","txt":"外经贸部根据调查的需要可以对有关被调查产品的国内进口商进行实地核查，该核查参照本规则进行。"},{"i":23,"n":"第二十三条","txt":"应有关出口商、生产商的请求，且其所在国（地区）政府对此未提出异议的，外经贸部可以派工作人员赴该出口国（地区）解释反补贴调查问卷。"},{"i":24,"n":"第二十四条","txt":"本规则由外经贸部负责解释。"},{"i":25,"n":"第二十五条","txt":"本规则自2002年4月15日起实施。"}],"fanbutiediaochalianzanxingguize":[{"i":1,"n":"第一条","txt":"为规范反补贴调查申请及立案程序，根据《中华人民共和国反补贴条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"外经贸部可以应申请人的申请决定立案，进行反补贴调查；也可以自行决定立案，进行反补贴调查。"},{"i":4,"n":"第四条","txt":"国内产业或者代表国内产业的自然人、法人或者有关组织（以下统称申请人），可以向外经贸部提起反补贴调查申请。"},{"i":5,"n":"第五条","txt":"国内产业是指中华人民共和国国内同类产品的全部生产者，或者其总产量占国内同类产品全部总产量50%以上的生产者。"},{"i":6,"n":"第六条","txt":"申请人的产量占国内同类产品总产量虽不足50%，但如果表示支持申请和反对申请的国内生产者中，支持者的产量占支持者和反对者的总产量的50%以上，并且表示支持申请的国内生产者的产量不低于同类产品总产量25%的，该申请应视为代表国内产业提出。在确定本条第一款支持者的产量时，申请人的产量应当计算在内。"},{"i":7,"n":"第七条","txt":"国内产业十分分散而涉及生产者数量巨大时，外经贸部可以采用统计学上有效的抽样方式审查申请人的资格。"},{"i":8,"n":"第八条","txt":"国内生产者与出口商或者进口商有关联的，或者其本身为申请调查的产品或者其同类产品的进口商的，应当排除在国内产业之外。"},{"i":9,"n":"第九条","txt":"国内一个区域市场中的生产者，在该市场中销售其全部或者几乎全部的同类产品，并且该市场中对同类产品的需求主要不是由国内其他地方的生产者供给的，可以视为单独产业。"},{"i":10,"n":"第十条","txt":"反补贴调查申请应以书面形式提出。申请书应载明正式请求外经贸部立案进行反补贴调查的意思表示，并由申请人或其合法授权人盖章或签字。"},{"i":11,"n":"第十一条","txt":"反补贴调查申请应包括下列内容并附具相关证据材料： （一）申请人及已知国内生产者的情况说明； （二）申请调查进口产品、国内同类产品的完整说明及二者的比较； （三）已知出口商或国外生产商、进口商情况说明和出口国（地区）； （四）国内产业的情况说明； （五）补贴的情况说明； （六）国内产业受到损害的情况说明； （七）补贴和损害之间因果关系的论证； （八）申请人认为需要说明的其他事项。"},{"i":12,"n":"第十二条","txt":"申请人的情况说明应包括申请人的名称、地址、电话、传真、邮政编码、法定代表人及其联系人。 申请人委托代理人的，应当说明代理人的名称及身份等事项，并提供委托授权书。 已知国内生产者的情况说明应包括已知国内生产者的名称、地址、邮政编码以及其他联系方式。"},{"i":13,"n":"第十三条","txt":"申请调查的产品的情况说明应包括产品的名称、种类、规格、用途、市场情况及该产品的中华人民共和国进口关税税则号等。 国内同类产品的情况说明应包括产品的名称、种类、规格、用途及市场情况等。 对二者的比较应包括在物理特征、化学性质、生产工艺、替代性和用途等方面的比较。"},{"i":14,"n":"第十四条","txt":"已知的出口商或国外生产商的情况说明应包括出口商或生产商的国别、名称、地址以及其他联系方式。 已知的进口商的情况说明应包括进口商的名称、地址、邮政编码以及其他联系方式。"},{"i":15,"n":"第十五条","txt":"国内产业的情况说明应包括申请提出前三年国内同类产品每年的产量，申请提出前三年申请人每年的产量及其在国内总产量中所占的比例。"},{"i":16,"n":"第十六条","txt":"补贴的情况说明应包括补贴的存在、性质、补贴金额和单位产品补贴额的估算额。 申请人应提供出口国（地区）给予补贴的法律文件，并列明估算单位产品接受补贴额的计算过程。"},{"i":17,"n":"第十七条","txt":"国内产业损害的情况说明主要包括国内产业损害的类型（实质损害、实质损害威胁或实质阻碍国内产业建立）、申请调查进口产品的数量变化及价格变化、对国内同类产品的价格影响、对国内产业相关经济因素和指标的影响等方面。"},{"i":18,"n":"第十八条","txt":"以实质损害为由提出申请的，申请人应当提供下列证据材料： （一）申请调查进口产品申请提出前三年的绝对进口数量或相对于国内同类产品生产量或消费量的数量增长情况； （二）申请调查进口产品申请提出前三年在中国国内销售的平均价格、平均价格变动图表等； （三）申请调查进口产品申请提出前三年对国内同类产品价格影响的情况，包括对国内同类产品价格削减情况、对国内同类产品的价格压低和抑制情况、影响国内产品价格的变动值等； （四）申请调查进口产品对国内产业状况的影响，包括对国内产业的产量、销售、市场份额、利润、生产率、投资收益、设备利用率、影响国内价格的相关因素、现金流动、就业、工资增长、筹集资本或投资的能力、库存等因素产生的影响；申请调查进口产品为农产品的，还应提供是否给政府支持计划增加负担的相关证据。上述某个别因素不适用的，申请人应当予以说明。"},{"i":19,"n":"第十九条","txt":"以损害威胁为由提出申请的，申请人应当提供下列损害证据材料： （一）申请调查进口产品进入国内市场的大幅增长率或增长的可能性的证据，包括：出口国（地区）现有及潜在的出口能力、库存等； （二）本规则第十八条第四项所规定的指标或因素指标的可明显预见并迫近的变化趋势。"},{"i":20,"n":"第二十条","txt":"以对国内产业的建立造成实质阻碍为由提出申请的，申请人除应提供第十九条规定的证据外，还应当提供国内产业建立的计划及其实际实施情况的证据等。"},{"i":21,"n":"第二十一条","txt":"国内产业的损害证据，应当针对国内同类产品的生产单独确定；不能针对国内同类产品的国内生产进行单独确定的，应当以包括国内同类产品在内的最窄产品组或者范围的生产确定。"},{"i":22,"n":"第二十二条","txt":"对补贴和损害之间因果关系的论证，申请人应当分析受补贴产品的进口和损害之间的关系；还应当说明非补贴进口产品的数量和价格、需求萎缩、消费方式的变化、外国与国内生产者的限制贸易的做法及它们之间的竞争、技术发展、以及国内产业的出口实绩和生产率等因素对国内产业损害的影响。上述因素不适用的，申请人应当予以说明。"},{"i":23,"n":"第二十三条","txt":"申请人在提供本章所规定的证据材料时，应当说明证据来源。"},{"i":24,"n":"第二十四条","txt":"申请中涉及保密材料的，申请人应当提出保密申请，同时应提交使案件其他利害关系方能够对保密材料有合理了解的非保密概要。不能提供非保密概要的，应说明理由。"},{"i":25,"n":"第二十五条","txt":"证据材料是外文的，申请人应当提供该证据材料的外文全文并提供相关部分的中文翻译件。"},{"i":26,"n":"第二十六条","txt":"申请人提交的反补贴调查立案申请书应当采用中文印刷体的形式；国家有统一规定术语的，应当采用规范词语。"},{"i":27,"n":"第二十七条","txt":"反补贴调查申请应当分为保密文本（如果申请人提出保密申请）和公开文本；保密文本应当提交正本1份，副本6份；公开文本除提交正本1份，副本6份外，还应当按已知的申请调查进口产品的出口国（地区）的数量提供副本，如涉及已知的申请调查进口产品的出口国（地区）的数量过多，可以适当减少但不能低于5份。"},{"i":28,"n":"第二十八条","txt":"申请人申请时应当按进出口公平贸易局要求的计算机程序提供申请书及其证据的电子数据载体。"},{"i":29,"n":"第二十九条","txt":"申请人可以以邮寄、直接送达或者进出口公平贸易局规定的其他方式将申请书及附具的证据材料递交进出口公平贸易局。"},{"i":30,"n":"第三十条","txt":"申请人正式递交申请书及证据材料的，进出口公平贸易局应予签收；签收之日为外经贸部收到申请书及证据材料之日。"},{"i":31,"n":"第三十一条","txt":"进出口公平贸易局应当自收到申请人提交的申请书及附具的证据材料之日起60天内，对申请进行审查，决定立案调查或者不立案调查。情况特别复杂的，可以适当延长审查期限。"},{"i":32,"n":"第三十二条","txt":"进出口公平贸易局应自收到申请人提交的申请书及附具的证据材料之日起7日内，向国家经济贸易委员会转交申请公开文本及保密文本各一套。国家经济贸易委员会至少应有20天对申请书及附具的证据材料进行研究并提出意见。"},{"i":33,"n":"第三十三条","txt":"进出口公平贸易局经审查后，可以要求申请人对其反补贴调查的申请进行调整或补充材料，申请人未如期按要求进行调整或补充材料的，可以驳回申请人的申请。"},{"i":34,"n":"第三十四条","txt":"外经贸部驳回申请人反补贴立案申请的，应当通知申请人并向其说明理由。"},{"i":35,"n":"第三十五条","txt":"经初步审查认为申请基本符合要求的，在决定立案调查前，外经贸部应当在决定立案前邀请出口国（地区）政府进行磋商，以澄清申请中所涉事项并寻求双方满意的解决办法。 出口国（地区）政府拒绝磋商的不影响反补贴措施程序进一步进行。"},{"i":36,"n":"第三十六条","txt":"外经贸部与出口国（地区）磋商成功取得一致意见达成协议的，外经贸部可以终止反补贴调查立案，通知申请人并说明理由。"},{"i":37,"n":"第三十七条","txt":"出口国（地区）政府接受邀请的，外经贸部可以适当延长反补贴立案期限，进行磋商。磋商应在6O天内结束。 磋商失败或者6O天内达不成协议的，不影响反补贴措施程序的进一步进行。"},{"i":38,"n":"第三十八条","txt":"决定不进行立案调查的，外经贸部不予以公告，但应通知申请人并说明理由。"},{"i":39,"n":"第三十九条","txt":"外经贸部决定不进行立案调查的，不得公布调查申请。"},{"i":40,"n":"第四十条","txt":"经审查决定进行立案调查的，由外经贸部予以公告并通知申请人、已知的出口商、进口商以及其他有利害关系的组织、个人和出口国（地区）政府。"},{"i":41,"n":"第四十一条","txt":"立案公告应当载明下列内容： （一）申请书概要及外经贸部对申请的审查结果； （二）发起调查依据材料的概要说明； （三）发起调查的日期； （四）调查产品出口国（地区）； （五）调查的产品； （六）调查期； （七）调查机关进行实地核查的意向； （八）利害关系方的不应诉将承担的后果； （九）利害关系方提出意见的时限； （十）调查机关的地址及联系方式。"},{"i":42,"n":"第四十二条","txt":"立案调查的决定一经公布，外经贸部应将申请书公开部分提供给已知的出口商和出口国（地区）政府。"},{"i":43,"n":"第四十三条","txt":"反补贴调查的立案日期为立案调查决定公告之日。"},{"i":44,"n":"第四十四条","txt":"在特殊情况下，外经贸部没有收到反补贴调查的书面申请，但有充分证据认为存在补贴和损害以及二者之间有因果关系的，经商国家经贸委后，可以自行决定立案调查。 自行决定立案的，外经贸部所掌握的证据应当符合本规则第三章规定的证据要求。"},{"i":45,"n":"第四十五条","txt":"自行决定立案的程序依照本章的规定。"},{"i":46,"n":"第四十六条","txt":"本规则由外经贸部负责解释。"},{"i":47,"n":"第四十七条","txt":"本规则自2002年3月13日起实施。"}],"fanbutiewenjuandiaochazanxingguize":[{"i":1,"n":"第一条","txt":"为了保证反补贴问卷调查规范有序地进行，根据《中华人民共和国反补贴条例》的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"对外贸易经济合作部（以下简称外经贸部）指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"本规则适用于外经贸部为确定补贴及补贴金额而通过调查问卷方式进行的反补贴调查。"},{"i":4,"n":"第四条","txt":"本规则所称的调查问卷是指在反补贴调查中，外经贸部向报名应诉的被调查国家（地区）的生产商或出口商（以下简称应诉公司）发放的书面问题单。"},{"i":5,"n":"第五条","txt":"应诉公司应按照外经贸部的要求，完整而准确地回答调查问卷中所列问题，提交调查问卷中所要求的信息和资料。"},{"i":6,"n":"第六条","txt":"被调查国家（地区）的生产商或出口商应自反补贴调查立案之日起20日内，按照立案公告的要求，向外经贸部报名应诉。"},{"i":7,"n":"第七条","txt":"报名应诉的生产商或出口商向外经贸部报名应诉时，应以印刷体简体中文形式提交以下信息： 1、报名应诉的意思表示； 2、应诉公司的名称、地址、法定代表人、联系方式和联系人； 3、调查期内向中华人民共和国出口被调查产品的总数量、总金额。 报名应诉文件应有应诉公司的盖章和（或）其法定代表人的签字。 如申请书委托中华人民共和国执业律师代理呈送，应列出代理律师的姓名和联系方式、所在的律师事务所及其地址，并附授权委托书原件。"},{"i":8,"n":"第八条","txt":"调查问卷应在报名应诉截止之日起10个工作日内，向应诉公司发放。"},{"i":9,"n":"第九条","txt":"如应诉公司数量过多，外经贸部决定采取抽样方式进行反补贴调查的，调查问卷可以只发放给经抽样选中的应诉公司。 如涉及抽样调查，外经贸部可对发放问卷的期限进行适当延长。"},{"i":10,"n":"第十条","txt":"应诉公司应在规定时间内提交完整而准确的答卷。答卷应当包括调查问卷所要求的全部信息。"},{"i":11,"n":"第十一条","txt":"如应诉公司在回答问卷时对调查问卷有疑问，可以书面形式向调查问卷所列明的案件调查人员咨询。"},{"i":12,"n":"第十二条","txt":"应诉公司在回答调查问卷所列问题时，应首先列 出问题题目，并在题目下直接回答。"},{"i":13,"n":"第十三条","txt":"答卷应当以印刷体简体中文形式填制，并按要求提供相关证据材料。如证据材料原件是外文的，应按照外文原文的格式提供中文翻译件，并附外文原文或复印件。"},{"i":14,"n":"第十四条","txt":"应诉公司应指明答卷中所使用的证据材料的来源和出处。所有与答卷有关的销售单证、会计记录、财务报告和其他文件除按要求附在公司的答卷中之外，均应留备核查。"},{"i":15,"n":"第十五条","txt":"答卷要求提供的证据材料应按照交易发生的时间顺序进行整理；每一笔交易的证据材料应按照交易流程进行整理，并提供该笔交易的证据材料清单。"},{"i":16,"n":"第十六条","txt":"如果应诉公司按照问卷要求应将调查问卷复印转交给关联贸易公司或其他公司填制时，该关联贸易公司或其他公司应按问卷要求独立提交答卷。"},{"i":17,"n":"第十七条","txt":"调查问卷的答卷应当在问卷发放之日起37日内送达外经贸部。"},{"i":18,"n":"第十八条","txt":"如果应诉公司有正当理由表明在答卷到期日不能完成答卷，应在问卷提交截止期限7日前向外经贸部提出延期提交答卷书面申请，陈述延期请求和延期理由。 外经贸部应在问卷提交截止期限4日前，根据申请延期的应诉公司的具体情况对申请延期请求做出书面答复。 通常情况下，延期不超过14日。"},{"i":19,"n":"第十九条","txt":"应诉公司认为答卷中有需要保密内容的，应当提出保密处理的申请，并陈述需要保密的理由。 对要求保密处理的信息，应提供一份非保密概要。非保密概要应包括充分的有意义的信息，以使其他利害关系方对保密信息能有合理的了解。如不能提供非保密概要，应说明理由。"},{"i":20,"n":"第二十条","txt":"外经贸部应当对保密申请进行审查。如认为保密理由不能成立或非保密概要不能满足第十九条第二款的要求，或应诉公司不能提供非保密概要的理由不充分，可要求应诉公司在规定期限内进行修改。 如应诉公司拒绝修改或修改后的非保密概要仍然不符合要求，外经贸部可对该材料不予考虑。"},{"i":21,"n":"第二十一条","txt":"答卷应做成两种类型，一类为含有保密信息的完整答卷，一类为只包括公开信息的答卷。应诉公司应在答卷首页注明保密答卷或公开答卷。公开答卷中涉及保密的部分应当用“〖〗”号标注，并注明相应非保密概要的序号。"},{"i":22,"n":"第二十二条","txt":"应诉公司应提交公开答卷和保密答卷中文原件各一份、中文复印件各四份。 所有答卷均须妥善装订成册。答卷正文和所附证据材料均应按顺序标注页码。答卷应包含答卷目录和附件目录，每一附件均应列明序号。"},{"i":23,"n":"第二十三条","txt":"应诉公司应按照答卷要求提供一份证明信，声明应诉公司提供的信息是准确和完整的，并由应诉公司法定代表人或其授权人签署。 外经贸部对没有附具证明信的答卷不予接受。"},{"i":24,"n":"第二十四条","txt":"应诉公司提供的书面答卷和数据表格，应按照问卷要求提交计算机软盘、光盘或外经贸部可接受的其他电子数据载体。 电子数据载体的内容应当与答卷中的格式完全一致，表格中数据涉及到计算的部分应保留计算公式。"},{"i":25,"n":"第二十五条","txt":"应诉公司应保证提供的电子数据载体不携带病毒。如果携带病毒，可被视为阻碍调查，外经贸部可依据可获得的事实和现有最佳材料做出裁定。"},{"i":26,"n":"第二十六条","txt":"通常情况下，不提供电子数据载体，特别是不提供交易和财务数据电子数据载体的应诉公司，将被视为不合作。 如果应诉公司无法提供电子数据载体或者无法按照本规则要求提供电子数据载体，或者按照本规则要求提供电子数据载体将给应诉公司造成不合理的额外负担，应诉公司应在问卷发放之日起15日内向外经贸部提交书面申请，说明无法按要求提供电子数据载体的理由。外经贸部在接到申请后5日内对是否同意申请做出书面答复。"},{"i":27,"n":"第二十七条","txt":"应诉公司的答卷应通过中华人民共和国执业律师代理呈送并由代理律师处理相关事宜。答卷中应提供一份有效的律师授权委托书及该代理律师有效的执业证书复印件。"},{"i":28,"n":"第二十八条","txt":"调查问卷的答卷应在答卷截止当日17：00之前寄至或直接送至问卷所列地址。 送达日为外经贸部收到答卷的日期。"},{"i":29,"n":"第二十九条","txt":"在反补贴调查中，外经贸部可向应诉公司发放补充问卷，要求提供补充信息和材料。 关于补充问卷的发放、回答以及提交等事宜应符合本规则。"},{"i":30,"n":"第三十条","txt":"应诉公司在规定的期限内不提交答卷，或者不能按照本规则的要求提供完整而准确的答卷，或者对其所提供的资料不允许外经贸部进行核查，或者以其他方式严重妨碍调查的，则外经贸部可依据可获得的事实和现有最佳材料做出初步或者最终裁定。"},{"i":31,"n":"第三十一条","txt":"外经贸部可在立案调查公告后30日内向出口国（地区）政府或原产国（地区）政府发放调查问卷。调查问卷的发放、回答及提交参照本规则。"},{"i":32,"n":"第三十二条","txt":"本规则由外经贸部负责解释。"},{"i":33,"n":"第三十三条","txt":"本规则自2002年4月15日起实施。"}],"xiangtedingguojiachukouyizhiduhuaxuepinzanxingguan05dd35":[{"i":1,"n":"第一条","txt":"为防止易制毒化学品流入特定国家（地区）用于毒品制造，规范易制毒化学品出口活动，根据《中华人民共和国对外贸易法》及有关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称易制毒化学品是指本规定附件1《向特定国家(地区)出口易制毒化学品管理目录》所列化学品。商务部会同公安部、海关总署、国家安全生产监督管理总局和国家食品药品监督管理局可根据需要调整并公布《向特定国家（地区）出口易制毒化学品管理目录》。"},{"i":3,"n":"第三条","txt":"本规定所称特定国家（地区）是指本规定附件2《特定国家（地区）目录》所列国家（地区）。商务部会同公安部、海关总署、国家安全生产监督管理总局和国家食品药品监督管理局可根据需要调整并公布《特定国家（地区）目录》。"},{"i":4,"n":"第四条","txt":"国家对易制毒化学品向特定国家（地区）的出口实行许可证管理。 未经许可，不得向特定国家（地区）出口易制毒化学品。 向特定国家（地区）出口易制毒化学品时，应向海关交验有关出口许可证，海关凭出口许可证办理有关出口验放手续。"},{"i":5,"n":"第五条","txt":"易制毒化学品出口许可证实行“一批一证”制和“一证一关”制。 同一合同项下如需分批出口，出口经营者应在出口申请中提出，由商务部核准后,签发相应份数的出口许可证。同一申请最多分批不超过12次。"},{"i":6,"n":"第六条","txt":"向特定国家（地区）出口易制毒化学品实行国际核查制度。"},{"i":7,"n":"第七条","txt":"出口经营者拟向特定国家（地区）出口易制毒化学品的，应向所在地省级商务主管部门提出申请，并提交以下书面材料： （一）《易制毒化学品出口申请表》一式二份； （二）出口合同（协议）副本； （三）进口国（地区）政府主管部门出具的合法使用易制毒化学品的证明或者进口方合法使用的保证文件原件； （四）出口经营者营业执照复印件； （五）对外贸易经营者备案登记表复印件（外商投资企业提交批准证书复印件）。"},{"i":8,"n":"第八条","txt":"省级商务主管部门应在受理申请之日起3日内进行初审，经初审合格后，将初审意见及有关材料报商务部审批。"},{"i":9,"n":"第九条","txt":"商务部自收到省级商务主管部门的初审意见之日起5日内完成审查，审查合格的，将审查意见和有关材料转公安部进行国际核查。"},{"i":10,"n":"第十条","txt":"公安部自收到商务部的审查意见和有关材料之日起3日内将核查材料发送进口国（地区）政府主管部门。 公安部自收到进口国（地区）政府主管部门确认通知后3日内书面通知商务部。 商务部自收到公安部书面通知之日起5日内，做出许可或者不许可的决定。"},{"i":11,"n":"第十一条","txt":"出口经营者在申领易制毒化学品出口许可证时，应如实申报，不得弄虚作假。严禁以欺骗或其他不正当手段获取易制毒化学品出口许可。 不得伪造、变造或者买卖易制毒化学品出口许可证。"},{"i":12,"n":"第十二条","txt":"易制毒化学品出口管理有关部门应当建立信息交流和电子数据联网核查制度。"},{"i":13,"n":"第十三条","txt":"违反本规定，未经许可擅自向特定国家（地区）出口或者擅自超出许可的范围出口易制毒化学品，伪造、变造或者买卖易制毒化学品出口许可证件以及以欺骗或者其他不正当手段获取易制毒化学品出口许可证件的，依照《对外贸易法》、《海关法》等法律、行政法规的规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"对易制毒化学品实施出口管理的国家工作人员玩忽职守、徇私舞弊、滥用职权或者利用职务上的便利索取他人财物、非法收受他人财物为他人谋取利益，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":15,"n":"第十五条","txt":"由保税区、出口加工区等海关特殊监管区域、保税场所向特定国家（地区）出口易制毒化学品，适用本规定。 易制毒化学品由境内运入保税区、出口加工区等海关特殊监管区域、保税场所，或者在上述海关特殊监管区域、保税场所之间进出，无须申领出口许可证。"},{"i":16,"n":"第十六条","txt":"向特定国家（地区）出口易制毒化学品，本规定没有规定的，依照原外经贸部制定的《易制毒化学品进出口管理规定》（原外经贸部1999年第4号令）、原外经贸部和公安部联合制定的《易制毒化学品进出口国际核查管理规定》（外经贸贸发[2002]147号）的有关规定办理。"},{"i":17,"n":"第十七条","txt":"本规定自2005年9月1日起施行。 附件： 1.向特定国家（地区）出口易制毒化学品管理目录 2.特定国家（地区）目录 1、缅甸 2、老挝"}],"shangyetexujingyingxinxipiluguanlibanfa":[{"i":1,"n":"第一条","txt":"为维护特许人与被特许人双方的合法权益，根据《商业特许经营管理条例》（以下简称《条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内开展商业特许经营活动适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称关联方，是指特许人的母公司或其自然人股东、特许人直接或间接拥有全部或多数股权的子公司、与特许人直接或间接地由同一所有人拥有全部或多数股权的公司。"},{"i":4,"n":"第四条","txt":"特许人应当按照《条例》的规定，在订立商业特许经营合同之日前至少30日，以书面形式向被特许人披露本办法第五条规定的信息，但特许人与被特许人以原特许合同相同条件续约的情形除外。"},{"i":5,"n":"第五条","txt":"特许人进行信息披露应当包括以下内容： （一）特许人及特许经营活动的基本情况。 1．特许人名称、通讯地址、联系方式、法定代表人、总经理、注册资本额、经营范围以及现有直营店的数量、地址和联系电话。 2．特许人从事商业特许经营活动的概况。 3．特许人备案的基本情况。 4．由特许人的关联方向被特许人提供产品和服务的，应当披露该关联方的基本情况。 5．特许人或其关联方过去2年内破产或申请破产的情况。 （二）特许人拥有经营资源的基本情况。 1．注册商标、企业标志、专利、专有技术、经营模式及其他经营资源的文字说明。 2．经营资源的所有者是特许人关联方的，应当披露该关联方的基本信息、授权内容，同时应当说明在与该关联方的授权合同中止或提前终止的情况下，如何处理该特许体系。 3．特许人（或其关联方）的注册商标、企业标志、专利、专有技术等与特许经营相关的经营资源涉及诉讼或仲裁的情况。 （三）特许经营费用的基"},{"i":6,"n":"第六条","txt":"特许人在推广、宣传活动中，不得有欺骗、误导的行为，发布的广告中不得含有宣传单个被特许人从事商业特许经营活动收益的内容。"},{"i":7,"n":"第七条","txt":"特许人向被特许人披露信息前，有权要求被特许人签署保密协议。 被特许人在订立合同过程中知悉的商业秘密，无论特许经营合同是否成立，不得泄露或者不正当使用。 特许经营合同终止后，被特许人因合同关系知悉特许人商业秘密的，即使未订立合同终止后的保密协议，也应当承担保密义务。 被特许人违反本条　前两款规定，泄露或者不正当使用商业秘密给特许人或者其他人造成损失的，应当承担相应的损害赔偿责任。"},{"i":8,"n":"第八条","txt":"特许人在向被特许人进行信息披露后，被特许人应当就所获悉的信息内容向特许人出具回执说明（一式两份），由被特许人签字，一份由被特许人留存，另一份由特许人留存。"},{"i":9,"n":"第九条","txt":"特许人隐瞒影响特许经营合同履行致使不能实现合同目的的信息或者披露虚假信息的，被特许人可以解除特许经营合同。"},{"i":10,"n":"第十条","txt":"特许人违反本办法有关规定的，被特许人有权向商务主管部门举报，经查实的，分别依据《条例》第二十六条、第二十七条、第二十八条予以处罚。"},{"i":11,"n":"第十一条","txt":"本办法由中华人民共和国商务部负责解释。"},{"i":12,"n":"第十二条","txt":"本办法自2012年4月1日起施行。原《商业特许经营信息披露管理办法》（商务部令2007年第16号）同时废止。"}],"shangyetexujingyingbeianguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对商业特许经营活动的管理，规范特许经营市场秩序，根据《商业特许经营管理条例》（以下简称《条例》）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内（以下简称中国境内）从事商业特许经营活动，适用本办法。"},{"i":3,"n":"第三条","txt":"商务部及省、自治区、直辖市人民政府商务主管部门是商业特许经营的备案机关。在省、自治区、直辖市范围内从事商业特许经营活动的，向特许人所在地省、自治区、直辖市人民政府商务主管部门备案；跨省、自治区、直辖市范围从事特许经营活动的，向商务部备案。 商业特许经营实行全国联网备案。符合《条例》规定的特许人，依据本办法规定通过商务部设立的商业特许经营信息管理系统进行备案。"},{"i":4,"n":"第四条","txt":"商务部可以根据有关规定，将跨省、自治区、直辖市范围从事商业特许经营的备案工作委托有关省、自治区、直辖市人民政府商务主管部门完成。受委托的省、自治区、直辖市人民政府商务主管部门应当自行完成备案工作，不得再委托其他任何组织和个人备案。 受委托的省、自治区、直辖市人民政府商务主管部门未依法行使备案职责的，商务部可以直接受理特许人的备案申请。"},{"i":5,"n":"第五条","txt":"任何单位或者个人对违反本办法规定的行为，有权向商务主管部门举报，商务主管部门应当依法处理。"},{"i":6,"n":"第六条","txt":"申请备案的特许人应当向备案机关提交以下材料： （一）商业特许经营基本情况。 （二）中国境内全部被特许人的店铺分布情况。 （三）特许人的市场计划书。 （四）企业法人营业执照或其他主体资格证明。 （五）与特许经营活动相关的商标权、专利权及其他经营资源的注册证书。 （六）符合《条例》第七条第二款规定的证明文件。 在2007年5月1日前已经从事特许经营活动的特许人在提交申请商业特许经营备案材料时不适用于上款的规定。 （七）与中国境内的被特许人订立的第一份特许经营合同。 （八）特许经营合同样本。 （九）特许经营操作手册的目录（须注明每一章节的页数和手册的总页数，对于在特许系统内部网络上提供此类手册的，须提供估计的打印页数）。 （十）国家法律法规规定经批准方可开展特许经营的产品和服务，须提交相关主管部门的批准文件。 （十一）经法定代表人签字盖章的特许人承诺。 （十二）备案机关认为应当提交的其他资料"},{"i":7,"n":"第七条","txt":"特许人应当在与中国境内的被特许人首次订立特许经营合同之日起15日内向备案机关申请备案。"},{"i":8,"n":"第八条","txt":"特许人的以下备案信息有变化的，应当自变化之日起30日内向备案机关申请变更： （一）特许人的工商登记信息。 （二）经营资源信息。 （三）中国境内全部被特许人的店铺分布情况。"},{"i":9,"n":"第九条","txt":"特许人应当在每年3月31日前将其上一年度订立、撤销、终止、续签的特许经营合同情况向备案机关报告。"},{"i":10,"n":"第十条","txt":"特许人应认真填写所有备案事项的信息，并确保所填写内容真实、准确和完整。"},{"i":11,"n":"第十一条","txt":"备案机关应当自收到特许人提交的符合本办法第六条规定的文件、资料之日起10日内予以备案，并在商业特许经营信息管理系统予以公告。 特许人提交的文件、资料不完备的，备案机关可以要求其在7日内补充提交文件、资料。备案机关在特许人材料补充齐全之日起10日内予以备案。"},{"i":12,"n":"第十二条","txt":"已完成备案的特许人有下列行为之一的，备案机关可以撤销备案，并在商业特许经营信息管理系统予以公告： （一）特许人注销工商登记，或因特许人违法经营，被主管登记机关吊销营业执照的。 （二）备案机关收到司法机关因为特许人违法经营而作出的关于撤销备案的司法建议书。 （三）特许人隐瞒有关信息或者提供虚假信息，造成重大影响的。 （四）特许人申请撤销备案并经备案机关同意的。 （五）其他需要撤销备案的情形。"},{"i":13,"n":"第十三条","txt":"各省、自治区、直辖市人民政府商务主管部门应当将备案及撤销备案的情况在10日内反馈商务部。"},{"i":14,"n":"第十四条","txt":"备案机关应当完整准确地记录和保存特许人的备案信息材料，依法为特许人保守商业秘密。 特许人所在地的（省、自治区、直辖市或设区的市级）人民政府商务主管部门可以向通过备案的特许人出具备案证明。"},{"i":15,"n":"第十五条","txt":"公众可通过商业特许经营信息管理系统查询以下信息： （一）特许人的企业名称及特许经营业务使用的注册商标、企业标志、专利、专有技术等经营资源。 （二）特许人的备案时间。 （三）特许人的法定经营场所地址与联系方式、法定代表人姓名。 （四）中国境内全部被特许人的店铺分布情况。"},{"i":16,"n":"第十六条","txt":"特许人未按照《条例》和本办法的规定办理备案的，由设区的市级以上商务主管部门责令限期备案，并处1万元以上5万元以下罚款；逾期仍不备案的，处5万元以上10万元以下罚款，并予以公告。"},{"i":17,"n":"第十七条","txt":"特许人违反本办法第九条规定的，由设区的市级以上商务主管部门责令改正，可以处1万元以下的罚款；情节严重的，处1万元以上5万元以下的罚款，并予以公告。"},{"i":18,"n":"第十八条","txt":"国外特许人在中国境内从事特许经营活动，按照本办法执行。香港、澳门特别行政区及台湾地区特许人参照本办法执行。"},{"i":19,"n":"第十九条","txt":"相关协会组织应当依照本办法规定，加强行业自律，指导特许人依法备案。"},{"i":20,"n":"第二十条","txt":"本办法由商务部负责解释。"},{"i":21,"n":"第二十一条","txt":"本办法自公布之日起施行。"}],"shangwubuguojiagongshanghangzhengguanlijuguanyuwaiaad8fc":[{"i":1,"n":"第一条","txt":"为规范外商投资企业的投资行为，根据《中华人民共和国公司法》（以下简称“《公司法》”）以及有关外商投资的法律、法规的有关规定，制订本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外商投资企业境内投资，是指在中国境内依法设立，采取有限责任公司形式的中外合资经营企业、中外合作经营企业和外资企业以及外商投资股份有限公司，以本企业的名义，在中国境内投资设立企业或购买其他企业（以下简称“被投资公司”）投资者股权的行为。 外商投资举办的投资性公司境内投资，依照国家有关外商投资的法律、法规以及《关于外商投资举办投资性公司的暂行规定》办理。 外国投资者与外商投资企业共同在中国境内投资，按照国家有关外商投资的法律、法规办理，其中外国投资者的出资比例一般不得低于被投资企业注册资本的百分之二十五。"},{"i":3,"n":"第三条","txt":"外商投资企业境内投资，应遵守国家法律、法规。 外商投资企业境内投资比照执行《指导外商投资方向暂行规定》和《外商投资产业指导目录》的规定。外商投资企业不得在禁止外商投资的领域投资。"},{"i":4,"n":"第四条","txt":"被投资公司应为有限责任公司或股份有限公司。"},{"i":5,"n":"第五条","txt":"外商投资企业应符合下列条件，方可投资： 1、开始盈利； 2、依法经营，无违法经营记录。"},{"i":6,"n":"第六条","txt":"外商投资企业在鼓励类或允许类领域投资设立公司，应向被投资公司所在地公司登记机关提出申请，并应提供下列材料： 1、外商投资企业关于投资的一致通过的董事会决议； 2、外商投资企业的批准证书和营业执照（复印件）； 3、外商投资企业经审计的资产负债表； 4、外商投资企业缴纳所得税或减免所得税的证明材料； 5、法律、法规及规章规定的其他材料。"},{"i":7,"n":"第七条","txt":"公司登记机关依《公司法》、《中华人民共和国公司登记管理条例》（以下简称《公司登记管理条例》）的有关规定，决定准予登记或不予登记。准予登记的，发给《企业法人营业执照》，并在企业类别栏目加注“外商投资企业投资”字样（以下简称“《（加注）营业执照》”）。"},{"i":8,"n":"第八条","txt":"外商投资企业在限制类领域投资设立公司的，应向被投资公司所在地省级外经贸主管部门（以下称“省级审批机关”）提出申请，并应提供下列材料： 1、依照第六条规定提供的材料； 2、被投资公司的章程。 被投资公司的章程应当载明下列事项： （1）公司名称和住所； （2）公司经营范围及产品国内外销售比例； （3）公司注册资本； （4）投资者的名称或姓名； （5）投资者的权利和义务； （6）投资者的出资方式和出资额； （7）投资者转让出资的条件； （8）公司的机构及其产生办法、职权、议事规则； （9）公司的法定代表人； （10）公司的解散事由与清算办法； （11）投资者认为需要规定的其他事项。 投资者应当在公司章程上签名、盖章。"},{"i":9,"n":"第九条","txt":"省级审批机关接到上述申请后，按照被投资公司的经营范围，征求同级或国家行业管理部门的意见。 省级审批机关应自收到同级或国家管理行业部门同意或不同意的意见起十日之内，作出书面批复。"},{"i":10,"n":"第十条","txt":"省级审批机关对外商投资企业作出同意批复的，外商投资企业凭该批复文件向被投资公司所在地公司登记机关申请设立登记。 公司登记机关依《公司登记管理条例》的有关规定，决定准予登记或不予登记。准予登记的，发给《（加注）营业执照》。"},{"i":11,"n":"第十一条","txt":"自被投资公司设立之日起三十日内，外商投资企业应向原审批机关备案。备案材料包括： 1、外商投资企业投资备案表； 2、被投资公司的营业执照（复印件）； 3、被投资公司经营范围涉及限制类领域的，还应提交省级审批机关作出的同意设立被投资公司的批复。"},{"i":12,"n":"第十二条","txt":"外商投资企业以其固定资产投资而改变原经营规模或内容的，投资前应向原审批机关申请并征得原审批机关的同意。 原审批机关应自接到申请之日起十五日之内予以答复；逾期不答复的，视作同意。 原审批机关不同意的，外商投资企业可向其上级审批机关或对外贸易经济合作部（以下简称“外经贸部”）提出申诉。该上级审批机关或外经贸部应自收到申诉之日起三十日内，对外商投资企业作出书面答复。"},{"i":13,"n":"第十三条","txt":"按照本规定第六条、第七条设立的公司变更经营范围，涉及限制类领域的，应按照本规定第八条、第九条规定的程序办理，并向其原公司登记机关申请变更登记。"},{"i":14,"n":"第十四条","txt":"外商投资企业购买被投资公司投资者的股权，被投资公司经营范围属于鼓励类或允许类领域的，被投资公司应向原公司登记机关报送本规定第六条所列的材料，并按照《公司登记管理条例》等有关规定，申请变更登记。 被投资公司经营范围涉及限制类领域的，外商投资企业应按照本规定第八条、第九条规定的程序办理后，被投资公司凭省级审批机关的同意批复，按照《公司登记管理条例》等有关规定，向原公司登记机关申请变更登记。 公司登记机关依《公司登记管理条例》的有关规定，决定予以登记或不予登记。准予登记的，发给“（加注）营业执照”。 被投资公司属于外商投资企业的，按照《外商投资企业投资者股权变更的规定》办理。"},{"i":15,"n":"第十五条","txt":"外商投资企业向中西部地区投资，被投资公司注册资本中外资比例不低于百分之二十五的，可享受外商投资企业待遇。"},{"i":16,"n":"第十六条","txt":"被投资公司享受外商投资企业待遇，应按有关外商投资企业设立程序的规定，向被投资公司所在地的省级审批机关提出申请。申请人应提供下列材料： 1、依照第六条规定应提供的材料； 2、被投资公司的名称、住所； 3、被投资公司的投资合同及章程； 4、被投资公司经营范围涉及限制类领域的，还应提交设立被投资公司的项目建议书和可行性研究报告。 其投资者出让股权的被投资公司享受外商投资企业待遇的，申请人除向被投资公司所在地的省级审批机关提供上款所列材料之外，还应提交相应的投资者股权转让协议。"},{"i":17,"n":"第十七条","txt":"省级审批机关确认外商投资企业的投资符合国家有关法律、法规且被投资公司注册资本中外资比例不低于百分之二十五的，向申请人下发批准文件，颁发《外商投资企业批准证书》，并加注“外商投资企业投资”字样。 被投资公司经营范围涉及限制类领域的，省级审批机关批准之前，应依照本规定第十条的规定，征求有关行业管理部门的意见。"},{"i":18,"n":"第十八条","txt":"申请人凭《外商投资企业批准证书》向被投资公司所在地公司登记机关申请登记注册。 公司登记机关依《公司登记管理条例》的有关规定，决定准予登记或不予登记。准予登记的，发给《（加注）营业执照》。 被投资公司经营范围未涉及限制类领域的，按本规定第六条办理。"},{"i":19,"n":"第十九条","txt":"中西部地区的被投资公司凭《外商投资企业批准证书》和《（加注）营业执照》享受国家法律、法规规定的外商投资企业待遇。"},{"i":20,"n":"第二十条","txt":"在中西部地区设立的被投资公司投资总额超过其所在省、自治区、直辖市审批机关审批权限的，应报外经贸部审批。"},{"i":21,"n":"第二十一条","txt":"被投资公司属于法律、法规和部门规章明确规定的应由外经贸部审批的特定类型或行业的外商投资企业的，省级审批机关应将有关申请材料转报外经贸部审批。外经贸部根据有关法律、法规和部门规章的规定决定批准或不批准。"},{"i":22,"n":"第二十二条","txt":"本规定颁布前，根据有关规定已设立的外商投资企业参股企业，符合本规定要求的，可参照本规定补办有关手续，享受外商投资企业待遇。"},{"i":23,"n":"第二十三条","txt":"本规定由外经贸部和国家工商行政管理局负责解释。"},{"i":24,"n":"第二十四条","txt":"本规定自2000年9月1日起施行。 附：外商投资企业投资备案表"}],"shangwubuguanyuwaiguotouzizhebinggoujingneiqiyedege2eba0":[{"i":1,"n":"第一条","txt":"为了促进和规范外国投资者来华投资，引进国外的先进技术和管理经验，提高利用外资的水平，实现资源的合理配置，保证就业、维护公平竞争和国家经济安全，依据外商投资企业的法律、行政法规及《公司法》和其他相关法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外国投资者并购境内企业，系指外国投资者购买境内非外商投资企业（以下称“境内公司”）股东的股权或认购境内公司增资，使该境内公司变更设立为外商投资企业（以下称“股权并购”）；或者，外国投资者设立外商投资企业，并通过该企业协议购买境内企业资产且运营该资产，或，外国投资者协议购买境内企业资产，并以该资产投资设立外商投资企业运营该资产（以下称“资产并购”）。"},{"i":3,"n":"第三条","txt":"外国投资者并购境内企业应遵守中国的法律、行政法规和规章，遵循公平合理、等价有偿、诚实信用的原则，不得造成过度集中、排除或限制竞争，不得扰乱社会经济秩序和损害社会公共利益，不得导致国有资产流失。"},{"i":4,"n":"第四条","txt":"外国投资者并购境内企业，应符合中国法律、行政法规和规章对投资者资格的要求及产业、土地、环保等政策。 依照《外商投资产业指导目录》不允许外国投资者独资经营的产业，并购不得导致外国投资者持有企业的全部股权；需由中方控股或相对控股的产业，该产业的企业被并购后，仍应由中方在企业中占控股或相对控股地位；禁止外国投资者经营的产业，外国投资者不得并购从事该产业的企业。 被并购境内企业原有所投资企业的经营范围应符合有关外商投资产业政策的要求；不符合要求的，应进行调整。"},{"i":5,"n":"第五条","txt":"外国投资者并购境内企业涉及企业国有产权转让和上市公司国有股权管理事宜的，应当遵守国有资产管理的相关规定。"},{"i":6,"n":"第六条","txt":"外国投资者并购境内企业设立外商投资企业，应依照本规定经审批机关批准，向登记管理机关办理变更登记或设立登记。 如果被并购企业为境内上市公司，还应根据《外国投资者对上市公司战略投资管理办法》，向国务院证券监督管理机构办理相关手续。"},{"i":7,"n":"第七条","txt":"外国投资者并购境内企业所涉及的各方当事人应当按照中国税法规定纳税，接受税务机关的监督。"},{"i":8,"n":"第八条","txt":"外国投资者并购境内企业所涉及的各方当事人应遵守中国有关外汇管理的法律和行政法规，及时向外汇管理机关办理各项外汇核准、登记、备案及变更手续。"},{"i":9,"n":"第九条","txt":"外国投资者在并购后所设外商投资企业注册资本中的出资比例高于25％的，该企业享受外商投资企业待遇。 外国投资者在并购后所设外商投资企业注册资本中的出资比例低于25%的，除法律和行政法规另有规定外，该企业不享受外商投资企业待遇，其举借外债按照境内非外商投资企业举借外债的有关规定办理。审批机关向其颁发加注“外资比例低于25%”字样的外商投资企业批准证书（以下称“批准证书”）。登记管理机关、外汇管理机关分别向其颁发加注“外资比例低于25%”字样的外商投资企业营业执照和外汇登记证。 境内公司、企业或自然人以其在境外合法设立或控制的公司名义并购与其有关联关系的境内公司，所设立的外商投资企业不享受外商投资企业待遇，但该境外公司认购境内公司增资，或者该境外公司向并购后所设企业增资，增资额占所设企业注册资本比例达到25%以上的除外。根据该款所述方式设立的外商投资企业，其实际控制人以外的外国投资者在企业注"},{"i":10,"n":"第十条","txt":"本规定所称的审批机关为中华人民共和国商务部或省级商务主管部门（以下称“省级审批机关”），登记管理机关为中华人民共和国国家工商行政管理总局或其授权的地方工商行政管理局，外汇管理机关为中华人民共和国国家外汇管理局或其分支机构。 并购后所设外商投资企业，根据法律、行政法规和规章的规定，属于应由商务部审批的特定类型或行业的外商投资企业的，省级审批机关应将申请文件转报商务部审批，商务部依法决定批准或不批准。"},{"i":11,"n":"第十一条","txt":"境内公司、企业或自然人以其在境外合法设立或控制的公司名义并购与其有关联关系的境内的公司，应报商务部审批。 当事人不得以外商投资企业境内投资或其他方式规避前述要求。"},{"i":12,"n":"第十二条","txt":"外国投资者并购境内企业并取得实际控制权，涉及重点行业、存在影响或可能影响国家经济安全因素或者导致拥有驰名商标或中华老字号的境内企业实际控制权转移的，当事人应就此向商务部进行申报。 当事人未予申报，但其并购行为对国家经济安全造成或可能造成重大影响的，商务部可以会同相关部门要求当事人终止交易或采取转让相关股权、资产或其他有效措施，以消除并购行为对国家经济安全的影响。"},{"i":13,"n":"第十三条","txt":"外国投资者股权并购的，并购后所设外商投资企业承继被并购境内公司的债权和债务。 外国投资者资产并购的，出售资产的境内企业承担其原有的债权和债务。 外国投资者、被并购境内企业、债权人及其他当事人可以对被并购境内企业的债权债务的处置另行达成协议，但是该协议不得损害第三人利益和社会公共利益。债权债务的处置协议应报送审批机关。 出售资产的境内企业应当在投资者向审批机关报送申请文件之前至少15日，向债权人发出通知书，并在全国发行的省级以上报纸上发布公告。"},{"i":14,"n":"第十四条","txt":"并购当事人应以资产评估机构对拟转让的股权价值或拟出售资产的评估结果作为确定交易价格的依据。并购当事人可以约定在中国境内依法设立的资产评估机构。资产评估应采用国际通行的评估方法。禁止以明显低于评估结果的价格转让股权或出售资产，变相向境外转移资本。 外国投资者并购境内企业，导致以国有资产投资形成的股权变更或国有资产产权转移时，应当符合国有资产管理的有关规定。"},{"i":15,"n":"第十五条","txt":"并购当事人应对并购各方是否存在关联关系进行说明，如果有两方属于同一个实际控制人，则当事人应向审批机关披露其实际控制人，并就并购目的和评估结果是否符合市场公允价值进行解释。当事人不得以信托、代持或其他方式规避前述要求。"},{"i":16,"n":"第十六条","txt":"外国投资者并购境内企业设立外商投资企业，外国投资者应自外商投资企业营业执照颁发之日起3个月内向转让股权的股东，或出售资产的境内企业支付全部对价。对特殊情况需要延长者，经审批机关批准后，应自外商投资企业营业执照颁发之日起6个月内支付全部对价的60%以上，1年内付清全部对价，并按实际缴付的出资比例分配收益。 外国投资者认购境内公司增资，有限责任公司和以发起方式设立的境内股份有限公司的股东应当在公司申请外商投资企业营业执照时缴付不低于20%的新增注册资本，其余部分的出资时间应符合《公司法》、有关外商投资的法律和《公司登记管理条例》的规定。其他法律和行政法规另有规定的，从其规定。股份有限公司为增加注册资本发行新股时，股东认购新股，依照设立股份有限公司缴纳股款的有关规定执行。 外国投资者资产并购的，投资者应在拟设立的外商投资企业合同、章程中规定出资期限。设立外商投资企业，并通过该企业协议购买境内"},{"i":17,"n":"第十七条","txt":"作为并购对价的支付手段，应符合国家有关法律和行政法规的规定。外国投资者以其合法拥有的人民币资产作为支付手段的，应经外汇管理机关核准。外国投资者以其拥有处置权的股权作为支付手段的，按照本规定第四章办理。"},{"i":18,"n":"第十八条","txt":"外国投资者协议购买境内公司股东的股权，境内公司变更设立为外商投资企业后，该外商投资企业的注册资本为原境内公司注册资本，外国投资者的出资比例为其所购买股权在原注册资本中所占比例。 外国投资者认购境内有限责任公司增资的，并购后所设外商投资企业的注册资本为原境内公司注册资本与增资额之和。外国投资者与被并购境内公司原其他股东，在境内公司资产评估的基础上，确定各自在外商投资企业注册资本中的出资比例。 外国投资者认购境内股份有限公司增资的，按照《公司法》有关规定确定注册资本。"},{"i":19,"n":"第十九条","txt":"外国投资者股权并购的，除国家另有规定外，对并购后所设外商投资企业应按照以下比例确定投资总额的上限： （一） 注册资本在210万美元以下的，投资总额不得超过注册资本的10/7； （二） 注册资本在210万美元以上至500万美元的，投资总额不得超过注册资本的2倍； （三） 注册资本在500万美元以上至1200万美元的，投资总额不得超过注册资本的2.5倍； （四） 注册资本在1200万美元以上的，投资总额不得超过注册资本的3倍。"},{"i":20,"n":"第二十条","txt":"外国投资者资产并购的，应根据购买资产的交易价格和实际生产经营规模确定拟设立的外商投资企业的投资总额。拟设立的外商投资企业的注册资本与投资总额的比例应符合有关规定。"},{"i":21,"n":"第二十一条","txt":"外国投资者股权并购的，投资者应根据并购后所设外商投资企业的投资总额、企业类型及所从事的行业，依照设立外商投资企业的法律、行政法规和规章的规定，向具有相应审批权限的审批机关报送下列文件： （一） 被并购境内有限责任公司股东一致同意外国投资者股权并购的决议，或被并购境内股份有限公司同意外国投资者股权并购的股东大会决议； （二） 被并购境内公司依法变更设立为外商投资企业的申请书； （三） 并购后所设外商投资企业的合同、章程； （四） 外国投资者购买境内公司股东股权或认购境内公司增资的协议； （五） 被并购境内公司上一财务年度的财务审计报告； （六） 经公证和依法认证的投资者的身份证明文件或注册登记证明及资信证明文件； （七） 被并购境内公司所投资企业的情况说明； （八） 被并购境内公司及其所投资企业的营业执照（副本）； （九） 被并购境内公司职工安置计划； （十） 本规定第十三条、第十四条、"},{"i":22,"n":"第二十二条","txt":"股权购买协议、境内公司增资协议应适用中国法律，并包括以下主要内容： （一） 协议各方的状况，包括名称（姓名），住所，法定代表人姓名、职务、国籍等； （二） 购买股权或认购增资的份额和价款； （三） 协议的履行期限、履行方式； （四） 协议各方的权利、义务； （五） 违约责任、争议解决； （六） 协议签署的时间、地点。"},{"i":23,"n":"第二十三条","txt":"外国投资者资产并购的，投资者应根据拟设立的外商投资企业的投资总额、企业类型及所从事的行业，依照设立外商投资企业的法律、行政法规和规章的规定，向具有相应审批权限的审批机关报送下列文件： （一） 境内企业产权持有人或权力机构同意出售资产的决议； （二） 外商投资企业设立申请书； （三） 拟设立的外商投资企业的合同、章程； （四） 拟设立的外商投资企业与境内企业签署的资产购买协议，或外国投资者与境内企业签署的资产购买协议； （五） 被并购境内企业的章程、营业执照（副本）； （六） 被并购境内企业通知、公告债权人的证明以及债权人是否提出异议的说明； （七） 经公证和依法认证的投资者的身份证明文件或开业证明、有关资信证明文件； （八） 被并购境内企业职工安置计划； （九） 本规定第十三条、第十四条、第十五条要求报送的文件。 依照前款的规定购买并运营境内企业的资产，涉及其他相关政府部门许可的，有关"},{"i":24,"n":"第二十四条","txt":"资产购买协议应适用中国法律，并包括以下主要内容： （一） 协议各方的状况，包括名称（姓名），住所，法定代表人姓名、职务、国籍等； （二） 拟购买资产的清单、价格； （三） 协议的履行期限、履行方式； （四） 协议各方的权利、义务； （五） 违约责任、争议解决； （六） 协议签署的时间、地点。"},{"i":25,"n":"第二十五条","txt":"外国投资者并购境内企业设立外商投资企业，除本规定另有规定外，审批机关应自收到规定报送的全部文件之日起30日内，依法决定批准或不批准。决定批准的，由审批机关颁发批准证书。 外国投资者协议购买境内公司股东股权，审批机关决定批准的，应同时将有关批准文件分别抄送股权转让方、境内公司所在地外汇管理机关。股权转让方所在地外汇管理机关为其办理转股收汇外资外汇登记并出具相关证明，转股收汇外资外汇登记证明是证明外方已缴付的股权收购对价已到位的有效文件。"},{"i":26,"n":"第二十六条","txt":"外国投资者资产并购的，投资者应自收到批准证书之日起30日内，向登记管理机关申请办理设立登记，领取外商投资企业营业执照。 外国投资者股权并购的，被并购境内公司应依照本规定向原登记管理机关申请变更登记，领取外商投资企业营业执照。原登记管理机关没有登记管辖权的，应自收到申请文件之日起10日内转送有管辖权的登记管理机关办理，同时附送该境内公司的登记档案。被并购境内公司在申请变更登记时，应提交以下文件，并对其真实性和有效性负责： （一）变更登记申请书； （二）外国投资者购买境内公司股东股权或认购境内公司增资的协议； （三）修改后的公司章程或原章程的修正案和依法需要提交的外商投资企业合同； （四）外商投资企业批准证书； （五）外国投资者的主体资格证明或者自然人身份证明； （六）修改后的董事会名单，记载新增董事姓名、住所的文件和新增董事的任职文件； （七）国家工商行政管理总局规定的其他有关文件和证件"},{"i":27,"n":"第二十七条","txt":"本章所称外国投资者以股权作为支付手段并购境内公司，系指境外公司的股东以其持有的境外公司股权，或者境外公司以其增发的股份，作为支付手段，购买境内公司股东的股权或者境内公司增发股份的行为。"},{"i":28,"n":"第二十八条","txt":"本章所称的境外公司应合法设立并且其注册地具有完善的公司法律制度，且公司及其管理层最近3年未受到监管机构的处罚；除本章第三节所规定的特殊目的公司外，境外公司应为上市公司，其上市所在地应具有完善的证券交易制度。"},{"i":29,"n":"第二十九条","txt":"外国投资者以股权并购境内公司所涉及的境内外公司的股权，应符合以下条件： （一） 股东合法持有并依法可以转让； （二） 无所有权争议且没有设定质押及任何其他权利限制； （三） 境外公司的股权应在境外公开合法证券交易市场（柜台交易市场除外）挂牌交易； （四） 境外公司的股权最近1年交易价格稳定。 前款第（三）、（四）项不适用于本章第三节所规定的特殊目的公司。"},{"i":30,"n":"第三十条","txt":"外国投资者以股权并购境内公司，境内公司或其股东应当聘请在中国注册登记的中介机构担任顾问（以下称“并购顾问”）。并购顾问应就并购申请文件的真实性、境外公司的财务状况以及并购是否符合本规定第十四条、第二十八条和第二十九条的要求作尽职调查，并出具并购顾问报告，就前述内容逐项发表明确的专业意见。"},{"i":31,"n":"第三十一条","txt":"并购顾问应符合以下条件： （一） 信誉良好且有相关从业经验； （二） 无重大违法违规记录； （三） 应有调查并分析境外公司注册地和上市所在地法律制度与境外公司财务状况的能力。"},{"i":32,"n":"第三十二条","txt":"外国投资者以股权并购境内公司应报送商务部审批，境内公司除报送本规定第三章所要求的文件外，另须报送以下文件： （一） 境内公司最近1年股权变动和重大资产变动情况的说明； （二） 并购顾问报告； （三） 所涉及的境内外公司及其股东的开业证明或身份证明文件； （四） 境外公司的股东持股情况说明和持有境外公司5％以上股权的股东名录； （五） 境外公司的章程和对外担保的情况说明； （六） 境外公司最近年度经审计的财务报告和最近半年的股票交易情况报告。"},{"i":33,"n":"第三十三条","txt":"商务部自收到规定报送的全部文件之日起30日内对并购申请进行审核，符合条件的，颁发批准证书，并在批准证书上加注“外国投资者以股权并购境内公司，自营业执照颁发之日起6个月内有效”。"},{"i":34,"n":"第三十四条","txt":"境内公司应自收到加注的批准证书之日起30日内，向登记管理机关、外汇管理机关办理变更登记，由登记管理机关、外汇管理机关分别向其颁发加注“自颁发之日起8个月内有效”字样的外商投资企业营业执照和外汇登记证。 境内公司向登记管理机关办理变更登记时，应当预先提交旨在恢复股权结构的境内公司法定代表人签署的股权变更申请书、公司章程修正案、股权转让协议等文件。"},{"i":35,"n":"第三十五条","txt":"自营业执照颁发之日起6个月内，境内公司或其股东应就其持有境外公司股权事项，向商务部、外汇管理机关申请办理境外投资开办企业核准、登记手续。 当事人除向商务部报送《关于境外投资开办企业核准事项的规定》所要求的文件外，另须报送加注的外商投资企业批准证书和加注的外商投资企业营业执照。商务部在核准境内公司或其股东持有境外公司的股权后，颁发中国企业境外投资批准证书，并换发无加注的外商投资企业批准证书。 境内公司取得无加注的外商投资企业批准证书后，应在30日内向登记管理机关、外汇管理机关申请换发无加注的外商投资企业营业执照、外汇登记证。"},{"i":36,"n":"第三十六条","txt":"自营业执照颁发之日起6个月内，如果境内外公司没有完成其股权变更手续，则加注的批准证书和中国企业境外投资批准证书自动失效。登记管理机关根据境内公司预先提交的股权变更登记申请文件核准变更登记，使境内公司股权结构恢复到股权并购之前的状态。 并购境内公司增发股份而未实现的，在登记管理机关根据前款予以核准变更登记之前，境内公司还应当按照《公司法》的规定，减少相应的注册资本并在报纸上公告。 境内公司未按照前款规定办理相应的登记手续的，由登记管理机关按照《公司登记管理条例》的有关规定处理。"},{"i":37,"n":"第三十七条","txt":"境内公司取得无加注的外商投资企业批准证书、外汇登记证之前，不得向股东分配利润或向有关联关系的公司提供担保，不得对外支付转股、减资、清算等资本项目款项。"},{"i":38,"n":"第三十八条","txt":"境内公司或其股东凭商务部和登记管理机关颁发的无加注批准证书和营业执照，到税务机关办理税务变更登记。"},{"i":39,"n":"第三十九条","txt":"特殊目的公司系指中国境内公司或自然人为实现以其实际拥有的境内公司权益在境外上市而直接或间接控制的境外公司。 特殊目的公司为实现在境外上市，其股东以其所持公司股权，或者特殊目的公司以其增发的股份，作为支付手段，购买境内公司股东的股权或者境内公司增发的股份的，适用本节规定。 当事人以持有特殊目的公司权益的境外公司作为境外上市主体的，该境外公司应符合本节对于特殊目的公司的相关要求。"},{"i":40,"n":"第四十条","txt":"特殊目的公司境外上市交易，应经国务院证券监督管理机构批准。 特殊目的公司境外上市所在国家或者地区应有完善的法律和监管制度，其证券监管机构已与国务院证券监督管理机构签订监管合作谅解备忘录，并保持着有效的监管合作关系。"},{"i":41,"n":"第四十一条","txt":"本节所述的权益在境外上市的境内公司应符合下列条件： （一）产权明晰，不存在产权争议或潜在产权争议； （二）有完整的业务体系和良好的持续经营能力； （三）有健全的公司治理结构和内部管理制度； （四）公司及其主要股东近3年无重大违法违规记录。"},{"i":42,"n":"第四十二条","txt":"境内公司在境外设立特殊目的公司，应向商务部申请办理核准手续。办理核准手续时，境内公司除向商务部报送《关于境外投资开办企业核准事项的规定》要求的文件外，另须报送以下文件： （一）特殊目的公司实际控制人的身份证明文件； （二）特殊目的公司境外上市商业计划书； （三）并购顾问就特殊目的公司未来境外上市的股票发行价格所作的评估报告。 获得中国企业境外投资批准证书后，设立人或控制人应向所在地外汇管理机关申请办理相应的境外投资外汇登记手续。"},{"i":43,"n":"第四十三条","txt":"特殊目的公司境外上市的股票发行价总值，不得低于其所对应的经中国有关资产评估机构评估的被并购境内公司股权的价值。"},{"i":44,"n":"第四十四条","txt":"特殊目的公司以股权并购境内公司的，境内公司除向商务部报送本规定第三十二条所要求的文件外，另须报送以下文件： （一）设立特殊目的公司时的境外投资开办企业批准文件和证书； （二）特殊目的公司境外投资外汇登记表； （三）特殊目的公司实际控制人的身份证明文件或开业证明、章程； （四）特殊目的公司境外上市商业计划书； （五）并购顾问就特殊目的公司未来境外上市的股票发行价格所作的评估报告。 如果以持有特殊目的公司权益的境外公司作为境外上市主体，境内公司还须报送以下文件： （一）该境外公司的开业证明和章程； （二）特殊目的公司与该境外公司之间就被并购的境内公司股权所作的交易安排和折价方法的详细说明。"},{"i":45,"n":"第四十五条","txt":"商务部对本规定第四十四条所规定的文件初审同意的，出具原则批复函，境内公司凭该批复函向国务院证券监督管理机构报送申请上市的文件。国务院证券监督管理机构于20个工作日内决定是否核准。 境内公司获得核准后，向商务部申领批准证书。商务部向其颁发加注“境外特殊目的公司持股，自营业执照颁发之日起1年内有效”字样的批准证书。 并购导致特殊目的公司股权等事项变更的，持有特殊目的公司股权的境内公司或自然人，凭加注的外商投资企业批准证书，向商务部就特殊目的公司相关事项办理境外投资开办企业变更核准手续，并向所在地外汇管理机关申请办理境外投资外汇登记变更。"},{"i":46,"n":"第四十六条","txt":"境内公司应自收到加注的批准证书之日起30日内，向登记管理机关、外汇管理机关办理变更登记，由登记管理机关、外汇管理机关分别向其颁发加注“自颁发之日起14个月内有效”字样的外商投资企业营业执照和外汇登记证。 境内公司向登记管理机关办理变更登记时，应当预先提交旨在恢复股权结构的境内公司法定代表人签署的股权变更申请书、公司章程修正案、股权转让协议等文件。"},{"i":47,"n":"第四十七条","txt":"境内公司应自特殊目的公司或与特殊目的公司有关联关系的境外公司完成境外上市之日起30日内，向商务部报告境外上市情况和融资收入调回计划，并申请换发无加注的外商投资企业批准证书。同时，境内公司应自完成境外上市之日起30日内，向国务院证券监督管理机构报告境外上市情况并提供相关的备案文件。境内公司还应向外汇管理机关报送融资收入调回计划，由外汇管理机关监督实施。境内公司取得无加注的批准证书后，应在30日内向登记管理机关、外汇管理机关申请换发无加注的外商投资企业营业执照、外汇登记证。 如果境内公司在前述期限内未向商务部报告，境内公司加注的批准证书自动失效，境内公司股权结构恢复到股权并购之前的状态，并应按本规定第三十六条办理变更登记手续。"},{"i":48,"n":"第四十八条","txt":"特殊目的公司的境外上市融资收入，应按照报送外汇管理机关备案的调回计划，根据现行外汇管理规定调回境内使用。融资收入可采取以下方式调回境内： （一）向境内公司提供商业贷款； （二）在境内新设外商投资企业； （三）并购境内企业。 在上述情形下调回特殊目的公司境外融资收入，应遵守中国有关外商投资及外债管理的法律和行政法规。如果调回特殊目的公司境外融资收入，导致境内公司和自然人增持特殊目的公司权益或特殊目的公司净资产增加，当事人应如实披露并报批，在完成审批手续后办理相应的外资外汇登记和境外投资登记变更。 境内公司及自然人从特殊目的公司获得的利润、红利及资本变动所得外汇收入，应自获得之日起6个月内调回境内。利润或红利可以进入经常项目外汇帐户或者结汇。资本变动外汇收入经外汇管理机关核准，可以开立资本项目专用帐户保留，也可经外汇管理机关核准后结汇。"},{"i":49,"n":"第四十九条","txt":"自营业执照颁发之日起1年内，如果境内公司不能取得无加注批准证书，则加注的批准证书自动失效，并应按本规定第三十六条办理变更登记手续。"},{"i":50,"n":"第五十条","txt":"特殊目的公司完成境外上市且境内公司取得无加注的批准证书和营业执照后，当事人继续以该公司股份作为支付手段并购境内公司的，适用本章第一节和第二节的规定。"},{"i":51,"n":"第五十一条","txt":"依据《反垄断法》的规定，外国投资者并购境内企业达到《国务院关于经营者集中申报标准的规定》规定的申报标准的，应当事先向商务部申报，未申报不得实施交易。"},{"i":52,"n":"第五十二条","txt":"外国投资者在中国境内依法设立的投资性公司并购境内企业，适用本规定。 外国投资者购买境内外商投资企业股东的股权或认购境内外商投资企业增资的，适用现行外商投资企业法律、行政法规和外商投资企业投资者股权变更的相关规定，其中没有规定的，参照本规定办理。 外国投资者通过其在中国设立的外商投资企业合并或收购境内企业的，适用关于外商投资企业合并与分立的相关规定和关于外商投资企业境内投资的相关规定，其中没有规定的，参照本规定办理。 外国投资者并购境内有限责任公司并将其改制为股份有限公司的，或者境内公司为股份有限公司的，适用关于设立外商投资股份有限公司的相关规定，其中没有规定的，适用本规定。"},{"i":53,"n":"第五十三条","txt":"申请人或申报人报送文件，应依照本规定对文件进行分类，并附文件目录。规定报送的全部文件应用中文表述。"},{"i":54,"n":"第五十四条","txt":"被股权并购境内公司的中国自然人股东，经批准，可继续作为变更后所设外商投资企业的中方投资者。"},{"i":55,"n":"第五十五条","txt":"境内公司的自然人股东变更国籍的，不改变该公司的企业性质。"},{"i":56,"n":"第五十六条","txt":"相关政府机构工作人员必须忠于职守、依法履行职责，不得利用职务之便牟取不正当利益，并对知悉的商业秘密负有保密义务。"},{"i":57,"n":"第五十七条","txt":"香港特别行政区、澳门特别行政区和台湾地区的投资者并购境内其他地区的企业，参照本规定办理。"},{"i":58,"n":"第五十八条","txt":"本规定自公布之日起施行。"}],"shangwubuxingzhengchufashishibanfa":[{"i":1,"n":"第一条","txt":"为了规范商务部行政处罚的实施，保障行政处罚的合法性和有效性，保护公民、法人或者其他组织的合法权益，维护公共利益和经济秩序，根据《中华人民共和国行政处罚法》，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织违反行政管理秩序的行为，依据法律、行政法规、规章规定，应当由商务部给予行政处罚的，适用本办法。"},{"i":3,"n":"第三条","txt":"商务部实施行政处罚应当遵循公正、公开的原则，并保障公民、法人或者其他组织的陈述权、申辩权、要求举行听证权、申请行政复议或行政诉讼的权利。"},{"i":4,"n":"第四条","txt":"商务部实施行政处罚，应当以法律、行政法规、规章为依据，并依照《中华人民共和国行政处罚法》及本办法规定的程序实施。"},{"i":5,"n":"第五条","txt":"行政处罚由商务部在法定职权范围内实施。没有法律、行政法规或规章的规定，商务部不得委托其他组织实施行政处罚。 没有法律、行政法规授权，商务部所属机构不得以自己的名义实施行政处罚。"},{"i":6,"n":"第六条","txt":"商务部行政处罚案件的立案、调查、执行等由案件所涉及的业务部门作为承办机构负责。 符合立案标准的，应当及时立案，并向当事人发出立案通知书。立案后，承办机构应及时展开调查。"},{"i":7,"n":"第七条","txt":"违法行为在二年内未被发现的，不再给予行政处罚；涉及公民生命健康安全、金融安全且有危害后果的，上述期限延长至五年。法律另有规定的除外。 前款规定的期限，从违法行为发生之日起计算；违法行为有连续或者继续状态的，从行为终了之日起计算。"},{"i":8,"n":"第八条","txt":"承办机构应当全面、客观、公正开展调查，收集有关证据。 调查时，执法人员不得少于两人，并应向当事人或相关人员出示行政执法证件。"},{"i":9,"n":"第九条","txt":"执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，应当回避。 当事人认为执法人员与案件有直接利害关系或者有其他关系可能影响公正执法的，有权申请回避。 当事人提出回避申请的，承办机构应当依法审查，由商务部负责人决定。决定作出之前，不停止调查。"},{"i":10,"n":"第十条","txt":"承办机构应当依法以文字、音像等形式，对行政处罚的启动、调查取证、审核、决定、送达、执行等进行全过程记录，归档保存。"},{"i":11,"n":"第十一条","txt":"承办机构应当制作《案件调查报告》。报告应列明案件基本情况、立案调查过程、查明事实及证据、违法行为性质、拟作出决定的内容和方式、法律依据等。"},{"i":12,"n":"第十二条","txt":"调查终结，承办机构应提请商务部负责人对调查结果进行审查。商务部负责人根据不同情况，分别作出如下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关。 对情节复杂或者重大违法行为给予行政处罚，承办机构应当提请商务部负责人集体讨论决定。"},{"i":13,"n":"第十三条","txt":"有下列情形之一，在提请商务部负责人审查或集体讨论前，承办机构应将《案件调查报告》提交法制机构进行法制审核；未经法制审核或者审核未通过的，不得作出处罚决定： （一）重大违法行为、涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案情复杂、涉及多个法律关系的； （四）法律、法规规定应当进行法制审核的其他情形。 承办机构认为需要并提交法制审核的，法制机构应当进行法制审核。"},{"i":14,"n":"第十四条","txt":"法制审核采取书面形式进行，包括： （一）处罚事项是否属于商务部职能范围，执法人员是否具备执法资格； （二）处罚程序是否合法； （三）证据是否合法充分； （四）适用法律、行政法规、规章是否准确，裁量是否存在明显不当； （五）处罚文书是否完备、规范； （六）违法行为是否涉嫌犯罪、需要移送司法机关等。 法制审核结束后，法制机构应当提出同意或者存在问题的书面审核意见。"},{"i":15,"n":"第十五条","txt":"承办机构要对法制机构提出的存在问题的审核意见进行研究，研究后仍拟作出行政处罚的，应作出相应处理后再次报送法制审核。 法制审核通过后，承办机构应将法制审核意见、《案件调查报告》提请商务部负责人按第十二条规定审查处理。"},{"i":16,"n":"第十六条","txt":"承办机构应当按照商务部负责人或集体讨论的审查意见制作行政处罚告知书，书面告知当事人拟作出的行政处罚内容及事实、理由、依据，并告知当事人依法享有陈述、申辩的权利。"},{"i":17,"n":"第十七条","txt":"拟作出下列行政处罚决定的，承办机构应当在行政处罚告知书中告知当事人有要求举行听证的权利： （一）对自然人处以一万元以上、对法人或者其他组织处以十万元以上罚款； （二）对自然人、法人或者其他组织作出没收违法所得或非法财物价值总额达到第一项所列数额的行政处罚； （三）降低资质等级、吊销许可证件； （四）责令停产停业、责令关闭、限制从业； （五）法律、行政法规、规章规定的其他情形。"},{"i":18,"n":"第十八条","txt":"当事人有陈述、申辩意见的，承办机构应当充分听取当事人的意见，对当事人提出的事实、理由和证据，应当进行复核；当事人提出的事实、理由或者证据成立的，应当采纳；不得因当事人陈述、申辩而给予更重的处罚。 承办机构未依照本办法规定向当事人告知拟作出的行政处罚内容及事实、理由、依据，或者拒绝听取当事人的陈述、申辩的，不得作出行政处罚决定；当事人明确放弃陈述或者申辩权利的除外。"},{"i":19,"n":"第十九条","txt":"当事人要求举行听证的，应当自行政处罚告知书送达之日起五个工作日内向承办机构提出。当事人未在法定时间内要求听证的，视为放弃听证权利。 满足第十七条规定的情形且当事人要求举行听证的，由法制机构或商务部负责人指定的其他机构按照《中华人民共和国行政处罚法》的规定组织听证。案件调查人员不得担任听证主持人、听证员或记录员。 商务部负责组织听证的机构应当自当事人依法提出听证请求之日起三十日内完成听证，听证期限不计入办理行政处罚期限。"},{"i":20,"n":"第二十条","txt":"听证结束后，负责组织听证的机构应制作听证笔录，法制机构应对案件出具法制审核意见，承办机构应将听证笔录、法制审核意见和《案件调查报告》按第十二条规定提请商务部负责人或集体讨论审查处理。"},{"i":21,"n":"第二十一条","txt":"承办机构应当按照商务部负责人或集体讨论的审查决定，根据《中华人民共和国行政处罚法》第五十九条的规定制作行政处罚决定书。"},{"i":22,"n":"第二十二条","txt":"商务部应当自行政处罚案件立案之日起九十日内作出行政处罚决定。法律、行政法规、规章另有规定的，从其规定。 案情复杂，不能在规定期限内作出处罚决定的，经商务部负责人批准，可以延长三十日，并告知当事人。 案情特别复杂或者有其他特殊情形，经延期仍不能作出处罚决定的，应由商务部负责人集体讨论决定是否延期。决定延期的，应当同时确定延长的合理期限，并告知当事人。"},{"i":23,"n":"第二十三条","txt":"行政处罚告知书和行政处罚决定书作出后，由承办机构按照《中华人民共和国行政处罚法》第六十一条等规定送达当事人。"},{"i":24,"n":"第二十四条","txt":"满足《中华人民共和国行政处罚法》第五十一条规定的情形，承办机构拟当场作出罚款或警告行政处罚决定的，应按《中华人民共和国行政处罚法》简易程序的有关规定处理。法律另有规定的，从其规定。"},{"i":25,"n":"第二十五条","txt":"当事人应当在行政处罚决定书确定的期限内履行行政处罚决定。逾期不履行行政处罚决定的，商务部可采取《中华人民共和国行政处罚法》第七十二条规定的措施，予以执行。"},{"i":26,"n":"第二十六条","txt":"商务部在执行罚款、没收违法所得等行政处罚时，应当实行罚缴分离制度。罚款及没收违法所得应由当事人按《中华人民共和国行政处罚法》第六十七条的规定上缴国库。"},{"i":27,"n":"第二十七条","txt":"具有一定社会影响的行政处罚决定应当依法公开，由承办机构在商务部网站公布。 公开的行政处罚决定被依法变更、撤销、确认违法或者确认无效的，承办机构应当在三个工作日内撤回行政处罚决定信息并公开说明理由。"},{"i":28,"n":"第二十八条","txt":"本办法不适用于商务部对部机关各单位工作人员所做的行政处分及其他人事处理决定。"},{"i":29,"n":"第二十九条","txt":"本办法由商务部负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自公布之日起施行。《商务行政处罚程序规定》（商务部令2012年第6号）、《商务部行政处罚委员会工作制度》（商法字〔2019〕6号）同时废止。"}],"shangwubuxingzhengfuyishishibanfa":[{"i":1,"n":"第一条","txt":"为防止和纠正违法的或者不当的具体行政行为，保护公民、法人和其它组织的合法权益，保障和监督国内外贸易和国际经济合作管理机关依法行使职权，根据《中华人民共和国行政复议法》(以下简称《行政复议法》)，制定本办法。"},{"i":2,"n":"第二条","txt":"商务部依据《行政复议法》及本办法的规定履行行政复议职责。商务部法制工作机构(条约法律司)具体办理商务部的行政复议事项，并履行《行政复议法》第三条规定的职责。"},{"i":3,"n":"第三条","txt":"对下列具体行政行为不服的，可以向商务部申请行政复议： (一)商务部的具体行政行为； (二)商务部的派出机构依照法律、法规或者规章的规定，以自己的名义作出的具体行政行为； (三)法律、法规授权并由商务部直接管理的组织的具体行政行为； (四)对省、自治区、直辖市国内外贸易和国际经济合作管理机关的具体行政行为不服的，可以向商务部申请行政复议，也可以向该省、自治区、直辖市人民政府申请行政复议。"},{"i":4,"n":"第四条","txt":"当事人以书面方式申请行政复议的，应当提交行政复议申请书正本一份，并按照被申请人的数目提交副本。复议申请书应当载明下列内容： (一)申请人及委托代理人的姓名、职业、住址(法人或者其他组织的名称、地址、法定代表人的姓名)； (二)被申请人的名称、地址； (三)申请复议的具体要求； (四)主要事实和理由(包括知道具体行政行为的时间)； (五)提出行政复议申请的日期。 复议申请书应当由申请人或申请人的法定代表人(或其授权委托人)签字并盖章，并附有必要的证据。申请人为自然人的，应当提交居民身份证或其他有效证件的复印件；申请人为法人或其他组织的，应当提交营业执照或其他有效证件的复印件、法定代表人身份证明等。"},{"i":5,"n":"第五条","txt":"同申请行政复议的具体行政行为有利害关系的其他公民、法人或者其他组织要求作为第三人参加行政复议，应当以书面形式提出申请，经商务部审查同意，可以作为第三人参加行政复议。 商务部认为必要时，也可以通知同申请复议的具体行政行为有利害关系的其他公民、法人或者其他组织作为第三人参加行政复议。"},{"i":6,"n":"第六条","txt":"申请人向商务部申请复议的，向商务部法制工作机构办理申请手续。法制工作机构应当在申请书上注明收到日期，并由递交人签字确认；"},{"i":7,"n":"第七条","txt":"商务部法制工作机构收到行政复议申请后，应当在5个工作日内按照《行政复议法》的有关规定进行审查，并依法做出是否受理的决定。 除依法决定不予受理或告知申请人应当向其他复议机关申请复议的外，行政复议申请自商务部法制工作机构收到之日起即为受理。"},{"i":8,"n":"第八条","txt":"行政复议申请有下列情形之一的，不予受理，并以书面形式告知申请人： (一)申请复议的事项不属于《行政复议法》第六条规定的范围的； (二)申请人不具备复议申请主体资格的； (三)申请人错列被申请人且拒绝变更的； (四)申请复议超过了法定的申请期限且无正当理由的； (五)申请人提起行政诉讼，法院已经受理或尚未决定是否受理，又申请行政复议的； (六)申请人向其它有管辖权的行政机关申请复议，该复议机关已经依法受理的； (七)申请人撤回复议申请，无正当理由再行申请复议的； (八)申请人超越复议管辖权限、越级申请的(《行政复议》>第二十条规定的情形除外)； (九)行政复议申请不具备其他法定要件的。"},{"i":9,"n":"第九条","txt":"商务部法制工作机构应当自行政复议申请受理之日起7个工作日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到申请书副本或者申请笔录复印件之日起10日内提出书面答复，并提交当初作出具体行政行为的证据、依据和其他有关材料。 被申请人的书面答复应当载明以下内容： (一)被申请人的基本情况(被申请人为商务部的除外)； (二)进行答辩的事由，案件的基本过程和情况； (三)做出具体行政行为的事实依据和有关证据材料； (四)做出具体行政行为所依据的法律、法规、规章和规范性文件的具体条款和内容； (五)做出答复的时间。 书面答复应当加盖被申请人单位公章；被申请人为商务部的，加盖作出该具体行政行为的部门的印章。"},{"i":10,"n":"第十条","txt":"被申请人不按照《行政复议法》第二十三条和本办法第十条的规定提出书面答复、提交当初作出具体行政行为的证据、依据和其他有关材料的，视为该具体行政行为没有证据、依据，决定撤消该具体行政行为。"},{"i":11,"n":"第十一条","txt":"行政复议原则上采取书面审查的方式，如案情复杂、书面审查无法查明案情的，也可以采取听取当事人的意见、实地调查，邀请专门机构进行检验、鉴定等方式。"},{"i":12,"n":"第十二条","txt":"在行政复议过程中，被申请人及其代理人均不得自行向申请人或其他有关组织或者个人收集证据，也不得以做出具体行政行为之后发现的事实或情况作为具体行政行为的事实依据。"},{"i":13,"n":"第十三条","txt":"法制工作机构应当对被申请人做出的具体行政行为进行审查，提出意见，经商务部负责人同意或集体讨论通过后，按照《行政复议法》第二十八条的规定作出行政复议决定。"},{"i":14,"n":"第十四条","txt":"申请人在申请行政复议时一并提出行政赔偿请求的，应当按照《中华人民共和国国家赂偿法》第十二条的规定写明具体的赔偿要求、事实根据和理由。行政复议机关对符合国家赔偿法的有关规定应当给予赔偿的，在决定撤消、变更具体行政行为或者确认具体行政行为违法时，应当同时决定被申请人依法给予赔偿。"},{"i":15,"n":"第十五条","txt":"本办法由商务部负责解释，自2004年7月1日起施行。"}],"shangwubuguifanxingwenjianzhidingheguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范商务部规范性文件的制定和管理工作，促进依法行政，保护公民、法人或者其他组织的合法权益，根据《法治政府建设实施纲要（2015—2020年）》等规定，结合商务部实际情况，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称规范性文件，是指部门规章以外的，商务部依照法定职权和程序单独或者牵头会同有关部门制定的，涉及公民、法人或者其他组织的权利义务，具有普遍约束力并且在一定期限内反复适用的文件。规范性文件不包括规范内部事务、通报具体情况、处理具体事项以及单纯转发的文件，如内部执行的管理规范、工作制度、会议纪要、请示报告及表彰奖惩、人事任免文件等。"},{"i":3,"n":"第三条","txt":"商务部规范性文件的起草、审查、批准、公布、解释和清理等，适用本办法。"},{"i":4,"n":"第四条","txt":"制定规范性文件应当坚持合法、公开、精简、效能和权责统一原则。"},{"i":5,"n":"第五条","txt":"规范性文件应当符合法律、行政法规、部门规章的规定，不得设定行政许可、行政处罚、行政强制等事项，无法律法规依据，不得减损公民、法人或者其他组织合法权益或者增加其义务。"},{"i":6,"n":"第六条","txt":"部内业务部门及相关单位负责职责范围内的规范性文件的起草、修改和清理等工作；办公厅负责规范性文件的审核、制发（含编号、登记）工作；法制机构负责规范性文件的合法性审查、组织清理工作。"},{"i":7,"n":"第七条","txt":"法律、行政法规、部门规章或者国务院文件中已有明确、具体规定的，不得重复制定规范性文件。"},{"i":8,"n":"第八条","txt":"规范性文件应当按照法定要求和程序予以公布，未经公布不得作为行政管理依据。"},{"i":9,"n":"第九条","txt":"规范性文件自公布之日起三十日后施行，但涉及国家安全的及公布后不立即施行将有碍规范性文件实施的，可以自公布之日起施行。"},{"i":10,"n":"第十条","txt":"规范性文件由部内业务部门及相关单位负责起草。草案定稿应经过起草单位司（局）务会审议通过。 起草规范性文件草案时应当同时起草草案说明，并明确文件类型为“规范性文件”，在公文办理系统中进行标注。"},{"i":11,"n":"第十一条","txt":"规范性文件的名称应当根据具体内容确定，一般使用“办法”、“规定”、“通知”、“决定”、“意见”、“公告”等名称，但不得使用“法”、“条例”。规范性文件的内容应当明确具体、逻辑严密、具有可操作性；一般以条文的形式制定，序号用中文数字依次表述。文字应当准确、规范、简洁。"},{"i":12,"n":"第十二条","txt":"规范性文件草案应当根据内容需要明确制定目的和依据、适用范围、执行部门和施行日期等内容。 草案还应当明确列明因该文件施行而失效或者废止的文件的名称、文号；仅涉及部分条款失效或者废止的，应当列明相关条款。"},{"i":13,"n":"第十三条","txt":"草案说明应当包括下列内容： （一）制定该文件的背景、宗旨和必要性； （二）所依据的法律、行政法规、部门规章或国务院的决定、命令等有关文件； （三）拟解决的主要问题，拟采取的主要措施及其合理性、可行性； （四）征求意见及对意见的采纳情况； （五）该文件与此前发布的相关规范性文件的合并、衔接、替代、废止等关系； （六）该文件的内容涉及部内其他专项审查的，应说明相关审查情况，如：公平竞争审查、贸易政策合规评估、政策效果和舆情评估等； （七）其他需要说明的问题。"},{"i":14,"n":"第十四条","txt":"规范性文件一般应规定有效期，有效期自发布之日起，原则上不得超过5年。对于需要稳定市场预期并长期执行的规范性文件，或者是对于上位法的执行性规范，可以不规定有效期，但应当在起草说明中作出专门说明或以规章形式发布。 规定有效期的规范性文件，有效期届满，规范性文件自动失效。确有必要继续适用的，应当重新制定发布，或者距有效期届满3个月前，由商务部确定新的有效期后继续适用，并向社会公告。确定新的有效期的程序，参照本办法第二至五章相关规定。"},{"i":15,"n":"第十五条","txt":"起草单位应当深入开展调查研究，根据实际需要征求部内相关部门、地方商务主管部门、市场主体和有关专家的意见。 起草涉及重大事项或关系公民、法人或者其他组织切身利益的规范性文件，起草单位应当通过商务部网站公开征求社会公众意见，征求意见时间一般不少于30日。 涉及地方人民政府及其有关部门职责或者需要其贯彻落实的，还应当征求各省级人民政府或其有关部门意见。 征求意见可以采取书面、网上公开或者召开座谈会、论证会、听证会等形式。 起草单位应当根据征求意见的情况，对规范性文件征求意见稿进行修改，形成规范性文件草案，并在草案说明中对征求意见及采纳情况进行说明。"},{"i":16,"n":"第十六条","txt":"规范性文件起草工作完成后，在报请部领导批准或者部务会议审议前，起草单位应当将规范性文件草案、草案说明和法律、行政法规、规章等依据材料以及其他必要材料提交法制机构进行合法性审查。 不得以征求意见等方式代替合法性审查。未经合法性审查的，不得提交批准或者审议。办公厅在文件审核过程中，发现已标注为“规范性文件”的文件草案未经合法性审查，应退回并责令起草单位履行合法性审查程序。"},{"i":17,"n":"第十七条","txt":"合法性审查的内容包括： （一）是否违反法律、行政法规、部门规章或国务院文件； （二）是否违反我国加入的国际条约； （三）是否超越法定职权； （四）是否创设行政许可、行政处罚、行政强制等事项； （五）是否无法律法规依据作出减损公民、法人和其他组织合法权益或者增加其义务的规定； （六）是否符合本办法规定的制定程序； （七）是否对征求意见进行了说明； （八）是否涉及第十三条第（六）项规定的审查事项； （九）其他需要审查的事项。"},{"i":18,"n":"第十八条","txt":"法制机构应当自收到规范性文件的全部送审材料之日起10个工作日内完成合法性审查工作；情况复杂或者需进一步调查研究或者征求意见的，经法制机构负责人批准，可延长10个工作日。为预防、应对和处置自然灾害、灾难事故、公共卫生和社会安全等突发事件或者执行上级行政机关的紧急命令和决定，需要立即制定和实施的规范性文件，应当缩短审查时限。"},{"i":19,"n":"第十九条","txt":"规范性文件草案符合本办法相关规定的，法制机构应当作出合法性审查予以通过的意见。 规范性文件草案不符合本办法要求的，法制机构应当根据不同情形作出书面审查意见：对与上位法抵触的，提出不符合法律、行政法规、部门规章或国务院文件等规定的审查意见；超越制定机关权限的，提出无权制定文件的审查意见；对部分内容违反上位法规定的，部分内容无法律法规依据对公民、法人和其他组织变相减损权利或者增加义务事项的，提出修改的审查意见；对不符合本办法程序的，未说明征求意见情况的，提出履行相应程序或者补充相关材料的审查意见。"},{"i":20,"n":"第二十条","txt":"法制机构进行合法性审查，可以根据实际情况，采用书面征求意见、座谈会、论证会等多种方式，可以组织有关专家协助审查，并发挥政府法律顾问、公职律师等的作用。 对专业技术性强或者疑难、复杂的规范性文件草案，可以组织进行专门论证，专门论证时间一般不超过10个工作日，此期间不计算在第十八条规定的时限内。"},{"i":21,"n":"第二十一条","txt":"合法性审查意见是制定机关决策的重要依据，起草单位对合法性审查意见应认真研究，并根据审查意见对规范性文件草案进行相应修改。规范性文件草案经起草机构修改后，应当根据本规定要求重新进行合法性审查。不采纳合法性审查意见的，应当在报请部领导批准或者部务会议审议时说明理由。对无正当理由拒不采纳合法性审查意见的，予以通报；造成严重后果的，按照有关规定追究有关人员的责任。"},{"i":22,"n":"第二十二条","txt":"办公厅会同法制机构、信息工作机构共同推进落实规范性文件合法性审查信息化平台。对所审查的规范性文件实行目录和文本动态化、精细化管理。"},{"i":23,"n":"第二十三条","txt":"规范性文件草案应当由至少三名部领导签批，涉及重大事项或关系公民、法人或者其他组织切身利益的，应当经部务会议审议通过。制定重大经济社会方面的规范性文件，应当按照有关规定及时报告部党组。 规范性文件草案由起草单位提交批准或者提请审议，提请时应当附具草案说明和合法性审查意见书。部务会议对规范性文件草案进行审议时，由起草单位就起草情况作说明，法制机构就合法性审查情况作说明。 规范性文件经批准或者审议通过后，由起草单位按照审议意见修改完善，并按照《商务部公文处理办法》行文办理。"},{"i":24,"n":"第二十四条","txt":"规范性文件应当以商务部名义发布。办公厅应当对规范性文件统一登记、统一编号、统一印发。规范性文件文号中增加“规”字。不符合上述规定，不认定为规范性文件，不得作为管理行政相对人的依据。 起草单位应当在规范性文件发布后，7日内在部政府网站上全文公开。根据工作需要，起草说明可以和文件同时上网公开，若起草说明中涉及国家秘 密或者商业秘 密的，应当删除相关部分后予以公开。"},{"i":25,"n":"第二十五条","txt":"规范性文件发布后，起草单位应当同时将全文报送信息工作机构。信息工作机构会同办公厅设立公开的规范性文件备案数据库，在规范性文件合法性审查信息平台基础上，将所有规范性文件纳入数据库进行统一管理，载明文件名称、文号、发文时间、有效期等。数据库实行动态化、信息化管理，新制定、修改或者废止规范性文件后，数据库的相应数据应及时更新。"},{"i":26,"n":"第二十六条","txt":"商务部定期组织对本部门的规范性文件进行清理。 起草单位应当对其负责起草的所有规范性文件提出明确修改或清理意见。规范性文件的起草涉及多个司（局）的，由牵头起草单位商相关司（局）后提出修改或清理意见。对本办法出台前的规范性文件，各司（局）在定期清理时应逐步进行修改以符合本办法的规定。 清理工作完成后，由法制机构拟定现行有效的规范性文件目录，按照规范性文件批准发布程序及时向社会公布。规范性文件修改和废止程序参照本办法第二章至第五章的规定。"},{"i":27,"n":"第二十七条","txt":"规范性文件有下列情形之一的，应予修改： （一）个别条款与现行法律、行政法规、部门规章和国家政策不一致，但基本适应经济社会发展需要、有必要继续实施； （二）规范性文件之间对同一事项规定不一致； （三）作为主要依据的法律、行政法规、部门规章和国务院文件已经修改； （四）个别条款不能适应经济社会发展需要。"},{"i":28,"n":"第二十八条","txt":"规范性文件有下列情形之一的，应予废止： （一）主要内容与现行法律、行政法规、部门规章以及国家政策相抵触； （二）主要内容已经不能适应经济社会发展需要，调整对象已消失或者规定的事项、任务已完成； （三）主要内容已被新的法律、行政法规、部门规章或者规范性文件代替； （四）作为主要依据的法律、行政法规、部门规章和国务院文件已废止或者失效。"},{"i":29,"n":"第二十九条","txt":"本办法由商务部负责解释。规范性文件需要解释的，由规范性文件的起草部门提出解释意见，经法制机构合法性审查后，参照本办法第四章的规定公布。 公民、法人或者其他组织可以向制定机关提出对规范性文件的解释建议。规范性文件的解释与规范性文件具有同等效力。"},{"i":30,"n":"第三十条","txt":"公民、法人或者其他组织认为规范性文件违反法律法规，可以通过信函、传真等方式向部法制机构提出书面审查建议。书面审查建议应当载明建议人姓名或者单位名称、建议审查事项以及理由、联系方式、建议日期。"},{"i":31,"n":"第三十一条","txt":"本办法自2018年5月13日起施行。"}],"shangwulingyubiaozhunhuaguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强商务领域标准化工作，根据《中华人民共和国标准化法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称商务领域标准，包括商务领域国家标准和商务领域行业标准。"},{"i":3,"n":"第三条","txt":"商务部负责全国商务领域标准化管理工作，履行下列职责： （一）制定、编制全国商务领域标准化工作的制度和规划； （二）依法负责商务领域标准的制定、组织实施以及对商务领域标准的制定、实施进行监督； （三）指导地方商务领域标准化工作； （四）依法组建、管理商务领域专业标准化技术委员会（以下简称技术委员会）； （五）统筹商务领域国际标准化活动； （六）负责商务领域标准化工作的其他重大事项。 设区的市级以上地方人民政府商务主管部门在商务部指导下，履行下列职责： （一）贯彻执行商务领域标准化有关规定，制定本行政区域商务领域标准化工作计划并组织实施； （二）组织、指导商务领域标准在本行政区域内的实施和推广； （三）协助督促、检查本行政区域内单位承担的商务领域标准的起草工作； （四）承办商务部委托的其他商务领域标准化工作。"},{"i":4,"n":"第四条","txt":"技术委员会包括商务领域全国专业标准化技术委员会和商务领域行业标准化技术委员会（工作组），履行下列职责： （一）提出本专业领域的标准化工作政策和措施建议； （二）编制本专业领域标准体系； （三）提出制修订标准项目建议； （四）开展标准起草、技术审查、复审及标准外文版的翻译和审查等有关具体工作； （五）承担本专业领域行业标准有关具体技术内容的咨询答复工作。 商务领域全国专业标准化技术委员会的组建、换届、调整以及监督管理按照全国专业标准化技术委员会规定执行。 商务领域行业标准化技术委员会（工作组）的组建、换届、调整以及监督管理的具体规则由商务部另行制定。"},{"i":5,"n":"第五条","txt":"商务部推动参与商务领域国际标准化活动，开展标准化对外合作与交流，推动中国标准走出去，结合国情采用国际标准，推动商务领域标准与国外标准之间的认可、采用，组织开展商务领域标准外文版翻译工作。"},{"i":6,"n":"第六条","txt":"商务部对在商务领域标准化工作中作出显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":7,"n":"第七条","txt":"商务领域国家标准的制定按照国家标准规定执行。 商务领域行业标准的制定按照本办法执行。"},{"i":8,"n":"第八条","txt":"技术委员会、行业协会商会等组织和单位（以下简称申请单位）可以向商务部提出商务领域行业标准立项申请。 申请单位提出立项申请时，应当报送项目建议书和标准草案。项目建议书应当包括以下内容： （一）制定行业标准的必要性、可行性； （二）主要技术要求； （三）国内外有关标准情况； （四）采用国际标准情况； （五）其他应当予以说明的事项。"},{"i":9,"n":"第九条","txt":"商务部应当对立项申请进行评估。评估内容包括： （一）有关领域标准体系情况； （二）标准技术化水平、产业化情况和预期达到的效果； （三）与有关法律法规和标准的协调性； （四）有关国际、国外标准的比对分析情况； （五）其他需要评估的内容。"},{"i":10,"n":"第十条","txt":"商务部经评估决定予以立项的，下达项目计划。决定不予立项的，向申请单位说明理由。 必要时，商务部可以直接下达项目计划。"},{"i":11,"n":"第十一条","txt":"项目计划下达后，有关技术委员会应当组建起草组。没有技术委员会的，由申请单位明确起草单位，由起草单位组建起草组。 商务部直接下达项目计划的，由商务部指定技术委员会或者起草单位组建起草组。 起草组应当具有专业性和广泛代表性。"},{"i":12,"n":"第十二条","txt":"起草组负责编写标准征求意见稿和编制说明。标准征求意见稿和编制说明应当符合标准制修订编写技术文件的有关要求。编制说明应当包括以下内容： （一）工作简况，包括起草组成员及其所在单位、起草过程等； （二）与有关法律法规和标准的协调性； （三）编制原则和主要内容； （四）推广应用论证和预期达到的效果； （五）采用国际标准和国外先进标准情况； （六）重大分歧意见的处理经过和依据； （七）贯彻标准的要求和措施建议； （八）其他应当予以说明的事项。"},{"i":13,"n":"第十三条","txt":"标准征求意见稿和编制说明形成后，技术委员会或者起草单位应当以书面形式向有关主管部门、社会团体、企事业单位、科研院所、专家等征求意见，同时报请商务部在商务部网站向社会公开征求意见。"},{"i":14,"n":"第十四条","txt":"公开征求意见结束后，起草组应当根据征集意见对标准征求意见稿、编制说明进行完善，形成标准送审稿、编制说明、征求意见汇总处理表，报技术委员会初审。初审通过后，由技术委员会形成送审材料报商务部。没有技术委员会的，由起草单位报商务部相关司局初审。初审通过后，由起草单位形成送审材料报商务部。送审材料包括： （一）标准送审稿； （二）编制说明； （三）征求意见汇总处理表； （四）初审意见表。"},{"i":15,"n":"第十五条","txt":"商务部对送审材料进行审核。审核内容包括： （一）标准制定程序、送审材料是否规范； （二）是否符合有关法律法规的规定； （三）标准之间的协调性； （四）重大分歧意见处理情况； （五）其他需要审核的内容。"},{"i":16,"n":"第十六条","txt":"审核通过后，技术委员会成立专家组对标准送审稿进行技术审查。没有技术委员会的，由商务部成立专家组进行技术审查。 专家组成员来自生产者、经营者、使用者、消费者、公共利益方等相关方。教育科研机构、有关行政主管部门、检测及认证机构、社会团体等可以作为公共利益方代表。专家组成员一般不少于九人。 起草组成员不得承担技术审查工作。"},{"i":17,"n":"第十七条","txt":"技术审查可以采用现场会议、视频会议或者函审等形式。涉及国计民生等可能产生重大影响的行业标准，应当采用会议形式审查。技术审查内容包括： （一）标准技术内容的必要性、经济性和可操作性； （二）关键技术指标的来源和依据； （三）其他需要技术审查的内容。"},{"i":18,"n":"第十八条","txt":"采用会议形式进行技术审查的，应当形成审查会会议纪要和审查会审查结论表。采用函审形式的，应当形成函审结论表。 技术审查结论应当经专家组全体成员三分之二以上同意。"},{"i":19,"n":"第十九条","txt":"技术审查通过后，技术委员会或者起草单位组织起草组根据技术审查结论完善相关材料，形成报批材料报商务部。报批材料包括： （一）标准报批稿； （二）编制说明； （三）专家组成员名单； （四）审查会会议纪要、审查会审查结论表或者函审结论表； （五）采用国际标准的原文和译文。"},{"i":20,"n":"第二十条","txt":"商务部对报批材料的完整性、规范性以及意见处理情况等进行审核。 涉及国计民生等可能产生重大影响的行业标准，商务部可以在标准发布前再次向社会公开征求意见或者征求相关方面意见。"},{"i":21,"n":"第二十一条","txt":"经商务部审核同意的商务领域行业标准由商务部编号，以公告形式发布。"},{"i":22,"n":"第二十二条","txt":"商务领域行业标准代号为“SB/T”（国内贸易行业标准）或“WM/T”（外经贸行业标准），商务领域行业标准编号由标准代号、发布顺序号和发布年份号组成。"},{"i":23,"n":"第二十三条","txt":"商务领域行业标准文本在商务部网站依法向社会公开。"},{"i":24,"n":"第二十四条","txt":"商务领域行业标准制定过程中，经商务部同意，标准名称、起草单位可以调整。"},{"i":25,"n":"第二十五条","txt":"商务领域行业标准从项目计划下达到报送报批稿的期限一般不超过十二个月。 在规定期限内无法报送的，技术委员会或者起草单位应当提前三十日向商务部说明情况，并申请延长期限。延长的期限不得超过六个月。"},{"i":26,"n":"第二十六条","txt":"技术委员会或者起草单位逾期未报送报批稿或者出现不宜继续制定商务领域行业标准情形的，商务部可以终止项目。"},{"i":27,"n":"第二十七条","txt":"商务部可以根据工作需要简化急需的商务领域行业标准制定程序。"},{"i":28,"n":"第二十八条","txt":"技术委员会或者起草单位无正当理由未按时完成或者未按规定完成商务领域行业标准制定工作的，由商务部责令限期改正；逾期不改正的，五年内不得承担商务领域标准化任务。"},{"i":29,"n":"第二十九条","txt":"商务领域国家标准的组织实施按照国家标准规定执行。 商务领域行业标准的组织实施按照本办法执行。"},{"i":30,"n":"第三十条","txt":"商务领域行业标准发布后，商务部组织地方商务主管部门、技术委员会、社会团体等开展标准宣传和推广工作。"},{"i":31,"n":"第三十一条","txt":"商务领域行业标准的解释由商务部负责。解释申请应当向商务部提出，由商务部依法受理并予以答复。解释申请存在下列情形的，商务部不予受理： （一）不属于商务领域行业标准规定的内容； （二）对有关对象是否符合某一项商务领域行业标准的判断； （三）尚未发布的商务领域行业标准。 属于商务领域行业标准实施过程中有关具体技术内容的咨询，由技术委员会或者起草单位答复。"},{"i":32,"n":"第三十二条","txt":"商务部建立商务领域行业标准制修订信息管理系统，接收社会各方对行业标准实施情况的意见建议。"},{"i":33,"n":"第三十三条","txt":"技术委员会或者起草单位应当采取多种形式收集商务领域行业标准实施情况，及时开展评估研究。"},{"i":34,"n":"第三十四条","txt":"技术委员会或者起草单位应当根据商务领域行业标准实施效果以及社会发展需要，对商务领域行业标准进行复审，向商务部提出继续有效、修订或者废止的复审结论。复审内容包括： （一）标准内容与现行法律法规和相关标准的协调性； （二）标准的实施应用范围； （三）标准实施产生的经济效益和社会效益； （四）标准实施过程中存在的问题和建议。 复审周期一般不超过五年。"},{"i":35,"n":"第三十五条","txt":"复审结论为修订的，按照本办法第二章程序执行。 复审结论为废止的，由商务部在商务部网站公开征求意见。无重大分歧意见或者经协调一致的，由商务部发布公告予以废止。"},{"i":36,"n":"第三十六条","txt":"商务领域行业标准发布后，个别技术要求需要修改、补充或者删减的，由技术委员会或者起草单位填写《行业标准修改通知单》，报商务部。商务部同意后以公告形式发布。"},{"i":37,"n":"第三十七条","txt":"商务领域标准化指导性技术文件的制定、组织实施以及对商务领域标准化指导性技术文件的制定、实施进行监督，参照本办法执行。"},{"i":38,"n":"第三十八条","txt":"本办法由商务部负责解释。"},{"i":39,"n":"第三十九条","txt":"本办法自2022年10月20日起施行。《商务领域标准化管理办法（试行）》（商务部令2012年第5号）同时废止。"}],"shangwulingyujingyingzheshiyongbaogaoyicixingsuliafa2a56":[{"i":1,"n":"第一条","txt":"为贯彻实施《中华人民共和国固体废物污染环境防治法》关于一次性塑料制品使用和报告的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于商务领域一次性塑料制品使用和报告的监督管理。 本办法所称商务领域是指根据国家法律和相关规定商务主管部门在一次性塑料制品使用和报告职责范围内的领域，包括商品零售、电子商务、餐饮、住宿、展览。 本办法所称一次性塑料制品是指商务领域经营者在其经营活动中向消费者提供的、由塑料制成的、不以重复使用为目的的制成品。"},{"i":3,"n":"第三条","txt":"国家推行绿色发展方式，倡导简约适度、绿色低碳的生活方式，鼓励减少使用一次性塑料制品，科学稳妥推广应用替代产品，引导公众积极参与塑料污染治理。"},{"i":4,"n":"第四条","txt":"国家依法禁止、限制使用不可降解塑料袋等一次性塑料制品，禁止、限制使用的具体范围、实施时间和地域要求，依据国家相关规定进行规范和调整（以下简称国家禁限使用规定），商务领域经营者应当遵守国家禁限使用规定，未列入国家禁限使用规定的可以使用。"},{"i":5,"n":"第五条","txt":"商务领域经营者中的商品零售场所开办单位、电子商务平台（含外卖平台）企业、外卖企业应当根据本办法向商务主管部门报告一次性塑料制品使用、回收情况。 本办法所称商品零售场所是指向消费者提供零售服务的各类超市、商场、集贸市场。商品零售场所开办单位是指为商品零售经营者提供经营场所，并与场所内商品零售经营者签订联营或租赁经营协议的企业法人。 本办法所称电子商务平台企业是指在电子商务中为交易双方或者多方提供网络经营场所、交易撮合、信息发布等服务，供交易双方或者多方独立开展交易活动的企业。 本办法所称外卖企业是指提供外卖服务的零售、餐饮企业。"},{"i":6,"n":"第六条","txt":"商务部负责全国商务领域执行国家禁限使用规定和一次性塑料制品报告活动的监督管理。 发展改革委等有关部门建立工作机制，统筹指导协调塑料污染治理工作。 县级以上地方商务主管部门依据职责对本行政区域内商务领域执行国家禁限使用规定和一次性塑料制品报告活动实施监督管理。县级以上地方商务主管部门涉及本办法有关商务执法职责发生调整的，有关商务执法职责由本级人民政府确定的承担相关职责的部门实施。 县级以上地方发展改革部门依据职责会同有关部门统筹指导协调本行政区域内塑料污染治理工作。"},{"i":7,"n":"第七条","txt":"一次性塑料制品相关行业协会应当制定行业规范，提供咨询、培训等服务，加强宣传引导和行业自律。"},{"i":8,"n":"第八条","txt":"商务领域经营者应当在其经营场所或网站的醒目位置张贴、摆放或设置国家禁限使用规定的标语，或者上述信息的链接标识，链接标识应当清晰、醒目。"},{"i":9,"n":"第九条","txt":"商品零售经营者应当依法执行《商品零售场所塑料购物袋有偿使用管理办法》。 鼓励商品零售经营者通过设置替代产品自助售卖装置，提供购物筐、购物车租赁服务等方式减少一次性塑料制品使用。"},{"i":10,"n":"第十条","txt":"电子商务经营者应当优先采用可重复使用、易回收利用的包装物，遵守国家包装管理有关规定。 鼓励电子商务经营者与商品生产企业合作，设计应用满足快递物流配送需求的商品包装，推广电商快件原装直发。 鼓励电子商务经营者与快递企业合作，推广应用可循环快递包装，减少一次性塑料制品使用。"},{"i":11,"n":"第十一条","txt":"电子商务平台（含外卖平台）企业应当制定鼓励平台内经营者减少快递包装和外卖环节一次性塑料制品使用的平台规则。 鼓励电子商务平台（含外卖平台）企业与快递企业、环卫单位、回收企业等开展合作，在写字楼、学校、大型社区等重点区域投放一次性塑料制品回收设施。 鼓励电子商务平台（含外卖平台）企业通过建立积分反馈、绿色信用等机制引导消费者使用替代产品，减少快递包装和外卖环节一次性塑料制品使用。"},{"i":12,"n":"第十二条","txt":"商品零售场所开办单位、电子商务平台（含外卖平台）企业应当督促其入驻经营者作出一次性塑料制品使用自律承诺，主动承诺知悉并遵守国家禁限使用规定。已经入驻的经营者应当于本办法实施之日起60日内作出自律承诺。"},{"i":13,"n":"第十三条","txt":"餐饮经营者应当根据内装物情况，合理选用替代产品或合规的一次性塑料制品提供打包或外卖服务。 鼓励餐饮经营者通过激励措施引导消费者使用替代产品，减少一次性塑料制品使用。"},{"i":14,"n":"第十四条","txt":"住宿经营者应当按照国家有关规定推行不主动提供一次性塑料制品。 鼓励住宿经营者通过激励措施引导消费者减少一次性塑料制品使用。"},{"i":15,"n":"第十五条","txt":"展馆经营者应当积极开展宣传引导，书面告知展览活动主办单位国家禁限使用规定。 展览活动主办单位应当告知参展单位等与展览活动相关的各单位国家禁限使用规定。 鼓励展览活动主办单位、参展单位使用替代产品，减少一次性塑料制品使用。"},{"i":16,"n":"第十六条","txt":"商品零售场所开办单位、电子商务平台（含外卖平台）企业、外卖企业应当通过商务部建立的全国一次性塑料制品使用、回收报告系统，向所在地县级商务主管部门报告一次性塑料制品使用、回收情况。报告每半年一次，上半年报告应于当年7月31日前完成，下半年报告应于次年的1月31日前完成。 一次性塑料制品报告范围根据国家相关规定动态调整。报告应当真实、完整，不得含有虚假内容，不得有重大遗漏。"},{"i":17,"n":"第十七条","txt":"商品零售场所开办单位报告其自营、联营及其场所内经营者塑料购物袋有偿使用情况、塑料废弃物回收情况和场所内经营者作出自律承诺的情况。 商品零售场所内存在不同企业法人的商品零售场所开办单位的，开办单位分别报告各自情况。 鼓励商品零售场所开办单位报告范围外的商品零售经营者报告塑料购物袋有偿使用情况和塑料废弃物回收情况。"},{"i":18,"n":"第十八条","txt":"电子商务平台企业报告其自营业务产生的快递塑料包装（含塑料包装袋、塑料胶带、一次性塑料编织袋等）的使用情况、塑料废弃物回收情况和平台内经营者作出自律承诺的情况。外卖平台企业报告其自营业务产生的塑料购物袋、一次性塑料餐具（刀、叉、勺）、一次性可降解塑料吸管的使用情况、塑料废弃物回收情况和平台内经营者作出自律承诺的情况。 电子商务平台企业、外卖平台企业参照前款报告客体，对平台内经营者一次性塑料制品使用、回收情况应当按照报告期开展总体评估，并向所在地县级商务主管部门报告。总体评估报告包括平台企业制定鼓励平台内经营者减少上述一次性塑料制品使用的平台规则、采取的相关治理措施、开展的宣传推广活动、平台内经营者取得的减量成效等。外卖平台企业除评估报告以上内容外，还应当报告其平台内经营者对上述一次性塑料制品有偿使用评估情况。 外卖平台企业以适当方式告知平台内外卖企业国家有关一次性塑料制品使用、回收报告的"},{"i":19,"n":"第十九条","txt":"外卖企业报告塑料购物袋、一次性塑料餐具（刀、叉、勺）、一次性可降解塑料吸管使用情况和塑料废弃物回收情况。外卖企业报告数据不区分店内即时消费与外卖业务。商品零售场所开办单位提供外卖服务的，按照本办法第十七条和本条规定合并报告。"},{"i":20,"n":"第二十条","txt":"各报告主体报告一次性塑料制品使用情况时可根据实际填报“使用量”“销售量”或“采购量”，报告口径须在报告过程中始终保持一致。 鼓励各报告主体主动报告替代产品使用、回收情况。"},{"i":21,"n":"第二十一条","txt":"县级以上地方商务主管部门采取“双随机、一公开”方式，对本行政区域内商务领域经营者执行国家禁限使用规定和使用、回收报告活动实施日常监督检查，重点检查以下方面： （一）一次性塑料制品使用的情况； （二）商务领域经营者张贴、摆放或设置国家禁限使用规定标语或链接标识的情况； （三）商品零售场所开办单位、电子商务平台（含外卖平台）企业对其入驻经营者作出自律承诺督促管理的情况； （四）电子商务平台（含外卖平台）企业平台规则制定情况； （五）展馆经营者告知义务履行的情况； （六）一次性塑料制品使用、回收报告的情况。"},{"i":22,"n":"第二十二条","txt":"县级以上地方商务主管部门可以依法采取以下措施实施监督检查： （一）进入一次性塑料制品使用等场所进行检查； （二）询问与监督检查事项有关的单位或个人，要求其说明情况； （三）查阅、复制有关文件、资料； （四）依据有关法律法规采取的其他措施。"},{"i":23,"n":"第二十三条","txt":"商务领域经营者涉嫌违法使用不可降解塑料袋等一次性塑料制品的，或者商品零售场所开办单位、电子商务平台（含外卖平台）企业、外卖企业涉嫌违法报告一次性塑料制品使用、回收情况的，县级以上地方商务主管部门可以对上述经营者进行约谈。"},{"i":24,"n":"第二十四条","txt":"县级以上地方商务主管部门应当加强本行政区域内一次性塑料制品报告质量审核和宣传引导工作，做好一次性塑料制品使用、回收报告分析工作。报告制度执行情况和分析情况应当于报告工作结束后30日内向上一级商务主管部门报告，并抄送同级发展改革部门。"},{"i":25,"n":"第二十五条","txt":"商务领域经营者未遵守国家禁限使用规定的，由县级以上地方商务主管部门责令限期改正，限期不改正的，处一万元以上十万元以下的罚款。"},{"i":26,"n":"第二十六条","txt":"违反本办法第十六条、第十七条、第十八条第一款和第二款、第十九条规定，商品零售场所开办单位、电子商务平台（含外卖平台）企业、外卖企业未按照本办法报告一次性塑料制品使用情况的，由县级以上地方商务主管部门责令限期改正，限期不改正的，处一万元以上十万元以下的罚款。"},{"i":27,"n":"第二十七条","txt":"省级商务主管部门会同同级发展改革部门，可以结合本地实际情况制定本办法的实施细则，并报商务部、发展改革委备案。"},{"i":28,"n":"第二十八条","txt":"县级以上地方人民政府可以根据本地区实际情况确定实施本办法监督管理职责的部门，本办法规定的县级以上地方商务主管部门职责由县级以上地方人民政府确定的监督管理部门承担。"},{"i":29,"n":"第二十九条","txt":"本办法由商务部会同发展改革委进行解释。"},{"i":30,"n":"第三十条","txt":"本办法自2023年6月20日起实施。《商务领域一次性塑料制品使用、回收报告办法（试行）》（商务部公告2020年第61号）同时废止。"}],"shangpinxianhuoshichangjiaoyitebieguiding":[{"i":1,"n":"第一条","txt":"为规范商品现货市场交易活动，维护市场秩序，防范市场风险，保护交易各方的合法权益，促进商品现货市场健康发展，加快推行现代流通方式，根据国家有关法律法规以及《国务院关于清理整顿各类交易场所切实防范金融风险的决定》（国发〔2011〕38号），制定本规定。"},{"i":2,"n":"第二条","txt":"中华人民共和国境内的商品现货市场交易活动，应当遵守本规定。国家另有规定的，依照其规定。"},{"i":3,"n":"第三条","txt":"本规定所称商品现货市场，是指依法设立的，由买卖双方进行公开的、经常性的或定期性的商品现货交易活动，具有信息、物流等配套服务功能的场所或互联网交易平台。 本规定所称商品现货市场经营者（以下简称市场经营者），是指依法设立商品现货市场，制定市场相关业务规则和规章制度，并为商品现货交易活动提供场所及相关配套服务的法人、其他经济组织和个人。"},{"i":4,"n":"第四条","txt":"从事商品现货市场交易活动，应当遵循公开、公平、公正和诚实信用的原则。"},{"i":5,"n":"第五条","txt":"商务部负责全国商品现货市场的规划、信息、统计等行业管理工作，促进商品现货市场健康发展。 中国人民银行依据职责负责商品现货市场交易涉及的金融监管以及非金融机构支付业务的监管工作。"},{"i":6,"n":"第六条","txt":"商品现货市场行业协会应当制定行业规范和行业标准，加强行业自律，组织业务培训，建立高管诚信档案，受理投诉和调解纠纷等。"},{"i":7,"n":"第七条","txt":"商品现货市场交易对象包括： （一）实物商品； （二）以实物商品为标的的仓单、可转让提单等提货凭证； （三）省级人民政府依法规定的其他交易对象。"},{"i":8,"n":"第八条","txt":"商品现货市场交易的实物商品，应当执行国家有关质量担保责任的法律法规，并符合现行有效的质量标准。"},{"i":9,"n":"第九条","txt":"商品现货市场交易可以采用下列方式： （一）协议交易； （二）单向竞价交易； （三）省级人民政府依法规定的其他交易方式。 本规定所称协议交易，是指买卖双方以实物商品交收为目的，采用协商等方式达成一致，约定立即交收或者在一定期限内交收的交易方式。 本规定所称单向竞价交易，是指一个买方（卖方）向市场提出申请，市场预先公告交易对象，多个卖方（买方）按照规定加价或者减价，在约定交易时间内达成一致并成交的交易方式。"},{"i":10,"n":"第十条","txt":"市场经营者不得开展法律法规以及《国务院关于清理整顿各类交易场所切实防范金融风险的决定》禁止的交易活动，不得以集中交易方式进行标准化合约交易。 现货合同的转让、变更，应当按照法律法规的相关规定办理。"},{"i":11,"n":"第十一条","txt":"市场经营者应当履行下列职责： （一）提供交易的场所、设施及相关服务； （二）按照本规定确定的交易方式和交易对象，建立健全交易、交收、结算、仓储、信息发布、风险控制、市场管理等业务规则与各项规章制度； （三）法律法规规定的其他职责。"},{"i":12,"n":"第十二条","txt":"市场经营者应当公开业务规则和规章制度。制定、修改和变更业务规则和规章制度，应当在合理时间内提前公示。"},{"i":13,"n":"第十三条","txt":"商品现货市场应当制定应急预案。出现异常情况时，应当及时采取有效措施，防止出现市场风险。"},{"i":14,"n":"第十四条","txt":"市场经营者应当采取合同约束、系统控制、强化内部管理等措施，加强资金管理力度。 市场经营者不得以任何形式侵占或挪用交易者的资金。"},{"i":15,"n":"第十五条","txt":"鼓励商品现货市场创新流通方式，降低交易成本；建设节能环保、绿色低碳市场。"},{"i":16,"n":"第十六条","txt":"鼓励商品现货市场采用现代信息化技术，建立互联网交易平台，开展电子商务。"},{"i":17,"n":"第十七条","txt":"市场经营者应当建立完善商品信息发布制度，公布交易商品的名称、数量、质量、规格、产地等相关信息，保证信息的真实、准确，不得发布虚假信息。"},{"i":18,"n":"第十八条","txt":"采用现代信息化技术开展交易活动的，市场经营者应当实时记录商品仓储、交易、交收、结算、支付等相关信息，采取措施保证相关信息的完整和安全，并保存五年以上。"},{"i":19,"n":"第十九条","txt":"市场经营者不得擅自篡改、销毁相关信息和资料。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府商务主管部门负责本行政区域内的商品现货市场的行业管理，并按照要求及时报送行业发展规划和其他具体措施。 中国人民银行分支机构依据职责负责辖区内商品现货市场交易涉及的金融机构和支付机构的监督管理工作。 国务院期货监督管理机构派出机构负责商品现货市场非法期货交易活动的认定等工作。"},{"i":21,"n":"第二十一条","txt":"市场经营者应当根据相关部门的要求报送有关经营信息与资料。"},{"i":22,"n":"第二十二条","txt":"县级以上人民政府商务主管部门应当根据本地实际情况，建立完善各项工作制度。必要时应及时将有关情况报告上级商务主管部门和本级人民政府。"},{"i":23,"n":"第二十三条","txt":"市场经营者违反第十一条、第十二条、第十三条、第十四条、第十七条、第十八条、第十九条、第二十一条规定，由县级以上商务主管部门会同有关部门责令改正。逾期不改的，处一万元以上三万元以下罚款。"},{"i":24,"n":"第二十四条","txt":"市场经营者违反第八条、第十条规定和《期货交易管理条例》的，依法予以处理。"},{"i":25,"n":"第二十五条","txt":"有关行政管理部门工作人员在市场监督管理工作中，玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"本规定自2014年1月1日起施行。"}],"shangpinlingshouchangsuosuliaogouwudaiyouchangshiyccf4a5-2":[{"i":1,"n":"第一条","txt":"为节约资源、保护生态环境，引导消费者减少使用塑料购物袋，制订本办法。"},{"i":2,"n":"第二条","txt":"本办法所称商品零售场所是指向消费者提供零售服务的各类超市、商场、集贸市场。 本办法所称塑料购物袋是指由商品零售场所提供的，用于装盛消费者所购商品，具有提携功能的塑料袋。但不包括商品零售场所基于卫生及食品安全目的，用于装盛散装生鲜食品、熟食、面食等商品的塑料预包装袋。 塑料购物袋的材质及技术要求由国家相关标准予以规范。"},{"i":3,"n":"第三条","txt":"商品零售场所应当依据本办法向消费者有偿提供塑料购物袋。"},{"i":4,"n":"第四条","txt":"商务主管部门、价格主管部门、工商行政管理部门依照有关法律法规，在各自职责范围内对商品零售场所塑料购物袋有偿使用过程中的经营行为进行监督管理。"},{"i":5,"n":"第五条","txt":"商品零售场所对塑料购物袋应当依法明码标价。"},{"i":6,"n":"第六条","txt":"商品零售场所可自主制定塑料购物袋价格，但不得有下列行为： （一）低于经营成本销售塑料购物袋； （二）不标明价格或不按规定的内容方式标明价格销售塑料购物袋； （三）采取打折或其他方式不按标示的价格向消费者销售塑料购物袋； （四）向消费者无偿或变相无偿提供塑料购物袋。"},{"i":7,"n":"第七条","txt":"商品零售场所应当在销售凭证上单独列示消费者购买塑料购物袋的数量、单价和款项。 　　以出租摊位形式经营的集贸市场对消费者开具销售凭证确有困难的除外。"},{"i":8,"n":"第八条","txt":"商品零售场所应向依法设立的塑料购物袋生产厂家、批发商或进口商采购塑料购物袋，并索取相关证照，建立塑料购物袋购销台账，以备查验。"},{"i":9,"n":"第九条","txt":"商品零售场所不得销售不符合国家相关标准的塑料购物袋。"},{"i":10,"n":"第十条","txt":"商品零售场所应采取措施，为消费者自带购物袋、购物篮购物提供便利。"},{"i":11,"n":"第十一条","txt":"鼓励商品零售场所提供符合相关质量标准和环保要求的塑料购物袋替代品。"},{"i":12,"n":"第十二条","txt":"以出租摊位形式经营的集贸市场，可以由开办单位或经其批准在市场内设立的专营（或兼营）塑料购物袋经营摊位实行塑料购物袋统一采购、销售。"},{"i":13,"n":"第十三条","txt":"商品零售场所的经营者对违反本办法有关规定的行为承担相应责任。 下列商品零售场所，由开办单位或出租单位对违反本办法有关规定的行为承担相应责任： （一）以出租摊位形式经营的集贸市场； （二）场内外租超市、柜台； （三）大型超市、商场引厂进店的经营摊位。"},{"i":14,"n":"第十四条","txt":"商品零售场所的经营者、开办单位或出租单位违反本办法第六条有关价格行为和明码标价规定的，由价格主管部门责令改正，并可视情节处以5000元以下罚款。"},{"i":15,"n":"第十五条","txt":"商品零售场所的经营者、开办单位或出租单位违反本办法第六条有关竞争行为和第七条规定的，由工商行政管理部门责令改正，并可视情节处以10000元以下罚款。"},{"i":16,"n":"第十六条","txt":"商品零售场所经营者、开办单位或出租单位违反本办法第八条规定的，由工商行政管理部门责令改正，并可视情节处以20000元以下罚款。"},{"i":17,"n":"第十七条","txt":"商品零售场所经营者、开办单位或出租单位违反本办法第九条规定的，由工商行政管理部门依据《中华人民共和国产品质量法》等法律法规予以处罚。"},{"i":18,"n":"第十八条","txt":"商品零售场所经营者、开办单位或出租单位因违反本办法相关规定受到处罚的，商务主管部门、价格主管部门和工商行政管理部门可将处罚情况向社会公告。"},{"i":19,"n":"第十九条","txt":"鼓励新闻媒体对违反本办法规定的行为进行舆论监督。 任何单位或个人可向当地商务主管部门、价格主管部门和工商行政管理部门举报违反本办法规定的行为。"},{"i":20,"n":"第二十条","txt":"各省、自治区、直辖市人民政府商务主管部门可会同同级价格主管、工商行政管理部门依据本办法制订实施细则，经同级人民政府批准后实施，并报商务部、国家发展和改革委员会、国家工商行政管理总局备案。"},{"i":21,"n":"第二十一条","txt":"本办法由商务部、国家发展和改革委员会、国家工商行政管理总局负责解释。"},{"i":22,"n":"第二十二条","txt":"本办法自2008年6月1日起实施。"}],"shangpinlingshouchangsuosuliaogouwudaiyouchangshiyccf4a5":[{"i":1,"n":"第一条","txt":"为节约资源、保护生态环境，引导消费者减少使用塑料购物袋，制订本办法。"},{"i":2,"n":"第二条","txt":"本办法所称商品零售场所是指向消费者提供零售服务的各类超市、商场、集贸市场。 本办法所称塑料购物袋是指由商品零售场所提供的，用于装盛消费者所购商品，具有提携功能的塑料袋。但不包括商品零售场所基于卫生及食品安全目的，用于装盛散装生鲜食品、熟食、面食等商品的塑料预包装袋。 塑料购物袋的材质及技术要求由国家相关标准予以规范。"},{"i":3,"n":"第三条","txt":"商品零售场所应当依据本办法向消费者有偿提供塑料购物袋。"},{"i":4,"n":"第四条","txt":"商务主管部门、价格主管部门、工商行政管理部门依照有关法律法规，在各自职责范围内对商品零售场所塑料购物袋有偿使用过程中的经营行为进行监督管理。"},{"i":5,"n":"第五条","txt":"商品零售场所对塑料购物袋应当依法明码标价。"},{"i":6,"n":"第六条","txt":"商品零售场所可自主制定塑料购物袋价格，但不得有下列行为： （一）低于经营成本销售塑料购物袋； （二）不标明价格或不按规定的内容方式标明价格销售塑料购物袋； （三）采取打折或其他方式不按标示的价格向消费者销售塑料购物袋； （四）向消费者无偿或变相无偿提供塑料购物袋。"},{"i":7,"n":"第七条","txt":"商品零售场所应当在销售凭证上单独列示消费者购买塑料购物袋的数量、单价和款项。 以出租摊位形式经营的集贸市场对消费者开具销售凭证确有困难的除外。"},{"i":8,"n":"第八条","txt":"商品零售场所应向依法设立的塑料购物袋生产厂家、批发商或进口商采购塑料购物袋，并索取相关证照，建立塑料购物袋购销台账，以备查验。"},{"i":9,"n":"第九条","txt":"商品零售场所不得销售不符合国家相关标准的塑料购物袋。"},{"i":10,"n":"第十条","txt":"商品零售场所应采取措施，为消费者自带购物袋、购物篮购物提供便利。"},{"i":11,"n":"第十一条","txt":"鼓励商品零售场所提供符合相关质量标准和环保要求的塑料购物袋替代品。"},{"i":12,"n":"第十二条","txt":"以出租摊位形式经营的集贸市场，可以由开办单位或经其批准在市场内设立的专营（或兼营）塑料购物袋经营摊位实行塑料购物袋统一采购、销售。"},{"i":13,"n":"第十三条","txt":"商品零售场所的经营者（以下简称经营者）对违反本办法有关规定的行为承担相应责任。 下列商品零售场所，由开办单位或出租单位对违反本办法有关规定的行为承担相应责任： （一）以出租摊位形式经营的集贸市场； （二）场内外租超市、柜台； （三）大型超市、商场引厂进店的经营摊位。"},{"i":14,"n":"第十四条","txt":"商品零售场所的经营者、开办单位或出租单位违反本办法第六条有关价格行为和明码标价规定的，由价格主管部门责令改正，并可视情节处以5000元以下罚款。"},{"i":15,"n":"第十五条","txt":"商品零售场所的经营者、开办单位或出租单位违反本办法第六条有关竞争行为和第七条规定的，由工商行政管理部门责令改正，并可视情节处以10000元以下罚款。"},{"i":16,"n":"第十六条","txt":"商品零售场所经营者、开办单位或出租单位违反本办法第八条规定的，由工商行政管理部门责令改正，并可视情节处以20000元以下罚款。"},{"i":17,"n":"第十七条","txt":"商品零售场所经营者、开办单位或出租单位违反本办法第九条规定的，由工商行政管理部门依据《中华人民共和国产品质量法》等法律法规予以处罚。"},{"i":18,"n":"第十八条","txt":"商品零售场所经营者、开办单位或出租单位因违反本办法相关规定受到处罚的，商务主管部门、价格主管部门和工商行政管理部门可将处罚情况向社会公告。"},{"i":19,"n":"第十九条","txt":"鼓励新闻媒体对违反本办法规定的行为进行舆论监督。 任何单位或个人可向当地商务主管部门、价格主管部门和工商行政管理部门举报违反本办法规定的行为。"},{"i":20,"n":"第二十条","txt":"各省、自治区、直辖市人民政府商务主管部门可会同同级价格主管、工商行政管理部门依据本办法制订实施细则，经同级人民政府批准后实施，并报商务部、国家发展和改革委员会、国家工商行政管理总局备案。"},{"i":21,"n":"第二十一条","txt":"本办法由商务部、国家发展和改革委员会、国家工商行政管理总局负责解释。"},{"i":22,"n":"第二十二条","txt":"本办法自2008年6月1日起实施。"}],"guojihuoyundailiqiyebeianbanfa":[{"i":1,"n":"第一条","txt":"为加强对国际货物运输代理业的管理，根据《中华人民共和国对外贸易法》（以下简称《外贸法》）和《中华人民共和国国际货物运输代理业管理规定》的有关规定，制订本办法。"},{"i":2,"n":"第二条","txt":"凡经国家工商行政管理部门依法注册登记的国际货物运输代理企业及其分支机构（以下简称国际货代企业），应当向商务部或商务部委托的机构办理备案。"},{"i":3,"n":"第三条","txt":"商务部是全国国际货代企业备案工作的主管部门。"},{"i":4,"n":"第四条","txt":"国际货代企业备案工作实行全国联网和属地化管理。 商务部委托符合条件的地方商务主管部门（以下简称备案机关）负责办理本地区国际货代企业备案手续；受委托的备案机关不得自行委托其他机构进行备案。 备案机关必须具备办理备案所必需的固定的办公场所，管理、录入、技术支持、维护的专职人员以及连接商务部国际货运代理企业信息管理系统(以下简称信息管理系统)的相关设备等条件。 对于符合上述条件的备案机关，商务部可出具书面委托函，发放由商务部统一监制的备案印章，并对外公布。备案机关凭商务部的书面委托函和备案印章，通过信息管理系统办理备案手续。对于情况发生变化、不符合上述条件的以及未按本办法第六、七条规定办理备案的备案机关，商务部可收回对其委托。"},{"i":5,"n":"第五条","txt":"国际货代企业在本地区备案机关办理备案（有计划单列市的省份仍按省和计划单列市的管理范围进行管理）。 国际货代企业备案程序如下： （一）领取《国际货运代理企业备案表》（以下简称《备案表》）。国际货代企业可以通过商务部政府网站（http://www.mofcom.gov.cn）下载，或到所在地备案机关领取《备案表》(样式附后)。 （二）填写《备案表》。国际货代企业应按《备案表》要求认真填写所有事项的信息，并确保所填写内容完整、准确和真实；同时认真阅读《备案表》背面的条款，并由法定代表人签字、盖章。 （三）向备案机关提交如下备案材料： 1、按本条第二款要求填写的《备案表》； 2、营业执照复印件；"},{"i":6,"n":"第六条","txt":"备案机关应自收到国际货代企业提交的上述材料之日起5日内办理备案手续，在《备案表》上加盖备案印章。"},{"i":7,"n":"第七条","txt":"备案机关在完成备案手续的同时，应当完整准确地记录和保存国际货代企业的备案信息材料，依法建立备案档案。"},{"i":8,"n":"第八条","txt":"国际货代企业应凭加盖备案印章的《备案表》在30日内到有关部门办理开展国际货代业务所需的有关手续。从事有关业务，依照有关法律、行政法规的规定，需经有关主管机关注册的，还应当向有关主管机关注册。"},{"i":9,"n":"第九条","txt":"《备案表》上的任何信息发生变更时，国际货代企业应比照本办法第五条的有关规定，在30日内办理《备案表》的变更手续，逾期未办理变更手续的，其《备案表》自动失效。 备案机关收到国际货代企业提交的书面材料后，应当即时予以办理变更手续。"},{"i":10,"n":"第十条","txt":"国际货代企业应当按照《中华人民共和国国际货物运输代理业管理规定》的有关规定，按要求向商务部或其委托机关（机构）提交与其经营活动有关的文件和资料。商务部和其委托机关（机构）应当为提供者保守商业秘密。"},{"i":11,"n":"第十一条","txt":"国际货代企业已在工商部门办理注销手续或被吊销营业执照的，自营业执照注销或被吊销之日起，《备案表》自动失效。"},{"i":12,"n":"第十二条","txt":"备案机关应当在国际货代企业撤销备案后将有关情况及时通报海关、检验检疫、外汇、税务等部门。"},{"i":13,"n":"第十三条","txt":"国际货代企业不得伪造、变造、涂改、出租、出借、转让和出卖《备案表》。"},{"i":14,"n":"第十四条","txt":"备案机关在办理备案或变更备案时，不得变相收取费用。"},{"i":15,"n":"第十五条","txt":"原经审批从事货代行业的企业应当依照本办法备案。"},{"i":16,"n":"第十六条","txt":"外商投资国际货代企业按照《外商投资国际货物运输代理企业管理办法》有关规定办理。"},{"i":17,"n":"第十七条","txt":"国际货代行业协会应协助政府主管部门做好企业备案工作，充分发挥行业协会的协调作用，加强行业自律。"},{"i":18,"n":"第十八条","txt":"本办法由商务部负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自2005年4月1日起施行。凡与本办法不一致的规定，自本办法施行之日起废止。 附件：国际货运代理企业备案表（样式） 本人代表本企业作如下保证： 一、遵守《中华人民共和国对外贸易法》、《中华人民共和国国际货物运输代理业管理规定》及其配套法律、法规、规章。 二、遵守与国际货物运输代理业相关的运输、海关、外汇、税务、检验检疫、环保、知识产权等其他法律、法规、规章。 三、服从主管部门对国际货物运输代理业的行业管理，自觉维护国际货物运输代理业的经营秩序。 四、不伪造、变造、涂改、出租、出借、转让、出卖《国际货运代理企业备案表》。 五、在备案表中所填写的信息是完整的、准确的、真实的。 六、按要求认真填写、及时提交与经营活动有关的文件和资料。 七、《国际货运代理企业备案表》上填写的任何事项发生变化之日起，30日内到原备案登记机关办理《国际货运代理企业备案表》的变更手续。 以上如有违反，将承担一"}],"zaijingneijubanduiwaijingjijishuzhanlanhuiguanliza334f39":[{"i":1,"n":"第一条","txt":"为使举办对外经济技术展览会有秩序进行，保障展览业的健康发展，根据《中华人民共和国对外贸易法》及《国务院办公厅关于对在我国境内举办对外经济技 术展览会加强管理的通知》，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内举办的对外经济技术展览会。包括： (一)国际展览会和国际博览会，境外民用经济技术来华展览会(以下统称国际展览会)。 (二)对外经济贸易洽谈会和出口商品交易会。包括综合性或专业性的出口商品、投资贸易(利用外资)、技术出口、对外经济合作洽谈会或交易会。"},{"i":3,"n":"第三条","txt":"举办对外经济技术展览会，由对外贸易经济合作部(以下简称外经贸部)负责协调和管理。"},{"i":4,"n":"第四条","txt":"对外经济技术展览会的举办单位，包括主办单位和承办单位。 主办单位主要负责制定并实施举办对外经济技术展览会的方案和计划，组织招商招展，负责财务管理，并承担举办展览的民事责任。 承办单位主要负责布展、展览施工、安全保卫及会务事项。"},{"i":5,"n":"第五条","txt":"境内主办单位和承办单位，必须具有主办和承办资格。 （一）经外经贸部或其授权部门批准，以下单位具有主办资格并可主办相应的对外经济技术展览会： 1. 省级经济贸易促进机构或行业(专业)协会、商会； 2. 展览公司，外经贸公司。 （二）省级及副省级市人民政府或外经贸主管部门可以主办对外经济贸易洽谈会和出口商品交易会。 （三）国务院部门可以部门名义主办与其业务相关的国际展览会；省级人民政府可以其名义主 办有关的国际展览会。 以国务院部门或省级人民政府名义主办国际展览会，应由具有主办资格的单位(指本条第(一)款所列单位或省级及副省级市外经贸主管部门)承办，并由其承担办展民事责任及主办单位有关职责。 （四）凡具有主办资格的单位均具有相应的承办资格。受主办单位委托，有关公司可以承办展览的单项业务(包括设计、布展、展览施工、广告 )。"},{"i":6,"n":"第六条","txt":"境外(指外国和台港澳地区，以下均同)机构举办对外经济技术展览会，必须联合或委托境内具有主办资格的单位举办。境内招商招展由境内主办单位负责。 属境外机构的主办单位，应是具有相当规模和办展实力，在国际上影响和信誉良好的展览机构、大型跨国公司、经济团体或组织(包括经济贸易促进机构、商会、行业协会等)。"},{"i":7,"n":"第七条","txt":"国家间双边、多边及国内外友好省市间的展览(含交流展)，按对等原则和实际需要由相应的单位主办和承办。"},{"i":8,"n":"第八条","txt":"主办单位和承办单位的展览行为必须规范，维护参展单位的合法权 益。 （一）主办单位与承办单位之间，以及主办单位之间(即有二个或二个以上的单位联合主办)，必须签订规范的办展协议，明确职责分工及承担办展民事责任单位等事项。 （二）招商招展由主办单位负责。 除以国务院部门和省级人民政府名义主办的国际展览会，其他均不得以组委会或筹委会名义招展。 （三）招商招展必须以企业自愿为原则，不得进行行政干预。 （四）招展文件或招展(参展)合同必须明确主办单位和参展单位的权利与义务，明确承担办展民事责任的单位。 （五）举办以国际展为名称的对外经济技术展览会，境外参展商(不包括境内外商投资企业)比例必须达到20%以上。 （六）举办对外经济技术展览会的广告、宣传材料必须真实可靠。未经同意不得将其他单位列为支持(赞助)单位。 （七）主办单位在办展结束后1个月之内，向审批部门报送举办展览总结。对由境外机构主办并境内"},{"i":9,"n":"第九条","txt":"举办展览面积在1000平方米(指展位总面积)以上的对外经济技术展览会必须经批准，并实行分级审批。 （一）以国务院部门或省级人民政府名义主办的国际展览会，以及由省级或副省级市人民政府主办的对外经济贸易洽谈会和出口商品交易会，须报国务院批准。 省级及副省级市外经贸主管部门和多省(自治区、直辖市)联合主办的对外经济贸易洽谈会和出口商品交易会，由外经贸部审批。 （二）国务院部门所属单位主办的对外经济技术展览会，以及境外机构主办的国际展览会，报外经贸部审批。对在北京以外地区举办的，主办单位需事先征得举办地外经贸主管部门同意 。 （三）地方其他单位主办的对外经济技术展览会，由所在省、自治区、直辖市外经贸主管部门审批，并报外经贸部备案。 （四）以科研、技术交流、研讨为内容的展览会，由科学技术部负责审批。 （五）中国国际贸易促进委员会(以下简称贸促会)系统单位主办的对外经济技术展览会，由贸促会审批并报"},{"i":10,"n":"第十条","txt":"举办对外经济技术展览会由主办单位申请报批。 属于二个或二个以上单位联合主办的，由承担办展民事责任的主办单位申请报批。 境外机构联合或委托境内有主办资格的单位举办国际展览会，由境内单位申请报批。"},{"i":11,"n":"第十一条","txt":"审批对外经济技术展览会需审查的主要内容： （一）主办单位和承办单位资格。 境外机构主办或与境内单位联合主办的，需审查境外机构资信及有关情况。 （二）展览会名称、内容、规模、时间、地点，组织招商招展的方案和计划，办展的可行性报告，主办单位与承办单位的协议。二个或二个以上单位联合主办的，需审查联合主办的协议(包括各主办单位的职责分工，承担办展民事责任的单位等)。境外机构联合或委托境内单位举办的，需审查其联合或委托办展协议。 （三）国务院部门所属单位及贸促会系统单位在北京以外地区主办的，需审查是否征得当地外经贸主管部门的同意。"},{"i":12,"n":"第十二条","txt":"申请报批的单位按审批对外经济技术展览会需审查的内容和要求，向审批部门申报并提交有关文件和资料。申请报批时间原则上应提前12个月。"},{"i":13,"n":"第十三条","txt":"对外经济技术展览会批准文件的主要内容： （一）展览会名称。 （二）主办单位(主办单位如有境外机构应注明国别或地区)。 （三）展览会的主要业务内容、规模、举办地点、时间。 （四）其他需要批准或备注事项。 （五）以上内容变更，应办理批准手续。"},{"i":14,"n":"第十四条","txt":"批准文件抄送办展地外经贸主管部门和海关。"},{"i":15,"n":"第十五条","txt":"具有对外经济技术展览会主办资格的单位，可自行举办面积在1000平方米以下的对外经济技术展览会，但应报有关审批部门备案。"},{"i":16,"n":"第十六条","txt":"严格控制同类展览的数量。鼓励和推动联合办展，鼓励举办专业性展览会。对申请举办较多的同类展览，审批部门要加强协调，并对照《对外经济技术展览会分类目录》按以下原则审批： （一）同类展览，原则上在同一省、自治区、直辖市及副省级市，每年不超过2个。 （二）优先批准规模大、影响大、定期举办的展览。 （三）优先批准具有行业优势和办展经验的单位举办的展览。"},{"i":17,"n":"第十七条","txt":"审批部门负责对主办单位、承办单位办展活动进行管理和监督，检查办展质量，维护正常的办展秩序。对国务院部门所属单位及贸促会系统单位在北京以外地区主办的展览，由当地外经贸主管部门进行管理和监督检查。"},{"i":18,"n":"第十八条","txt":"由外经贸部牵头，会同科学技术部、贸促会等单位，以召开联席会议的形式，定期通报审批和举办对外经济技术展览会情况，调整和公布《对外经济技术展览 会分类目录》，对外发布展览信息；研究对外展览业务发展过程中出现的情况和问题，及时采取有效措施，加强协调管理；维护办展单位和参展单位的合法权益，保障对外展览业的健康发展；推动和扶持举办有特色、有规模、有影响的对外经济技术展览会。"},{"i":19,"n":"第十九条","txt":"境外展览品监管由海关按照《中华人民共和国海关对进口展览品监管办法》执行。对1000平方米以上展览的境外展览品监管及留购，由办展地海关凭本办法规定的审批单位的批准文件按规定办理；对1000平方米以下的，海关凭主办单位申请按规定办理。"},{"i":20,"n":"第二十条","txt":"对外经济技术展览会的境外展览品不得擅自零售。对确需零售的，须事先报外经贸部批准，海关赁外经贸部批件按规定办理，并照章征收进口关税和其他税费。"},{"i":21,"n":"第二十一条","txt":"对违反本办法规定举办对外经济技术展览会，以及在办展过程中有乱摊派、损害参展单位合法权益等违反法律法规行为的，由外经贸部依据《国务院办公 厅关于对在我国境内举办对外经济技术展览会加强管理的通知》有关规定，取消其主办资格 ，并由有关部门依法查处。对不具备主办或承办对外经济技术展览会资格而擅自办展的，盗用其他单位名称办展的，或转让、转卖展览批准文件的，由各级外经贸主管部门和工商行政管理机关依法查处。对违反海关规定的，由海关依法处理。"},{"i":22,"n":"第二十二条","txt":"未经外经贸部批准，任何对外经济技术展览会不得使用 “中国出口商品交 易会”或“广交会”名称及其他接近名称(包括英文名称THE CHINESE EXPORT COMMODITIESF AIR，简称CANTON FAIR，缩写CECF )。"},{"i":23,"n":"第二十三条","txt":"举办对外经济技术展览会的审批管理，国家法规和国务院另有规定的，从其规定。"},{"i":24,"n":"第二十四条","txt":"本办法自1998年10月1日起实行。凡过去规定与本办法不一致的 ，以本办法为准。本办法由外经贸部负责解释。涉及海关业务的，由海关总署负责解释。"}],"zaizuguodalujubanduitaiwanjingjijishuzhanlanhuiguaa91091":[{"i":1,"n":"第一条","txt":"为使举办对台湾经济技术展览会规范有序地进行，促进海峡两岸经贸关系的发展，根据《国务院办公厅关于对在我国境内举办对外经济技术展览会加强管理的通知》和对外贸易经济合作部《在境内举办对外经济技术展览会管理暂行办法》，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在祖国大陆举办的对台湾经济技术展览会，包括： （一）海峡两岸的经济技术展览会。 （二）对台湾出口商品交易会。 （三）台湾商品展览会。 （四）台湾厂商参展的国际性展览会、博览会。 （五）台湾厂商参展的全国性展览会。"},{"i":3,"n":"第三条","txt":"对台湾经济技术展览会的举办单位（包括主办单位和承办单位）的责任、资格和展览行为按照对外贸易经济合作部《在境内举办对外经济技术展览会管理暂行办法》的规定执行。"},{"i":4,"n":"第四条","txt":"台湾民间机构在祖国大陆举办对台湾经济技术展览会，须联合或委托大陆具有主办资格的单位举办。在大陆的招商招展由大陆主办单位负责。 台湾的主办单位，应是具有相当规模和办展实力、信誉良好的展览机构、大型公司、经济团体或组织（包括经济贸易促进机构、同业公会、行业协会等）。"},{"i":5,"n":"第五条","txt":"举办海峡两岸的经济技术展览会，由外经贸部会同国务院台湾事务办公室审批。"},{"i":6,"n":"第六条","txt":"除第五条规定之外，举办其他对台湾经济技术展览会，由对外贸易经济合作部（以下简称外经贸部）负责审批，报国务院台湾事务办公室备案。"},{"i":7,"n":"第七条","txt":"审批举办对台湾经济技术展览会需审查的主要内容： （一）政治内容 举办对台湾经济技术展览会，不得出现“台湾独立”、“两个中国”、“一中一台”等政治问题。台湾厂商参展的宣传品、杂志、电子出版物等资料中不得有代表“中华民国”的字样、图片、音乐等。 （二）展览会名称、展品内容、展出面积、时间、地点、筹组方案和计划等。 祖国大陆与台湾联合举办的经济技术展览会，应冠以“海峡两岸”的名称；各省（市、区）与台湾省联合举办的经济技术展览会，则应分别冠以该省（市、区）与台湾省之名（如：“闽台××展览会”、“沪台××展览会”等）。 展品应符合国家知识产权保护法和国家产业政策，具有先进水平，有利于扩大海峡两岸经贸交流与合作。"},{"i":8,"n":"第八条","txt":"申请报批的单位应按要求向外经贸部提交有关文件和资料。 邀请台湾厂商参展的国际性及全国性展览会、博览会，应提交有关主管单位的批件、参展台湾厂商的名单（中文）、展品内容、展出面积等详细清单，并提前一个月申请报批；举办海峡两岸的经济技术展览会、对台湾出口商品交易会、台湾商品展览会，应提交展览会的筹组计划和方案、可行性研究报告、参展企业及其展品的有关情况等，并提前六个月申请报批。"},{"i":9,"n":"第九条","txt":"海关凭外经贸部批件，根据《中华人民共和国海关对进口展览品监管办法》，办理进出境手续。"},{"i":10,"n":"第十条","txt":"祖国大陆台资企业参加在大陆举办的对台湾经济技术展览会应以大陆台资企业名义参展。以台湾厂商名义参展；展出从台湾进口商品的，适用本办法。"},{"i":11,"n":"第十一条","txt":"本办法从公布之日起实行并由外经贸部负责解释。本办法未尽事宜，适用对外贸易经济合作部《在境内举办对外经济技术展览会管理暂行办法》的有关规定。 附件二 主办单位报送举办对台湾经济技术展览会总结的内容和要求 一、主办单位和承办单位。 二、展览时间和地点。 三、展览规模，包括： （一）展览面积或摊位总数（按标准摊位3 X3平方米计算）； （二）参展单位总数； （三）举办国际性及全国性的展览会、博览会，报台湾参展单位数量及所占比例，境外参展面积（或摊位数量）及所占比例，参观人数；举办海峡两岸的经济技术展览会、对台湾出口商品交易会及台湾商品展览会，报台湾到会客商数量及相当于摊位总数的比例，洽谈项目或出口成交额。 四、参展单位、到会客商、参观人员对展览会的反映和意见。 五、主办单位之间或主办单位与承办单位之间履行联合办展协议的情况。 六、审批部门要求报送的其他事项或材料。"}],"jingwaitouziguanlibanfa":[{"i":1,"n":"第一条","txt":"为了促进和规范境外投资，提高境外投资便利化水平，根据《国务院关于投资体制改革的决定》、《国务院对确需保留的行政审批项目设定行政许可的决定》及相关法律规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称境外投资，是指在中华人民共和国境内依法设立的企业（以下简称企业）通过新设、并购及其他方式在境外拥有非金融企业或取得既有非金融企业所有权、控制权、经营管理权及其他权益的行为。"},{"i":3,"n":"第三条","txt":"企业开展境外投资，依法自主决策、自负盈亏。"},{"i":4,"n":"第四条","txt":"企业境外投资不得有以下情形： （一）危害中华人民共和国国家主权、安全和社会公共利益，或违反中华人民共和国法律法规； （二）损害中华人民共和国与有关国家（地区）关系； （三）违反中华人民共和国缔结或者参加的国际条约、协定； （四）出口中华人民共和国禁止出口的产品和技术。"},{"i":5,"n":"第五条","txt":"商务部和各省、自治区、直辖市、计划单列市及新疆生产建设兵团商务主管部门（以下称省级商务主管部门）负责对境外投资实施管理和监督。"},{"i":6,"n":"第六条","txt":"商务部和省级商务主管部门按照企业境外投资的不同情形，分别实行备案和核准管理。 企业境外投资涉及敏感国家和地区、敏感行业的，实行核准管理。 企业其他情形的境外投资，实行备案管理。"},{"i":7,"n":"第七条","txt":"实行核准管理的国家是指与中华人民共和国未建交的国家、受联合国制裁的国家。必要时，商务部可另行公布其他实行核准管理的国家和地区的名单。 实行核准管理的行业是指涉及出口中华人民共和国限制出口的产品和技术的行业、影响一国（地区）以上利益的行业。"},{"i":8,"n":"第八条","txt":"商务部和省级商务主管部门应当依法办理备案和核准，提高办事效率，提供优质服务。 商务部和省级商务主管部门通过“境外投资管理系统”（以下简称“管理系统”）对企业境外投资进行管理，并向获得备案或核准的企业颁发《企业境外投资证书》（以下简称《证书》，样式见附件1）。《证书》由商务部和省级商务主管部门分别印制并盖章，实行统一编码管理。 《证书》是企业境外投资获得备案或核准的凭证，按照境外投资最终目的地颁发。"},{"i":9,"n":"第九条","txt":"对属于备案情形的境外投资，中央企业报商务部备案；地方企业报所在地省级商务主管部门备案。 中央企业和地方企业通过“管理系统”按要求填写并打印《境外投资备案表》（以下简称《备案表》，样式见附件2），加盖印章后，连同企业营业执照复印件分别报商务部或省级商务主管部门备案。 《备案表》填写如实、完整、符合法定形式，且企业在《备案表》中声明其境外投资无本办法第四条所列情形的，商务部或省级商务主管部门应当自收到《备案表》之日起3个工作日内予以备案并颁发《证书》。企业不如实、完整填报《备案表》的，商务部或省级商务主管部门不予备案。"},{"i":10,"n":"第十条","txt":"对属于核准情形的境外投资，中央企业向商务部提出申请，地方企业通过所在地省级商务主管部门向商务部提出申请。 企业申请境外投资核准需提交以下材料： （一）申请书，主要包括投资主体情况、境外企业名称、股权结构、投资金额、经营范围、经营期限、投资资金来源、投资具体内容等； （二）《境外投资申请表》（样式见附件3），企业应当通过“管理系统”按要求填写打印，并加盖印章； （三）境外投资相关合同或协议； （四）有关部门对境外投资所涉的属于中华人民共和国限制出口的产品或技术准予出口的材料； （五）企业营业执照复印件。"},{"i":11,"n":"第十一条","txt":"核准境外投资应当征求我驻外使（领）馆（经商处室）意见。涉及中央企业的，由商务部征求意见；涉及地方企业的，由省级商务主管部门征求意见。征求意见时，商务部和省级商务主管部门应当提供投资事项基本情况等相关信息。驻外使（领）馆（经商处室）应当自接到征求意见要求之日起7个工作日内回复。"},{"i":12,"n":"第十二条","txt":"商务部应当在受理中央企业核准申请后20个工作日内（包含征求驻外使（领）馆（经商处室）意见的时间）作出是否予以核准的决定。申请材料不齐全或者不符合法定形式的，商务部应当在3个工作日内一次告知申请企业需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。中央企业按照商务部的要求提交全部补正申请材料的，商务部应当受理该申请。 省级商务主管部门应当在受理地方企业核准申请后对申请是否涉及本办法第四条所列情形进行初步审查，并在15个工作日内（包含征求驻外使（领）馆（经商处室）意见的时间）将初步审查意见和全部申请材料报送商务部。申请材料不齐全或者不符合法定形式的，省级商务主管部门应当在3个工作日内一次告知申请企业需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。地方企业按照省级商务主管部门的要求提交全部补正申请材料的，省级商务主管部门应当受理该申请。商务部收到省级商务主管部门"},{"i":13,"n":"第十三条","txt":"对予以核准的境外投资，商务部出具书面核准决定并颁发《证书》；因存在本办法第四条所列情形而不予核准的，应当书面通知申请企业并说明理由，告知其享有依法申请行政复议或者提起行政诉讼的权利。企业提供虚假材料申请核准的，商务部不予核准。"},{"i":14,"n":"第十四条","txt":"两个以上企业共同开展境外投资的，应当由相对大股东在征求其他投资方书面同意后办理备案或申请核准。如果各方持股比例相等，应当协商后由一方办理备案或申请核准。如投资方不属同一行政区域，负责办理备案或核准的商务部或省级商务主管部门应当将备案或核准结果告知其他投资方所在地商务主管部门。"},{"i":15,"n":"第十五条","txt":"企业境外投资经备案或核准后，原《证书》载明的境外投资事项发生变更的，企业应当按照本章程序向原备案或核准的商务部或省级商务主管部门办理变更手续。"},{"i":16,"n":"第十六条","txt":"自领取《证书》之日起2年内，企业未在境外开展投资的，《证书》自动失效。如需再开展境外投资，应当按照本章程序重新办理备案或申请核准。"},{"i":17,"n":"第十七条","txt":"企业终止已备案或核准的境外投资，应当在依投资目的地法律办理注销等手续后，向原备案或核准的商务部或省级商务主管部门报告。原备案或核准的商务部或省级商务主管部门根据报告出具注销确认函。 终止是指原经备案或核准的境外企业不再存续或企业不再拥有原经备案或核准的境外企业的股权等任何权益。"},{"i":18,"n":"第十八条","txt":"《证书》不得伪造、涂改、出租、出借或以任何其他形式转让。已变更、失效或注销的《证书》应当交回原备案或核准的商务部或省级商务主管部门。"},{"i":19,"n":"第十九条","txt":"企业应当客观评估自身条件、能力，深入研究投资目的地投资环境，积极稳妥开展境外投资，注意防范风险。境内外法律法规和规章对资格资质有要求的，企业应当取得相关证明文件。"},{"i":20,"n":"第二十条","txt":"企业应当要求其投资的境外企业遵守投资目的地法律法规、尊重当地风俗习惯，履行社会责任，做好环境、劳工保护、企业文化建设等工作，促进与当地的融合。"},{"i":21,"n":"第二十一条","txt":"企业对其投资的境外企业的冠名应当符合境内外法律法规和政策规定。未按国家有关规定获得批准的企业，其境外企业名称不得使用“中国”、“中华”等字样。"},{"i":22,"n":"第二十二条","txt":"企业应当落实人员和财产安全防范措施，建立突发事件预警机制和应急预案。在境外发生突发事件时，企业应当在驻外使（领）馆和国内有关主管部门的指导下，及时、妥善处理。 企业应当做好外派人员的选审、行前安全、纪律教育和应急培训工作，加强对外派人员的管理，依法办理当地合法居留和工作许可。"},{"i":23,"n":"第二十三条","txt":"企业应当要求其投资的境外企业中方负责人当面或以信函、传真、电子邮件等方式及时向驻外使（领）馆（经商处室）报到登记。"},{"i":24,"n":"第二十四条","txt":"企业应当向原备案或核准的商务部或省级商务主管部门报告境外投资业务情况、统计资料，以及与境外投资相关的困难、问题，并确保报送情况和数据真实准确。"},{"i":25,"n":"第二十五条","txt":"企业投资的境外企业开展境外再投资，在完成境外法律手续后，企业应当向商务主管部门报告。涉及中央企业的，中央企业通过“管理系统”填报相关信息，打印《境外中资企业再投资报告表》（以下简称《再投资报告表》，样式见附件4）并加盖印章后报商务部；涉及地方企业的，地方企业通过\"管理系统\"填报相关信息，打印《再投资报告表》并加盖印章后报省级商务主管部门。"},{"i":26,"n":"第二十六条","txt":"商务部负责对省级商务主管部门的境外投资管理情况进行检查和指导。省级商务主管部门应当每半年向商务部报告本行政区域内境外投资的情况。"},{"i":27,"n":"第二十七条","txt":"商务部会同有关部门为企业境外投资提供权益保障、投资促进、风险预警等服务。 商务部发布《对外投资合作国别（地区）指南》、国别产业指引等文件，帮助企业了解投资目的地投资环境；加强对企业境外投资的指导和规范，会同有关部门发布环境保护等指引，督促企业在境外合法合规经营；建立对外投资与合作信息服务系统，为企业开展境外投资提供数据统计、投资机会、投资障碍、风险预警等信息。"},{"i":28,"n":"第二十八条","txt":"企业以提供虚假材料等不正当手段办理备案并取得《证书》的，商务部或省级商务主管部门撤销该企业境外投资备案，给予警告，并依法公布处罚决定。"},{"i":29,"n":"第二十九条","txt":"企业提供虚假材料申请核准的，商务部给予警告，并依法公布处罚决定。该企业在一年内不得再次申请该项核准。 企业以欺骗、贿赂等不正当手段获得境外投资核准的，商务部撤销该企业境外投资核准，给予警告，并依法公布处罚决定。该企业在三年内不得再次申请该项核准；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"企业开展境外投资过程中出现本办法第四条所列情形的，应当承担相应的法律责任。"},{"i":31,"n":"第三十一条","txt":"企业伪造、涂改、出租、出借或以任何其他形式转让《证书》的，商务部或省级商务主管部门给予警告；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"境外投资出现第二十八至三十一条规定的情形以及违反本办法其他规定的企业，三年内不得享受国家有关政策支持。"},{"i":33,"n":"第三十三条","txt":"商务部和省级商务主管部门有关工作人员不依照本办法规定履行职责、滥用职权、索取或者收受他人财物或者谋取其他利益，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。"},{"i":34,"n":"第三十四条","txt":"省级商务主管部门可依照本办法制定相应的工作细则。"},{"i":35,"n":"第三十五条","txt":"本办法所称中央企业系指国务院国有资产监督管理委员会履行出资人职责的企业及其所属企业、中央管理的其他单位。"},{"i":36,"n":"第三十六条","txt":"事业单位法人开展境外投资、企业在境外设立分支机构参照本办法执行。"},{"i":37,"n":"第三十七条","txt":"企业赴香港、澳门、台湾地区投资参照本办法执行。"},{"i":38,"n":"第三十八条","txt":"本办法由商务部负责解释。"},{"i":39,"n":"第三十九条","txt":"本办法自2014年10月6日起施行。商务部2009年发布的《境外投资管理办法》（商务部令2009年第5号）同时废止。 附件： 1、企业境外投资证书（样式）.doc 2、境外投资备案表（样式）.docx 3、境外投资申请表（样式）.doc 4、境外中资企业再投资报告表（样式）.doc"}],"waishangtouziqiyehebingyufenliguiding":[{"i":1,"n":"第一条","txt":"为了规范涉及外商投资企业合并与分立的行为，保护企业投资者和债权人的合法权益，根据《中华人民共和国公司法》和有关外商投资企业的法律和行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于依照中国法律在中国境内设立的中外合资经营企业、具有法人资格的中外合作经营企业、外资企业、外商投资股份有限公司(以下统称公司)之间合并或分立。 公司与中国内资企业合并，参照有关法律、法规和本规定办理。"},{"i":3,"n":"第三条","txt":"本规定所称合并，是指两个以上公司依照公司法有关规定，通过订立协议而归并成为一个公司。 公司合并可以采取吸收合并和新设合并两种形式。 吸收合并，是指公司接纳其他公司加入本公司，接纳方继续存在，加入方解散。 新设合并，是指两个以上公司合并设立一个新的公司，合并各方解散。"},{"i":4,"n":"第四条","txt":"本规定所称分立，是指一个公司依照公司法有关规定，通过公司最高权力机构决议分成两个以上的公司。 公司分立可以采取存续分立和解散分立两种形式。 存续分立，是指一个公司分离成两个以上公司，本公司继续存在并设立一个以上新的公司。 解散分立，是指一个公司分解为两个以上公司，本公司解散并设立两个以上新的公司。"},{"i":5,"n":"第五条","txt":"公司合并或分立，应当遵守中国的法律、法规和本规定，遵循自愿、平等和公平竞争的原则，不得损害社会公共利益和债权人的合法权益。 公司合并或分立，应符合《指导外商投资方向暂行规定》和《外商投资产业指导目录》的规定，不得导致外国投资者在不允许外商独资、控股或占主导地位的产业的公司中独资、控股或占主导地位。 公司因合并或分立而导致其所从事的行业或经营范围发生变更的，应符合有关法律、法规及国家产业政策的规定并办理必要的审批手续。"},{"i":6,"n":"第六条","txt":"公司合并或分立，应当符合海关、税务和外汇管理等有关部门颁布的规定。合并或分立后存续或新设的公司，经审批机关、海关和税务等机关核定，继续享受原公司所享受的各项外商投资企业待遇。"},{"i":7,"n":"第七条","txt":"公司合并或分立，须经公司原审批机关批准并到登记机关办理有关公司设立、变更或注销登记。 拟合并公司的原审批机关或登记机关有两个以上的，由合并后公司住所地对外经济贸易主管部门和国家工商行政管理总局(以下简称国家工商总局)授权的登记机关作为审批和登记机关。 拟合并公司的投资总额之和超过公司原审批机关或合并后公司住所地审批机关审批权限的，由具有相应权限的审批机关审批。 拟合并的公司至少有一家为股份有限公司的，由中华人民共和国对外贸易经济合作部(以下简称外经贸部)审批。"},{"i":8,"n":"第八条","txt":"因公司合并或分立而解散原公司或新设异地公司，须征求拟解散或拟设立公司的所在地审批机关的意见。"},{"i":9,"n":"第九条","txt":"有限责任公司之间合并后为有限责任公司。股份有限公司之间合并后为股份有限公司。 上市的股份有限公司与有限责任公司合并后为股份有限公司。非上市的股份有限公司与有限责任公司合并后可以是股份有限公司，也可以是有限责任公司。"},{"i":10,"n":"第十条","txt":"股份有限公司之间合并或者公司合并后为有限责任公司的，合并后公司的注册资本为原公司注册资本额之和。 有限责任公司与股份有限公司合并后为股份有限公司的，合并后公司的注册资本为原有限责任公司净资产额根据拟合并的股份有限公司每股所含净资产额折成的股份额与原股份有限公司股份总额之和。"},{"i":11,"n":"第十一条","txt":"根据本规定第十条第一款合并的，各方投资者在合并后的公司中的股权比例，根据国家有关规定，由投资者之间协商或根据资产评估机构对其在原公司股权价值的评估结果，在合并后的公司合同、章程中确定，但外国投资者的股权比例不得低于合并后公司注册资本的百分之二十五。"},{"i":12,"n":"第十二条","txt":"分立后公司的注册资本额，由分立前公司的最高权力机构，依照有关外商投资企业法律、法规和登记机关的有关规定确定，但分立后各公司的注册资本额之和应为分立前公司的注册资本额。"},{"i":13,"n":"第十三条","txt":"各方投资者在分立后的公司中的股权比例，由投资者在分立后的公司合同、章程中确定，但外国投资者的股权比例不得低于分立后公司注册资本的百分之二十五。"},{"i":14,"n":"第十四条","txt":"公司合并，采取吸收合并形式的，接纳方公司的成立日期为合并后公司的成立日期；采取新设合并形式的，登记机关核准设立登记并签发营业执照的日期为合并后公司的成立日期。 因公司分立而设立新公司的，登记机关核准设立登记并签发营业执照的日期为分立后公司的成立日期。"},{"i":15,"n":"第十五条","txt":"涉及上市的股份有限公司合并或分立的，应当符合有关法律、法规和国务院证券监督管理部门对上市公司的规定并办理必要的审批手续。"},{"i":16,"n":"第十六条","txt":"公司与中国内资企业合并必须符合我国利用外资的法律、法规规定和产业政策要求并具备以下条件： (一)拟合并的中国内资企业是依照《中华人民共和国公司法》规范组建的有限责任公司或股份有限公司； (二)投资者符合法律、法规和部门规章对合并后公司所从事有关产业的投资者资格要求； (三)外国投资者的股权比例不得低于合并后公司注册资本的百分之二十五； (四)合并协议各方保证拟合并公司的原有职工充分就业或给予合理安置。"},{"i":17,"n":"第十七条","txt":"公司与中国内资企业合并后为外商投资企业，其投资总额为原公司的投资总额与中国内资企业财务审计报告所记载的企业资产总额之和，注册资本为原公司的注册资本额与中国内资企业的注册资本额之和。合并后的公司注册资本与投资总额比例，应当符合国家工商总局《关于中外合资经营企业注册资本与投资总额比例的暂行规定》；在特殊情况下，不能执行该规定的，须经外经贸部会同国家工商总局批准。"},{"i":18,"n":"第十八条","txt":"与公司合并的中国内资企业已经投资设立的企业，成为合并后公司所持股的企业，应当符合中国利用外资的产业政策要求和《关于外商投资企业境内投资的暂行规定》。合并后的公司不得在禁止外商投资产业的企业中持有股权。"},{"i":19,"n":"第十九条","txt":"公司吸收合并，由接纳方公司作为申请人，公司新设合并，由合并各方协商确定一个申请人。 申请人应向审批机关报送下列文件： (一)各公司法定代表人签署的关于公司合并的申请书和公司合并协议； (二)各公司最高权力机构关于公司合并的决议； (三)各公司合同、章程； (四)各公司的批准证书和营业执照复印件； (五) 各公司的资产负债表及财产清单； (六) 各公司上一年度的审计报告； (七) 各公司的债权人名单； (八) 合并后的公司合同、章程； (九) 合并后的公司最高权力机构成员名单； (十) 审批机关要求报送的其他文件。 公司与中国内资企业合并的，申请人还应向审批机关报送拟合并的中国内资企业已投资设立企业的营业执照复印件。"},{"i":20,"n":"第二十条","txt":"公司合并协议应包括下列主要内容： (一)合并协议各方的名称、住所、法定代表人； (二)合并后公司的名称、住所、法定代表人； (三)合并后公司的投资总额和注册资本； (四)合并形式； (五)合并协议各方债权、债务的承继方案； (六)职工安置办法； (七)违约责任； (八)解决争议的方式； (九)签约日期、地点； (十)合并协议各方认为需要规定的其他事项。"},{"i":21,"n":"第二十一条","txt":"拟合并的公司有两个以上原审批机关的，拟解散的公司应当在依照本规定第十九条向审批机关报送有关文件之前，向其原审批机关提交因公司合并而解散的申请。 原审批机关应自接到前款有关解散申请之日起十五日内做出是否同意解散的批复。超过十五日，原审批机关未作批复的，视作原审批机关同意该公司解散。 如果原审批机关在前款规定期限内，作出不同意有关公司解散的批复，拟解散公司可将有关解散申请提交原审批机关与公司合并的审批机关共同的上一级对外经济贸易主管部门，该部门应自接到有关公司解散申请之日起三十日内作出裁决。 如果审批机关不同意或不批准公司合并，则有关公司解散的批复自行失效。"},{"i":22,"n":"第二十二条","txt":"拟分立的公司应向审批机关报送下列文件： (一)公司法定代表人签署的关于公司分立的申请书； (二)公司最高权力机构关于公司分立的决议； (三)因公司分立而拟存续、新设的公司(以下统称分立协议各方)签订的公司分立协议； (四)公司合同、章程； (五)公司的批准证书和营业执照复印件； (六) 公司的资产负债表及财产清单； (七) 公司的债权人名单； (八) 分立后的各公司合同、章程； (九) 分立后的各公司最高权力机构成员名单； (十) 审批机关要求报送的其他文件。 因公司分立而在异地新设公司的，公司还必须向审批机关报送拟设立公司的所在地审批机关对因分立而新设公司签署的意见。"},{"i":23,"n":"第二十三条","txt":"公司分立协议应包括下列主要内容： (一)分立协议各方拟定的名称、住所、法定代表人； (二)分立后公司的投资总额和注册资本； (三)分立形式； (四)分立协议各方对拟分立公司财产的分割方案； (五)分立协议各方对拟分立公司债权、债务的承继方案； (六)职工安置办法； (七)违约责任； (八)解决争议的方式； (九)签约日期、地点； (十)分立协议各方认为需要规定的其他事项。"},{"i":24,"n":"第二十四条","txt":"合并后存续的公司或者新设的公司全部承继因合并而解散的公司的债权、债务。 分立后的公司按照分立协议承继原公司的债权、债务。"},{"i":25,"n":"第二十五条","txt":"审批机关应自接到本规定第十九条或第二十二条规定报送的有关文件之日起四十五日内，以书面形式作出是否同意合并或分立的初步批复。 公司合并的审批机关为外经贸部的，如果外经贸部认为公司合并具有行业垄断的趋势或者可能形成就某种特定商品或服务的市场控制地位而妨碍公平竞争，可于接到前款所述有关文件后，召集有关部门和机构，对拟合并的公司进行听证并对该公司及其相关市场进行调查。前款所述审批期限可延长至一百八十天。"},{"i":26,"n":"第二十六条","txt":"拟合并或分立的公司应当自审批机关就同意公司合并或分立作出初步批复之日起十日内，向债权人发出通知书，并于三十日内在全国发行的省级以上报纸上至少公告三次。 公司应在上述通知书和公告中说明对现有公司债务的承继方案。"},{"i":27,"n":"第二十七条","txt":"公司债权人自接到本规定第二十六条所述通知书之日起三十日内、未接到通知书的债权人自第一次公告之日起九十日内，有权要求公司对其债务承继方案进行修改，或者要求公司清偿债务或提供相应的担保。 如果公司债权人未在前款规定期限内行使有关权利，视为债权人同意拟合并或分立公司的债权、债务承继方案，该债权人的主张不得影响公司的合并或分立进程。"},{"i":28,"n":"第二十八条","txt":"拟合并或分立的公司自第一次公告之日起九十日后，公司债权人无异议的，拟合并公司的申请人或拟分立的公司应向审批机关提交下列文件： (一)公司在报纸上三次登载公司合并或分立公告的证明； (二)公司通知其债权人的证明； (三)公司就其有关债权、债务处理情况的说明； (四)审批机关要求提交的其他文件。"},{"i":29,"n":"第二十九条","txt":"审批机关应自接到本规定第二十八条所列文件之日起三十日内，决定是否批准公司合并或分立。"},{"i":30,"n":"第三十条","txt":"公司采取吸收合并形式的，接纳方公司应到原审批机关办理外商投资企业批准证书变更手续并到登记机关办理公司变更登记；加入方公司应到原审批机关缴销外商投资企业批准证书并到登记机关办理公司注销登记。 公司采取新设合并形式的，合并各方公司应到原审批机关缴销外商投资企业批准证书并到登记机关办理公司注销登记；新设立的公司应通过申请人到审批机关领取外商投资企业批准证书并到登记机关办理公司设立登记。 公司采取存续分立形式的，存续的公司应到审批机关办理外商投资企业批准证书变更手续并到登记机关办理公司变更登记；新设立的公司应到审批机关领取外商投资企业批准证书并到登记机关办理公司设立登记。 公司采取解散分立形式的，原公司应到原审批机关缴销外商投资企业批准证书并到登记机关办理公司注销登记；新设立的公司应到审批机关领取外商投资企业批准证书并到登记机关办理公司设立登记。 公司与中国内资企业合并的仅由公司办理有关外商投"},{"i":31,"n":"第三十一条","txt":"公司合并的申请人或拟分立的公司，应自审批机关批准合并或分立之日起三十日内，就因合并或分立而解散、存续或新设公司的事宜，到相应的审批机关办理有关缴销、变更或领取外商投资企业批准证书手续。"},{"i":32,"n":"第三十二条","txt":"公司应自缴销、变更或领取外商投资企业批准证书之日起，依照《中华人民共和国企业法人登记管理条例》和《中华人民共和国公司登记管理条例》等有关规定，到登记机关办理有关注销、变更或设立登记手续。 设立登记应当在有关公司变更、注销登记办理完结后进行。 公司合并或分立协议中载明的有关公司财产处置方案及债权、债务承继方案和审批机关批准公司合并或分立的文件，视为注销登记所需提交的清算报告。"},{"i":33,"n":"第三十三条","txt":"公司为新设合并或分立办理注销、变更登记后，当事人不依法办理有关公司设立登记的，应承担相应的法律责任。"},{"i":34,"n":"第三十四条","txt":"公司投资者因公司合并或分立而签署的修改后的公司合同、章程自审批机关变更或核发外商投资企业批准证书之日起生效。"},{"i":35,"n":"第三十五条","txt":"合并或分立后存续或新设的公司应自变更或领取营业执照之日起三十日内，向因合并或分立而解散的公司之债权人和债务人发出变更债务人和债权人的通知并在全国发行的省级以上报纸上公告。"},{"i":36,"n":"第三十六条","txt":"合并或分立后存续或新设的公司应自换发或领取营业执照之日起三十日内，到税务、海关、土地管理和外汇管理等有关机关办理相应的登记手续。 公司与中国内资企业合并的，存续或新设的公司，还应根据有关外商投资企业的规定，到税务、海关、土地管理和外汇管理等机关，办理相关的审核手续。"},{"i":37,"n":"第三十七条","txt":"在公司合并或分立过程中发生股权转让的，依照有关法律、法规和外商投资企业投资者股权变更的规定办理。 在公司与中国内资企业合并过程中，外国投资者购买内资企业股东股权的，其股权购买金的支付条件，依照《<中外合资经营企业合营各方出资的若干规定>的补充规定》执行。"},{"i":38,"n":"第三十八条","txt":"香港、澳门、台湾地区的投资者在中国其他地区投资举办的公司合并或分立，参照本规定办理。"},{"i":39,"n":"第三十九条","txt":"本规定由外经贸部和国家工商总局负责解释。"},{"i":40,"n":"第四十条","txt":"本规定自发布之日起执行。"}],"waishangtouziqiyetousugongzuobanfa":[{"i":1,"n":"第一条","txt":"为及时有效处理外商投资企业投诉，保护外商投资合法权益，持续优化外商投资环境，根据《中华人民共和国外商投资法》和《中华人民共和国外商投资法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称外商投资企业投诉，是指： （一）外商投资企业、外国投资者（以下统称投诉人）认为行政机关（包括法律、法规授权的具有管理公共事务职能的组织）及其工作人员（以下统称被投诉人）的行政行为侵犯其合法权益，向投诉工作机构申请协调解决的行为； （二）投诉人向投诉工作机构反映投资环境方面存在的问题，建议完善有关政策措施的行为。 前款所称投诉工作机构，是指商务部和县级以上地方人民政府指定的负责受理外商投资企业投诉的部门或者机构。 本办法所称外商投资企业投诉，不包括外商投资企业、外国投资者申请协调解决与其他自然人、法人或者其他组织之间民商事纠纷的行为。"},{"i":3,"n":"第三条","txt":"投诉工作机构应当坚持公平公正合法、分级负责原则，及时处理投诉人反映的问题，协调完善相关政策措施。"},{"i":4,"n":"第四条","txt":"投诉人应当如实反映投诉事实，提供证据，积极协助投诉工作机构开展投诉处理工作。"},{"i":5,"n":"第五条","txt":"商务部会同国务院有关部门建立外商投资企业投诉工作部际联席会议制度（以下简称联席会议），协调、推动中央层面的外商投资企业投诉工作，指导和监督地方的外商投资企业投诉工作。联席会议办公室设在商务部外国投资管理司，承担联席会议的日常工作，指导和监督全国外商投资企业投诉中心的工作。"},{"i":6,"n":"第六条","txt":"商务部负责处理下列投诉事项： （一）涉及国务院有关部门，省、自治区、直辖市人民政府及其工作人员行政行为的； （二）建议国务院有关部门，省、自治区、直辖市人民政府完善相关政策措施的； （三）在全国范围内或者国际上有重大影响，商务部认为可以由其处理的。 商务部设立全国外商投资企业投诉中心（以下简称全国外资投诉中心，暂设在商务部投资促进事务局），负责具体处理前款规定的投诉事项。 全国外资投诉中心组织与外商投资有关的政策法规宣传，开展外商投资企业投诉工作培训，推广投诉事项处理经验，提出相关政策建议，督促地方做好外商投资企业投诉工作，积极预防投诉事项的发生。"},{"i":7,"n":"第七条","txt":"县级以上地方人民政府应当指定部门或者机构（以下简称地方投诉工作机构）负责投诉工作。地方投诉工作机构应当完善投诉工作规则、健全投诉方式、明确投诉事项受理范围和投诉处理时限。 地方投诉工作机构受理投诉人对本地区行政机关及其工作人员行政行为和建议完善本地区相关政策措施的投诉事项。"},{"i":8,"n":"第八条","txt":"投诉人依照本办法规定申请协调解决其与行政机关之间争议的，不影响其在法定时限内提起行政复议、行政诉讼等程序的权利。"},{"i":9,"n":"第九条","txt":"《中华人民共和国外商投资法》第二十七条规定的商会、协会可以参照本办法，向投诉工作机构反映会员提出的投资环境方面存在的问题，并提交具体的政策措施建议。"},{"i":10,"n":"第十条","txt":"投诉人提出投诉事项，应当提交书面投诉材料。投诉材料可以现场提交，也可以通过信函、传真、电子邮件、在线申请等方式提交。 各级投诉工作机构应当公布其地址、电话和传真号码、电子邮箱、网站等信息，便利投诉人提出投诉事项。"},{"i":11,"n":"第十一条","txt":"属于本办法第二条第一款第（一）项规定的投诉的，投诉材料应当包括下列内容： （一）投诉人的姓名或者名称、通讯地址、邮编、有关联系人和联系方式，主体资格证明材料，提出投诉的日期； （二）被投诉人的姓名或者名称、通讯地址、邮编、有关联系人和联系方式； （三）明确的投诉事项和投诉请求； （四）有关事实、证据和理由，如有相关法律依据可以一并提供； （五）是否存在本办法第十四条第（七）、（八）、（九）项所列情形的说明。 属于本办法第二条第一款第（二）项规定的投诉的，投诉材料应当包括前款第（一）项规定的信息、投资环境方面存在的相关问题以及具体政策措施建议。 投诉材料应当用中文书写。有关证据和材料原件以外文书写的，应当提交准确、完整的中文翻译件。"},{"i":12,"n":"第十二条","txt":"投诉人可以委托他人进行投诉。投诉人委托他人进行投诉的，除本办法第十一条规定的材料以外，还应当向投诉工作机构提交投诉人的身份证明、出具的授权委托书和受委托人的身份证明。授权委托书应当载明委托事项、权限和期限。"},{"i":13,"n":"第十三条","txt":"投诉材料不齐全的，投诉工作机构应当在收到投诉材料后7个工作日内一次性书面通知投诉人在15个工作日内补正。补正通知应当载明需要补正的事项和期限。"},{"i":14,"n":"第十四条","txt":"投诉具有以下情形的，投诉工作机构不予受理： （一）投诉主体不属于外商投资企业、外国投资者的； （二）申请协调解决与其他自然人、法人或者其他组织之间民商事纠纷，或者不属于本办法规定的外商投资企业投诉事项范围的； （三）不属于本投诉工作机构的投诉事项处理范围的； （四）经投诉工作机构依据本办法第十三条的规定通知补正后，投诉材料仍不符合本办法第十一条要求的； （五）投诉人伪造、变造证据或者明显缺乏事实依据的； （六）没有新的证据或者法律依据，向同一投诉工作机构重复投诉的； （七）同一投诉事项已经由上级投诉工作机构受理或者处理终结的； （八）同一投诉事项已经由信访等部门受理或者处理终结的； （九）同一投诉事项已经进入或者完成行政复议、行政诉讼等程序的。"},{"i":15,"n":"第十五条","txt":"投诉工作机构接到完整齐备的投诉材料，应当在7个工作日内作出是否受理的决定。 符合投诉受理条件的，应当予以受理并向投诉人发出投诉受理通知书。 不符合投诉受理条件的，投诉工作机构应当于7个工作日内向投诉人发出不予受理通知书并说明不予受理的理由。属于本办法第十四条第一款第（三）项情形的，投诉工作机构可以告知投诉人向有关投诉工作机构提出投诉。"},{"i":16,"n":"第十六条","txt":"投诉工作机构在受理投诉后，应当与投诉人和被投诉人进行充分沟通，了解情况，依法协调处理，推动投诉事项的妥善解决。"},{"i":17,"n":"第十七条","txt":"投诉工作机构进行投诉处理时，可以要求投诉人进一步说明情况、提供材料或者提供其他必要的协助，投诉人应当予以协助；投诉工作机构可以向被投诉人了解情况，被投诉人应当予以配合。 根据投诉事项具体情况，投诉工作机构可以组织召开会议，邀请投诉人和被投诉人共同参加，陈述意见，探讨投诉事项的解决方案。投诉工作机构根据投诉处理工作需要，可以就专业问题听取有关专家意见。"},{"i":18,"n":"第十八条","txt":"根据投诉事项不同情况，投诉工作机构可以采取下列方式进行处理： （一）推动投诉人和被投诉人达成谅解（包括达成和解协议）； （二）与被投诉人进行协调； （三）向县级以上人民政府及其有关部门提交完善相关政策措施的建议； （四）投诉工作机构认为适当的其他处理方式。 投诉人和被投诉人签署和解协议的，应当写明达成和解的事项和结果。依法订立的和解协议对投诉人和被投诉人具有约束力。被投诉人不履行生效和解协议的，依据《中华人民共和国外商投资法实施条例》第四十一条的规定处理。"},{"i":19,"n":"第十九条","txt":"投诉工作机构应当在受理投诉之日起60个工作日内办结受理的投诉事项。涉及部门多、情况复杂的投诉事项，可以适当延长处理期限。"},{"i":20,"n":"第二十条","txt":"有下列情况之一的，投诉处理终结： （一）投诉工作机构依据本办法第十八条进行协调处理，投诉人同意终结的； （二）投诉事项与事实不符的，或者投诉人拒绝提供材料导致无法查明有关事实的； （三）投诉人的有关诉求没有法律依据的； （四）投诉人书面撤回投诉的； （五）投诉人不再符合投诉主体资格的； （六）经投诉工作机构联系，投诉人连续30日无正当理由不参加投诉处理工作的。 投诉处理期间，出现本办法第十四条第（七）、（八）、（九）项所列情形的，视同投诉人书面撤回投诉。 投诉处理终结后，投诉工作机构应当在3个工作日内将投诉处理结果书面通知投诉人。"},{"i":21,"n":"第二十一条","txt":"投诉事项自受理之日起一年未能依据本办法第二十条处理终结的，投诉工作机构应当及时向本级人民政府报告有关情况，提出有关工作建议。"},{"i":22,"n":"第二十二条","txt":"投诉人对地方投诉工作机构作出的不予受理决定或者投诉处理结果有异议的，可以就原投诉事项逐级向上级投诉工作机构提起投诉。上级投诉工作机构可以根据本机构投诉工作规则决定是否受理原投诉事项。"},{"i":23,"n":"第二十三条","txt":"投诉工作机构应当建立健全内部管理制度，依法采取有效措施保护投诉处理过程中知悉的投诉人的商业秘密、保密商务信息和个人隐私。"},{"i":24,"n":"第二十四条","txt":"投诉工作机构应当建立投诉档案管理制度，及时、全面、准确记录有关投诉事项的受理和处理情况，按年度进行归档。"},{"i":25,"n":"第二十五条","txt":"地方投诉工作机构应当每两个月向上一级投诉工作机构上报投诉工作情况，包括收到投诉数量、处理进展情况、已处理完结投诉事项的详细情况和有关政策建议等。 省、自治区、直辖市投诉工作机构应当在单数月前7个工作日内向全国外资投诉中心上报前两个月本地区投诉工作情况，由全国外资投诉中心汇总后提交联席会议办公室。"},{"i":26,"n":"第二十六条","txt":"地方投诉工作机构在处理投诉过程中，发现有关地方或者部门工作中存在普遍性问题，或者有关规范性文件存在违反法律规定或者明显不当的情形的，可以向全国外资投诉中心反映并提出完善政策措施建议，由全国外资投诉中心汇总后提交联席会议办公室。"},{"i":27,"n":"第二十七条","txt":"全国外资投诉中心督促各省、自治区、直辖市投诉工作，建立定期督查制度，向各省、自治区、直辖市人民政府通报投诉工作情况，并视情向社会公示。"},{"i":28,"n":"第二十八条","txt":"全国外资投诉中心应当按年度向联席会议办公室报送外商投资企业权益保护建议书，总结外商投资企业、外国投资者、商会、协会、有关地方和部门反映的典型案例、重大问题、政策措施建议，提出加强投资保护、改善投资环境的相关建议。"},{"i":29,"n":"第二十九条","txt":"投诉工作机构及其工作人员在处理外商投资企业投诉过程中滥用职权、玩忽职守、徇私舞弊的，或者泄露、非法向他人提供投诉处理过程中知悉的商业秘密、保密商务信息和个人隐私的，依据《中华人民共和国外商投资法》第三十九条的规定处理。"},{"i":30,"n":"第三十条","txt":"投诉人通过外商投资投诉工作机制反映或者申请协调解决问题，任何单位和个人不得压制或者打击报复。"},{"i":31,"n":"第三十一条","txt":"香港特别行政区、澳门特别行政区、台湾地区投资者以及定居在国外的中国公民所投资企业投诉工作，参照本办法办理。"},{"i":32,"n":"第三十二条","txt":"本办法由商务部负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2020年10月1日起施行。2006年9月1日商务部第2号令公布的《商务部外商投资企业投诉工作暂行办法》同时废止。"}],"waishangtouziqiyedanganguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为加强外商投资企业（包括中外合资经营企业、中外合作经营企业、外资企业）的档案管理工作，有效地保护和利用档案，维护企业的合法权益，根据《中华人民共和国档案法》和国家有关外商投资企业的法律、法规，特制定本规定。"},{"i":2,"n":"第二条","txt":"外商投资企业档案是指外商投资企业筹建以来的各项活动中形成的对本企业以及对国家、社会具有利用、保存价值的各种文件材料（包括不同载体形式）。"},{"i":3,"n":"第三条","txt":"外商投资企业档案属企业所有，受国家法律保护。企业承担保护档案的义务。"},{"i":4,"n":"第四条","txt":"外商投资企业档案工作是企业管理基础工作的组成部分，是维护企业经济利益、合法权益和历史真实面貌的一项工作，是国家全部档案工作的组成部分。其主要任务是贯彻执行国家档案工作的有关法律、法规，建立健全本企业档案管理规章制度；统一管理本企业的档案，并对本企业所属单位的档案工作进行监督和指导。"},{"i":5,"n":"第五条","txt":"外商投资企业应当加强对其档案工作的领导，把企业档案工作列入企业管理计划，并确定管理档案的部门和人员负责本企业的档案工作。 负责管理档案的人员应有档案专业知识、技能和企业管理知识。 各级政府档案行政管理部门和上级主管部门，有权对本级行政区域内或本系统、本行业的下属外商投资企业的档案工作进行监督和检查，承担有关服务工作。"},{"i":6,"n":"第六条","txt":"外商投资企业文件材料的归档范围主要包括： １．外商投资企业设立和变更的申请、审批、登记以及终止、解散后清算等方面的文件材料（包括外商投资企业的章程及投资各方签订的合资、合作合同）； ２．董事会或联合管理机构形成的文件材料； ３．财务、会计及其管理方面的文件材料； ４．劳动工资、人事、法律事务管理方面的文件材料； ５．经营管理方面的文件材料； ６．生产技术管理方面的文件材料； ７．产品生产方面的文件材料； ８．仪器、设备方面的文件材料； ９．基本建设方面的文件材料； １０．科学技术研究、技术引进、技术转让方面的文件材料； １１．教育培训方面的文件材料； １２．情报信息方面的文件材料； １３．中共党组织和工会组织的文件材料； １４．其它具有利用和保存价值的文件材料。"},{"i":7,"n":"第七条","txt":"外商投资企业各部门形成的文件材料原则上由本部门负责立卷和归档，按本企业的规定，定期向档案部门或指定的部门移交，任何个人不得据为已有。"},{"i":8,"n":"第八条","txt":"外商投资企业所形成的档案参照国家标准、规范和国际先进方法，进行科学分类和整理。"},{"i":9,"n":"第九条","txt":"外商投资企业应当有库房和必要的设施及保护设备保管档案，确保档案的安全。暂不具备档案安全保管条件的企业，可委托主管部门或当地国家档案馆代为保管。档案代管单位必须保障代管档案的安全，做好代管档案的所有者利用档案的各项服务工作。"},{"i":10,"n":"第十条","txt":"外商投资企业应当根据档案的实际价值和国家有关规定，编制档案保管期限表。档案保管期限分永久、长期、短期三种。具有长远查考利用及研究价值的永久保存；在一定时期内有查考利用价值的长期或短期保存；凡是介于两种保管期限之间的档案，其保管期限从长。"},{"i":11,"n":"第十一条","txt":"外商投资企业对保管到期的档案应当进行鉴定。鉴定工作由企业负责人、专业人员和档案人员组成的鉴定小组负责，直接对档案进行鉴定。对失去保存价值的档案列出销毁清单，报经董事会审批后销毁，销毁清单永久保存。其中，会计档案按《中华人民共和国会计法》的有关规定执行。"},{"i":12,"n":"第十二条","txt":"外商投资企业的中外各方都有利用档案的权利，应当建立健全并严格执行档案利用制度，防止失密和泄密。 中国政府有关部门依法执行公务需要查阅企业档案时，企业应予提供。"},{"i":13,"n":"第十三条","txt":"外商投资企业终止、解散后，中外合资经营企业、中外合作经营企业的档案交由原中方合资、合作者妥为保存，或向当地国家档案馆移交。外资企业的档案按以下情况，分别处理： １．外资企业延长期限、分立、合并或其它事项变更的，该企业的档案向变更后的企业移交。 ２．外资企业期满或依法宣告破产的，该企业的档案按第十一条规定执行。 ３．外资企业因违反法律、行政规章被依法责令关闭的，按照有关机关的决定处理。 ４．原企业根据需要可保存有关档案的复制件。"},{"i":14,"n":"第十四条","txt":"有下列行为之一的，根据情节轻重，给予行政处分或处罚；造成损失的，根据档案的价值和数量，责令赔偿；构成犯罪的，应当依法追究当事人的责任： １．损毁、丢失或擅自销毁应当归档保存的文件材料和档案的； ２．涂改、伪造档案的； ３．私自出卖、倒卖档案的； ４．擅自占有和非法携带档案出境的； ５．档案工作人员玩忽职守造成损失的。"},{"i":15,"n":"第十五条","txt":"香港、澳门、台湾地区的公司、企业和其它经济组织或者个人在中国大陆举办的企业比照本规定执行。"},{"i":16,"n":"第十六条","txt":"本规定由国家档案局负责解释。"},{"i":17,"n":"第十七条","txt":"本规定自发布之日起施行。"}],"waishangtouzixinxibaogaobanfa-2":[{"i":1,"n":"第一条","txt":"为进一步扩大对外开放，提升外商投资促进、保护和管理水平，完善外商投资政策措施，改善营商环境，根据《中华人民共和国外商投资法》及《中华人民共和国外商投资法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"外国投资者直接或者间接在中国境内进行投资活动，应由外国投资者或者外商投资企业根据本办法向商务主管部门报送投资信息。"},{"i":3,"n":"第三条","txt":"商务部负责统筹和指导全国范围内外商投资信息报告工作。 县级以上地方人民政府商务主管部门以及自由贸易试验区、国家级经济技术开发区的相关机构负责本区域内外商投资信息报告工作。"},{"i":4,"n":"第四条","txt":"外国投资者或者外商投资企业应当通过企业登记系统以及国家企业信用信息公示系统向商务主管部门报送投资信息。 市场监管部门应当及时将外国投资者、外商投资企业报送的上述投资信息推送至商务主管部门。 商务部建立外商投资信息报告系统，及时接收、处理市场监管部门推送的投资信息以及部门共享信息等。"},{"i":5,"n":"第五条","txt":"市场监管总局统筹指导全国企业登记系统、国家企业信用信息公示系统建设，保障外商投资信息报告的实施。"},{"i":6,"n":"第六条","txt":"各级商务主管部门和市场监管部门应当做好工作衔接。商务主管部门应当为外国投资者和外商投资企业报送投资信息提供专门指导。"},{"i":7,"n":"第七条","txt":"外国投资者或者外商投资企业应当及时报送投资信息，遵循真实、准确、完整原则，不得进行虚假或误导性报告，不得有重大遗漏。"},{"i":8,"n":"第八条","txt":"外国投资者或者外商投资企业应当按照本办法规定通过提交初始报告、变更报告、注销报告、年度报告等方式报送投资信息。"},{"i":9,"n":"第九条","txt":"外国投资者在中国境内设立外商投资企业，应于办理外商投资企业设立登记时通过企业登记系统提交初始报告。 外国投资者股权并购境内非外商投资企业，应在办理被并购企业变更登记时通过企业登记系统提交初始报告。"},{"i":10,"n":"第十条","txt":"外国投资者提交初始报告，应当报送企业基本信息、投资者及其实际控制人信息、投资交易信息等信息。"},{"i":11,"n":"第十一条","txt":"初始报告的信息发生变更，涉及企业变更登记（备案）的，外商投资企业应于办理企业变更登记（备案）时通过企业登记系统提交变更报告。 不涉及企业变更登记（备案）的，外商投资企业应于变更事项发生后20个工作日内通过企业登记系统提交变更报告。企业根据章程对变更事项作出决议的，以作出决议的时间为变更事项的发生时间；法律法规对变更事项的生效条件另有要求的，以满足相应要求的时间为变更事项的发生时间。 外商投资的上市公司及在全国中小企业股份转让系统挂牌的公司，可仅在外国投资者持股比例变化累计超过5%或者引起外方控股、相对控股地位发生变化时，报告投资者及其所持股份变更信息。"},{"i":12,"n":"第十二条","txt":"外商投资企业提交变更报告，应当报送企业基本信息、投资者及其实际控制人信息、投资交易信息等信息的变更情况。"},{"i":13,"n":"第十三条","txt":"外商投资企业注销或者转为内资企业的，在办理企业注销登记或者企业变更登记后视同已提交注销报告，相关信息由市场监管部门推送至商务主管部门，外商投资企业无需另行报送。"},{"i":14,"n":"第十四条","txt":"外商投资企业应于每年1月1日至6月30日通过国家企业信用信息公示系统提交上一年度的年度报告。 当年设立的外商投资企业，自下一年起报送年度报告。"},{"i":15,"n":"第十五条","txt":"外商投资企业提交年度报告，应当报送企业基本信息、投资者及其实际控制人信息、企业经营和资产负债等信息，涉及外商投资准入特别管理措施的，还应当报送获得相关行业许可信息。"},{"i":16,"n":"第十六条","txt":"初始报告、变更报告和年度报告等的具体内容，按照确有必要原则，结合外商投资实际情况和企业登记注册、企业信息公示的有关规定确定，由商务部以公告形式对外发布。"},{"i":17,"n":"第十七条","txt":"商务主管部门与有关部门应当根据信息报告工作需要建立外商投资信息共享机制。 除法律、行政法规另有规定外，有关部门在履行职责过程中获取的外商投资信息，应当及时与商务主管部门共享。"},{"i":18,"n":"第十八条","txt":"外国投资者或者外商投资企业报送的投资信息，根据《企业信息公示暂行条例》应当向社会公示或者外国投资者、外商投资企业同意公示的，将通过国家企业信用信息公示系统及外商投资信息报告系统向社会公示。"},{"i":19,"n":"第十九条","txt":"外国投资者或者外商投资企业发现其存在未报、错报、漏报有关投资信息的，应当及时进行补报或更正。外商投资企业对《企业信息公示暂行条例》第九条所列年度报告公示信息的补报或者更正应当符合该条例有关规定。 商务主管部门发现外国投资者或者外商投资企业存在未报、错报、漏报的，应当通知外国投资者或者外商投资企业于20个工作日内进行补报或更正。 更正涉及公示事项的，更正前后的信息应当同时公示。"},{"i":20,"n":"第二十条","txt":"商务主管部门对外国投资者、外商投资企业遵守本办法情况实施监督检查。 商务主管部门可联合有关部门，采取抽查、根据举报进行检查、根据有关部门或司法机关的建议和反映的情况进行检查，以及依职权启动检查等方式开展监督检查。"},{"i":21,"n":"第二十一条","txt":"商务主管部门采取抽查方式对外国投资者、外商投资企业履行信息报告义务的情况实施监督检查，应当随机抽取检查对象、随机选派执法检查人员，抽查事项及查处结果及时通过外商投资信息报告系统公示平台予以公示。 公民、法人或其他组织发现外国投资者或者外商投资企业存在违反本办法的行为的，可向商务主管部门举报。举报采取书面形式，有明确的被举报人，并提供相关事实和证据的，商务主管部门接到举报后应当依法及时处理。 其他有关部门或司法机关在履行职责的过程中，发现外国投资者或者外商投资企业有违反本办法的行为的，可向商务主管部门提出监督检查的建议，商务主管部门接到相关建议后应当依法及时处理。 对于未按本办法的规定进行报告，或曾有报告不实、对监督检查不予配合、拒不履行商务主管部门作出的行政处罚决定记录的外国投资者或者外商投资企业，商务主管部门可依职权对其启动检查。"},{"i":22,"n":"第二十二条","txt":"商务主管部门可采取实地核查、书面检查等方式进行监督检查，可根据需要从其他部门获取信息用于核实外国投资者或者外商投资企业报送的投资信息是否真实、准确、完整、及时。商务主管部门可依法查阅或者要求被检查人提供有关材料，被检查人应当配合检查，如实提供。"},{"i":23,"n":"第二十三条","txt":"商务主管部门实施监督检查不得妨碍被检查人正常的生产经营活动，不得接受被检查人提供的财物或者服务，不得谋取其他非法利益。"},{"i":24,"n":"第二十四条","txt":"商务主管部门、市场监管部门应当依法保护履行职责过程中知悉的外国投资者、外商投资企业的商业秘密。"},{"i":25,"n":"第二十五条","txt":"外国投资者或者外商投资企业未按照本办法要求报送投资信息，且在商务主管部门通知后未按照本办法第十九条予以补报或更正的，由商务主管部门责令其于20个工作日内改正；逾期不改正的，处十万元以上三十万元以下罚款；逾期不改正且存在以下情形的，处三十万元以上五十万元以下罚款： （一）外国投资者或者外商投资企业故意逃避履行信息报告义务，或在进行信息报告时隐瞒真实情况、提供误导性或虚假信息； （二）外国投资者或者外商投资企业就所属行业、是否涉及外商投资准入特别管理措施、企业投资者及其实际控制人等重要信息报送错误； （三）外国投资者或者外商投资企业未按照本办法要求报送投资信息，并因此受到行政处罚的，两年内再次违反本办法有关要求； （四）商务主管部门认定的其他严重情形。"},{"i":26,"n":"第二十六条","txt":"商务主管部门在监督检查中掌握的外国投资者、外商投资企业未依法履行信息报告义务的有关情况，应当记入外商投资信息报告系统，并按照国家关于信用体系建设的有关规定完善信用监管。 外国投资者、外商投资企业因违反信息报告义务受到商务主管部门行政处罚的，商务主管部门可将相关情况在外商投资信息报告系统公示平台上予以公示，并按照国家有关规定纳入信用信息系统。 商务主管部门可与市场监管、外汇、海关、税务等有关部门共享外国投资者、外商投资企业履行信息报告义务以及受到相应行政处罚的有关情况。"},{"i":27,"n":"第二十七条","txt":"外国投资者或者外商投资企业认为外商投资信息报告系统公示平台上有关信息记录不完整或者有错误的，可提供相关证明材料并向商务主管部门申请修正。经核查属实的，予以修正。 外国投资者或者外商投资企业改正违法行为、履行相关义务后1年内未再发生违反信息报告义务行为的，可向商务主管部门申请移除外商投资信息报告系统公示平台上有关信息记录。经核查属实的，予以移除。"},{"i":28,"n":"第二十八条","txt":"外商投资企业在中国境内投资（含多层次投资）设立企业的，在向市场监管部门办理登记备案、报送年报信息后，相关信息由市场监管部门推送至商务主管部门，上述企业无需另行报送。"},{"i":29,"n":"第二十九条","txt":"外商投资举办的投资性公司、创业投资企业和以投资为主要业务的合伙企业在境内投资设立企业的，应当参照本办法第二章的规定报送投资信息。"},{"i":30,"n":"第三十条","txt":"非企业形式的外商投资，应由外国投资者参照本办法第二章的规定报送投资信息，但通过部门信息共享可以获得相关信息的除外。"},{"i":31,"n":"第三十一条","txt":"法律、行政法规规定企业设立、变更、注销登记前须行业主管部门许可的，外国投资者或者外商投资企业应当在申请登记注册时向市场监管部门提交有关批准文件。"},{"i":32,"n":"第三十二条","txt":"外国投资者在中国境内投资银行业、证券业、保险业等金融行业，适用本办法。"},{"i":33,"n":"第三十三条","txt":"香港特别行政区、澳门特别行政区、台湾地区投资者以及定居在国外的中国公民的投资，参照本办法报送投资信息。"},{"i":34,"n":"第三十四条","txt":"本办法由商务部、市场监管总局负责解释。"},{"i":35,"n":"第三十五条","txt":"本办法自2020年1月1日起实施。《外商投资企业设立及变更备案管理暂行办法》同时废止。"}],"waishangtouzixinxibaogaobanfa":[{"i":1,"n":"第一条","txt":"为进一步扩大对外开放，提升外商投资促进、保护和管理水平，完善外商投资政策措施，改善营商环境，根据《中华人民共和国外商投资法》及《中华人民共和国外商投资法实施条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"外国投资者直接或者间接在中国境内进行投资活动，应由外国投资者或者外商投资企业根据本办法向商务主管部门报送投资信息。"},{"i":3,"n":"第三条","txt":"商务部负责统筹和指导全国范围内外商投资信息报告工作。 县级以上地方人民政府商务主管部门以及自由贸易试验区、国家级经济技术开发区的相关机构负责本区域内外商投资信息报告工作。"},{"i":4,"n":"第四条","txt":"外国投资者或者外商投资企业应当通过企业登记系统以及国家企业信用信息公示系统向商务主管部门报送投资信息。 市场监管部门应当及时将外国投资者、外商投资企业报送的上述投资信息推送至商务主管部门。 商务部建立外商投资信息报告系统，及时接收、处理市场监管部门推送的投资信息以及部门共享信息等。"},{"i":5,"n":"第五条","txt":"市场监管总局统筹指导全国企业登记系统、国家企业信用信息公示系统建设，保障外商投资信息报告的实施。"},{"i":6,"n":"第六条","txt":"各级商务主管部门和市场监管部门应当做好工作衔接。商务主管部门应当为外国投资者和外商投资企业报送投资信息提供专门指导。"},{"i":7,"n":"第七条","txt":"外国投资者或者外商投资企业应当及时报送投资信息，遵循真实、准确、完整原则，不得进行虚假或误导性报告，不得有重大遗漏。"},{"i":8,"n":"第八条","txt":"外国投资者或者外商投资企业应当按照本办法规定通过提交初始报告、变更报告、注销报告、年度报告等方式报送投资信息。"},{"i":9,"n":"第九条","txt":"外国投资者在中国境内设立外商投资企业，应于办理外商投资企业设立登记时通过企业登记系统提交初始报告。 外国投资者股权并购境内非外商投资企业，应在办理被并购企业变更登记时通过企业登记系统提交初始报告。"},{"i":10,"n":"第十条","txt":"外国投资者提交初始报告，应当报送企业基本信息、投资者及其实际控制人信息、投资交易信息等信息。"},{"i":11,"n":"第十一条","txt":"初始报告的信息发生变更，涉及企业变更登记（备案）的，外商投资企业应于办理企业变更登记（备案）时通过企业登记系统提交变更报告。 不涉及企业变更登记（备案）的，外商投资企业应于变更事项发生后20个工作日内通过企业登记系统提交变更报告。企业根据章程对变更事项作出决议的，以作出决议的时间为变更事项的发生时间；法律法规对变更事项的生效条件另有要求的，以满足相应要求的时间为变更事项的发生时间。 外商投资的上市公司及在全国中小企业股份转让系统挂牌的公司，可仅在外国投资者持股比例变化累计超过5%或者引起外方控股、相对控股地位发生变化时，报告投资者及其所持股份变更信息。"},{"i":12,"n":"第十二条","txt":"外商投资企业提交变更报告，应当报送企业基本信息、投资者及其实际控制人信息、投资交易信息等信息的变更情况。"},{"i":13,"n":"第十三条","txt":"外商投资企业注销或者转为内资企业的，在办理企业注销登记或者企业变更登记后视同已提交注销报告，相关信息由市场监管部门推送至商务主管部门，外商投资企业无需另行报送。"},{"i":14,"n":"第十四条","txt":"外商投资企业应于每年1月1日至6月30日通过国家企业信用信息公示系统提交上一年度的年度报告。 当年设立的外商投资企业，自下一年起报送年度报告。"},{"i":15,"n":"第十五条","txt":"外商投资企业提交年度报告，应当报送企业基本信息、投资者及其实际控制人信息、企业经营和资产负债等信息，涉及外商投资准入特别管理措施的，还应当报送获得相关行业许可信息。"},{"i":16,"n":"第十六条","txt":"初始报告、变更报告和年度报告等的具体内容，按照确有必要原则，结合外商投资实际情况和企业登记注册、企业信息公示的有关规定确定，由商务部以公告形式对外发布。"},{"i":17,"n":"第十七条","txt":"商务主管部门与有关部门应当根据信息报告工作需要建立外商投资信息共享机制。 除法律、行政法规另有规定外，有关部门在履行职责过程中获取的外商投资信息，应当及时与商务主管部门共享。"},{"i":18,"n":"第十八条","txt":"外国投资者或者外商投资企业报送的投资信息，根据《企业信息公示暂行条例》应当向社会公示或者外国投资者、外商投资企业同意公示的，将通过国家企业信用信息公示系统及外商投资信息报告系统向社会公示。"},{"i":19,"n":"第十九条","txt":"外国投资者或者外商投资企业发现其存在未报、错报、漏报有关投资信息的，应当及时进行补报或更正。外商投资企业对《企业信息公示暂行条例》第九条所列年度报告公示信息的补报或者更正应当符合该条例有关规定。 商务主管部门发现外国投资者或者外商投资企业存在未报、错报、漏报的，应当通知外国投资者或者外商投资企业于20个工作日内进行补报或更正。 更正涉及公示事项的，更正前后的信息应当同时公示。"},{"i":20,"n":"第二十条","txt":"商务主管部门对外国投资者、外商投资企业遵守本办法情况实施监督检查。 商务主管部门可联合有关部门，采取抽查、根据举报进行检查、根据有关部门或司法机关的建议和反映的情况进行检查，以及依职权启动检查等方式开展监督检查。"},{"i":21,"n":"第二十一条","txt":"商务主管部门采取抽查方式对外国投资者、外商投资企业履行信息报告义务的情况实施监督检查，应当随机抽取检查对象、随机选派执法检查人员，抽查事项及查处结果及时通过外商投资信息报告系统公示平台予以公示。 公民、法人或其他组织发现外国投资者或者外商投资企业存在违反本办法的行为的，可向商务主管部门举报。举报采取书面形式，有明确的被举报人，并提供相关事实和证据的，商务主管部门接到举报后应当依法及时处理。 其他有关部门或司法机关在履行职责的过程中，发现外国投资者或者外商投资企业有违反本办法的行为的，可向商务主管部门提出监督检查的建议，商务主管部门接到相关建议后应当依法及时处理。 对于未按本办法的规定进行报告，或曾有报告不实、对监督检查不予配合、拒不履行商务主管部门作出的行政处罚决定记录的外国投资者或者外商投资企业，商务主管部门可依职权对其启动检查。"},{"i":22,"n":"第二十二条","txt":"商务主管部门可采取实地核查、书面检查等方式进行监督检查，可根据需要从其他部门获取信息用于核实外国投资者或者外商投资企业报送的投资信息是否真实、准确、完整、及时。商务主管部门可依法查阅或者要求被检查人提供有关材料，被检查人应当配合检查，如实提供。"},{"i":23,"n":"第二十三条","txt":"商务主管部门实施监督检查不得妨碍被检查人正常的生产经营活动，不得接受被检查人提供的财物或者服务，不得谋取其他非法利益。"},{"i":24,"n":"第二十四条","txt":"商务主管部门、市场监管部门应当依法保护履行职责过程中知悉的外国投资者、外商投资企业的商业秘密。"},{"i":25,"n":"第二十五条","txt":"外国投资者或者外商投资企业未按照本办法要求报送投资信息，且在商务主管部门通知后未按照本办法第十九条予以补报或更正的，由商务主管部门责令其于20个工作日内改正；逾期不改正的，处十万元以上三十万元以下罚款；逾期不改正且存在以下情形的，处三十万元以上五十万元以下罚款： （一）外国投资者或者外商投资企业故意逃避履行信息报告义务，或在进行信息报告时隐瞒真实情况、提供误导性或虚假信息； （二）外国投资者或者外商投资企业就所属行业、是否涉及外商投资准入特别管理措施、企业投资者及其实际控制人等重要信息报送错误； （三）外国投资者或者外商投资企业未按照本办法要求报送投资信息，并因此受到行政处罚的，两年内再次违反本办法有关要求； （四）商务主管部门认定的其他严重情形。"},{"i":26,"n":"第二十六条","txt":"商务主管部门在监督检查中掌握的外国投资者、外商投资企业未依法履行信息报告义务的有关情况，应当记入外商投资信息报告系统，并按照国家关于信用体系建设的有关规定完善信用监管。 外国投资者、外商投资企业因违反信息报告义务受到商务主管部门行政处罚的，商务主管部门可将相关情况在外商投资信息报告系统公示平台上予以公示，并按照国家有关规定纳入信用信息系统。 商务主管部门可与市场监管、外汇、海关、税务等有关部门共享外国投资者、外商投资企业履行信息报告义务以及受到相应行政处罚的有关情况。"},{"i":27,"n":"第二十七条","txt":"外国投资者或者外商投资企业认为外商投资信息报告系统公示平台上有关信息记录不完整或者有错误的，可提供相关证明材料并向商务主管部门申请修正。经核查属实的，予以修正。 外国投资者或者外商投资企业改正违法行为、履行相关义务后1年内未再发生违反信息报告义务行为的，可向商务主管部门申请移除外商投资信息报告系统公示平台上有关信息记录。经核查属实的，予以移除。"},{"i":28,"n":"第二十八条","txt":"外商投资企业在中国境内投资（含多层次投资）设立企业的，在向市场监管部门办理登记备案、报送年报信息后，相关信息由市场监管部门推送至商务主管部门，上述企业无需另行报送。"},{"i":29,"n":"第二十九条","txt":"外商投资举办的投资性公司、创业投资企业和以投资为主要业务的合伙企业在境内投资设立企业的，应当参照本办法第二章的规定报送投资信息。"},{"i":30,"n":"第三十条","txt":"非企业形式的外商投资，应由外国投资者参照本办法第二章的规定报送投资信息，但通过部门信息共享可以获得相关信息的除外。"},{"i":31,"n":"第三十一条","txt":"法律、行政法规规定企业设立、变更、注销登记前须行业主管部门许可的，外国投资者或者外商投资企业应当在申请登记注册时向市场监管部门提交有关批准文件。"},{"i":32,"n":"第三十二条","txt":"外国投资者在中国境内投资银行业、证券业、保险业等金融行业，适用本办法。"},{"i":33,"n":"第三十三条","txt":"香港特别行政区、澳门特别行政区、台湾地区投资者以及定居在国外的中国公民的投资，参照本办法报送投资信息。"},{"i":34,"n":"第三十四条","txt":"本办法由商务部、市场监管总局负责解释。"},{"i":35,"n":"第三十五条","txt":"本办法自2020年1月1日起实施。《外商投资企业设立及变更备案管理暂行办法》同时废止。"}],"waishangtouzichuangyetouziqiyeguanliguiding-2":[{"i":1,"n":"第一条","txt":"为鼓励外国公司、企业和其他经济组织或个人（以下简称外国投资者）来华从事创业投资，建立和完善中国的创业投资机制，根据《中华人民共和国中外合作经营企业法》、《中华人民共和国中外合资经营企业法》、《中华人民共和国外资企业法》、《公司法》及其他相关的法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外商投资创业投资企业（以下简称创投企业）是指外国投资者或外国投资者与根据中国法律注册成立的公司、企业或其他经济组织（以下简称中国投资者），根据本规定在中国境内设立的以创业投资为经营活动的外商投资企业。"},{"i":3,"n":"第三条","txt":"本规定所称创业投资是指主要向未上市高新技术企业（以下简称所投资企业）进行股权投资，并为之提供创业管理服务，以期获取资本增值收益的投资方式。"},{"i":4,"n":"第四条","txt":"创投企业可以采取非法人制组织形式，也可以采取公司制组织形式。 采取非法人制组织形式的创投企业（以下简称非法人制创投企业）的投资者对创投企业的债务承担连带责任。非法人制创投企业的投资者也可以在创投企业合同中约定在非法人制创投企业资产不足以清偿该债务时由第七条所述的必备投资者承担连带责任，其他投资者以其认缴的出资额为限承担责任。 采用公司制组织形式的创投企业（以下简称公司制创投企业）的投资者以其各自认缴的出资额为限对创投企业承担责任。"},{"i":5,"n":"第五条","txt":"创投企业应遵守中国有关法律法规，符合外商投资产业政策，不得损害中国的社会公共利益。创投企业在中国境内的正当经营活动及合法权益受中国法律的保护。"},{"i":6,"n":"第六条","txt":"设立创投企业应具备下列条件： （一）投资者人数在2人以上50以下；且应至少拥有一个第七条所述的必备投资者； （二）外国投资者以可自由兑换的货币出资，中国投资者以人民币出资； （三）有明确的组织形式； （四）有明确合法的投资方向； （五）除了将本企业经营活动授予一家创业投资管理公司进行管理的情形外，创投企业应有三名以上具备创业投资从业经验的专业人员； （六）法律、行政法规规定的其他条件。"},{"i":7,"n":"第七条","txt":"必备投资者应当具备下列条件： （一）以创业投资为主营业务； （二）在申请前三年其管理的资本累计不低于1亿美元，且其中至少5000万美元已经用于进行创业投资。在必备投资者为中国投资者的情形下，本款业绩要求为：在申请前三年其管理的资本累计不低于1亿元人民币，且其中至少5000万元人民币已经用于进行创业投资）； （三）拥有3名以上具有3年以上创业投资从业经验的专业管理人员； （四）如果某一投资者的关联实体满足上述条件，则该投资者可以申请成为必备投资者。本款所称关联实体是指该投资者控制的某一实体、或控制该投资者的某一实体、或与该投资者共同受控于某一实体的另一实体。本款所称控制是指控制方拥有被控制方超过50%的表决权； （五）必备投资者及其上述关联实体均应未被所在国司法机关和其他相关监管机构禁止从事创业投资或投资咨询业务或以欺诈等原因进行处罚； （六）非法人制创投企业的必备投资者，对创投企业的认"},{"i":8,"n":"第八条","txt":"设立创投企业按以下程序办理： （一）投资者须向拟设立创投企业所在地省级外经贸主管部门报送设立申请书及有关文件。 （二）省级外经贸主管部门应在收到全部上报材料后15天内完成初审并上报对外贸易经济合作部（以下简称审批机构）。 （三）审批机构在收到全部上报材料之日起45天内，经商科学技术部同意后，做出批准或不批准的书面决定。予以批准的，发给《外商投资企业批准证书》。 （四）获得批准设立的创投企业应自收到审批机构颁发的《外商投资企业批准证书》之日起一个月内，持此证书向国家工商行政管理部门或所在地具有外商投资企业登记管理权的省级工商行政管理部门（以下简称登记机关）申请办理注册登记手续。"},{"i":9,"n":"第九条","txt":"申请设立创投企业应当向审批机构报送以下文件： （一）必备投资者签署的设立申请书； （二）投资各方签署的创投企业合同及章程； （三）必备投资者书面声明（声明内容包括：投资者符合第七条规定的资格条件；所有提供的材料真实性；投资者将严格遵循本规定及中国其他有关法律法规的要求）； （四）律师事务所出具的对必备投资者合法存在及其上述声明已获得有效授权和签署的法律意见书； （五）必备投资者的创业投资业务说明、申请前三年其管理资本的说明、其已投资资本的说明，及其拥有的创业投资专业管理人员简历； （六）投资者的注册登记证明（复印件）、法定代表人证明（复印件）； （七）名称登记机关出具的创投企业名称预先核准通知书； （八）如果必备投资者的资格条件是依据第七条第（四）款的规定，则还应报送其符合条件的关联实体的相关材料； （九）审批机构要求的其他与申请设立有关的文件。"},{"i":10,"n":"第十条","txt":"创投企业应当在名称中加注创业投资字样。除创投企业外，其他外商投资企业不得在名称中使用创业投资字样。"},{"i":11,"n":"第十一条","txt":"申请设立创投企业应当向登记机关报送下列文件,并对其真实性、有效性负责： （一）创投企业董事长或联合管理委员会负责人签署的设立登记申请书； （二）合同、章程以及审批机构的批准文件和批准证书； （三）投资者的合法开业证明或身份证明； （四）投资者的资信证明； （五）法定代表人的任职文件、身份证明和企业董事、经理等人员的备案文件； （六）企业名称预先核准通知书； （七）企业住所或营业场所证明。 申请设立非法人制创投企业，还应当提交境外必备投资者的章程或合伙协议。企业投资者中含本规定第七条第四款规定的投资者的，还应当提交关联实体为其出具的承担出资连带责任的担保函。 以上文件应使用中文。使用外文的，应提供规范的中文译本。 创投企业登记事项变更应依法向原登记机关申请办理变更登记。"},{"i":12,"n":"第十二条","txt":"经登记机关核准的公司制创投企业，领取《企业法人营业执照》；经登记机关核准的非法人制创投企业，领取《营业执照》。 《营业执照》应载明非法人制创投企业投资者认缴的出资总额和必备投资者名称。"},{"i":13,"n":"第十三条","txt":"非法人制创投企业的投资者的出资及相关变更应符合如下规定： （一）投资者可以根据创业投资进度分期向创投企业注入认缴出资。各期投入资本额由创投企业根据创投企业合同及其与所投资企业签定的协议自主制定。投资者应在创投企业合同中约定投资者不如期出资的责任和相关措施； （二）必备投资者在创投企业存续期内不得从创投企业撤出。特殊情况下确需撤出的，应获得占总出资额超过50%的其他投资者同意，并应将其权益转让给符合第七条要求的新投资者，且应当相应修改创投企业的合同和章程，并报审批机构批准。 其他投资者如转让其认缴资本额或已投入资本额，须按创投企业合同的约定进行，且受让人应符合本规定第六条的有关要求。投资各方应相应修改创投企业合同和章程，并报审批机构备案。 （三）创投企业设立后，如果有新的投资者申请加入，须符合本规定和创投企业合同的约定，经必备投资者同意，相应修改创投企业合同和章程，并报审批机构备案。 （"},{"i":14,"n":"第十四条","txt":"非法人制创投企业向登记机关申请变更登记时，上述规定中审批机关出具的相关备案证明可替代相应的审批文件。"},{"i":15,"n":"第十五条","txt":"非法人制创投企业投资者根据创业投资进度缴付出资后，应持相关验资报告向原登记机关申请办理出资备案手续。登记机关根据其实际出资状况在其《营业执照》出资额栏目后加注实缴出资额数目。 非法人制创投企业超过最长投资期限仍未缴付或缴清出资的，登记机关根据现行规定予以处罚。"},{"i":16,"n":"第十六条","txt":"公司制创投企业投资者的出资及相关变更按现行规定办理。"},{"i":17,"n":"第十七条","txt":"非法人制创投企业设联合管理委员会。公司制创投企业设董事会。联合管理委员会或董事会的组成由投资者在创投企业合同及章程中予以约定。联合管理委员会或董事会代表投资者管理创投企业。"},{"i":18,"n":"第十八条","txt":"联合管理委员会或董事会下设经营管理机构，根据创投企业的合同及章程中规定的权限，负责日常经营管理工作，执行联合管理委员会或董事会的投资决策。"},{"i":19,"n":"第十九条","txt":"经营管理机构的负责人应当符合下列条件： （一）具有完全的民事行为能力； （二）无犯罪记录； （三）无不良经营记录； （四）应具有创业投资业的从业经验，且无违规操作记录； （五）审批机构要求的与经营管理资格有关的其他条件。"},{"i":20,"n":"第二十条","txt":"经营管理机构应定期向联合管理委员会或董事会报告以下事项： （一）经授权的重大投资活动； （二）中期、年度业绩报告和财务报告； （三）法律、法规规定的其他事项； （四）创投企业合同及章程中规定的有关事项。"},{"i":21,"n":"第二十一条","txt":"联合管理委员会或董事会可以不设立经营管理机构，而将该创投企业的日常经营权授予一家创业投资管理企业或另一家创投企业进行管理。该创业投资管理企业可以是内资创业投资管理企业，也可以是外商投资创业投资管理企业，或境外创业投资管理企业。在此情形下，该创投企业与该创业投资管理企业应签订管理合同，约定创投企业和创业投资管理企业的权利义务。该管理合同应经全体投资者同意并报审批机构批准后方可生效。"},{"i":22,"n":"第二十二条","txt":"创投企业的投资者可以在创业投资合同中依据国际惯例约定内部收益分配机制和奖励机制。"},{"i":23,"n":"第二十三条","txt":"受托管理创投企业的创业投资管理企业应具备下列条件： （一）以受托管理创投企业的投资业务为主营业务； （二）拥有三名以上具有三年以上创业投资从业经验的专业管理人员； （三）有完善的内部控制制度。"},{"i":24,"n":"第二十四条","txt":"创业投资管理企业可以采取公司制组织形式，也可以采取合伙制组织形式。"},{"i":25,"n":"第二十五条","txt":"同一创业投资管理企业可以受托管理不同的创投企业。"},{"i":26,"n":"第二十六条","txt":"创业投资管理企业应定期向委托方的联合管理委员会或董事会报告第二十条所列事项。"},{"i":27,"n":"第二十七条","txt":"设立外商投资创业投资管理企业应符合本规定第二十三条的条件，经拟设立外商投资创业投资管理公司所在地省级外经贸主管部门报审批机构批准。审批机构在收到全部上报材料之日起45天内，做出批准或不批准的书面决定。予以批准的，发给《外商投资企业批准证书》。获得批准设立的外商投资创业投资管理企业应自收到审批机构颁发的《外商投资企业批准证书》之日起一个月内，持此证书向登记机关申请办理注册登记手续。"},{"i":28,"n":"第二十八条","txt":"申请设立外商投资创业投资管理公司应当向审批机构报送以下文件： （一）设立申请书； （二）外商投资创业投资管理公司合同及章程； （三）投资者的注册登记证明（复印件）、法定代表人证明（复印件）； （四）审批机构要求的其他与申请设立有关的文件。"},{"i":29,"n":"第二十九条","txt":"外商投资创业投资管理企业名称应当加注创业投资管理字样。除外商投资创业投资管理企业外，其他外商投资企业不得在名称中使用创业投资管理字样。"},{"i":30,"n":"第三十条","txt":"获得批准接受创投企业委托在华从事创业投资管理业务的境外创业投资管理企业，应当自管理合同获得批准之日起30日内，向登记机关申请办理营业登记手续。 申请营业登记应报送下列文件，并对其真实性、有效性负责： （一）境外创业投资管理企业董事长或有权签字人签署的登记申请书； （二）经营管理合同及审批机构的批准文件； （三）境外创业投资管理企业的章程或合伙协议； （四）境外创业投资管理企业的合法开业证明； （五）境外创业投资管理企业的资信证明； （六）境外创业投资管理企业委派的中国项目负责人的授权书、简历及身份证明； （七）境外创业投资管理企业在华营业场所证明。 以上文件应使用中文。使用外文的，应提供规范的中文译本。"},{"i":31,"n":"第三十一条","txt":"创投企业可以经营以下业务： （一）以全部自有资金进行股权投资，具体投资方式包括新设企业、向已设立企业投资、接受已设立企业投资者股权转让以及国家法律法规允许的其他方式； （二）提供创业投资咨询； （三）为所投资企业提供管理咨询； （四）审批机构批准的其他业务。 创投企业资金应主要用于向所投资企业进行股权投资。"},{"i":32,"n":"第三十二条","txt":"创投企业不得从事下列活动： （一）在国家禁止外商投资的领域投资； （二）直接或间接投资于上市交易的股票和企业债券，但所投资企业上市后，创投企业所持股份不在此列； （三）直接或间接投资于非自用不动产； （四）贷款进行投资； （五）挪用非自有资金进行投资； （六）向他人提供贷款或担保，但创投企业对所投资企业1年以上的企业债券和可以转换为所投资企业股权的债券性质的投资不在此列（本款规定并不涉及所投资企业能否发行该等债券）； （七）法律、法规以及创投企业合同禁止从事的其他事项。"},{"i":33,"n":"第三十三条","txt":"投资者应在创投企业合同中约定对外投资期限。"},{"i":34,"n":"第三十四条","txt":"创投企业主要从出售或以其他方式处置其在所投资企业的股权获得收益。创投企业出售或以其他方式处置其在所投资企业的股权时，可以依法选择适用的退出机制，包括： （一）将其持有的所投资企业的部分股权或全部股权转让给其他投资者； （二）与所投资企业签订股权回购协议，由所投资企业在一定条件下依法回购其所持有的股权； （三）所投资企业在符合法律、行政法规规定的上市条件时可以申请到境内外证券市场上市。创投企业可以依法通过证券市场转让其拥有的所投资企业的股份； （四）中国法律、行政法规允许的其他方式。 所投资企业向创投企业回购该创投企业所持股权的具体办法由审批机构会同登记机关另行制订。"},{"i":35,"n":"第三十五条","txt":"创投企业应当依照国家税法的规定依法申报纳税。对非法人制创投企业，可以由投资各方依照国家税法的有关规定，分别申报缴纳企业所得税；也可以由非法人制创投企业提出申请，经批准后，依照税法规定统一计算缴纳企业所得税。 非法人制创投企业企业所得税的具体征收管理办法由国家税务总局另行颁布。"},{"i":36,"n":"第三十六条","txt":"创投企业中属于外国投资者的利润等收益汇出境外的，应当凭管理委员会或董事会的分配决议，由会计师事务所出具的审计报告、外方投资者投资资金流入证明和验资报告、完税证明和税务申报单（享受减免税优惠的，应提供税务部门出具的减免税证明文件），从其外汇帐户中支付或者到外汇指定银行购汇汇出。 外国投资者回收的对创投企业的出资可依法申购外汇汇出。公司制创投企业开立和使用外汇帐户、资本变动及其他外汇收支事项，按照现行外汇管理规定办理。非法人制创投企业外汇管理规定由国家外汇管理局另行制定。"},{"i":37,"n":"第三十七条","txt":"投资者应在合同、章程中约定创投企业的经营期限，一般不得超过12年。经营期满，经审批机构批准，可以延期。 经审批机构批准，创投企业可以提前解散，终止合同和章程。但是，如果非法人制创投企业的所有投资均已被出售或通过其他方式变卖，其债务亦已全部清偿，且其剩余财产均已被分配给投资者，则毋需上述批准即可进入解散和终止程序，但该非法人制创业投资企业应在该等解散生效前至少30天内向审批机构提交一份书面备案说明。 创投企业解散，应按有关规定进行清算。"},{"i":38,"n":"第三十八条","txt":"创投企业应当自清算结束之日起30日内向原登记机关申请注销登记。 申请注销登记，应当提交下列文件，并对其真实性、有效性负责： （一）董事长或联合管理委员会负责人或清算组织负责人签署的注销登记申请书； （二）董事会或联合管理委员会的决议； （三）清算报告； （四）税务机关、海关出具的注销登记证明； （五）审批机构的批准文件或备案文件； （六）法律、行政法规规定应当提交的其他文件。 经登记机关核准注销登记，创投企业终止。 非法人制创投企业必备投资者承担的连带责任不因非法人制创投企业的终止而豁免。"},{"i":39,"n":"第三十九条","txt":"创投企业境内投资比照执行《指导外商投资方向规定》和《外商投资产业指导目录》的规定。"},{"i":40,"n":"第四十条","txt":"创投企业投资于任何鼓励类和允许类的所投资企业，应向所投资企业当地授权的外经贸部门备案。当地授权的外经贸部门应在收到备案材料后15天内完成备案审核手续并向所投资企业颁发外商投资企业批准证书。所投资企业持外商投资企业批准证书向登记机关申请办理注册登记手续。登记机关依照有关法律和行政法规规定决定准予登记或不予登记。准予登记的，颁发外商投资企业法人营业执照。"},{"i":41,"n":"第四十一条","txt":"创投企业投资于限制类的所投资企业，应向所投资企业所在地省级外经贸主管部门提出申请，并提供下列材料： （一）创投企业关于投资资金充足的声明； （二）创投企业的批准证书和营业执照（复印件）； （三）创投企业（与所投资企业其他投资者）签定的所投资企业合同与章程。 省级外经贸主管部门接到上述申请之日起45日内作出同意或不同意的书面批复。作出同意批复的，颁发外商投资企业批准证书。所投资企业持该批复文件和外商投资企业批准证书向登记机关申请登记。登记机关依照有关法律和行政法规规定决定准予登记或不予登记。准予登记的，颁发外商投资企业法人营业执照。"},{"i":42,"n":"第四十二条","txt":"创投企业投资属于服务贸易领域逐步开放的外商投资项目，按国家有关规定审批。"},{"i":43,"n":"第四十三条","txt":"创投企业增加或转让其在所投资企业投资等行为，按照第四十条、第四十一条和第四十二条规定的程序办理。"},{"i":44,"n":"第四十四条","txt":"创投企业应在履行完第四十条、第四十一条、第四十二条和第四十三条规定的程序之日起一个月内向审批机构备案。"},{"i":45,"n":"第四十五条","txt":"创投企业还应在每年3月份将上一年度的资金筹集和使用情况报审批机构备案。 审批机构在接到该备案材料起5个工作日内应出具备案登记证明。凡未按上述规定备案的，审批机构将商国务院有关部门后予以相应处罚。"},{"i":46,"n":"第四十六条","txt":"创投企业的所投资企业注册资本中，如果创投企业投资的比例中外国投资者的实际出资比例或与其他外国投资者联合投资的比例总和不低于25%，则该所投资企业将享受外商投资企业有关优惠待遇；如果创投企业投资的比例中外国投资者的实际出资比例或与其他外国投资者联合投资的比例总和低于该所投资企业注册资本的25%，则该所投资企业将不享受外商投资企业有关优惠待遇。"},{"i":47,"n":"第四十七条","txt":"已成立的含有境内自然人投资者的内资企业在接受创业投资企业投资变更为外商投资企业后，可以继续保留其原有境内自然人投资者的股东地位。"},{"i":48,"n":"第四十八条","txt":"创投企业经营管理机构的负责人和创业投资管理企业的负责人如有违法操作行为，除依法追究责任外，情节严重的，不得继续从事创业投资及相关的投资管理活动。"},{"i":49,"n":"第四十九条","txt":"香港特别行政区、澳门特别行政区、台湾地区的投资者在大陆投资设立创投企业，参照本规定执行。"},{"i":50,"n":"第五十条","txt":"本规定由对外贸易经济合作部、科学技术部、国家工商行政管理总局、国家税务总局和国家外汇管理局负责解释。"},{"i":51,"n":"第五十一条","txt":"本规定自二OO三年三月一日起施行。对外贸易经济合作部、科学技术部和国家工商行政管理总局于二OO一年八月二十八日发布的《关于设立外商投资创业投资企业的暂行规定》同日废止。"}],"waishangtouzichuangyetouziqiyeguanliguiding":[{"i":1,"n":"第一条","txt":"为鼓励外国公司、企业和其他经济组织或个人（以下简称外国投资者）来华从事创业投资，建立和完善中国的创业投资机制，根据《中华人民共和国中外合作经营企业法》、《中华人民共和国中外合资经营企业法》、《中华人民共和国外资企业法》、《公司法》及其他相关的法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称外商投资创业投资企业（以下简称创投企业）是指外国投资者或外国投资者与根据中国法律注册成立的公司、企业或其他经济组织（以下简称中国投资者），根据本规定在中国境内设立的以创业投资为经营活动的外商投资企业。"},{"i":3,"n":"第三条","txt":"本规定所称创业投资是指主要向未上市高新技术企业（以下简称所投资企业）进行股权投资，并为之提供创业管理服务，以期获取资本增值收益的投资方式。"},{"i":4,"n":"第四条","txt":"创投企业可以采取非法人制组织形式，也可以采取公司制组织形式。 采取非法人制组织形式的创投企业（以下简称非法人制创投企业）的投资者对创投企业的债务承担连带责任。非法人制创投企业的投资者也可以在创投企业合同中约定在非法人制创投企业资产不足以清偿该债务时由第七条所述的必备投资者承担连带责任，其他投资者以其认缴的出资额为限承担责任。 采用公司制组织形式的创投企业（以下简称公司制创投企业）的投资者以其各自认缴的出资额为限对创投企业承担责任。"},{"i":5,"n":"第五条","txt":"创投企业应遵守中国有关法律法规，符合外商投资产业政策，不得损害中国的社会公共利益。创投企业在中国境内的正当经营活动及合法权益受中国法律的保护。"},{"i":6,"n":"第六条","txt":"设立创投企业应具备下列条件： （一）投资者人数在2人以上50以下；且应至少拥有一个第七条所述的必备投资者； （二）外国投资者以可自由兑换的货币出资，中国投资者以人民币出资； （三）有明确的组织形式； （四）有明确合法的投资方向； （五）除了将本企业经营活动授予一家创业投资管理公司进行管理的情形外，创投企业应有三名以上具备创业投资从业经验的专业人员； （六）法律、行政法规规定的其他条件。"},{"i":7,"n":"第七条","txt":"必备投资者应当具备下列条件： （一）以创业投资为主营业务； （二）在申请前三年其管理的资本累计不低于1亿美元，且其中至少5000万美元已经用于进行创业投资。在必备投资者为中国投资者的情形下，本款业绩要求为：在申请前三年其管理的资本累计不低于1亿元人民币，且其中至少5000万元人民币已经用于进行创业投资）； （三）拥有3名以上具有3年以上创业投资从业经验的专业管理人员； （四）如果某一投资者的关联实体满足上述条件，则该投资者可以申请成为必备投资者。本款所称关联实体是指该投资者控制的某一实体、或控制该投资者的某一实体、或与该投资者共同受控于某一实体的另一实体。本款所称控制是指控制方拥有被控制方超过50%的表决权； （五）必备投资者及其上述关联实体均应未被所在国司法机关和其他相关监管机构禁止从事创业投资或投资咨询业务或以欺诈等原因进行处罚； （六）非法人制创投企业的必备投资者，对创投企业的认"},{"i":8,"n":"第八条","txt":"设立创投企业按以下程序办理： （一）投资者须向拟设立创投企业所在地省级外经贸主管部门报送设立申请书及有关文件。 （二）省级外经贸主管部门应在收到全部上报材料后15天内完成初审并上报对外贸易经济合作部（以下简称审批机构）。 （三）审批机构在收到全部上报材料之日起45天内，经商科学技术部同意后，做出批准或不批准的书面决定。予以批准的，发给《外商投资企业批准证书》。 （四）获得批准设立的创投企业应自收到审批机构颁发的《外商投资企业批准证书》之日起一个月内，持此证书向国家工商行政管理部门或所在地具有外商投资企业登记管理权的省级工商行政管理部门（以下简称登记机关）申请办理注册登记手续。"},{"i":9,"n":"第九条","txt":"申请设立创投企业应当向审批机构报送以下文件： （一）必备投资者签署的设立申请书； （二）投资各方签署的创投企业合同及章程； （三）必备投资者书面声明（声明内容包括：投资者符合第七条规定的资格条件；所有提供的材料真实性；投资者将严格遵循本规定及中国其他有关法律法规的要求）； （四）律师事务所出具的对必备投资者合法存在及其上述声明已获得有效授权和签署的法律意见书； （五）必备投资者的创业投资业务说明、申请前三年其管理资本的说明、其已投资资本的说明，及其拥有的创业投资专业管理人员简历； （六）投资者的注册登记证明（复印件）、法定代表人证明（复印件）； （七）名称登记机关出具的创投企业名称预先核准通知书； （八）如果必备投资者的资格条件是依据第七条第（四）款的规定，则还应报送其符合条件的关联实体的相关材料； （九）审批机构要求的其他与申请设立有关的文件。"},{"i":10,"n":"第十条","txt":"创投企业应当在名称中加注创业投资字样。除创投企业外，其他外商投资企业不得在名称中使用创业投资字样。"},{"i":11,"n":"第十一条","txt":"申请设立创投企业应当向登记机关报送下列文件,并对其真实性、有效性负责： （一）创投企业董事长或联合管理委员会负责人签署的设立登记申请书； （二）合同、章程以及审批机构的批准文件和批准证书； （三）投资者的合法开业证明或身份证明； （四）投资者的资信证明； （五）法定代表人的任职文件、身份证明和企业董事、经理等人员的备案文件； （六）企业名称预先核准通知书； （七）企业住所或营业场所证明。 申请设立非法人制创投企业，还应当提交境外必备投资者的章程或合伙协议。企业投资者中含本规定第七条第四款规定的投资者的，还应当提交关联实体为其出具的承担出资连带责任的担保函。 以上文件应使用中文。使用外文的，应提供规范的中文译本。 创投企业登记事项变更应依法向原登记机关申请办理变更登记。"},{"i":12,"n":"第十二条","txt":"经登记机关核准的公司制创投企业，领取《企业法人营业执照》；经登记机关核准的非法人制创投企业，领取《营业执照》。 《营业执照》应载明非法人制创投企业投资者认缴的出资总额和必备投资者名称。"},{"i":13,"n":"第十三条","txt":"非法人制创投企业的投资者的出资及相关变更应符合如下规定： （一）投资者可以根据创业投资进度分期向创投企业注入认缴出资。各期投入资本额由创投企业根据创投企业合同及其与所投资企业签定的协议自主制定。投资者应在创投企业合同中约定投资者不如期出资的责任和相关措施； （二）必备投资者在创投企业存续期内不得从创投企业撤出。特殊情况下确需撤出的，应获得占总出资额超过50%的其他投资者同意，并应将其权益转让给符合第七条要求的新投资者，且应当相应修改创投企业的合同和章程，并报审批机构批准。 其他投资者如转让其认缴资本额或已投入资本额，须按创投企业合同的约定进行，且受让人应符合本规定第六条的有关要求。投资各方应相应修改创投企业合同和章程，并报审批机构备案。 （三）创投企业设立后，如果有新的投资者申请加入，须符合本规定和创投企业合同的约定，经必备投资者同意，相应修改创投企业合同和章程，并报审批机构备案。 （"},{"i":14,"n":"第十四条","txt":"非法人制创投企业向登记机关申请变更登记时，上述规定中审批机关出具的相关备案证明可替代相应的审批文件。"},{"i":15,"n":"第十五条","txt":"非法人制创投企业投资者根据创业投资进度缴付出资后，应持相关验资报告向原登记机关申请办理出资备案手续。登记机关根据其实际出资状况在其《营业执照》出资额栏目后加注实缴出资额数目。 非法人制创投企业超过最长投资期限仍未缴付或缴清出资的，登记机关根据现行规定予以处罚。"},{"i":16,"n":"第十六条","txt":"公司制创投企业投资者的出资及相关变更按现行规定办理。"},{"i":17,"n":"第十七条","txt":"非法人制创投企业设联合管理委员会。公司制创投企业设董事会。联合管理委员会或董事会的组成由投资者在创投企业合同及章程中予以约定。联合管理委员会或董事会代表投资者管理创投企业。"},{"i":18,"n":"第十八条","txt":"联合管理委员会或董事会下设经营管理机构，根据创投企业的合同及章程中规定的权限，负责日常经营管理工作，执行联合管理委员会或董事会的投资决策。"},{"i":19,"n":"第十九条","txt":"经营管理机构的负责人应当符合下列条件： （一）具有完全的民事行为能力； （二）无犯罪记录； （三）无不良经营记录； （四）应具有创业投资业的从业经验，且无违规操作记录； （五）审批机构要求的与经营管理资格有关的其他条件。"},{"i":20,"n":"第二十条","txt":"经营管理机构应定期向联合管理委员会或董事会报告以下事项： （一）经授权的重大投资活动； （二）中期、年度业绩报告和财务报告； （三）法律、法规规定的其他事项； （四）创投企业合同及章程中规定的有关事项。"},{"i":21,"n":"第二十一条","txt":"联合管理委员会或董事会可以不设立经营管理机构，而将该创投企业的日常经营权授予一家创业投资管理企业或另一家创投企业进行管理。该创业投资管理企业可以是内资创业投资管理企业，也可以是外商投资创业投资管理企业，或境外创业投资管理企业。在此情形下，该创投企业与该创业投资管理企业应签订管理合同，约定创投企业和创业投资管理企业的权利义务。该管理合同应经全体投资者同意并报审批机构批准后方可生效。"},{"i":22,"n":"第二十二条","txt":"创投企业的投资者可以在创业投资合同中依据国际惯例约定内部收益分配机制和奖励机制。"},{"i":23,"n":"第二十三条","txt":"受托管理创投企业的创业投资管理企业应具备下列条件： （一）以受托管理创投企业的投资业务为主营业务； （二）拥有三名以上具有三年以上创业投资从业经验的专业管理人员； （三）有完善的内部控制制度。"},{"i":24,"n":"第二十四条","txt":"创业投资管理企业可以采取公司制组织形式，也可以采取合伙制组织形式。"},{"i":25,"n":"第二十五条","txt":"同一创业投资管理企业可以受托管理不同的创投企业。"},{"i":26,"n":"第二十六条","txt":"创业投资管理企业应定期向委托方的联合管理委员会或董事会报告第二十条所列事项。"},{"i":27,"n":"第二十七条","txt":"设立外商投资创业投资管理企业应符合本规定第二十三条的条件，经拟设立外商投资创业投资管理公司所在地省级外经贸主管部门报审批机构批准。审批机构在收到全部上报材料之日起45天内，做出批准或不批准的书面决定。予以批准的，发给《外商投资企业批准证书》。获得批准设立的外商投资创业投资管理企业应自收到审批机构颁发的《外商投资企业批准证书》之日起一个月内，持此证书向登记机关申请办理注册登记手续。"},{"i":28,"n":"第二十八条","txt":"申请设立外商投资创业投资管理公司应当向审批机构报送以下文件： （一）设立申请书； （二）外商投资创业投资管理公司合同及章程； （三）投资者的注册登记证明（复印件）、法定代表人证明（复印件）； （四）审批机构要求的其他与申请设立有关的文件。"},{"i":29,"n":"第二十九条","txt":"外商投资创业投资管理企业名称应当加注创业投资管理字样。除外商投资创业投资管理企业外，其他外商投资企业不得在名称中使用创业投资管理字样。"},{"i":30,"n":"第三十条","txt":"获得批准接受创投企业委托在华从事创业投资管理业务的境外创业投资管理企业，应当自管理合同获得批准之日起30日内，向登记机关申请办理营业登记手续。 申请营业登记应报送下列文件，并对其真实性、有效性负责： （一）境外创业投资管理企业董事长或有权签字人签署的登记申请书； （二）经营管理合同及审批机构的批准文件； （三）境外创业投资管理企业的章程或合伙协议； （四）境外创业投资管理企业的合法开业证明； （五）境外创业投资管理企业的资信证明； （六）境外创业投资管理企业委派的中国项目负责人的授权书、简历及身份证明； （七）境外创业投资管理企业在华营业场所证明。 以上文件应使用中文。使用外文的，应提供规范的中文译本。"},{"i":31,"n":"第三十一条","txt":"创投企业可以经营以下业务： （一）以全部自有资金进行股权投资，具体投资方式包括新设企业、向已设立企业投资、接受已设立企业投资者股权转让以及国家法律法规允许的其他方式； （二）提供创业投资咨询； （三）为所投资企业提供管理咨询； （四）审批机构批准的其他业务。 创投企业资金应主要用于向所投资企业进行股权投资。"},{"i":32,"n":"第三十二条","txt":"创投企业不得从事下列活动： （一）在国家禁止外商投资的领域投资； （二）直接或间接投资于上市交易的股票和企业债券，但所投资企业上市后，创投企业所持股份不在此列； （三）直接或间接投资于非自用不动产； （四）贷款进行投资； （五）挪用非自有资金进行投资； （六）向他人提供贷款或担保，但创投企业对所投资企业1年以上的企业债券和可以转换为所投资企业股权的债券性质的投资不在此列（本款规定并不涉及所投资企业能否发行该等债券）； （七）法律、法规以及创投企业合同禁止从事的其他事项。"},{"i":33,"n":"第三十三条","txt":"投资者应在创投企业合同中约定对外投资期限。"},{"i":34,"n":"第三十四条","txt":"创投企业主要从出售或以其他方式处置其在所投资企业的股权获得收益。创投企业出售或以其他方式处置其在所投资企业的股权时，可以依法选择适用的退出机制，包括： （一）将其持有的所投资企业的部分股权或全部股权转让给其他投资者； （二）与所投资企业签订股权回购协议，由所投资企业在一定条件下依法回购其所持有的股权； （三）所投资企业在符合法律、行政法规规定的上市条件时可以申请到境内外证券市场上市。创投企业可以依法通过证券市场转让其拥有的所投资企业的股份； （四）中国法律、行政法规允许的其他方式。 所投资企业向创投企业回购该创投企业所持股权的具体办法由审批机构会同登记机关另行制订。"},{"i":35,"n":"第三十五条","txt":"创投企业应当依照国家税法的规定依法申报纳税。对非法人制创投企业，可以由投资各方依照国家税法的有关规定，分别申报缴纳企业所得税；也可以由非法人制创投企业提出申请，经批准后，依照税法规定统一计算缴纳企业所得税。 非法人制创投企业企业所得税的具体征收管理办法由国家税务总局另行颁布。"},{"i":36,"n":"第三十六条","txt":"创投企业中属于外国投资者的利润等收益汇出境外的，应当凭管理委员会或董事会的分配决议，由会计师事务所出具的审计报告、外方投资者投资资金流入证明和验资报告、完税证明和税务申报单（享受减免税优惠的，应提供税务部门出具的减免税证明文件），从其外汇帐户中支付或者到外汇指定银行购汇汇出。 外国投资者回收的对创投企业的出资可依法申购外汇汇出。公司制创投企业开立和使用外汇帐户、资本变动及其他外汇收支事项，按照现行外汇管理规定办理。非法人制创投企业外汇管理规定由国家外汇管理局另行制定。"},{"i":37,"n":"第三十七条","txt":"投资者应在合同、章程中约定创投企业的经营期限，一般不得超过12年。经营期满，经审批机构批准，可以延期。 经审批机构批准，创投企业可以提前解散，终止合同和章程。但是，如果非法人制创投企业的所有投资均已被出售或通过其他方式变卖，其债务亦已全部清偿，且其剩余财产均已被分配给投资者，则毋需上述批准即可进入解散和终止程序，但该非法人制创业投资企业应在该等解散生效前至少30天内向审批机构提交一份书面备案说明。 创投企业解散，应按有关规定进行清算。"},{"i":38,"n":"第三十八条","txt":"创投企业应当自清算结束之日起30日内向原登记机关申请注销登记。 申请注销登记，应当提交下列文件，并对其真实性、有效性负责： （一）董事长或联合管理委员会负责人或清算组织负责人签署的注销登记申请书； （二）董事会或联合管理委员会的决议； （三）清算报告； （四）税务机关、海关出具的注销登记证明； （五）审批机构的批准文件或备案文件； （六）法律、行政法规规定应当提交的其他文件。 经登记机关核准注销登记，创投企业终止。 非法人制创投企业必备投资者承担的连带责任不因非法人制创投企业的终止而豁免。"},{"i":39,"n":"第三十九条","txt":"创投企业境内投资比照执行《指导外商投资方向规定》和《外商投资产业指导目录》的规定。"},{"i":40,"n":"第四十条","txt":"创投企业投资于任何鼓励类和允许类的所投资企业，应向所投资企业当地授权的外经贸部门备案。当地授权的外经贸部门应在收到备案材料后15天内完成备案审核手续并向所投资企业颁发外商投资企业批准证书。所投资企业持外商投资企业批准证书向登记机关申请办理注册登记手续。登记机关依照有关法律和行政法规规定决定准予登记或不予登记。准予登记的，颁发外商投资企业法人营业执照。"},{"i":41,"n":"第四十一条","txt":"创投企业投资于限制类的所投资企业，应向所投资企业所在地省级外经贸主管部门提出申请，并提供下列材料： （一）创投企业关于投资资金充足的声明； （二）创投企业的批准证书和营业执照（复印件）； （三）创投企业（与所投资企业其他投资者）签定的所投资企业合同与章程。 省级外经贸主管部门接到上述申请之日起45日内作出同意或不同意的书面批复。作出同意批复的，颁发外商投资企业批准证书。所投资企业持该批复文件和外商投资企业批准证书向登记机关申请登记。登记机关依照有关法律和行政法规规定决定准予登记或不予登记。准予登记的，颁发外商投资企业法人营业执照。"},{"i":42,"n":"第四十二条","txt":"创投企业投资属于服务贸易领域逐步开放的外商投资项目，按国家有关规定审批。"},{"i":43,"n":"第四十三条","txt":"创投企业增加或转让其在所投资企业投资等行为，按照第四十条、第四十一条和第四十二条规定的程序办理。"},{"i":44,"n":"第四十四条","txt":"创投企业应在履行完第四十条、第四十一条、第四十二条和第四十三条规定的程序之日起一个月内向审批机构备案。"},{"i":45,"n":"第四十五条","txt":"创投企业还应在每年3月份将上一年度的资金筹集和使用情况报审批机构备案。 审批机构在接到该备案材料起5个工作日内应出具备案登记证明。凡未按上述规定备案的，审批机构将商国务院有关部门后予以相应处罚。"},{"i":46,"n":"第四十六条","txt":"创投企业的所投资企业注册资本中，如果创投企业投资的比例中外国投资者的实际出资比例或与其他外国投资者联合投资的比例总和不低于25%，则该所投资企业将享受外商投资企业有关优惠待遇；如果创投企业投资的比例中外国投资者的实际出资比例或与其他外国投资者联合投资的比例总和低于该所投资企业注册资本的25%，则该所投资企业将不享受外商投资企业有关优惠待遇。"},{"i":47,"n":"第四十七条","txt":"已成立的含有境内自然人投资者的内资企业在接受创业投资企业投资变更为外商投资企业后，可以继续保留其原有境内自然人投资者的股东地位。"},{"i":48,"n":"第四十八条","txt":"创投企业经营管理机构的负责人和创业投资管理企业的负责人如有违法操作行为，除依法追究责任外，情节严重的，不得继续从事创业投资及相关的投资管理活动。"},{"i":49,"n":"第四十九条","txt":"香港特别行政区、澳门特别行政区、台湾地区的投资者在大陆投资设立创投企业，参照本规定执行。"},{"i":50,"n":"第五十条","txt":"本规定由对外贸易经济合作部、科学技术部、国家工商行政管理总局、国家税务总局和国家外汇管理局负责解释。"},{"i":51,"n":"第五十一条","txt":"本规定自二OO三年三月一日起施行。对外贸易经济合作部、科学技术部和国家工商行政管理总局于二OO一年八月二十八日发布的《关于设立外商投资创业投资企业的暂行规定》同日废止。"}],"waiguotouzizheduishangshigongsizhanlvetouziguanlib6303a6-2":[{"i":1,"n":"第一条","txt":"为了规范股权分置改革后外国投资者对A股上市公司（以下简称上市公司）进行战略投资，维护证券市场秩序，引进境外先进管理经验、技术和资金，改善上市公司治理结构，保护上市公司和股东的合法权益，按照《关于上市公司股权分置改革的指导意见》的要求，根据国家有关外商投资、上市公司监管的法律法规以及《外国投资者并购境内企业暂行规定》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于外国投资者（以下简称投资者）对已完成股权分置改革的上市公司和股权分置改革后新上市公司通过具有一定规模的中长期战略性并购投资（以下简称战略投资），取得该公司A股股份的行为。"},{"i":3,"n":"第三条","txt":"经商务部批准，投资者可以根据本办法对上市公司进行战略投资。"},{"i":4,"n":"第四条","txt":"战略投资应遵循以下原则： （一）遵守国家法律、法规及相关产业政策，不得危害国家经济安全和社会公共利益； （二）坚持公开、公正、公平的原则，维护上市公司及其股东的合法权益，接受政府、社会公众的监督及中国的司法和仲裁管辖； （三）鼓励中长期投资，维护证券市场的正常秩序，不得炒作； （四）不得妨碍公平竞争，不得造成中国境内相关产品市场过度集中、排除或限制竞争。"},{"i":5,"n":"第五条","txt":"投资者进行战略投资应符合以下要求： （一）以协议转让、上市公司定向发行新股方式以及国家法律法规规定的其他方式取得上市公司A股股份； （二）投资可分期进行，首次投资完成后取得的股份比例不低于该公司已发行股份的百分之十，但特殊行业有特别规定或经相关主管部门批准的除外； （三）取得的上市公司A股股份三年内不得转让； （四）法律法规对外商投资持股比例有明确规定的行业，投资者持有上述行业股份比例应符合相关规定；属法律法规禁止外商投资的领域，投资者不得对上述领域的上市公司进行投资； （五）涉及上市公司国有股股东的，应符合国有资产管理的相关规定。"},{"i":6,"n":"第六条","txt":"投资者应符合以下要求： （一）依法设立、经营的外国法人或其他组织，财务稳健、资信良好且具有成熟的管理经验； （二）境外实有资产总额不低于1亿美元或管理的境外实有资产总额不低于5亿美元；或其母公司境外实有资产总额不低于1亿美元或管理的境外实有资产总额不低于5亿美元； （三）有健全的治理结构和良好的内控制度，经营行为规范； （四）近三年内未受到境内外监管机构的重大处罚（包括其母公司）。"},{"i":7,"n":"第七条","txt":"通过上市公司定向发行方式进行战略投资的，按以下程序办理： （一）上市公司董事会通过向投资者定向发行新股及公司章程修改草案的决议； （二）上市公司股东大会通过向投资者定向发行新股及修改公司章程的决议； （三）上市公司与投资者签订定向发行的合同； （四）上市公司根据本办法第十二条向商务部报送相关申请文件，有特殊规定的从其规定； （五）定向发行完成后，上市公司到商务部领取外商投资企业批准证书，并凭该批准证书到工商行政管理部门办理变更登记。"},{"i":8,"n":"第八条","txt":"通过协议转让方式进行战略投资的，按以下程序办理： （一）上市公司董事会通过投资者以协议转让方式进行战略投资的决议； （二）上市公司股东大会通过投资者以协议转让方式进行战略投资的决议； （三）转让方与投资者签订股份转让协议； （四）投资者根据本办法第十二条向商务部报送相关申请文件，有特殊规定的从其规定； （五）投资者参股上市公司的，获得前述批准后向证券交易所办理股份转让确认手续、向证券登记结算机构申请办理登记过户手续，并报中国证监会备案； （六）协议转让完成后，上市公司到商务部领取外商投资企业批准证书，并凭该批准证书到工商行政管理部门办理变更登记。"},{"i":9,"n":"第九条","txt":"投资者拟通过协议转让方式构成对上市公司的实际控制，按照第八条第（一）、（二）、（三）、（四）项的程序获得批准后，向中国证监会报送上市公司收购报告书及相关文件，经中国证监会审核无异议后向证券交易所办理股份转让确认手续、向证券登记结算机构申请办理登记过户手续。完成上述手续后，按照第八条第（六）项办理。"},{"i":10,"n":"第十条","txt":"投资者对上市公司进行战略投资，应按《证券法》和中国证监会的相关规定履行报告、公告及其他法定义务。"},{"i":11,"n":"第十一条","txt":"投资者对其已持有股份的上市公司继续进行战略投资的，需按本办法规定的方式和程序办理。"},{"i":12,"n":"第十二条","txt":"上市公司或投资者应向商务部报送以下文件： （一）战略投资申请书（格式见附件1）； （二）战略投资方案（格式见附件2）； （三）定向发行合同或股份转让协议； （四）保荐机构意见书（涉及定向发行）或法律意见书； （五）投资者持续持股的承诺函； （六）投资者三年内未受到境内外监管机构重大处罚的声明，以及是否受到其他非重大处罚的说明； （七）经依法公证、认证的投资者的注册登记证明、法定代表人（或授权代表）身份证明； （八）经注册会计师审计的该投资者近三年来的资产负债表； （九）上述（一）、（二）、（三）、（五）、（六）项中规定提交的文件均需经投资者法定代表人或其授权代表签署，由授权代表签署的还应提交经法定代表人签署的授权书及相应的公证、认证文件； （十）商务部规定的其他文件。 前款所列文件，除第七项、第八项所列文件外，必须报送中文本原件，第七项、第八项所列文件应报送原件及中文译件。 商务部收到"},{"i":13,"n":"第十三条","txt":"符合本办法第六条规定的外国公司（\"母公司\"）可以通过其全资拥有的境外子公司（\"投资者\"）进行战略投资，投资者除提交本办法第十二条所列文件外，还应向商务部提交其母公司对投资者投资行为承担连带责任的不可撤销的承诺函。"},{"i":14,"n":"第十四条","txt":"投资者应在商务部原则批复之日起15日内根据外商投资并购的相关规定开立外汇账户。投资者从境外汇入的用于战略投资的外汇资金，应当根据外汇管理的有关规定，到上市公司注册所在地外汇局申请开立外国投资者专用外汇账户（收购类），账户内资金的结汇及账户注销手续参照相关外汇管理规定办理。"},{"i":15,"n":"第十五条","txt":"投资者可以持商务部对该投资者对上市公司进行战略投资的批准文件和有效身份证明，向证券登记结算机构办理相关手续。 对于投资者在上市公司股权分置改革前持有的非流通股份或在上市公司首次公开发行前持有的股份，证券登记结算机构可以根据投资者申请为其开立证券账户。 证券登记结算机构应根据本管理办法制定相应规定。"},{"i":16,"n":"第十六条","txt":"投资者应在资金结汇之日起15日内启动战略投资行为，并在原则批复之日起180日内完成战略投资。 投资者未能在规定时间内按战略投资方案完成战略投资的，审批机关的原则批复自动失效。投资者应在原则批复失效之日起45日内，经外汇局核准后将结汇所得人民币资金购汇并汇出境外。"},{"i":17,"n":"第十七条","txt":"战略投资完成后，上市公司应于10日内凭以下文件到商务部领取外商投资企业批准证书： （一）申请书； （二）商务部原则批复函； （三）证券登记结算机构出具的股份持有证明； （四）上市公司营业执照和法定代表人身份证明； （五）上市公司章程。 商务部在收到上述全部文件之日起5日内颁发外商投资企业批准证书，加注\"外商投资股份公司（A股并购）\"。 如投资者取得单一上市公司25%或以上股份并承诺在10年内持续持股不低于25%，商务部在颁发的外商投资企业批准证书上加注\"外商投资股份公司（A股并购25%或以上）\"。"},{"i":18,"n":"第十八条","txt":"上市公司应自外商投资企业批准证书签发之日起30日内，向工商行政管理机关申请办理公司类型变更登记，并提交下列文件： （一）公司法定代表人签署的申请变更申请书； （二）外商投资企业批准证书； （三）证券登记结算机构出具的股份持有证明； （四）经公证、认证的投资者的合法开业证明； （五）国家工商行政管理总局规定应提交的其他文件。 经核准变更的，工商行政管理机关在营业执照企业类型栏目中加注\"外商投资股份公司（A股并购）\"字样，其中，投资者进行战略投资取得单一上市公司25%或以上股份并承诺在10年内持续持股不低于25%的，加注\"外商投资股份公司（A股并购25%或以上）\"。"},{"i":19,"n":"第十九条","txt":"上市公司应自外商投资企业营业执照签发之日起30日内，到税务、海关、外汇管理等有关部门办理相关手续。外汇管理部门在所颁发的外汇登记证上加注\"外商投资股份公司（A股并购）\"。如投资者进行战略投资取得单一上市公司25%或以上股份并承诺在10年内持续持股不低于25%的，外汇管理部门在外汇登记证上加注\"外商投资股份公司（A股并购25%或以上）\"。"},{"i":20,"n":"第二十条","txt":"除以下情形外，投资者不得进行证券买卖（B股除外）： （一）投资者进行战略投资所持上市公司A股股份，在其承诺的持股期限届满后可以出售； （二）投资者根据《证券法》相关规定须以要约方式进行收购的，在要约期间可以收购上市公司A股股东出售的股份； （三）投资者在上市公司股权分置改革前持有的非流通股份，在股权分置改革完成且限售期满后可以出售； （四）投资者在上市公司首次公开发行前持有的股份，在限售期满后可以出售； （五）投资者承诺的持股期限届满前，因其破产、清算、抵押等特殊原因需转让其股份的，经商务部批准可以转让。"},{"i":21,"n":"第二十一条","txt":"投资者减持股份使上市公司外资股比低于25%，上市公司应在10日内向商务部备案并办理变更外商投资企业批准证书的相关手续。 投资者减持股份使上市公司外资股比低于10%，且该投资者非为单一最大股东，上市公司应在10日内向审批机关备案并办理注销外商投资企业批准证书的相关手续。"},{"i":22,"n":"第二十二条","txt":"投资者减持股份使上市公司外资股比低于25%，上市公司应自外商投资企业批准证书变更之日起30日内到工商行政管理机关办理变更登记，工商行政管理机关在营业执照上企业类型调整为\"外商投资股份公司（A股并购）\"。上市公司应自营业执照变更之日起30日内到外汇管理部门办理变更外汇登记，外汇管理部门在外汇登记证上加注\"外商投资股份公司（A股并购）\"。 投资者减持股份使上市公司外资股比低于10%，且投资者非为单一最大股东，上市公司自外商投资企业批准证书注销之日起30日内到工商行政管理机关办理变更登记，企业类型变更为股份有限公司。上市公司应自营业执照变更之日起30日内到外汇管理部门办理外汇登记注销手续。"},{"i":23,"n":"第二十三条","txt":"母公司通过其全资拥有的境外子公司进行战略投资并已按期完成的，母公司转让上述境外子公司前应向商务部报告，并根据本办法所列程序提出申请。新的受让方仍应符合本办法所规定的条件，承担母公司及其子公司在上市公司中的全部权利和义务，并依法履行向中国证监会报告、公告及其他法定义务。"},{"i":24,"n":"第二十四条","txt":"投资者通过A股市场将所持上市公司股份出让的，可凭以下文件向上市公司注册所在地外汇局申请购汇汇出： （一）书面申请； （二）为战略投资目的所开立的外国投资者专用外汇账户（收购类）内资金经外汇局核准结汇的核准件； （三）证券经纪机构出具的有关证券交易证明文件。"},{"i":25,"n":"第二十五条","txt":"投资者持股比例低于25%的上市公司，其举借外债按照境内中资企业举借外债的有关规定办理。"},{"i":26,"n":"第二十六条","txt":"相关政府机构工作人员必须忠于职守、依法履行职责，不得利用职务便利牟取不正当利益，并对知悉的商业秘密负有保密义务。"},{"i":27,"n":"第二十七条","txt":"香港特别行政区、澳门特别行政区、台湾地区的投资者进行战略投资，参照本办法办理。"},{"i":28,"n":"第二十八条","txt":"本办法自发布之日起30日后施行。"}],"waiguotouzizheduishangshigongsizhanlvetouziguanlib6303a6":[{"i":1,"n":"第一条","txt":"为了规范股权分置改革后外国投资者对A股上市公司（以下简称上市公司）进行战略投资，维护证券市场秩序，引进境外先进管理经验、技术和资金，改善上市公司治理结构，保护上市公司和股东的合法权益，按照《关于上市公司股权分置改革的指导意见》的要求，根据国家有关外商投资、上市公司监管的法律法规以及《外国投资者并购境内企业暂行规定》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于外国投资者（以下简称投资者）对已完成股权分置改革的上市公司和股权分置改革后新上市公司通过具有一定规模的中长期战略性并购投资（以下简称战略投资），取得该公司A股股份的行为。"},{"i":3,"n":"第三条","txt":"经商务部批准，投资者可以根据本办法对上市公司进行战略投资。"},{"i":4,"n":"第四条","txt":"战略投资应遵循以下原则： （一）遵守国家法律、法规及相关产业政策，不得危害国家经济安全和社会公共利益； （二）坚持公开、公正、公平的原则，维护上市公司及其股东的合法权益，接受政府、社会公众的监督及中国的司法和仲裁管辖； （三）鼓励中长期投资，维护证券市场的正常秩序，不得炒作； （四）不得妨碍公平竞争，不得造成中国境内相关产品市场过度集中、排除或限制竞争。"},{"i":5,"n":"第五条","txt":"投资者进行战略投资应符合以下要求： （一）以协议转让、上市公司定向发行新股方式以及国家法律法规规定的其他方式取得上市公司A股股份； （二）投资可分期进行，首次投资完成后取得的股份比例不低于该公司已发行股份的百分之十，但特殊行业有特别规定或经相关主管部门批准的除外； （三）取得的上市公司A股股份三年内不得转让； （四）法律法规对外商投资持股比例有明确规定的行业，投资者持有上述行业股份比例应符合相关规定；属法律法规禁止外商投资的领域，投资者不得对上述领域的上市公司进行投资； （五）涉及上市公司国有股股东的，应符合国有资产管理的相关规定。"},{"i":6,"n":"第六条","txt":"投资者应符合以下要求： （一）依法设立、经营的外国法人或其他组织，财务稳健、资信良好且具有成熟的管理经验； （二）境外实有资产总额不低于1亿美元或管理的境外实有资产总额不低于5亿美元；或其母公司境外实有资产总额不低于1亿美元或管理的境外实有资产总额不低于5亿美元； （三）有健全的治理结构和良好的内控制度，经营行为规范； （四）近三年内未受到境内外监管机构的重大处罚（包括其母公司）。"},{"i":7,"n":"第七条","txt":"通过上市公司定向发行方式进行战略投资的，按以下程序办理： （一）上市公司董事会通过向投资者定向发行新股及公司章程修改草案的决议； （二）上市公司股东大会通过向投资者定向发行新股及修改公司章程的决议； （三）上市公司与投资者签订定向发行的合同； （四）上市公司根据本办法第十二条向商务部报送相关申请文件，有特殊规定的从其规定； （五）定向发行完成后，上市公司到商务部领取外商投资企业批准证书，并凭该批准证书到工商行政管理部门办理变更登记。"},{"i":8,"n":"第八条","txt":"通过协议转让方式进行战略投资的，按以下程序办理： （一）上市公司董事会通过投资者以协议转让方式进行战略投资的决议； （二）上市公司股东大会通过投资者以协议转让方式进行战略投资的决议； （三）转让方与投资者签订股份转让协议； （四）投资者根据本办法第十二条向商务部报送相关申请文件，有特殊规定的从其规定； （五）投资者参股上市公司的，获得前述批准后向证券交易所办理股份转让确认手续、向证券登记结算机构申请办理登记过户手续，并报中国证监会备案； （六）协议转让完成后，上市公司到商务部领取外商投资企业批准证书，并凭该批准证书到工商行政管理部门办理变更登记。"},{"i":9,"n":"第九条","txt":"投资者拟通过协议转让方式构成对上市公司的实际控制，按照第八条第（一）、（二）、（三）、（四）项的程序获得批准后，向中国证监会报送上市公司收购报告书及相关文件，经中国证监会审核无异议后向证券交易所办理股份转让确认手续、向证券登记结算机构申请办理登记过户手续。完成上述手续后，按照第八条第（六）项办理。"},{"i":10,"n":"第十条","txt":"投资者对上市公司进行战略投资，应按《证券法》和中国证监会的相关规定履行报告、公告及其他法定义务。"},{"i":11,"n":"第十一条","txt":"投资者对其已持有股份的上市公司继续进行战略投资的，需按本办法规定的方式和程序办理。"},{"i":12,"n":"第十二条","txt":"上市公司或投资者应向商务部报送以下文件： （一）战略投资申请书（格式见附件1）； （二）战略投资方案（格式见附件2）； （三）定向发行合同或股份转让协议； （四）保荐机构意见书（涉及定向发行）或法律意见书； （五）投资者持续持股的承诺函； （六）投资者三年内未受到境内外监管机构重大处罚的声明，以及是否受到其他非重大处罚的说明； （七）经依法公证、认证的投资者的注册登记证明、法定代表人（或授权代表）身份证明； （八）经注册会计师审计的该投资者近三年来的资产负债表； （九）上述（一）、（二）、（三）、（五）、（六）项中规定提交的文件均需经投资者法定代表人或其授权代表签署，由授权代表签署的还应提交经法定代表人签署的授权书及相应的公证、认证文件； （十）商务部规定的其他文件。 前款所列文件，除第七项、第八项所列文件外，必须报送中文本原件，第七项、第八项所列文件应报送原件及中文译件。 商务部收到"},{"i":13,"n":"第十三条","txt":"符合本办法第六条规定的外国公司（“母公司”）可以通过其全资拥有的境外子公司（“投资者”）进行战略投资，投资者除提交本办法第九条所列文件外，还应向商务部提交其母公司对投资者投资行为承担连带责任的不可撤销的承诺函。"},{"i":14,"n":"第十四条","txt":"投资者应在商务部原则批复之日起15日内根据外商投资并购的相关规定开立外汇账户。投资者从境外汇入的用于战略投资的外汇资金，应当根据外汇管理的有关规定，到上市公司注册所在地外汇局申请开立外国投资者专用外汇账户（收购类），账户内资金的结汇及账户注销手续参照相关外汇管理规定办理。"},{"i":15,"n":"第十五条","txt":"投资者可以持商务部对该投资者对上市公司进行战略投资的批准文件和有效身份证明，向证券登记结算机构办理相关手续。 对于投资者在上市公司股权分置改革前持有的非流通股份或在上市公司首次公开发行前持有的股份，证券登记结算机构可以根据投资者申请为其开立证券账户。 证券登记结算机构应根据本管理办法制定相应规定。"},{"i":16,"n":"第十六条","txt":"投资者应在资金结汇之日起15日内启动战略投资行为，并在原则批复之日起180日内完成战略投资。 投资者未能在规定时间内按战略投资方案完成战略投资的，审批机关的原则批复自动失效。投资者应在原则批复失效之日起45日内，经外汇局核准后将结汇所得人民币资金购汇并汇出境外。"},{"i":17,"n":"第十七条","txt":"战略投资完成后，上市公司应于10日内凭以下文件到商务部领取外商投资企业批准证书： （一）申请书； （二）商务部原则批复函； （三）证券登记结算机构出具的股份持有证明； （四）上市公司营业执照和法定代表人身份证明； （五）上市公司章程。 商务部在收到上述全部文件之日起5日内颁发外商投资企业批准证书，加注“外商投资股份公司（A股并购）”。 如投资者取得单一上市公司25％或以上股份并承诺在10年内持续持股不低于25％，商务部在颁发的外商投资企业批准证书上加注“外商投资股份公司（A股并购25％或以上）”。"},{"i":18,"n":"第十八条","txt":"上市公司应自外商投资企业批准证书签发之日起30日内，向工商行政管理机关申请办理公司类型变更登记，并提交下列文件： （一）公司法定代表人签署的申请变更申请书； （二）外商投资企业批准证书； （三）证券登记结算机构出具的股份持有证明； （四）经公证、认证的投资者的合法开业证明； （五）国家工商行政管理总局规定应提交的其他文件。 经核准变更的，工商行政管理机关在营业执照企业类型栏目中加注“外商投资股份公司（A股并购）”字样，其中，投资者进行战略投资取得单一上市公司25％或以上股份并承诺在10年内持续持股不低于25%的，加注“外商投资股份公司（A股并购25％或以上）”。"},{"i":19,"n":"第十九条","txt":"上市公司应自外商投资企业营业执照签发之日起30日内，到税务、海关、外汇管理等有关部门办理相关手续。外汇管理部门在所颁发的外汇登记证上加注“外商投资股份公司（A股并购）”。如投资者进行战略投资取得单一上市公司25％或以上股份并承诺在10年内持续持股不低于25%的，外汇管理部门在外汇登记证上加注“外商投资股份公司（A股并购25％或以上）”。"},{"i":20,"n":"第二十条","txt":"除以下情形外，投资者不得进行证券买卖（B股除外）： （一）投资者进行战略投资所持上市公司A股股份，在其承诺的持股期限届满后可以出售； （二）投资者根据《证券法》相关规定须以要约方式进行收购的，在要约期间可以收购上市公司A股股东出售的股份； （三）投资者在上市公司股权分置改革前持有的非流通股份，在股权分置改革完成且限售期满后可以出售； （四）投资者在上市公司首次公开发行前持有的股份，在限售期满后可以出售； （五）投资者承诺的持股期限届满前，因其破产、清算、抵押等特殊原因需转让其股份的，经商务部批准可以转让。"},{"i":21,"n":"第二十一条","txt":"投资者减持股份使上市公司外资股比低于25%，上市公司应在10日内向商务部备案并办理变更外商投资企业批准证书的相关手续。 投资者减持股份使上市公司外资股比低于10%，且该投资者非为单一最大股东，上市公司应在10日内向审批机关备案并办理注销外商投资企业批准证书的相关手续。"},{"i":22,"n":"第二十二条","txt":"投资者减持股份使上市公司外资股比低于25%，上市公司应自外商投资企业批准证书变更之日起30日内到工商行政管理机关办理变更登记，工商行政管理机关在营业执照上企业类型调整为“外商投资股份公司（A股并购）”。上市公司应自营业执照变更之日起30日内到外汇管理部门办理变更外汇登记，外汇管理部门在外汇登记证上加注“外商投资股份公司（A股并购）”。 投资者减持股份使上市公司外资股比低于10％，且投资者非为单一最大股东，上市公司自外商投资企业批准证书注销之日起30日内到工商行政管理机关办理变更登记，企业类型变更为股份有限公司。上市公司应自营业执照变更之日起30日内到外汇管理部门办理外汇登记注销手续。"},{"i":23,"n":"第二十三条","txt":"母公司通过其全资拥有的境外子公司进行战略投资并已按期完成的，母公司转让上述境外子公司前应向商务部报告，并根据本办法所列程序提出申请。新的受让方仍应符合本办法所规定的条件，承担母公司及其子公司在上市公司中的全部权利和义务，并依法履行向中国证监会报告、公告及其他法定义务。"},{"i":24,"n":"第二十四条","txt":"投资者通过A股市场将所持上市公司股份出让的，可凭以下文件向上市公司注册所在地外汇局申请购汇汇出： （一）书面申请； （二）为战略投资目的所开立的外国投资者专用外汇账户（收购类）内资金经外汇局核准结汇的核准件； （三）商务部出具的关于上市公司股权结构变更的批复文件； （四）证券经纪机构出具的有关证券交易证明文件。"},{"i":25,"n":"第二十五条","txt":"投资者持股比例低于25%的上市公司，其举借外债按照境内中资企业举借外债的有关规定办理。"},{"i":26,"n":"第二十六条","txt":"相关政府机构工作人员必须忠于职守、依法履行职责，不得利用职务便利牟取不正当利益，并对知悉的商业秘密负有保密义务。"},{"i":27,"n":"第二十七条","txt":"香港特别行政区、澳门特别行政区、台湾地区的投资者进行战略投资，参照本办法办理。"},{"i":28,"n":"第二十八条","txt":"本办法自发布之日起30日后施行。 附件1： 战略投资申请书 一、投资者名称 二、目标上市公司名称 三、投资意向 （投资者及授权代表签章） 年　月　日 附件2： 战略投资方案 一、投资者名称及自身情况简介（母公司通过其全资拥有的境外子公司进行战略投资的还应提供母公司的相关材料） 二、目标上市公司名称、经营范围，拟取得公司股份的具体方式、拟取得的股份数量及取得后占上市公司已发行股份的比例、战略投资时限 三、持续持股期限 四、投资者与目标上市公司控股股东的关联关系说明 （投资者及授权代表签章） 年　月　日"}],"waipailaowurenyuanpeixungongzuoguanliguiding":[{"i":1,"n":"第一条","txt":"为加强对我国外派劳务人员培训工作的管理，提高我国外派劳务人员素质，促进对外劳务合作业务发展，特制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称“外派劳务人员培训”，是指具有对外经济合作业务经营资格（以下简称“经营资格”）的企业拟派出的各类劳务人员（包括劳务性质的研修生等，下同）在出国（境）前应接受的适应性培训。"},{"i":3,"n":"第三条","txt":"本规定所称的“外派劳务人．员培训中心”（以下简称“培训中心”）是指经对外贸易经济合作部（以下简称“外经贸部”）核准的具有外派劳务培训、考核资格的单位。"},{"i":4,"n":"第四条","txt":"外经贸部归口管理全国的外派劳务培训工作；各省、自治区、直辖市及计划单列市外经贸委（厅、局）（以下简称“省级地方外经贸主管部门”）负责归口管理本地区的外派劳务培训工作。中央大型企业工作委员会管理的企业（以下简称“中央企业”）负责管理本企业的外派劳务培训工作。中国对外承包工程商会（以下简称“承包商会”）依照外经贸部制订的有关规定和政策，具体负责协调、指导培训中心的工作。"},{"i":5,"n":"第五条","txt":"设立培训中心，应由地方外经贸主管部门或中央企业逐级申请。各级地方外经贸主管部门和中央企业可根据本地区、本企业对外劳务合作业务的开展情况和外派劳务培训工作的需要，利用社会或本部门、本企业现有的培训设施和教学条件，申请设立由其直接管理的综合性或专业（行业）性的培训中心，或申请赋予现有培训单位外派劳务培训资格（以下统简称“申请设立培训中心”）。其它单位或企业原则上不能申请设立培训中心。"},{"i":6,"n":"第六条","txt":"省级地方外经贸主管部门或中央企业应依据本规定的标准，会同有关部门组成联合核查组，对本地区（本企业）培训中心的情况进行核查，经核查符合标准的，方可报外经贸部申请核准。 省级地方外经贸主管部门根据外经贸部的核准文件向培训中心颁发《外派劳务人员（研修生）培训资格证书》（以下简称“《资格证书》”。 未经外经贸部核准，任何单位不具备外派劳务培训资格。外经贸部授权省级地方外经贸主管部门负责对本地区（包括中央企业）的培训中心进行《外派劳务人员（研修生）培训资格证书》的年度审核和管理工作。《资格证书》管理办法另行制订、颁布。"},{"i":7,"n":"第七条","txt":"地方外经贸主管部门申请设立培训中心，本地区年外派劳务人数应连续两年超过1000人次；中央企业申请设立培训中心，年外派劳务人数应连续两年超过1500人次。西部省区和距离现有培训中心较远、交通不便的地区，若年外派劳务人数连续两年超过200人次，可申请设立培训中心。原则上每个地级及地级以下城市最多只核准一家培训中心，省会城市不超过两家，直辖市和计划单列市不超过四家。如果地级及地级以下城市年外派人数超过3000人次，省会城市年外派人数超过6000人次，直辖市和计划单列市年外派人数超过10000人次，可在上述基数上适当增加。 外经贸部根据各地区和各中央企业历年来外派劳务情况，按照既满足培训业务需要、又保证各培训中心生源的原则，兼顾行业与地域优势，统筹规划全国培训中心的布局，并根据各地区和各中央企业外派劳务业务的发展情况及时进行调整，实行动态管理。"},{"i":8,"n":"第八条","txt":"培训中心应具备的条件 一、拥有固定的培训场所和培训设施，可同时培训1OO人以上。 二、拥有熟悉对外劳务合作业务及政策、具备良好政治素质、职业道德和较高教学水平的专、兼职教师队伍。原则上专职教师人数应不少于3人，并有明确的教学分工。 三、拥有保证外派劳务培训工作正常运行的管理人员和规章制度。 四、拥有适应国际劳务市场需求变化、及时调整培训方向和培训方式的能力。"},{"i":9,"n":"第九条","txt":"申请设立培训中心需向外经贸部报送的材料： 一、申请报告； 二、培训中心情况介绍（包括培训中心的组织机构、教学设施、师资情况、专业构成及培训实绩等）； 三、省级地方外经贸主管部门或中央企业的核查报告； 四、本地区或本企业外派劳务情况（包括累计派出人数、近两年外派劳务人数、目前在外人数、分布情况及前景分析等）。"},{"i":10,"n":"第十条","txt":"培训的内容 一、我国对外劳务合作方面的法律、法规和规定。 二、安全保密、外事纪律、涉外礼仪等方面的出国常识。 三、派出单位与国外雇主、劳务人员所签合同的内容与条款的具体含义。 四、从事国（境）外劳务工作应承担的义务和享有的权利及正确处理与外方雇主的关系、提高服务意识、保证工作质量、依法履行合同和正当保护自身合法权益等。 五、派往国家（地区）的政治、经济、人文、地理等方面的情况。 六、派往国家（地区）的有关法律、宗教，民俗等方面的情况，特别要提高对带有反动性质的外国宗教势力和邪教组织的鉴别与抵制有力。 七、语言、专业技能及其他需要培训的内容。"},{"i":11,"n":"第十一条","txt":"培训教材 一、培训教材包括公共课教材、语言培训教材和专业技能教材。 二、公共课、语言培训课的教材、教学大纲和考核大纲由承包商会根据外经贸部制订的标准和要求，统一组织编写和修订。专业技能教材，各培训中心可根据我国或派往国家有关技术标准及国外业主的要求编写。根据培训工作的需要，外经贸部委托承包商会或其它单位组织编写专业技能补充教材。 三、各培训中心应严格执行外经贸部审定的教学大纲和考核大纲。在实施培训中，公共课必须使用统编教材，外派劳务人员要人手一册。非公共课教材，各培训中心可根据外派劳务项目的实际需要自行选编。"},{"i":12,"n":"第十二条","txt":"具有初级以上职称（含初级职称）从事技术劳务的，如已熟练掌握拟派往国家（地区）的官方语言或相应技术，凭外语考试证书（成绩表）或技术职称证书，可不进行外语培训或技能培训，只进行规定时间内的公共课程培训。"},{"i":13,"n":"第十三条","txt":"培训时间 一、公共课程内容的培训一般不得少于40个课时； 二、语言培训时间应根据劳务人员拟派往国家企业提出的标准进行安排，如外语水平未达到第十二条所述标准，至少需进行40个课时的简单生活用语和工作用语的强化培训； 三、专业技能的培训时间，由外派单位根据劳务人员的技术情况和国外雇主的要求与培训中心协商确定。"},{"i":14,"n":"第十四条","txt":"培训地点 为减轻劳务人员的经济负担，劳务人员应尽可能就地、就近培训。一般情况下，不得跨省（市）或中央企业培训。"},{"i":15,"n":"第十五条","txt":"培训中心的师资和教学 一、各培训中心的教师应具备相应的学历，专业技能课教师应具有相应的实践经验。对于培训经验丰富、教学质量较高的教师，学历要求可适当放宽。 二、各培训中心的教师应根据教学大纲和培训计划的要求搞好教学工作，并根据外派劳务的特点进行教学研究，改进教学方法，提高培训质量。 三、承包商会应不定期组织培训中心的师资培训和教学经验交流会；并配合外经贸部对部分培训中心业务进行年度评估。对评估结果较差的培训中心，外经贸部按本文有关规定进行处理。 四、各培训中心可充分利用网络培训方式，大力发挥兼职教师的作用，以适应外派劳务培训多专业、多层次的特点。 五、各培训中心应不断完善管理系统，建立健全教学管理、考核和教学质量检查评估制度，建立培训人员档案。"},{"i":16,"n":"第十六条","txt":"考试 为保证培训质量，参加培训的外派劳务人员，应在规定的培训时间内接受所有规定培训内容的培训。培训结束时，培训中心必须 按考核大纲对劳务人员进行考试；对考试不合格者，不能发给资格证书。"},{"i":17,"n":"第十七条","txt":"各培训中心应树立良好的服务意识，与本地区内有经营资格的企业保持经常性联系，接受他们的培训委托，并努力保证培训质量，严禁“走过场”。"},{"i":18,"n":"第十八条","txt":"培训中心的办公经费及人员工资、福利待遇等，可按其隶属关系由所属部门解决，也可采取自筹自支的方式解决。"},{"i":19,"n":"第十九条","txt":"各培训中心应根据专款专用的原则合理使用国家、地方的专项拨款及社会的捐助款。"},{"i":20,"n":"第二十条","txt":"外派劳务人员的培训费用原则上应自行负担，承包工程项下派出的劳务人员可由派出单位负担。各培训中心收取培训费的标准必须符合外经贸部的有关规定，严禁乱收费。"},{"i":21,"n":"第二十一条","txt":"《外派劳务（研修生）培训合格证》（以下简称“《合格证》”）是外派劳务人员的资格证明，是外派劳务人员办理出国（境）手续的证明文件之一。"},{"i":22,"n":"第二十二条","txt":"《合格证》由外经贸部统一监制。外经贸部委托省级外经贸主管部门审核、发放其所属培训中心的《合格证》和本地方行政区域内中央企业培训中心的《合格证》，委托北京市外经 贸委审核、发放在京各中央企业培训中心的《合格证》。"},{"i":23,"n":"第二十三条","txt":"《合格证》须在照片处加盖“中国外派劳务培训（）号”钢印、并由外经贸部委托的审核部门在第4页盖章后生效。地方培训中心的《合格证》加盖省级外经贸主管部门的公章，中央企业培训中心的《合格证》加盖所在地省级外经贸主管部门的公章。"},{"i":24,"n":"第二十四条","txt":"各培训中心申请发放《合格证》时，须填写《外派劳务（研修生）培训合格人员送审表》（民以下简称《送审表》，样式见附件）一式二份，与《合格证》一并送外经贸部委托审核部门审核。外经贸部委托审核部门须在收到《送审表》后的二个工作日内完成审核。"},{"i":25,"n":"第二十五条","txt":"《合格证》的收费标准由外经贸部商财政部制订，任何部门不得以任何理由加价。"},{"i":26,"n":"第二十六条","txt":"《合格证》的有效期 一、《合格证》的有效期为三年，根据劳务合同需要，可适当延长。 二、在《合格证》有效期内，如果劳务人员派往《合格证》规定以外的国家（地区），在接受相应的国别（地区）概况和语言培训后，可申请办理新的《合格证》。 三、有效期满后二年内派往同一国家（地区），可凭原《合格证》和派出单位证明办理新的《合格证》，超过二年需重新接受培训。"},{"i":27,"n":"第二十七条","txt":"外派劳务人员出国（境）后必须妥善保存《合格证》，可视情况向国（境）外雇主和单位出示，不得出售、伪造或挪作它用。 如《合格证》遗失，应立即凭个人申请、派出单位证明及《送审表》向原培训中心申请补办，并在补办的《合格证》上注明遗失补办，有效期为原《合格证》有效期。"},{"i":28,"n":"第二十八条","txt":"《合格证》由承包商会代部发放。各培训中心可直接向承包商会购买，也可委托地方外经贸主管部门统一订购。"},{"i":29,"n":"第二十九条","txt":"各培训中心应以提高外派劳务人员的素质为宗旨，不得以盈利为目的，要严格遵守国家有关法律、法规和政策，在培训过程中认真执行外经贸部审定的教学大纲和考核大纲，保证培训质量。"},{"i":30,"n":"第三十条","txt":"在从事外派劳务人员培训工作中，持证单位有以下行为之一者，外经贸部将给予警告处分： 一、违反培训工作的有关规定； 二、不服从或逃避省级外经贸主管部门和承包商会的管理或协调； 三、年培训人数过少（200人次以下）： 四、无特殊理由，逾期6个月不办理申领或更换《资格证书》手续。"},{"i":31,"n":"第三十一条","txt":"在从事外派劳务培训过程中，持证单位有以下行为之一者，外经贸部将暂停其外派劳务人员培训资格： 一、违反培训工作的有关规定，给国家、企业或劳务人员的利益带来损害； 二、不服从省级外经贸主管部门和承包商会的管理或协调，扰乱了培训工作的正常秩序； 三、培训中心管理不善，培训制度不健全，培训流于形式、走过场； 四、培训工作开展不力（连续两年培训不足200人）： 五、逾期一年不办理申领或更换《资格证书》手续； 六、违反外派劳务培训收费的有关规定，巧立名目高收费、乱收费。"},{"i":32,"n":"第三十二条","txt":"在从事外派劳务培训过程中，持证单位有以下行为之一者，外经贸部将吊销其外派劳务人员培训资格： 一、严重违反培训工作的有关规定，给国家、企业或劳务人员的利益带来严重损害； 二、不服从省级外经贸主管部门和承包商会的管理或协调，干扰、破坏了外派劳务业务和外派劳务培训工作的正常秩序； 三、弄虚作假、倒卖或变相倒卖《合格证》； 四、受到警告、暂停培训资格处罚后，培训工作仍达不到有关规定要求。"},{"i":33,"n":"第三十三条","txt":"省级外经贸主管部门和承包商会应经常监督、检查和指导培训中心的工作，及时将培训工作中存在的问题、解决意见和改进培训工作的建议报外经贸部。"},{"i":34,"n":"第三十四条","txt":"本规定自二○○二年二月一日起实施，〔1996〕外经贸合发第101号文同时废止。外经贸部以往有关外派劳务培训的文件与本规定不相一致的内容一律以本规定为准。"}],"daxingdanjihechengtaoshebeichukouxiangmuxietiaoguad86c87":[{"i":1,"n":"第一条","txt":"为了进一步促进大型单机和成套设备出口健康、持续和稳定的发展，规范、加强大型单机和成套设备出口项目的管理，建立和维护正常的出口秩序，有效防范和控制项目风险，维护国家利益和企业的合法权益，推动有实力的企业;走出去\"参与国际竞争，根据《中华人民共和国对外贸易法》和外经贸部、财政部、中国人民银行《关于大型出口信贷及出口信用保险项目的报批程序》（外经贸机电发〔2001〕282号），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称大型单机和成套设备出口项目是指境外大型单机和成套设备的国际公开招标、邀请招标和议标项目，其内容包括设备供应、工艺设计、技术转让、安装调试指导、零配件供应、售后维修及其他相应的服务。"},{"i":3,"n":"第三条","txt":"本办法所称大型单机出口项目指金额在1百万美元以上（含1百万美元）的项目，成套设备出口项目指金额在2百万美元以上（含2百万美元）的项目。"},{"i":4,"n":"第四条","txt":"外经贸部负责大型单机和成套设备出口项目协调的管理和监督。"},{"i":5,"n":"第五条","txt":"中国机电产品进出口商会（以下简称机电商会）和中国对外承包工程商会（以下简称承包商会）依照国家和外经贸部的有关法律法规和规章对大型单机和成套设备出口项目进行协调，并为出口企业提供咨询、指导和服务。各商会的具体协调工作接受外经贸部的管理、指导和监督。"},{"i":6,"n":"第六条","txt":"有关商会协调职能的划分，原则按照外经贸部《关于对机电商会和承包商会项目协调职能进行重新分工意见的函》（〔1999〕外经贸办字第72号）的规定执行，即对于涉及成套设备出口的工业项目，由机电商会协调；对于涉及成套设备出口的非工业项目，由承包商会协调。"},{"i":7,"n":"第七条","txt":"本办法所称经营者是指：在中华人民共和国境内登记注册的具有大型单机和成套设备出口项目经营资格的企业法人。"},{"i":8,"n":"第八条","txt":"经营者开展项目经营活动必须严格遵照国家和外经贸部的有关法律、法规，依法经营，不得危害国家安全，损害国家和同行业企业的合法权益；遵守项目所在国家或地区的法律法规和风俗习惯；自觉接受有关商会的协调。"},{"i":9,"n":"第九条","txt":"本办法所称经营资格是指从事大型单机和成套设备出口项目的经营者必须具备以下条件： （一）具有工商行政管理部门核发的企业法人营业执照； （二）具有外经贸经营权； （三）具有与项目金额相适应的注册资本，资信情况并且经营情况良好； （四）通过ISO9000认证； （五）具有开展大型单机和成套设备出口项目所需的专业技术人员，组织机构健全，规章制度完善； （六）具有大型单机和成套设备出口项目的业绩或参与过相应的国内外大型单机和成套设备出口项目的经营活动； （七）具有大型单机和成套设备出口项目所需的融资能力； （八）符合国家和外经贸部有关法律法规和规章规定的其他条件； （九）为有关商会会员。"},{"i":10,"n":"第十条","txt":"本办法所称大型单机和成套设备出口项目的协调须遵循以下原则： （一）公开、公平、公正； （二）维护国家利益和正常的出口秩序； （三）保护市场开拓者的利益； （四）有利于提高我国公司的中标率； （五）有利于推动我国公司提高其经济效益； （六）提倡\"强强联合\"的组合方式，各企业利益共享，风险共担； （七）在同一项目中，两个经营者不得选择国内的同一家勘察、设计或安装施工单位，也不得选择国外的同一代理商； （八）促进合作、统一对外，建立优先分包、利益补偿的机制； （九）保护项目合同中各方的合法权益。"},{"i":11,"n":"第十一条","txt":"拟参加大型单机和成套设备出口项目的经营者，必须向有关商会申报项目。"},{"i":12,"n":"第十二条","txt":"经营者申报项目，招标项目应在对外投标截标日60日前；议标项目应在与国外业主签订会谈纪要或合作协议后的20日内。"},{"i":13,"n":"第十三条","txt":"经营者申报项目时应当提供以下材料： （一）项目申请报告； （二）《大型单机和成套设备出口项目申报表》； （三）与客户商谈的情况、项目的技术要求说明； （四）与客户签订的意向书、会谈纪要、备忘录等文件； （五）涉及国家限制出口技术的项目，提交《中华人民共和国技术出口许可意向书》； （六）涉及国家秘密技术的项目，提交《国家秘密技术出口保密审查批准书》； （七）涉及国家需出具最终用户或最终用途证明再出口的项目，提交批准文件； （八）经营资格证明的复印件； （九）项目所需的其他相关文件。"},{"i":14,"n":"第十四条","txt":"有关商会在规定的项目申报时间截止日期后的20个工作日内，认真审核经营者的申报材料，征求有关方面和专家的意见，根据协调原则对经营者参与项目的资格进行确认，提出协调意见并函告项目经营者，同时抄报外经贸部、驻外使馆经商处等有关单位备案。"},{"i":15,"n":"第十五条","txt":"对需我国提供出口信贷及出口信用保险的大型单机和成套设备出口项目，有关商会的协调意见函须抄报有关银行和保险机构。有关银行和保险机构根据有关商会的协调意见，按照出口信贷和出口信用保险管理的有关规定评估，对符合要求的经营者出具承贷意向书和承保意向书。"},{"i":16,"n":"第十六条","txt":"参与项目协调的有关工作人员应该严守职业道德和协调纪律，照章办事，增强服务意识，提高服务质量。在项目协调过程中玩忽职守、徇私舞弊、滥用职权、泄露项目中的商业机密的，由有关部门给予其相应的行政处分，构成犯罪的，由司法机关依法追究其法律责任。"},{"i":17,"n":"第十七条","txt":"经营者应该严格执行有关商会的协调意见。经营者对有关商会的协调意见如有异议，可在协调意见作出的15日内向外经贸部递交申请书提出申诉。外经贸部依据有关法律、法规和协调原则，在收到申请书之日起10个工作日内对申诉作出裁定。裁定一经送达即发生效力，申诉人和有关商会必须遵守。经营者在申诉期间仍须执行有关商会的协调意见。"},{"i":18,"n":"第十八条","txt":"经营者对外经贸部作出的裁定不服的，可依法提起行政诉讼。"},{"i":19,"n":"第十九条","txt":"经营者有下述行为之一的，视作违纪行为： （一）不按规定申报或不接受协调而擅自参与项目的； （二）不执行有关商会协调意见又未在规定期限提出申诉及不执行裁定意见而擅自参与项目的； （三）对外泄露有关商会协调内容及相关情况的； （四）采取不正当竞争行为，损害国家和其他经营者利益的； （五）有违反协调程序行为的； （六）其他违反国家和外经贸部有关法律、法规的行为。"},{"i":20,"n":"第二十条","txt":"对有违反有关规定行为的经营者经有关商会查实上报后，外经贸部按《行政处罚法》和《中华人民共和国货物进出口管理条例》视情节对该经营者给予警告、罚款、暂停项目参与资格、暂停或取消其大型单机和成套设备出口项目经营资格、暂停或取消其外经贸经营权的处罚。"},{"i":21,"n":"第二十一条","txt":"对有违反有关规定行为的经营者，商会应将相关情况及时通报有关银行和保险机构，银行和保险机构不得为该经营者出具项目承贷意向书和承保意向书。"},{"i":22,"n":"第二十二条","txt":"有关商会根据本办法制定项目协调实施细则和单项实施细则，报外经贸部批准后实施。"},{"i":23,"n":"第二十三条","txt":"本办法由外经贸部负责解释。"},{"i":24,"n":"第二十四条","txt":"本办法自发布之日起施行。外经贸部以前制定的关于大型单机和成套设备出口项目协调管理的有关规定同时废止。"}],"dazongnongchanpinjinkoubaogaohexinxifabuguanlibanf16b1b6":[{"i":1,"n":"第一条","txt":"为了维护对外贸易秩序，保护经营者的合法权益，提供大宗农产品进口信息服务，根据《中华人民共和国对外贸易法》(以下简称《外贸法》)、《中华人民共和国货物进出口管理条例》（以下简称《货物进出口条例》）及其他有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称大宗农产品系指生产量、消费量、贸易量、运输量等较大的关系国计民生的农产品。"},{"i":3,"n":"第三条","txt":"商务部会同有关部门制定、调整《实行进口报告管理的大宗农产品目录》（以下简称《目录》）。"},{"i":4,"n":"第四条","txt":"商务部委托有关组织（以下简称受委托组织）负责大宗农产品进口报告信息的收集、整理、汇总、分析和核对等日常工作。"},{"i":5,"n":"第五条","txt":"进口《目录》项下大宗农产品的对外贸易经营者(以下简称对外贸易经营者)，应向受委托组织办理本企业基本情况备案。 备案内容包括：对外贸易经营者名称、企业海关代码、对外贸易经营者备案登记表复印件、工商营业执照复印件、法定代表人和统计负责人姓名与签字等。"},{"i":6,"n":"第六条","txt":"对外贸易经营者应填报《大宗农产品进口报告统计报表》（格式见附件），报告事项主要包括：对外贸易经营者、联系人、联系方式、商品名称、商品编码、贸易方式、贸易国（地区）、原产地国（地区）、合同号、合同数量、合同船期、装运港、预计抵港时间、实际船期、装船数量、进口报关口岸、进口数量和实际抵港日期等。 对外贸易经营者应通过相应电子报告系统向受委托组织进行报告。如无法通过电子方式报告，可下载报表传真报告。"},{"i":7,"n":"第七条","txt":"对外贸易经营者应在下述情况发生后三个工作日内履行进口报告义务： 1、签订进口合同； 2、货物在装运港出运； 3、货物抵达目的港； 4、报告事项发生变更。"},{"i":8,"n":"第八条","txt":"对外贸易经营者应严格遵守规定，及时、准确报告有关进口信息，并对报告内容的真实性负责，不得虚报、瞒报、伪造、篡改、迟报和拒报。"},{"i":9,"n":"第九条","txt":"受委托组织应向商务部报告大宗农产品进口的信息情况，并提出建议。"},{"i":10,"n":"第十条","txt":"商务部定期在商务部政府网站“大宗农产品进口信息发布专栏”对外发布《目录》项下大宗农产品进口信息。 发布内容为：预计进口数量、预计货物到港时间、实际装船时间、实际装船数量、装运港、原产地国（地区）、主要口岸进口情况等。"},{"i":11,"n":"第十一条","txt":"受委托组织根据海关、质检相关数据核对大宗农产品对外贸易经营者报告情况，向商务部报告结果。"},{"i":12,"n":"第十二条","txt":"对外贸易经营者违反本规定，虚报、瞒报、伪造、篡改、迟报和拒报大宗农产品有关进口信息的，商务部应向国家统计局通报。 统计部门依法对违法对外贸易经营者处以行政处罚后，商务部可以禁止违法对外贸易经营者自行政处罚决定生效之日起一年以上三年以下的期限内从事有关的对外贸易经营活动。"},{"i":13,"n":"第十三条","txt":"对外贸易经营者违反本规定的，商务部按照《对外贸易经营者违法违规行为公告办法》的规定发布公告，并通知海关、税务、质检、外汇、工商等部门以及地方商务主管部门、行业中介组织、银行等单位。"},{"i":14,"n":"第十四条","txt":"任何单位和个人可向商务部举报对外贸易经营者虚假报告进口信息的行为。"},{"i":15,"n":"第十五条","txt":"商务部及受委托组织有关人员应当为履行进口信息报告义务的对外贸易经营者保守商业秘密，不得向任何企业、机构和个人透露对外贸易经营者报告的信息。违反上述规定的，依照《外贸法》第六十五条及《货物进出口条例》第七十条进行处罚。"},{"i":16,"n":"第十六条","txt":"本办法适用于《目录》项下以各种贸易方式进行的大宗农产品进口交易，包括由境外进入保税仓库、保税区、保税港区和出口加工区等。"},{"i":17,"n":"第十七条","txt":"《目录》、受委托组织名称以及大宗农产品进口信息发布周期由商务部以公告形式发布。"},{"i":18,"n":"第十八条","txt":"本办法由商务部负责解释。"},{"i":19,"n":"第十九条","txt":"本办法自2008年8月1日起实施。"}],"jiatingfuwuyeguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了满足家庭服务消费需求，维护家庭服务消费者、家庭服务人员和家庭服务机构的合法权益，规范家庭服务经营行为，促进家庭服务业发展，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事家庭服务活动，适用本办法。 本办法所称家庭服务业，是指以家庭为服务对象，由家庭服务机构指派或介绍家庭服务员进入家庭成员住所提供烹饪、保洁、搬家、家庭教育、儿童看护以及孕产妇、婴幼儿、老人和病人的护理等有偿服务，满足家庭生活需求的服务行业。 本办法所称家庭服务机构，是指依法设立从事家庭服务经营活动的企业、事业、民办非企业单位和个体经济组织等营利性组织。 本办法所称家庭服务员，是指根据家庭服务合同的约定提供家庭服务的人员。 本办法所称消费者，是指接受家庭服务的对象。"},{"i":3,"n":"第三条","txt":"家庭服务的经营和管理，应当坚持社会效益与经济效益并重的原则。家庭服务各方当事人应当遵循自愿、平等、诚实、守信、安全和方便的原则。"},{"i":4,"n":"第四条","txt":"商务部承担全国家庭服务业行业管理职责，负责监督管理家庭服务机构的服务质量，指导协调合同文本规范和服务矛盾纠纷处理工作。县级以上商务主管部门负责本行政区域内家庭服务业的监督管理。"},{"i":5,"n":"第五条","txt":"县级以上商务主管部门引导和支持家庭服务机构运用现代流通方式，培育示范性家庭服务机构，提升行业规范化经营水平。"},{"i":6,"n":"第六条","txt":"国家鼓励公益性家庭服务信息平台的建设，扶持中小家庭服务机构发展，采取各项措施促进行业规范发展。"},{"i":7,"n":"第七条","txt":"家庭服务行业协会应当制定行业规范，加强行业自律，为会员企业提供服务，维护会员企业的合法权益，建立服务纠纷调解处理机构，调解处理家庭服务纠纷。"},{"i":8,"n":"第八条","txt":"家庭服务机构从事家庭服务活动需取得工商行政管理部门颁发的营业执照。"},{"i":9,"n":"第九条","txt":"家庭服务机构应在经营场所醒目位置悬挂有关证照，公开服务项目、收费标准和投诉监督电话。"},{"i":10,"n":"第十条","txt":"家庭服务机构须建立家庭服务员工作档案，接受并协调消费者和家庭服务员投诉，建立家庭服务员服务质量跟踪管理制度。"},{"i":11,"n":"第十一条","txt":"家庭服务机构应按照县级以上商务主管部门要求及时准确地提供经营档案信息。"},{"i":12,"n":"第十二条","txt":"家庭服务机构在家庭服务活动中不得有下列行为： （一）以低于成本价格或抬高价格等手段进行不正当竞争； （二）不按服务合同约定提供服务； （三）唆使家庭服务员哄抬价格或有意违约骗取服务费用； （四）发布虚假广告或隐瞒真实信息误导消费者； （五）利用家庭服务之便强行向消费者推销商品； （六）扣押、拖欠家庭服务员工资或收取高额管理费，以及其他损害家庭服务员合法权益的行为； （七）扣押家庭服务员身份、学历、资格证明等证件原件。 （八）法律、法规禁止的其他行为。"},{"i":13,"n":"第十三条","txt":"从事家庭服务活动，家庭服务机构或家庭服务员应当与消费者以书面形式签订家庭服务合同。"},{"i":14,"n":"第十四条","txt":"家庭服务合同应至少包括以下内容： （一）家庭服务机构的名称、地址、负责人、联系方式和家庭服务员的姓名、身份证号码、健康状况、技能培训情况、联系方式等信息；消费者的姓名、身份证号码、住所、联系方式等信息； （二）服务地点、内容、方式和期限等； （三）服务费用及其支付形式； 四）各方权利与义务、违约责任与争议解决方式等。"},{"i":15,"n":"第十五条","txt":"家庭服务机构应当明确告知涉及家庭服务员利益的服务合同内容，应允许家庭服务员查阅、复印家庭服务合同，保护其合法权益。"},{"i":16,"n":"第十六条","txt":"鼓励家庭服务机构为家庭服务员投保职业责任保险和人身意外伤害保险。"},{"i":17,"n":"第十七条","txt":"鼓励家庭服务机构加入家庭服务行业协会，自觉遵守行业自律规范。"},{"i":18,"n":"第十八条","txt":"家庭服务机构、家庭服务员与消费者之间发生争议的，可以协商解决；协商不成的，可以向人民调解委员会、行业协会调解机构或其他家庭服务纠纷调解组织申请调解，也可以依法提请仲裁或者向人民法院提起诉讼。"},{"i":19,"n":"第十九条","txt":"家庭服务员应当如实向家庭服务机构提供本人身份、学历、健康状况、技能等证明材料，并向家庭服务机构提供真实有效的住址和联系方式。"},{"i":20,"n":"第二十条","txt":"家庭服务员应符合以下基本要求： （一）遵守国家法律、法规和社会公德； （二）遵守职业道德； （三）遵守合同，按照合同约定内容提供服务； （四）掌握相应职业技能，具备必需的职业素质。"},{"i":21,"n":"第二十一条","txt":"家庭服务员在提供家庭服务过程中与消费者发生纠纷，应当及时向家庭服务机构反映，不得擅自离岗。"},{"i":22,"n":"第二十二条","txt":"消费者有下列情形之一的，家庭服务员可以拒绝提供服务： （一）不能提供合同约定的工作条件的； （二）对家庭服务员有虐待或严重损害人格尊严行为的； （三）要求家庭服务员从事可能对其人身造成损害行为的； （四）要求家庭服务员从事违法犯罪行为的。"},{"i":23,"n":"第二十三条","txt":"消费者到家庭服务机构聘用家庭服务员时，应持有户口簿或身份证及相关证明，并如实填写登记表，交纳有关费用。 消费者或其家庭成员患有传染病、精神病或其他重要疾病的，应当告知家庭服务机构和家庭服务员，并如实登记。"},{"i":24,"n":"第二十四条","txt":"消费者有权要求家庭服务机构按照合同约定指派或介绍家庭服务员和提供服务，消费者有权要求家庭服务机构如实提供家庭服务员的道德品行、教育状况、职业技能、相关工作经历、健康状况等个人信息。"},{"i":25,"n":"第二十五条","txt":"消费者应当保障家庭服务员合法权益，尊重家庭服务员的人格和劳动，按约定提供食宿等条　件，保证家庭服务员每天基本睡眠时间和每月必要休息时间，不得对家庭服务员有谩骂、殴打等侵权行为，不得拖欠、克扣家庭服务员工资，不得扣押家庭服务员身份、学历、资格证明等证件原件。 未经家庭服务员同意，消费者不得随意增加合同以外的服务项目，如需增加须事先与家庭服务机构、家庭服务员协商，并适当增加服务报酬。"},{"i":26,"n":"第二十六条","txt":"商务部建立家庭服务业信息报送系统。家庭服务机构应按要求及时报送经营情况信息，具体报送内容由商务部另行规定。"},{"i":27,"n":"第二十七条","txt":"设区的市级以上商务主管部门应当建设完善家庭服务网络中心，免费提供家庭服务信息，加强从业人员培训，规范市场秩序，推进家庭服务体系建设，促进家庭服务消费便利化和规范化。"},{"i":28,"n":"第二十八条","txt":"县级以上商务主管部门建立健全家庭服务机构信用档案和客户服务跟踪监督管理机制，建立完善家庭服务机构和家庭服务员信用评价体系。"},{"i":29,"n":"第二十九条","txt":"县级以上商务主管部门积极会同相关部门，依法规范家庭服务机构从业行为，查处违法经营行为。"},{"i":30,"n":"第三十条","txt":"县级以上商务主管部门指导制定家庭服务合同范本，指导协调服务纠纷处理工作。"},{"i":31,"n":"第三十一条","txt":"县级以上商务主管部门应当公布有关家庭服务业的举报、投诉渠道和方式，接受相关当事人的举报、投诉。对于属于职责范围内的举报、投诉，应当在15日内依法处理；对于不属于职责范围的，应当移交有权处理的行政机关处理。"},{"i":32,"n":"第三十二条","txt":"家庭服务机构违反本办法第九条规定，未公开服务项目、收费标准和投诉监督电话的，由商务主管部门责令改正；拒不改正的，可处5000元以下罚款。"},{"i":33,"n":"第三十三条","txt":"家庭服务机构违反本办法第十条规定，未按要求建立工作档案、跟踪管理制度，对消费者和家庭服务员之间的投诉不予妥善处理的，由商务主管部门责令改正；拒不改正的，可处2万元以下罚款。"},{"i":34,"n":"第三十四条","txt":"家庭服务机构违反本办法第十一条、第二十六条规定，未按要求提供信息的，由商务主管部门责令改正；拒不改正的，可处1万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"家庭服务机构有本办法第十二条规定行为的，由商务主管部门或有关主管部门责令改正；拒不改正的，属于商务主管部门职责的，可处3万元以下罚款，属于其他部门职责的，由商务主管部门提请有关主管部门处理。"},{"i":36,"n":"第三十六条","txt":"家庭服务机构违反本办法第十三条、第十四条、第十五条规定，未按要求订立家庭服务合同的，拒绝家庭服务员获取家庭服务合同的，由商务主管部门或有关部门责令改正；拒不改正的，可处3万元以下罚款。"},{"i":37,"n":"第三十七条","txt":"商务主管部门在家庭服务业监督管理工作中，玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"省、自治区、直辖市商务主管部门可结合本地实际情况制定实施细则。"},{"i":39,"n":"第三十九条","txt":"本办法自2013年2月1日起施行。"}],"jiadianweixiufuwuyeguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范家电维修服务业市场经营秩序，维护家电维修服务经营者和消费者的合法权益，促进行业健康发展，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事家电维修服务经营活动，适用本办法。 本办法所称家电是指可用于家庭的，为了生活、娱乐及获取信息等目的使用的电子或电器产品。包括制冷空调器具、清洁器具、厨房器具、通风器具、取暖熨烫器具、个人护理器具、保健器具、娱乐器具等电器产品和音像娱乐类、信息技术类等电子产品。 本办法所称家电维修服务经营者（以下简称家电维修经营者）是指提供家电维护保养、故障修理、使用咨询指导等服务的法人、其他经济组织和个人。"},{"i":3,"n":"第三条","txt":"商务部负责家电维修服务业的行业管理工作，各级商务主管部门负责本行政区域内的家电维修服务业的指导、协调和监督管理工作。"},{"i":4,"n":"第四条","txt":"家电维修经营者及从业人员应当遵守国家有关法律、法规和标准。 家电维修从业人员应当具备从事相应维修活动的职业、技术资质。从事高处作业、焊接与热切割作业、制冷与空调作业、电工作业、危险化学品安全作业等特种作业的人员，应具备国家规定的特种作业资格，执证上岗。涉及特种作业的家电维修经营者，其负责人和安全管理人员，须进行相关安全责任培训。 家电维修经营者应当配备相应质量合格的作业设备和劳动保护用具。"},{"i":5,"n":"第五条","txt":"家电维修经营者应在经营场所显著位置悬挂营业执照，明示服务项目和家电配件的收费标准、质量规范、质保期限以及投诉电话。 家电维修经营者从事特约维修，须取得商标权人授权，并在经营场所显著位置明示有效期内的授权证明。获得授权的家电维修经营者应在其被授权范围内提供维修服务。"},{"i":6,"n":"第六条","txt":"家电维修经营者应通过企业互联网站、电话等形式向消费者提供本企业维修服务人员身份资质查验，应为上岗工作人员配制职业资质标识，要求在岗工作时佩戴或向消费者出示。"},{"i":7,"n":"第七条","txt":"家电维修经营者在提供维修服务前应当向消费者明确告知维修方案及需注意和配合的事项，尊重消费者选择。 家电维修经营者在提供维修服务时应当向消费者提供维修服务凭证和收费发票。维修服务凭证应如实填写维修服务项目、维修详细情况、维修服务质量责任及注意事项等内容。"},{"i":8,"n":"第八条","txt":"家电维修经营者在维修服务中获得的机关、企（事）业单位及个人信息不得用于与维修活动无关的领域，对于知悉的商业秘密、个人隐私负有保密义务。"},{"i":9,"n":"第九条","txt":"家电维修经营者和从业人员应恪守职业道德，不得有下列行为： （一）虚列、夸大、伪造维修服务项目或内容； （二）隐瞒、掩饰因维修服务导致用户产品损毁的事实； （三）虚报故障部件，故意替换性能正常的部件； （四）冒用家电生产者商标或特约维修标识。"},{"i":10,"n":"第十条","txt":"家电维修经营者在维修服务中发现同一品牌、类型或批次的家电存在安全、质量问题的，应及时通报生产者、销售者，并向所在地县级商务主管部门报告。"},{"i":11,"n":"第十一条","txt":"家电维修经营者在维修服务中使用和销售的配件和耗材，其质量、规格应符合国家有关产品质量安全规定和标准，不得使用和销售假冒伪劣产品。"},{"i":12,"n":"第十二条","txt":"鼓励家电维修经营者建设完善的维修服务保障网络体系，统一负责维修服务的业务受理、质量监管、费用结算、投诉处理等业务。"},{"i":13,"n":"第十三条","txt":"家电维修服务业协会应当积极为家电维修经营者提供服务，维护家电维修经营者合法权益，加强行业引导和监督，做好行业自律、行业统计和家电维修经营者信息备案工作，促进行业发展。"},{"i":14,"n":"第十四条","txt":"各级商务主管部门对于违反本办法的家电维修经营者可以予以警告，责令限期改正；拒不改正的，可以向社会公告；违反本办法第九条　规定，情节严重的，可处三万元以下罚款；对依据有关法律、法规应予以处罚的，各级商务主管部门应提请有关部门依法处罚。"},{"i":15,"n":"第十五条","txt":"各省、自治区、直辖市商务主管部门可以依据本办法，结合当地家电维修服务行业实际情况，会同有关部门制定相关的实施办法。"},{"i":16,"n":"第十六条","txt":"本办法自2012年8月1日起施行。"}],"duitaiwandiquxiaoemaoyideguanlibanfa":[{"i":1,"n":"第一条","txt":"为便于大陆沿海省市与台湾地区的货物交流，引导海峡两岸民间小额贸易正常开展，特制定本办法。"},{"i":2,"n":"第二条","txt":"对台湾地区小额贸易（以下简称对台小额贸易）是指台湾地区居民在大陆沿海指定口岸（福建、广东、浙江、江苏、山东、上海）依照有关规定进行的货物交易。"},{"i":3,"n":"第三条","txt":"对台小额贸易只能由台湾地区居民同大陆的对台小额贸易公司进行。 台湾居民是指持有有效、完整的台湾渔民证、身份证等有关身份证明的人员。"},{"i":4,"n":"第四条","txt":"对台小额贸易公司应由对外贸易经济合作部（以下简称外经贸部）授权的沿海省市对外经贸主管机关批准，并在工商行政管理部门登记注册。 对台小额贸易公司只准开展对台湾地区小额贸易，不得经营一般进出口业务。"},{"i":5,"n":"第五条","txt":"对台小额贸易每船每航次进出口限额各为十万美元。"},{"i":6,"n":"第六条","txt":"对台小额贸易所经营的货物限于非国家专营、禁止、限制进出口的，非进出口配额许可证管理的货物。 确需出口少量配额许可证管理货物的，应由对台小额贸易公司报上级外经贸机关按照一般贸易和对台贸易的有关规定办理审批手续，经批准同意后申领出口许可证，海关凭证验放。"},{"i":7,"n":"第七条","txt":"对台小额贸易进口的货物仅限于原产地为台湾的货物。海关必要时应审阅进口货物的产地证明书。"},{"i":8,"n":"第八条","txt":"对台小额贸易只能使用一百吨以下（含一百吨）的台湾船只。台湾船只系指在台湾地区正式登记注册、可供在海上进行正常作业和航行的载体。 对台小额贸易的船只所载未能成交的货物，应原船退回。"},{"i":9,"n":"第九条","txt":"对台小额贸易只能在指定的口岸进行。 对台小额贸易口岸由外经贸部授权的沿海省市对外经贸主管机关商当地公安、边检、海关、交通、台办等部门指定。 经授权的沿海省市对外经贸主管机关应及时将本地区所确定的对台小额贸易公司和口岸情况向外经贸部备案并知会海关总署和国务院台湾事务办公室。外经贸部在收到对台小额贸易公司和口岸全部材料之日起三十天内，若未提出异议，备案自动生效。"},{"i":10,"n":"第十条","txt":"对台小额贸易应以易货形式为主进行，易货货物均需以美元计价。 采用现汇形式进行的对台小额贸易，应以国家允许兑换的外币进行结算。双方所得现汇均应按国家外汇管理的有关规定进行处理。 出口收入的外汇由对台小额贸易公司实行全额留成。"},{"i":11,"n":"第十一条","txt":"所有对台小额贸易进出口的货物和船只及船上人员必须接受当地海关、边检及其它港口联检部门的监管，并照章交纳税、费。 对台小额贸易货物和船只均不得出现违反“一个中国”即中华人民共和国的字样及旗、徽、号等标记。 船员个人携带自用物品应以自用合理数量为限。船员不得携带规定禁止进出境的物品，个人不得利用船舶为他人携带物品。船舶带进的航行必须的设备、燃料、物料，应原船带出。上述物品不得作为货物交易。 未经向海关申报并办理验放手续，不得擅自卸、装货物。"},{"i":12,"n":"第十二条","txt":"除国家另有规定外，对台小额贸易进出口货物由海关按照《中华人民共和国海关进出口税则》的优惠税率和《中华人民共和国产品税条例》、《中华人民共和国增值税条例》征税，并按海关有关征税规定进行管理。"},{"i":13,"n":"第十三条","txt":"对台小额贸易公司如违反本管理办法，原审批机关可视情节轻重分别给予警告、严重警告、撤销其经营权的处罚。作出撤销经营权处罚的，应及时报外经贸部和海关总署备案。 对于不具备开展对台小额贸易条件的对台小额贸易公司和口岸，外经贸部有权予以撤销。 对违反海关规定的，由海关按照“中华人民共和国海关法”及有关法规进行查处。构成犯罪的，移交司法机关追究刑事责任。"},{"i":14,"n":"第十四条","txt":"开展对台小额贸易的省市对外经贸主管机关应于每年一月底前将本省市前一年的对台小额贸易情况总结上报外经贸部。"},{"i":15,"n":"第十五条","txt":"本办法由对外贸易经济合作部、海关总署负责解释并监督执行。"},{"i":16,"n":"第十六条","txt":"本办法自发布之日起施行。以前有关规定与本办法不一致者，以本办法为准。"}],"duitaiwandiqumaoyiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了发展大陆与台湾地区间的贸易，维护海峡两岸正常的贸易秩序，促进海峡两岸经济的发展，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于大陆与台湾地区间的货物贸易、技术贸易和服务贸易（以下简称对台贸易）。"},{"i":3,"n":"第三条","txt":"从事对台贸易，应当遵守法律、行政法规和国家其他有关规定，不得损害国家安全和社会公共利益。"},{"i":4,"n":"第四条","txt":"中华人民共和国对外贸易经济合作部是对台贸易的主管机关。 有关省、自治区和直辖市人民政府对外经济贸易主管部门负责管理本行政区域内的对台贸易工作。"},{"i":5,"n":"第五条","txt":"依法从事对外贸易经营活动的法人和其他组织，包括依法设立的外商投资企业，可以在其经营范围内与台湾地区的法人和其他组织或者个人进行对台贸易。"},{"i":6,"n":"第六条","txt":"对台贸易合同以及货物上不得出现违反一个中国原则的字样和标记，不得出现有碍祖国统一的内容。"},{"i":7,"n":"第七条","txt":"对台贸易的货物及其包装上需要标明原产地的，台湾货物及其包装上应当标明原产地为台湾，大陆货物及其包装上根据实际情况可以采用中性包装。"},{"i":8,"n":"第八条","txt":"间接进行对台贸易的，应当通过在香港特别行政区或者澳门特别行政区登记注册的工商企业进行。"},{"i":9,"n":"第九条","txt":"大陆货物经香港特别行政区或者澳门特别行政区转口、转运至台湾地区的，应当遵守国家对香港特别行政区、澳门特别行政区贸易的有关规定。"},{"i":10,"n":"第十条","txt":"对台贸易中涉及国家统一、联合经营或者总量控制的商品，以及许可证、配额管理的商品，按照国家有关进出口的规定办理。"},{"i":11,"n":"第十一条","txt":"对台贸易的货物由海关依照有关法律、行政法规的规定，按照优惠税率征收关税，并依法征收进口环节的税收。"},{"i":12,"n":"第十二条","txt":"对台贸易中发生纠纷时，由当事人通过协商或者调解解决。当事人不愿协商、调解的或者协商、调解不成的，可以依据合同中的仲裁条款或者事后达成的书面仲裁协议，提交中国的仲裁机构仲裁。当事人未在合同中订立仲裁条款，事后又未达成书面仲裁协议的，可以依法向人民法院提起诉讼。"},{"i":13,"n":"第十三条","txt":"大陆与台湾地区间的小额贸易，适用对外贸易经济合作部、海关总署发布的《对台湾地区小额贸易的管理办法》。"},{"i":14,"n":"第十四条","txt":"对台贸易中的有关事项，本办法未作规定的，参照国家有关货物进出口、技术进出口和国际服务贸易的规定执行。"},{"i":15,"n":"第十五条","txt":"本办法自发布之日起施行。"}],"duiwailaowuhezuofengxianchuzhibeiyongjinguanlibanf91625c":[{"i":1,"n":"第一条","txt":"为规范对外劳务合作企业的经营行为，保障外派劳务人员合法权益，根据《对外劳务合作管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"对外劳务合作风险处置备用金（以下简称备用金）是指对外劳务合作企业缴存，用于《对外劳务合作管理条例》第十条所规定使用范围的专用资金。"},{"i":3,"n":"第三条","txt":"对外劳务合作企业缴存备用金的银行，由负责对外劳务合作经营资格审批的商务主管部门（以下简称商务主管部门）会同同级财政部门指定。"},{"i":4,"n":"第四条","txt":"商务主管部门和财政部门应根据本地区对外劳务合作企业数量和外派劳务规模等实际情况，在本行政区域内择优指定一家或多家信用等级良好、服务水平优良，并承诺按照要求提供相关服务的银行作为备用金缴存银行。"},{"i":5,"n":"第五条","txt":"对外劳务合作企业应到指定银行办理备用金缴存和取款手续。"},{"i":6,"n":"第六条","txt":"对外劳务合作企业应当自获得对外劳务合作经营资格并在工商行政管理部门登记之日起5个工作日内，在指定银行缴存备用金。"},{"i":7,"n":"第七条","txt":"备用金缴存标准为300万元人民币，以现金或等额银行保函形式缴存。"},{"i":8,"n":"第八条","txt":"对外劳务合作企业以现金形式缴存备用金的，需持《营业执照》副本和《对外劳务合作经营资格证书》到指定银行开设专门账户并办理存款手续。缴存备用金的对外劳务合作企业应与指定银行签订《对外劳务合作风险处置备用金存款协议书》（附件1），并将复印件送商务主管部门备案。"},{"i":9,"n":"第九条","txt":"备用金本金和利息归对外劳务合作企业所有，对外劳务合作企业可自由提取和使用备用金利息。"},{"i":10,"n":"第十条","txt":"对外劳务合作企业以银行保函形式缴存备用金的，由指定银行出具受益人为商务主管部门的不可撤销保函（附件2），保证在发生《对外劳务合作管理条例》第十条规定使用情形时履行担保责任。对外劳务合作企业应在其对外劳务合作经营资格存续期间提供有效的保函，保函有效期至少为两年。商务主管部门应在保函到期前一个月提醒对外劳务合作企业延长保函的有效期。保函正本由商务主管部门保存。"},{"i":11,"n":"第十一条","txt":"商务主管部门应当将缴存备用金的对外劳务合作企业名单向社会公布。"},{"i":12,"n":"第十二条","txt":"对外劳务合作企业拒绝或无力承担违反国家规定收取应退还给劳务人员的服务费或按照约定应向劳务人员支付的劳动报酬的，在劳务人员向商务主管部门投诉并提供相关合同以及收费凭证或者工资凭条等证据后，商务主管部门应书面通知对外劳务合作企业在5个工作日内退还或支付劳务人员有关费用。 对外劳务合作企业在规定时间内未退还或支付有关费用的，商务主管部门应做出使用备用金的决定并书面通知有关对外劳务合作企业和指定银行，同时出具《对外劳务合作风险处置备用金取款通知书》（附件3，以下简称《取款通知书》）。指定银行根据书面通知和《取款通知书》，从备用金中将相应数额的款项以现金或转账方式支付给商务主管部门指定的劳务人员。"},{"i":13,"n":"第十三条","txt":"对外劳务合作企业拒绝或无力承担依法应向劳务人员支付的劳动报酬或赔偿劳务人员的损失所需费用的，商务主管部门凭人民法院判决、裁定及其他生效法律文书使用备用金。"},{"i":14,"n":"第十四条","txt":"对外劳务合作企业拒绝或无力承担因发生突发事件，劳务人员回国或接受紧急救助所需费用的，商务主管部门应向对外劳务合作企业提供发生劳务人员回国或接受紧急救助所发生的费用证明，并书面通知对外劳务合作企业在5个工作日内支付有关费用。 对外劳务合作企业在规定时间内未支付有关费用的，商务主管部门应做出使用备用金的决定，并书面通知有关对外劳务合作企业和指定银行，同时出具《取款通知书》。指定银行根据书面通知和《取款通知书》，从备用金中将相应数额的款项以现金或转账方式支付给商务主管部门指定的人员或单位。"},{"i":15,"n":"第十五条","txt":"提供保函的指定银行应在收到书面通知和《取款通知书》５个工作日内，履行担保责任。"},{"i":16,"n":"第十六条","txt":"备用金使用后，对外劳务合作企业应当自使用之日起20个工作日内将备用金补足到300万元人民币。"},{"i":17,"n":"第十七条","txt":"对外劳务合作企业停止开展对外劳务合作的，应当对其派出的尚在国外工作的劳务人员做出妥善安排，并将安排方案连同2年内有效的备用金缴存凭证或者保函报商务主管部门备案。 对外劳务合作企业自备案之日起2年内未发生针对其的劳务纠纷投诉或者诉讼的，商务主管部门应出具书面通知和《取款通知书》，指定银行根据书面通知和《取款通知书》，退还其缴存的备用金或允许其撤销保函。"},{"i":18,"n":"第十八条","txt":"指定银行应每季度分别向对外劳务合作企业和商务主管部门提供备用金存款对账单。"},{"i":19,"n":"第十九条","txt":"对外劳务合作企业对商务主管部门使用备用金的决定持有异议的，可以依法申请行政复议或者向人民法院提起行政诉讼。"},{"i":20,"n":"第二十条","txt":"备用金实行专款专用。"},{"i":21,"n":"第二十一条","txt":"对外劳务合作企业未依据《对外劳务合作管理条例》和本办法规定缴存或者补足备用金的，商务主管部门责令其在备用金应缴存或补足之日起一个月内改正；拒不改正的，吊销其对外劳务合作经营资格证书。"},{"i":22,"n":"第二十二条","txt":"备用金由商务主管部门负责使用、管理，同级财政部门负责监督，并接受审计部门的审计。"},{"i":23,"n":"第二十三条","txt":"对外承包工程的单位应当自收到中标文件或签署项目商务合同后15个工作日内，在指定银行缴存备用金。备用金缴存标准为300万元人民币，以现金或等额银行保函形式缴存。对外承包工程的单位已取得对外劳务合作经营资格并足额缴存备用金的，不需依照本条再次缴存备用金。 以现金形式缴存备用金的，对外承包工程的单位应当在对外承包工程项目数据库系统中填写并打印《备用金缴存申请表》，连同《营业执照》副本或《事业单位法人证书》副本，到指定银行开设专门账户并办理存款手续，签订《备用金存款协议书》，并将复印件送注册地省级商务主管部门备案（原备用金账户余额已达到缴存标准的除外）。 对外承包工程的单位以银行保函形式缴存备用金的，由指定银行出具受益人为注册地省级商务主管部门的不可撤销保函，保证在发生《对外承包工程管理条例》第十九条规定使用情形时履行担保责任。保函有效期至少为两年，注册地省级商务主管部门应在保函到期前一个月提"},{"i":24,"n":"第二十四条","txt":"本办法施行前从事对外劳务合作经营的企业，如不再从事对外劳务合作经营的，应向商务主管部门、财政部门申请退还备用金；如继续从事对外劳务合作经营的，应按照《对外劳务合作管理条例》和本办法的有关规定及时缴存备用金。未取得对外劳务合作经营资格或未及时缴存备用金的，分别按照《对外劳务合作管理条例》第三十九条和第四十一条有关规定处理。"},{"i":25,"n":"第二十五条","txt":"本办法由商务部会同财政部负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2014年8月17日起施行，2001年11月27日原对外贸易经济合作部、财政部发布的《对外劳务合作备用金暂行办法》（原对外贸易经济合作部 财政部二〇〇一年第7号令）及其补充规定同时废止。 附件： 对外劳务合作风险处置备用金存款协议书 对外劳务合作风险处置备用金银行保函 对外劳务合作风险处置备用金取款通知书"}],"duiwaichengbaogongchengxiangmubeianhelixiangguanli015b41":[{"i":1,"n":"第一条","txt":"为进一步完善对外承包工程管理，促进对外承包工程高质量发展，根据《对外承包工程管理条例》（以下简称《条例》）、《国务院关于修改和废止部分行政法规的决定》（国务院令第676号）和《国务院关于取消一批行政许可事项的决定》（国发〔2017〕46号）等相关法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用的对外承包工程项目（以下简称工程项目），是指中国境内注册企业（以下简称企业）承包的境外建设工程项目，包括工程的咨询、勘察、设计、监理、施工、采购安装、运营维护等。 本办法所称特定项目，是指在与我无外交关系或者外交关系降级的国家承包的工程项目、涉及多国利益的工程项目、存在高风险的工程项目，以及按照《条例》规定确定的其他特定项目。特定项目以外的工程项目，为一般项目。"},{"i":3,"n":"第三条","txt":"商务部和各省、自治区、直辖市及计划单列市、新疆生产建设兵团商务主管部门（以下简称省级商务主管部门），应坚持统筹发展和安全，依法履行职责，加强对外承包工程的监管，积极防范化解各类风险，规范企业办理工程项目备案立项和信息报告的流程，提高行政效率，提供优质服务。"},{"i":4,"n":"第四条","txt":"企业开展对外承包工程不得损害我国国家安全和国家利益，不得违反我国法律和我国缔结或者参加的国际条约、协定，应当遵守项目所在国（地区）法律，加强风险防范，避免不正当竞争，履行社会责任，树立良好形象。"},{"i":5,"n":"第五条","txt":"企业承包一般项目应当在商务主管部门办理备案。商务部负责中央企业总部（含整体上市的股份有限公司）承包一般项目的备案；省级商务主管部门负责注册地在本行政区域内的地方企业和中央企业所属企业承包一般项目的备案。"},{"i":6,"n":"第六条","txt":"企业承包特定项目应当经商务部会同国务院有关部门批准立项；省级商务主管部门负责监督指导注册地在本行政区域内的地方企业和中央企业所属企业，在承包特定项目前及时办理立项。"},{"i":7,"n":"第七条","txt":"企业应当按照“凡备案立项必报告”原则，向商务主管部门、中国驻工程项目所在国使（领）馆或者代管馆定期报告工程项目后续开展情况。在境外发生突发事件时，企业应当按照《条例》规定，及时妥善处理，并立即向中国驻工程项目所在国使（领）馆或者代管馆和国内有关主管部门报告。企业在报告工程项目信息时，应当遵守境内外数据信息保护的相关法律法规。"},{"i":8,"n":"第八条","txt":"企业通过商务部业务系统统一平台的对外承包工程项目管理系统（以下简称业务系统）办理工程项目备案立项，定期报告项目后续开展情况。业务系统操作指南由商务部发布。 企业初次使用业务系统的，应当首先在业务系统如实填写《对外承包工程企业信息登记表》。所登记信息发生变动的，应当自变动之日起30个工作日以内在业务系统办理变更。"},{"i":9,"n":"第九条","txt":"企业以投标或者议标方式承包一般项目的，应当在对外投标或者议标前完成工程项目备案。企业以其他方式承包一般项目的，应当在项目签约前完成工程项目备案。"},{"i":10,"n":"第十条","txt":"企业办理一般项目备案，应当通过业务系统填写《对外承包工程项目备案表》（以下简称《项目备案表》），打印并加盖单位公章后扫描上传至业务系统。企业对备案信息的真实性、准确性和完整性负责。企业认为不适宜通过业务系统填写的事项，可以商商务主管部门另行提交纸质材料。"},{"i":11,"n":"第十一条","txt":"项目不属于备案管理范围、《项目备案表》填写不完整或者不准确、不属于本级商务主管部门管理权限或者按规定需会同相关部门和单位会商的，商务主管部门应当在收到《项目备案表》之日起3个工作日以内，通过业务系统告知企业。"},{"i":12,"n":"第十二条","txt":"项目备案申请不存在本办法第十一条列举情形的，商务主管部门应当自受理《项目备案表》之日起3个工作日以内予以备案。企业通过业务系统自行打印《对外承包工程项目备案回执》（以下简称《备案回执》）。"},{"i":13,"n":"第十三条","txt":"企业获得《备案回执》之日起2年以内，未对外投标或者签订工程项目合同的，《备案回执》自动失效。"},{"i":14,"n":"第十四条","txt":"《备案回执》载明的信息发生变动的，企业应当自变动之日起30个工作日以内，通过业务系统填写《对外承包工程项目备案变更表》（以下简称《备案变更表》），打印并加盖单位公章后扫描上传至业务系统。收到企业《备案变更表》后，商务主管部门应当根据本办法相关规定为符合备案管理要求的企业办理信息变更。企业可通过业务系统自行打印信息变更后的《备案回执》，原《备案回执》自动失效。"},{"i":15,"n":"第十五条","txt":"企业以投标或者议标方式承包特定项目的，应当在对外投标或者议标前完成工程项目立项。企业以其他方式承包特定项目的，应当在项目签约前完成工程项目立项。未经批准立项，企业不得擅自参与特定项目。"},{"i":16,"n":"第十六条","txt":"企业办理特定项目立项，应当通过业务系统填写《对外承包工程项目立项表》（以下简称《项目立项表》），打印并加盖单位公章后扫描上传至业务系统。根据不同类型的特定项目，企业应当按照相关规定或者业务系统提示相应地在线提交立项申请函、中国驻项目所在国使（领）馆或者代管馆意见、专业机构出具的项目安全风险评估报告、项目安保方案和应急预案等立项申请材料。如项目拟使用境内金融机构信贷或者信用保险的，企业应当提交资金落实情况说明。企业对提交材料的真实性、准确性和完整性负责。 企业认为不适宜通过业务系统提交的立项申请材料，可以商商务部另行提交纸质材料。"},{"i":17,"n":"第十七条","txt":"项目不属于立项管理范围、《项目立项表》填写不完整或者不准确、申请材料不齐全或者不符合法定形式，或者按规定需会同相关部门和单位会商的，商务部应当在收到企业立项申请材料之日起5个工作日以内告知企业。"},{"i":18,"n":"第十八条","txt":"项目立项申请不存在本办法第十七条列举情形的，商务部应当会同有关部门作出是否批准立项的决定。企业可通过业务系统查看立项的办理进展和办理结果。获得批准立项的企业通过业务系统自行打印《对外承包工程项目立项回执》（以下简称《立项回执》）。"},{"i":19,"n":"第十九条","txt":"企业获得《立项回执》之日起2年以内，未对外投标或者签订工程项目合同的，《立项回执》自动失效。企业申请《立项回执》信息变更，参照本办法第十四条规定的程序办理。"},{"i":20,"n":"第二十条","txt":"企业应当在工程项目投标或者议标结果公布、合同签订、开工、完工后30个工作日以内，通过业务系统分别填报中标情况、签约情况、开工日期、完工日期等信息。 工程项目开工后，企业应当在工程项目实施期间于每年1月和7月，通过业务系统填写《对外承包工程项目半年情况报告表》。"},{"i":21,"n":"第二十一条","txt":"企业应当在对外签订工程项目合同之日起30个工作日以内，通过业务系统填写《对外承包工程项目报到登记表》，打印并加盖单位公章后，扫描上传业务系统，报送给中国驻工程项目所在国使（领）馆或者代管馆。"},{"i":22,"n":"第二十二条","txt":"企业应当按照对外承包工程业务统计调查制度等相关规定要求向商务主管部门报送统计资料。"},{"i":23,"n":"第二十三条","txt":"企业应当对所报告信息的真实性、准确性和完整性负责，不得漏报、谎报或者瞒报相关工程项目信息。"},{"i":24,"n":"第二十四条","txt":"商务主管部门应当落实岗位责任，强化内部监督，严格按照本办法规定为企业办理工程项目备案立项和信息报告。对企业咨询拟承包工程项目是否属于一般项目或者特定项目的，商务主管部门应当及时予以告知。"},{"i":25,"n":"第二十五条","txt":"商务主管部门应当对企业办理工程项目备案立项和信息报告情况开展监督检查。企业应当积极配合监督检查。 商务部负责全国对外承包工程项目备案立项和信息报告的管理；负责对中央企业总部执行本办法情况的监督检查和违规查处。商务部驻各地特派员办事处按照商务部工作部署，对所联系地区的企业执行本办法情况开展检查。省级商务主管部门履行属地责任，负责对注册地在本行政区域内的地方企业和中央企业所属企业执行本办法情况的监督检查和违规查处。"},{"i":26,"n":"第二十六条","txt":"企业违反《条例》和本办法规定受到处罚的，商务主管部门可以按照相关规定将企业违法违规行为信息纳入全国信用信息共享平台、“信用中国”网站等，与有关主管部门、驻外使（领）馆、金融机构和对外承包工程行业组织等共享信息。"},{"i":27,"n":"第二十七条","txt":"商务主管部门应当督促和引导企业加强风险防范，在承包工程项目前，对项目所在国家和地区的政治、经济、外交、法律、安全环境，以及项目内容、地点、背景、资金来源和当地利益相关方态度等情况进行全面、系统、客观的考察和评估。"},{"i":28,"n":"第二十八条","txt":"商务主管部门加强对企业境外合规经营培训，引导和督促企业规范对外承包工程经营行为；加强与中国驻工程项目所在国使（领）馆或者代管馆的沟通联系，及时了解企业境外合规经营情况。"},{"i":29,"n":"第二十九条","txt":"商务主管部门应当完善对外承包工程服务保障体系，健全多双边工作机制，提供相关公共服务产品，完善相关服务平台，积极支持企业开展对外承包工程业务。"},{"i":30,"n":"第三十条","txt":"商务主管部门鼓励和支持对外承包工程有关行业组织加强行业协调自律，引导企业守法诚信经营，维护市场秩序和公平竞争。"},{"i":31,"n":"第三十一条","txt":"对不符合本办法规定条件的项目予以备案立项，或者违反本办法权限和程序予以备案立项的，商务主管部门应当依法予以撤销。"},{"i":32,"n":"第三十二条","txt":"商务主管部门及工作人员应当保护企业商业秘密，不得违法违规透露企业和工程项目信息。"},{"i":33,"n":"第三十三条","txt":"企业有下列情形之一的，由商务主管部门予以提醒、函询，或者予以警告、通报批评，并责令改正；情节严重或者造成不良影响的，处2万元以上5万元以下的罚款，并可以对其主要负责人处5000元以上1万元以下的罚款： （一）以投标或者议标方式承包一般项目，未在对外投标或者议标前办理一般项目备案并取得《备案回执》的；以其他方式承包一般项目，未在项目签约前办理一般项目备案并取得《备案回执》的； （二）《备案回执》载明的信息发生变动，未按本办法规定办理信息变更的。"},{"i":34,"n":"第三十四条","txt":"企业有下列情形之一的，由商务主管部门予以提醒、函询，或者予以警告、通报批评，并责令改正；情节严重或者造成不良影响的，处5万元以上10万元以下的罚款，并可以对其主要负责人处5000元以上1万元以下的罚款： （一）以投标或者议标方式承包特定项目，未在对外投标或者议标前办理特定项目立项并取得《立项回执》的；以其他方式承包特定项目，未在项目签约前办理特定项目立项并取得《立项回执》的； （二）《立项回执》载明的信息发生变动，未按本办法规定办理信息变更的； （三）未按照本办法第四十三条规定，在完成会商前对外投标、议标或者签约项目的。"},{"i":35,"n":"第三十五条","txt":"企业通过隐瞒有关情况、提供不实信息或者虚假材料等手段申请工程项目备案立项的，商务主管部门不予备案立项，并对其予以提醒、函询，或者警告。企业通过隐瞒有关情况、提供不实信息或者虚假材料等手段取得《备案回执》或《立项回执》的，商务主管部门撤销《备案回执》或《立项回执》，并对其予以提醒、函询，或者处2万元以上5万元以下的罚款；造成不良影响的，处5万元以上10万元以下的罚款，并可以对其主要负责人处5000元以上1万元以下的罚款。 企业伪造、涂改、出租、出借、转让《备案回执》或《立项回执》的，由商务主管部门予以警告、通报批评或者处5万元以上10万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":36,"n":"第三十六条","txt":"企业未按照本办法相关规定履行信息报告义务的，由商务主管部门对其予以提醒、函询，并责令改正；情节严重或者造成不良影响的，予以警告、通报批评或者处2万元以上5万元以下的罚款，拒不改正的，对其主要负责人处5000元以上1万元以下的罚款。"},{"i":37,"n":"第三十七条","txt":"企业对商务主管部门根据本办法第二十五条规定开展监督检查不予配合的，包括未按照商务主管部门监督检查要求及时提供有关材料或者提供的材料不真实等，由商务主管部门予以提醒、函询，并责令改正；情节严重或者造成不良影响的，予以警告、通报批评或者处1万元以上5万元以下的罚款，并可以对其主要负责人处5000元以上1万元以下的罚款。"},{"i":38,"n":"第三十八条","txt":"企业涉及违反《条例》规定情形的，应当按照《条例》予以行政处罚。企业存在《条例》第二十条、第二十一条或者第二十三条规定情形，被禁止在一定期限内对外承包新的工程项目的，商务主管部门在禁止期限内不予办理该企业的备案和立项。"},{"i":39,"n":"第三十九条","txt":"商务主管部门有关工作人员在执行本办法中滥用职权、玩忽职守、徇私舞弊、索取或者收受他人财物、泄露企业商业秘密的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":40,"n":"第四十条","txt":"企业在香港特别行政区、澳门特别行政区、台湾地区承包工程项目，参照本办法执行。 事业单位及其他法人对外承包工程项目按照本办法执行。"},{"i":41,"n":"第四十一条","txt":"本办法所称中央企业系指国务院国有资产监督管理机构履行出资人职责的企业、中央管理的其他企业。"},{"i":42,"n":"第四十二条","txt":"企业通过境外注册分公司承包工程项目的，或者与境外企业联合承包工程项目的，应当按照本办法规定办理备案立项和信息报告。两个以上企业联合承包工程项目的，应当由一家牵头企业办理备案立项和信息报告。企业依法将已备案立项的工程项目分包的，分包企业无需办理备案立项。"},{"i":43,"n":"第四十三条","txt":"企业承包合同额在10亿美元以上的工程项目，在办理备案立项手续时，由商务部会同相关部门和单位先开展会商，对项目风险进行评估。"},{"i":44,"n":"第四十四条","txt":"省级商务主管部门可结合本地区实际，根据本办法制定对外承包工程项目备案立项和信息报告的实施细则。"},{"i":45,"n":"第四十五条","txt":"对外承包工程单位备用金管理按照《条例》以及商务部、财政部相关规定执行。"},{"i":46,"n":"第四十六条","txt":"本办法所称“以内”“以上”“以下”均含本数。"},{"i":47,"n":"第四十七条","txt":"《对外承包工程项目备案表》（样式）、《对外承包工程项目立项表》（样式）、《对外承包工程项目备案变更表》（样式）、《对外承包工程项目立项变更表》（样式）、《对外承包工程项目备案回执》（样式）、《对外承包工程项目立项回执》（样式）、《对外承包工程企业信息登记表》（样式）、《对外承包工程项目半年情况报告表》（样式）、《对外承包工程项目报到登记表》（样式）由商务部另行发布。"},{"i":48,"n":"第四十八条","txt":"本办法由商务部负责解释。"},{"i":49,"n":"第四十九条","txt":"本办法自2024年7月1日起施行。《商务部办公厅关于做好对外承包工程项目备案管理的通知》（商办合函〔2017〕455号）同时废止。"}],"duiwaijishuyuanzhuxiangmuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对外技术援助项目的管理，保证项目质量，提高援助效果，依据有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称技术援助项目，是指中方在援外资金项下，综合采用选派专家、技术工人或提供设备等手段，帮助受援方实现特定技术目标的援助项目。"},{"i":3,"n":"第三条","txt":"技术援助项目一般由中方负责组织实施。如受援方有组织实施意愿，中方可结合项目实际情况与受援方商定，将技术援助项目交由受援方组织实施。"},{"i":4,"n":"第四条","txt":"商务部负责技术援助项目的立项、管理和监督。 援外项目管理机构依据本办法规定具体组织、监督和管理技术援助项目的实施，并接受商务部的监督检查。"},{"i":5,"n":"第五条","txt":"驻受援国使领馆经济商务机构协助商务部办理与技术援助项目有关的政府间事务，负责技术援助项目实施的境外监督管理。"},{"i":6,"n":"第六条","txt":"各省级商务主管部门协助商务部处理对外技术援助管理事务。"},{"i":7,"n":"第七条","txt":"项目管理机构在经商务部认定资格的援外项目实施企业范围内根据援外项目采购规定选定技术援助项目实施单位。 商务部可根据国家区域发展政策选定对外技术援助项目实施单位。 中标的技术援助项目实施单位对所承担的技术援助项目任务实行企业承包责任制。"},{"i":8,"n":"第八条","txt":"技术援助项目采购以技术援助方案的技术可靠性、方案成熟度和经济合理性作为主要选择标准。 技术援助方案是指根据技术援助项目可行性研究报告和立项建议书的要求，提出的要素整合方式、技术实现手段和标准，实现技术援助目标的规划、路径和程序等内容。其中，技术援助要素主要包括人力资源开发、智力支持、技术服务和转让、管理合作、提供物资设备和提供工程服务等不同类型。 对于技术实现路径简单明确的技术援助项目，项目管理机构可以在采购程序中确定统一的技术援助方案，并根据方案响应性和经济合理性依法选定实施单位；对于实现同一技术目标路径多元的技术援助项目，项目管理机构应当在采购程序中依法选定技术援助方案及实施单位。"},{"i":9,"n":"第九条","txt":"对于技术援助项目内容较为复杂或有特殊安全性要求，所需主项技术资质为两项以上的，可由符合所有主项技术资质的单位单独投标，也可由投标单位组成联合体投标。联合体各方不得再单独或者与其他投标单位另外组成联合体参与投标。 联合体牵头单位应当具备技术援助项目实施单位资格。联合体各方在项目中标后应当共同与项目管理机构签订项目实施合同，并承担连带法律责任。"},{"i":10,"n":"第十条","txt":"根据立项要求或实施管理实际情况，如技术援助项目涉及由唯一供货单位提供的物资或唯一服务单位提供的专利、专有技术服务，项目管理机构应根据援外项目采购规定，提前与相应物资或服务提供单位议定采购价格和条件，列入项目招标文件，并监督相应物资或服务提供单位向所有竞标单位落实议定采购价格和条件。 中标的技术援助项目实施单位应按招标文件列明的议定采购价格和条件与唯一供货企业和专利或专有技术服务提供单位签订内部分包合同，并将分包的物资或服务任务的进度、质量、安全和投资控制纳入技术援助总承包责任范围。"},{"i":11,"n":"第十一条","txt":"项目管理机构代表商务部向中标的技术援助项目实施单位下达实施任务通知函。 技术援助项目实施单位凭实施任务通知函办理技术援助人员出入境以及设备物资的检验通关。"},{"i":12,"n":"第十二条","txt":"中标单位不得将承包责任范围内的任务进行转包，也不得将承包责任范围内的关键性或主体性工作任务分包或分解成若干部分分包。 中标单位将本单位技术资质不能覆盖的非关键性或非主体性任务分包给其他专业技术单位的，其分包内容、分包单位选择和分包金额应当在技术援助项目投标书中载明，作为中标条件审定并写入合同约定。 分包方式一旦确定，不得变更。中标单位应当按投标文件中载明的分包方式签订分包合同并报项目管理机构备案。确需变更或新增分包的，应当按变更合同程序办理。"},{"i":13,"n":"第十三条","txt":"合规分包不排除技术援助项目实施单位承包责任范围内的任何义务。"},{"i":14,"n":"第十四条","txt":"商务部负责审批技术援助项目的可行性研究报告和立项建议书，并办理立项。 立项后，项目管理机构在政府间立项协议以及商务部批准的可行性研究报告和立项建议书范围内组织项目实施和管理。"},{"i":15,"n":"第十五条","txt":"技术援助项目政府间协议要求签订对外实施协议的，项目管理机构应当在实施单位与受援方正式确认技术援助方案的基础上，负责与受援方指定机构签订项目对外实施协议。 对外实施协议应当细化规定中、外双方的合作方式、管理程序和实施全过程的权利、义务。"},{"i":16,"n":"第十六条","txt":"技术援助项目实施单位应当严格按照政府间协议、对外实施协议及与商务部订立的项目实施合同的规定，执行技术援助方案，确保整合提供人力、技术、管理、物资和工程服务等各项要素的质量和效率，在规定期限内实现技术援助目标，并在承包责任范围内承担全部的经济、技术和法律责任。"},{"i":17,"n":"第十七条","txt":"技术援助项目实施单位应当成立技术援助专家组并指定组长，负责在受援国当地技术援助任务的组织实施和管理。 技术援助专家组接受驻受援国使领馆经济商务机构的监督管理。"},{"i":18,"n":"第十八条","txt":"技术援助项目实施单位应当定期向项目管理机构报送工作简报，内容涵盖项目执行进展、遇到有关问题及解决措施、下阶段工作计划和实施方案等。遇有重大质量安全问题和可能影响项目实施的突发事件应当及时专题报告。 技术援助项目实施完毕后，实施单位应当向项目管理机构书面提交项目总结报告，内容涵盖项目总体实施情况、取得的援助效果和经济社会效益、受援方对项目实施的总体评价、项目执行过程中遇到的问题及解决措施、有关突发紧急情况的处理应对以及项目是否延续的有关建议等。"},{"i":19,"n":"第十九条","txt":"项目管理机构在技术援助项目实施单位基本履行完毕政府间协议、对外实施协议和项目实施合同规定的义务后，可依法选定经商务部认定资格的顾问咨询单位组成专家组进行技术援助项目验收。 验收专家组的具体组成方式和人员资格由项目管理机构根据技术援助项目性质和特点决定。验收专家组成员不得与技术援助项目实施单位存在可能影响公正验收的利害关系。 技术援助项目验收以政府间协议、对外实施协议、项目实施合同规定以及技术援助方案为主要依据，对技术援助项目项下人力资源开发、智力支持、技术服务和转让、管理合作的实物工作量、智力成果和援助效果进行综合评估，对实施单位的履约情况和专家服务情况进行确认，对附带物资设备和工程服务进行核验和验收，最终对技术援助目标的实现作出结论。验收结论分为合格和不合格两个评定等级。 验收专家组应当根据验收结果向项目管理机构提交验收报告。验收报告经验收专家组全体成员签字后生效。"},{"i":20,"n":"第二十条","txt":"技术援助项目实施单位应当对验收过程中发现的问题和验收报告提出的问题及时进行整改。 验收期间整改完毕的问题，由验收专家组作出整改结论并写入验收报告；无法在验收期间完成整改的问题，由实施单位在规定期限内进行整改，将整改结果报验收专家组补充作出整改结论。"},{"i":21,"n":"第二十一条","txt":"技术援助项目验收合格后，项目管理机构代表商务部，应当及时通过外交渠道与受援方办理政府间移交手续。 项目管理机构应当在完成政府间移交手续后及时向商务部提交技术援助项目完成报告。"},{"i":22,"n":"第二十二条","txt":"技术援助项目实施单位应当在承包责任范围内，负责归集、整理项目技术资料，并在项目完成验收且办理对外移交手续后六十日内向项目管理机构移交。 纳入管理和移交的技术援助项目技术资料是指项目实施过程中形成的、具有保存价值的各类技术文件和反映项目准备、实施过程情况的有关载体。 技术援助项目技术资料纳入商务部建立的对外援助成套项目技术资料库统一管理。附带工程的技术资料管理要求按照《对外援助成套项目管理办法（试行）》执行。"},{"i":23,"n":"第二十三条","txt":"对于技术援助项目项下需要派遣中方专家（以下简称技术援助专家）赴受援国执行人力资源开发、智力支持、技术服务和转让、管理合作等专业技术任务的，项目管理机构应当根据技术援助项目的实际需要，在项目采购时明确技术援助专家的专业资质或同等技术要求。"},{"i":24,"n":"第二十四条","txt":"技术援助项目实施单位应当保证所派技术援助专家达到项目所要求的专业资质或同等技术水平，具体人选由项目管理机构通过项目采购程序确定。 确定的技术援助专家人选非因特殊情况不得随意变更。确需变更的，技术援助项目实施单位应当将变更后的人员资质、条件等情况重新报项目管理机构确定。"},{"i":25,"n":"第二十五条","txt":"技术援助项目实施单位应当主要选派本单位人员担任技术援助专家。因专业特殊或技术资质限制需要外聘人员担任技术援助专家的，应当对外聘人员进行必要的审查，并与外聘人员签订劳动合同，明确双方在执行项目期间的权利和义务。"},{"i":26,"n":"第二十六条","txt":"项目管理机构应当在技术援助项目执行完毕前，提请驻受援国使领馆经济商务机构对技术援助专家的服务质量和效果出具履职评估意见。 驻受援国使领馆经济商务机构出具的技术援助专家履职评估意见应当如实反映中方专家在受援国工作期间的工作绩效及履职情况，并充分听取受援方意见。 技术援助专家履职评估意见应当作为项目验收时，验收专家组确认专家服务情况的重要依据。"},{"i":27,"n":"第二十七条","txt":"技术援助项目实施单位应当切实保障技术援助专家的待遇，包括在受援国执行技术援助任务期间的国内职位、岗位、职称待遇、工作保障和社会福利待遇不变，充分享有技术援助专家的国外津贴、艰苦地区补贴、医疗费用、休假、境外人身意外伤害保险及食宿、办公、交通等在国外履行公务所必需的工作和生活条件等。 驻受援国使领馆经济商务机构应当协助技术援助项目实施单位，督促受援方根据政府间协议或对外实施协议的规定，为技术援助专家提供出入境、当地居留和执行援助任务的便利，并保障技术援助专家的人身和财产安全。"},{"i":28,"n":"第二十八条","txt":"技术援助项目的智力成果是指技术援助项目实施单位在技术援助项下开展人力资源开发、智力支持、技术服务和转让、管理合作等活动所形成的一切有价值的精神财富或智力产品，包括： （一）技术建议书、规划报告、咨询报告、分析研究报告、论文、课程讲义等资料； （二）专利、专有技术、实用技术、版权等知识产权成果； （三）具有经济和技术价值的操作规程、工艺流程、工作程序、实施模式和管理经验等技术解决方案。"},{"i":29,"n":"第二十九条","txt":"技术援助项目实施单位应当依据技术援助方案单独制定智力成果的工作方案，明确不同阶段具体技术任务及其配套智力成果完成的目标、时限、条件和程序，确保智力成果提供的质量。 项目实施单位应当将项目执行期间取得的智力成果进行系统整理，形成书面材料后提交项目管理机构和商务部。"},{"i":30,"n":"第三十条","txt":"验收专家组应当在技术援助项目验收过程中，对技术援助项目项下形成的智力成果进行专业评审，确认智力成果的创新性、适用性和援助效果。 对智力成果的专业评审结果应当作为技术援助项目验收时，验收专家组确认实现技术援助目标的重要依据。"},{"i":31,"n":"第三十一条","txt":"技术援助项目实施单位在执行技术援助任务过程中形成或创造的智力成果，应当归属中方和受援方共同所有。具体归属安排及后续成果使用由中方与受援方在政府间协议或对外实施协议中约定。 未经商务部批准，技术援助项目实施单位无权公开、转让技术援助项目的智力成果或许可其他单位和个人使用智力成果。"},{"i":32,"n":"第三十二条","txt":"技术援助项目项下提供的援助物资主要分为专家物资、零配件和技术物资三类。"},{"i":33,"n":"第三十三条","txt":"技术援助项目项下附带物资，符合以下情形之一的，应当单独立项并按照《对外援助物资项目管理办法（试行）》组织实施： （一）供货总额（含运、保费）在五百万元人民币以上； （二）所占技术援助项目估算投资比重在50%以上； （三）技术物资供货总额（含运、保费）在三百万元人民币以上； （四）技术物资供货总额在一百万元人民币以上不足三百万元人民币，且所占技术援助项目投资估算比重在35%以上。"},{"i":34,"n":"第三十四条","txt":"专家物资主要是为满足中方技术援助专家在受援国执行援助任务的工作和生活需要所提供的交通车辆、办公设备、耐用消费品和一般消费品等物资，按照固定资产和消耗品分别进行管理。 专家物资项下的消耗品由技术援助项目实施单位负责采购、使用、分配和管理。任务完成后仍有使用价值的消耗品由技术援助项目实施单位自行向受援方移交。 专家物资项下使用援款单独购置并按固定资产进行管理的交通车辆、办公设备以及耐用消费品的产权归受援方所有，由技术援助项目实施单位负责采购，在技术援助项目执行期间由中方专家使用和管理。 项目管理机构应当与技术援助项目实施单位明确约定列入管理范围的固定资产清单（作为合同附件），并将固定资产清单及时通报驻受援国使领馆经济商务机构。技术援助项目执行完毕后，驻受援国使领馆经济商务机构应当监督技术援助项目实施单位对固定资产进行盘点，及时移交受援方主管部门，并办理移交确认手续，有关书面交接材料报项目管"},{"i":35,"n":"第三十五条","txt":"零配件主要是指技术援助项目项下为保证相关技术设备、装备恢复功能或长期使用所提供的合理数量的易损件、备件、配件或维修工器具等。 零配件由技术援助项目实施单位负责采购、使用和管理。技术援助项目执行完毕后，驻受援国使领馆经济商务机构应当监督技术援助项目实施单位对剩余零配件进行盘点，及时移交受援方主管部门，并办理移交确认手续，有关书面交接材料报项目管理机构备案。"},{"i":36,"n":"第三十六条","txt":"技术物资是指技术援助项目项下使用援款单独购置且用于实现技术援助目标的各类技术设备、装备、器材及生产物资等。 技术物资的产权归受援方所有。除本办法另有规定外，技术物资由技术援助项目实施单位负责采购，在技术援助项目执行期间由中方专家使用和管理。项目管理机构应当与技术援助项目实施单位明确约定技术物资清单，并将技术物资清单及时通报驻受援国使领馆经济商务机构。技术援助项目执行完毕后，驻受援国使领馆经济商务机构应当监督技术援助项目实施单位对技术物资进行盘点，及时移交受援方主管部门，并办理相应移交确认手续，有关书面交接材料报项目管理机构备案。"},{"i":37,"n":"第三十七条","txt":"技术援助项目项下专家物资、技术物资和零配件的供货企业应当依法承担所供物资的质量保证责任，对于在合同约定的质量保证期内出现的非受援国原因导致的产品质量问题，应当负责修理或更换，并承担所需费用。"},{"i":38,"n":"第三十八条","txt":"技术援助项目项下附带工程，符合以下情形之一的，应当单独立项并按照《对外援助成套项目管理办法（试行）》组织实施： （一）投资规模在一千万元人民币以上； （二）所占技术援助项目估算投资比重在50%以上。"},{"i":39,"n":"第三十九条","txt":"除第三十八条规定情形外，技术援助项目附带工程由技术援助项目实施单位依法组织实施或委托受援国当地有技术能力的中资单位或当地工程承包商组织实施。 其中，对于技术援助项下一定规模以上附带工程，即投资规模在五百万元人民币以上不足一千万元人民币的附带新建工程，项目管理机构应依据援外项目采购规定的程序，从具备援外成套项目实施企业资格的单位中择优选定项目管理公司承担附带工程管理任务。"},{"i":40,"n":"第四十条","txt":"技术援助项目项下附带工程应当坚持基本建设程序，按照“先勘察、后设计、再施工”的原则组织实施，具体承包模式、实施程序和管理要求参照《对外援助成套项目管理办法（试行）》的相关规定执行。 技术援助项目实施单位对附带工程的进度、质量、安全和投资控制承担总承包责任。如将附带工程整体或部分任务委托分包单位进行实施的，承担附带工程勘察设计任务的企业对勘察设计的质量、进度、安全生产及项目投资控制负连带责任；承担附带工程建设任务的企业对附带工程建设所涉及的质量、进度、安全生产以及工程建成后的质量保证和配套技术服务负连带责任。 承担附带工程管理任务的企业应当对附带工程勘察设计及工程建设全过程进行协调、控制和管理，并对涉及的质量、进度、安全生产及投资控制负连带责任。"},{"i":41,"n":"第四十一条","txt":"技术援助项目项下一定规模以上附带工程的质量检查由项目管理公司会同技术援助项目实施单位共同负责组织。对于附带投资规模较小的零星土建工程和小型修缮工程的质量检查，由技术援助项目实施单位负责组织。 技术援助项目项下附带工程的验收由项目管理机构组织。 附带工程检查验收的程序和标准参照《对外援助成套项目管理办法（试行）》的相关规定执行。"},{"i":42,"n":"第四十二条","txt":"除因受援方使用不当引致的质量问题外，对于技术援助项目项下附带工程，技术援助项目实施单位应当在合理使用期限内承担无缺陷质量保证责任。 技术援助项目实施单位应当在附带工程验收时向项目管理机构出具无缺陷质量保证书，明确附带工程各部分及设备材料的无缺陷质量保证范围、保证期限和相关的保修责任，自行制订并相应实施质量保修计划，至少在验收后两年内现场留驻质量保修团队，确保质量保证期限内返工、返修所需人力物资等配套资源提供和及时抵达现场，并自行承担质量保修所需全部费用。"},{"i":43,"n":"第四十三条","txt":"商务部按照市场化原则建立技术援助项目的风险承担机制，明确界定技术援助项目涉及的风险因素，规范风险承担主体责任。"},{"i":44,"n":"第四十四条","txt":"技术援助项目涉及的风险因素主要包括政治外交风险、业主责任风险、不可抗力风险、技术方案变动风险和经营性风险等。 政治外交风险是指政治外交变动或政策性调整对技术援助项目实施造成的影响，主要包括：国与国战争和涉核战争；中国与受援方外交关系变化；受援方合法当局没收、征用；与项目实施相关的法律、法规变动或政策调整等，风险责任由商务部承担。 业主责任风险是指由于商务部的责任或商务部同意承担受援方责任对技术援助项目实施造成的影响，风险责任由商务部承担。 不可抗力风险是指不可预见、不可克服、不可避免的客观情况对技术援助项目造成的影响，主要包括：自然灾害；意外事故；受援方国内战乱、罢工、暴乱、民众骚乱等突发情况，风险责任由技术援助项目实施单位和商务部分担。 技术方案变动风险是指因原定技术援助方案的失误、缺陷、错漏等导致不能实现预定技术援助目标，应当相应调整技术援助方案造成的影响，风险责任由技术援助项目实"},{"i":45,"n":"第四十五条","txt":"商务部通过合同补款方式对于技术援助项目实施过程中发生的政治外交风险和业主责任风险承担责任。"},{"i":46,"n":"第四十六条","txt":"商务部通过承担合同约定项目附带货物运输保险及其他必要的保险费用，以及将项目附带工程纳入商务部统一建立的成套项目工程保险制度范围投保并承担相关保险费用，合理分担总承包企业的不可抗力风险。超出约定保险以外的不可抗力风险由总承包企业承担。"},{"i":47,"n":"第四十七条","txt":"由受援方组织实施的技术援助项目，商务部应当在可行性研究阶段与受援方确认以下条件： （一）受援方具备完备的招投标法律制度和管理体系； （二）受援方具有独立组织实施的能力与经验，并愿意接受中方的外部监管； （三）项目投资限额明确，中方和受援方的分工责任和费用承担划分清楚，风险可控。 受援方组织实施的技术援助项目原则上不附带工程。"},{"i":48,"n":"第四十八条","txt":"对于受援方组织实施的技术援助项目，由受援方从中方推荐企业范围内依据其法律法规规定的招标程序选定实施企业。 项目管理机构负责与受援方商定推荐实施企业的范围和条件。项目管理机构在征求驻受援国使领馆经济商务机构和行业组织意见后，根据企业技术资质、项目实施能力及诚信表现等条件确定向受援国推荐的中资企业名单。 推荐的中资企业可与受援方当地企业组成联合体或建立专业分包关系。"},{"i":49,"n":"第四十九条","txt":"对于受援方组织实施的技术援助项目，项目管理机构负责与受援方签订项目实施纪要，约定双方权利义务。 项目管理机构应当按援外项目采购规定选定中方项目管理单位对受援方组织实施技术援助项目进行有限监管。 技术援助项目管理单位的职责主要包括： （一）监督受援方的招投标程序，评估其招投标程序的合规性并对招投标结果予以确认； （二）对项目合同执行情况进行监控，定期向项目管理机构提交专题报告； （三）审核受援方提出的拨款申请； （四）对受援方提交的项目实施内容变更申请进行初步审查，并向项目管理机构提出处理意见。 在实施监管过程中，技术援助项目管理单位发现正在或将要发生偏离技术援助目标的违约或违规事项，应当以书面形式向受援方提出整改建议。如受援方未及时采取有效措施，技术援助项目管理单位应当及时报告项目管理机构，项目管理机构可以暂停或终止对项目资金拨付申请的审核。"},{"i":50,"n":"第五十条","txt":"对于受援方组织实施的技术援助项目，项目资金应当依据受援方与实施企业签订的合同和经技术援助项目管理单位审核签发的拨款申请直接拨付到实施企业账户。"},{"i":51,"n":"第五十一条","txt":"受援方组织实施的技术援助项目完成后，技术援助项目管理单位负责对技术成果的内容完整性、深度的符合性及科技创新性进行预审核，并与受援方共同对技术援助项目进行成果验收。 技术援助项目管理单位应当及时促请受援方提交相关技术资料及成果文件，并报项目管理机构备案。 项目管理机构负责与受援方办理技术援助项目完成确认证书，并及时向商务部提交技术援助项目完成报告。"},{"i":52,"n":"第五十二条","txt":"对于受援方组织实施的技术援助项目，项目管理机构依据立项确定的投资预估算对受援方进行投资目标控制。受援方与相关实施企业签订的实施合同总价应当控制在投资预估算范围内。 项目实施过程中，因合同变更、索赔等原因造成合同超支的，超出部分由受援方承担；调减合同价款的，按照调减后的合同价款进行资金拨付。"},{"i":53,"n":"第五十三条","txt":"项目管理机构应当按照本办法规定的职责组织实施技术援助项目，并向商务部履行有关备案和报批手续；建立健全信息报告制度，按月向商务部报送项目执行情况；针对项目执行过程中出现的重大问题，及时向商务部专题报告。 商务部负责对项目管理机构组织实施的技术援助项目进行监督检查。"},{"i":54,"n":"第五十四条","txt":"项目管理机构依据合同对技术援助项目实施单位境内境外资金进行监督管理，确保援外资金专款专用，单独核算，不挪作他用。"},{"i":55,"n":"第五十五条","txt":"项目管理机构应当建立重大技术援助项目巡视检查制度，现场监督检查技术援助项目实施单位及其附带工程实施企业落实援外项目管理制度和合同约定的情况。"},{"i":56,"n":"第五十六条","txt":"技术援助项目实施单位有以下行为之一的，除按合同规定承担赔偿责任外，商务部给予警告，可以并处三万元人民币以下罚款，并可以依法公布处罚决定；违反相关法律、行政法规规定的，依法给予行政处罚；构成犯罪的，依法追究刑事责任： （一）违反本办法规定，将所承担的实施任务转包或违法分包的； （二）违反本办法规定，挪用援外项目资金的； （三）擅自改变经审定的技术专家、技术方案、工艺或实施流程，造成项目无法实现援助效果的； （四）未按照合同履行或延迟履行义务，影响项目正常实施，对外造成不良影响的。 项目实施单位违反本条第一款规定受到行政、刑事处罚的，自行政处罚生效之日起二至六年内，不选定其参与技术援助项目。"},{"i":57,"n":"第五十七条","txt":"技术援助项目实施单位在参与技术援助项目采购过程中，有下列情形之一的，商务部给予警告，可以并处三万元人民币以下罚款；违反相关法律、行政法规规定的，依法给予行政处罚；构成犯罪的，依法追究刑事责任： （一）弄虚作假，获取不正当竞争优势的； （二）与其他参与采购单位串通，谋取非法利益的； （三）与采购代理机构恶意串通，或向采购代理机构、评审专家行贿或提供其他不正当利益的； （四）在采购承诺有效期内实质性变更承诺的。"},{"i":58,"n":"第五十八条","txt":"技术援助项目实施单位主要负责人、项目负责人及直接责任人未履行法律法规和对外援助管理有关规定，造成严重后果的，商务部给予警告，可以并处三万元人民币以下罚款；违反相关法律、行政法规规定的，依法给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":59,"n":"第五十九条","txt":"商务部和援外项目管理机构工作人员在项目管理和组织实施过程中有下列行为之一的，视情节轻重给予相应的行政处分；构成犯罪的，依法追究刑事责任： （一）利用职务便利索取他人财物，或非法收受他人财物为他人谋取利益的； （二）滥用职权、玩忽职守或徇私舞弊，致使国家利益遭受损失的； （三）泄露国家秘密的。"},{"i":60,"n":"第六十条","txt":"对优惠贷款项下的援外项目、因严重自然灾害或其他不可抗力事件所实施的紧急援助项目以及涉及国家安全和秘密的援助项目，另有规定的，从其规定。"},{"i":61,"n":"第六十一条","txt":"本办法所称“以上”、“以下”包含本数。"},{"i":62,"n":"第六十二条","txt":"本办法由商务部负责解释。"},{"i":63,"n":"第六十三条","txt":"本办法自2016年1月8日起施行。"}],"duiwaiyuanzhuchengtaoxiangmuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对外援助成套项目的管理，保证项目质量，提高援助效果，依据有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称成套项目，是指中方在援外资金项下，通过组织或指导施工、安装和试生产等全部或部分阶段，向受援方提供用于生产生活、公共服务等成套设备和工程设施，并提供建成后长效质量保证和配套技术服务的援助项目。"},{"i":3,"n":"第三条","txt":"成套项目采取“中方代建”或“受援方自建”的管理模式。 “中方代建”是指中国政府受受援方委托负责成套项目的勘察、设计、建设和调试运行全过程或其中部分阶段任务，以“交钥匙”形式交付受援方使用，并提供建成后长效质量保证和配套技术服务的管理模式。 “受援方自建”是指受援方在中国政府援助资金和技术支持下，负责成套项目的勘察、设计和建设全过程或其中主要阶段任务，并相应承担建成后运营、维护责任，中国政府对受援方自建项目实施外部监管的管理模式。 在中方代建和受援方自建管理模式下，中方可与受援方按照分工合作的原则合理界定成套项目具体任务分工。"},{"i":4,"n":"第四条","txt":"商务部负责成套项目的立项、管理和监督。 援外项目管理机构依据本办法规定具体组织、管理和监督成套项目的实施，并接受商务部的监督。"},{"i":5,"n":"第五条","txt":"驻受援国使领馆经济商务机构协助商务部办理与成套项目实施管理有关的政府间事务，负责成套项目实施的境外监管。"},{"i":6,"n":"第六条","txt":"各省级商务主管部门协助商务部处理成套项目援助管理事务。"},{"i":7,"n":"第七条","txt":"中方代建项目实行“项目管理+工程总承包”的实施方式和企业承包责任制。 项目管理企业和工程总承包企业根据不同的项目承包方式分别承担项目的专业考察、工程勘察、各阶段设计、项目管理和工程建设任务，并承担相应法律责任。"},{"i":8,"n":"第八条","txt":"成套项目一般采用“采购—施工”（以下简称P-C方式）承包方式，即项目管理企业承担成套项目的专业考察、工程勘察、方案设计、深化设计（以下合并简称勘察设计）和全过程项目管理任务；工程总承包企业承担施工详图设计和工程建设总承包任务。"},{"i":9,"n":"第九条","txt":"成套项目同时符合以下规定条件的，可以采用“设计—采购—施工”（以下简称EPC方式）承包方式，即项目管理企业承担全过程项目管理任务；工程总承包企业承担勘察设计、施工详图设计和工程建设总承包任务： （一）拟建项目技术指标明确，对交付成果和项目实施结果可以进行准确的技术描述； （二）可以依据公布的技术标准或规程组织验收； （三）项目进度计划可控，具有明确的开始和结束时间预测； （四）投资限额明确，可依据经验数据及可行性研究报告直接估算； （五）成本风险可控，实施企业可合理承担项目实施过程中的预期风险。 成套项目EPC承包方式主要适用于生产型项目、技术简单的基础设施项目或无需复杂设计的设备安装项目。"},{"i":10,"n":"第十条","txt":"承担成套项目勘察设计任务的企业应对勘察设计及施工详图设计的质量、进度、安全生产及项目投资控制负责。 承担成套项目工程建设总承包任务的企业应对工程建设所涉及的质量、进度、安全生产以及工程建成后的长效质量保证和配套技术服务负责。 承担成套项目管理任务的企业应对成套项目勘察设计、施工详图设计及工程建设全过程进行协调、控制和管理，并对涉及的质量、进度、安全生产及投资控制承担连带责任。"},{"i":11,"n":"第十一条","txt":"项目管理机构应在经商务部认定的援外项目实施企业范围内根据援外项目采购规定选定工程总承包企业和项目管理企业。 商务部可根据国家区域发展政策选定成套项目工程总承包企业和项目管理企业。"},{"i":12,"n":"第十二条","txt":"项目管理机构在选定项目管理企业时应同时确定项目设计方案或管理方案，必要时也可在设计方案确定后再选定项目管理企业。 中标的项目管理企业应在签订合同前向项目管理机构提交以商务部为受益人且覆盖其承包责任范围的职业责任保险，并承担保费。"},{"i":13,"n":"第十三条","txt":"采用P-C承包方式的，项目管理机构在选定工程总承包企业时依据项目管理企业编制的深化设计文件组织采购。 采用EPC承包方式的，项目管理机构在选定工程总承包企业时依据项目管理企业编制的工程总承包招标方案组织采购。招标方案至少包括：工程技术方案（包括功能性、数量性指标以及配套的设计标准、质量等级、性能指标和实现方法）、验收技术标准或规程、项目进度要求、主要设备材料技术规范、工程量估算、投资估算以及工程建设阶段可能会出现的特殊风险因素。 中标的工程总承包企业应在签订合同前，向项目管理机构提交以商务部为受益人且覆盖其承包责任范围的职业责任保险和工程质量缺陷责任保险，并承担保费。"},{"i":14,"n":"第十四条","txt":"在选定工程总承包企业时，项目管理企业应配合项目管理机构制定资格审查和招标方案并提供配套技术文件、对招标方案和配套技术文件进行技术性复核和澄清、组织推荐中标候选单位的承诺性答疑并就确定中标条件提出咨询意见。 项目管理企业应在履行配合招标职责过程中遵守关联回避、充分披露和合理谨慎的原则，对所提供的意见承担法律责任并纳入职业责任范围。"},{"i":15,"n":"第十五条","txt":"成套项目所需主项技术资质为两项以上的，可由符合所有主项技术资质的企业单独投标，也可由投标企业组成联合体投标。联合体各方不得再单独或者与其他投标企业另外组成联合体参与投标。 项目管理机构应在项目招标文件中明确组成联合体的条件。其中，联合体牵头单位应具备援外项目实施企业资格。"},{"i":16,"n":"第十六条","txt":"项目管理机构代表商务部向中标企业下达成套项目实施任务通知函。 成套项目实施任务通知函是企业办理项目相关工程技术人员出入境以及设备材料、施工机械机具和生活物资检验通关的依据。"},{"i":17,"n":"第十七条","txt":"中标企业不得将承包责任范围内的任务转包，也不得将关键性工作或主体性工程分包或分解成若干部分分包。 中标企业将本单位技术资质不能覆盖的非关键性工作或非主体工程分包给其他单位的，其分包内容、分包单位和分包金额应在投标文件中载明，作为中标条件审定并写入合同约定。 分包方式一旦确定，不得变更。中标企业应按投标文件中载明的分包方式签订分包合同并报项目管理机构备案。确需变更或新增分包的，应按变更合同程序办理。 中标企业应与派赴项目的中方工程技术人员直接签订劳务合同，建立劳动合同关系，保障中方工程技术人员的合法权益，不得进行劳务分包。 鼓励中标企业将适合受援国当地实施的非主体性工程内容进行当地分包实施或雇佣受援方劳务承担，分包事项及分包合同应报项目管理机构备案。中标企业组织当地分包或雇佣当地劳务的，应遵从受援国有关法律法规，加强分包管理、技术指导和技术转让。"},{"i":18,"n":"第十八条","txt":"商务部负责审批中方代建项目的可行性研究报告和立项建议书，并办理立项。 立项后，项目管理机构在政府间立项协议以及商务部批准的可行性研究报告和立项建议书范围内组织项目实施和管理。"},{"i":19,"n":"第十九条","txt":"中方代建项目的设计一般包括方案设计、深化设计和施工详图设计三个设计阶段，以及专业考察和工程勘察两个设计准备阶段。"},{"i":20,"n":"第二十条","txt":"承担勘察设计任务的企业应事先配备专门团队，制定工作计划和保障措施，提交项目管理机构备案，并根据投标承诺和合同约定完成勘察设计任务。设计工作应遵循规范适用、整体规划、功能优先、投资匹配、技术创新、绿色环保、便利维护和持续发展的设计原则。"},{"i":21,"n":"第二十一条","txt":"承担项目勘察设计任务的企业根据立项建议书的要求负责编制和完善方案设计。 方案设计应符合立项建议书的规定，其内容和范围、依据的技术规范标准及深度要求由项目管理机构在合同中规定。 方案设计文件经项目管理企业内审或审查确认后，应及时报项目管理机构备案。"},{"i":22,"n":"第二十二条","txt":"承担项目勘察设计任务的企业负责组织专业考察，应做好专业考察前的各项准备工作，在专业考察过程中及时研究汇总受援方意见、提出相关工作建议，配合项目管理机构开展方案设计对外商谈，并接受项目管理机构的指导和监督。 承担勘察设计任务的企业应在考察结束后编报专业考察报告。对外需提交的专业考察阶段成果文件由项目管理机构规定。"},{"i":23,"n":"第二十三条","txt":"在完成方案设计和专业考察并与受援方在技术层面充分做好技术沟通和准备的基础上，项目管理机构与受援方确认项目方案设计，并与受援方签订项目对外实施协议或纪要。 由于受援方原因不能在专业考察阶段签订对外实施协议的，项目管理机构可先与受援方签订勘察设计纪要，确定设计方案并约定勘察设计过程的职责分工，然后与受援方签订对外实施协议或纪要。"},{"i":24,"n":"第二十四条","txt":"承担项目勘察设计任务的企业负责建设场址的工程勘察，并在启动项目后续设计前及时将工程勘察报告报项目管理机构备案。 承担项目勘察设计任务的企业应提前拟定项目建设场址和建设边界范围内的工程勘察方案，充分采用勘探、测量、试验等必要技术措施实施工程勘察，并按行业要求编制工程勘察报告，全面准确反映建设场址的地形、地貌、地质、水文情况，作为开展下一阶段项目设计工作的技术依据。"},{"i":25,"n":"第二十五条","txt":"承担项目勘察设计任务的企业负责深化设计。 深化设计应符合方案设计的规定，满足项目管理机构组织工程总承包招标或能据以准确编制工程概算的要求，依据的技术规范和标准以及设计文件深度要求由项目管理机构在合同中规定。"},{"i":26,"n":"第二十六条","txt":"项目管理企业应对项目深化设计进行自检或审查，重点包括： （一）确认设计内容符合批准的立项建议书、对外商定的方案设计和工程勘察结果； （二）确认设计深度达到合同约定，无重大缺漏项； （三）确认设计技术规范、标准适用准确； （四）确认配套工程量清单、投资概算满足后续实施或工程招投标要求； （五）确认主要设备材料技术规范书内容完备、明确，可以据以进行设备材料选型，且无指定或变相指定产品的违规情况。 承担项目勘察设计任务的企业应根据项目管理企业的审查意见，对深化设计进行修改，并提交项目管理企业审查批准。 对外实施协议对受援方审查深化设计有规定的，项目管理企业应将经内审或审查批准的深化设计文件提交受援方审查，完成必需的对外审查确认手续。 项目管理企业应在完成上述深化设计内部审查和对外审查程序后，将最终审定的深化设计文件报项目管理机构备案。"},{"i":27,"n":"第二十七条","txt":"工程总承包企业依据深化设计文件进行项目施工详图设计。 施工详图设计应符合深化设计的规定，能据以准确编制工程量清单和施工预算以及施工组织设计，满足设计材料选型采购以及非标准设备、构件制作需要，据以施工和安装以及进行工程检查验收，设计文件深度要求由项目管理企业与工程总承包企业明确。 施工详图设计可以根据工程进度分阶段编制，报项目管理企业审批后据以直接指导施工。"},{"i":28,"n":"第二十八条","txt":"项目管理企业应成立项目现场管理组，对项目进行现场管理。现场管理组由负责设计管理、施工监管、质量安全控制以及对外协调的专业工程技术人员组成，具备现场审批施工图纸、全过程质量安全监理以及代表项目管理机构与受援方进行对外实施协议协调履约的能力。其中，组长应具备设计咨询高级专业技术职称、二级以上注册建造师资质或施工监理执业资格及工程项目管理经验。项目管理企业现场管理组的人员组派由项目管理企业提交项目管理机构批准，并报驻受援国使领馆经商机构备案。 工程总承包企业应成立国内后勤组和施工技术组分别负责对项目的国内支持服务和现场施工组织管理。施工技术组至少由组长、总工程师、质量员、安全员和其他相关专业工程技术人员组成，其中，施工技术组组长应具备二级以上项目注册建造师和工程项目管理经验，质量员和安全员应具备国内建设主管部门批准的岗位执行资格和从事相关工作经验。施工技术组组长及主要人员由工程总承包企业提交"},{"i":29,"n":"第二十九条","txt":"在项目施工前准备阶段，项目管理企业应会同工程总承包企业组织施工前技术交底会，澄清技术问题、对接管理程序并部署施工准备。技术交底会由项目管理企业主持，主要设计人员、项目现场管理组、国内后勤组和施工技术组主要技术和管理负责人参加，项目管理机构派人监督。 技术交底会的会议纪要应报项目管理机构备案。"},{"i":30,"n":"第三十条","txt":"工程总承包企业应根据施工前技术交底共识，在中标条件基础上修改完善施工组织设计以及后勤保障、采购供应和质量、进度、安全保证等专项计划，报项目管理企业批准。 项目管理企业根据施工前技术交底共识以及工程总承包企业编报的施工组织设计和各类专项计划，完善项目管理计划，连同最终批定的施工组织设计和各类专项计划报项目管理机构备案。"},{"i":31,"n":"第三十一条","txt":"工程总承包企业负责组织施工所需机械机具和设备材料的采购和运输，并接受项目管理企业的监督。 从中国关税境内采购发运设备、材料的品质检验、口岸验放按照有关对外援助物资检验和验放管理规定执行。 项目管理企业根据项目管理计划采取见证抽样、见证检验以及驻厂监造等必要的监管措施。"},{"i":32,"n":"第三十二条","txt":"项目管理企业与工程总承包企业应共同做好施工前现场准备工作。 工程总承包企业应及时完成与受援方的施工现场移交、临时设施建设和工程用市政条件联接，并组织首批工程技术人员、施工机械机具和设备材料抵达施工现场。 项目管理企业应做好配合工作，及时派驻现场管理组并监督检查工程总承包企业的施工现场准备情况。"},{"i":33,"n":"第三十三条","txt":"项目管理企业应会同工程总承包企业促请受援方履行政府协议和对外实施协议规定的职责，并协助受援方解决有关技术问题。 受援方派遣工地代表的，项目管理企业应与受援方商定工地代表的职责，建立现场工作机制。"},{"i":34,"n":"第三十四条","txt":"项目管理企业根据工程总承包企业提交的开工申请，确认所有施工前准备工作完成、开工所需人员、设备材料和施工机械、机具入场，满足开工条件后书面下达开工令并书面通知受援方，同时报项目管理机构和驻受援国使领馆经商机构备案。开工令是正式起算项目合同工期的依据。"},{"i":35,"n":"第三十五条","txt":"项目管理企业对进入施工现场的一切设备材料和施工机械、机具进行监管。 所有进入施工现场的设备材料和施工机械、机具应由工程总承包企业报项目管理企业签认，并提供品质符合设计要求的证明。 已经签认进入施工现场的设备材料和施工机械、机具因合理理由需退场的，工程总承包企业应报项目管理企业批准。 所有设备材料应由工程总承包企业安全存放和有序管理，并在使用前按规定的试验规程或标准进行检测试验。涉及主体或结构安全的试块、试件以及材料应在项目管理企业现场监督下取样并送具有相应资质的检测单位进行检测。未经检测或检测不合格的不得使用。 因与设计要求和质量标准不符合或未经签认的设备材料和施工机械、机具，工程总承包企业应按项目管理企业要求运出施工现场。"},{"i":36,"n":"第三十六条","txt":"项目管理企业应对工程总承包企业进入施工现场的所有人员进行监管。 工程总承包企业应将进入或退出现场的人员名单报项目管理企业审核。其中，施工技术组组长及主要管理人员、特种作业人员和高危作业人员应符合有关执业资格要求，并持证上岗；所有工程技术人员应与工程总承包企业具有劳动合同关系。 工程总承包企业应对进入施工现场的管理人员和工程技术人员进行管理，建立、健全岗位教育和培训制度，督促其遵守当地法律法规和外事纪律，维护其人身财产安全、生活保障、人格尊严、宗教信仰等合法权益，依法、合规处理劳务纠纷。"},{"i":37,"n":"第三十七条","txt":"项目管理企业负责对工程总承包企业的施工全过程进行监管，并与工程总承包企业共同承担项目的质量、进度、安全和投资控制责任。 项目管理企业应及时审批工程总承包企业报送的施工组织设计及其他专项计划、专项施工调整方案，监督其按批准的计划或方案现场施工。 项目管理企业负责审批施工详图设计并监督工程总承包企业按图施工。 项目管理企业应监督工程总承包企业加强工序管理，落实各工序施工前技术交底、工序自检和交接检查程序，保证上道工序合格后才能进入下道工序，并对隐蔽工程和关键部位施工实施旁站监督。 项目管理企业应监督工程总承包企业做好分部分项工程的日常质量自检，及时审核办理分部分项工程质量验收、工程量测量核定和节点合同价款拨款申请。 项目管理企业应监督工程总承包企业贯彻GB/T19000和GB/T50430质量体系标准、GB/T24000环境管理体系标准和GB/T28000职业健康安全标准，提前制订和实施贯"},{"i":38,"n":"第三十八条","txt":"施工过程中如发现已批准的设计文件、施工组织设计、专项计划、专项施工方案等存在错误或按原定技术路径不能达成技术目标的，项目管理企业和工程总承包企业可进行技术洽商与变更。 技术洽商方案由工程总承包企业提出，经项目管理企业批准后，双方签订技术洽商纪要予以确认。项目管理企业不得越权批准任何导致变更合同条件的洽商事项，也不得批准仅为简化施工或减少工程量、可能降低设计标准或影响使用功能、可能引起索赔或争议及其他缺乏技术必要性的洽商事项。项目管理企业应将技术洽商纪要及时报项目管理机构备案。 对于超出项目管理合同授权和工程总承包合同范围内的技术洽商事项，由项目管理企业出具审核意见，报项目管理机构处理。"},{"i":39,"n":"第三十九条","txt":"工程总承包企业应在项目建设过程中对受援方指派的管理维护人员进行必要的技术指导和岗位培训，使其熟悉相关设备的操作，主要设备材料的维护保养要求，易损件的更换途径等，使受援方在项目建成后基本具备操作、维护和管理的能力。 项目管理企业应对工程总承包企业落实建设过程中的技术培训职责进行监督指导。"},{"i":40,"n":"第四十条","txt":"施工过程中，项目管理企业应在项目管理机构的指导下代表项目管理机构与受援方沟通对外实施协议的执行事宜。 如遇对外实施协议的实质性变更或争议等重大问题，项目管理企业应根据现场情况制订应对方案，报项目管理机构审定后对外磋商。 项目管理企业对外磋商应采取书面形式并妥善保存。 工程总承包企业应配合项目管理企业与受援方对外磋商，并服从项目管理企业的协调。"},{"i":41,"n":"第四十一条","txt":"项目管理企业应会同工程总承包企业提前一个月向项目管理机构提出中期验收申请并联名附交自检中期报告。 项目管理机构负责组织项目中期验收并由验收专家组出具中期验收报告。结论为合格的中期验收报告是确认项目阶段性实现合同约定目标并准予进入后续施工的依据。 在不影响中期验收的情况下，经项目管理企业批准，工程总承包企业可以提前适度进行后续施工。"},{"i":42,"n":"第四十二条","txt":"项目管理企业应会同工程总承包企业提前一个月向项目管理机构提出竣工验收申请并联名附交自检总结报告。 项目管理机构负责组织项目竣工验收并由验收专家组出具竣工验收报告。结论为合格的竣工验收报告是确认项目全面实现合同约定目标并准予办理对外技术验收和移交手续的依据。"},{"i":43,"n":"第四十三条","txt":"工程总承包企业应以经项目管理企业批准的施工详图为基础，结合施工过程的技术洽商和变更以及实际检查验收情况，编制项目竣工图，如实反映工程的最终实物结果。 竣工图应随施工过程使用中、外文及时编制，不得在工程竣工后补编。竣工图应由工程总承包企业加盖“竣工图”标识，施工技术组组长和竣工图编制人员签章，并经项目管理企业审核后由项目管理组长签字确认。 竣工图纳入项目管理机构的竣工验收范围。"},{"i":44,"n":"第四十四条","txt":"工程总承包企业负责编制项目维护使用指导手册，项目管理企业对编制工作进行监督审核。维护使用指导手册应纳入项目管理机构的竣工验收范围。 维护使用指导手册须用中、外文对应编制，确保内容完整、准确，且不得以产品自带说明代替维护使用指导手册。"},{"i":45,"n":"第四十五条","txt":"项目竣工验收合格后，项目管理机构应要求项目管理企业依据对外实施协议的约定与受援方共同组织项目的对外技术验收，在双方确认完成对外实施协议约定的项目建设内容后签订对外技术验收纪要。 对外技术验收后，项目管理机构代表商务部及时与受援方办理政府间移交手续。项目竣工图和维护使用指导手册应作为政府间移交手续的附件。 项目完成政府间移交手续后，项目管理机构应及时向商务部提交项目完成报告。"},{"i":46,"n":"第四十六条","txt":"除受援方负责已建成项目的运营管理外，工程总承包企业应对已建成移交的项目提供长效技术支持。 对于受援方需要中方在项目建成后继续提供必要援助合作支持的，商务部可在立项阶段与受援方商定援助合作安排，在立项协议和对外实施协议中规定，由项目管理机构一并纳入工程总承包范围组织实施。 对于超出援助合作以外的长效技术支持，工程总承包企业应在项目竣工移交前与受援方就合作内容、服务期限、实施方案和费用承担通过商业合同予以确定。"},{"i":47,"n":"第四十七条","txt":"项目管理企业和工程总承包企业应按照本办法和合同约定承担项目的质量责任，项目管理机构负责对质量责任的落实进行监督管理。"},{"i":48,"n":"第四十八条","txt":"商务部制定并发布《对外援助成套项目主要设备材料指导目录》（以下简称《主材目录》），根据市场声誉、供货保证、境外服务能力等要素明确对外提供成套项目主要设备材料的政策导向和推荐原则。 《主材目录》用于指导成套项目的可行性研究和立项工作。"},{"i":49,"n":"第四十九条","txt":"承担项目工程勘察的企业应承担以下义务： （一）在依法取得的技术资质许可范围内开展工程勘察，不转包和违法分包； （二）按照国家有关技术规范和标准并结合受援方相关特殊技术要求实施工程勘察，对工程勘察成果的质量负责； （三）在做好勘察、测量、现场原位测试和室内试验等技术工作的基础上，结合工程特点编制工程勘察成果文件； （四）保证工程勘察成果文件全面、真实、准确，满足设计、施工和岩土治理的需要，并经注册执业资格人员签字确认。"},{"i":50,"n":"第五十条","txt":"承担项目方案设计、深化设计和施工详图设计任务的企业应承担以下义务： （一）在依法取得的技术资质许可范围内开展工程设计，不转包和违法分包； （二）按照工程勘察成果文件和本办法规定的设计原则进行工程设计，保证设计文件由注册执业人员签字确认，对设计文件质量负责； （三）在政府间立项协议规定和商务部批定的可行性研究报告、立项建议书范围内进行分阶段设计，确保分阶段设计文件符合上一阶段设计文件的规定，设计文件深度达到规定要求； （四）保证设计文件完整、准确，不存在未设计内容或以规范、图册代替设计的内容； （五）设计文件选用的设备、材料和构配件应注明规格、型号、性能等技术指标，质量应符合中国或受援国规定和合同约定的标准。除有特殊要求的材料、专用设备和工艺生产线等，不通过设计指定或变相指定产品或供应商。"},{"i":51,"n":"第五十一条","txt":"工程总承包企业应承担以下义务： （一）在依法取得的技术资质许可范围内承担项目施工任务，不转包和违法分包； （二）按照批准的施工详图设计和施工组织设计以及合同约定的施工技术标准，并结合受援方特殊技术要求组织施工。在施工过程中发现设计文件和图纸有差错的，应及时提出修改建议报项目管理企业解决； （三）在施工过程中全面贯彻GB/T19000、GB/T50430质量体系标准和GB/T24000环境管理体系标准，建立健全贯彻标准的保证体系和质量责任制； （四）按工程设计和合同约定采购供应工程所需设备材料和施工机械机具并保证其质量，依法办理援外物资检验和通关验放手续； （五）建立、健全施工过程的检测试验制度，根据设计确定的技术标准和合同约定对设备材料等进行检验； （六）严格施工过程的工序管理。对施工过程中出现的质量问题或检查验收不合格的工程及时予以返修。"},{"i":52,"n":"第五十二条","txt":"除因受援方使用不当引致的质量问题外，工程总承包企业应对其承包责任范围内的建成项目，在合理使用期限内终身承担无缺陷质量保证责任。 项目的无缺陷质量保证期自项目管理机构完成竣工验收且办理完毕对外技术验收手续之日开始起算，在正常使用条件下的分部分项工程的质量保证最低年限执行中国国家标准或受援国当地法律法规的强制性规定（以期限长者为准），中国国家标准或受援国当地法律法规无规定的，由项目管理机构与工程总承包企业在合同中约定。 工程总承包企业应在提交项目竣工验收申请时一并向项目管理机构出具无缺陷质量保证书，明确项目各部分及设备材料的无缺陷质量保证范围、保证期限和相关的保修责任，制订并相应实施质量保修计划，至少在项目竣工后两年内现场留驻质量保修团队，确保质量保证期限内返工、返修所需人力物资等配套资源提供和及时抵达现场，并承担质量保修费用。"},{"i":53,"n":"第五十三条","txt":"商务部负责在立项阶段确定项目建设期限。项目建设期限一经确定，不得随意变动。 受援方对缩短项目建设期限有要求的，商务部应将设定特殊建设期限及由此产生的配套赶工措施和额外投资一并纳入立项范围与受援方商定。 商务部负责对项目管理机构组织实施项目全过程按项目建设期限进行目标管理；项目管理机构通过采购程序对项目管理企业和工程总承包企业承担勘察设计和施工建设任务的期限进行合同进度管理。"},{"i":54,"n":"第五十四条","txt":"项目管理企业和承担项目勘察设计任务的企业应共同承担勘察设计进度控制责任。 承担勘察设计任务的企业应将可能影响勘察设计进度的外部因素一并纳入勘察设计进度控制范围，在出现受援方配合不力和风险因素等不利情况下，主动采取必要措施加强对外沟通协调和风险应对，保证按合同进度完成勘察设计任务。 项目管理企业应对勘察设计进度进行自检或监督控制，及时研究或帮助解决影响勘察设计进度的突出问题。"},{"i":55,"n":"第五十五条","txt":"项目管理企业和工程总承包企业应共同承担项目工期进度控制责任。 工程总承包企业应将可能影响施工进度的外部因素一并纳入工期进度控制范围，在出现受援方配合不力和风险因素等情况下，主动采取必要措施加强对外沟通协调和风险应对，保证按合同进度完成施工任务。 项目管理企业应对工程总承包企业的工期进度进行监督控制，协助工程总承包企业解决影响工期进度的突出问题。"},{"i":56,"n":"第五十六条","txt":"由于本办法规定的业主责任和不可抗力等原因，且相关责任企业已采取必要措施仍导致项目勘察设计和工程建设不能实现约定进度的，项目管理机构可与相关企业调整合同进度。 相关企业应提出合同进度调整方案，经项目管理企业审核后报项目管理机构。项目管理机构与企业签订补充合同进行合同进度调整。 合同进度调整超出项目对外实施协议规定期限的，项目管理机构应与受援方签订对外实施补充合同。"},{"i":57,"n":"第五十七条","txt":"项目施工期间，除以下情况外，工程总承包企业不得自行暂停项目部分或全部的施工： （一）由于本办法规定的业主责任或不可抗力风险导致不能继续施工的； （二）为应对重大质量安全事故需要暂停项目某一部分或全部施工的； （三）发现勘察设计或施工质量问题，继续施工可能会导致更大损失的。 工程总承包企业应及时向项目管理企业提出部分停工或停工申请，说明理由以及恢复施工时间或条件，经批准后暂停施工。 在暂停期间，工程总承包企业应进行保护、保管，保证该部分或全部工程不产生变质、损失或损害。 具备恢复施工条件后，工程总承包企业应及时向项目管理企业提出复工申请，经批准后恢复施工。 项目管理企业为履行项目管理职责，也可以主动向工程总承包企业下达停工令，明确停工理由及恢复施工时间或条件。 项目管理企业应将全部停工及超过七天以上的部分停工事项报项目管理机构备案。"},{"i":58,"n":"第五十八条","txt":"商务部和项目管理机构负责根据立项批准的项目投资限额，对项目投资全过程实施限额目标管理和逐级投资控制。 特殊情况下确需调整项目投资限额的，商务部应按原立项程序重新批准。"},{"i":59,"n":"第五十九条","txt":"项目立项准备阶段，商务部依据项目可行性研究报告和立项建议书审定投资预估算，并以此为基准增列一定比例的风险准备金后确定投资限额。风险准备金用于补充在项目实施过程中非因项目管理企业或工程总承包企业责任导致的投资增加。商务部负责审批风险准备金的使用。 风险准备金的调整系数根据受援国和项目所在地政治安全形势、受援方履行中外分工的能力、项目技术复杂程度、项目实施方式等综合因素确定，具体确定办法详见附表1。"},{"i":60,"n":"第六十条","txt":"承担项目方案设计的企业应以方案设计为基准编制项目投资估算，并报项目管理机构备案。投资估算应控制在投资预估算范围内。 项目投资估算应遵循以下原则： （一）涵盖项目建设所需全部费用； （二）保证投资与拟建项目内容相匹配； （三）各类间接费费率符合商务部规定取费标准； （四）合理预估项目实施过程中的不可预见因素和物价上涨风险。"},{"i":61,"n":"第六十一条","txt":"采用P-C承包方式的项目，由项目管理企业按深化设计文件编制投资概算，报项目管理机构备案。采用EPC承包方式的项目，由工程总承包企业按深化设计文件和行业要求编制投资概算，报项目管理企业审查。 投资概算应控制在投资估算范围内，并与深化设计内容相匹配，科学设定项目单位造价、设备和材料总价、材料用量、单位用工量、国际和当地运保费、综合人工单价和工期等主要经济技术指标。"},{"i":62,"n":"第六十二条","txt":"项目投资由勘察设计费、项目管理费、项目前期工程费、建筑安装工程费和工程独立费五部分组成，项目投资的具体费用构成详见附表2。"},{"i":63,"n":"第六十三条","txt":"项目投资涉及的实物工程量或工作量应主要采取定额法编制，具体适用的投资编报定额根据工程设计阶段由项目管理机构确定。工程量或工作量单价根据对外援助有关规定或市场价格据实组价。 项目（修正）概算应以人民币、美元和当地货币分列，均以人民币为最终计价单位。人民币与美元的汇价，按编制（修正）概算时中国银行公布的美元卖出价计算，当地货币按受援国中央银行的美元对当地货币的美元买入价计算。"},{"i":64,"n":"第六十四条","txt":"项目管理企业和工程总承包企业按照本办法和合同约定承担项目的安全生产责任。项目管理机构负责对安全生产责任的落实进行监督管理。 项目的安全生产管理应遵守“安全第一、预防为主”的原则。"},{"i":65,"n":"第六十五条","txt":"承担项目工程勘察任务的企业应依照中国有关工程勘察的强制性标准和受援国法律法规有关工程勘察的强制性规定进行工程勘察，确保所提供的工程勘察文件真实、准确，满足项目安全生产的需要。在进行勘察时，责任企业应遵守勘察作业操作规程，采取措施保证各类管线、设施和周边建筑物、构筑物的安全。"},{"i":66,"n":"第六十六条","txt":"承担项目方案设计、深化设计和施工详图设计任务的企业应确保设计内容符合工程勘察结果和合同约定的技术规范标准，遵守中国国家标准和受援方法律法规有关工程安全的强制性规定，不存在可能导致安全事故的不合理设计内容。 对于项目设计采用的新技术、新工艺和新材料，责任企业应确保技术、工艺和材料的可靠性与安全性，并在设计中研究提出保障施工作业安全和预防安全生产事故的技术措施。 对于项目的隐蔽工程、主体结构等关键部位以及特殊结构，责任企业应在进行模型安全试验或严格计算的基础上确定设计方案。 对于项目涉及的维修、改扩建和拆除工程，责任企业应在对原建筑物或构筑物的结构安全性做出鉴定的基础上确定设计方案。 责任企业应在深化设计文件中制定安全专篇，重点阐明：针对施工现场和毗邻设施、管线的安全防护措施要求；针对安全施工所涉施工机械机具的特殊技术要求；针对分部分项工程内危险性较大部位和环节的安全技术措施等。"},{"i":67,"n":"第六十七条","txt":"工程总承包企业应在项目施工建设过程中建立健全安全生产规章制度和操作规程，落实安全生产责任制。 工程总承包企业应在施工技术组设立安全生产管理机构，成立以施工技术组组长为首的安全生产领导小组，负责现场安全施工。 工程总承包企业应在施工技术组配备安全员。安全员应具有本办法规定的岗位资格，上岗前接受援外管理制度和贯彻职业健康安全管理体系标准的专业培训，履行监督安全生产制度执行、组织安全生产教育和定期专项安全检查等岗位职责。 工程总承包企业应在经项目管理企业批准的施工组织设计指导下，按照规定的施工规范和标准组织施工。涉及危险性较大的分部分项工程和施工现场易发生安全生产事故的部位、环节，应在施工前编制专项安全施工方案并附具安全验算结果，必要时，应组织专家对安全施工方案进行论证和审查。 工程总承包企业应在工序施工前组织安全施工技术交底，落实安全施工技术要求并做好技术交底记录。 工程总承包企业应建立健"},{"i":68,"n":"第六十八条","txt":"项目管理企业和工程总承包企业应为本企业派赴境外执行项目任务的中方人员办理人身意外伤害保险，保险责任和保险条件以中国相关法律法规为准，应覆盖境外执行任务的主要风险，并承担保险费用。 项目管理企业和工程总承包企业应为本企业在境外雇佣承担项目任务的外方工程技术人员或劳务人员办理人身意外伤害保险，保险责任和保险条件以受援国当地相关法律法规为准，并承担保险费用。"},{"i":69,"n":"第六十九条","txt":"商务部按照市场化原则建立项目的风险承担机制，明确项目涉及的风险，规范风险承担主体责任，并配套完善相应的责任保险和工程保险制度。"},{"i":70,"n":"第七十条","txt":"项目涉及的风险因素主要包括政治外交风险、业主责任风险、不可抗力风险、设计变更风险和经营性风险等五类。对于项目实施过程中发生的政治外交风险和业主责任风险，商务部通过合同补款方式承担责任；商务部以承担工程保险费用为限和相关企业分担不可抗力风险；设计变更风险和经营性风险，由相关企业承担。"},{"i":71,"n":"第七十一条","txt":"商务部按照“政策性保障、市场化运作”的原则建立健全项目的配套工程保险和责任保险制度。 工程保险用于分担不可抗力风险，由责任企业作为投保主体，责任企业和商务部为保险共同受益人，保险费用由商务部承担。超出工程保险以外的不可抗力风险，由相关责任企业承担。 职业责任保险用于承担项目勘察设计和项目管理的职业责任，由责任企业作为投保主体，商务部为保险受益人，保险费用由责任企业承担。 工程质量缺陷保险用于承担项目工程质量的无缺陷保证责任，由责任企业作为投保主体，商务部为保险受益人，保险费用由责任企业承担。 具体保险方案由商务部另行规定。"},{"i":72,"n":"第七十二条","txt":"项目实施过程中发生政治外交风险和业主责任风险的，责任企业应在出险后六十日内根据实际损失情况和合同约定及时提出合同价款和合同期限补偿申请，说明事由、责任方及报价依据，经项目管理企业审核后报项目管理机构。 项目管理机构应对材料的真实性、报价的合理性、理由的合规性进行复核后报商务部审批，并在商务部批准后与相关企业签订补充合同予以规定。必要时，项目管理机构应赴现场核实情况。 责任企业无正当理由，在出险后六十日内未及时提出补偿申请的，项目管理机构可不再受理，相关损失由责任企业承担。"},{"i":73,"n":"第七十三条","txt":"项目管理企业和工程总承包企业应在承包责任范围内，依据本办法和合同归集、整理项目技术资料，并将全套技术资料在项目完成竣工验收且办妥对外技术验收手续后六十日内向项目管理机构移交。"},{"i":74,"n":"第七十四条","txt":"项目技术资料具体划分为勘察设计文件、施工建设文件、竣工文件、检查验收文件和项目管理文件五个部分。 其中，勘察设计文件由承担勘察设计任务的企业承担管理责任；施工建设文件、竣工文件由工程总承包企业承担管理责任；检查验收文件和项目管理文件由项目管理企业承担管理责任。"},{"i":75,"n":"第七十五条","txt":"项目管理企业和工程总承包企业应随项目进度及时归集、整理项目技术资料，做到分类准确、资料齐全、字迹清楚、记录详实且无未了事项，真实、完整反映项目的实际情况，并具有可追溯性。 任何单位和个人不得伪造、变造、抽撤或故意损毁项目技术资料。"},{"i":76,"n":"第七十六条","txt":"项目技术资料的保存期应按照工程设计的合理使用年限确定，其中，竣工文件应永久保存。"},{"i":77,"n":"第七十七条","txt":"商务部建立项目技术资料库，委托相关项目管理机构负责技术资料库的具体管理。商务部负责保障技术资料库建设管理所需配套条件。 项目管理机构应加强技术资料库的规范化管理和安全防护，提高信息化水平，并按年度向商务部提交技术资料库管理的专题报告。"},{"i":78,"n":"第七十八条","txt":"项目的工程检查和验收分中期验收和竣工验收，由项目管理机构组织实施。 项目主体工程已按设计要求完工，自检并经项目管理企业检查合格，相关技术资料已按本办法规定整理完毕的，经项目管理企业会同工程总承包企业向项目管理机构正式提交申请，可以组织中期验收。 项目全部工程已按设计要求完工，主要工艺设备或配套装备经联运负荷试运行达到功能要求或形成生产能力，自检并经项目管理企业检查合格，相关技术资料已按本办法规定整理完毕的，经项目管理企业会同工程总承包企业向项目管理机构正式提交申请，可以组织竣工验收。 如提交验收申请的项目经现场核查实际不具备上述规定的中期验收或竣工验收条件，项目管理机构不得组织验收。 对于投资限额在五千万元人民币以下、技术较为简单的项目，项目管理机构可不从国内派组进行中期验收。"},{"i":79,"n":"第七十九条","txt":"项目管理机构应依法选定经商务部认定资格的顾问咨询单位组成验收专家组赴现场对项目进行验收，具体专家组组成人选由项目管理机构审定。 验收专家组组长应具有相关技术专业的高级技术职称或执业资格和工程管理或质量管理经验，成员应具有中级技术职称或执业资格和从事本专业工作经验，熟悉有关工程验收标准或相关施工技术规范。验收专家组成员不得与项目管理企业或工程总承包企业存在可能影响公正验收的利害关系。"},{"i":80,"n":"第八十条","txt":"在交付项目管理机构组织验收前，项目应按建设项目、单项工程、单位工程、分部工程和分项工程分为五个项目划分等级，完成质量检查并确认合格： （一）建设项目是指按一个总体设计进行施工，由一个或几个单项工程组成的工程整体，由项目管理企业在工程总承包企业自检基础上进行质量检查并确认合格。 （二）单项工程是指具有独立的设计文件，竣工后可以独立发挥工程作用和效益的工程，由项目管理企业在工程总承包企业自检基础上进行质量检查并确认合格。 （三）单位工程是单项工程的组成部分，一般项目主要划分为土木工程和设备安装工程两个单位工程，由项目管理企业在工程总承包企业自检基础上进行质量检查并确认合格。 （四）分部工程是单位工程的组成部分，一般按不同工程部位或专业工程类别进行划分，由工程总承包企业自检合格，报项目管理企业复核确认。 （五）分项工程或检验批是分部工程的组成部分，主要按专业工种进行划分，由工程总承包企业自检"},{"i":81,"n":"第八十一条","txt":"项目工程验收应依据政府立项协议、对外实施协议、内部承包合同和招投标承诺、工程设计文件和技术洽商以及合同约定的施工质量验收标准进行，按本办法规定的项目划分方式分级作出验收结果。 验收结果分为优良、合格和不合格三个评定等级： （一）合格。分部工程以下评定等级按有关行业施工质量验收标准进行；所有分部工程合格，该单位工程方可评定为合格；所有单位工程合格，该单项工程方可评定为合格；所有单项工程合格，该建设项目方可评定为合格。 （二）优良。质量控制资料完整、有关安全和功能的检验和抽样检测数量应符合有关规定。 分项工程以下，质量检查项目每项抽样检验100%符合设计要求和有关行业施工质量验收规范规定，计数抽样检测项目每项抽验点中，90%以上（钢结构工程为95%以上）实测值在有关行业施工质量验收规范规定的允许偏差范围内，且其它实测值最大偏差不超过允许偏差的1.2倍（钢结构工程为1.1倍），该检验批可评定"},{"i":82,"n":"第八十二条","txt":"分项工程质量不符合有关行业质量验收标准合格的规定时，应进行及时处理，并按以下规定确定其质量等级： （一）返工重做的可重新评定质量等级。 （二）经加固补强或经法定检测单位鉴定能够达到设计要求的，其质量仅应评定为合格。 （三）经法定检测单位鉴定达不到原设计要求，但经项目管理企业认可能够满足结构安全和使用功能要求可不加固补强的；或经加固补强改变外形尺寸或造成永久性缺陷的，其质量可定为合格，但所在分部工程不应评为优良。"},{"i":83,"n":"第八十三条","txt":"项目工程验收应由验收专家组按以下规定程序进行： （一）合同履约专项核查。 对项目管理企业和工程总承包企业履行合同规定的质量、进度、安全生产和投资控制责任包括现场技术洽商与变更审批、人员和劳务管理的合规性管理等进行专项评定。 合同履约存在严重缺陷或问题致使不能确认其工程质量结果的，应中止验收。 （二）施工技术资料核查。 全面审阅验收范围内工程的施工技术资料，主要包括：设备材料、构配件的质量合格证和检测试验报告；施工试验记录；施工记录；技术复核记录；隐蔽工程验收记录；分部分项工程质量自检和检查记录等。 施工技术资料管理存在严重缺陷或问题致使不能确定其工程质量结果的，应中止验收。 （三）复核确认。 对于已经工程已隐蔽部位或此前已经中期验收部分的验收结论予以复核确认，必要时，可进行破损检查和检测。 （四）实测检查。 通过抽查和核对、观感评定和实测实量相结合，按项目划分方式分级验收并评定等级。对"},{"i":84,"n":"第八十四条","txt":"验收专家组应根据验收结论现场编制中期或竣工验收报告，明确质量评定等级和专项评定结果，并对存在问题及后续工作提出处理意见和建议。 验收报告经验收专家组全体成员、现场管理组组长签字后生效。施工技术组组长或工程总承包企业现场负责人一般应对验收报告附署签字确认，未附署确认或拒绝附署确认的，不影响上述验收报告的效力。"},{"i":85,"n":"第八十五条","txt":"工程总承包企业应对工程质量验收过程中所发现的问题和验收报告提出的问题及时进行整改。 验收期间整改完毕的问题，由验收专家组作出整改结论并写入验收报告；无法在工程质量验收期间完成整改的问题，由项目管理企业监督工程总承包企业在规定期限内进行整改，将整改结果报验收专家组补充作出整改结论。"},{"i":86,"n":"第八十六条","txt":"为提高受援方的自主发展能力，中方鼓励采取受援方自建模式组织实施成套项目或成套项目的主要任务阶段。在受援方有明确意愿或中方代建存在实际困难的情况下，对于符合以下条件的成套项目，经与受援方商定，可以采取受援方自建模式： （一）受援方有完备的工程建设招投标法律法规制度和管理体系； （二）受援方有独立承担工程勘察设计能力或接受认可中方已完成的可行性研究、勘察设计等前期工作，具备组织实施的经验，并愿意接受中方的外部监管； （三）项目投资限额明确，中方和受援方的分工责任和费用承担划分清楚，风险可控。"},{"i":87,"n":"第八十七条","txt":"采取受援方自建模式的项目，由受援方从中方推荐企业范围内依据其法律法规规定的招标程序选定实施企业；经双方协商，也可以由受援方在受援方企业范围内选定实施企业。 项目管理机构负责与受援方商定推荐实施企业的范围和条件。项目管理机构在征求驻受援国使领馆经商机构和行业组织意见后，根据企业技术资质、项目实施能力及诚信表现等条件确定向受援国推荐的中资企业名单。 推荐的中资企业可与受援方当地企业组成联合体或建立专业分包关系。"},{"i":88,"n":"第八十八条","txt":"采取受援方自建模式的成套项目，项目管理机构应与受援方签订项目实施纪要，具体约定受援方自建的项目内容、技术标准、投资控制、监管代表和监管程序以及中外双方权利义务等。 项目管理机构应依法选定项目管理企业对受援方自建项目实施进行有限监管，确保受援方按政府间立项协议和项目实施纪要完成项目。项目管理企业应编制并执行项目监管计划，主要包括： （一）按中方评估的可行性研究报告和政府间立项协议监督受援方的招标准备技术工作； （二）监督受援方的招投标程序，评估其招投标程序的合规性并对招投标结果予以确认； （三）对项目合同执行情况及项目质量、进度、安全和投资控制进行监控，定期向项目管理机构提交专题报告； （四）审核受援方提出的拨款申请； （五）对受援方提交的项目变更申请进行初步审查并向项目管理机构提出处理意见。 在实施有限监管过程中，项目管理企业发现正在或将要发生对项目质量、安全、工期等造成重大危害的违约"},{"i":89,"n":"第八十九条","txt":"采取受援方自建模式的项目，项目资金应依据受援方与实施企业签订的合同和经项目管理企业审核签发的拨款申请直接拨付到实施企业账户，并接受相关主管部门对资金使用情况的监督检查。"},{"i":90,"n":"第九十条","txt":"采取受援方自建模式的项目结束后，项目管理企业和受援方共同对项目进行竣工验收。 项目管理企业应及时促请受援方提交项目验收报告和配套成果文件，并报项目管理机构备案。 项目管理机构负责与受援方办理项目完成确认证书。"},{"i":91,"n":"第九十一条","txt":"对于采取受援方自建模式的项目，项目管理机构依据立项确定的投资预估算对受援方进行投资目标控制。受援方与相关实施企业签订的实施合同总价应控制在投资预估算范围内。 项目实施过程中，因合同变更、索赔等原因造成合同超支的，超出部分由受援方承担；调减合同价款的，按照调减后的合同价款进行资金拨付。"},{"i":92,"n":"第九十二条","txt":"对于采取受援方自建模式的项目，符合以下情形之一的，项目管理机构可以不委派项目管理企业，采取资金审计、巡回检查等其他非派驻方式进行有限监管： （一）因安全因素无法派遣项目管理企业赴受援国的； （二）派遣项目管理企业费用占项目总成本过大的。"},{"i":93,"n":"第九十三条","txt":"项目管理机构应按本办法组织实施项目，规范向商务部备案和报批的程序；建立健全信息报告制度，按月向商务部报送项目执行情况；针对项目执行过程中出现的重大质量、进度、安全生产和投资控制问题，及时向商务部专题报告。 商务部对项目管理机构组织实施项目进行监督检查。"},{"i":94,"n":"第九十四条","txt":"项目管理机构应按本办法建立项目技术性监督审查制度，依法组织稳定的独立专家队伍对项目管理企业和工程总承包企业阶段性报送的成果文件进行全过程的专项技术监督，监督重点包括安全性、投资匹配性和立项意图一致性等，及时发现存在的重大技术、安全和投资失控问题，出具监督审查意见，并采取措施监督相关责任企业及时纠正。"},{"i":95,"n":"第九十五条","txt":"项目管理机构建立重大项目巡视检查制度，现场监督检查项目管理企业和工程总承包企业落实项目各项管理制度和合同约定的情况。"},{"i":96,"n":"第九十六条","txt":"项目管理机构依据合同对管理企业和工程总承包企业境内境外资金进行监督管理，确保援外资金专款专用，单独核算，不挪作他用。"},{"i":97,"n":"第九十七条","txt":"项目管理机构应建立健全项目的技术争议处理机制，通过组建项目咨询专家委员会，规范专家委员会咨询、议事和仲裁规程，对项目实施过程中项目管理企业和工程总承包企业之间出现的合同争议、技术争议和重大质量安全争议进行第三方评审和仲裁，切实提高项目技术管理的质量和效率。"},{"i":98,"n":"第九十八条","txt":"项目发生质量安全事故，造成人员伤亡和财产损失的，项目管理机构应统一指挥项目管理企业和工程总承包企业进行事故应急救援和现场处置，防止事故扩大，保护事故现场，进行初步调查取证，并及时向商务部报告。 项目质量安全事故按一般、重大、特大和特别重大四个等级进行处理。 发生一般质量安全事故的，项目管理机构应在事故发生后三个自然日内报告商务部。项目管理机构负责事故处理，并在三十个工作日内作出处理决定。 发生重大或特大质量安全事故的，项目管理机构应在事故发生后二十四小时内向商务部报告。商务部负责组织事故调查处理，并在六十日内作出处理决定。遇有特殊情况，可适当延长处理期限。 发生特别重大质量安全事故的，项目管理机构应在事故发生后二十四小时内向商务部报告。商务部应在接到事故报告后十二小时内报告国务院，并根据国务院决定会同国务院有关主管部门组成事故调查组进行调查处理，在九十日内完成事故调查并向国务院提交事故"},{"i":99,"n":"第九十九条","txt":"成套项目实施企业有以下行为之一的，除按合同规定承担赔偿责任外，商务部给予行政警告，可以并处三万元人民币以下罚款，并可以依法公布处罚决定；违反相关法律、行政法规规定的，依法给予行政处罚；构成犯罪的，依法追究刑事责任： （一）违反本办法规定，将所承担的实施任务转包或违法分包的； （二）违反安全生产规定，造成重大安全生产事故的； （三）造成项目质量事故或形成项目质量隐患，商务部责令限期改正，逾期未改正的； （四）导致项目投资失控并造成国家财政资金损失的； （五）在设计文件中指定或变相指定产品的； （六）越权批准设计变更导致项目建设偏离中方和受援方商定的立项内容的； （七）未按照合同履行义务或延迟履行义务，影响项目正常实施，造成严重不良影响的； （八）擅自变更相关人员的，商务部责令限期改正，逾期未改正的； （九）未依法管理人员造成严重不良影响的； （十）违反本办法规定挪用援外项目资金的。 项目"},{"i":100,"n":"第一百条","txt":"成套项目实施企业在参与项目采购过程中，有下列情形之一的，商务部给予警告，可以并处三万元人民币以下罚款；违反相关法律、行政法规规定的，依法给予行政处罚；构成犯罪的，依法追究刑事责任： （一）弄虚作假，获取不正当竞争优势的； （二）与其他参与采购单位串通，谋取非法利益的； （三）与采购代理机构恶意串通，或向采购代理机构、评审专家行贿或提供其他不正当利益的； （四）在采购承诺有效期内实质性变更承诺的。"},{"i":101,"n":"第一百零一条","txt":"成套项目实施企业主要负责人或项目负责人及直接责任人未履行法律法规和本办法规定的，商务部责令限期改正；逾期未改正，或造成重大安全事故或重大质量事故等严重后果的，商务部给予警告，可以并处三万元人民币以下罚款；违反相关法律、行政法规规定的，依法给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":102,"n":"第一百零二条","txt":"国家机关和项目管理机构工作人员在项目管理过程中有下列行为之一，视情节轻重给予相应的行政处分；构成犯罪的，依法追究刑事责任： （一）利用职务便利索取他人财物，或非法收受他人财物为他人谋取利益的； （二）滥用职权、玩忽职守或徇私舞弊，致使国家利益遭受损失的； （三）泄露国家秘密的。"},{"i":103,"n":"第一百零三条","txt":"对优惠贷款项下的援外项目、因严重自然灾害或其他不可抗力事件所实施的紧急援助项目以及涉及国家安全和秘密的成套项目，另有规定的，从其规定。"},{"i":104,"n":"第一百零四条","txt":"本办法所称的“以上”和“以下”包含本数。"},{"i":105,"n":"第一百零五条","txt":"本办法所涉及的术语解释见附件。"},{"i":106,"n":"第一百零六条","txt":"本办法由商务部负责解释。"},{"i":107,"n":"第一百零七条","txt":"本办法自2016年1月8日起施行。施行之日起，《对外援助成套项目管理办法（试行）》（商务部令2008年第18号）、《对外援助成套项目安全生产管理办法（试行）》(商务部令2006年第15号）同时废止。 附件： 风险准备金系数取值参考表 成套项目费用构成及取费参考表"}],"duiwaiyuanzhuwuzixiangmuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对外援助物资项目的管理，保证项目质量，提高援助效果，依据有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称物资项目，是指中方在援外资金项下，向受援方提供一般生产生活物资、技术性产品或单项设备，并承担必要配套技术服务的援助项目。"},{"i":3,"n":"第三条","txt":"物资项目一般由中方负责组织实施，实行企业承包责任制。 物资项目总承包企业及相关人员应遵守中国和受援方法律法规，尊重受援方风俗习惯，根据本办法规定和合同实施物资项目，并承担相应的法律责任。 由于受援方对援助物资有特别需求，须在受援方当地采购的物资项目，经中方与受援方商定，可以采用中方代理采购方式组织实施。"},{"i":4,"n":"第四条","txt":"商务部负责物资项目的立项、管理和监督。 援外项目管理机构依据本办法规定具体组织、管理和监督物资项目的实施，并接受商务部的监督检查。"},{"i":5,"n":"第五条","txt":"驻受援国使领馆经济商务机构协助商务部办理与物资援助有关的政府间事务，负责物资项目实施的境外监督管理。"},{"i":6,"n":"第六条","txt":"各省级商务主管部门协助商务部处理物资项目援助管理事务。"},{"i":7,"n":"第七条","txt":"除涉及两用物项和技术出口管制的管理外，对外援助物资出口不纳入配额和许可证管理。"},{"i":8,"n":"第八条","txt":"商务部制定并发布《对外援助物资供货指导目录》（以下简称《指导目录》），明确中国政府对外提供援助物资的原则和导向。 《指导目录》用于指导物资项目可行性研究（含拟供货物清单编制）和立项工作。列入《指导目录》的援助物资应为本国货物，满足可标准化、技术成熟、质量优良、合理适用、绿色环保、售后服务可保障等要求，符合有关产品出口的法律法规和中国缔结或参加的国际条约、协定，并通过法定的强制性产品认证。 对于受援方提出《指导目录》以外的援助物资，应在可行性研究中增加对该项物资的专题政策评估和技术评价。"},{"i":9,"n":"第九条","txt":"《指导目录》的编制应本着“科学合理、客观准确、政策引导、动态管理”的原则，重点规范产品的品名、海关HS编码、产品描述、技术要求和产品标准。"},{"i":10,"n":"第十条","txt":"商务部对《指导目录》实行动态管理，根据对外援助需要及援助效果、技术标准变化等情况，每四年进行一次全面修订；并对《指导目录》内产品的产品描述、技术要求和标准等内容进行随时更新。"},{"i":11,"n":"第十一条","txt":"项目管理机构根据援外项目采购规定，在经商务部资格认定的援外项目实施企业范围内选定总承包企业。 商务部可根据国家区域发展政策选定对外援助物资项目实施企业。"},{"i":12,"n":"第十二条","txt":"商务部在可行性研究阶段确定项目的投资估算和投资限额。 商务部制定项目的费用构成及取费参考标准，供编制项目估算和报价时参考使用。"},{"i":13,"n":"第十三条","txt":"物资项目项下某一项或若干项物资经立项确定由唯一供货企业提供，项目管理机构根据援外项目采购规定，提前与唯一供货企业议定采购价格和条件，列入项目招标文件，并监督唯一供货企业向所有竞标单位落实议定采购价格和条件。 中标的总承包企业应按招标文件列明的议定采购价格和条件与唯一供货企业签订内部供货合同。"},{"i":14,"n":"第十四条","txt":"项目管理机构代表商务部向中标的总承包企业下达物资项目实施任务通知函。 物资项目实施任务通知函是总承包企业办理援外物资采购、仓储、检验、通关、运输和相关人员出入境手续的依据。"},{"i":15,"n":"第十五条","txt":"中标的总承包企业不得将承包责任范围内的任务转包或违法分包。 项目涉及的部分物资采购、配套工程建设、设备安装或其他技术服务任务有特殊经营许可或专业技术资质要求，而拟投标的总承包企业自身资质不能覆盖的，可以分包给其他专业单位合作承担，其分包内容、分包单位选定和分包金额应在投标文件中载明。 分包方式一旦确定，不得变更。中标的总承包企业应按投标文件中载明的分包方式签订分包合同并报项目管理机构备案。因特殊原因确需变更或新增分包单位的，应按变更合同程序办理。"},{"i":16,"n":"第十六条","txt":"商务部审批物资项目的可行性研究报告和立项建议书，与受援方确认项目供货清单（包括品种、数量和主要技术参数等），并办理立项。 立项后，项目管理机构在政府间立项协议以及商务部批准的可行性研究报告和立项建议书范围内，按照确认的供货清单组织项目实施和管理。"},{"i":17,"n":"第十七条","txt":"物资项目政府间协议要求签订对外实施协议的，项目管理机构应与受援方指定机构签订项目对外实施协议。 对外实施协议应规定中、外双方的合作方式、管理程序和实施全过程的权利、义务。"},{"i":18,"n":"第十八条","txt":"项目管理机构根据采购结果与总承包企业签订内部总承包合同，明确项目组织实施的具体事宜和双方权利义务。 总承包企业根据本办法规定和合同约定负责组织所供物资的生产采购、仓储包装、检验检疫和运输，按期完成物资交付，并提供相应的配套技术服务。"},{"i":19,"n":"第十九条","txt":"总承包企业应当与物资生产企业或供货企业签订供货合同，不得在签订供货合同时擅自改变采购承诺。 总承包企业建立并执行产品收货前检查验收制度，验明产品合格证明和其他标识，确保援外物资质量。"},{"i":20,"n":"第二十条","txt":"总承包企业按照合同约定办理物资的仓储和包装,采取合理措施保证项目下产品的质量及安全。"},{"i":21,"n":"第二十一条","txt":"总承包企业按合同约定办理物资运抵指定交付地点的全程运输，并支付所有运费。总承包企业应妥善保管提单、保险单、装箱单等单证，并在物资启运后及时将有关情况通知受援方指定收货人、驻受援国使领馆经商机构和项目管理机构。 因不可抗力或外方需求变化等原因，确需变更运输方案的，总承包企业应事先报商务部同意。"},{"i":22,"n":"第二十二条","txt":"总承包企业按合同约定办理货物运输保险及其他必要的保险。属于保险责任范围内的损失，总承包企业应向保险公司索赔；未按规定办理保险的，总承包企业承担有关损失。"},{"i":23,"n":"第二十三条","txt":"总承包企业将所供物资运抵指定交付地点后，应及时与受援方办理物资交付手续，确认物资交付的数量和实际运抵时间等。"},{"i":24,"n":"第二十四条","txt":"总承包企业按合同约定组织实施项目配套技术服务任务，包括选派技术服务人员赴受援方当地组织开展安装、调试、技术指导和人员培训以及接待受援方技术人员来华实习培训等。 总承包企业应保证实施技术服务所需的物质条件和技术条件，确保技术服务质量。"},{"i":25,"n":"第二十五条","txt":"总承包企业定期向项目管理机构、驻受援国使领馆经商机构报送工作简报，内容包括项目执行进展、遇到有关问题及解决措施、下阶段工作计划和实施方案等。遇有重大质量安全问题和可能影响项目实施的突发事件应及时专题报告。 项目实施完毕后，总承包企业应向项目管理机构书面提交项目总结报告，内容包括项目总体实施情况、取得的援助效果及受援方总体评价、项目执行过程中遇到的问题或突发事件情况及采取的应对措施等。"},{"i":26,"n":"第二十六条","txt":"在项目实施过程中，总承包企业应及时整理、妥善保存项目资料。在物资对外移交一个月内，向项目管理机构提交项目相关文件资料。"},{"i":27,"n":"第二十七条","txt":"物资项目项下所供物资交付受援方并完成政府间立项协议及对外实施协议规定的中方义务后，项目管理机构代表商务部及时与受援方办理政府间移交手续。 其中，需要提供后续技术服务的项目，可在所供物资交付受援方并完成所需安装调试及操作培训等主要技术服务工作后，办理政府间移交手续。 项目完成政府间移交手续后，项目管理机构应及时向商务部提交项目完成报告。"},{"i":28,"n":"第二十八条","txt":"商务部一般在立项阶段根据合理进度规划确定项目实施期限。 受援方对缩短项目实施期限有特殊要求的，商务部将特殊期限及由此产生的配套措施（如改变运输方式）和额外投资一并纳入立项范围与受援方商定。"},{"i":29,"n":"第二十九条","txt":"项目实施期限一经确定，不得随意变动。 由于本办法规定的业主责任、政治外交风险和不抗力风险等非企业责任原因，且相关总承包企业已主动采取必要措施应对不利情况，仍导致项目的实施期限不能实现约定进度的，项目管理机构可与总承包企业调整合同进度。 总承包企业应提出合同进度调整方案报项目管理机构，经项目管理机构与实施企业协商一致后，通过合同调整程序签订补充合同规定。 合同进度调整超出项目对外实施协议规定期限的，项目管理机构应与受援方签订补充对外实施协议。"},{"i":30,"n":"第三十条","txt":"总承包企业承担项目的质量责任，保证所供物资符合合同约定和采购承诺的质量标准，不得擅自变更物资品名、品牌、规格型号、技术参数、供货数量、生产厂商和包装方式等实质性内容。 项目管理机构负责对总承包企业的质量责任的落实进行监督管理。"},{"i":31,"n":"第三十一条","txt":"总承包企业应对其承包责任范围内所供物资在合理使用期限内承担无缺陷质量保证责任。 无缺陷质量保证期由商务部根据项目可行性研究结果在立项阶段分产品设定，并由项目管理机构根据立项要求和采购结果，在项目内部承包合同中与总承包企业明确约定。 无缺陷质量保证期自总承包企业将所供物资运抵合同指定交付地点之日起算。 在无缺陷质量保证期内，非因受援方使用或保管不当产生的产品质量问题，总承包企业应及时修复、更换和赔偿，并承担由此产生的全部费用。 总承包企业应向项目管理机构提交无缺陷质量保证金保函，并承担保函费用。保函金额不低于所保证产品货值的10%，保函期限应按产品质量保证的最长期限设定，但不超过五年。"},{"i":32,"n":"第三十二条","txt":"对于项目项下有长期维护和维修服务要求的大型机电设备等产品，总承包企业应在立项阶段确定的合理期限内确保受援方在当地得到及时、有效的维护和维修服务。对于超过产品质量保证期，且未列入中方技术服务范围的维护和维修服务费用，由受援方按商业化原则承担。 总承包企业对所供大型机电设备提供长期维护和维修服务的具体方式包括总承包企业或供货企业在受援方当地设立服务网点，或长期授权受援方当地合作机构，或第三国技术服务网络覆盖受援方等。 项目管理机构应监督总承包企业编制并向受援方提交所供大型机电设备的维修保养手册，详细说明所供大型机电设备的维护保养期限、维护保养条件和费用承担、正常使用操作指南、异常情况处理以及提供维护保养服务的当地厂商信息及联系方式等。维修保养手册须用中、外文对应编制，确保内容完整、准确。 总承包企业应定期跟踪受援方对大型机电设备的使用情况和评价，并向商务部及项目管理机构及时反馈。"},{"i":33,"n":"第三十三条","txt":"本办法所称监造，是指承担监造任务的单位根据总承包合同或供货合同规定的货物质量标准，以及国家有关法律法规和技术标准，对设备在制造和生产过程中的工艺流程、制造质量和设备制造单位质量体系的运行进行监督。"},{"i":34,"n":"第三十四条","txt":"对于进行非标设计或有特殊建造需求的技术复杂或专业性强的重大设备等物资，项目管理机构应根据商务部下达的物资项目管理通知要求组织实施监造。"},{"i":35,"n":"第三十五条","txt":"项目监造原则上采用独立第三方监造的方式，监造单位由项目管理机构根据援外项目采购规定选定。"},{"i":36,"n":"第三十六条","txt":"项目管理机构依据采购结果，与监造单位签订委托监造合同，明确双方权利义务及相应的责任。"},{"i":37,"n":"第三十七条","txt":"监造单位应根据本办法及国家有关法律规定，选派监造代表组驻厂监造，严格履行监造职责，并对被监造设备的制造质量承担法律责任。"},{"i":38,"n":"第三十八条","txt":"监造代表组应编写监造工作实施细则，对设备制造、装配和整体试验过程进行监督和抽查，定期向项目管理机构提供监造工作简报，并在监造工作结束后提交总结报告。"},{"i":39,"n":"第三十九条","txt":"总承包企业和相关设备生产企业应积极配合监造代表组的工作，提供监造所需标准、图纸及检验记录等资料并提供工作便利。"},{"i":40,"n":"第四十条","txt":"商务部按照市场化原则建立项目风险承担机制，明确界定项目涉及的风险因素，规范风险承担主体责任。"},{"i":41,"n":"第四十一条","txt":"项目涉及的风险因素主要包括政治外交风险、业主责任风险、不可抗力风险和经营性风险。 政治外交风险是指政治外交变动或政策性调整对项目实施造成的影响，主要包括：国与国战争和涉核战争；中国与受援国外交关系变化；受援国合法当局没收、征用；与项目实施相关的法律、法规变动或政策调整等，风险责任由商务部承担。 业主责任风险是指由于商务部的责任或经商务部同意承担受援方责任对项目实施造成的影响，风险责任由商务部承担。 不可抗力风险是指不可预见、不可克服、不可避免的客观情况对项目造成的影响，主要包括：自然灾害；意外事故；受援国国内战乱、罢工、暴乱、民众骚乱等突发情况，风险责任由项目实施单位和商务部分担。 经营性风险是指因市场变动或总承包企业自身经营管理责任对项目造成的影响，包括投标报价以外的物价和汇率波动等经营性意外，由总承包企业承担。"},{"i":42,"n":"第四十二条","txt":"商务部通过合同补款方式对项目实施过程中发生的政治外交风险和业主责任风险承担责任。 商务部通过合同约定的货物运输保险及其他必要的保险，合理分担总承包企业的不可抗力风险。超出合同约定保险以外的不可抗力风险由总承包企业承担。"},{"i":43,"n":"第四十三条","txt":"受援方提出的援助物资需求符合中方代理采购的实施条件，经中方与受援方商定采用中方代理采购方式的，有关实施方式应在中外双方签订的立项协议（或其他政府间文件）中明确。"},{"i":44,"n":"第四十四条","txt":"采取中方代理采购方式的项目，由受援方从中方推荐企业范围内依据其法律法规规定的程序选定代理企业。 项目管理机构负责与受援方商定推荐中方代理企业的范围和条件。项目管理机构在征求驻受援国使馆经商机构意见后，在受援方当地依法注册或设有分支机构的中资企业范围内，根据企业资质、项目实施能力及诚信表现等条件确定向受援方推荐的中资企业名单。 有关经商机构监督中方代理企业与受援方签订委托代理合同，明确双方权利义务。"},{"i":45,"n":"第四十五条","txt":"中方代理采购的项目，由受援方选定产品，明确品牌、规格型号，与供货商议定或在中方代理企业协助下与供货商议定供货价格和供货条件。 中方代理企业应将受援方确定的物资清单及与供货商议定的供货价格和供货条件等报有关经商机构复核确认。"},{"i":46,"n":"第四十六条","txt":"项目管理机构负责与中方代理企业签订内部合同，明确双方权利义务和项目价款结算。"},{"i":47,"n":"第四十七条","txt":"中方代理企业按照与受援方签订的委托代理合同，按与供货商议定的价格和供货条件等负责采购受援方指定产品，并办理受援方委托的国内运输、仓储等相关事宜。 中方代理企业完成项目有关任务后，应将拨款申请和各项费用有关单据送经商机构审核后报送项目管理机构，由项目管理机构按照有关规定进行资金拨付和结算申请复核。"},{"i":48,"n":"第四十八条","txt":"中方代理采购相关产品的质量责任及售后服务应列入供货条件，由受援方与供货商落实。"},{"i":49,"n":"第四十九条","txt":"商务部负责对项目组织实施工作进行监督管理，建立项目实施企业诚信评价体系，引导企业诚实守信经营。 商务部根据需要会同有关部门对项目执行情况进行审计。"},{"i":50,"n":"第五十条","txt":"项目管理机构依据实施合同对总承包企业履行合同义务情况进行监督管理，并定期向商务部报告项目执行情况。 项目管理机构采取检查等有效方式对项目实施进行事中和事后监管，确保监管效果。"},{"i":51,"n":"第五十一条","txt":"项目有关资金应专款专用，单独核算，任何单位和个人不得将援外资金挪作他用。"},{"i":52,"n":"第五十二条","txt":"对于项目项下需从中国境内采购、发运的物资，商务部会同有关部门共同建立援外出口物资的检验监管和口岸验放制度。 在中国关税境外采购、发运的援外物资实行采购地检验和验放制度。"},{"i":53,"n":"第五十三条","txt":"商务部建立援外项目评估制度，对项目的实施情况和实施效果进行全过程评估。"},{"i":54,"n":"第五十四条","txt":"项目可行性研究单位及可行性研究评估单位有下列行为之一的，除按合同规定承担赔偿责任外，商务部给予警告，可以并处以三万元人民币以下罚款： （一）提供的可行性研究意见、拟供货物清单存在重大失误或质量低劣，对项目实施造成严重影响； （二）与总承包企业或供货企业串通、在采购文件发布前泄露拟供货清单内容或擅自指定或变相指定唯一供货产品。"},{"i":55,"n":"第五十五条","txt":"总承包企业在参与项目采购过程中，有下列情形之一的，商务部给予警告，可以并处三万元人民币以下罚款；违反相关法律、行政法规规定的，依法给予行政处罚；构成犯罪的，依法追究刑事责任： （一）弄虚作假，获取不正当竞争优势的； （二）与其他参与采购单位串通，谋取非法利益的； （三）与采购代理机构恶意串通，或向采购代理机构、评审专家行贿或提供其他不正当利益的； （四）在采购承诺有效期内实质性变更承诺的。"},{"i":56,"n":"第五十六条","txt":"总承包企业在项目实施过程中有下列行为之一的，除按合同规定承担赔偿责任外，商务部给予警告，可以并处以三万元人民币以下的罚款。违反相关法律、行政法规规定的，依法给予行政处罚；构成犯罪的，依法追究刑事责任： （一）未履行合同义务或承诺，严重影响项目的正常实施的； （二）违反本办法规定，将所承担的项目任务转包或违法分包的； （三）违反本办法规定，挪用援外项目资金的； （四）因货物或技术服务质量问题对外造成严重不良影响的； （五）其他违反本办法规定，造成重大损失或严重不良影响的。"},{"i":57,"n":"第五十七条","txt":"总承包企业主要负责人、项目负责人及直接责任人未履行法律法规和对外援助管理有关规定，造成严重后果的，商务部给予警告，可以并处以三万元人民币以下罚款；违反相关法律、行政法规规定的，依法给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":58,"n":"第五十八条","txt":"商务部和项目管理机构工作人员在项目管理和组织实施过程中有下列行为之一，视情节轻重给予相应的行政处分；构成犯罪的，依法追究刑事责任： （一）利用职务便利索取他人财物，或非法收受他人财物为他人谋取利益的； （二）滥用职权、玩忽职守或徇私舞弊，致使国家利益遭受损失的； （三）泄露国家秘密的。"},{"i":59,"n":"第五十九条","txt":"对优惠贷款项下的援外项目、因严重自然灾害或其他不可抗力事件所实施的紧急援助项目以及涉及国家安全和秘密的物资项目，另有规定的，从其规定。"},{"i":60,"n":"第六十条","txt":"本办法所称“以下”包含本数。"},{"i":61,"n":"第六十一条","txt":"本办法由商务部负责解释。"},{"i":62,"n":"第六十二条","txt":"本办法自2016年1月8日起施行。施行之日起，《对外援助物资项目管理办法》（商务部令2011年第1号）同时废止。"}],"duiwaiyuanzhuxiangmushishiqiyezigerendingbanfa":[{"i":1,"n":"第一条","txt":"为规范对外援助项目实施企业（以下简称援外项目实施企业）的资格认定，依据《行政许可法》和《国务院对确需保留的行政审批项目设定行政许可的决定》（国务院令2004年第412号），制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称援外项目实施企业是指经资格认定，可承担中国政府对外援助项目实施任务的企业和其他组织。 前款所称的援外项目实施企业包括： （一）对外援助成套项目（以下简称成套项目）总承包企业和项目管理企业； （二）对外援助物资项目（以下简称物资项目）总承包企业； （三）对外技术援助项目（以下简称技术援助项目）实施单位； （四）对外人力资源开发合作项目（以下简称人力资源项目）实施单位； （五）对外援助项目咨询服务单位。"},{"i":3,"n":"第三条","txt":"商务部负责援外项目实施企业的资格认定和资格管理。 省、自治区、直辖市及新疆生产建设兵团商务主管部门（以下统称省级商务主管部门）协助商务部进行援外项目实施企业资格认定。 援外项目管理机构协助商务部对援外项目实施企业进行资格管理。"},{"i":4,"n":"第四条","txt":"商务部根据援外项目实施企业的不同类别，分别采用资格审查或资格招标方式进行援外项目实施企业资格认定。 经资格认定的援外项目实施企业可在相应的资格类别范围内承担援外项目具体实施任务。"},{"i":5,"n":"第五条","txt":"援外项目实施企业应具备以下基本资格条件： （一）系依照中国法律在中国境内设立的法人； （二）所有出资人均为中国投资者； （三）前三个会计年度未出现亏损； （四）前三年未受过刑事处罚、未因进行非法经营活动或违反有关援外管理规章受过行政处罚； （五）依法纳税和缴纳社会保险费。"},{"i":6,"n":"第六条","txt":"商务部通过资格审查方式认定成套项目总承包企业资格。 申请成套项目总承包企业资格的，除具备第五条规定的基本资格条件外，还应具备以下条件： （一）具备特级施工总承包资质；或具备一级施工总承包或相应等级的技术资质，申请前三年均列入商务部统计对外承包工程营业额前一百强； （二）通过质量管理体系、环境管理体系、职业健康安全管理体系认证且认证资格有效； （三）具有良好的金融资信条件； （四）具有良好的经营诚信表现。"},{"i":7,"n":"第七条","txt":"商务部通过资格招标方式认定成套项目管理企业资格。 参与成套项目管理企业资格招标的，除具备第五条规定的基本资格条件外，还应具备以下条件： （一）具备国务院建设主管部门颁发的可从事项目管理服务的工程设计甲级资质，或国务院发展改革主管部门颁发的工程项目管理（全过程管理或全过程策划和准备阶段管理类别）甲级资格； （二）具备国务院建设主管部门颁发的工程监理甲级资质，或与具备工程监理甲级资质法人单位签订长期合作协议； （三）具备在境外开展相关业务的业绩； （四）具有工程项目的项目管理经验。"},{"i":8,"n":"第八条","txt":"商务部通过资格审查方式认定物资项目总承包企业资格。 申请物资项目总承包企业资格的，除具备第五条规定的基本资格条件外，还应具备以下条件： （一）系符合《对外贸易法》规定的对外贸易经营者； （二）具有良好的金融资信条件； （三）申请前三年在受援国有进出口业绩； （四）具有良好的经营诚信表现。"},{"i":9,"n":"第九条","txt":"商务部通过资格招标方式认定技术援助项目实施单位资格。 参与技术援助项目实施单位资格招标的，除具备第五条规定的基本资格条件外，还应具备以下条件： （一）具备相关专业的技术能力； （二）具备在境外开展相关业务的业绩; （三）具备相关项目的实施经验。"},{"i":10,"n":"第十条","txt":"商务部通过资格招标方式认定人力资源项目实施单位资格。 参与人力资源项目实施单位资格招标的，除具备第五条规定的基本资格条件外，还应具备以下条件： （一）具备丰富的对外培训经验和较强的外事接待能力； （二）具备开展培训所需的师资力量、培训场所和其他软硬件； （三）在相关行业、专业或领域内，具有较高的科研能力和影响力。"},{"i":11,"n":"第十一条","txt":"商务部通过资格招标方式认定咨询服务单位资格。 参与咨询服务单位资格招标的，除具备第五条规定的基本资格条件外，还应具备以下条件： （一）具备国务院有关行政主管部门核准的咨询资质或其他技术资质； （二）具备开展境外项目咨询服务的相关业绩； （三）具备项目咨询服务经验。"},{"i":12,"n":"第十二条","txt":"采取资格审查方式认定资格的，申请人应提交以下文件： （一）申请书； （二）企业法人营业执照和法定代表人身份证明文件； （三）出资人身份证明文件； （四）企业出资情况的说明并承诺属实； （五）前三个年度企业会计报表； （六）本企业关于前三年未受过刑事处罚、未因进行非法经营活动或违反有关援外管理规章受过行政处罚的声明； （七）税务机关出具的前三年完税证明； （八）社会保险经办机构出具的前三年缴费证明。 除上述文件外，申请成套项目总承包企业资格还须提交技术资质证书、质量管理体系认证证书、环境管理体系认证证书、职业健康安全管理体系认证证书和具有良好的经营诚信表现说明；申请物资项目总承包企业资格还须提交海关统计信息部门出具的货物进出口业绩证明和具有良好的经营诚信表现说明及证明。"},{"i":13,"n":"第十三条","txt":"中央企业和其他在国务院工商行政主管部门登记的企业直接向商务部提交申请，其他企业向所在地省级商务主管部门提交申请。"},{"i":14,"n":"第十四条","txt":"企业向省级商务主管部门申请的，省级商务主管部门应当在收到企业提交的申请文件之日起五个工作日内完成初核，将企业申请文件连同初核意见一并报商务部审核。"},{"i":15,"n":"第十五条","txt":"商务部应在收到企业提交的完备申请文件之日起二十个工作日内或收到省级商务主管部门初核意见之日起十五个工作日内完成审核，作出许可与否的决定。 准予许可的，商务部颁发有效期为三年的许可文件；不予许可的，商务部应当说明理由，并告知企业享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":16,"n":"第十六条","txt":"商务部应公布经资格审查取得资格的企业名单。"},{"i":17,"n":"第十七条","txt":"取得资格的企业需要延续资格许可有效期的,应当在有效期届满六十日前按第十二条和第十三条向商务部或所在地省级商务主管部门提出申请。 省级商务主管部门和商务部按照第十四条和第十五条规定的期限对申请进行初核或审核，商务部在许可有效期届满前作出是否准予延期的决定。 准予延期的，商务部颁发准予延期三年的许可文件；不予延期的，商务部应当说明理由，并告知企业享有依法申请行政复议或者提起行政诉讼的权利。"},{"i":18,"n":"第十八条","txt":"采用资格招标方式认定资格的，商务部自本办法施行之日起每三年组织一次公开资格招标。 商务部依法委托招标代理机构组织招标。"},{"i":19,"n":"第十九条","txt":"商务部应在组织资格招标前一个月发布招标公告，招标公告主要包括以下内容： （一）招标代理机构的名称、地址和联系方式； （二）援外项目实施企业资格招标的类别和数量； （三）申请参与资格招标单位的资格要求； （四）获取招标文件的时间、地点、方式； （五）投标截止时间。"},{"i":20,"n":"第二十条","txt":"招标文件开始发出之日起至投标单位提交投标文件截止之日止，应不少于二十日。"},{"i":21,"n":"第二十一条","txt":"商务部对已发出的招标文件进行必要的澄清或修改的，应当在提交投标文件截止时间至少十五日前，以书面形式作出通知。该澄清或修改的内容为招标文件的组成部分。"},{"i":22,"n":"第二十二条","txt":"申请参与资格招标的单位对招标文件有异议的，应当在投标截止时间十日前提出。商务部应当自收到异议之日起三日内作出答复；作出答复前，应当暂停招标投标活动。"},{"i":23,"n":"第二十三条","txt":"申请参与资格招标的单位应按照招标文件要求编制投标文件，并在招标文件规定的截止时间前，将投标文件经单位法定代表人或其授权代表签字、加盖公章并密封后，送达指定地点。 逾期送达的、未送达至指定地点的或未按招标文件要求密封的投标文件无效，招标代理机构应当拒收。"},{"i":24,"n":"第二十四条","txt":"商务部依法组建评标委员会。评标委员会应当按照招标文件规定的评标标准和方法，对投标文件进行评审。 评标委员会由商务部的代表和有关技术、经济等方面的专家组成，成员人数为五人以上单数，其中技术、经济等方面的专家不得少于成员总数的三分之二。"},{"i":25,"n":"第二十五条","txt":"属下列情况之一的，评标委员会应当否决其投标： （一）未按招标文件规定加盖公章的； （二）未经单位法定代表人或其授权代表签字确认的； （三）投标函与招标文件规定格式严重不符的； （四）申请参与资格招标的单位不具备招标文件规定资格要求的。"},{"i":26,"n":"第二十六条","txt":"评标委员会应自评标结束之日起两日内将评标报告提交商务部，评标报告主要包括评标结果和中标候选单位排序。"},{"i":27,"n":"第二十七条","txt":"商务部自收到评标报告之日起五日内在评标报告推荐的中标候选单位中确定中标单位。"},{"i":28,"n":"第二十八条","txt":"在正式授标前，商务部将中标单位名单公示五日，公示期满后公布通过资格招标的单位名单。"},{"i":29,"n":"第二十九条","txt":"通过资格招标的，取得相应类别的援外项目实施企业资格，商务部颁发有效期为三年的许可文件。"},{"i":30,"n":"第三十条","txt":"通过资格招标方式认定资格的援外项目实施企业，由于受到行政处罚或第三十四条规定等原因不能承担援外项目实施任务，且数量超出原定资格招标数量百分之三十的，商务部应及时组织补充资格招标，按原定资格招标数量补足援外项目实施企业。"},{"i":31,"n":"第三十一条","txt":"援外项目实施企业发生企业名称、企业类型、法定代表人、注册资本和出资人变更的，应在变更之日起一个月内向商务部备案，提供以下文件： （一）变更申请表； （二）工商行政管理机构出具的变更登记证明文件； （三）变更后的相关证明文件。"},{"i":32,"n":"第三十二条","txt":"援外项目实施企业发生改制、分立或合并情形的，改制、分立或合并后新成立的企业应按照本办法规定重新申请资格认定。原企业注销的，改制、合并或分立后的企业可继承原企业的援外业绩。"},{"i":33,"n":"第三十三条","txt":"商务部建立援外项目实施企业诚信评价体系，根据企业遵守援外管理规章和履行项目实施合同情况将企业诚信状况分为良好、合格和不合格三个等级。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，商务部可依据职权或根据利害关系人的请求，撤销援外项目实施企业资格： （一）行政机关工作人员滥用职权、玩忽职守作出援外项目实施企业资格许可决定的； （二）违反法定程序作出援外项目实施企业资格许可决定的； （三）对不具备申请资格或不符合法定条件的申请人准予援外项目实施企业资格许可的。 企业以欺骗、贿赂等不正当手段获得援外项目实施企业资格的，商务部应撤销其资格。"},{"i":35,"n":"第三十五条","txt":"援外项目实施企业因有效期届满而丧失实施资格，不影响已中标项目的履行。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一的，商务部给予警告，可以并处三万元人民币以下罚款；违反相关法律、行政法规规定的，依照相关法律、行政法规的规定给予行政处罚；构成犯罪的，依法追究刑事责任： （一）企业以欺骗、贿赂等不正当手段获得援外项目实施企业资格的； （二）企业以出租、出借等方式非法转让援外项目实施企业资格的。"},{"i":37,"n":"第三十七条","txt":"商务部、省级商务主管部门和援外项目管理机构工作人员在援外项目实施企业资格管理过程中，违反有关法律法规和本办法规定的，视情节轻重给予相应处分；构成犯罪的，依法追究刑事责任。"},{"i":38,"n":"第三十八条","txt":"在采取资格招标方式认定资格的援外项目实施企业类别项下，部分技术类别、业务类别因行业特点或其他限制条件暂时不能组织资格招标的，该技术类别或业务类别援外项目实施企业的选定按照援外项目采购规定执行。"},{"i":39,"n":"第三十九条","txt":"有关第六条第二款第（三）项、第（四）项、第（五）项和第八条第二款第（二）项、第（四）项涉及的细化条件及第八条第二款第（三）项规定的受援国名单，商务部以公告方式另行公布。"},{"i":40,"n":"第四十条","txt":"本办法所称\"中国投资者\"不包括外商投资企业。"},{"i":41,"n":"第四十一条","txt":"本办法所称的\"中央企业\"是指国务院国有资产监督管理机构履行出资人职责的企业。"},{"i":42,"n":"第四十二条","txt":"本办法所称\"以上\"，包括本数。"},{"i":43,"n":"第四十三条","txt":"本办法由商务部负责解释。"},{"i":44,"n":"第四十四条","txt":"本办法自公布之日起施行。《对外援助成套项目施工任务实施企业资格认定办法（试行）》（商务部2004年第9号令）和《对外援助物资项目实施企业资格管理办法》（商务部2011年第2号令）同时废止。"}],"duiwaimaoyibileidiaochaguize":[{"i":1,"n":"第一条","txt":"为了开展和规范对外贸易壁垒调查工作，消除国外贸易壁垒对我国对外贸易的影响，促进对外贸易的正常发展，根据《中华人民共和国对外贸易法》，制定本规则。"},{"i":2,"n":"第二条","txt":"商务部负责对国外贸易壁垒的调查工作。 商务部指定进出口公平贸易局负责实施本规则。"},{"i":3,"n":"第三条","txt":"外国（地区）政府采取或者支持的措施或者做法，存在下列情形之一的，视为贸易壁垒： （一）违反该国（地区）与我国共同缔结或者共同参加的经济贸易条约或者协定，或者未能履行与我国共同缔结或者共同参加的经济贸易条约或者协定规定的义务； （二）造成下列负面贸易影响之一： 对我国产品或者服务进入该国（地区）市场或者第三国（地区）市场造成或者可能造成阻碍或者限制； 对我国产品或者服务在该国（地区）市场或者第三国（地区）市场的竞争力造成或者可能造成损害； 对该国（地区）或者第三国（地区）的产品或者服务向我国出口造成或者可能造成阻碍或者限制。"},{"i":4,"n":"第四条","txt":"商务部可以应申请人的申请立案，进行贸易壁垒调查。 商务部认为有必要的，可以自行立案，进行贸易壁垒调查。"},{"i":5,"n":"第五条","txt":"国内企业、国内产业或者代表国内企业、国内产业的自然人、法人或者其他组织（以下统称申请人），可以向商务部提出贸易壁垒调查的申请。 前款所称的“国内企业、国内产业”，是指与被诉贸易壁垒涉及的产品生产或者服务供应有直接关系的企业或者产业。"},{"i":6,"n":"第六条","txt":"贸易壁垒调查的申请必须以书面形式提交。"},{"i":7,"n":"第七条","txt":"申请书应当包括以下内容： （一）申请人的名称、地址及有关情况； （二）被申请调查的措施或者做法的说明； （三）被申请调查的措施或者做法所针对的产品或者服务的说明； （四）国内相关产业基本情况的说明； （五）被申请调查的措施或者做法造成负面贸易影响的，关于负面贸易影响的说明； （六）申请人认为需要说明的其他内容。"},{"i":8,"n":"第八条","txt":"申请书应当尽可能附具下列证据材料并说明其来源： （一）证明被申请调查的措施或者做法存在的证据材料； （二）证明被申请调查的措施或者做法造成的负面贸易影响的证据材料。 申请人无法提供上述证据材料的，应当以书面形式说明理由。"},{"i":9,"n":"第九条","txt":"申请人可以在商务部作出立案决定之前撤回申请。"},{"i":10,"n":"第十条","txt":"商务部应当自收到申请人提交的申请书及有关证据材料之日起60天内，对申请材料进行审查，作出立案或者不予立案的决定。"},{"i":11,"n":"第十一条","txt":"商务部在审查申请材料的过程中，可以要求申请人按照规定的时限提供补充材料。"},{"i":12,"n":"第十二条","txt":"如果申请人提交的申请材料符合本规则第六条和第七条的规定，并且不存在本规则第十六条第（一）、（三）和（四）项规定的情形，商务部应当决定立案调查并发布公告。 商务部决定自行立案的，也应当发布立案公告。"},{"i":13,"n":"第十三条","txt":"立案公告应当载明被调查的措施或者做法、被调查的措施或者做法涉及的产品或者服务以及实施被调查的措施或者做法的国家（地区）（以下简称“被调查国（地区）”）等内容，简要介绍已有的信息，并说明利害关系方陈述意见及公众提出评论的期限。"},{"i":14,"n":"第十四条","txt":"商务部应当在发布立案公告后，将立案决定通知申请人、已知的出口经营者和进口经营者、被调查国（地区）政府以及其他利害关系方。"},{"i":15,"n":"第十五条","txt":"立案公告发布之日为立案日期。"},{"i":16,"n":"第十六条","txt":"出现以下情形之一的，商务部可以作出不予立案的决定： （一）申请人提交的申请材料所描述的情况与事实明显不符； （二）申请人提交的申请材料不完整，并且未在商务部规定的时限内提供补充材料； （三）申请人申请调查的措施或者做法明显不属于本规则第三条所指的贸易壁垒； （四）商务部认为不应立案的其他情形。"},{"i":17,"n":"第十七条","txt":"商务部应当以书面形式将不予立案的决定通知申请人，并说明理由。"},{"i":18,"n":"第十八条","txt":"商务部应当通过调查认定被调查的措施或者做法是否构成本规则第三条所称的贸易壁垒。"},{"i":19,"n":"第十九条","txt":"在调查中，商务部可以使用主动收集的任何相关信息。"},{"i":20,"n":"第二十条","txt":"商务部认为必要时，可以成立由国务院有关部门、专家、学者组成的专家咨询组。专家咨询组负责对调查中涉及的技术性和法律性问题提供咨询意见。"},{"i":21,"n":"第二十一条","txt":"商务部可以采用问卷、听证会等方式向利害关系方了解情况，进行调查。"},{"i":22,"n":"第二十二条","txt":"商务部认为必要时，可以在征得被调查国（地区）政府同意后，派出工作人员赴该国（地区）进行调查取证。"},{"i":23,"n":"第二十三条","txt":"利害关系方认为其提供的资料泄露后将产生严重不利影响的，可以向商务部申请对该资料按照保密资料处理。"},{"i":24,"n":"第二十四条","txt":"商务部认为保密申请有正当理由的，应当对利害关系方提供的资料按照保密资料处理，同时要求利害关系方提供一份非保密的资料概要。 未经提供资料的利害关系方同意，商务部不得将按照保密资料处理的资料用于该贸易壁垒调查以外的用途。"},{"i":25,"n":"第二十五条","txt":"商务部在调查过程中，可以就被调查的措施或者做法与被调查国（地区）政府进行磋商。"},{"i":26,"n":"第二十六条","txt":"出现以下情形之一的，商务部可以决定中止调查并发布公告： （一）被调查国（地区）政府承诺在合理期限内取消或者调整被调查的措施或者做法； （二）被调查国（地区）政府承诺在合理期限内向我国提供适当的贸易补偿； （三）被调查国（地区）政府承诺履行经济贸易条约或者协定的义务； （四）商务部认为可以中止调查的其他情形。"},{"i":27,"n":"第二十七条","txt":"被调查国（地区）政府未在合理期限内履行本规则第二十六条第（一）至（三）项承诺的，商务部可以恢复调查；商务部根据本规则第二十六条第（四）项决定中止调查的，在该情形消除后，也可以恢复调查。"},{"i":28,"n":"第二十八条","txt":"应申请人的请求，商务部可以终止调查程序，除非认为终止调查程序不符合公共利益。"},{"i":29,"n":"第二十九条","txt":"出现以下情形之一的，商务部应当终止调查并发布公告： （一）被调查国（地区）政府已经取消或者调整被调查的措施或者做法； （二）被调查国（地区）政府已经向我国提供适当的贸易补偿； （三）被调查国（地区）政府已经履行经济贸易条约或者协定的义务。"},{"i":30,"n":"第三十条","txt":"出现下列情况之一的，商务部可以终止调查并发布公告： （一）申请人在调查中不提供必要的合作； （二）商务部认为可以终止调查的其他情形。"},{"i":31,"n":"第三十一条","txt":"通过调查，商务部应就被调查的措施或者做法是否构成本规则第三条所称的贸易壁垒作出决定，并发布公告。"},{"i":32,"n":"第三十二条","txt":"贸易壁垒调查应当自立案决定公告之日起6个月内结束；特殊情况下可以延长，但延长期不得超过3个月。"},{"i":33,"n":"第三十三条","txt":"如果被调查的措施或者做法被认定构成本规则第三条所称的贸易壁垒，商务部应当视情况采取以下措施： （一）进行双边磋商； （二）启动多边争端解决机制； （三）采取其他适当的措施。"},{"i":34,"n":"第三十四条","txt":"依照本规则作出的公告，应当载明重要的情况、事实、理由、依据、结果和结论等内容。"},{"i":35,"n":"第三十五条","txt":"对国外投资壁垒的调查，参照本规则进行。"},{"i":36,"n":"第三十六条","txt":"本规则由商务部负责解释。"},{"i":37,"n":"第三十七条","txt":"本规则自2005年3月1日起施行。"}],"duiwaimaoyijingjihezuobuguanyugongyinggangaoxianhub68092":[{"i":1,"n":"第一条","txt":"为维护正常的出口经营秩序，使供港澳鲜活冷冻商品做到优质、适量、均衡、应时，以满足港澳同胞日常生活消费需要，维护港澳地区的繁荣稳定，根据国务院批准的《出口商品管理暂行办法》特制定本规定。"},{"i":2,"n":"第二条","txt":"目前实行主动配额管理的鲜活冷冻商品共十二种（见附件）。经港澳转口、转运上述鲜活冷冻商品，视同对港澳出口，纳入主动配额管理范围。"},{"i":3,"n":"第三条","txt":"供港澳鲜活冷冻商品的出口配额一经下达，各地各有关单位须严格执行并保证完成。配额不允许买卖或转让。"},{"i":4,"n":"第四条","txt":"中华人民共和国对外贸易经济合作部（以下简称“外经贸部”）全面管理港澳鲜活冷冻主动配额商品（以下简称“鲜活冷冻商品”）的出口工作。负责制订并组织实施鲜活冷冻商品出口管理法规和发展规划；确定实行主动配额管理的鲜活冷冻商品的范围；负责鲜活冷冻商品主动配额的总量制定、分配下达、调整和监督使用；协调解决出口工作中的问题；授权鲜活冷冻商品出口证书的签发；管理全国证书的发放和统计；对各地、各有关公司以及驻港澳代理机构的工作进行指导、检查和监督；依法查处违章出口。"},{"i":5,"n":"第五条","txt":"外经贸部驻广州特派员办事处（以下简称“广州特办”）根据外经贸部授权，负责鲜活冷冻商品的部分管理工作，广州特办依据外经贸部下达的配额，分月安排出口数量并报外经贸部备案，并对执行情况进行监督、检查；及时研究解决配额执行过程中的具体问题；重大问题须及时向外经贸部报告并提出具体建议；协调各地区出口及地区与港澳代理机构之间的经营活动，随时了解市场需求状况，及时安排有关地区组织货源出口，保证均衡供应；会同有关单位调查违章出口，并对调查结果提出处理意见。"},{"i":6,"n":"第六条","txt":"各省、自治区、直辖市及计划单列市经贸厅（委）、外贸局（以下简称“各地外经贸委”）负责本地区鲜活冷冻商品的综合管理工作。根据外经贸部授权，签发有关鲜活冷冻商品出口证书；负责本地区出口企业关于鲜活冷冻商品配额申请的审核、平衡和上报工作；管理和督促检查本地区出口企业所分得配额的使用情况并负责本地区鲜活冷冻商品的出口统计工作；负责本地区鲜活冷冻商品的运输管理工作；指导有关企业做好鲜活冷冻商品的货源和基地的规划建设和质量管理工作；及时与各有关机构沟通本地区的业务情况，遇到重大问题及时向外经贸部报告。"},{"i":7,"n":"第七条","txt":"香港华润（集团）五丰行、澳门南光（集团）粮油食品有限公司作为内地鲜活冷冻商品在港澳的统一代理机构，负责协调管理市场销售工作。香港粤海（集团）广南行和澳门南粤（集团）食品水产公司在分别接受华润、南光（集团）公司统一协调的前提下，负责代理广东省出口的鲜活商品。 港澳代理和经销机构负责市场调研和预测、及时向国内有关机构反馈信息，并根据港澳市场需求，对其代理商品的配额的安排和调整提出建议。负责监督管理其代理商品范围内的鲜活冷冻商品经港澳转口业务。"},{"i":8,"n":"第八条","txt":"中国海关对鲜活冷冻商品的出口实行监管，凭有效的出口证书查验放行货物。"},{"i":9,"n":"第九条","txt":"除外经贸部另有规定者外，鲜活冷冻商品中的鲜蔬菜、水产品中的活塘鱼及水果中的西瓜、荔枝实行出口放行证管理，其余商品一律实行出口许可证管理。出口许可证和放行证由外经贸部授权的签证机关依据外经贸部分配的配额签发，交由海关凭出口许可证或放行证放行。"},{"i":10,"n":"第十条","txt":"获得配额的出口企业，均须按外经贸部有关许可证管理规定，到规定的签证机关领证后，方可出口。"},{"i":11,"n":"第十一条","txt":"活塘鱼和广东省（含广州、深圳）办理出口的鲜蔬菜，由广东省经贸委按配额核发出口放行证。鲜水果中的西瓜、荔枝及广东省以外地区出口的鲜蔬菜由广州特办按配额发出口放行证。"},{"i":12,"n":"第十二条","txt":"外经贸部根据港澳市场需求数量，我货供销数量，上年配额安排数量及使用情况，参考港澳代理机构、各地外经贸委及广州特办等单位意见后，确定全年配额总量。"},{"i":13,"n":"第十三条","txt":"针对港澳市场容量有限，鲜活冷冻商品易残损、易死亡和腐烂的特点，为确保其出口工作健康发展，配额分配宜集中。原则上主要分配给承担上缴国家出口创汇任务并有鲜活冷冻商品出口实绩的各地粮油（食品）进出口公司。在此前提下，外经贸部可接受地方公司或国家有关外贸公司的申请，根据市场需求状况适量分配，以拾遗补缺。"},{"i":14,"n":"第十四条","txt":"各地各单位的配额数量按其上年出口实绩、配额执行情况、商品质量、售价和对鲜活冷冻商品出口的贡献以及执行本办法有关奖惩规定而定。"},{"i":15,"n":"第十五条","txt":"经外经贸部批准的有鲜活冷冻商品配额的外商投资企业以及三来一补项目，其配额数量在其项目合同期内原则上维持不变，合同期满后不再安排出口配额。"},{"i":16,"n":"第十六条","txt":"为促进各地及各出口企业提高出口商品质量和配额使用效益，外经贸部每年将安排部分配额进行招标，配额招标办法另行制订。"},{"i":17,"n":"第十七条","txt":"鲜活冷冻商品配额调整中实行“前落空后不补，前超后扣”的原则，即前期落空配额后期不补，前期未经安排而擅自超供的数量在后期的配额中扣减。"},{"i":18,"n":"第十八条","txt":"由于市场、货源和运输发生变化等原因所需在年度配额总量内临时调整，由广州特办负责，调整情况每月及时报外经贸部。如市场需求增加，超出配额总量的调整均须报外经贸部审批。"},{"i":19,"n":"第十九条","txt":"广东省（含广州、深圳）自产和出口的活塘鱼和鲜蔬菜的月度配额由广东省经贸委在外经贸部下达的广东省配额总量内自行下达和调整。月度配额安排及调整情况及时报外经贸部备案。"},{"i":20,"n":"第二十条","txt":"申请经港澳转口、转运鲜活冷冻商品的企业，必须事先提供合同、进口国许可证明和当地省级（含计划单列市）经贸管理部门的初审意见，报外经贸部审批，并抄送港澳代理机构。企业凭批准的配额领取出口许可证或放行证，由广州特办具体安排并检查出口情况。"},{"i":21,"n":"第二十一条","txt":"经港澳转口、转运的鲜活冷冻商品须接受港澳代理机构（香港华润五丰行和澳门南光粮油食品公司）的监管。转口、转运的商品运抵港澳后，应立即通知港澳代理机构，转运时由港澳代理机构派人监装。并将二程船运提单副本交港澳代理机构转广州特办销案。 广东省自行办理的活塘鱼和鲜蔬菜的转口和转运，由该省驻港澳代理机构按本办法的原则监督执行。"},{"i":22,"n":"第二十二条","txt":"对符合下列条件者可在调增配额时给予一定奖励： 1、严格执行本管理规定，商品质量优、信誉好、售价高。 2、配额执行情况好，并且积极配合市场调剂余缺，完成临时应急供应任务。"},{"i":23,"n":"第二十三条","txt":"对下列情况给予处罚： 1、不执行本规定，商品质量差、信誉差，以及无配额和超配额出口者，将视情况给予通报批评、扣减配额直至取消配额的处罚。 2、对超出出口许可证或放行证载明数量出口的鲜活冷冻商品，海关可酌情作出罚款并没收货物的处理。 3、对不交由港澳代理机构代理而自行销售的出口企业（含外资企业）将视情况给予扣减配额直至取消配额的处罚。 4、对以远洋地区许可证出口到港澳地区者，一经查实，将按其情节轻重给予取消配额或该项商品出口经营权的处罚。"},{"i":24,"n":"第二十四条","txt":"鲜活冷冻商品管理的各项工作应严格执行本规定，防止主观随意性。外经贸部和各地外经贸委的管理工作人员应接受监督，如有以权谋私、违反本办法者，经查实后，将视情节轻重给予处分直至追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"各地外经贸委和各出口企业均应安排足够的人员专司此项工作，管理人员要相对稳定。"},{"i":26,"n":"第二十六条","txt":"各地外经贸委应结合本地区具体情况，制订实施细则，并报外经贸部备案；广州特办要综合有关情况，制订工作实施细则，经报外经贸部批准后下达。"},{"i":27,"n":"第二十七条","txt":"本规定自发布之日起实行，凡与本规定有抵触者，均以本规定为准。"},{"i":28,"n":"第二十八条","txt":"本规定由外经贸部负责解释。 附：供港澳鲜活冷冻主动配额商品目录 1、活猪（包括活大猪、活中猪、活乳猪）2、活牛3、活羊4、活禽（包括活鸡、竹丝鸡、珍珠鸡、活鸭、野鸭、活鹅、活乳鸽）5、活水产品（包括活塘鱼、大闸蟹）6、冻猪肉（包括整只冻猪、分割鲜、冷、冻猪肉、猪付产品、冻乳猪）7、冻牛肉（包括鲜、冷牛肉）8、冻羊肉（包括整只冻羊、分割鲜、冷、冻羊肉）9、冻家禽（包括整只和分割鲜、冷、冻鸡、鸭、填鸭、鹅、乳鸽）10、鲜水果（包括鸭梨（含雪梨）、哈密瓜、香梨、荔枝、西瓜）11、鲜蔬菜（包括大白菜、土豆、萝卜（白萝卜、青萝卜）、冬瓜、菜花、其它蔬菜）12、皮蛋"}],"duiwaimaoyijingyingzhebeiandengjibanfa":[{"i":1,"n":"第一条","txt":"为促进对外贸易发展，根据《中华人民共和国对外贸易法》（以下简称《外贸法》）第九条的有关规定，制订本办法。"},{"i":2,"n":"第二条","txt":"从事货物进出口或者技术进出口的对外贸易经营者，应当向中华人民共和国商务部（以下简称商务部）或商务部委托的机构办理备案登记；但是，法律、行政法规和商务部规定不需要备案登记的除外。 对外贸易经营者未按照本办法办理备案登记的，海关不予办理进出口的报关验放手续。"},{"i":3,"n":"第三条","txt":"商务部是全国对外贸易经营者备案登记工作的主管部门。"},{"i":4,"n":"第四条","txt":"对外贸易经营者备案登记工作实行全国联网和属地化管理。 商务部委托符合条件的地方对外贸易主管部门（以下简称备案登记机关）负责办理本地区对外贸易经营者备案登记手续；受委托的备案登记机关不得自行委托其他机构进行备案登记。 备案登记机关必须具备办理备案登记所必需的固定的办公场所，管理、录入、技术支持、维护的专职人员以及连接商务部对外贸易经营者备案登记网络系统(以下简称\"备案登记网络\")的相关设备等条件。 对于符合上述条件的备案登记机关，商务部可出具书面委托函，发放由商务部统一监制的备案登记印章，并对外公布。备案登记机关凭商务部的书面委托函和备案登记印章，通过商务部备案登记网络办理备案登记手续。对于情况发生变化、不符合上述条件的以及未按本办法第六、七条规定办理备案登记的备案登记机关，商务部可收回对其委托。"},{"i":5,"n":"第五条","txt":"对外贸易经营者备案登记的程序 对外贸易经营者在本地区备案登记机关办理备案登记。 对外贸易经营者备案登记程序如下： （一）领取《对外贸易经营者备案登记表》（以下简称《登记表》）。对外贸易经营者可以通过商务部政府网站（http://www.mofcom.gov.cn）下载，或到所在地备案登记机关领取《登记表》(样式附后)。 （二）填写《登记表》。对外贸易经营者应按《登记表》要求认真填写所有事项的信息，并确保所填写内容是完整的、准确的和真实的；同时认真阅读《登记表》背面的条款，并由企业法定代表人或个体工商负责人签字、盖章。 （三）向备案登记机关提交如下备案登记材料： 1、按本条第二款要求填写的《登记表》； 2、营业执照复印件；"},{"i":6,"n":"第六条","txt":"备案登记机关应自收到对外贸易经营者提交的上述材料之日起5日内办理备案登记手续，在《登记表》上加盖备案登记印章。"},{"i":7,"n":"第七条","txt":"备案登记机关在完成备案登记手续的同时，应当完整准确地记录和保存对外贸易经营者的备案登记信息和登记材料，依法建立备案登记档案。"},{"i":8,"n":"第八条","txt":"对外贸易经营者应凭加盖备案登记印章的《登记表》在30日内到当地海关、检验检疫、外汇、税务等部门办理开展对外贸易业务所需的有关手续。逾期未办理的，《登记表》自动失效。"},{"i":9,"n":"第九条","txt":"《登记表》上的任何登记事项发生变更时，对外贸易经营者应比照本办法第五条和第八条的有关规定，在30日内办理《登记表》的变更手续，逾期未办理变更手续的，其《登记表》自动失效。 备案登记机关收到对外贸易经营者提交的书面材料后，应当即时予以办理变更手续。"},{"i":10,"n":"第十条","txt":"对外贸易经营者已在工商部门办理注销手续或被吊销营业执照的，自营业执照注销或被吊销之日起，《登记表》自动失效。 根据《外贸法》的相关规定，商务部决定禁止有关对外贸易经营者在一年以上三年以下的期限内从事有关货物或者技术的进出口经营活动的，备案登记机关应当撤销其《登记表》；处罚期满后，对外贸易经营者可依据本办法重新办理备案登记。"},{"i":11,"n":"第十一条","txt":"备案登记机关应当在对外贸易经营者撤销备案登记后将有关情况及时通报海关、检验检疫、外汇、税务等部门。"},{"i":12,"n":"第十二条","txt":"对外贸易经营者不得伪造、变造、涂改、出租、出借、转让和出卖《登记表》。"},{"i":13,"n":"第十三条","txt":"备案登记机关在办理备案登记或变更备案登记时，不得变相收取费用。"},{"i":14,"n":"第十四条","txt":"本办法实施前，已经依法取得货物和技术进出口经营资格、且仅在原核准经营范围内从事进出口经营活动的对外贸易经营者，不再需要办理备案登记手续；对外贸易经营者如超出原核准经营范围从事进出口经营活动，仍需按照本办法办理备案登记。"},{"i":15,"n":"第十五条","txt":"本办法由商务部负责解释。"},{"i":16,"n":"第十六条","txt":"本办法自2004年7月1日起实施。凡与本办法不一致的规定，自本办法发布之日起废止。"}],"duiwaimaoyijingyingzheweifaweiguixingweigonggaoban226f4e":[{"i":1,"n":"第一条","txt":"为维护公平、自由的对外贸易秩序，根据《中华人民共和国对外贸易法》(以下简称《外贸法》)及其他有关法律、行政法规的规定，制订本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在对外贸易以及与对外贸易有关的知识产权保护中，违反《外贸法》规定，危害对外贸易秩序的违法违规对外贸易经营者及其行为。"},{"i":3,"n":"第三条","txt":"本办法所称对外贸易经营者，是指依法办理工商登记或者其他执业手续，依照《外贸法》和其他有关法律、行政法规的规定从事对外贸易经营活动的法人、其他组织或者个人。"},{"i":4,"n":"第四条","txt":"商务部负责沟通、协调、汇总违法违规对外贸易经营者及其行为的信息，并通过官方网站和指定的全国性刊物向社会公告违法违规对外贸易经营者及其行为。 商务部及地方商务主管部门会同海关、税务、工商、质检、外汇管理、公安、法院等有关部门建立信息交换和协调机制。"},{"i":5,"n":"第五条","txt":"向社会公告的违法违规对外贸易经营者及其行为，是指在对外贸易经营活动中有下列行为之一，并且依照法律、行政法规规定受到处理、处罚，或被依法追究刑事责任的： （一）进出口属于禁止进出口的货物、技术的，或者未经许可擅自进出口属于限制进出口的货物、技术的行为。 （二）违反国营贸易管理规定，非经授权擅自进出口实行国营贸易管理的货物的行为。 （三）从事属于禁止的国际服务贸易、未经许可擅自从事属于限制的国际服务贸易的行为。 （四）进出口货物侵犯知识产权，并危害对外贸易秩序的行为。 （五）违反有关反垄断的法律、行政法规的规定实施垄断行为。 （六）实施以不正当的低价销售商品、串通投标、发布虚假广告、进行商业贿赂等不正当竞争行为。 （七）伪造、变造进出口货物原产地标记，伪造、变造或者买卖进出口货物原产地证书、进出口许可证、进出口配额证明或者其他进出口证明文件。 （八）骗取出口退税。 （九）走私。 （十）逃避"},{"i":6,"n":"第六条","txt":"公告对外贸易经营者违法违规行为的信息包括： （一）经营者的名称、组织机构代码、住所、经营场所、法定代表人、工商登记注册号。 （二）违法违规行为。 （三）依照法律、行政法规规定所受到的处理、处罚和被追究刑事责任的内容。"},{"i":7,"n":"第七条","txt":"对已受到行政处罚、或已被依法追究刑事责任的对外贸易经营者，但属于下列情况之一的，不予或暂不予以公告： （一）在法律规定的有效期限内对行政处罚提起行政复议或行政诉讼，但尚未作出终局性决定、裁定或判决的； （二）涉及国家安全、商业秘密等法律、法规规定不予披露的。"},{"i":8,"n":"第八条","txt":"商务部按照公平、公正的原则，向社会公告危害对外贸易秩序的违法违规对外贸易经营者及其行为。"},{"i":9,"n":"第九条","txt":"依照本办法负责公告的工作人员玩忽职守，给对外贸易经营者造成不良影响和损失的，依据相关法律法规承担责任，并对有关责任人追究领导责任。"},{"i":10,"n":"第十条","txt":"本办法由商务部负责解释。"},{"i":11,"n":"第十一条","txt":"本办法自2005年9月1日起施行。"}],"duixianggangdiqulaowuhezuoguanlibanfa":[{"i":1,"n":"第一条","txt":"本着有利于祖国内地与香港地区的劳务合作和香港的繁荣稳定和“一国两制”方针的贯彻执行，特制定本办法。"},{"i":2,"n":"第二条","txt":"对香港地区进行劳务合作执行国家的统一政策和规定，服从统一协调管理，实行公平竞争，禁止经营公司间的相互压价和中间商的介入。"},{"i":3,"n":"第三条","txt":"对香港开展劳务合作业务应按照香港经济发展的需要和雇主的要求进行，劳务人员获得香港政府的入境许可后方可派出。"},{"i":4,"n":"第四条","txt":"对香港开展劳务合作业务须严格遵守当地的法律及规定。"},{"i":5,"n":"第五条","txt":"根据国家授权，对外贸易经济合作部（下称外经贸部）对在香港开展劳务合作业务实行统一归口管理，国务院港澳事务办公室（下称港澳办）进行政策指导。"},{"i":6,"n":"第六条","txt":"外经贸部根据香港输入外劳的规模及内地公司的经营状况，经商港澳办不定期确定经营对港劳务合作的经营公司名单。未获批准的公司一律不得经营对港劳务合作。"},{"i":7,"n":"第七条","txt":"经营公司按香港有关法律规定在香港注册领取牌照。"},{"i":8,"n":"第八条","txt":"对在香港开展劳务合作实行审批制，经营公司凭外经贸部（合作司）的批文办理劳务人员的出境手续。"},{"i":9,"n":"第九条","txt":"经营公司与香港政府批准输入劳务人员的雇主直接签订劳务合作合同。"},{"i":10,"n":"第十条","txt":"经营公司与劳务人员签订合同，明确双方的权利、义务。合同条款不得与经营公司与雇主签订的合同有抵触。"},{"i":11,"n":"第十一条","txt":"劳务人员须根据香港政府颁布的《聘用外地雇员的雇佣合约》与雇主签订雇佣合同。经营公司向劳务人员解释合同内容，回答劳务人员的问题。"},{"i":12,"n":"第十二条","txt":"经营公司按照国家的统一规定向劳务人员收取服务费。对从社会招聘的劳务人员，经营公司每月收取的服务费不得超过港府核定劳工月底薪的12．5％；为劳务人员保留职位的原单位每月可另行收取不超过港府核定劳工月底薪12．5％的费用。服务费一律在劳务人员派出前在国内由经营公司和劳务人员原所在单位分别一次性收取，并可采取现金、担保、抵押或借贷等多种方式。"},{"i":13,"n":"第十三条","txt":"办理派港劳务人员的护照、签证等费用由香港的雇主负担，经营公司不得另向劳务人员收取。"},{"i":14,"n":"第十四条","txt":"经营公司按合同要求选派品质好、技术合格、身体健康、能胜任工作的人员赴港工作。"},{"i":15,"n":"第十五条","txt":"派港劳务人员的招聘由经营公司负责进行，严禁香港雇主或中间商直接到内地自行招工。"},{"i":16,"n":"第十六条","txt":"劳务人员招聘工作要实行公开、公平的原则，除经外经贸主管部门批准发布的收费项目和收费标准外，经营公司不得向应聘人员收取任何其他额外费用。"},{"i":17,"n":"第十七条","txt":"经营公司原则上不得跨省（自治区、直辖市）招聘劳务人员。如因特殊情况需跨省（自治区、直辖市）招聘劳务人员，必须在报批时加以说明，并凭批文到劳务人员所在地的外经贸主管部门办理确认手续。"},{"i":18,"n":"第十八条","txt":"经营公司按照国家《外派劳务人员培训工作管理规定》对派港劳务人员进行培训，经考试合格并发给《外派劳务培训合格证》后方可派出。"},{"i":19,"n":"第十九条","txt":"经营公司须严格履行与雇主及劳务人员签订的合同，并督促雇主及劳务人员认真履约。"},{"i":20,"n":"第二十条","txt":"派港劳务人员在香港须遵守当地的法律、法规，不得擅自改变雇主和合同规定的工种，合同期满后，须及时返回原居住地，不得无故滞留香港。"},{"i":21,"n":"第二十一条","txt":"经营公司要保护派港劳务人员的合法权益。在雇主不遵守合同或发生劳资纠纷时，经营公司必须代表劳务人员出面交涉。发生重大问题要及时处理并向上级主管部门报告。"},{"i":22,"n":"第二十二条","txt":"经营公司应及时了解劳务人员的工作、生活情况，配合雇主切实加强对劳务人员的管理。"},{"i":23,"n":"第二十三条","txt":"对违反本办法第二条和第八条的经营公司，给予撤销对香港劳务合作经营权的处罚，并通报批评。"},{"i":24,"n":"第二十四条","txt":"对违反本办法第十二条和第十六条的经营公司，除责令退出多收款项外，还可给予撤销对港劳务合作经营权的处罚，并通报批评。"},{"i":25,"n":"第二十五条","txt":"对违反本办法其他条款的经营公司视情节给予警告或严重警告处分。对两年内累计受两次警告处分的经营公司，给予撤销对香港劳务合作经营权的处罚，并通报批评。"},{"i":26,"n":"第二十六条","txt":"如劳务人员在港有违法行为，按当地法律和规定处理；如违反与经营公司所签订的合同，按内地有关规定处理。"},{"i":27,"n":"第二十七条","txt":"本办法由外经贸部负责解释。"},{"i":28,"n":"第二十八条","txt":"本办法自下发之日起执行。"}],"zhanhuizhishichanquanbaohubanfa-3":[{"i":1,"n":"第一条","txt":"为加强展会期间知识产权保护，维护会展业秩序，推动会展业的健康发展，根据《中华人民共和国对外贸易法》、《中华人民共和国专利法》、《中华人民共和国商标法》和《中华人民共和国著作权法》及相关行政法规等制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内举办的各类经济技术贸易展览会、展销会、博览会、交易会、展示会等活动中有关专利、商标、版权的保护。"},{"i":3,"n":"第三条","txt":"展会管理部门应加强对展会期间知识产权保护的协调、监督、 检查，维护展会的正常交易秩序。"},{"i":4,"n":"第四条","txt":"展会主办方应当依法维护知识产权权利人的合法权益。展会主办方在招商招展时，应加强对参展方有关知识产权的保护和对参展项目（包括展品、展板及相关宣传资料等）的知识产权状况的审查。在展会期间，展会主办方应当积极配合知识产权行政管理部门的知识产权保护工作。 展会主办方可通过与参展方签订参展期间知识产权保护条款或合同的形式，加强展会知识产权保护工作。"},{"i":5,"n":"第五条","txt":"参展方应当合法参展，不得侵犯他人知识产权，并应对知识产权行政管理部门或司法部门的调查予以配合"},{"i":6,"n":"第六条","txt":"展会时间在三天以上（含三天），展会管理部门认为有必要的，展会主办方应在展会期间设立知识产权投诉机构。设立投诉机构的，展会举办地知识产权行政管理部门应当派员进驻，并依法对侵权案件进行处理。 未设立投诉机构的，展会举办地知识产权行政管理部门应当加强对展会知识产权保护的指导、监督和有关案件的处理，展会主办方应当将展会举办地的相关知识产权行政管理部门的联系人、联系方式等在展会场馆的显著位置予以公示。"},{"i":7,"n":"第七条","txt":"展会知识产权投诉机构应由展会主办方、展会管理部门、专利、商标、版权等知识产权行政管理部门的人员组成，其职责包括： （一）接受知识产权权利人的投诉，暂停涉嫌侵犯知识产权的展品在展会期间展出； （二）将有关投诉材料移交相关知识产权行政管理部门； （三）协调和督促投诉的处理； （四）对展会知识产权保护信息进行统计和分析； （五）其他相关事项。"},{"i":8,"n":"第八条","txt":"知识产权权利人可以向展会知识产权投诉机构投诉也可直接向知识产权行政管理部门投诉。权利人向投诉机构投诉的，应当提交以下材料： （一）合法有效的知识产权权属证明：涉及专利的，应当提交专利证书、专利公告文本、专利权人的身份证明、专利法律状态证明；涉及商标的，应当提交商标注册证明文件，并由投诉人签章确认，商标权利人身份证明；涉及著作权的，应当提交著作权权利证明、著作权人身份证明； （二）涉嫌侵权当事人的基本信息； （三）涉嫌侵权的理由和证据； （四）委托代理人投诉的，应提交授权委托书。"},{"i":9,"n":"第九条","txt":"不符合本办法第八条规定的，展会知识产权投诉机构应当及时通知投诉人或者请求人补充有关材料。未予补充的，不予接受。"},{"i":10,"n":"第十条","txt":"投诉人提交虚假投诉材料或其他因投诉不实给被投诉人带来损失的，应当承担相应法律责任。"},{"i":11,"n":"第十一条","txt":"展会知识产权投诉机构在收到符合本办法第八条规定的投诉材料后，应于24小时内将其移交有关知识产权行政管理部门。"},{"i":12,"n":"第十二条","txt":"地方知识产权行政管理部门受理投诉或者处理请求的，应当通知展会主办方，并及时通知被投诉人或者被请求人。"},{"i":13,"n":"第十三条","txt":"在处理侵犯知识产权的投诉或者请求程序中，地方知识产权行政管理部门可以根据展会的展期指定被投诉人或者被请求人的答辩期限。"},{"i":14,"n":"第十四条","txt":"被投诉人或者被请求人提交答辩书后，除非有必要作进一步调查，地方知识产权行政管理部门应当及时作出决定并送交双方当事人。 被投诉人或者被请求人逾期未提交答辩书的，不影响地方知识产权行政管理部门作出决定。"},{"i":15,"n":"第十五条","txt":"展会结束后，相关知识产权行政管理部门应当及时将有关处理结果通告展会主办方。展会主办方应当做好展会知识产权保护的统计分析工作，并将有关情况及时报展会管理部门。"},{"i":16,"n":"第十六条","txt":"展会投诉机构需要地方知识产权局协助的，地方知识产权局应当积极配合，参与展会知识产权保护工作。地方知识产权局在展会期间的工作可以包括： （一）接受展会投诉机构移交的关于涉嫌侵犯专利权的投诉，依照专利法律法规的有关规定进行处理； （二）受理展出项目涉嫌侵犯专利权的专利侵权纠纷处理请求，依照专利法第五十七条的规定进行处理； （三）受理展出项目涉嫌假冒他人专利和冒充专利的举报，或者依职权查处展出项目中假冒他人专利和冒充专利的行为，依据专利法第五十八条和第五十九条的规定进行处罚。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，地方知识产权局对侵犯专利权的投诉或者处理请求不予受理： （一）投诉人或者请求人已经向人民法院提起专利侵权诉讼的； （二）专利权正处于无效宣告请求程序之中的； （三）专利权存在权属纠纷，正处于人民法院的审理程序或者管理专利工作的部门的调解程序之中的； （四）专利权已经终止，专利权人正在办理权利恢复的。"},{"i":18,"n":"第十八条","txt":"地方知识产权局在通知被投诉人或者被请求人时，可以即行调查取证，查阅、复制与案件有关的文件，询问当事人，采用拍照、摄像等方式进行现场勘验，也可以抽样取证。 地方知识产权局收集证据应当制作笔录，由承办人员、被调查取证的当事人签名盖章。被调查取证的当事人拒绝签名盖章的，应当在笔录上注明原因；有其他人在现场的，也可同时由其他人签名。"},{"i":19,"n":"第十九条","txt":"展会投诉机构需要地方工商行政管理部门协助的，地方工商行政管理部门应当积极配合，参与展会知识产权保护工作。地方工商行政管理部门在展会期间的工作可以包括： （一）接受展会投诉机构移交的关于涉嫌侵犯商标权的投诉，依照商标法律法规的有关规定进行处理； （二）受理符合商标法第五十二条规定的侵犯商标专用权的投诉； （三）依职权查处商标违法案件。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，地方工商行政管理部门对侵犯商标专用权的投诉或者处理请求不予受理： （一）投诉人或者请求人已经向人民法院提起商标侵权诉讼的； （二）商标权已经无效或者被撤销的。"},{"i":21,"n":"第二十一条","txt":"地方工商行政管理部门决定受理后，可以根据商标法律法规等相关规定进行调查和处理。"},{"i":22,"n":"第二十二条","txt":"展会投诉机构需要地方著作权行政管理部门协助的，地方著作权行政管理部门应当积极配合，参与展会知识产权保护工作。地方著作权行政管理部门在展会期间的工作可以包括： （一）接受展会投诉机构移交的关于涉嫌侵犯著作权的投诉，依照著作权法律法规的有关规定进行处理； （二）受理符合著作权法第四十七条规定的侵犯著作权的投诉，根据著作权法的有关规定进行处罚。"},{"i":23,"n":"第二十三条","txt":"地方著作权行政管理部门在受理投诉或请求后，可以采取以下手段收集证据： （一）查阅、复制与涉嫌侵权行为有关的文件档案、帐簿和其他书面材料； （二）对涉嫌侵权复制品进行抽样取证； （三）对涉嫌侵权复制品进行登记保存。"},{"i":24,"n":"第二十四条","txt":"对涉嫌侵犯知识产权的投诉，地方知识产权行政管理部门认定侵权成立的，应会同会展管理部门依法对参展方进行处理。"},{"i":25,"n":"第二十五条","txt":"对涉嫌侵犯发明或者实用新型专利权的处理请求，地方知识产权局认定侵权成立的，应当依据专利法第十一条第一款关于禁止许诺销售行为的规定以及专利法第五十七条关于责令侵权人立即停止侵权行为的规定作出处理决定，责令被请求人从展会上撤出侵权展品，销毁介绍侵权展品的宣传材料，更换介绍侵权项目的展板。 对涉嫌侵犯外观设计专利权的处理请求，被请求人在展会上销售其展品，地方知识产权局认定侵权成立的，应当依据专利法第十一条第二款关于禁止销售行为的规定以及第五十七条关于责令侵权人立即停止侵权行为的规定作出处理决定，责令被请求人从展会上撤出侵权展品。"},{"i":26,"n":"第二十六条","txt":"在展会期间假冒他人专利或以非专利产品冒充专利产品，以非专利方法冒充专利方法的，地方知识产权局应当依据专利法第五十八条和第五十九条规定进行处罚。"},{"i":27,"n":"第二十七条","txt":"对有关商标案件的处理请求，地方工商行政管理部门认定侵权成立的，应当根据《商标法》、《商标法实施条例》等相关规定进行处罚。"},{"i":28,"n":"第二十八条","txt":"对侵犯著作权及相关权利的处理请求，地方著作权行政管理部门认定侵权成立的，应当根据著作权法第四十七条的规定进行处罚，没收、销毁侵权展品及介绍侵权展品的宣传材料，更换介绍展出项目的展板。"},{"i":29,"n":"第二十九条","txt":"经调查，被投诉或者被请求的展出项目已经由人民法院或者知识产权行政管理部门作出判定侵权成立的判决或者决定并发生法律效力的，地方知识产权行政管理部门可以直接作出第二十六条、第二十七条、第二十八条和第二十九条所述的处理决定。"},{"i":30,"n":"第三十条","txt":"请求人除请求制止被请求人的侵权展出行为之外，还请求制止同一被请求人的其他侵犯知识产权行为的，地方知识产权行政管理部门对发生在其管辖地域之内的涉嫌侵权行为，可以依照相关知识产权法律法规以及规章的规定进行处理。"},{"i":31,"n":"第三十一条","txt":"参展方侵权成立的，展会管理部门可依法对有关参展方予以公告；参展方连续两次以上侵权行为成立的，展会主办方应禁止有关参展方参加下一届展会。"},{"i":32,"n":"第三十二条","txt":"主办方对展会知识产权保护不力的，展会管理部门应对主办方给予警告，并视情节依法对其再次举办相关展会的申请不予批准。"},{"i":33,"n":"第三十三条","txt":"展会结束时案件尚未处理完毕的，案件的有关事实和证据可经展会主办方确认，由展会举办地知识产权行政管理部门在15个工作日内移交有管辖权的知识产权行政管理部门依法处理。"},{"i":34,"n":"第三十四条","txt":"本办法中的知识产权行政管理部门是指专利、商标和版权行政管理部门；本办法中的展会管理部门是指展会的审批或者登记部门。"},{"i":35,"n":"第三十五条","txt":"本办法自2006年3月1日起实施。"}],"zhanhuizhishichanquanbaohubanfa":[{"i":1,"n":"第一条","txt":"为加强展会期间知识产权保护，维护会展业秩序，推动会展业的健康发展，根据《中华人民共和国对外贸易法》、《中华人民共和国专利法》、《中华人民共和国商标法》和《中华人民共和国著作权法》及相关行政法规等制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内举办的各类经济技术贸易展览会、展销会、博览会、交易会、展示会等活动中有关专利、商标、版权的保护。"},{"i":3,"n":"第三条","txt":"展会管理部门应加强对展会期间知识产权保护的协调、监督、检查，维护展会的正常交易秩序。"},{"i":4,"n":"第四条","txt":"展会主办方应当依法维护知识产权权利人的合法权益。展会主办方在招商招展时，应加强对参展方有关知识产权的保护和对参展项目（包括展品、展板及相关宣传资料等）的知识产权状况的审查。在展会期间，展会主办方应当积极配合知识产权行政管理部门的知识产权保护工作。 展会主办方可通过与参展方签订参展期间知识产权保护条款或合同的形式，加强展会知识产权保护工作。"},{"i":5,"n":"第五条","txt":"参展方应当合法参展，不得侵犯他人知识产权，并应对知识产权行政管理部门或司法部门的调查予以配合。"},{"i":6,"n":"第六条","txt":"展会时间在三天以上（含三天），展会管理部门认为有必要的，展会主办方应在展会期间设立知识产权投诉机构。设立投诉机构的，展会举办地知识产权行政管理部门应当派员进驻，并依法对侵权案件进行处理。 未设立投诉机构的，展会举办地知识产权行政管理部门应当加强对展会知识产权保护的指导、监督和有关案件的处理，展会主办方应当将展会举办地的相关知识产权行政管理部门的联系人、联系方式等在展会场馆的显著位置予以公示。"},{"i":7,"n":"第七条","txt":"展会知识产权投诉机构应由展会主办方、展会管理部门、专利、商标、版权等知识产权行政管理部门的人员组成，其职责包括： （一）接受知识产权权利人的投诉，暂停涉嫌侵犯知识产权的展品在展会期间展出； （二）将有关投诉材料移交相关知识产权行政管理部门； （三）协调和督促投诉的处理； （四）对展会知识产权保护信息进行统计和分析； （五）其他相关事项。"},{"i":8,"n":"第八条","txt":"知识产权权利人可以向展会知识产权投诉机构投诉也可直接向知识产权行政管理部门投诉。权利人向投诉机构投诉的，应当提交以下材料： （一）合法有效的知识产权权属证明：涉及专利的，应当提交专利证书、专利公告文本、专利权人的身份证明、专利法律状态证明；涉及商标的，应当提交商标注册证明文件，并由投诉人签章确认，商标权利人身份证明；涉及著作权的，应当提交著作权权利证明、著作权人身份证明； （二）涉嫌侵权当事人的基本信息； （三）涉嫌侵权的理由和证据； （四）委托代理人投诉的，应提交授权委托书。"},{"i":9,"n":"第九条","txt":"不符合本办法第八条规定的，展会知识产权投诉机构应当及时通知投诉人或者请求人补充有关材料。未予补充的，不予接受。"},{"i":10,"n":"第十条","txt":"投诉人提交虚假投诉材料或其他因投诉不实给被投诉人带来损失的，应当承担相应法律责任。"},{"i":11,"n":"第十一条","txt":"展会知识产权投诉机构在收到符合本办法第八条规定的投诉材料后，应于24小时内将其移交有关知识产权行政管理部门。"},{"i":12,"n":"第十二条","txt":"地方知识产权行政管理部门受理投诉或者处理请求的，应当通知展会主办方，并及时通知被投诉人或者被请求人。"},{"i":13,"n":"第十三条","txt":"在处理侵犯知识产权的投诉或者请求程序中，地方知识产权行政管理部门可以根据展会的展期指定被投诉人或者被请求人的答辩期限。"},{"i":14,"n":"第十四条","txt":"被投诉人或者被请求人提交答辩书后，除非有必要作进一步调查，地方知识产权行政管理部门应当及时作出决定并送交双方当事人。 被投诉人或者被请求人逾期未提交答辩书的，不影响地方知识产权行政管理部门作出决定。"},{"i":15,"n":"第十五条","txt":"展会结束后，相关知识产权行政管理部门应当及时将有关处理结果通告展会主办方。展会主办方应当做好展会知识产权保护的统计分析工作，并将有关情况及时报展会管理部门。"},{"i":16,"n":"第十六条","txt":"展会投诉机构需要地方知识产权局协助的，地方知识产权局应当积极配合，参与展会知识产权保护工作。地方知识产权局在展会期间的工作可以包括： （一）接受展会投诉机构移交的关于涉嫌侵犯专利权的投诉，依照专利法律法规的有关规定进行处理； （二）受理展出项目涉嫌侵犯专利权的专利侵权纠纷处理请求，依照专利法第五十七条的规定进行处理； （三）受理展出项目涉嫌假冒他人专利和冒充专利的举报，或者依职权查处展出项目中假冒他人专利和冒充专利的行为，依据专利法第五十八条和第五十九条的规定进行处罚。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，地方知识产权局对侵犯专利权的投诉或者处理请求不予受理： （一）投诉人或者请求人已经向人民法院提起专利侵权诉讼的； （二）专利权正处于无效宣告请求程序之中的； （三）专利权存在权属纠纷，正处于人民法院的审理程序或者管理专利工作的部门的调解程序之中的； （四）专利权已经终止，专利权人正在办理权利恢复的。"},{"i":18,"n":"第十八条","txt":"地方知识产权局在通知被投诉人或者被请求人时，可以即行调查取证，查阅、复制与案件有关的文件，询问当事人，采用拍照、摄像等方式进行现场勘验，也可以抽样取证。 地方知识产权局收集证据应当制作笔录，由承办人员、被调查取证的当事人签名盖章。被调查取证的当事人拒绝签名盖章的，应当在笔录上注明原因；有其他人在现场的，也可同时由其他人签名。"},{"i":19,"n":"第十九条","txt":"展会投诉机构需要地方工商行政管理部门协助的，地方工商行政管理部门应当积极配合，参与展会知识产权保护工作。地方工商行政管理部门在展会期间的工作可以包括： （一）接受展会投诉机构移交的关于涉嫌侵犯商标权的投诉，依照商标法律法规的有关规定进行处理； （二）受理符合商标法第五十二条规定的侵犯商标专用权的投诉； （三）依职权查处商标违法案件。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，地方工商行政管理部门对侵犯商标专用权的投诉或者处理请求不予受理： （一）投诉人或者请求人已经向人民法院提起商标侵权诉讼的； （二）商标权已经无效或者被撤销的。"},{"i":21,"n":"第二十一条","txt":"地方工商行政管理部门决定受理后，可以根据商标法律法规等相关规定进行调查和处理。"},{"i":22,"n":"第二十二条","txt":"展会投诉机构需要地方著作权行政管理部门协助的，地方著作权行政管理部门应当积极配合，参与展会知识产权保护工作。地方著作权行政管理部门在展会期间的工作可以包括： （一）接受展会投诉机构移交的关于涉嫌侵犯著作权的投诉，依照著作权法律法规的有关规定进行处理； （二）受理符合著作权法第四十七条规定的侵犯著作权的投诉，根据著作权法的有关规定进行处罚。"},{"i":23,"n":"第二十三条","txt":"地方著作权行政管理部门在受理投诉或请求后，可以采取以下手段收集证据： （一）查阅、复制与涉嫌侵权行为有关的文件档案、帐簿和其他书面材料； （二）对涉嫌侵权复制品进行抽样取证； （三）对涉嫌侵权复制品进行登记保存。"},{"i":24,"n":"第二十四条","txt":"对涉嫌侵犯知识产权的投诉，地方知识产权行政管理部门认定侵权成立的，应会同会展管理部门依法对参展方进行处理。"},{"i":25,"n":"第二十五条","txt":"对涉嫌侵犯发明或者实用新型专利权的处理请求，地方知识产权局认定侵权成立的，应当依据专利法第十一条第一款关于禁止许诺销售行为的规定以及专利法第五十七条关于责令侵权人立即停止侵权行为的规定作出处理决定，责令被请求人从展会上撤出侵权展品，销毁介绍侵权展品的宣传材料，更换介绍侵权项目的展板。 对涉嫌侵犯外观设计专利权的处理请求，被请求人在展会上销售其展品，地方知识产权局认定侵权成立的，应当依据专利法第十一条第二款关于禁止销售行为的规定以及第五十七条关于责令侵权人立即停止侵权行为的规定作出处理决定，责令被请求人从展会上撤出侵权展品。"},{"i":26,"n":"第二十六条","txt":"在展会期间假冒他人专利或以非专利产品冒充专利产品，以非专利方法冒充专利方法的，地方知识产权局应当依据专利法第五十八条和第五十九条规定进行处罚。"},{"i":27,"n":"第二十七条","txt":"对有关商标案件的处理请求，地方工商行政管理部门认定侵权成立的，应当根据《商标法》、《商标法实施条例》等相关规定进行处罚。"},{"i":28,"n":"第二十八条","txt":"对侵犯著作权及相关权利的处理请求，地方著作权行政管理部门认定侵权成立的，应当根据著作权法第四十七条的规定进行处罚，没收、销毁侵权展品及介绍侵权展品的宣传材料，更换介绍展出项目的展板。"},{"i":29,"n":"第二十九条","txt":"经调查，被投诉或者被请求的展出项目已经由人民法院或者知识产权行政管理部门作出判定侵权成立的判决或者决定并发生法律效力的，地方知识产权行政管理部门可以直接作出第二十六条、第二十七条、第二十八条和第二十九条所述的处理决定。"},{"i":30,"n":"第三十条","txt":"请求人除请求制止被请求人的侵权展出行为之外，还请求制止同一被请求人的其他侵犯知识产权行为的，地方知识产权行政管理部门对发生在其管辖地域之内的涉嫌侵权行为，可以依照相关知识产权法律法规以及规章的规定进行处理。"},{"i":31,"n":"第三十一条","txt":"参展方侵权成立的，展会管理部门可依法对有关参展方予以公告；参展方连续两次以上侵权行为成立的，展会主办方应禁止有关参展方参加下一届展会。"},{"i":32,"n":"第三十二条","txt":"主办方对展会知识产权保护不力的，展会管理部门应对主办方给予警告，并视情节依法对其再次举办相关展会的申请不予批准。"},{"i":33,"n":"第三十三条","txt":"展会结束时案件尚未处理完毕的，案件的有关事实和证据可经展会主办方确认，由展会举办地知识产权行政管理部门在15个工作日内移交有管辖权的知识产权行政管理部门依法处理。"},{"i":34,"n":"第三十四条","txt":"本办法中的知识产权行政管理部门是指专利、商标和版权行政管理部门；本办法中的展会管理部门是指展会的审批或者登记部门。"},{"i":35,"n":"第三十五条","txt":"本办法自2006年3月1日起实施。"}],"chengpinyouliutongguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强成品油流通管理，规范企业经营行为，维护国内流通秩序，保护经营者和消费者的合法权益，推动成品油流通高质量发展，根据相关法律、行政法规及国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事成品油批发、仓储、零售经营活动，应当遵守有关法律法规和本办法。"},{"i":3,"n":"第三条","txt":"国家对成品油批发、仓储经营实施备案管理，对成品油零售经营资格实施许可管理。"},{"i":4,"n":"第四条","txt":"商务部负责制定全国成品油流通监督管理政策，配合负有安全生产监督管理职责的部门做好成品油流通行业安全生产管理工作，指导地方做好成品油流通管理工作。 省、自治区、直辖市及计划单列市人民政府商务主管部门（以下简称省级商务主管部门）实施成品油批发、仓储经营企业备案。设区的市级人民政府指定部门（以下简称市级政府指定部门）负责本行政区域内成品油零售经营资格许可。 县级以上地方商务主管部门依据本办法依照职责分工，对本行政区域内成品油流通实施监督管理，配合负有安全生产监督管理职责的部门做好成品油流通行业安全生产管理工作。 县级以上地方商务主管部门执法职能已经整合划入有关综合执法部门的，本级人民政府有关综合执法部门负责本办法规定的行政执法工作；执法职能没有划转的，县级以上地方商务主管部门负责本办法规定的行政执法工作。"},{"i":5,"n":"第五条","txt":"成品油流通行业协会应当建立健全行业经营规范、自律公约和职业道德准则，加强行业信用建设，引导企业规范经营行为，维护行业秩序，促进行业健康有序高质量发展。"},{"i":6,"n":"第六条","txt":"商务部负责制定并公布全国统一的成品油批发、仓储经营企业备案操作指南，明确备案流程、备案材料、办理时限等。"},{"i":7,"n":"第七条","txt":"企业从事成品油批发、仓储经营的，持经营范围包含成品油批发仓储的营业执照、危险化学品经营许可证或港口经营许可证（含港口危险货物作业附证及相关附表），通过“全国石油市场管理应用”向企业所在地省级商务主管部门进行备案。企业应当对其提交的备案材料的真实性、合法性和完整性负责。 省级商务主管部门负责对企业提交的备案材料进行核对。备案材料齐全的，按规定时限予以办理，生成企业备案回执，并推送有关部门。备案材料不齐全的，应一次性告知补正。"},{"i":8,"n":"第八条","txt":"企业备案信息发生变化的，应当在自信息变化之日起30日内，通过“全国石油市场管理应用”履行备案变更手续。 经备案的成品油批发、仓储经营企业，相关证照失效的、企业依法终止的或不再从事相关经营活动的，应及时通过“全国石油市场管理应用”履行备案注销手续。 备案回执有效期一般为3年，且不应超过危险化学品经营许可证或港口经营许可证的有效期。有效期届满自动失效。"},{"i":9,"n":"第九条","txt":"申请成品油零售经营资格的企业，应当向零售网点所在地市级政府指定部门提出申请。 市级政府指定部门依法受理申请并依据本办法进行审核。对符合规定条件的，准予成品油零售经营资格许可，颁发成品油零售经营批准证书，并将许可企业信息推送有关部门。对不符合条件的，作出不予批准的决定并说明理由。"},{"i":10,"n":"第十条","txt":"申请成品油零售经营资格的企业，应当具备下列条件： （一）申请主体为在中华人民共和国境内依法登记注册的企业； （二）申请主体应当符合安全主管部门许可管理的有关要求； （三）零售网点符合国土空间规划和本地区成品油零售体系发展规划； （四）零售网点建设及设施设备符合国家相关标准和技术规范，通过相关部门验收。"},{"i":11,"n":"第十一条","txt":"申请成品油零售经营资格的企业，应当提交以下材料： （一）企业申请文件； （二）企业营业执照； （三）零售网点及其配套设施的产权文件； （四）市级以上地方商务主管部门出具的规划确认文件； （五）危险化学品经营许可证或港口经营许可证（含港口危险货物作业附证及相关附表）； （六）零售网点及其配套设施依法需要取得的生态环境、交通运输、自然资源、住房城乡建设、应急管理、市场监管等相关部门核发的许可文件或验收合格文件；民用机场内零售网点还应当提供符合国家有关标准、与经营业务规模相适应的航空燃油供应设施和设备的证明材料，但无需提交本款第（四）项材料；加油趸船还应当提供船舶权证、水域准入文件、加油趸船有效检验证书、港口经营备案批准材料; （七）审核机关要求的其他文件。 上述文件可以通过政府信息系统获取的，审核机关可不再要求企业提供。 企业应当对其提交的申请材料的真实性、合法性和完整性负责。"},{"i":12,"n":"第十二条","txt":"市级政府指定部门实施成品油零售经营资格许可的程序和期限，依照《中华人民共和国行政许可法》的有关规定执行。"},{"i":13,"n":"第十三条","txt":"成品油零售经营批准证书的发放实施一站一证原则。批准证书的登记经营地址（场所）应当与零售网点地址保持一致，每个地址只能登记一个批准证书。"},{"i":14,"n":"第十四条","txt":"成品油零售经营批准证书有效期一般为5年。成品油零售经营企业需要在有效期满后继续从事成品油零售经营活动的，应当在证书有效期届满30日前，向作出许可决定的市级政府指定部门提出延续申请。对仍具备本办法第十条规定条件的，准予换领成品油零售经营批准证书。 租赁经营、特许经营企业依法领取的成品油零售经营批准证书，应当标注“租赁经营”“特许经营”字样，证书有效期不应超过租赁合同、特许经营合同的终止日期。"},{"i":15,"n":"第十五条","txt":"商务部统一制定并公布成品油零售经营批准证书 （正、副本）版式。成品油零售经营批准证书的登记信息应当包括：证书编号、企业名称、经营地址（场所）、法定代表人（负责人）、经营种类、证书有效期、发证机关（签章）以及发证时间。"},{"i":16,"n":"第十六条","txt":"成品油零售经营批准证书不得伪造、涂改，不得买卖、出租、转借、质押或者以任何其他形式转让。 已变更、注销或到期换证的成品油零售经营批准证书应当交回发证机关，任何企业和个人不得私自收存。"},{"i":17,"n":"第十七条","txt":"成品油零售经营企业要求变更成品油零售经营批准证书有关事项的，应当向作出许可决定的市级政府指定部门提交变更申请，经核准后予以换发成品油零售经营批准证书。 以租赁方式从事成品油零售经营的，承租方应当自租赁合同签订之日起30日内申请办理成品油零售经营资格变更。"},{"i":18,"n":"第十八条","txt":"省级商务主管部门、市级政府指定部门及其工作人员在实施成品油批发、仓储经营企业备案及零售经营资格许可过程中，不得收取费用。"},{"i":19,"n":"第十九条","txt":"成品油经营企业应当符合自然资源、规划、建设、质量、计量、环保、安全生产、消防、治安反恐、商务、税务、交通运输、气象等方面法律法规和标准要求，建立油品购销存和出入库台账，严格落实散装汽油购销实名登记制度，据实核算数据，完善油品来源、销售去向、检验报告、检查记录等凭证材料档案。"},{"i":20,"n":"第二十条","txt":"成品油经营企业应当建立健全安全生产管理制度、风险防控机制、隐患排查治理机制和质量、环境保护管理制度，按照国家有关规定要求制定事故应急处置预案，定期对工作人员开展安全生产、应急处置等培训，定期开展安全自查。"},{"i":21,"n":"第二十一条","txt":"成品油经营企业应当按照统一格式，每月通过“全国石油市场管理应用”推送上月度油品购销存数据，不得提供虚假数据。"},{"i":22,"n":"第二十二条","txt":"任何单位和个人，未经批准不得擅自新建、改（扩）建成品油零售网点。成品油零售网点原址改（扩）建的，应当向所在地市级政府指定部门提出申请。"},{"i":23,"n":"第二十三条","txt":"成品油零售经营企业未经作出许可决定的市级政府指定部门批准，不得擅自歇业。 歇业一般不超过12个月。对因自然灾害、城市建设等原因造成歇业或无法正常经营的，经企业所在地市级政府指定部门批准，可延长歇业时间。 市级政府指定部门应当及时将成品油零售经营企业的歇业信息同步推送至相关部门。"},{"i":24,"n":"第二十四条","txt":"成品油批发、零售经营企业应当从经国家相关部门批准的成品油生产企业或经省级商务主管部门备案的成品油批发经营企业购进成品油。 成品油仓储经营企业为其他企业代储成品油的，应当验证油品合法来源及委托人合法证明。 成品油批发经营企业不得采用直接加注等方式向机动车船、非道路移动机械或终端用户加注成品油。 成品油零售经营企业不得未经批准在零售网点以外加注成品油。"},{"i":25,"n":"第二十五条","txt":"成品油零售经营企业应当将成品油零售经营批准证书正本置于企业经营地址（场所）的醒目位置。 成品油零售经营企业销售乙醇汽油和生物柴油等替代燃料，应当明示所销售替代燃料的油品种类和标号；加油设施罩棚标注的企业名称应当与成品油零售经营批准证书登记信息相符；加油站开展特许经营的，应当在加油站罩棚显著位置标识“特许”或“特许经营”字样。"},{"i":26,"n":"第二十六条","txt":"省级商务主管部门应当会同有关部门建立本行政区域内成品油批发、仓储经营企业名录，市级政府指定部门应当会同有关部门建立本行政区域内成品油零售经营企业名录。上述企业名录应当向社会公布。"},{"i":27,"n":"第二十七条","txt":"成品油批发、仓储经营企业有下列情形之一的，省级商务主管部门应当在“全国石油市场管理应用”中予以标注，并推送有关部门： （一）通过隐瞒有关情况或者提供虚假材料完成备案的； （二）营业执照、危险化学品经营许可证或港口经营许可证已过期或失效的； （三）根据本办法第三十八条、第三十九条规定受到行政处罚的。"},{"i":28,"n":"第二十八条","txt":"省级商务主管部门应当坚持优化存量、按需增量原则，对市级人民政府商务主管部门编制成品油零售体系发展规划进行指导。规划编制要符合《成品油零售企业管理技术规范》加油站设置间距要求，充分考虑农村地区用油需求，支持农村加油点按照新建加油站设置程序和要求升级为加油站。"},{"i":29,"n":"第二十九条","txt":"县级以上地方商务主管部门应当按照本办法对本行政区域内成品油经营企业进行监督检查。对检查中发现违反本办法规定的及时查处，并将查处情况向社会公开；对检查中发现涉及其他部门监管职责的，应当通报同级相关部门予以查处。 监督检查可以采取下列措施： （一）实施现场检查、非现场检查； （二）就监督检查事项询问有关单位和个人； （三）查阅、复制与监督检查事项有关的文件、资料、电子数据； （四）依据国家有关规定采取的其他措施。"},{"i":30,"n":"第三十条","txt":"县级以上地方商务主管部门应当组织对本行政区域内成品油零售经营企业进行年度检查，并将检查情况报上一级商务主管部门。对不配合检查或检查不合格的成品油零售经营企业，应当下达整改通知书，责令其限期整改。 成品油零售经营企业应当配合年度检查，按要求提交有关材料，包括： （一）企业基础信息； （二）企业相关证照情况； （三）企业经营设施情况； （四）企业相关管理制度建立和执行情况； （五）企业上年度经营状况、购销存和出入库台账； （六）主管部门认为应当提交的其他相关材料。"},{"i":31,"n":"第三十一条","txt":"县级以上地方商务主管部门应当依职责会同相关部门加强本行政区域内成品油经营企业基本信息和经营数据归集，加强部门间产业链上下游数据交互共享和协同应用。 鼓励有条件的地方推广运用大数据、物联网等技术手段，推进智慧加油站、成品油流通大数据管理体系建设，加快构建涵盖批发、仓储、零售等环节的动态监管体系，提升成品油流通领域数智化监管效能和服务水平。"},{"i":32,"n":"第三十二条","txt":"县级以上地方商务主管部门应当会同有关部门对成品油经营企业实施信用分级分类管理，根据企业诚信经营、规范管理、依法纳税、服务质量、履行社会责任和日常监管等情况，对本行政区域内成品油经营企业划分信用状况等级，依法实施差异化监管。 县级以上地方商务主管部门结合企业日常检查与年度检查情况，对运营管理规范、设备设施齐全、经营状况及信用良好的成品油经营企业相关信息进行公示。"},{"i":33,"n":"第三十三条","txt":"有关部门和单位对成品油流通管理工作中知悉的国家秘密、商业秘密和个人隐私依法负有保密义务。"},{"i":34,"n":"第三十四条","txt":"企业在进行成品油批发、仓储经营企业备案时，隐瞒有关情况或者提供虚假备案材料的，省级商务主管部门不予备案，并给予警告。 企业通过隐瞒有关情况或者提供虚假备案材料取得备案回执的，省级商务主管部门应当撤销其备案回执，并可给予警告、通报批评或处5万元以下罚款。"},{"i":35,"n":"第三十五条","txt":"企业隐瞒有关情况或者提供虚假材料申请成品油零售经营资格许可的，市级政府指定部门应当不予受理或者不予许可，并给予警告；该企业在一年内不得再次申请成品油零售经营资格许可。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一的，作出成品油零售经营资格许可决定的市级政府指定部门或者其上级行政机关，根据利害关系人的请求或依据职权，可以撤销成品油零售经营资格许可： （一）行政机关工作人员滥用职权、玩忽职守作出准予许可决定的； （二）超越法定职权或违反法定程序作出准予许可决定的； （三）对不具备申请资格或者不符合法定条件的申请人作出准予许可决定的； （四）依法可以撤销行政许可的其他情形。 企业以欺骗、贿赂等不正当手段取得成品油零售经营资格许可的，作出许可决定的市级政府指定部门或者其上级行政机关应当撤销其成品油零售经营资格许可，并给予警告、通报批评或处10万元以下罚款；该企业在三年内不得再次申请成品油零售经营资格许可。"},{"i":37,"n":"第三十七条","txt":"成品油零售经营企业有下列情形之一的，作出许可决定的市级政府指定部门应当依法办理成品油零售经营资格许可注销手续： （一）成品油零售经营批准证书有效期满未延续的； （二）成品油零售经营企业依法终止的； （三）成品油零售经营资格许可依法被撤销、撤回，或者相关许可证件、营业执照依法被吊销的； （四）因不可抗力导致行政许可事项无法实施的； （五）法律、法规规定的其他应当注销的情形。"},{"i":38,"n":"第三十八条","txt":"有下列情形之一的，由县级以上地方商务主管部门责令限期改正，并可给予警告、通报批评或处5万元以下罚款： （一）违反本办法第八条规定，成品油批发、仓储经营企业的备案信息发生变化，但无正当理由未在规定时限内履行变更备案手续的； （二）违反本办法第十九条规定，成品油经营企业未按要求建立油品购销存和出入库台账的，或者台账弄虚作假的； （三）违反本办法第二十三条规定，成品油零售经营企业未按要求办理歇业相关手续且逾期不改正的； （四）违反本办法第二十五条规定，成品油零售经营企业未准确明示油品种类和标号进行销售的，或者加油设施罩棚标注的企业名称与成品油零售经营批准证书登记信息不相符的，或者加油站开展特许经营但未在加油站罩棚显著位置标识“特许”或“特许经营”字样的； （五）违反本办法第二十九条、第三十条规定，成品油经营企业不配合检查，或检查不合格且限期整改不到位的。"},{"i":39,"n":"第三十九条","txt":"有下列情形之一的，由县级以上地方商务主管部门责令限期改正，并可给予警告、通报批评或处10万元以下罚款： （一）成品油零售经营企业不再符合本办法第十条许可条件但继续从事成品油零售经营活动的； （二）违反本办法第十六条规定，成品油零售经营企业涂改、倒卖、出租、转借、质押或者以其他形式转让成品油零售经营批准证书的； （三）违反本办法第二十一条规定，成品油经营企业隐瞒有关情况、不报送油品购销存数据或提供虚假数据的； （四）违反本办法第二十二条规定，擅自新建、改（扩）建成品油零售网点的； （五）违反本办法第二十四条第一款规定，成品油经营企业未按规定购进、销售成品油的； （六）违反本办法第二十四条第二款规定，成品油仓储经营企业不能提供代储油品合法来源及委托人合法证明的； （七）违反本办法第二十四条第三款规定，成品油批发经营企业采用直接加注等方式向机动车船、非道路移动机械或终端用户加注成品油的； （"},{"i":40,"n":"第四十条","txt":"县级以上商务主管部门、市级政府指定部门及其工作人员违反本办法规定，有下列情形之一的，由其上级行政机关或监察机关责令改正；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）对符合法定条件的申请不予受理的； （二）未向申请人说明不受理申请或者不予备案、不予许可理由的； （三）对不符合条件的申请人予以许可或者超越法定职权作出许可的； （四）对符合法定条件的申请人不予批准或无正当理由不在法定期限内作出批准决定的； （五）在实施成品油批发、仓储经营企业备案或零售经营资格许可过程中擅自收费的； （六）不依法履行监督职责或监督不力，造成严重后果的。"},{"i":41,"n":"第四十一条","txt":"本办法所称成品油是指汽油、煤油、柴油，及以上述油品为主要成分、符合国家产业政策和国家强制性产品质量标准、具有相同用途的乙醇汽油和生物柴油等替代燃料。 成品油批发是指向用于生产或经营的单位批量销售成品油的经营行为；成品油仓储是指利用油库设施提供成品油代储服务的经营行为；成品油零售是指利用零售网点向终端用户销售成品油的经营行为。 加油站租赁经营是指加油站出租方在一定期限内将加油站设施及建构筑物交由承租方经营，承租方向出租方交付租金并依照租赁经营合同对加油站实行自主经营的经营方式；加油站特许经营是指拥有与加油站经营相关的商号、注册商标、专有技术、经营模式、服务标准等经营资源的特许人，以合同形式将其拥有的经营资源许可被特许人使用，被特许人按照合同约定在统一的经营模式下开展经营，并向特许人支付特许经营费用的经营活动。 成品油零售网点是指利用加油站、加油点从事成品油终端销售的经营站点；加油点是指只"},{"i":42,"n":"第四十二条","txt":"省级商务主管部门可以结合本地区实际情况制定本办法的实施细则。"},{"i":43,"n":"第四十三条","txt":"本办法由商务部负责解释。"},{"i":44,"n":"第四十四条","txt":"本办法自2025年9月1日起施行。"}],"zhixingshijiemaoyizuzhimaoyijiujizhengduancaijueza5f2acc":[{"i":1,"n":"第一条","txt":"为执行世界贸易组织反倾销、反补贴和保障措施争端裁决，根据有关法律、行政法规的规定，制定本规则。"},{"i":2,"n":"第二条","txt":"世界贸易组织争端解决机构作出裁决，要求我国反倾销、反补贴或者保障措施与世界贸易组织协定相一致的，商务部可以依法建议或者决定修改、取消反倾销、反补贴或保障措施，或者决定采取其他适当措施。"},{"i":3,"n":"第三条","txt":"在作出本规则第二条的建议或者决定之前，商务部可以对有关案件进行再调查。决定进行再调查的，应当发布公告或者以其他方式通知案件利害关系方。"},{"i":4,"n":"第四条","txt":"再调查可以采用问卷、抽样、听证会、现场核查等方式。"},{"i":5,"n":"第五条","txt":"在得出再调查结果之前，商务部应当将所依据的基本事实披露给利害关系方，并给予合理时间提出评论意见。"},{"i":6,"n":"第六条","txt":"商务部可以就修改或者取消反倾销税、反补贴税、保障措施关税等关税措施，向国务院关税税则委员会提出建议，并根据其决定发布公告。 商务部决定修改或者取消价格承诺、承诺、数量限制等措施，或者决定采取其他适当措施的，应当发布公告或者以其他方式通知案件利害关系方。"},{"i":7,"n":"第七条","txt":"根据我国缔结或参加的其他贸易协定作出的裁决，要求我国反倾销、反补贴和保障措施与该协定相一致的，参照本规则执行。"},{"i":8,"n":"第八条","txt":"本规则自公布之日起施行。 本规则施行之日尚未执行完毕的裁决，适用本规则。"}],"jishujinchukouhetongdengjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范自由进出口技术的管理，建立技术进出口信息管理制度，促进我国技术进出口的发展，根据《中华人民共和国技术进出口管理条例》，特制定本办法。"},{"i":2,"n":"第二条","txt":"技术进出口合同包括专利权转让合同、专利申请权转让合同、专利实施许可合同、技术秘 密许可合同、技术服务合同和含有技术进出口的其他合同。"},{"i":3,"n":"第三条","txt":"商务主管部门是技术进出口合同的登记管理部门。 自由进出口技术合同自依法成立时生效。"},{"i":4,"n":"第四条","txt":"商务部负责对《政府核准的投资项目目录》和政府投资项目中由国务院或国务院投资主管部门核准或审批的项目项下的技术进口合同进行登记管理。"},{"i":5,"n":"第五条","txt":"各省、自治区、直辖市和计划单列市商务主管部门负责对本办法第四条以外的自由进出口技术合同进行登记管理。中央管理企业的自由进出口技术合同，按属地原则到各省、自治区、直辖市和计划单列市商务主管部门办理登记。 各省、自治区、直辖市和计划单列市商务主管部门可授权下一级商务主管部门对自由进出口技术合同进行登记管理。"},{"i":6,"n":"第六条","txt":"技术进出口经营者应在合同生效后60天内办理合同登记手续，支付方式为提成的合同除外。"},{"i":7,"n":"第七条","txt":"支付方式为提成的合同，技术进出口经营者应在首次提成基准金额形成后60天内，履行合同登记手续，并在以后每次提成基准金额形成后，办理合同变更手续。 技术进出口经营者在办理登记和变更手续时，应提供提成基准金额的相关证明文件。"},{"i":8,"n":"第八条","txt":"国家对自由进出口技术合同实行网上在线登记管理。技术进出口经营者应登陆商务部政府网站上的\"技术进出口合同信息管理系统\"(网址：jsjckqy.fwmys.mofcom.gov.cn)进行合同登记，并持技术进（出）口合同登记申请书、技术进（出）口合同副本（包括中文译本）和签约双方法律地位的证明文件，到商务主管部门履行登记手续。商务主管部门在收到上述文件起3个工作日内，对合同登记内容进行核对，并向技术进出口经营者颁发《技术进口合同登记证》或《技术出口合同登记证》。"},{"i":9,"n":"第九条","txt":"对申请文件不符合《中华人民共和国技术进出口管理条例》第十八条、第四十条规定要求或登记记录与合同内容不一致的，商务主管部门应当在收到申请文件的3个工作日内通知技术进出口经营者补正、修改，并在收到补正的申请文件起3个工作日内，对合同登记的内容进行核对，颁发《技术进口合同登记证》或《技术出口合同登记证》。"},{"i":10,"n":"第十条","txt":"自由进出口技术合同登记的主要内容为： （一）合同号 （二）合同名称 （三）技术供方 （四）技术受方 （五）技术使用方 （六）合同概况 （七）合同金额 （八）支付方式 （九）合同有效期"},{"i":11,"n":"第十一条","txt":"国家对自由进出口技术合同号实行标准代码管理。技术进出口经营者编制技术进出口合同号应符合下述规则： (一)合同号总长度为17位。 (二)前9位为固定号：第1-2位表示制合同的年份（年代后2位）、第3-4位表示进口或出口国别地区（国标2位代码）、第5-6位表示进出口企业所在地区（国标2位代码）、第7位表示技术进出口合同标识（进口Y，出口E）、第8-9位表示进出口技术的行业分类（国标2位代码）。后8位为企业自定义。 例：01USBJE01CNTIC001。"},{"i":12,"n":"第十二条","txt":"已登记的自由进出口技术合同若变更本办法第十条规定合同登记内容的，技术进出口经营者应当办理合同登记变更手续。 办理合同变更手续时，技术进出口经营者应登录\"技术进出口合同信息管理系统\"，填写合同数据变更记录表，持合同变更协议和合同数据变更记录表，到商务主管部门办理手续。商务主管部门自收到完备的变更申请材料之日起3日内办理合同变更手续。 按本办法第七条办理变更手续的，应持变更申请和合同数据变更记录表办理。"},{"i":13,"n":"第十三条","txt":"经登记的自由进出口技术合同在执行过程中因故中止或解除，技术进出口经营者应当持技术进出口合同登记证等材料及时向商务主管部门备案。"},{"i":14,"n":"第十四条","txt":"技术进出口合同登记证遗失，进出口经营者应公开挂失。凭挂失证明、补办申请和相关部门证明到商务主管部门办理补发手续。"},{"i":15,"n":"第十五条","txt":"各级商务主管部门应加强对技术进出口合同登记管理部门和人员的管理，建立健全合同登记岗位责任制，加强业务培训和考核。"},{"i":16,"n":"第十六条","txt":"中外合资、中外合作和外资企业成立时作为资本入股并作为合资章程附件的技术进口合同按外商投资企业有关法律规定办理相关手续。"},{"i":17,"n":"第十七条","txt":"商务部负责对全国技术进出口情况进行统计并定期发布统计数据。各级商务主管部门负责对本行政区域内的技术进出口情况进行统计。"},{"i":18,"n":"第十八条","txt":"本办法自公布之日起30日后施行。2002年1月1日起施行的《技术进出口合同登记管理办法》(对外贸易经济合作部 2001年第17号令)同时废止。"}],"baofeijidongchehuishouguanlibanfashishixize-2":[{"i":1,"n":"第一条","txt":"为规范报废机动车回收拆解活动，加强报废机动车回收拆解行业管理，根据国务院《报废机动车回收管理办法》（以下简称《管理办法》），制定本细则。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事报废机动车回收拆解活动，适用本细则。"},{"i":3,"n":"第三条","txt":"国家鼓励报废机动车回收拆解行业市场化、专业化、集约化发展，推动完善报废机动车回收利用体系，提高回收利用效率和服务水平。"},{"i":4,"n":"第四条","txt":"商务部负责组织全国报废机动车回收拆解的监督管理工作，发展改革委、工业和信息化部、公安部、生态环境部、交通运输部、市场监管总局等部门在各自职责范围内负责报废机动车有关监督管理工作。"},{"i":5,"n":"第五条","txt":"省级商务主管部门负责实施报废机动车回收拆解企业（以下简称回收拆解企业）资质认定工作。县级以上地方商务主管部门对本行政区域内报废机动车回收拆解活动实施监督管理，促进行业健康有序发展。 县级以上地方公安机关依据职责及相关法律法规的规定，对报废机动车回收拆解行业治安状况、买卖伪造票证等活动实施监督管理，并依法处置。 县级以上地方生态环境主管部门依据职责对回收拆解企业回收拆解活动的环境污染防治工作进行监督管理，防止造成环境污染，并依据相关法律法规处理。 县级以上地方发展改革、工业和信息化、交通运输、市场监管部门在各自的职责范围内负责本行政区域内报废机动车有关监督管理工作。"},{"i":6,"n":"第六条","txt":"报废机动车回收拆解行业协会、商会等应当制定行业规范，提供信息咨询、培训等服务，开展行业监测和预警分析，加强行业自律。"},{"i":7,"n":"第七条","txt":"国家对回收拆解企业实行资质认定制度。未经资质认定，任何单位或者个人不得从事报废机动车回收拆解活动。 国家鼓励机动车生产企业从事报废机动车回收拆解活动，机动车生产企业按照国家有关规定承担生产者责任，应当向回收拆解企业提供报废机动车拆解指导手册等相关技术信息。"},{"i":8,"n":"第八条","txt":"取得报废机动车回收拆解资质认定，应当具备下列条件： （一）具有企业法人资格； （二）拆解经营场地符合所在地城市总体规划或者国土空间规划及安全要求，不得建在居民区、商业区、饮用水水源保护区及其他环境敏感区内； （三）符合国家标准《报废机动车回收拆解企业技术规范》（GB22128）的场地、设施设备、存储、拆解技术规范，以及相应的专业技术人员要求； （四）符合环保标准《报废机动车拆解环境保护技术规范》（HJ348）要求； （五）具有符合国家规定的生态环境保护制度，具备相应的污染防治措施，对拆解产生的固体废物有妥善处置方案。"},{"i":9,"n":"第九条","txt":"申请资质认定的企业（以下简称申请企业）应当书面向拆解经营场地所在地省级商务主管部门或者通过商务部“全国汽车流通信息管理应用服务”系统提出申请，并提交下列书面材料： （一）设立申请报告（应当载明申请企业的名称、法定代表人、注册资本、住所、拆解场所、统一社会信用代码等内容）； （二）申请企业《营业执照》； （三）申请企业章程； （四）申请企业法定代表人身份证或者其他有效身份证件； （五）拆解经营场地土地使用权、房屋产权证明或者租期10年以上的土地租赁合同或者土地使用权出租合同及房屋租赁证明材料； （六）申请企业购置或者以融资租赁方式获取的用于报废机动车拆解和污染防治的设施、设备清单，以及发票或者融资租赁合同等所有权证明文件； （七）生态环境主管部门出具的建设项目环境影响评价文件的审批文件； （八）申请企业高级管理和专业技术人员名单； （九）申请企业拆解操作规范、安全规程和固体废物利用处置方"},{"i":10,"n":"第十条","txt":"省级商务主管部门应当对收到的资质认定申请材料进行审核，对材料齐全、符合法定形式的，应当受理申请；对材料不齐全或者不符合法定形式的，应当在收到申请之日起5个工作日内告知申请企业需要补正的内容。 省级商务主管部门可以委托拆解经营场地所在地地（市）级商务主管部门对申请材料是否齐全、符合法定形式进行审核。"},{"i":11,"n":"第十一条","txt":"省级商务主管部门受理资质认定申请后，应当组织成立专家组对申请企业进行现场验收评审。 省级商务主管部门应当建立由报废机动车拆解、生态环境保护、财务等相关领域专业技术人员组成的专家库，专家库人数不少于20人。 现场验收评审专家组由5人以上单数专家组成，从专家库中随机抽取专家产生，专家应当具有专业代表性。 专家组根据本细则规定的资质认定条件，实施现场验收评审，如实填写《现场验收评审意见表》。现场验收评审专家应当对现场验收评审意见负责。 省级商务主管部门应当参照商务部报废机动车回收拆解企业现场验收评审意见示范表，结合本地实际，制定本地区《现场验收评审意见表》。"},{"i":12,"n":"第十二条","txt":"省级商务主管部门经审查资质认定申请材料、《现场验收评审意见表》等，认为申请符合资质认定条件的，在省级商务主管部门网站和“全国汽车流通信息管理应用服务”系统予以公示，公示期不少于5个工作日。公示期间，对申请有异议的，省级商务主管部门应当根据需要通过组织听证、专家复评复审等对异议进行核实；对申请无异议的，省级商务主管部门应当在“全国汽车流通信息管理应用服务”系统对申请予以通过，创建企业账户，并颁发《报废机动车回收拆解企业资质认定证书》（以下简称《资质认定书》）。对申请不符合资质认定条件的，省级商务主管部门应当作出不予资质认定的决定并书面说明理由。 省级商务主管部门应当及时将本行政区域内取得资质认定的回收拆解企业名单向社会公布。"},{"i":13,"n":"第十三条","txt":"省级商务主管部门应当自受理资质认定申请之日起20个工作日内完成审查工作并作出相关决定。20个工作日内不能作出决定的，经省级商务主管部门负责人批准，可以延长10个工作日，并应当将延长期限的理由告知申请企业。 现场验收评审、听证等所需时间不计算在本条规定的期限内。省级商务主管部门应当将所需时间书面告知申请企业。"},{"i":14,"n":"第十四条","txt":"回收拆解企业不得涂改、出租、出借《资质认定书》，或者以其他形式非法转让《资质认定书》。"},{"i":15,"n":"第十五条","txt":"回收拆解企业设立分支机构的，应当在市场监管部门注册登记后30日内通过“全国汽车流通信息管理应用服务”系统向分支机构注册登记所在地省级商务主管部门备案，并上传下列材料的电子文档： （一）分支机构《营业执照》； （二）《报废机动车回收拆解企业分支机构备案信息表》。 回收拆解企业的分支机构不得拆解报废机动车。"},{"i":16,"n":"第十六条","txt":"回收拆解企业名称、住所或者法定代表人发生变更的，回收拆解企业应当自信息变更之日起30日内通过“全国汽车流通信息管理应用服务”系统上传变更说明及变更后的《营业执照》，经拆解经营场地所在地省级商务主管部门核准后换发《资质认定书》。"},{"i":17,"n":"第十七条","txt":"回收拆解企业拆解经营场地发生迁建、改建、扩建的，应当依据本细则重新申请回收拆解企业资质认定。申请符合资质认定条件的，予以换发《资质认定书》；不符合资质认定条件的，由原发证机关注销其《资质认定书》。"},{"i":18,"n":"第十八条","txt":"回收拆解企业在回收报废机动车时，应当核验机动车所有人有效身份证件，逐车登记机动车型号、号牌号码、 车辆识别代号、发动机号等信息，并收回下列证牌： （一）机动车登记证书原件； （二）机动车行驶证原件； （三）机动车号牌。 回收拆解企业应当核对报废机动车的车辆型号、号牌号码、车辆识别代号、发动机号等实车信息是否与机动车登记证书、机动车行驶证记载的信息一致。 无法提供本条第一款所列三项证牌中任意一项的，应当由机动车所有人出具书面情况说明，并对其真实性负责。 机动车所有人为自然人且委托他人代办的，还需提供受委托人有效证件及授权委托书；机动车所有人为机关、企业、事业单位、社会团体等的，需提供加盖单位公章的营业执照复印件、统一社会信用代码证书复印件或者社会团体法人登记证书复印件以及单位授权委托书、经办人身份证件。"},{"i":19,"n":"第十九条","txt":"回收拆解企业在回收报废机动车后，应当通过“全国汽车流通信息管理应用服务”系统如实录入机动车信息，打印《报废机动车回收证明》，上传机动车拆解前照片，机动车拆解后，上传拆解后照片。上传的照片应当包括机动车拆解前整体外观、拆解后状况以及车辆识别代号等特征。对按照规定应当在公安机关监督下解体的报废机动车，回收拆解企业应当在机动车拆解后，打印《报废机动车回收证明》。 回收拆解企业应当按照国家有关规定及时向公安机关交通管理部门申请机动车注销登记，将注销证明及《报废机动车回收证明》交给机动车所有人。"},{"i":20,"n":"第二十条","txt":"报废机动车“五大总成”和尾气后处理装置，以及新能源汽车动力蓄电池不齐全的，机动车所有人应当书面说明情况，并对其真实性负责。机动车车架（或者车身）或者发动机缺失的应当认定为车辆缺失，回收拆解企业不得出具《报废机动车回收证明》。"},{"i":21,"n":"第二十一条","txt":"机动车存在抵押、质押情形的，回收拆解企业不得出具《报废机动车回收证明》。 发现回收的报废机动车疑似为赃物或者用于盗窃、抢劫等犯罪活动工具的，以及涉嫌伪造变造号牌、车辆识别代号、发动机号的，回收拆解企业应当向公安机关报告。已经打印的《报废机动车回收证明》应当予以作废。"},{"i":22,"n":"第二十二条","txt":"《报废机动车回收证明》需要重新开具或者作废的，回收拆解企业应当收回已开具的《报废机动车回收证明》，并向拆解经营场地所在地地（市）级商务主管部门提出书面申请。地（市）级商务主管部门在“全国汽车流通信息管理应用服务”系统中对相关信息进行更改，并通报同级公安机关交通管理部门。"},{"i":23,"n":"第二十三条","txt":"回收拆解企业必须在其资质认定的拆解经营场地内对回收的报废机动车予以拆解，禁止以任何方式交易报废机动车整车、拼装车。回收的报废大型客、货车等营运车辆和校车，应当在公安机关现场或者视频监督下解体。回收拆解企业应当积极配合报废机动车监督解体工作。"},{"i":24,"n":"第二十四条","txt":"回收拆解企业拆解报废机动车应当符合国家标准《报废机动车回收拆解企业技术规范》（GB22128）相关要求，并建立生产经营全覆盖的电子监控系统，录像保存至少1年。"},{"i":25,"n":"第二十五条","txt":"回收拆解企业应当遵守环境保护法律、法规和强制性标准，建立固体废物管理台账，如实记录报废机动车拆解产物的种类、数量、流向、贮存、利用和处置等信息，并通过“全国固体废物管理信息系统”进行填报；制定危险废物管理计划，按照国家有关规定贮存、运输、转移和利用处置危险废物。"},{"i":26,"n":"第二十六条","txt":"回收拆解企业应当建立报废机动车零部件销售台账，如实记录报废机动车“五大总成”数量、型号、流向等信息，并录入“全国汽车流通信息管理应用服务”系统。 回收拆解企业应当对出售用于再制造的报废机动车“五大总成”按照商务部制定的标识规则编码，其中车架应当录入原车辆识别代号信息。"},{"i":27,"n":"第二十七条","txt":"回收拆解企业应当按照国家对新能源汽车动力蓄电池回收利用管理有关要求，对报废新能源汽车的废旧动力蓄电池或者其他类型储能装置进行拆卸、收集、贮存、运输及回收利用，加强全过程安全管理。 回收拆解企业应当将报废新能源汽车车辆识别代号及动力蓄电池编码、数量、型号、流向等信息，录入“新能源汽车国家监测与动力蓄电池回收利用溯源综合管理平台”系统。"},{"i":28,"n":"第二十八条","txt":"回收拆解企业拆解的报废机动车“五大总成”具备再制造条件的，可以按照国家有关规定出售给具有再制造能力的企业经过再制造予以循环利用；不具备再制造条件的，应当作为废金属，交售给冶炼或者破碎企业。"},{"i":29,"n":"第二十九条","txt":"回收拆解企业拆解的报废机动车“五大总成”以外的零部件符合保障人身和财产安全等强制性国家标准，能够继续使用的，可以出售，但应当标明“报废机动车回用件”。 回收拆解企业拆解的尾气后处理装置、危险废物应当如实记录，并交由有处理资质的企业进行拆解处置，不得向其他企业出售和转卖。 回收拆解企业拆卸的动力蓄电池应当交售给新能源汽车生产企业建立的动力蓄电池回收服务网点，或者符合国家对动力蓄电池梯次利用管理有关要求的梯次利用企业，或者从事废旧动力蓄电池综合利用的企业。"},{"i":30,"n":"第三十条","txt":"禁止任何单位或者个人利用报废机动车“五大总成”拼装机动车。"},{"i":31,"n":"第三十一条","txt":"机动车维修经营者不得承修已报废的机动车"},{"i":32,"n":"第三十二条","txt":"县级以上地方商务主管部门应当会同相关部门，采取“双随机、一公开”方式，对本行政区域内报废机动车回收拆解活动实施日常监督检查，重点检查以下方面： （一）回收拆解企业符合资质认定条件情况； （二）报废机动车回收拆解程序合规情况； （三）《资质认定书》使用合规情况； （四）出具《报废机动车回收证明》情况； （五）“五大总成”及其他零部件处置情况。"},{"i":33,"n":"第三十三条","txt":"县级以上地方商务主管部门可以会同相关部门采取下列措施进行监督检查： （一）进入从事报废机动车回收拆解活动的有关场所进行检查； （二）询问与监督检查事项有关的单位和个人，要求其说明情况； （三）查阅、复制有关文件、资料，检查相关数据信息系统及复制相关信息数据； （四）依据有关法律法规采取的其他措施。"},{"i":34,"n":"第三十四条","txt":"县级以上地方商务主管部门发现回收拆解企业不再具备本细则第八条规定条件的，应当责令其限期整改；拒不改正或者逾期未改正的，由原发证机关撤销其《资质认定书》。 回收拆解企业停止报废机动车回收拆解业务12个月以上的，或者注销营业执照的，由原发证机关撤销其《资质认定书》。 省级商务主管部门应当将本行政区域内被撤销、吊销《资质认定书》的回收拆解企业名单及时向社会公布。 回收拆解企业因违反本细则受到被吊销《资质认定书》的行政处罚，禁止该企业自行政处罚生效之日起三年内再次申请报废机动车回收拆解资质认定。"},{"i":35,"n":"第三十五条","txt":"各级商务、发展改革、工业和信息化、公安、生态环境、交通运输、市场监管等部门应当加强回收拆解企业监管信息共享，及时分享资质认定、变更、撤销等信息、回收拆解企业行政处罚以及《报废机动车回收证明》和报废机动车照片等信息。"},{"i":36,"n":"第三十六条","txt":"县级以上地方商务主管部门应当会同有关部门建立回收拆解企业信用档案，将企业相关违法违规行为依法作出的处理决定录入信用档案，并及时向社会公布。"},{"i":37,"n":"第三十七条","txt":"《资质认定书》《报废机动车回收证明》和《报废机动车回收拆解企业分支机构备案信息表》样式由商务部规定，省级商务主管部门负责印制发放，任何单位和个人不得买卖或者伪造、变造。"},{"i":38,"n":"第三十八条","txt":"省级商务主管部门应当加强对现场验收评审专家库的管理，实施动态调整机制。专家在验收评审过程中出现违反独立、客观、公平、公正原则问题的，省级商务主管部门应当及时将有关专家调整出现场验收评审专家库，且不得再次选入。"},{"i":39,"n":"第三十九条","txt":"县级以上地方商务主管部门应当向社会公布本部门的联系方式，方便公众举报报废机动车回收拆解相关的违法行为。 县级以上地方商务主管部门接到举报，应当及时依法调查处理，并为举报人保密；对实名举报的，应当将处理结果告知举报人。"},{"i":40,"n":"第四十条","txt":"违反本细则第七条第一款规定，未取得资质认定，擅自从事报废机动车回收拆解活动的，由县级以上地方商务主管部门会同有关部门按照《管理办法》第十九条规定没收非法回收拆解的报废机动车、报废机动车“五大总成”和其他零部件，没收违法所得；违法所得在5万元以上的，并处违法所得2倍以上5倍以下的罚款；违法所得不足5万元或者没有违法所得的，并处5万元以上10万元以下的罚款。 违反本细则第七条第二款规定，机动车生产企业未按照国家有关规定承担生产者责任向回收拆解企业提供相关技术支持的，由县级以上地方工业和信息化主管部门责令改正，并处1万元以上3万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"违反本细则第十四条规定，回收拆解企业涂改、出租、出借或者以其他形式非法转让《资质认定书》的，由县级以上地方商务主管部门责令改正，并处1万元以上3万元以下的罚款。"},{"i":42,"n":"第四十二条","txt":"违反本细则第十五条第一款规定，回收拆解企业未按照要求备案分支机构的，由分支机构注册登记所在地县级以上地方商务主管部门责令改正，并处1万元以上3万元以下的罚款。 违反本细则第十五条第二款规定，回收拆解企业的分支机构对报废机动车进行拆解的，由分支机构注册登记所在地县级以上地方商务主管部门责令改正，并处3万元罚款；拒不改正或者情节严重的，由原发证部门吊销回收拆解企业的《资质认定书》。"},{"i":43,"n":"第四十三条","txt":"违反本细则第十九条第一款、第二十条、第二十一条的规定，回收拆解企业违规开具或者发放《报废机动车回收证明》，或者未按照规定对已出具《报废机动车回收证明》的报废机动车进行拆解的，由县级以上地方商务主管部门责令限期改正，整改期间暂停打印《报废机动车回收证明》；情节严重的，处1万元以上3万元以下的罚款。 回收拆解企业明知或者应当知道回收的机动车为赃物或者用于盗窃、抢劫等犯罪活动的犯罪工具，未向公安机关报告，擅自拆解、改装、拼装、倒卖该机动车的，由县级以上地方公安机关按照《治安管理处罚法》予以治安管理处罚，构成犯罪的，依法追究刑事责任。 因违反前款规定，被追究刑事责任或者两年内被治安管理处罚两次以上的，由原发证部门吊销《资质认定书》。"},{"i":44,"n":"第四十四条","txt":"违反本细则第十九条第二款规定，回收拆解企业未按照国家有关规定及时向公安机关交通管理部门办理机动车注销登记，并将注销证明转交机动车所有人的，由县级以上地方商务主管部门按照《管理办法》第二十二条规定责令改正，可以处1万元以上5万元以下的罚款。"},{"i":45,"n":"第四十五条","txt":"违反本细则第二十三条规定，回收拆解企业未在其资质认定的拆解经营场地内对回收的报废机动车予以拆解，或者交易报废机动车整车、拼装车的，由县级以上地方商务主管部门责令改正，并处3万元罚款；拒不改正或者情节严重的，由原发证部门吊销《资质认定书》。"},{"i":46,"n":"第四十六条","txt":"违反本细则第二十四条规定，回收拆解企业未建立生产经营全覆盖的电子监控系统，或者录像保存不足1年的，由县级以上地方商务主管部门责令限期改正，整改期间暂停打印《报废机动车回收证明》；情节严重的，处1万元以上3万元以下的罚款。"},{"i":47,"n":"第四十七条","txt":"回收拆解企业违反环境保护法律、法规和强制性标准，污染环境的，由生态环境主管部门按照《管理办法》第二十四条规定责令限期改正，并依法予以处罚；拒不改正或者逾期未改正的，由原发证部门吊销《资质认定书》。 回收拆解企业不再符合本细则第八条规定有关环境保护相关认定条件的，由生态环境主管部门责令限期改正，并依法予以处罚；拒不改正或者逾期未改正的，由原发证部门撤销《资质认定书》。 回收拆解企业违反本细则第二十五条规定的，由生态环境主管部门依法予以处罚。"},{"i":48,"n":"第四十八条","txt":"违反本细则第二十六条规定，回收拆解企业未按照要求建立报废机动车零部件销售台账并如实记录“五大总成”信息并上传信息系统的，由县级以上地方商务主管部门按照《管理办法》第二十三条规定责令改正，并处1万元以上5万元以下的罚款；情节严重的，责令停业整顿。"},{"i":49,"n":"第四十九条","txt":"违反本细则第二十七条规定，回收拆解企业未按照国家有关标准和规定要求，对报废新能源汽车的废旧动力蓄电池或者其他类型储能设施进行拆卸、收集、贮存、运输及回收利用的，或者未将报废新能源汽车车辆识别代号及动力蓄电池编码、数量、型号、流向等信息录入有关平台的，由县级以上地方商务主管部门会同工业和信息化主管部门责令改正 ，并处1万元以上3万元以下的罚款。"},{"i":50,"n":"第五十条","txt":"违反本细则第二十八条、第二十九条规定，回收拆解企业出售的报废机动车“五大总成”及其他零部件不符合相关要求的，由县级以上地方商务主管部门按照《管理办法》第二十一条规定责令改正，没收报废机动车“五大总成”和其他零部件，没收违法所得；违法所得在5万元以上的，并处违法所得2倍以上5倍以下的罚款；违法所得不足5万元或者没有违法所得的，并处5万元以上10万元以下的罚款；情节严重的，责令停业整顿直至由原发证部门吊销《资质认定书》。 回收拆解企业将报废机动车“五大总成”及其他零部件出售给或者交予本细则第二十八条、第二十九条规定以外企业处理的，由县级以上地方商务主管部门会同有关部门责令改正，并处1万元以上3万元以下的罚款。"},{"i":51,"n":"第五十一条","txt":"违反本细则第三十一条规定，机动车维修经营者承修已报废的机动车的，由县级以上道路运输管理机构责令改正；有违法所得的，没收违法所得，处违法所得2倍以上10倍以下的罚款；没有违法所得或者违法所得不足1万元的，处2万元以上5万元以下的罚款，没收报废机动车；情节严重的，由县级以上道路运输管理机构责令停业整顿；构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"违反本细则三十七条规定，买卖或者伪造、变造《资质认定书》的，由县级以上地方公安机关依法给予治安管理处罚。 买卖或者伪造、变造《报废机动车回收证明》的，由县级以上地方公安机关按照《治安管理处罚法》予以治安管理处罚。"},{"i":53,"n":"第五十三条","txt":"发现在拆解或者处置过程中可能造成环境污染的电器电子等产品，设计使用列入国家禁止使用名录的有毒有害物质的，回收拆解企业有权向市场监管部门进行举报，有关部门应当及时通报市场监管部门。市场监管部门依据《循环经济促进法》第五十一条规定处理。"},{"i":54,"n":"第五十四条","txt":"各级商务、发展改革、工业和信息化、公安、生态环境、交通运输、市场监管等部门及其工作人员应当按照《管理办法》和本细则规定履行职责。违反相关规定的，按照《管理办法》第二十五条规定追究责任。任何单位和个人有权对相关部门及其工作人员的违法违规行为进行举报。"},{"i":55,"n":"第五十五条","txt":"省级商务主管部门可以结合本地实际情况制定本细则的实施办法，并报商务部备案。"},{"i":56,"n":"第五十六条","txt":"本细则实施前已经取得报废机动车回收资质的企业，应当在本细则实施后两年内按照本细则的要求向省级商务主管部门申请重新进行资质认定。通过资质认定的，换发《资质认定书》；超过两年未通过资质认定的，由原发证部门注销其《 资质认定书》。"},{"i":57,"n":"第五十七条","txt":"县级以上地方商务主管部门涉及本细则有关商务执法职责发生调整的，有关商务执法职责由本级人民政府确定的承担相关职责的部门实施。"},{"i":58,"n":"第五十八条","txt":"本细则由商务部会同发展改革委、工业和信息化部、公安部、生态环境部、交通运输部、市场监管总局负责解释。"},{"i":59,"n":"第五十九条","txt":"本细则自2020年9月1日起施行。"}],"baofeijidongchehuishouguanlibanfashishixize":[{"i":1,"n":"第一条","txt":"为规范报废机动车回收拆解活动，加强报废机动车回收拆解行业管理，根据国务院《报废机动车回收管理办法》（以下简称《管理办法》），制定本细则。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事报废机动车回收拆解活动，适用本细则。"},{"i":3,"n":"第三条","txt":"国家鼓励报废机动车回收拆解行业市场化、专业化、集约化发展，推动完善报废机动车回收利用体系，提高回收利用效率和服务水平。"},{"i":4,"n":"第四条","txt":"商务部负责组织全国报废机动车回收拆解的监督管理工作，发展改革委、工业和信息化部、公安部、生态环境部、交通运输部、市场监管总局等部门在各自职责范围内负责报废机动车有关监督管理工作。"},{"i":5,"n":"第五条","txt":"省级商务主管部门负责实施报废机动车回收拆解企业（以下简称回收拆解企业）资质认定工作。县级以上地方商务主管部门对本行政区域内报废机动车回收拆解活动实施监督管理，促进行业健康有序发展。 县级以上地方公安机关依据职责及相关法律法规的规定，对报废机动车回收拆解行业治安状况、买卖伪造票证等活动实施监督管理，并依法处置。 县级以上地方生态环境主管部门依据职责对回收拆解企业回收拆解活动的环境污染防治工作进行监督管理，防止造成环境污染，并依据相关法律法规处理。 县级以上地方发展改革、工业和信息化、交通运输、市场监管部门在各自的职责范围内负责本行政区域内报废机动车有关监督管理工作。"},{"i":6,"n":"第六条","txt":"报废机动车回收拆解行业协会、商会等应当制定行业规范，提供信息咨询、培训等服务，开展行业监测和预警分析，加强行业自律。"},{"i":7,"n":"第七条","txt":"国家对回收拆解企业实行资质认定制度。未经资质认定，任何单位或者个人不得从事报废机动车回收拆解活动。 国家鼓励机动车生产企业从事报废机动车回收拆解活动，机动车生产企业按照国家有关规定承担生产者责任，应当向回收拆解企业提供报废机动车拆解指导手册等相关技术信息。"},{"i":8,"n":"第八条","txt":"取得报废机动车回收拆解资质认定，应当具备下列条件： （一）具有企业法人资格； （二）拆解经营场地符合所在地城市总体规划或者国土空间规划及安全要求，不得建在居民区、商业区、饮用水水源保护区及其他环境敏感区内； （三）符合国家标准《报废机动车回收拆解企业技术规范》（GB22128）的场地、设施设备、存储、拆解技术规范，以及相应的专业技术人员要求； （四）符合环保标准《报废机动车拆解环境保护技术规范》（HJ348）要求； （五）具有符合国家规定的生态环境保护制度，具备相应的污染防治措施，对拆解产生的固体废物有妥善处置方案。"},{"i":9,"n":"第九条","txt":"申请资质认定的企业（以下简称申请企业）应当书面向拆解经营场地所在地省级商务主管部门或者通过商务部“全国汽车流通信息管理应用服务”系统提出申请，并提交下列书面材料： （一）设立申请报告（应当载明申请企业的名称、法定代表人、注册资本、住所、拆解场所、统一社会信用代码等内容）； （二）申请企业《营业执照》； （三）申请企业章程； （四）申请企业法定代表人身份证或者其他有效身份证件； （五）拆解经营场地土地使用权、房屋产权证明或者租期10年以上的土地租赁合同或者土地使用权出租合同及房屋租赁证明材料； （六）申请企业购置或者以融资租赁方式获取的用于报废机动车拆解和污染防治的设施、设备清单，以及发票或者融资租赁合同等所有权证明文件； （七）生态环境主管部门出具的建设项目环境影响评价文件的审批文件； （八）申请企业高级管理和专业技术人员名单； （九）申请企业拆解操作规范、安全规程和固体废物利用处置方"},{"i":10,"n":"第十条","txt":"省级商务主管部门应当对收到的资质认定申请材料进行审核，对材料齐全、符合法定形式的，应当受理申请；对材料不齐全或者不符合法定形式的，应当在收到申请之日起5个工作日内告知申请企业需要补正的内容。 省级商务主管部门可以委托拆解经营场地所在地地（市）级商务主管部门对申请材料是否齐全、符合法定形式进行审核。"},{"i":11,"n":"第十一条","txt":"省级商务主管部门受理资质认定申请后，应当组织成立专家组对申请企业进行现场验收评审。 省级商务主管部门应当建立由报废机动车拆解、生态环境保护、财务等相关领域专业技术人员组成的专家库，专家库人数不少于20人。现场验收评审专家组由5人以上单数专家组成，从专家库中随机抽取专家产生，专家应当具有专业代表性。 专家组根据本细则规定的资质认定条件，实施现场验收评审，如实填写《现场验收评审意见表》。现场验收评审专家应当对现场验收评审意见负责。 省级商务主管部门应当参照商务部报废机动车回收拆解企业现场验收评审意见示范表，结合本地实际，制定本地区《现场验收评审意见表》。"},{"i":12,"n":"第十二条","txt":"省级商务主管部门经审查资质认定申请材料、《现场验收评审意见表》等，认为申请符合资质认定条件的，在省级商务主管部门网站和“全国汽车流通信息管理应用服务”系统予以公示，公示期不少于5个工作日。公示期间，对申请有异议的，省级商务主管部门应当根据需要通过组织听证、专家复评复审等对异议进行核实；对申请无异议的，省级商务主管部门应当在“全国汽车流通信息管理应用服务”系统对申请予以通过，创建企业账户，并颁发《报废机动车回收拆解企业资质认定证书》（以下简称《资质认定书》）。对申请不符合资质认定条件的，省级商务主管部门应当作出不予资质认定的决定并书面说明理由。 省级商务主管部门应当及时将本行政区域内取得资质认定的回收拆解企业名单向社会公布。"},{"i":13,"n":"第十三条","txt":"省级商务主管部门应当自受理资质认定申请之日起20个工作日内完成审查工作并作出相关决定。20个工作日内不能作出决定的，经省级商务主管部门负责人批准，可以延长10个工作日，并应当将延长期限的理由告知申请企业。 现场验收评审、听证等所需时间不计算在本条规定的期限内。省级商务主管部门应当将所需时间书面告知申请企业。"},{"i":14,"n":"第十四条","txt":"回收拆解企业不得涂改、出租、出借《资质认定书》，或者以其他形式非法转让《资质认定书》。"},{"i":15,"n":"第十五条","txt":"回收拆解企业设立分支机构的，应当在市场监管部门注册登记后30日内通过“全国汽车流通信息管理应用服务”系统向分支机构注册登记所在地省级商务主管部门备案，并上传下列材料的电子文档： （一）分支机构《营业执照》； （二）《报废机动车回收拆解企业分支机构备案信息表》。 回收拆解企业的分支机构不得拆解报废机动车。"},{"i":16,"n":"第十六条","txt":"回收拆解企业名称、住所或者法定代表人发生变更的，回收拆解企业应当自信息变更之日起30日内通过“全国汽车流通信息管理应用服务”系统上传变更说明及变更后的《营业执照》，经拆解经营场地所在地省级商务主管部门核准后换发《资质认定书》。"},{"i":17,"n":"第十七条","txt":"回收拆解企业拆解经营场地发生迁建、改建、扩建的，应当依据本细则重新申请回收拆解企业资质认定。申请符合资质认定条件的，予以换发《资质认定书》；不符合资质认定条件的，由原发证机关注销其《资质认定书》。"},{"i":18,"n":"第十八条","txt":"回收拆解企业在回收报废机动车时，应当核验机动车所有人有效身份证件，逐车登记机动车型号、号牌号码、车辆识别代号、发动机号等信息，并收回下列证牌： （一）机动车登记证书原件； （二）机动车行驶证原件； （三）机动车号牌。 回收拆解企业应当核对报废机动车的车辆型号、号牌号码、车辆识别代号、发动机号等实车信息是否与机动车登记证书、机动车行驶证记载的信息一致。 无法提供本条第一款所列三项证牌中任意一项的，应当由机动车所有人出具书面情况说明，并对其真实性负责。 机动车所有人为自然人且委托他人代办的，还需提供受委托人有效证件及授权委托书；机动车所有人为机关、企业、事业单位、社会团体等的，需提供加盖单位公章的营业执照复印件、统一社会信用代码证书复印件或者社会团体法人登记证书复印件以及单位授权委托书、经办人身份证件。"},{"i":19,"n":"第十九条","txt":"回收拆解企业在回收报废机动车后，应当通过“全国汽车流通信息管理应用服务”系统如实录入机动车信息，打印《报废机动车回收证明》，上传机动车拆解前照片，机动车拆解后，上传拆解后照片。上传的照片应当包括机动车拆解前整体外观、拆解后状况以及车辆识别代号等特征。对按照规定应当在公安机关监督下解体的报废机动车，回收拆解企业应当在机动车拆解后，打印《报废机动车回收证明》。 回收拆解企业应当按照国家有关规定及时向公安机关交通管理部门申请机动车注销登记，将注销证明及《报废机动车回收证明》交给机动车所有人。"},{"i":20,"n":"第二十条","txt":"报废机动车“五大总成”和尾气后处理装置，以及新能源汽车动力蓄电池不齐全的，机动车所有人应当书面说明情况，并对其真实性负责。机动车车架（或者车身）或者发动机缺失的应当认定为车辆缺失，回收拆解企业不得出具《报废机动车回收证明》。"},{"i":21,"n":"第二十一条","txt":"机动车存在抵押、质押情形的，回收拆解企业不得出具《报废机动车回收证明》。 发现回收的报废机动车疑似为赃物或者用于盗窃、抢劫等犯罪活动工具的，以及涉嫌伪造变造号牌、车辆识别代号、发动机号的，回收拆解企业应当向公安机关报告。已经打印的《报废机动车回收证明》应当予以作废。"},{"i":22,"n":"第二十二条","txt":"《报废机动车回收证明》需要重新开具或者作废的，回收拆解企业应当收回已开具的《报废机动车回收证明》，并向拆解经营场地所在地地（市）级商务主管部门提出书面申请。地（市）级商务主管部门在“全国汽车流通信息管理应用服务”系统中对相关信息进行更改，并通报同级公安机关交通管理部门。"},{"i":23,"n":"第二十三条","txt":"回收拆解企业必须在其资质认定的拆解经营场地内对回收的报废机动车予以拆解，禁止以任何方式交易报废机动车整车、拼装车。回收的报废大型客、货车等营运车辆和校车，应当在公安机关现场或者视频监督下解体。回收拆解企业应当积极配合报废机动车监督解体工作。"},{"i":24,"n":"第二十四条","txt":"回收拆解企业拆解报废机动车应当符合国家标准《报废机动车回收拆解企业技术规范》（GB22128）相关要求，并建立生产经营全覆盖的电子监控系统，录像保存至少1年。"},{"i":25,"n":"第二十五条","txt":"回收拆解企业应当遵守环境保护法律、法规和强制性标准，建立固体废物管理台账，如实记录报废机动车拆解产物的种类、数量、流向、贮存、利用和处置等信息，并通过“全国固体废物管理信息系统”进行填报；制定危险废物管理计划，按照国家有关规定贮存、运输、转移和利用处置危险废物。"},{"i":26,"n":"第二十六条","txt":"回收拆解企业应当建立报废机动车零部件销售台账，如实记录报废机动车“五大总成”数量、型号、流向等信息，并录入“全国汽车流通信息管理应用服务”系统。 回收拆解企业应当对出售用于再制造的报废机动车“五大总成”按照商务部制定的标识规则编码，其中车架应当录入原车辆识别代号信息。"},{"i":27,"n":"第二十七条","txt":"回收拆解企业应当按照国家对新能源汽车动力蓄电池回收利用管理有关要求，对报废新能源汽车的废旧动力蓄电池或者其他类型储能装置进行拆卸、收集、贮存、运输及回收利用，加强全过程安全管理。 回收拆解企业应当将报废新能源汽车车辆识别代号及动力蓄电池编码、数量、型号、流向等信息，录入“新能源汽车国家监测与动力蓄电池回收利用溯源综合管理平台”系统。"},{"i":28,"n":"第二十八条","txt":"回收拆解企业拆解的报废机动车“五大总成”具备再制造条件的，可以按照国家有关规定出售给具有再制造能力的企业经过再制造予以循环利用；不具备再制造条件的，应当作为废金属，交售给冶炼或者破碎企业。"},{"i":29,"n":"第二十九条","txt":"回收拆解企业拆解的报废机动车“五大总成”以外的零部件符合保障人身和财产安全等强制性国家标准，能够继续使用的，可以出售，但应当标明“报废机动车回用件”。 回收拆解企业拆解的尾气后处理装置、危险废物应当如实记录，并交由有处理资质的企业进行拆解处置，不得向其他企业出售和转卖。 回收拆解企业拆卸的动力蓄电池应当交售给新能源汽车生产企业建立的动力蓄电池回收服务网点，或者符合国家对动力蓄电池梯次利用管理有关要求的梯次利用企业，或者从事废旧动力蓄电池综合利用的企业。"},{"i":30,"n":"第三十条","txt":"禁止任何单位或者个人利用报废机动车“五大总成”拼装机动车。"},{"i":31,"n":"第三十一条","txt":"机动车维修经营者不得承修已报废的机动车。"},{"i":32,"n":"第三十二条","txt":"县级以上地方商务主管部门应当会同相关部门，采取“双随机、一公开”方式，对本行政区域内报废机动车回收拆解活动实施日常监督检查，重点检查以下方面： （一）回收拆解企业符合资质认定条件情况； （二）报废机动车回收拆解程序合规情况； （三）《资质认定书》使用合规情况； （四）出具《报废机动车回收证明》情况； （五）“五大总成”及其他零部件处置情况。"},{"i":33,"n":"第三十三条","txt":"县级以上地方商务主管部门可以会同相关部门采取下列措施进行监督检查： （一）进入从事报废机动车回收拆解活动的有关场所进行检查； （二）询问与监督检查事项有关的单位和个人，要求其说明情况； （三）查阅、复制有关文件、资料，检查相关数据信息系统及复制相关信息数据； （四）依据有关法律法规采取的其他措施。"},{"i":34,"n":"第三十四条","txt":"县级以上地方商务主管部门发现回收拆解企业不再具备本细则第八条规定条件的，应当责令其限期整改；拒不改正或者逾期未改正的，由原发证机关撤销其《资质认定书》。 回收拆解企业停止报废机动车回收拆解业务12个月以上的，或者注销营业执照的，由原发证机关撤销其《资质认定书》。 省级商务主管部门应当将本行政区域内被撤销、吊销《资质认定书》的回收拆解企业名单及时向社会公布。 回收拆解企业因违反本细则受到被吊销《资质认定书》的行政处罚，禁止该企业自行政处罚生效之日起三年内再次申请报废机动车回收拆解资质认定。"},{"i":35,"n":"第三十五条","txt":"各级商务、发展改革、工业和信息化、公安、生态环境、交通运输、市场监管等部门应当加强回收拆解企业监管信息共享，及时分享资质认定、变更、撤销等信息、回收拆解企业行政处罚以及《报废机动车回收证明》和报废机动车照片等信息。"},{"i":36,"n":"第三十六条","txt":"县级以上地方商务主管部门应当会同有关部门建立回收拆解企业信用档案，将企业相关违法违规行为依法作出的处理决定录入信用档案，并及时向社会公布。"},{"i":37,"n":"第三十七条","txt":"《资质认定书》《报废机动车回收证明》和《报废机动车回收拆解企业分支机构备案信息表》样式由商务部规定，省级商务主管部门负责印制发放，任何单位和个人不得买卖或者伪造、变造。"},{"i":38,"n":"第三十八条","txt":"省级商务主管部门应当加强对现场验收评审专家库的管理，实施动态调整机制。专家在验收评审过程中出现违反独立、客观、公平、公正原则问题的，省级商务主管部门应当及时将有关专家调整出现场验收评审专家库，且不得再次选入。"},{"i":39,"n":"第三十九条","txt":"县级以上地方商务主管部门应当向社会公布本部门的联系方式，方便公众举报报废机动车回收拆解相关的违法行为。 县级以上地方商务主管部门接到举报，应当及时依法调查处理，并为举报人保密；对实名举报的，应当将处理结果告知举报人。"},{"i":40,"n":"第四十条","txt":"违反本细则第七条第一款规定，未取得资质认定，擅自从事报废机动车回收拆解活动的，由县级以上地方商务主管部门会同有关部门按照《管理办法》第十九条规定没收非法回收拆解的报废机动车、报废机动车“五大总成”和其他零部件，没收违法所得；违法所得在5万元以上的，并处违法所得2倍以上5倍以下的罚款；违法所得不足5万元或者没有违法所得的，并处5万元以上10万元以下的罚款。 违反本细则第七条第二款规定，机动车生产企业未按照国家有关规定承担生产者责任向回收拆解企业提供相关技术支持的，由县级以上地方工业和信息化主管部门责令改正，并处1万元以上3万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"违反本细则第十四条规定，回收拆解企业涂改、出租、出借或者以其他形式非法转让《资质认定书》的，由县级以上地方商务主管部门责令改正，并处1万元以上3万元以下的罚款。"},{"i":42,"n":"第四十二条","txt":"违反本细则第十五条第一款规定，回收拆解企业未按照要求备案分支机构的，由分支机构注册登记所在地县级以上地方商务主管部门责令改正，并处1万元以上3万元以下的罚款。 违反本细则第十五条第二款规定，回收拆解企业的分支机构对报废机动车进行拆解的，由分支机构注册登记所在地县级以上地方商务主管部门责令改正，并处3万元罚款；拒不改正或者情节严重的，由原发证部门吊销回收拆解企业的《资质认定书》。"},{"i":43,"n":"第四十三条","txt":"违反本细则第十九条第一款、第二十条、第二十一条的规定，回收拆解企业违规开具或者发放《报废机动车回收证明》，或者未按照规定对已出具《报废机动车回收证明》的报废机动车进行拆解的，由县级以上地方商务主管部门责令限期改正，整改期间暂停打印《报废机动车回收证明》；情节严重的，处1万元以上3万元以下的罚款。 回收拆解企业明知或者应当知道回收的机动车为赃物或者用于盗窃、抢劫等犯罪活动的犯罪工具，未向公安机关报告，擅自拆解、改装、拼装、倒卖该机动车的，由县级以上地方公安机关按照《治安管理处罚法》予以治安管理处罚，构成犯罪的，依法追究刑事责任。 因违反前款规定，被追究刑事责任或者两年内被治安管理处罚两次以上的，由原发证部门吊销《资质认定书》。"},{"i":44,"n":"第四十四条","txt":"违反本细则第十九条第二款规定，回收拆解企业未按照国家有关规定及时向公安机关交通管理部门办理机动车注销登记，并将注销证明转交机动车所有人的，由县级以上地方商务主管部门按照《管理办法》第二十二条规定责令改正，可以处1万元以上5万元以下的罚款。"},{"i":45,"n":"第四十五条","txt":"违反本细则第二十三条规定，回收拆解企业未在其资质认定的拆解经营场地内对回收的报废机动车予以拆解，或者交易报废机动车整车、拼装车的，由县级以上地方商务主管部门责令改正，并处3万元罚款；拒不改正或者情节严重的，由原发证部门吊销《资质认定书》。"},{"i":46,"n":"第四十六条","txt":"违反本细则第二十四条规定，回收拆解企业未建立生产经营全覆盖的电子监控系统，或者录像保存不足1年的，由县级以上地方商务主管部门责令限期改正，整改期间暂停打印《报废机动车回收证明》；情节严重的，处1万元以上3万元以下的罚款。"},{"i":47,"n":"第四十七条","txt":"回收拆解企业违反环境保护法律、法规和强制性标准，污染环境的，由生态环境主管部门按照《管理办法》第二十四条规定责令限期改正，并依法予以处罚；拒不改正或者逾期未改正的，由原发证部门吊销《资质认定书》。 回收拆解企业不再符合本细则第八条规定有关环境保护相关认定条件的，由生态环境主管部门责令限期改正，并依法予以处罚；拒不改正或者逾期未改正的，由原发证部门撤销《资质认定书》。 回收拆解企业违反本细则第二十五条规定的，由生态环境主管部门依法予以处罚。"},{"i":48,"n":"第四十八条","txt":"违反本细则第二十六条规定，回收拆解企业未按照要求建立报废机动车零部件销售台账并如实记录“五大总成”信息并上传信息系统的，由县级以上地方商务主管部门按照《管理办法》第二十三条规定责令改正，并处1万元以上5万元以下的罚款；情节严重的，责令停业整顿。"},{"i":49,"n":"第四十九条","txt":"违反本细则第二十七条规定，回收拆解企业未按照国家有关标准和规定要求，对报废新能源汽车的废旧动力蓄电池或者其他类型储能设施进行拆卸、收集、贮存、运输及回收利用的，或者未将报废新能源汽车车辆识别代号及动力蓄电池编码、数量、型号、流向等信息录入有关平台的，由县级以上地方商务主管部门会同工业和信息化主管部门责令改正，并处1万元以上3万元以下的罚款。"},{"i":50,"n":"第五十条","txt":"违反本细则第二十八条、第二十九条规定，回收拆解企业出售的报废机动车“五大总成”及其他零部件不符合相关要求的，由县级以上地方商务主管部门按照《管理办法》第二十一条规定责令改正，没收报废机动车“五大总成”和其他零部件，没收违法所得；违法所得在5万元以上的，并处违法所得2倍以上5倍以下的罚款；违法所得不足5万元或者没有违法所得的，并处5万元以上10万元以下的罚款；情节严重的，责令停业整顿直至由原发证部门吊销《资质认定书》。 回收拆解企业将报废机动车“五大总成”及其他零部件出售给或者交予本细则第二十八条、第二十九条规定以外企业处理的，由县级以上地方商务主管部门会同有关部门责令改正，并处1万元以上3万元以下的罚款。"},{"i":51,"n":"第五十一条","txt":"违反本细则第三十一条规定，机动车维修经营者承修已报废的机动车的，由县级以上道路运输管理机构责令改正；有违法所得的，没收违法所得，处违法所得2倍以上10倍以下的罚款；没有违法所得或者违法所得不足1万元的，处2万元以上5万元以下的罚款，没收报废机动车；情节严重的，由县级以上道路运输管理机构责令停业整顿；构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"违反本细则第三十七条规定，买卖或者伪造、变造《资质认定书》的，由县级以上地方公安机关依法给予治安管理处罚。 买卖或者伪造、变造《报废机动车回收证明》的，由县级以上地方公安机关按照《治安管理处罚法》予以治安管理处罚。"},{"i":53,"n":"第五十三条","txt":"发现在拆解或者处置过程中可能造成环境污染的电器电子等产品，设计使用列入国家禁止使用名录的有毒有害物质的，回收拆解企业有权向市场监管部门进行举报，有关部门应当及时通报市场监管部门。市场监管部门依据《循环经济促进法》第五十一条规定处理。"},{"i":54,"n":"第五十四条","txt":"各级商务、发展改革、工业和信息化、公安、生态环境、交通运输、市场监管等部门及其工作人员应当按照《管理办法》和本细则规定履行职责。违反相关规定的，按照《管理办法》第二十五条规定追究责任。任何单位和个人有权对相关部门及其工作人员的违法违规行为进行举报。"},{"i":55,"n":"第五十五条","txt":"省级商务主管部门可以结合本地实际情况制定本细则的实施办法，并报商务部备案。"},{"i":56,"n":"第五十六条","txt":"本细则实施前已经取得报废机动车回收资质的企业，应当在本细则实施后两年内按照本细则的要求向省级商务主管部门申请重新进行资质认定。通过资质认定的，换发《资质认定书》；超过两年未通过资质认定的，由原发证部门注销其《资质认定书》。"},{"i":57,"n":"第五十七条","txt":"县级以上地方商务主管部门涉及本细则有关商务执法职责发生调整的，有关商务执法职责由本级人民政府确定的承担相关职责的部门实施。"},{"i":58,"n":"第五十八条","txt":"本细则由商务部会同发展改革委、工业和信息化部、公安部、生态环境部、交通运输部、市场监管总局负责解释。"},{"i":59,"n":"第五十九条","txt":"本细则自2020年9月1日起施行。"}],"paimaiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范拍卖行为，维护拍卖秩序，推动拍卖业的对外开放，促进拍卖业健康发展，根据《中华人民共和国拍卖法》（以下简称《拍卖法》）和有关外商投资的法律、行政法规和规章，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内拍卖企业进行的拍卖活动。 各种经营性拍卖活动，应当由依法取得从事拍卖业务许可的企业进行。"},{"i":3,"n":"第三条","txt":"本办法所称拍卖企业，是指依法在中国境内设立的从事经营性拍卖活动的有限责任公司或者股份有限公司。"},{"i":4,"n":"第四条","txt":"商务部是拍卖行业主管部门，对全国拍卖业实施监督管理。 省、自治区、直辖市人民政府（以下简称省级）和设区的市人民政府(以下简称市级)商务主管部门对本行政区域内的拍卖业实施监督管理。"},{"i":5,"n":"第五条","txt":"拍卖企业从事拍卖活动，应当遵守《拍卖法》及其他有关法律、行政法规、规章的规定，遵循公开、公平、公正、诚实信用的原则。"},{"i":6,"n":"第六条","txt":"申请从事拍卖业务许可的企业的投资者应有良好的信誉，无违反中国法律、行政法规、规章的行为。"},{"i":7,"n":"第七条","txt":"企业申请取得从事拍卖业务的许可，应当具备下列条件： （一）有1百万元人民币以上的注册资本； （二）有自己的名称、组织机构和章程； （三）有固定的办公场所； （四）有至少一名拍卖师； （五）有符合有关法律、行政法规及本办法规定的拍卖业务规则； （六）符合商务主管部门有关拍卖行业发展规划。"},{"i":8,"n":"第八条","txt":"企业申请取得从事拍卖业务的许可，应当提交下列材料： （一）申请书； （二）公司章程、拍卖业务规则； （三）企业法人营业执照副本（复印件）； （四）拟聘任的拍卖师执业资格证书； （五）企业已购买或租用固定办公场所的书面承诺；"},{"i":9,"n":"第九条","txt":"拍卖企业从事文物拍卖的，应当遵循有关文物拍卖的法律、行政法规的规定。 国家行政机关依法没收的物品，充抵税款、罚款的物品、人民法院依法没收的物品，充抵罚金、罚款的物品以及无法返还的追回物品和其他特殊国有资产等标的的拍卖应由具有相应拍卖资格的拍卖企业承担，具体资格条件由省级商务主管部门会同有关部门依据规范管理、择优选用的原则制定，并报商务部备案。"},{"i":10,"n":"第十条","txt":"拍卖企业分公司申请取得从事拍卖业务的许可，应当符合下列条件： （一）符合拍卖业发展规划； （二）有固定的办公场所； （三）经营拍卖业务3年以上，最近2年连续盈利，其上年拍卖成交额超过5千万元人民币；或者上年拍卖成交额超过2亿元人民币。"},{"i":11,"n":"第十一条","txt":"拍卖企业设立分公司，申请人需要提交下列材料: （一）拟设立分公司的申请报告； （二）企业法人营业执照副本（复印件）； （三）最近2年经会计师事务所审计的年度财务会计报表； （四）拟聘任的拍卖师执业资格证书； （五）企业已购买或租用固定办公场所的书面承诺。"},{"i":12,"n":"第十二条","txt":"企业及分公司申请取得从事拍卖业务的许可，按照下列程序办理： 企业及分公司申请取得从事拍卖业务的许可，应当先经企业或分公司所在地市级商务主管部门审查后，报省级商务主管部门核准并颁发拍卖经营批准证书。 省级商务主管部门对企业及分公司申请取得从事拍卖业务的许可可以采取听证方式。 拍卖经营批准证书由省级商务主管部门统一印制。"},{"i":13,"n":"第十三条","txt":"拍卖企业向工商行政管理机关申请变更注册登记项目后，应当报省级商务主管部门核准，并由其换发拍卖经营批准证书。"},{"i":14,"n":"第十四条","txt":"拍卖企业及分公司申请取得从事拍卖业务的许可后连续6个月无正当理由未举办拍卖会或没有营业纳税证明的，由商务主管部门收回拍卖经营批准证书。"},{"i":15,"n":"第十五条","txt":"拍卖企业根据章程规定事由、股东会决议或其他事由解散的；或者因违反法律、行政法规及本办法规定被责令关闭的；或者因不能清偿到期债务，被依法宣告破产的，由有关部门依法注销。"},{"i":16,"n":"第十六条","txt":"国家对拍卖专业技术人员实行执业资格制度，获得拍卖师执业资格证书的人员，经注册后，方可主持拍卖活动。 本办法所称拍卖师是指经全国统一考试合格，取得人事部、商务部联合用印的，由中国拍卖行业协会颁发的《中华人民共和国拍卖师执业资格证书》，并经注册登记的人员。"},{"i":17,"n":"第十七条","txt":"拍卖师只能在一个拍卖企业注册执业且不得以其拍卖师个人身份在其他拍卖企业兼职； 拍卖师不得将《中华人民共和国拍卖师执业资格证书》借予他人或其他单位使用。"},{"i":18,"n":"第十八条","txt":"拍卖师可以变更执业注册单位。拍卖师变更执业注册单位的，应当向中国拍卖行业协会办理注册变更手续。 中国拍卖行业协会应将拍卖师注册登记及变更情况每月定期报商务部备案。"},{"i":19,"n":"第十九条","txt":"下列物品或者财产权利禁止拍卖： （一）法律、法规禁止买卖的； （二）所有权或者处分权有争议，未经司法、行政机关确权的； （三）尚未办结海关手续的海关监管货物。"},{"i":20,"n":"第二十条","txt":"拍卖企业应当依法开展拍卖活动，不得有下列行为： （一）出租、擅自转让拍卖经营权； （二）对拍卖标的进行虚假宣传，给买受人造成经济损失； （三）雇佣未依法注册的拍卖师或其他人员充任拍卖师主持拍卖活动的； （四）采用恶意降低佣金比例或低于拍卖活动成本收取佣金，甚至不收取佣金（义拍除外）或给予委托人回扣等手段进行不正当竞争的； （五）其他违反法律法规的行为。"},{"i":21,"n":"第二十一条","txt":"拍卖企业发现拍卖标的中有公安机关通报协查物品或赃物，应当立即向所在地公安机关报告。"},{"i":22,"n":"第二十二条","txt":"竞买人委托他人代理竞买的，应当出具授权委托书和竞买人、代理人的身份证明复印件。 授权委托书应载明代理人的姓名或者名称、代理事项、代理权限和期间。"},{"i":23,"n":"第二十三条","txt":"拍卖实施前，拍卖企业与委托人应当就拍卖未成交的有关事宜或因委托人中止或终止拍卖所造成损失的赔偿责任等事项达成书面协议。"},{"i":24,"n":"第二十四条","txt":"对委托人送交的拍卖物品，拍卖企业应当由专人负责，妥善保管，建立拍卖品保管、值班和交接班制度，并采取必要的安全防范措施。"},{"i":25,"n":"第二十五条","txt":"拍卖企业举办拍卖活动，应当根据拍卖标的物的属性及拍卖的性质，按照《拍卖法》及相关法律、行政法规规定的日期进行公告。公告应当发布在拍卖标的所在地以及拍卖会举行地商务主管部门指定的发行量较大的报纸或其他有同等影响的媒体。"},{"i":26,"n":"第二十六条","txt":"拍卖企业应当在拍卖会前展示拍卖标的，为竞买人提供查看拍卖标的的条件并向竞买人提供有关资料。 展示时间应不少于2日，鲜活物品或其他不易保存的物品除外。"},{"i":27,"n":"第二十七条","txt":"拍卖企业有权查明或者要求委托人书面说明拍卖标的的来源和瑕疵。 拍卖企业应当向竞买人说明其知道或者应当知道的拍卖标的的瑕疵。"},{"i":28,"n":"第二十八条","txt":"法律、行政法规和规章对拍卖标的受让人有特别规定的，拍卖企业应当将标的拍卖给符合法律、行政法规和规章要求的竞买人。 拍卖标的是依照法律、行政法规和规章规定需要行政许可的经营资格且依法可以转让的，委托人应在拍卖前应当征得行政许可机关的同意。"},{"i":29,"n":"第二十九条","txt":"拍卖企业可以在拍卖会现场设立委托竞买席，并在拍卖会开始时对全体竞买人作出说明。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，应当中止拍卖： （一）没有竞买人参加拍卖的； （二）第三人对拍卖标的所有权或处分权有争议并当场提供有效证明的； （三）委托人在拍卖会前以正当理由书面通知拍卖企业中止拍卖的； （四）发生意外事件致使拍卖活动暂时不能进行的； （五）出现其他依法应当中止的情形的。 中止拍卖由拍卖企业宣布。中止拍卖的事由消失后，应恢复拍卖。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，应当终止拍卖： （一）人民法院、仲裁机构或者有关行政机关认定委托人对拍卖标的无处分权并书面通知拍卖企业的； （二）拍卖标的被认定为赃物的； （三）发生不可抗力或意外事件致使拍卖活动无法进行的； （四）拍卖标的在拍卖前毁损、灭失的； （五）委托人在拍卖会前书面通知拍卖企业终止拍卖的； （六）出现其他依法应当终止的情形的。 终止拍卖由拍卖企业宣布。拍卖终止后，委托人要求继续进行拍卖的，应当重新办理拍卖手续。"},{"i":32,"n":"第三十二条","txt":"外商投资拍卖企业与内资拍卖企业联合在中华人民共和国境内举办拍卖会的，其拍卖标的应符合法律、行政法规及本办法的有关规定。"},{"i":33,"n":"第三十三条","txt":"商务部组织制定有关拍卖行业规章、政策，指导各地制定拍卖行业发展规划，依法建立拍卖业监督核查、行业统计和信用管理制度；负责拍卖行业利用外资的促进与管理；对拍卖行业自律组织进行业务指导。"},{"i":34,"n":"第三十四条","txt":"省级商务主管部门负责制定和实施本地区拍卖行业发展规划，并将规划报商务部备案。 省级商务主管部门应建立本地区拍卖企业和从业人员的监督核查和行业统计及信用管理制度；负责企业和分公司申请取得从事拍卖业务的许可审核；管理与指导本地区的拍卖行业自律组织。 省级商务主管部门应当创造条件，建立与拍卖企业、其他有关行政机关计算机档案系统互联网络，对拍卖经营活动监督检查的情况和处理结果应当予以记录。每年度应当出具对拍卖企业的监督核查意见。对核查不合格的拍卖企业，应当责令限期整改，并将核查情况通报有关部门。"},{"i":35,"n":"第三十五条","txt":"拍卖行业协会依法并根据章程，对拍卖企业和拍卖师进行监督。拍卖行业协会应当制定拍卖行业规范，加强行业自律管理，协调会员企业与政府有关部门及会员企业之间的关系，为会员企业提供服务，维护会员企业的合法权益。 中国拍卖行业协会在商务部的指导下，具体实施全国拍卖企业信用管理制度和组织拍卖师考试、考核和资格认定工作。"},{"i":36,"n":"第三十六条","txt":"未经许可从事经营性拍卖活动的企业，应依照国家有关规定予以取缔。"},{"i":37,"n":"第三十七条","txt":"拍卖师违反本办法第十六条、第十七条规定或有向监管部门隐瞒情况、提供虚假材料等其他违规行为的，省级商务主管部门可将其违规事实及处理建议通告中国拍卖行业协会，中国拍卖行业协会应依照有关规定对违规拍卖师进行处理，并将处理结果在10个工作日内书面抄送拍卖师执业地省级商务主管部门和行业协会。"},{"i":38,"n":"第三十八条","txt":"拍卖企业违反本办法第十九条规定，对买受人造成损失的，拍卖企业应当给予赔偿；属于委托人责任的，拍卖企业有权向委托人追偿。"},{"i":39,"n":"第三十九条","txt":"拍卖企业违反第二十条第（一）项，由省级商务主管部门责令其改正，并处3万元以下罚款。"},{"i":40,"n":"第四十条","txt":"拍卖企业违反本办法第二十条第（三）项的规定，由省级商务主管部门视情节轻重予以警告，并处以非法所得额1倍以上的罚款，但最高不超过3万元；没有非法所得的，处以1万元以下的罚款。造成委托人和买受人损失的，拍卖企业应当依法给予赔偿。"},{"i":41,"n":"第四十一条","txt":"拍卖企业违反本办法第二十条第（二）项、第（四）项规定的，由有关行政机关依法进行处罚。"},{"i":42,"n":"第四十二条","txt":"拍卖企业违反本办法第二十五条、第二十六条规定，拍卖前违规进行公告或展示的，由省级商务主管部门视情节轻重予以警告，责令改正，延期拍卖或处以1万元以下罚款。"},{"i":43,"n":"第四十三条","txt":"拍卖企业、委托人违反本办法第二十七条规定，未说明拍卖标的的瑕疵，给买受人造成损害的，买受人有权要求拍卖企业给予赔偿；属于委托人责任的，拍卖企业有权向委托人追偿。 拍卖企业、委托人在拍卖前声明不能保证拍卖标的真伪或者品质的，不承担瑕疵担保责任（以下简称免责声明）。但是拍卖企业、委托人明确知道或应当知道拍卖标的有瑕疵时，免责声明无效。"},{"i":44,"n":"第四十四条","txt":"拍卖成交后，委托人没有协助买受人依法办理证照变更、产权过户手续，造成买受人或拍卖企业损失的，委托人应当依法给予赔偿。 委托人提出中止或者终止拍卖，给拍卖企业或者竞买人造成损失的，应当依法给予赔偿。"},{"i":45,"n":"第四十五条","txt":"有下列情形之一的，省级商务主管部门或商务部可以撤销有关拍卖企业及分公司从事拍卖业务的许可决定： （一）工作人员滥用职权、玩忽职守作出准予许可决定的； （二）违反《拍卖法》和本办法规定的取得从事拍卖业务的许可条件作出准予许可决定的； （三）超越法定职权作出准予从事拍卖业务的许可决定的。"},{"i":46,"n":"第四十六条","txt":"商务主管部门以及行业协会的工作人员在工作中滥用职权、徇私舞弊、玩忽职守、索贿受贿的，对负有责任的主管人员和直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":47,"n":"第四十七条","txt":"商务主管部门工作人员对在执行公务中获知的有关拍卖企业、委托人、竞买人、买受人要求保密的内容，应当按保密规定为其保密，造成泄密的，按有关规定处理。拍卖企业认为向管理机关报送的材料有保密内容的，应注明“保密”字样并密封。"},{"i":48,"n":"第四十八条","txt":"农产品批发市场、机动车交易市场等商品交易市场引入拍卖方式及利用互联网经营拍卖业务的管理，原则上参照本办法执行，具体办法另行制定。"},{"i":49,"n":"第四十九条","txt":"国有独资拍卖企业应按照国家有关规定进行改制。"},{"i":50,"n":"第五十条","txt":"本办法由商务部负责解释。"},{"i":51,"n":"第五十一条","txt":"本办法自2005年1月1日起施行。"}],"yuanwaiqingnianzhiyuanzhexuanpaiheguanlizanxingband665af":[{"i":1,"n":"第一条","txt":"为规范援外青年志愿者选派和管理工作，促进青年志愿者援外服务工作的健康发展，特制定本办法。"},{"i":2,"n":"第二条","txt":"援外青年志愿者是指利用国家对外援助资金，由专门机构选派到发展中国家，直接为发展中国家当地人民服务的青年志愿人员。"},{"i":3,"n":"第三条","txt":"援外青年志愿者主要被派往对中国友好的发展中国家从事教育、医疗卫生和其他有益于发展中国家公益事业发展的服务。"},{"i":4,"n":"第四条","txt":"援外青年志愿者是国家援外人员的组成部分，以志愿人员身份到发展中国家工作。"},{"i":5,"n":"第五条","txt":"商务部是援外青年志愿者援外服务的主管部门。 受商务部委托，中国青年志愿者协会负责援外青年志愿者的选派和具体管理工作。"},{"i":6,"n":"第六条","txt":"援外青年志愿者应符合以下条件： （一）具有中华人民共和国国籍； （二）年龄一般在20岁至35岁之间，确属援外青年志愿服务工作必需的，年龄可适当放宽； （三）身体健康； （四）一般具有大学本科以上学历； （五）品行端正，无犯罪、记过处分记录； （六）忠于祖国，乐于奉献，热爱志愿服务事业，志愿到发展中国家从事志愿服务工作。"},{"i":7,"n":"第七条","txt":"援外青年志愿者应遵守派遣援外青年志愿者的有关规定，遵守援外人员有关规定，接受中国驻外使领馆的管理；遵守受援方的法律、法规，尊重受援方的风俗习惯及服务单位的各项规章制度。"},{"i":8,"n":"第八条","txt":"商务部负责制定派遣援外青年志愿者年度计划，包括派遣国别、人数、服务岗位、服务时间以及资金预算等内容。"},{"i":9,"n":"第九条","txt":"商务部负责与受援方有关部门商谈、签署合作协议。 中国青年志愿者协会根据合作协议负责组织招募、选定、培训和派遣援外青年志愿者。"},{"i":10,"n":"第十条","txt":"中国驻外使领馆经济商务参赞处（室）负责援外青年志愿者在国外工作期间的管理工作。"},{"i":11,"n":"第十一条","txt":"中国青年志愿者协会可以通过商务部网站、中国志愿服务网、新闻媒体等发布招募启事，面向社会公开招募援外青年志愿者，也可以根据需要有针对性地面向具体地区或单位进行定向招募。"},{"i":12,"n":"第十二条","txt":"中国青年志愿者协会根据公开、公正、公平的原则，按照集中考试、公布成绩和录取等步骤选拔录用援外青年志愿者。援外青年志愿者名单报商务部备案。"},{"i":13,"n":"第十三条","txt":"中国青年志愿者协会应根据国家关于援外青年志愿者的有关规定与援外青年志愿者签订志愿服务合同。"},{"i":14,"n":"第十四条","txt":"援外青年志愿者赴国外服务前，中国青年志愿者协会应对援外青年志愿者进行集中培训，组织培训前，应编制培训方案并报商务部批准后实施。"},{"i":15,"n":"第十五条","txt":"中国青年志愿者协会根据国家关于援外人员派遣的有关规定，负责办理援外青年志愿者的出国手续。"},{"i":16,"n":"第十六条","txt":"援外青年志愿者国外服务期限为6个月至2年，一般应在1年以上。"},{"i":17,"n":"第十七条","txt":"中国青年志愿者协会应对援外青年志愿者在受援方服务期间的表现进行考核，考核应征求中国驻外使领馆经济商务参赞处（室）的意见，考核结束后应将考核结果上报商务部，并通知推荐单位或原工作单位。圆满完成服务任务的援外青年志愿者将获得援外青年志愿者荣誉证书，表现优秀的援外青年志愿者可以被推荐到中国驻外使领馆经济商务参赞处（室）或援外专家组工作。"},{"i":18,"n":"第十八条","txt":"援外青年志愿者相关费用的规定由商务部会同有关部门制定。"},{"i":19,"n":"第十九条","txt":"本办法由商务部负责解释，并自公布之日起30日后施行。"}],"sanzhuangshuiniguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为加快发展散装水泥，节约资源，保护和改善环境，提高经济和社会效益，促进经济与社会可持续发展，根据《中华人民共和国清洁生产促进法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称散装水泥，是指不用包装，直接通过专用装备出厂、运输、储存和使用的水泥。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事水泥生产、经营、运输、使用的单位和个人，适用本办法。"},{"i":4,"n":"第四条","txt":"国务院商务行政主管部门负责全国散装水泥发展和管理的协调工作。国务院财政、建设、铁路、交通、质量技术监督和环境保护等行政主管部门，按照各自的职责，负责散装水泥的有关工作。 县级以上地方人民政府确定的部门负责本行政区域内散装水泥的监督管理工作。县级以上地方人民政府财政、建设、交通、质量技术监督和环境保护等行政主管部门，按照各自的职责，负责本行政区域内散装水泥的有关工作。 各级散装水泥办公室负责本行政区内散装水泥行政管理的具体工作。"},{"i":5,"n":"第五条","txt":"国务院商务行政主管部门会同有关部门制定并发布国家鼓励发展和限期淘汰的散装水泥适用的生产技术、工艺、设备和产品目录。"},{"i":6,"n":"第六条","txt":"袋装水泥生产企业（包括水泥熟料粉磨站，下同）、使用单位应当严格按照财政部、国家经贸委发布的《散装水泥专项资金征收和使用管理办法》（财综〔2002〕23号）的规定缴纳散装水泥专项资金。"},{"i":7,"n":"第七条","txt":"新建、扩建和改建水泥生产企业，应当按散装比例70％以上发放能力的要求进行设计和同步建设，按期投入使用。 新建、扩建和改建水泥生产企业，应当依法进行环境影响评价。"},{"i":8,"n":"第八条","txt":"现有水泥生产和使用单位应当配置散装水泥发放和使用装备，其散装比例和实现期限由各省、自治区、直辖市人民政府散装水泥行政主管部门确定。"},{"i":9,"n":"第九条","txt":"水泥生产企业应当遵守国家生产许可证管理法规规定，取得生产许可证后，方可生产散装水泥。"},{"i":10,"n":"第十条","txt":"水泥生产企业应当按照水泥质量管理规程组织生产，不得生产、销售不合格的散装水泥。"},{"i":11,"n":"第十一条","txt":"散装水泥生产、经营、运输、使用单位和个人，应当执行国家有关计量规定。"},{"i":12,"n":"第十二条","txt":"散装水泥生产、经营、运输、使用单位和个人，应当依照《中华人民共和国统计法》向散装水泥行政主管部门报送有关统计报表。"},{"i":13,"n":"第十三条","txt":"散装水泥生产、经营、使用单位和个人，必须采取措施，确保生产、装卸、运输、储存、使用的设施和场所符合安全和环境保护的要求。"},{"i":14,"n":"第十四条","txt":"县级以上地方人民政府有关部门应当鼓励发展预拌混凝土和预拌砂浆，根据实际情况限期禁止城市市区现场搅拌混凝土，具体规定由国务院商务行政主管部门会同国务院建设行政主管部门制定。"},{"i":15,"n":"第十五条","txt":"预拌混凝土、预拌砂浆生产企业必须全部使用散装水泥。水泥制品生产企业也应当积极使用散装水泥。"},{"i":16,"n":"第十六条","txt":"散装水泥生产、经营、使用单位和铁路运输部门应当加强协调配合，做好散装水泥专用车调度与管理工作，提高车辆运输效率。"},{"i":17,"n":"第十七条","txt":"国家鼓励和促进散装水泥发展。县级以上地方人民政府有关部门应当对发展散装水泥事业做出显著贡献的单位及个人给予表彰和鼓励。"},{"i":18,"n":"第十八条","txt":"违反本办法第六条规定，不及时足额缴纳散装水泥专项资金的，由有关部门按照《散装水泥专项资金征收和使用管理办法》第四章的有关规定处罚。"},{"i":19,"n":"第十九条","txt":"违反本办法第十条、第十一条、第十二条、第十三条规定的，由有关部门分别按照《中华人民共和国质量法》、《中华人民共和国计量法》、《中华人民共和国统计法》、《中华人民共和国安全生产法》、《中华人民共和国环境保护法》等有关法律法规处罚。"},{"i":20,"n":"第二十条","txt":"违反本办法第十四条规定，擅自现场搅拌混凝土的，由有关部门依据有关规定处罚。"},{"i":21,"n":"第二十一条","txt":"违反本办法第十五条规定，不使用或不完全使用散装水泥的预拌混凝土、预拌砂浆生产企业，由建设行政主管部门责令整改，并可处以每立方米混凝土100元或者每吨袋装水泥300元的罚款，但罚款总额不超过30000元。"},{"i":22,"n":"第二十二条","txt":"各级散装水泥行政管理部门应当协同有关行政主管部门做好发展散装水泥和预拌混凝土的行政执法与处罚工作。"},{"i":23,"n":"第二十三条","txt":"本办法所称的预拌（亦称商品）混凝土（砂浆），是指由水泥、集料、水以及根据需要掺入的外加剂和掺合料等按一定成份，经集中计量拌制后通过运输车运至使用地点的混凝土（砂浆）拌合物。 本办法所称散装水泥发放能力，是指散装水泥库容量占水泥仓库容量的比例。"},{"i":24,"n":"第二十四条","txt":"本办法由商务部会同有关部门负责解释。"},{"i":25,"n":"第二十五条","txt":"本办法自发布之日起施行。"}],"sanzhuangshuiniguanlibanfa":[{"i":1,"n":"第一条","txt":"为加快发展散装水泥，节约资源，保护和改善环境，提高经济和社会效益，促进经济与社会可持续发展，根据《中华人民共和国清洁生产促进法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称散装水泥，是指不用包装，直接通过专用装备出厂、运输、储存和使用的水泥。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内从事水泥生产、经营、运输、使用的单位和个人，适用本办法。"},{"i":4,"n":"第四条","txt":"国务院商务行政主管部门负责全国散装水泥发展和管理的协调工作。国务院财政、建设、铁路、交通、质量技术监督和环境保护等行政主管部门，按照各自的职责，负责散装水泥的有关工作。 县级以上地方人民政府确定的部门负责本行政区域内散装水泥的监督管理工作。县级以上地方人民政府财政、建设、交通、质量技术监督和环境保护等行政主管部门，按照各自的职责，负责本行政区域内散装水泥的有关工作。 各级散装水泥办公室负责本行政区内散装水泥行政管理的具体工作。"},{"i":5,"n":"第五条","txt":"国务院商务行政主管部门会同有关部门制定并发布国家鼓励发展和限期淘汰的散装水泥适用的生产技术、工艺、设备和产品目录。"},{"i":6,"n":"第六条","txt":"袋装水泥生产企业（包括水泥熟料粉磨站，下同）、使用单位应当严格按照财政部、国家经贸委发布的《散装水泥专项资金征收和使用管理办法》（财综[2002]23号）的规定缴纳散装水泥专项资金。"},{"i":7,"n":"第七条","txt":"新建、扩建和改建水泥生产企业，应当按散装比例70％以上发放能力的要求进行设计和同步建设，按期投入使用。 新建、扩建和改建水泥生产企业，应当依法进行环境影响评价。"},{"i":8,"n":"第八条","txt":"现有水泥生产和使用单位应当配置散装水泥发放和使用装备，其散装比例和实现期限由各省、自治区、直辖市人民政府散装水泥行政主管部门确定。"},{"i":9,"n":"第九条","txt":"水泥生产企业应当遵守国家生产许可证管理法规规定，取得生产许可证后，方可生产散装水泥。"},{"i":10,"n":"第十条","txt":"水泥生产企业应当按照水泥质量管理规程组织生产，不得生产、销售不合格的散装水泥。"},{"i":11,"n":"第十一条","txt":"散装水泥生产、经营、运输、使用单位和个人，应当执行国家有关计量规定。"},{"i":12,"n":"第十二条","txt":"散装水泥生产、经营、运输、使用单位和个人，应当依照《中华人民共和国统计法》向散装水泥行政主管部门报送有关统计报表。"},{"i":13,"n":"第十三条","txt":"散装水泥生产、经营、使用单位和个人，必须采取措施，确保生产、装卸、运输、储存、使用的设施和场所符合安全和环境保护的要求。"},{"i":14,"n":"第十四条","txt":"县级以上地方人民政府有关部门应当鼓励发展预拌混凝土和预拌砂浆，根据实际情况限期禁止城市市区现场搅拌混凝土，具体规定由国务院商务行政主管部门会同国务院建设行政主管部门制定。"},{"i":15,"n":"第十五条","txt":"预拌混凝土、预拌砂浆生产企业必须全部使用散装水泥。水泥制品生产企业也应当积极使用散装水泥。"},{"i":16,"n":"第十六条","txt":"散装水泥生产、经营、使用单位和铁路运输部门应当加强协调配合，做好散装水泥专用车调度与管理工作，提高车辆运输效率。"},{"i":17,"n":"第十七条","txt":"国家鼓励和促进散装水泥发展。县级以上地方人民政府有关部门应当对发展散装水泥事业做出显著贡献的单位及个人给予表彰和鼓励。"},{"i":18,"n":"第十八条","txt":"违反本办法第六条规定，不及时足额缴纳散装水泥专项资金的，由有关部门按照《散装水泥专项资金征收和使用管理办法》第四章的有关规定处罚。"},{"i":19,"n":"第十九条","txt":"违反本办法第十条、第十一条、第十二条、第十三条规定的，由有关部门分别按照《中华人民共和国质量法》、《中华人民共和国计量法》、《中华人民共和国统计法》、《中华人民共和国安全生产法》、《中华人民共和国环境保护法》等有关法律法规处罚。"},{"i":20,"n":"第二十条","txt":"违反本办法第十四条规定，擅自现场搅拌混凝土的，由有关部门依据有关规定处罚。"},{"i":21,"n":"第二十一条","txt":"违反本办法第十五条规定，不使用或不完全使用散装水泥的预拌混凝土、预拌砂浆生产企业，由建设行政主管部门责令整改，并可处以每立方米混凝土100元或者每吨袋装水泥300元的罚款，但罚款总额不超过30000元。"},{"i":22,"n":"第二十二条","txt":"各级散装水泥行政管理部门应当协同有关行政主管部门做好发展散装水泥和预拌混凝土的行政执法与处罚工作。"},{"i":23,"n":"第二十三条","txt":"本办法所称的预拌（亦称商品）混凝土（砂浆），是指由水泥、集料、水以及根据需要掺入的外加剂和掺合料等按一定成份，经集中计量拌制后通过运输车运至使用地点的混凝土（砂浆）拌合物。 本办法所称散装水泥发放能力，是指散装水泥库容量占水泥仓库容量的比例。"},{"i":24,"n":"第二十四条","txt":"本办法由商务部会同有关部门负责解释。"},{"i":25,"n":"第二十五条","txt":"本办法自发布之日起施行。"}],"jiudianqidianzichanpinliutongguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对旧电器电子产品流通的管理，促进资源综合利用，保护环境，根据《中华人民共和国循环经济促进法》、《废弃电器电子产品回收处理管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称旧电器电子产品，是指已进入消费领域，仍保持全部或者部分原有使用价值的电器电子产品。包括制冷空调器具、清洁器具、厨房器具、通风器具、取暖熨烫器具、个人护理器具、保健器具、娱乐器具等电器产品和音像娱乐类、信息技术类等电子产品。 本办法所称旧电器电子产品经营者（以下简称经营者）是指从事旧电器电子产品收购或销售活动的法人、其他经济组织和个体工商户。"},{"i":3,"n":"第三条","txt":"本办法所称旧电器电子产品流通，是指经营者收购和销售旧电器电子产品的活动。"},{"i":4,"n":"第四条","txt":"经营者应当依照法律、法规和有关标准从事经营活动，遵循诚实、守信、公平、公开的原则。"},{"i":5,"n":"第五条","txt":"商务部负责旧电器电子产品流通的行业管理工作，负责制定行业发展规划、政策。 县级以上地方商务主管部门负责本行政区域内旧电器电子产品流通的行业管理工作。"},{"i":6,"n":"第六条","txt":"相关行业协会依照章程规定，积极为经营者服务，组织专业技能培训，完善旧电器电子产品档案信息系统，建立企业、从业人员诚信经营档案，发挥行业自律作用。"},{"i":7,"n":"第七条","txt":"经营者收购旧电器电子产品时应当对收购产品进行登记。登记信息应包括旧电器电子产品的品名、商标、型号、出售人原始购买凭证或者出售人身份信息等。"},{"i":8,"n":"第八条","txt":"经营者应当建立旧电器电子产品档案资料。档案资料应当包括产品的收购登记信息，质量性能状况、主要部件的维修、翻新情况和后配件的商标、生产者信息等情况。"},{"i":9,"n":"第九条","txt":"经营者不得将在流通过程中获得的机关、企（事）业单位及个人信息用于与旧电器电子产品流通活动无关的领域。旧电器电子产品涉及商业秘密、个人隐私的，出售人应当在出售前妥善处置相关信息，经营者收购上述产品前应作出提示。 退出使用的涉密旧电器电子产品的流通活动应当符合《保守国家秘密法》和国家有关保密规定。"},{"i":10,"n":"第十条","txt":"禁止经营者收购下列旧电器电子产品： （一）依法查封、扣押的； （二）明知是通过盗窃、抢劫、诈骗、走私或其他违法犯罪手段获得的； （三）不能说明合法来源的； （四）其他法律、行政法规禁止收购的。"},{"i":11,"n":"第十一条","txt":"待售的旧电器电子产品应在显著位置标识为旧货。"},{"i":12,"n":"第十二条","txt":"经营者销售旧电器电子产品时，应当向购买者明示产品质量性能状况、主要部件维修、翻新等有关情况。严禁经营者以翻新产品冒充新产品出售。"},{"i":13,"n":"第十三条","txt":"经营者应当向购买者出具销售凭证或发票，并应当提供不少于3个月的免费包修服务，交易双方另有约定的除外。旧电器电子产品仍在三包有效期内的，经营者应依法履行三包责任。 经营者应当设立销售台账，对销售情况进行如实、准确记录。"},{"i":14,"n":"第十四条","txt":"禁止经营者销售下列旧电器电子产品： （一）丧失全部使用功能或达到国家强制报废条件的； （二）不符合保障人体健康和人身、财产安全等强制性标准要求的； （三）其他法律、行政法规禁止销售的。"},{"i":15,"n":"第十五条","txt":"旧电器电子产品市场应当建立旧电器电子经营者档案，如实记录市场内经营者身份信息和信用信息。"},{"i":16,"n":"第十六条","txt":"国家鼓励旧电器电子产品市场建立信息管理系统，及时统计经营者收购和销售旧电器电子产品相关信息，包括销售产品品名、商标、型号、数量、单价、经销商等内容。"},{"i":17,"n":"第十七条","txt":"县级以上地方商务主管部门应当通过制定行业发展规划、促进政策和综合协调等方式，规范旧电器电子产品流通秩序，促进行业发展。"},{"i":18,"n":"第十八条","txt":"县级以上地方商务主管部门应当根据本地实际，建立定期检查及不定期抽查制度，及时发现和处理有关问题。经营者和旧电器电子产品市场应配合商务主管部门的监督检查，如实提供信息和材料。 县级以上地方商务主管部门应当组织本行政区域内的行业统计工作，经营者应按照商务主管部门要求及时报送相关信息和数据。"},{"i":19,"n":"第十九条","txt":"经营者违反本办法第七条、第八条、第十五条规定的，由县级以上地方商务主管部门责令改正；逾期不改正的，可处二千元以上一万元以下罚款。"},{"i":20,"n":"第二十条","txt":"经营者违反本办法第九条、第十一条、第十二条、第十三条、第十八条规定的，由法律、行政法规规定的有关部门依法处理；法律法规未作规定的，由县级以上地方商务主管部门责令改正；逾期不改正的，可处二千元以上一万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"经营者违反本办法第十条、第十四条规定的，由法律、行政法规规定的有关部门依法处理；法律法规未作规定的，由县级以上地方商务主管部门责令改正；逾期不改正的，可处一万元以上三万元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"通过互联网开展旧电器电子产品收购和销售活动的，参照本办法执行。"},{"i":23,"n":"第二十三条","txt":"本办法自2013年5月1日起施行。"}],"jiuhuoliutongguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对旧货流通的管理，维护旧货流通秩序，规范旧货交易行为，培育和发展旧货流通产业，保护交易当事人的合法权益，制定本办法。"},{"i":2,"n":"第二条","txt":"各类旧货市场、经营旧货的企业和个体工商户，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称旧货，是指已进入生产消费和生活消费领域，处于储备、使用和闲置状态，保持部分或者全部原有使用价值的物品。 本办法所称旧货市场，是指买卖双方进行公开的、经常性或者定期性的旧货交易活动，具有信息、评估、结算、加工翻新、保管、运输等配套服务功能的场所。"},{"i":4,"n":"第四条","txt":"旧货市场按其业务活动范围，可分为全国性旧货市场和地方性旧货市场。 全国性旧货市场是指跨省（自治区、直辖市）招商、经营的旧货市场。 地方性旧货市场是指在省（自治区、直辖市）内招商、经营的旧货市场。"},{"i":5,"n":"第五条","txt":"旧货流通坚持以公有制为主体，多种所有制经济共同发展的方针。 旧货流通应当统筹规划、合理布局、稳步发展，起步阶段先进行试点，取得经验后逐步推开。 旧货交易活动应当遵循自愿、公平、诚实、信用的原则。"},{"i":6,"n":"第六条","txt":"国务院商品流通主管部门是旧货业的行业主管部门。 县以上地方人民政府商品流通主管部门负责本行政区域旧货业的行业管理。 各级公安机关对旧货流通行业实施特种行业管理。"},{"i":7,"n":"第七条","txt":"旧货行业协会是依法成立的社会团体法人，是旧货行业的自律性组织，协助各级人民政府商品流通主管部门开展行业管理。"},{"i":8,"n":"第八条","txt":"设立旧货企业应当具备下列条件： （一）有适应业务需要的注册资金； （二）有与业务活动范围及经营规模相适应的专职执业人员和经营管理人员； （三）有固定的经营场所、必要的营业设施和自动化管理设备； （四）法定代表人无故意犯罪记录； （五）有组织章程、交易规则、治安保卫制度和经营管理制度； （六）符合法律、行政法规规定的其他条件。"},{"i":9,"n":"第九条","txt":"设立旧货连锁店除了应当具备本办法第八条规定的条件外，还应当具备连锁经营的基本条件。 旧货连锁店，是指经营旧货、使用统一商号的若干门店，在同一总部的管理下，采取统一管理经营模式，或者授予特许权等方式，实现规模效益的经营组织形式。"},{"i":10,"n":"第十条","txt":"设立旧货市场应当具备下列条件： （一）有与经营规模相适应的专职执业人员、经营管理人员及资金、场地、配套服务设施和自动化管理设备； （二）有组织章程、交易规则、治安保卫制度和经营管理制度； （三）符合国家和地方的统一规划与布局； （四）符合法律、行政法规规定的其他条件。"},{"i":11,"n":"第十一条","txt":"开办跨省、自治区、直辖市经营的旧货企业和旧货连锁店以及跨省、自治区、直辖市设立分支机构，需经企业总部、分支机构所在地省级人民政府商品流通主管部门同意后，报国务院商品流通主管部门批准。"},{"i":12,"n":"第十二条","txt":"开办在省、自治区、直辖市以及在市（地）和市（地）所属县（市）内经营的旧货企业，按其业务活动范围不同由当地市（地）和省级人民政府商品流通主管部门批准。"},{"i":13,"n":"第十三条","txt":"建立全国性旧货市场需经当地省级（含计划单列市）人民政府商品流通主管部门审核，报国务院商品流通主管部门批准。"},{"i":14,"n":"第十四条","txt":"建立地方性旧货市场须经当地省级（含计划单列市）人民政府商品流通主管部门批准，并报国务院商品流通主管部门备案。"},{"i":15,"n":"第十五条","txt":"中央部门的直属企业设立旧货市场，需经企业主管部门同意，并经当地省级（含计划单列市）人民政府商品流通主管部门审核后，报国务院商品流通主管部门批准。"},{"i":16,"n":"第十六条","txt":"报请审批设立旧货企业，应当提交下列材料： （一）申请报告； （二）可行性研究报告； （三）组织章程、交易规则、治安保卫制度和经营管理制度； （四）资金信用证明、经营场所使用证明及营业设施情况； （五）法定代表人和专职执业人员的姓名、职务和身份证明、执业资格证明。 报请审批设立旧货连锁店，除了前款规定提交的材料外，还需提交具有若干个门店的证明和总部关于设立全资及控股收购、加工翻新中心、门店的决定，或者总部与参股及无资产联系门店签订的连锁经营合同。"},{"i":17,"n":"第十七条","txt":"报请审批设立旧货市场，除本办法第十六条第一、二款规定提交的材料外，还需提交发起单位营业执照副本有效复印件和市场领导、管理机构组成方案以及市场交易规则。"},{"i":18,"n":"第十八条","txt":"商品流通主管部门接到申请报告及有关材料后，应当在30日内以书面形式作出答复；对批准设立的旧货企业颁发《旧货经营资格证书》，对批准设立的旧货市场颁发《旧货市场批准证书》。 《旧货经营资格证书》和《旧货市场批准证书》由国务院商品流通主管部门统一印制。"},{"i":19,"n":"第十九条","txt":"经批准设立的旧货企业和旧货市场，申请者应当持批准文件和证书到当地公安机关办理特种行业登记手续后，持商品流通主管部门和公安机关的批准手续，到同级工商行政管理部门办理登记手续，领取营业执照。"},{"i":20,"n":"第二十条","txt":"旧货企业以及其分支机构登记按照《中华人民共和国企业法人登记管理条例》和《中华人民共和国公司登记管理条例》的规定办理；旧货连锁店登记按照国家工商行政管理局、国内贸易部《关于连锁店登记管理有关问题的通知》的规定办理；旧货市场登记按照国家工商行政管理局《商品经营市场登记管理办法》的规定办理。"},{"i":21,"n":"第二十一条","txt":"经营旧货的个体工商业户直接到所在地县级人民政府公安机关办理特种行业登记手续后，持公安机关的批准文件，到同级工商行政管理部门办理登记手续，领取营业执照。"},{"i":22,"n":"第二十二条","txt":"变更名称、法定代表人、住所、注册资金及修改章程等重大事项，应当自变更决定作出之日起15日内，报原审批机关批准，依照有关规定向公安机关、工商管理部门办理变更手续。"},{"i":23,"n":"第二十三条","txt":"旧货企业、旧货连锁店和旧货市场因停办或者破产而经营终止，应当自终止决议或者决定作出之日起30日内，向原审批机关提出书面申请，经审批后，清理债权债务，并依照有关规定到公安机关、工商管理部门办理注销登记手续。"},{"i":24,"n":"第二十四条","txt":"旧货经营者可按照旧货的分类，实行综合性或者专业化经营。"},{"i":25,"n":"第二十五条","txt":"旧货企业可以采用购销、代理（寄售、代购、代销）、租赁、易货或者与生产、流通企业联合收旧卖新等方式开展业务，也可以对旧货进行加工修理、改制翻新和二次包装。"},{"i":26,"n":"第二十六条","txt":"旧货市场可以对外招商、开展自营、组织民间交易和捐赠，可以提供鉴定、评估、保管、储存、运输、修理、翻新、包装、信息、咨询及代社会福利机构处理受赠物品等配套服务。"},{"i":27,"n":"第二十七条","txt":"下列物品不得作为旧货经营： （一）赃物、走私物品、来历不明物品及抵押中的物品，或者有赃物、走私嫌疑的物品； （二）严重损坏且无法修复的物品； （三）法律、行政法规明令禁止经营和特许经营的其他物品。"},{"i":28,"n":"第二十八条","txt":"经营国家文物监管物品，必须经所在地文物行政管理部门审查批准。"},{"i":29,"n":"第二十九条","txt":"旧货经营者和旧货市场开展旧货经营、加工翻新等业务活动，应当遵守国家环境保护法律、行政法规的规定。"},{"i":30,"n":"第三十条","txt":"旧货经营者开展定时定点收购、电话预约上门收购等流动性收购业务，其业务人员和旧货企业的委托收购人员应当经过培训取得上岗执业资格，并佩戴统一标识。"},{"i":31,"n":"第三十一条","txt":"旧货经营者应当对收购和受他人委托代销、寄卖的旧货进行查验。对价值超过100元的旧货应当详细记录其基本特征、来源和去向。"},{"i":32,"n":"第三十二条","txt":"旧货经营者应当登记出售、寄卖及受他人委托出售、寄卖旧货的单位名称和个人的居民身份证；对委托处理旧货的单位和个人，还应当严格查验委托单位的授权委托书及委托人的居民身份证。"},{"i":33,"n":"第三十三条","txt":"旧货经营者接受委托代理销售或者代为保管旧货的，应当建立严格的物品交接、保管及偿付制度，明确有关责任，避免发生纠纷。"},{"i":34,"n":"第三十四条","txt":"旧货经营者应当对销售的旧日用品、旧家具进行必要的清洗、除尘和整理，保证所售物品清洁、卫生和安全。销售旧服装必须按卫生部门有关标准进行严格消毒。"},{"i":35,"n":"第三十五条","txt":"旧货经营者出售旧办公设备、旧大件家用电器（不含拆件商品），应当进行必要的检修，出具有关证明。保修期不得少于3个月。"},{"i":36,"n":"第三十六条","txt":"同时开展经销、寄售、代理、租赁等服务业务的旧货企业以及兼营新货的旧货企业，应当分别核算营业额，分别申报纳税。"},{"i":37,"n":"第三十七条","txt":"旧货市场、旧货经营者发现可疑人员、可疑物品及公安机关要求协查的物品、走私物品，有义务及时向当地公安机关报告，不得隐瞒包庇。"},{"i":38,"n":"第三十八条","txt":"公安机关对赃物、走私物品或者有赃物、走私嫌疑的物品，应当及时予以扣留，并开具收据。经查明不是赃物、走私物品的，应当及时退还；确属赃物、走私物品的，依照国家有关规定处理。"},{"i":39,"n":"第三十九条","txt":"旧货交易实行归行纳市，经营者必须在旧货市场或者工商行政管理部门指定的交易场所销售旧货。"},{"i":40,"n":"第四十条","txt":"旧货市场应当建立健全内部管理制度及经营者档案，其管理人员有权监督旧货经营者的经营行为，对其经营劣绩作如实记载，并按有关章程、细则对违反规定的经营者实行警告或者提请原批准部门取消其从业资格。"},{"i":41,"n":"第四十一条","txt":"旧货市场应当建立相应的结算系统，旧货成交后由市场委派的专职人员开具销售货款票。销售货款票应当包括旧货品名、数量、单价、货款总额、供货人、买货人等项内容。"},{"i":42,"n":"第四十二条","txt":"旧货成交后，需要依法办理证照变更的，应当持购买发票到有关行政管理部门办理手续。"},{"i":43,"n":"第四十三条","txt":"未取得旧货经营资格的单位和个人、或者被取消旧货经营资格未满五年的旧货企业和个人，不得从事旧货经营业务。"},{"i":44,"n":"第四十四条","txt":"跨省运输旧货，凭国务院商品流通主管部门及其授权的省、自治区、直辖市商品流通主管部门出具统一的准运证明和有效票据，公安机关检查后予以放行。"},{"i":45,"n":"第四十五条","txt":"旧货经营网点拆迁需征求所在地县级以上人民政府商品流通主管部门意见。同意拆迁的，要按有关规定在条件相当的地点予以补建。"},{"i":46,"n":"第四十六条","txt":"组织跨省、自治区、直辖市的旧货交易会，需经省、自治区、直辖市人民政府商品流通主管部门审查后，报国务院商品流通主管部门批准；组织地方性旧货交易会，需经省级商品流通主管部门批准。"},{"i":47,"n":"第四十七条","txt":"国务院商品流通主管部门负责旧货行业执业人员的业务培训、考核及执业资格认定工作。 公安机关对旧货行业执业人员进行治安业务培训。"},{"i":48,"n":"第四十八条","txt":"旧货业的主要执业人员（估价师、估价员）必须参加培训。经考核合格的，发给旧货行业执业资格证书，持证上岗。"},{"i":49,"n":"第四十九条","txt":"商品流通主管部门和公安机关对其批准的旧货企业、旧货市场及旧货经营者进行年检（具体年检办法另行规定）。"},{"i":50,"n":"第五十条","txt":"凡有以下情形之一的，认定为年检不合格： （一）取得《旧货市场批准证书》或《旧货经营资格证书》，办理有关证照后，6个月内仍不开展业务的； （二）旧货市场、旧货企业违反本办法第十一条规定，擅自设立分支机构的； （三）违反本办法第二十二条有关规定，不及时办理变更手续的； （四）不按规定及时申报年检材料的； （五）违反本办法第二十七条规定的； （六）旧货市场经营秩序混乱，交易行为严重失控的。"},{"i":51,"n":"第五十一条","txt":"年检不合格的，由公安机关、商品流通主管部门给予通报批评，并限期三个月整改。到期仍不合格的，由商品流通主管部门取消其旧货业经营资格。"},{"i":52,"n":"第五十二条","txt":"违反本办法第三十一条、第三十二条、第三十七条规定的，由公安机关依法查处。对直接负责的主管人员和其他直接责任人员处以200元以上500元以下罚款，并处经营单位3000元以上10000元以下罚款；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"违反本办法第二十八条、第三十四条、第三十五条、第三十六条、第三十九条规定的，由有关部门依法查处。"},{"i":54,"n":"第五十四条","txt":"凡不具备本办法规定条件的旧货经营者和旧货市场，应当自本办法发布之日起3个月内进行整顿，达到本办法规定的条件；逾期未达到本办法规定条件的，由商品流通主管部门、公安机关会同有关部门联合查处，并建议工商行政管理部门吊销其营业执照。"},{"i":55,"n":"第五十五条","txt":"本办法由国务院商品流通行政主管部门负责解释。"},{"i":56,"n":"第五十六条","txt":"本办法自发布之日起施行。"}],"yizhiduhuaxuepinjisuanjijiankonghuaxuepinguanlishif650f6":[],"yizhiduhuaxuepinjinchukouguojihechaguanliguiding":[{"i":1,"n":"第一条","txt":"为防止易制毒化学品流入非法渠道，规范易制毒化学品进出口国际核查工作，根据《易制毒化学品管理条例》制定本规定。"},{"i":2,"n":"第二条","txt":"本规定附件《国际核查易制毒化学品管理目录》（以下简称《目录》）所列易制毒化学品（以下简称核查化学品）的进口、出口实行国际核查管理制度。 根据实际情况，商务部会同公安部可对《目录》进行调整，并以公告形式发布。"},{"i":3,"n":"第三条","txt":"商务部与公安部共同负责全国易制毒化学品进口、出口国际核查管理工作。"},{"i":4,"n":"第四条","txt":"易制毒化学品进出口经营者（以下简称经营者）进口、出口核查化学品，应按照《易制毒化学品进出口管理规定》的有关规定申请许可。"},{"i":5,"n":"第五条","txt":"经营者申请出口核查化学品的，商务部应自收到有关电子数据和纸面材料之日起5日内进行审查，符合规定的，将电子数据转送公安部进行国际核查。"},{"i":6,"n":"第六条","txt":"公安部应自收到商务部转送的电子数据之日起3日内进行审查，符合规定的出口申请，发送进口国家或地区政府主管部门进行核查，并要求10日内答复。 在电子数据审查过程中，商务部可应公安部要求提供相关纸面材料。"},{"i":7,"n":"第七条","txt":"经进口国家或地区政府主管部门确认答复的出口申请，公安部应自收到核查确认答复之日起3日内通知商务部。 进口国家或地区政府主管部门逾期未能答复的，公安部可根据国际惯例、具体产品与进口国别和地区等情况分析提出是否许可出口的建议并书面通知商务部。"},{"i":8,"n":"第八条","txt":"核查化学品样品的出口，数量在100克（含）以下的无需进行国际核查，由商务部按照《易制毒化学品进出口管理规定》办理，并将结果通报公安部。"},{"i":9,"n":"第九条","txt":"经营者进口易制毒化学品，出口国家或者地区政府主管部门向我提出国际核查要求的，公安部应自收到核查要求之日起5日内将相关材料转送商务部进行确认。 商务部应对经营者真实性、资质及进口易制毒化学品用途合理性进行核查。必要时，商务部可委托省级商务主管部门核查。省级商务主管部门应自收到商务部委托核查之日起10日内上报核查结果。商务部应将核查结果及时反馈公安部。 对于需要核查经营者进口易制毒化学品的实际用途、用量的，公安部可委托地方公安机关核查，地方公安机关应自收到公安部委托核查之日起10日内上报核查结果，公安部应及时通报商务部。 公安部应在收到商务部、地方公安机关的核查结果后及时通报出口国家或者地区政府主管部门。"},{"i":10,"n":"第十条","txt":"核查化学品经营者应当加强内部管理，建立健全核查化学品进出口管理档案，至少留存两年备查，并指定专人负责核查化学品进出口相关工作。 核查化学品经营者应当积极配合商务部和公安机关核查。"},{"i":11,"n":"第十一条","txt":"如发现拟进出口的核查化学品有流入非法用途的可能，商务部可撤销已签发的许可证。"},{"i":12,"n":"第十二条","txt":"商务部和公安部可以定期或不定期公布有关国际核查结果及经营者违规情况。"},{"i":13,"n":"第十三条","txt":"核查化学品经营者违反第十条规定的，商务部给予警告，情节严重的，处3万元以下罚款；有违反治安管理行为的，由公安机关依法给予治安管理处罚，构成犯罪的，依法追究刑事责任。"},{"i":14,"n":"第十四条","txt":"本办法自发布之日起30日后施行。原外经贸部、公安部《易制毒化学品进出口国际核查管理规定》（外经贸贸发〔2002〕147号）同时废止。 附件：国际核查易制毒化学品管理目录"}],"yizhiduhuaxuepinjinchukouguanliguiding":[{"i":1,"n":"第一条","txt":"为加强易制毒化学品进出口管理，防止其流入非法制毒渠道，根据《中华人民共和国对外贸易法》和《易制毒化学品管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称的易制毒化学品系指《易制毒化学品管理条例》附表所列可用于制毒的主要原料及化学配剂，目录见本规定附件。"},{"i":3,"n":"第三条","txt":"国家对易制毒化学品进出口实行许可证管理制度。以任何方式进出口易制毒化学品均需申领许可证。"},{"i":4,"n":"第四条","txt":"商务部负责全国易制毒化学品的进出口管理工作。国务院其他部门在各自职责范围内负责有关管理工作。 各省、自治区、直辖市及计划单列市商务主管部门（以下统称省级商务主管部门）负责本地区易制毒化学品进出口管理工作。同时接受商务部委托负责本地区易制毒化学品进出口许可初审及部分易制毒化学品进出口许可工作。 县级以上商务主管部门负责本地区易制毒化学品进出口监督检查工作。"},{"i":5,"n":"第五条","txt":"通过对外交流、交换、合作、赠送、援助、服务等形式进出口易制毒化学品的，应按照本规定申请进（出）口许可证。"},{"i":6,"n":"第六条","txt":"易制毒化学品进出口经营者（以下简称经营者）以加工贸易方式进出口易制毒化学品或加工制成品、副产品为易制毒化学品需内销的，应首先按照本办法规定取得相应的进（出）口许可，并凭进（出）口许可证办理相关手续。"},{"i":7,"n":"第七条","txt":"混合物中含有易制毒化学品的，经营者应折算易制毒化学品数量后按照本规定申请进（出）口许可，含易制毒化学品的复方药品制剂除外。"},{"i":8,"n":"第八条","txt":"易制毒化学品样品的进出口应按照本规定申请进（出）口许可。"},{"i":9,"n":"第九条","txt":"易制毒化学品的过境、转运、通运应当按照本规定申请进（出）口许可。"},{"i":10,"n":"第十条","txt":"易制毒化学品在境外与保税区、出口加工区等海关特殊监管区域、保税场所之间进出的，应当按照本规定申请进（出）口许可证。 易制毒化学品在境内与保税区、出口加工区等海关特殊监管区域、保税场所之间进出的，或者在上述海关特殊监管区域、保税场所之间进出的，无须申请进（出）口许可证。"},{"i":11,"n":"第十一条","txt":"经营者在进出口易制毒化学品时，应当如实向海关申报，提交进（出）口许可证，海关凭许可证办理通关验放手续。进口第一类中的药品类易制毒化学品，还应提交食品药品监督管理部门出具的进口药品通关单。"},{"i":12,"n":"第十二条","txt":"进出境人员随身携带《易制毒化学品管理条例》第一类中的药品类易制毒化学品药品制剂和高锰酸钾的，应当以自用且数量合理为限，并接受海关监管。 进出境人员不得随身携带前款规定以外的易制毒化学品。"},{"i":13,"n":"第十三条","txt":"国家对部分易制毒化学品的进出口实行国际核查制度。管理规定另行制定。"},{"i":14,"n":"第十四条","txt":"麻黄素等属于重点监控范围的易制毒化学品，由商务部会同国务院有关部门核定的企业进口、出口。管理办法另行制定。"},{"i":15,"n":"第十五条","txt":"经营者申请进出口易制毒化学品，应通过商务部两用物项和技术进出口管理电子政务平台如实、准确、完整填写《易制毒化学品进（出）口申请表》，并提交电子数据。"},{"i":16,"n":"第十六条","txt":"省级商务主管部门应自收到进出口申请电子数据之日起3日内进行审查，符合填报要求的，网上通知经营者报送书面材料；不符合填报要求的，网上说明理由并退回重新填报。"},{"i":17,"n":"第十七条","txt":"经营者收到报送书面材料的通知后，应向省级商务主管部门提交下列书面材料： （一）经签字并加盖公章的《易制毒化学品进（出）口申请表》原件； （二）对外贸易经营者备案登记表复印件； （三）营业执照副本复印件； （四）易制毒化学品生产、经营、购买许可证或者备案证明； （五）进口或者出口合同（协议）复印件； （六）经办人的身份证明复印件。 申请易制毒化学品出口许可的，还应当提交进口方政府主管部门出具的合法使用易制毒化学品的证明复印件或进口方合法使用的保证文件原件。 对本条规定的材料复印件有疑问时，商务主管部门可要求经营者交验上述有关材料原件。 书面材料不齐全或不符合法定形式的，省级商务主管部门应在收到书面材料之日起5日内告知经营者需要补正的全部内容，逾期不告知的，自收到书面材料之日起即为受理。"},{"i":18,"n":"第十八条","txt":"申请进出口目录第三类中无需国际核查的易制毒化学品的，省级商务主管部门应自收到齐备、合格的书面材料之日起5日内对经营者提交的书面材料和电子数据进行审查，并作出是否许可的决定。 许可的，省级商务主管部门应在上述期限内发放《两用物项和技术进（出）口批复单》，并将电子数据报商务部备案；不予许可的，省级商务主管部门书面通知经营者并说明理由。"},{"i":19,"n":"第十九条","txt":"对于申请进出口目录第一、二类易制毒化学品和目录第三类中需国际核查的易制毒化学品的，省级商务主管部门应自收到齐备、合格的书面材料之日起3日内对申请进行初审。 初审合格后，对于申请进出口无需国际核查的目录第一、二类易制毒化学品的，省级商务主管部门将电子数据转报商务部审查；对于申请进出口需国际核查的易制毒化学品的，省级商务主管部门将书面材料和电子数据转报商务部审查。"},{"i":20,"n":"第二十条","txt":"对于申请进出口目录第一、二类中无需国际核查的易制毒化学品的，商务部应自收到省级商务主管部门上报电子数据之日起8日内进行审查，作出是否许可的决定并通知省级商务主管部门。 商务部依据前款对进出口申请予以许可的，省级商务主管部门应在收到许可决定后2日内发放《两用物项和技术进（出）口批复单》；不予许可的，省级商务主管部门书面通知经营者并说明理由。"},{"i":21,"n":"第二十一条","txt":"对于申请进口需国际核查的易制毒化学品的，商务部应自收到省级商务主管部门上报电子数据和书面材料之日起8日内进行审查，作出是否许可的决定并通知省级商务主管部门。 商务部依据前款对进口申请予以许可的，省级商务主管部门应在收到许可决定后2日内发放《两用物项和技术进口批复单》；不予许可的，省级商务主管部门书面通知经营者并说明理由。 应易制毒化学品出口国家或者地区政府主管部门提出的国际核查要求，商务部可会同公安部对经营者进口易制毒化学品的有关情况进行核查。"},{"i":22,"n":"第二十二条","txt":"对于申请出口需国际核查的易制毒化学品的，商务部应自收到省级商务主管部门上报书面材料和电子数据之日起5日内进行审查，符合规定的，进行国际核查。 商务部应自收到国际核查结果之日起3日内作出是否许可的决定并通知省级商务主管部门。商务部予以许可的，省级商务主管部门应在收到许可决定后2日内发放《两用物项和技术出口批复单》；不予许可的，省级商务主管部门书面通知经营者并说明理由。 国际核查所用时间不计算在许可期限之内。"},{"i":23,"n":"第二十三条","txt":"申请进口第一类中的药品类易制毒化学品的，商务部在作出许可决定之前，应当征得国务院食品药品监督管理部门的同意。 申请出口第一类中的药品类易制毒化学品，需要在取得出口许可证后办理购买许可证的，应当向省级食品药品监督管理部门申请购买许可证。"},{"i":24,"n":"第二十四条","txt":"在易制毒化学品进出口许可审查过程中，商务主管部门可以对申请材料的实质内容进行实地核查。"},{"i":25,"n":"第二十五条","txt":"经营者可通过商务部两用物项和技术进出口管理电子政务平台查询有关申请办理进程及结果。"},{"i":26,"n":"第二十六条","txt":"经营者凭《两用物项和技术进（出）口批复单》依据《两用物项和技术进出口许可证管理办法》有关规定申领两用物项和技术进（出）口许可证。"},{"i":27,"n":"第二十七条","txt":"外商投资企业申请进出口易制毒化学品的，通过外商投资企业进出口管理网络系统申报，如实、准确、完整填写《外商投资企业易制毒化学品进（出）口申请表》,并提交电子数据；手工不经过网络系统申报的，省级商务主管部门须按规范录入上述系统。"},{"i":28,"n":"第二十八条","txt":"省级商务主管部门应自收到进出口申请电子数据之日起3日内进行审查，符合填报要求的，网上通知外商投资企业报送书面材料；不符合填报要求的，网上说明理由并退回重新填报。"},{"i":29,"n":"第二十九条","txt":"外商投资企业收到报送书面材料的通知后，应向省级商务主管部门提交下列书面材料： （一）经签字并加盖公章的《外商投资企业易制毒化学品进（出）口申请表》原件； （二）批准证书复印件； （三）营业执照副本复印件； （四）商务主管部门关于设立该企业的批文及企业合营合同或章程； （五）易制毒化学品生产、经营、购买许可证或者备案证明； （六）进口或者出口合同（协议）复印件； （七）经办人的身份证明复印件。 申请易制毒化学品出口许可的，还应当提交进口方政府主管部门出具的合法使用易制毒化学品的证明或进口方合法使用的保证文件原件。 申请易制毒化学品进口许可的，还需提交申请进口易制毒化学品的报告，包括外商投资企业对监管手段的说明及不得用于制毒的保证函。 对本条规定的材料复印件有疑问时，商务主管部门可要求外商投资企业交验上述有关材料原件。 书面材料不齐全或不符合法定形式的，省级商务主管部门应在收到书面材料之日"},{"i":30,"n":"第三十条","txt":"申请进出口目录第三类中无需国际核查的易制毒化学品的，省级商务主管部门应自收到齐备、合格的书面材料之日起5日内对外商投资企业提交的书面材料和电子数据进行审查，并作出是否许可的决定。 许可的，省级商务主管部门应在上述期限内发放《外商投资企业易制毒化学品进（出）口批复单》，并将电子数据报商务部备案；不予许可的，省级商务主管部门书面通知外商投资企业并说明理由。"},{"i":31,"n":"第三十一条","txt":"对于申请进出口目录第一、二类易制毒化学品和目录第三类中需国际核查的易制毒化学品的，省级商务主管部门应自收到齐备、合格的书面材料之日起3日内对申请进行初审。 初审合格后，对于申请进出口无需国际核查的目录第一、二类易制毒化学品的，省级商务主管部门将电子数据转报商务部审查；对于申请进出口需国际核查的易制毒化学品的，省级商务主管部门将书面材料和电子数据转报商务部审查。"},{"i":32,"n":"第三十二条","txt":"对于申请进口目录第一、二类中无需国际核查的易制毒化学品的，商务部应自收到省级商务主管部门上报电子数据之日起8日内进行审查，作出是否许可的决定并通知省级商务主管部门。 商务部依据前款对进口申请予以许可的，省级商务主管部门应在收到许可决定后2日内发放《外商投资企业易制毒化学品进口批复单》；不予许可的，省级商务主管部门书面通知外商投资企业并说明理由。"},{"i":33,"n":"第三十三条","txt":"对于申请出口第一、二类中无需国际核查的易制毒化学品的，商务部应自收到省级商务主管部门上报电子数据和书面材料之日起10日内进行审查,作出是否许可的决定并通知省级商务主管部门。许可的，商务部应在上述期限内发放《外商投资企业易制毒化学品出口批复单》，省级商务主管部门通知外商投资企业；不予许可的，省级商务主管部门书面通知外商投资企业并说明理由。"},{"i":34,"n":"第三十四条","txt":"对于申请进口需国际核查的易制毒化学品的，商务部应自收到省级商务主管部门上报电子数据和书面材料之日起8日内进行审查，作出是否许可的决定并通知省级商务主管部门。 商务部依据前款对进口申请予以许可的，省级商务主管部门应在收到许可决定后2日内发放《外商投资企业易制毒化学品进口批复单》；不予许可的，省级商务主管部门书面通知外商投资企业并说明理由。 应易制毒化学品出口国家或者地区政府主管部门提出的国际核查要求，商务部可会同公安部对外商投资企业进口易制毒化学品的有关情况进行核查。"},{"i":35,"n":"第三十五条","txt":"对于申请出口需国际核查的易制毒化学品的，商务部应自收到省级商务主管部门上报书面材料和电子数据之日起5日内进行审查，符合规定的，进行国际核查。 商务部应自收到国际核查结果之日起5日内作出是否许可的决定并通知省级商务主管部门。许可的，商务部应在上述期限内发放《外商投资企业易制毒化学品出口批复单》，省级商务主管部门通知外商投资企业；不予许可的，省级商务主管部门书面通知外商投资企业并说明理由。 国际核查所用时间不计算在许可期限之内。"},{"i":36,"n":"第三十六条","txt":"外商投资企业申请进口第一类中的药品类易制毒化学品的，商务部在作出许可决定之前，应当征得国务院食品药品监督管理部门的同意。 外商投资企业申请出口第一类中的药品类易制毒化学品，需要在取得出口许可证后办理购买许可证的，应当向省级食品药品监督管理部门申请购买许可证。"},{"i":37,"n":"第三十七条","txt":"在外商投资企业易制毒化学品进出口许可审查过程中，商务主管部门可以对申请材料的实质内容进行实地核查。"},{"i":38,"n":"第三十八条","txt":"《外商投资企业易制毒化学品进（出）口批复单》须加盖商务主管部门公章。"},{"i":39,"n":"第三十九条","txt":"外商投资企业可通过外商投资企业进出口管理网络系统查询有关申请办理进程及结果。"},{"i":40,"n":"第四十条","txt":"外商投资企业凭《外商投资企业易制毒化学品进（出）口批复单》依据《两用物项和技术进出口许可证管理办法》有关规定申领两用物项和技术进（出）口许可证。"},{"i":41,"n":"第四十一条","txt":"县级以上商务主管部门应当按照本规定和其他有关法律、法规规定，严格履行对本地区易制毒化学品进出口的监督检查职责，依法查处违法行为。"},{"i":42,"n":"第四十二条","txt":"县级以上商务主管部门对经营者进行监督检查时，可以依法查看现场、查阅和复制有关资料、记录有关情况、扣押相关的证据材料和物品；必要时，可以临时查封有关场所。 有关单位和个人应当及时如实提供有关情况和材料、物品，不得拒绝或隐匿。"},{"i":43,"n":"第四十三条","txt":"易制毒化学品在进出口环节发生丢失、被盗、被抢案件，发案单位应当立即报告当地公安机关和当地商务主管部门。接到报案的商务主管部门应当逐级上报，并配合公安机关查处。"},{"i":44,"n":"第四十四条","txt":"经营者应当建立健全易制毒化学品进出口内部管理制度，建立健全易制毒化学品进出口管理档案，至少留存两年备查，并指定专人负责易制毒化学品进出口相关工作。"},{"i":45,"n":"第四十五条","txt":"经营者知道或者应当知道，或者得到商务主管部门通知，拟进出口的易制毒化学品可能流入非法渠道时，应及时终止合同执行，并将情况报告有关商务主管部门。 经营者违反本规定或当拟进出口易制毒化学品存在被用于制毒危险时，商务部或省级商务主管部门可对已经颁发的进（出）口许可证予以撤销。经营者应采取措施停止相关交易。"},{"i":46,"n":"第四十六条","txt":"经营者应当于每年3月31日前向省级商务主管部门和当地公安机关报告本单位上年度易制毒化学品进出口情况，药品类易制毒化学品进出口经营者还须向当地食品药品监督管理部门报告本单位上年度药品类易制毒化学品进出口情况。省级商务主管部门将本行政区域内的易制毒化学品进出口情况汇总后报商务部。 有条件的经营者，可以与商务主管部门建立计算机联网，及时通报有关进出口情况。"},{"i":47,"n":"第四十七条","txt":"未经许可或超出许可范围进出口易制毒化学品的，或者违反本规定第十二条的，由海关依照有关法律、行政法规的规定处理、处罚；构成犯罪的，依法追究刑事责任。"},{"i":48,"n":"第四十八条","txt":"违反本规定，有下列行为之一的，商务部可给予警告、责令限期改正，并处1万元以上5万元以下罚款： （一）经营者未按本规定建立健全内部管理制度； （二）将进出口许可证转借他人使用的； （三）易制毒化学品在进出口环节发生丢失、被盗、被抢后未及时报告，造成严重后果的。"},{"i":49,"n":"第四十九条","txt":"违反本规定第四十五、四十六条规定的，商务部可给予警告、责令限期改正，并处3万元以下罚款。"},{"i":50,"n":"第五十条","txt":"经营者或者个人拒不接受商务主管部门监督检查的，商务部可责令改正，对直接负责的主管人员以及其他直接责任人员给予警告；情节严重的，对单位处1万元以上5万元以下罚款，对直接负责的主管人员以及其他直接责任人员处1000元以上5000元以下罚款。"},{"i":51,"n":"第五十一条","txt":"自相关行政处罚决定生效之日或者刑事处罚判决生效之日起，商务部可在三年内不受理违法行为人提出的易制毒化学品进出口许可申请，或者禁止违法行为人在一年以上三年以下的期限内从事有关的易制毒化学品进出口经营活动。"},{"i":52,"n":"第五十二条","txt":"商务主管部门的工作人员在易制毒化学品进出口管理工作中有应当许可而不许可、不应许可而滥许可，以及其他滥用职权、玩忽职守、徇私舞弊行为的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":53,"n":"第五十三条","txt":"《两用物项和技术进（出）口批复单》、《外商投资企业易制毒化学品进（出）口批复单》由商务部规定式样并监督印制。"},{"i":54,"n":"第五十四条","txt":"《向特定国家（地区）出口易制毒化学品暂行管理规定》中与本办法规定不一致的，从其规定。"},{"i":55,"n":"第五十五条","txt":"本规定自公布之日起30日后起施行。原《易制毒化学品进出口管理规定》（原外经贸部1999年第4号令）、《对外贸易经济合作部关于印发〈外商投资企业易制毒化学品进出口审批原则和审批程序〉的通知》（（1997）外经贸资三函字第197号）同时废止。 附件：易制毒化学品进出口管理目录"}],"youguanhuaxuepinjixiangguanshebeihejishuchukouguana14c6d":[{"i":1,"n":"第一条","txt":"为加强对有关化学品及相关设备和技术的出口管制，维护国家安全和社会公共利益，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称有关化学品及相关设备和技术的出口，是指本办法附件《有关化学品及相关设备和技术出口管制清单》(以下简称《管制清单》)所列的物项和技术的贸易性出口以及对外赠送、展览、科技合作、援助、服务和以其他方式进行的技术转移。"},{"i":3,"n":"第三条","txt":"有关化学品及相关设备和技术的出口应当遵守国家的有关法律、行政法规和本办法的规定，不得损害国家安全和社会公共利益。"},{"i":4,"n":"第四条","txt":"国家对有关化学品及相关设备和技术出口实行严格管理，防止《管制清单》所列物项和技术被用于化学武器目的。"},{"i":5,"n":"第五条","txt":"国家对《管制清单》所列物项和技术的出口实行许可制度。未经许可，任何单位和个人不得出口《管制清单》所列物项和技术。"},{"i":6,"n":"第六条","txt":"有关化学品及相关设备和技术出口的接受方应当保证，不将中国提供的有关化学品及相关设备和技术用于储存、加工、生产、处理化学武器或用于生产化学武器前体化学品；未经中国政府允许，不得将中国提供的有关化学品及相关设备和技术用于申明的最终用途以外的用途或者向申明的最终用户以外的第三方转让。"},{"i":7,"n":"第七条","txt":"从事有关化学品及相关设备和技术出口的经营者，须经对外贸易经济合作部(以下简称外经贸部)登记。未经登记，任何单位或个人不得经营有关化学品及相关设备和技术出口。具体登记办法由外经贸部规定。"},{"i":8,"n":"第八条","txt":"出口《管制清单》所列物项和技术，应当向外经贸部提出申请，填写有关化学品及相关设备和技术出口申请表(以下简称出口申请表)，并提交下列文件： (一)出口经营者从事有关化学品及相关设备和技术出口的经营资格证明； (二)出口经营者的法定代表人、主要经营管理人以及经办人的身份证明； (三)合同或协议的副本； (四)有关化学品及相关设备和技术的技术说明； (五)最终用户和最终用途证明； (六)接受方依照本办法第六条规定提供的保证文书； (七)外经贸部要求提交的其他文件。"},{"i":9,"n":"第九条","txt":"出口经营者应如实填写出口申请表，出口申请表由外经贸部统一印制。"},{"i":10,"n":"第十条","txt":"外经贸部应当自收到出口申请表和本办法第八条规定的文件之日起进行审查，或会同国务院有关部门进行审查，并在45个工作日内作出许可或不许可的决定。"},{"i":11,"n":"第十一条","txt":"对国家安全、社会公共利益或外交政策有重大影响的有关化学品及相关设备和技术出口，外经贸部应当会同有关部门报国务院批准。 报国务院批准的，不受本办法第十条规定时限的限制。"},{"i":12,"n":"第十二条","txt":"有关化学品及相关设备和技术出口申请经审查许可的，由外经贸部颁发有关化学品及相关设备和技术出口许可证件(以下简称出口许可证件)，并书面通知海关。"},{"i":13,"n":"第十三条","txt":"出口许可证件持有人改变原申请出口的有关化学品及相关设备和技术的，应当交回原出口许可证件，并依照本办法的有关规定，重新申请出口许可证件。"},{"i":14,"n":"第十四条","txt":"有关化学品及相关设备和技术出口时，出口经营者应当向海关出具出口许可证件，依照海关规定办理海关手续。"},{"i":15,"n":"第十五条","txt":"接受方违反其依照本办法第六条规定做出的保证，或出现《管制清单》所规定的可被用于化学武器目的的有关化学品及相关设备和技术扩散危险时，外经贸部应当对已经颁发的出口许可证件予以中止或撤销，并书面通知海关。"},{"i":16,"n":"第十六条","txt":"出口经营者知道或应当知道所出口的有关化学品及相关设备和技术将被接受方直接用于化学武器目的或化学武器前体化学品生产目的，无论该物项或技术是否列入《管制清单》，都不应当出口。"},{"i":17,"n":"第十七条","txt":"经国务院批准，外经贸部会同国务院有关部门，可临时决定对《管制清单》以外的特定物项和技术的出口依照本办法实施管制。 前款规定的特定物项和技术的出口，应当依照本办法的规定经过许可。"},{"i":18,"n":"第十八条","txt":"未经许可擅自出口有关化学品及相关设备和技术，或擅自超出许可范围出口有关化学品及相关设备和技术的，依照刑法关于走私罪、非法经营罪、泄露国家秘密罪或其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，区别不同情况，依照海关法的有关规定处罚，或由外经贸部给予警告，处非法所得1倍以上5倍以下的罚款；外经贸部并可以撤销其对外贸易经营许可。"},{"i":19,"n":"第十九条","txt":"伪造、变造、买卖或通过欺骗等其他不正当手段获取有关化学品及相关设备和技术出口许可证件，依照刑法关于非法经营罪或伪造、变造、买卖国家机关公文、证件、印章罪的规定，依法追究刑事责任；尚不够刑事处罚的，依照海关法的有关规定处罚；外经贸部并可以撤销其对外贸易经营许可。"},{"i":20,"n":"第二十条","txt":"对有关化学品及相关设备和技术出口实施管制的国家工作人员，滥用职权、玩忽职守或利用职务上的便利收受、索取他人财物的，依照刑法关于滥用职权罪、玩忽职守罪、受贿罪或其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，依法给予行政处分。"},{"i":21,"n":"第二十一条","txt":"外经贸部可以会同国务院有关部门，根据实际情况对《管制清单》进行调整。"},{"i":22,"n":"第二十二条","txt":"本办法自2002年11月19日起施行。 附件： 有关化学品及相关设备和技术出口管制清单 第一部分 化学品 化学品名称 CAS登记号 1、氟化氢 （7664-39-3） （别名：无水氢氟酸） 2、氟化钾 （7789-23-3） 3、氟化钠 （7681-49-4） 4、硫化钠 （1313-82-2） 5、氟化氢钾 （7789-29-9） 6、氟化氢钠 （1333-83-1） 7、氟化氢氨 （1341-49-7） 8、二异丙胺 （108-18-9） 9、2－二乙氨基乙醇 （100-37-8） （或称N,N－二乙基乙醇胺） 10、2－氯乙醇 （107-07-3） 第二部分 有关化学品生产设备和技术 一、生产设备 说 明 （一）专为民用用途(如水净化、食品加工、纸浆以及造纸加工等)而设计的设备，如其设计特点不适合储存、加工、生产或处理国家实施出口管制的化学品以及控制它们的流动，则无需出口许可。"}],"jidongcheqiangzhibaofeibiaozhunguiding":[{"i":1,"n":"第一条","txt":"为保障道路交通安全、鼓励技术进步、加快建设资源节约型、环境友好型社会，根据《中华人民共和国道路交通安全法》及其实施条例、《中华人民共和国大气污染防治法》、《中华人民共和国噪声污染防治法》，制定本规定。"},{"i":2,"n":"第二条","txt":"根据机动车使用和安全技术、排放检验状况，国家对达到报废标准的机动车实施强制报废。"},{"i":3,"n":"第三条","txt":"商务、公安、环境保护、发展改革等部门依据各自职责，负责报废机动车回收拆解监督管理、机动车强制报废标准执行有关工作。"},{"i":4,"n":"第四条","txt":"已注册机动车有下列情形之一的应当强制报废，其所有人应当将机动车交售给报废机动车回收拆解企业，由报废机动车回收拆解企业按规定进行登记、拆解、销毁等处理，并将报废机动车登记证书、号牌、行驶证交公安机关交通管理部门注销： （一）达到本规定第五条规定使用年限的； （二）经修理和调整仍不符合机动车安全技术国家标准对在用车有关要求的； （三）经修理和调整或者采用控制技术后，向大气排放污染物或者噪声仍不符合国家标准对在用车有关要求的； （四）在检验有效期届满后连续3个机动车检验周期内未取得机动车检验合格标志的。"},{"i":5,"n":"第五条","txt":"各类机动车使用年限分别如下： （一）小、微型出租客运汽车使用8年，中型出租客运汽车使用10年，大型出租客运汽车使用12年； （二）租赁载客汽车使用15年； （三）小型教练载客汽车使用10年，中型教练载客汽车使用12年，大型教练载客汽车使用15年； （四）公交客运汽车使用13年； （五）其他小、微型营运载客汽车使用10年，大、中型营运载客汽车使用15年； （六）专用校车使用15年； （七）大、中型非营运载客汽车（大型轿车除外）使用20年； （八）三轮汽车、装用单缸发动机的低速货车使用9年，装用多缸发动机的低速货车以及微型载货汽车使用12年，危险品运输载货汽车使用10年，其他载货汽车（包括半挂牵引车和全挂牵引车）使用15年； （九）有载货功能的专项作业车使用15年，无载货功能的专项作业车使用30年； （十）全挂车、危险品运输半挂车使用10年，集装箱半挂车20年，其他半挂车使用15年； （十"},{"i":6,"n":"第六条","txt":"变更使用性质或者转移登记的机动车应当按照下列有关要求确定使用年限和报废： （一）营运载客汽车与非营运载客汽车相互转换的，按照营运载客汽车的规定报废，但小、微型非营运载客汽车和大型非营运轿车转为营运载客汽车的，应按照本规定附件1所列公式核算累计使用年限，且不得超过15年； （二）不同类型的营运载客汽车相互转换，按照使用年限较严的规定报废； （三）小、微型出租客运汽车和摩托车需要转出登记所属地省、自治区、直辖市范围的，按照使用年限较严的规定报废； （四）危险品运输载货汽车、半挂车与其他载货汽车、半挂车相互转换的，按照危险品运输载货车、半挂车的规定报废。 距本规定要求使用年限1年以内（含1年）的机动车，不得变更使用性质、转移所有权或者转出登记地所属地市级行政区域。"},{"i":7,"n":"第七条","txt":"国家对达到一定行驶里程的机动车引导报废。 达到下列行驶里程的机动车，其所有人可以将机动车交售给报废机动车回收拆解企业，由报废机动车回收拆解企业按规定进行登记、拆解、销毁等处理，并将报废的机动车登记证书、号牌、行驶证交公安机关交通管理部门注销： （一）小、微型出租客运汽车行驶60万千米，中型出租客运汽车行驶50万千米，大型出租客运汽车行驶60万千米； （二）租赁载客汽车行驶60万千米； （三）小型和中型教练载客汽车行驶50万千米，大型教练载客汽车行驶60万千米； （四）公交客运汽车行驶40万千米； （五）其他小、微型营运载客汽车行驶60万千米，中型营运载客汽车行驶50万千米，大型营运载客汽车行驶80万千米； （六）专用校车行驶40万千米； （七）小、微型非营运载客汽车和大型非营运轿车行驶60万千米，中型非营运载客汽车行驶50万千米，大型非营运载客汽车行驶60万千米； （八）微型载货汽车行"},{"i":8,"n":"第八条","txt":"本规定所称机动车是指上道路行驶的汽车、挂车、摩托车和轮式专用机械车；非营运载客汽车是指个人或者单位不以获取利润为目的的自用载客汽车；危险品运输载货汽车是指专门用于运输剧毒化学品、爆炸品、放射性物品、腐蚀性物品等危险品的车辆；变更使用性质是指使用性质由营运转为非营运或者由非营运转为营运，小、微型出租、租赁、教练等不同类型的营运载客汽车之间的相互转换，以及危险品运输载货汽车转为其他载货汽车。本规定所称检验周期是指《中华人民共和国道路交通安全法实施条例》规定的机动车安全技术检验周期。"},{"i":9,"n":"第九条","txt":"省、自治区、直辖市人民政府有关部门依据本规定第五条制定的小、微型出租客运汽车或者摩托车使用年限标准，应当及时向社会公布，并报国务院商务、公安、环境保护等部门备案。"},{"i":10,"n":"第十条","txt":"上道路行驶拖拉机的报废标准规定另行制定。"},{"i":11,"n":"第十一条","txt":"本规定自2013年5月1日起施行。2013年5月1日前已达到本规定所列报废标准的，应当在2014年4月30日前予以报废。《关于发布<汽车报废标准>的通知》（国经贸经〔1997〕456号）、《关于调整轻型载货汽车报废标准的通知》（国经贸经〔1998〕407号）、《关于调整汽车报废标准若干规定的通知》（国经贸资源〔2000〕1202号）、《关于印发<农用运输车报废标准>的通知》（国经贸资源〔2001〕234号）、《摩托车报废标准暂行规定》（国家经贸委、发展计划委、公安部、环保总局令〔2002〕第33号）同时废止。"}],"jidianchanpinchukouzhaobiaobanfa":[{"i":1,"n":"第一条","txt":"为了鼓励机电产品出口，维护对外贸易的正常秩序，建立平等竞争机制，保障国家的整体利益和外贸企业的合法权益，根据《中华人民共和国对外贸易法》及国务院批准的《出口商品管理暂行办法》，特制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所规定的机电产品出口招标，系指经营招标商品的出口企业通过自主投标并按规定程序取得商品出口数量。"},{"i":3,"n":"第三条","txt":"对外贸易经济合作部（以下简称外经贸部）公布的机电产品出口招标的商品适用本办法。"},{"i":4,"n":"第四条","txt":"机电产品出口招标工作必须遵循“公平、公开、竞争、效益”的原则。"},{"i":5,"n":"第五条","txt":"机电产品出口招标委员会（以下简称招标委员会）由外经贸部、国家机电产品进出口办公室、中国机电产品进出口商会（以下简称机电商会）和中国外商投资企业协会（以下简称外资协会）组成，设主任一人、副主任、委员若干人。招标委员会主任由外经贸部贸管司负责人担任。 招标委员会下设招标办公室。招标办公室设在机电商会有关分会，设主任一人，副主任、成员若干人。招标办公室主任由分会秘书处负责人担任，负责招标管理的日常工作。"},{"i":6,"n":"第六条","txt":"外经贸部制定、发布机电产品出口招标办法，确定实行出口招标商品品种，并负责指导监督招标工作。"},{"i":7,"n":"第七条","txt":"招标委员会的职责是根据本办法管理机电产品出口招标工作： １、审定招标工作方案； ２、审定、发布招标工作的各项规定、通告、公告； ３、根据出口实绩和国际市场需求，确定出口招标总量； ４、领导招标办公室工作，审定招标办公室对投标材料的初审意见，确定中标单位及中标数量并呈报外经贸部； ５、公布中标结果； ６、研究解决出口招标工作中的其它问题。"},{"i":8,"n":"第八条","txt":"招标办公室的职责是根据本办法和招标委员会的决定具体实施各项工作： １、调查研究招标商品市场情况，拟定招标工作方案，报招标委员会审定后实施； ２、统一印制、发放招标商品的各类文件、材料； ３、依据海关统计核定投标企业出口实绩，对投标企业资格进行初审，并报招标委员会核定； ４、开标评标，计算投标企业中标数量，并报招标委员会审定； ５、监督检查中标企业标数使用及同行协议价执行情况； ６、办理转受让事宜。"},{"i":9,"n":"第九条","txt":"招标范围是以各种贸易方式出口的招标商品的品种和数量。具体内容以招标委员会通告为准。"},{"i":10,"n":"第十条","txt":"招标委员会根据具体商品的出口情况，确定每年招标商品的出口数量和招标次数，每次招标事项由招标委员会提前一个月在《国际商报》等新闻媒介上发布“招标通告”，每年第三季度对下一年度招标商品进行招标。"},{"i":11,"n":"第十一条","txt":"招标委员会可以根据国际市场不同情况，限定出口招标的国别地区。"},{"i":12,"n":"第十二条","txt":"凡参加投标的企业必须具备下列条件： １、经外经贸部许可有外贸出口经营权； ２、在工商行政管理机关登记注册； ３、是机电商会所属招标商品分会会员或外资协会会员。"},{"i":13,"n":"第十三条","txt":"各投标企业应根据本企业实际出口能力和产品规格进行投标，不得虚报。投标价格不得低于同行业协议价。"},{"i":14,"n":"第十四条","txt":"参加投标的企业须按照“招标通告”规定填报投标材料。"},{"i":15,"n":"第十五条","txt":"投标材料须密封，并在“招标通告”规定的截标日前以邮寄等方式送达招标办公室（以收到日为准，传真件无效）。 每个企业限投标书一份，标书一经投出不得变更。 投标材料包括： １、投标申请书； ２、投标保证书； ３、机电商会分会会员或外资协会会员证明（复印件）； ４、外经贸部或其授权部门颁发的出口经营权批准文件、或“对外贸易企业审定证书”、或外商投资企业批准证书（复印件）； ５、国家工商行政管理部门核发的法人营业执照（复印件）； ６、商检部门出具的出口产品质量许可证（复印件）； ７、招标委员会规定的其它材料。"},{"i":16,"n":"第十六条","txt":"招标办公室收到投标材料后应立即登记封存。"},{"i":17,"n":"第十七条","txt":"招标办公室在招标委员会监督下，在规定的时间内公开开标，对标书进行初评，包括：１、投标材料的有效性；２、投标资格；３、投标价格（出口单价）。"},{"i":18,"n":"第十八条","txt":"招标办公室在招标委员会监督下根据有效的招标材料公开计算中标数量。中标数量按下列公式计算：１、确定中标企业在招标商品总量中所占比重“Ａ”：该企业上年度出口该项商品总值（量）　　Ａ＝－－－－－－－－－－－－－－－－－该项商品全国出口总值（量）２、确定全国单位招标商品平均创汇金额“Ｂ”和中标企业单位招标商品　　平均创汇金额“Ｘ”：该项商品出口总值Ｂ＝－－－－－－－－－该项商品出口总量　该中标企业上年度出口该项招标商品总值Ｘ＝－－－－－－－－－－－－－－－－－－该中标企业上年度出口该商品总量３、确定该中标企业中标数量“Ｃ”：ＸＣ＝招标总量×Ａ×－Ｂ"},{"i":19,"n":"第十九条","txt":"为了促进形成出口规模经营，招标委员会可规定并事先向投标企业公布最低投标数量，对上年出口实绩不足最低投标数量的企业不予投标和中标；外商投资企业中标数量不超过外经贸部批准的出口规模。"},{"i":20,"n":"第二十条","txt":"招标委员会根据有效投标材料审核、评定中标企业和中标数量，并在《国际商报》等新闻媒介上公告中标企业名单，同时，招标办公室发放《中标登记手册》。"},{"i":21,"n":"第二十一条","txt":"外经贸部将中标企业名单和中标数量下达授权的发证机关。"},{"i":22,"n":"第二十二条","txt":"授权发证机关发放出口许可证的依据：１、外经贸部转发的中标结果；２、招标委员会发放的《中标登记手册》；３、中标企业的有效出口合同。"},{"i":23,"n":"第二十三条","txt":"为了掌握中标数量的使用情况，招标办公室将跟踪检查，并定期向招标委员会报告执行情况。"},{"i":24,"n":"第二十四条","txt":"中标数量可以转让，受让企业应具有投标资格。转受让必须经招标办公室审核并办理手续。中标手续费交予招标办公室。"},{"i":25,"n":"第二十五条","txt":"中标企业须在招标当年９月３０日前向招标办公室申报登记使用不完的中标数量，并于１２月１５日前交回。招标办公室可将企业申报登记和交回的中标数量用于转受让。"},{"i":26,"n":"第二十六条","txt":"中标企业自收到《中标登记手册》后一个月内，按中标金额（中标数量×中标平均价格）的万分之三向招标委员会交纳手续费，手续费按《中标登记手册》的签发日汇率，折成人民币支付。"},{"i":27,"n":"第二十七条","txt":"手续费由招标办公室负责收取并存于其专项帐户上，单列科目，单独管理，用于招标管理工作，不得挪作它用。招标办公室每年向招标委员会报告手续费收支情况。"},{"i":28,"n":"第二十八条","txt":"对违反本办法的行为，招标委员会给予下列处罚：１、有下列行为之一者，取消其当年中标数量，并给予警告：（１）虚报投标材料；（２）擅自转让或变卖中标数量。２、有下列行为之一者，取消其当年中标数量并取消其下一年度投标资格：（１）涉及国外反倾销案而不参加应诉者；（２）实际出口价格低于同行协议价或变相降价者；（３）经有关部门查实侵犯商标权者；（４）不按期交纳中标手续费者。３、获得中标数量的企业不按本办法第二十五条规定申报登记和交回使用不完的中标数量，其比例不足中标数量３０％的，相应扣减其下一年度中标数量，比例达到或超过３０％的，取消其下年度投标资格。　４、中标企业被取消的中标数量由招标委员会报外经贸部备案，并通知有关发证机关停止发证。取消的中标数量可纳入下次招标总量或用于转受让。"},{"i":29,"n":"第二十九条","txt":"招标工作由注册律师进行法律见证，并出具律师见证书。"},{"i":30,"n":"第三十条","txt":"本办法由外经贸部负责解释，自颁布之日起实施。"}],"jidianchanpinguojizhaobiaodailijigoujianduguanliba488b16":[{"i":1,"n":"第一条","txt":"为加强机电产品国际招标代理机构（以下简称招标机构）监督管理，依据《中华人民共和国招标投标法》（以下简称招标投标法）、《中华人民共和国招标投标法实施条例》（以下简称招标投标法实施条例）等法律、行政法规以及国务院对有关部门实施招标投标活动行政监督的职责分工，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于对在中华人民共和国境内从事机电产品国际招标代理业务的招标机构的监督管理。"},{"i":3,"n":"第三条","txt":"招标机构是依法设立、从事机电产品国际招标代理业务并提供相关服务的社会中介组织。 招标机构应当具备从事招标代理业务的营业场所和相应资金；具备能够编制招标文件（中、英文）和组织评标的相应专业力量；拥有一定数量的招标专业人员。"},{"i":4,"n":"第四条","txt":"商务部负责全国招标机构的监督管理工作；负责组织和指导对全国招标机构的监督检查工作；负责建立全国招标机构信用档案，发布招标机构信用信息；负责指导机电产品国际招标投标有关行业协会开展工作。 各省、自治区、直辖市、计划单列市、新疆生产建设兵团、沿海开放城市及经济特区商务主管部门、国务院有关部门机电产品进出口管理机构负责本地区、本部门所属招标机构的监督管理工作；负责在本地区、本行业从事机电产品国际招标代理行为的监督检查工作。 各级机电产品进出口管理机构（以下简称主管部门）及其工作人员应当依法履行职责。"},{"i":5,"n":"第五条","txt":"招标机构从事机电产品国际招标代理业务，应当在中国国际招标网（网址：www.chinabidding.com，以下简称招标网）免费注册，注册前应当在招标网作出诚信承诺；注册时应当在招标网如实填写《机电产品国际招标代理机构注册登记表》（以下简称《注册登记表》，附件1）和《机电产品国际招标专职从业人员名单》（以下简称《人员名单》，附件2）。"},{"i":6,"n":"第六条","txt":"招标机构对《注册登记表》所填写的登记信息的真实性、合法性负责。因招标机构填写信息错误、遗漏、虚假，以及提供虚假证明材料引起的法律责任由其自行承担。"},{"i":7,"n":"第七条","txt":"注册信息发生变更的，招标机构应当在相关信息变更后30日内在招标网修改相关信息。 因合并、分立而续存的招标机构，其注册信息发生变化的，应当依照前款规定办理注册信息变更；因合并、分立而解散的招标机构，应当及时在招标网办理注销；因合并、分立而新设立的招标机构，应当依照本办法在招标网重新注册。"},{"i":8,"n":"第八条","txt":"不再从事机电产品国际招标代理业务的招标机构，应当及时在招标网注销。 招标机构已在工商部门办理注销手续或被吊销营业执照的，自营业执照注销或被吊销之日起，其招标网注册自动失效。"},{"i":9,"n":"第九条","txt":"招标机构应当遵守招标投标法、招标投标法实施条例、机电产品国际招标投标实施办法和本办法的规定；在招标代理活动中，应当依法经营、公平竞争、诚实守信，不得弄虚作假，不得损害国家利益、社会公共利益或者他人合法权益。"},{"i":10,"n":"第十条","txt":"招标机构应当与招标人签订书面委托合同，载明委托事项和代理权限。招标机构应当在招标人委托的范围内开展招标代理业务，不得接受招标人违法的委托内容和要求；不得在所代理的招标项目中投标或者代理投标，也不得为所代理的招标项目的投标人提供咨询。"},{"i":11,"n":"第十一条","txt":"招标机构从事机电产品国际招标代理业务的人员应当为与本机构依法存在劳动合同关系的员工，应当熟练掌握机电产品国际招标相关法律规定和政策。招标机构代理机电产品国际招标项目的负责人应当由招标专业人员担任。"},{"i":12,"n":"第十二条","txt":"招标机构应当受招标人委托依法组织招标投标活动，协助招标人及时对异议作出答复。在招标项目所属主管部门处理投诉期间，招标机构应当按照招标项目所属主管部门要求积极予以配合。 招标机构应当按照规定及时向招标项目所属主管部门报送招标投标相关材料，并在规定的时间内将招标投标情况及其相关数据上传招标网，在招标网上发布、公示或存档的内容应当与相应书面材料一致。 招标机构应当按照有关规定妥善保存招标投标相关资料，并对评标情况和资料严格保密。"},{"i":13,"n":"第十三条","txt":"招标机构应当积极开展招标投标相关法律规定、政策和业务培训，加强行业自律和内部管理。"},{"i":14,"n":"第十四条","txt":"商务部在招标网设立招标机构信息发布栏，公布以下信息： （一）机构信息：招标机构名称、注册地址、企业性质、联系方式、法定代表人姓名、从事机电产品国际招标代理业务时间、人员、场所等； （二）人员信息：机电产品国际招标专职从业人员姓名、学历、专业、职称、英语水平、劳动合同关系、从事机电产品国际招标代理业务时间、学术成果、机电产品国际招标代理主要业绩等； （三）其他信息：招标机构职业教育培训、学术交流成果、参加社会公益活动、纳税额等； （四）业绩记录：招标机构代理项目当年机电产品国际招标中标金额、历史年度机电产品国际招标中标金额、特定行业机电产品国际招标中标金额等； （五）异议和投诉记录：招标机构当年及历史年度代理项目异议数量、异议率、异议结果，以及投诉数量、投诉率和投诉处理结果等； （六）检查结果记录：本办法第十九条　规定的监督检查记录； （七）错误操作记录：招标机构在机电产品国际招标代理过"},{"i":15,"n":"第十五条","txt":"任何单位和个人发现招标机构信息存在不实的，可以在招标网或通过其他书面形式向该招标机构所属主管部门提出，并提供相关证明材料。经核实，招标机构信息确实存在不实的，由招标机构所属主管部门责令限期改正。"},{"i":16,"n":"第十六条","txt":"推动建立机电产品国际招标代理行业诚信自律体系，倡导招标机构签署行业诚信自律公约，承诺依法经营、诚实守信，共同维护公平竞争的招投标市场秩序。"},{"i":17,"n":"第十七条","txt":"招标机构在招标网完成注册登记后，应当向招标机构所属主管部门提交下列材料存档： （一）由招标机构法定代表人签字并加盖单位公章的《注册登记表》原件； （二）企业法人营业执照（复印件）、公司章程（复印件）并加盖单位公章； （三）《人员名单》及相关证明材料（复印件）并加盖单位公章：身份证、劳动合同、学历（或学位）证书、职称证书、英语水平证明、注册前三个月的社会保险缴费凭证等； （四）营业场所和资金证明材料（复印件）并加盖单位公章：房产证明（自有产权的提供房屋产权证书，非自有产权的提供房屋租赁合同和出租方房屋产权证书）、上一年度由会计师事务所出具的审计报告等（设立不满一年的企业可在下一年度补充提交）。 招标机构名称、法定代表人、营业场所发生变更的，应当在相关信息变更后30日内将变更后的由法定代表人签字并加盖单位公章的《注册登记表》及相关证明材料报送招标机构所属主管部门。机电产品国际招标专职从业人"},{"i":18,"n":"第十八条","txt":"主管部门应当加强招标机构在本地区、本行业从事机电产品国际招标代理行为的事中事后监督检查。主管部门开展监督检查工作，可以采取书面抽查、网络监测、实地检查等方式。各主管部门上年度监督检查情况，应当通过招标网于次年1月15日前报商务部。"},{"i":19,"n":"第十九条","txt":"商务部建立随机抽取检查对象、随机选派检查人员的“双随机”抽查机制，在招标网建立招标机构名录库、招标项目库和招标检查人员名录库，根据法律法规规章修订情况和工作实际动态调整随机抽查事项清单，并及时在招标网向社会公布。 实地检查应当采用“双随机”抽查方式。实施实地检查的主管部门从招标机构名录库中随机抽取检查机构，从招标项目库中随机抽取检查项目，从招标检查人员名录库中随机选派检查人员，按照随机抽查事项清单依法实施检查。 主管部门可根据本地区、本行业招标机构和招标项目实际情况，合理确定随机抽查的比例和频次。对所属招标机构的实地检查，年度检查率应当不低于所属招标机构数量的10%。每年实地检查的所属招标项目数量，应当不少于5个或者上一年度所属招标项目数量的1%（两者以高者为准）；上一年度所属招标项目数量低于5个的，应当至少实地检查1个项目。对投诉举报多、错误操作记录多或有严重违法记录等情况的招标机构"},{"i":20,"n":"第二十条","txt":"主管部门应当对招标机构是否存在下列行为依法进行监督： （一）与招标人、投标人串通损害国家利益、社会公共利益或者他人合法权益的； （二）在所代理的招标项目中投标、代理投标或者向该项目投标人提供咨询的； （三）参加受托编制标底项目的投标或者为该项目的投标人编制投标文件、提供咨询的； （四）泄露应当保密的与招标投标活动有关的情况和资料的； （五）与招标人、投标人相互串通、搞虚假招标投标的； （六）在进行招标机构注册登记时填写虚假信息或提供虚假证明材料的； （七）无故废弃随机抽取的评审专家的； （八）不按照规定及时向主管部门报送材料或者向主管部门提供虚假材料的； （九）未在规定的时间内将招标投标情况及其相关数据上传招标网，或者在招标网上发布、公示或存档的内容与招标公告、招标文件、投标文件、评标报告等相应书面内容存在实质性不符的； （十）不按照规定对异议作出答复，或者在投诉处理的过程中未按照主管"},{"i":21,"n":"第二十一条","txt":"主管部门可以责成招标机构自查，可以依法利用其他政府部门作出的检查、核查结果或者专业机构作出的专业结论。"},{"i":22,"n":"第二十二条","txt":"主管部门应当依法履行监管职责，对检查发现的违法行为，要依法处理。 主管部门实施检查不得妨碍被检查机构正常的经营活动，不得收受被检查机构给予的财物或者其他好处。"},{"i":23,"n":"第二十三条","txt":"主管部门应当对本地区、本部门所属招标机构进行培训和指导，组织开展机电产品国际招标法律规定、政策和业务的交流和培训。"},{"i":24,"n":"第二十四条","txt":"招标机构有本办法第二十条　第一项至第十二项所列的行为或者其他违反招标投标法、招标投标法实施条例、机电产品国际招标投标实施办法的行为的，依照招标投标法、招标投标法实施条例、机电产品国际招标投标实施办法的有关规定处罚。"},{"i":25,"n":"第二十五条","txt":"招标机构有本办法第二十条　第十三项至第十五项所列的行为或者其他违反本办法的行为的，责令改正，可以给予警告，并处3万元以下罚款。"},{"i":26,"n":"第二十六条","txt":"招标机构有本办法第二十条　第一项至第四项行为之一，情节严重的，商务部或招标机构所属主管部门可暂停其机电产品国际招标代理业务，并在招标网上公布。 在暂停机电产品国际招标代理业务期间，招标机构不得开展新的机电产品国际招标代理业务；同一单位法定代表人和直接责任人员不得作为法定代表人在招标网另行注册招标机构。"},{"i":27,"n":"第二十七条","txt":"本章规定的行政处罚，由相应的招标机构所属主管部门或招标项目所属主管部门决定。招标投标法、招标投标法实施条例已对实施行政处罚的机关作出规定的除外。"},{"i":28,"n":"第二十八条","txt":"主管部门应当依法履行职责，依法查处违反招标投标法、招标投标法实施条例、机电产品国际招标投标实施办法和本办法规定的行为，依法公告对招标机构当事人违法行为的行政处理决定。"},{"i":29,"n":"第二十九条","txt":"机电产品国际招标投标有关行业协会按照依法制定的章程开展活动，加强行业自律和服务。"},{"i":30,"n":"第三十条","txt":"本办法所称“日”为日历日，期限的最后一日是国家法定节假日的，顺延到节假日后的次日为期限的最后一日。"},{"i":31,"n":"第三十一条","txt":"本办法由商务部负责解释。"},{"i":32,"n":"第三十二条","txt":"本办法自2017年1月1日起施行。《机电产品国际招标机构资格管理办法》（商务部令2012年第3号）同时废止。 附件： 1.机电产品国际招标代理机构注册登记表 2.机电产品国际招标专职从业人员名单"}],"jidianchanpinguojizhaobiaotoubiaoshishibanfa":[{"i":1,"n":"第一条","txt":"为了规范机电产品国际招标投标活动，保护国家利益、社会公共利益和招标投标活动当事人的合法权益，提高经济效益，保证项目质量，根据《中华人民共和国招标投标法》（以下简称招标投标法）、《中华人民共和国招标投标法实施条例》（以下简称招标投标法实施条例）等法律、行政法规以及国务院对有关部门实施招标投标活动行政监督的职责分工，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内进行机电产品国际招标投标活动，适用本办法。 本办法所称机电产品国际招标投标活动，是指中华人民共和国境内的招标人根据采购机电产品的条件和要求，在全球范围内以招标方式邀请潜在投标人参加投标，并按照规定程序从投标人中确定中标人的一种采购行为。 本办法所称机电产品，是指机械设备、电气设备、交通运输工具、电子产品、电器产品、仪器仪表、金属制品等及其零部件、元器件。机电产品的具体范围见附件1。"},{"i":3,"n":"第三条","txt":"机电产品国际招标投标活动应当遵循公开、公平、公正、诚实信用和择优原则。机电产品国际招标投标活动不受地区或者部门的限制。"},{"i":4,"n":"第四条","txt":"商务部负责管理和协调全国机电产品的国际招标投标工作，制定相关规定；根据国家有关规定，负责调整、公布机电产品国际招标范围；负责监督管理全国机电产品国际招标代理机构（以下简称招标机构）；负责利用国际组织和外国政府贷款、援助资金（以下简称国外贷款、援助资金）项目机电产品国际招标投标活动的行政监督；负责组建和管理机电产品国际招标评标专家库；负责建设和管理机电产品国际招标投标电子公共服务和行政监督平台。 各省、自治区、直辖市、计划单列市、新疆生产建设兵团、沿海开放城市及经济特区商务主管部门、国务院有关部门机电产品进出口管理机构负责本地区、本部门的机电产品国际招标投标活动的行政监督和协调；负责本地区、本部门所属招标机构的监督和管理；负责本地区、本部门机电产品国际招标评标专家的日常管理。 各级机电产品进出口管理机构（以下简称主管部门）及其工作人员应当依法履行职责，不得以任何方式非法干涉招标投标活动。"},{"i":5,"n":"第五条","txt":"商务部委托专门网站为机电产品国际招标投标活动提供公共服务和行政监督的平台（以下简称招标网）。机电产品国际招标投标应当在招标网上完成招标项目建档、招标过程文件存档和备案、资格预审公告发布、招标公告发布、评审专家抽取、评标结果公示、异议投诉、中标结果公告等招标投标活动的相关程序，但涉及国家秘密的招标项目除外。 招标网承办单位应当在商务部委托的范围内提供网络服务，应当遵守法律、行政法规以及本办法的规定，不得损害国家利益、社会公共利益和招投标活动当事人的合法权益，不得泄露应当保密的信息，不得拒绝或者拖延办理委托范围内事项，不得利用委托范围内事项向有关当事人收取费用。"},{"i":6,"n":"第六条","txt":"通过招标方式采购原产地为中国关境外的机电产品，属于下列情形的必须进行国际招标： （一）关系社会公共利益、公众安全的基础设施、公用事业等项目中进行国际采购的机电产品； （二）全部或者部分使用国有资金投资项目中进行国际采购的机电产品； （三）全部或者部分使用国家融资项目中进行国际采购的机电产品； （四）使用国外贷款、援助资金项目中进行国际采购的机电产品； （五）政府采购项目中进行国际采购的机电产品； （六）其他依照法律、行政法规的规定需要国际招标采购的机电产品。 已经明确采购产品的原产地在中国关境内的，可以不进行国际招标。必须通过国际招标方式采购的，任何单位和个人不得将前款项目化整为零或者以国内招标等其他任何方式规避国际招标。 商务部制定、调整并公布本条第一项所列项目包含主要产品的国际招标范围。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，可以不进行国际招标： （一）国（境）外赠送或无偿援助的机电产品； （二）采购供生产企业及科研机构研究开发用的样品样机； （三）单项合同估算价在国务院规定的必须进行招标的标准以下的； （四）采购旧机电产品； （五）采购供生产配套、维修用零件、部件； （六）采购供生产企业生产需要的专用模具； （七）根据法律、行政法规的规定，其他不适宜进行国际招标采购的机电产品。 招标人不得为适用前款规定弄虚作假规避招标。"},{"i":8,"n":"第八条","txt":"鼓励采购人采用国际招标方式采购不属于依法必须进行国际招标项目范围内的机电产品。"},{"i":9,"n":"第九条","txt":"招标人应当在所招标项目确立、资金到位或资金来源落实并具备招标所需的技术资料和其他条件后开展国际招标活动。 按照国家有关规定需要履行项目审批、核准手续的依法必须进行招标的项目，其招标范围、招标方式、招标组织形式应当先获得项目审批、核准部门的审批、核准。"},{"i":10,"n":"第十条","txt":"国有资金占控股或者主导地位的依法必须进行机电产品国际招标的项目，应当公开招标；但有下列情形之一的，可以邀请招标： （一）技术复杂、有特殊要求或者受自然环境限制，只有少量潜在投标人可供选择； （二）采用公开招标方式的费用占项目合同金额的比例过大。 有前款第二项所列情形，属于本办法第九条第二款规定的项目，招标人应当在招标前向相应的主管部门提交项目审批、核准部门审批、核准邀请招标方式的文件；其他项目采用邀请招标方式应当由招标人申请相应的主管部门作出认定。"},{"i":11,"n":"第十一条","txt":"招标人采用委托招标的，有权自行选择招标机构为其办理招标事宜。任何单位和个人不得以任何方式为招标人指定招标机构。 招标人自行办理招标事宜的，应当具有与招标项目规模和复杂程度相适应的技术、经济等方面专业人员，具备编制国际招标文件（中、英文）和组织评标的能力。依法必须进行招标的项目，招标人自行办理招标事宜的，应当向相应主管部门备案。"},{"i":12,"n":"第十二条","txt":"招标机构应当具备从事招标代理业务的营业场所和相应资金；具备能够编制招标文件（中、英文）和组织评标的相应专业力量；拥有一定数量的取得招标职业资格的专业人员。 招标机构从事机电产品国际招标代理业务，应当在招标网免费注册，注册时应当在招标网在线填写机电产品国际招标机构登记表。 招标机构应当在招标人委托的范围内开展招标代理业务，任何单位和个人不得非法干涉。招标机构从事机电产品国际招标业务的人员应当为与本机构依法存在劳动合同关系的员工。招标机构可以依法跨区域开展业务，任何地区和部门不得以登记备案等方式加以限制。 招标机构代理招标业务，应当遵守招标投标法、招标投标法实施条例和本办法关于招标人的规定；在招标活动中，不得弄虚作假，损害国家利益、社会公共利益和招标人、投标人的合法权益。 招标人应当与被委托的招标机构签订书面委托合同，载明委托事项和代理权限，合同约定的收费标准应当符合国家有关规定。 招标机"},{"i":13,"n":"第十三条","txt":"发布资格预审公告、招标公告或发出投标邀请书前，招标人或招标机构应当在招标网上进行项目建档，建档内容包括项目名称、招标人名称及性质、招标方式、招标组织形式、招标机构名称、资金来源及性质、委托招标金额、项目审批或核准部门、主管部门等。"},{"i":14,"n":"第十四条","txt":"招标人采用公开招标方式的，应当发布招标公告。 招标人采用邀请招标方式的，应当向3个以上具备承担招标项目能力、资信良好的特定法人或者其他组织发出投标邀请书。"},{"i":15,"n":"第十五条","txt":"资格预审公告、招标公告或者投标邀请书应当载明下列内容： （一）招标项目名称、资金到位或资金来源落实情况； （二）招标人或招标机构名称、地址和联系方式； （三）招标产品名称、数量、简要技术规格； （四）获取资格预审文件或者招标文件的地点、时间、方式和费用； （五）提交资格预审申请文件或者投标文件的地点和截止时间； （六）开标地点和时间； （七）对资格预审申请人或者投标人的资格要求。"},{"i":16,"n":"第十六条","txt":"招标人不得以招标投标法实施条例第三十二条规定的情形限制、排斥潜在投标人或者投标人。"},{"i":17,"n":"第十七条","txt":"公开招标的项目，招标人可以对潜在投标人进行资格预审。资格预审按照招标投标法实施条例的有关规定执行。国有资金占控股或者主导地位的依法必须进行招标的项目，资格审查委员会及其成员应当遵守本办法有关评标委员会及其成员的规定。"},{"i":18,"n":"第十八条","txt":"编制依法必须进行机电产品国际招标的项目的资格预审文件和招标文件，应当使用机电产品国际招标标准文本。"},{"i":19,"n":"第十九条","txt":"招标人根据所采购机电产品的特点和需要编制招标文件。招标文件主要包括下列内容： （一）招标公告或投标邀请书； （二）投标人须知及投标资料表； （三）招标产品的名称、数量、技术要求及其他要求； （四）评标方法和标准； （五）合同条款； （六）合同格式； （七）投标文件格式及其他材料要求： 1、投标书； 2、开标一览表； 3、投标分项报价表； 4、产品说明一览表； 5、技术规格响应/偏离表； 6、商务条款响应/偏离表； 7、投标保证金银行保函； 8、单位负责人授权书； 9、资格证明文件； 10、履约保证金银行保函； 11、预付款银行保函； 12、信用证样本； 13、要求投标人提供的其他材料。"},{"i":20,"n":"第二十条","txt":"招标文件中应当明确评标方法和标准。机电产品国际招标的评标一般采用最低评标价法。技术含量高、工艺或技术方案复杂的大型或成套设备招标项目可采用综合评价法进行评标。所有评标方法和标准应当作为招标文件不可分割的一部分并对潜在投标人公开。招标文件中没有规定的评标方法和标准不得作为评标依据。 最低评标价法，是指在投标满足招标文件商务、技术等实质性要求的前提下，按照招标文件中规定的价格评价因素和方法进行评价，确定各投标人的评标价格，并按投标人评标价格由低到高的顺序确定中标候选人的评标方法。 综合评价法，是指在投标满足招标文件实质性要求的前提下，按照招标文件中规定的各项评价因素和方法对投标进行综合评价后，按投标人综合评价的结果由优到劣的顺序确定中标候选人的评标方法。 综合评价法应当由评价内容、评价标准、评价程序及推荐中标候选人原则等组成。综合评价法应当根据招标项目的具体需求，设定商务、技术、价格、服务"},{"i":21,"n":"第二十一条","txt":"招标文件的技术、商务等条款应当清晰、明确、无歧义，不得设立歧视性条款或不合理的要求排斥潜在投标人。招标文件编制内容原则上应当满足3个以上潜在投标人能够参与竞争。招标文件的编制应当符合下列规定： （一）对招标文件中的重要条款（参数）应当加注星号（“”），并注明如不满足任一带星号（“”）的条款（参数）将被视为不满足招标文件实质性要求，并导致投标被否决。 构成投标被否决的评标依据除重要条款（参数）不满足外，还可以包括超过一般条款（参数）中允许偏离的最大范围、最多项数。 采用最低评标价法评标的，评标依据中应当包括：一般商务和技术条款（参数）在允许偏离范围和条款数内进行评标价格调整的计算方法，每个一般技术条款（参数）的偏离加价一般为该设备投标价格的0.5%，最高不得超过该设备投标价格的1%，投标文件中没有单独列出该设备分项报价的，评标价格调整时按投标总价计算；交货期、付款条件等商务条款的偏离"},{"i":22,"n":"第二十二条","txt":"招标文件应当载明投标有效期，以保证招标人有足够的时间完成组织评标、定标以及签订合同。投标有效期从招标文件规定的提交投标文件的截止之日起算。"},{"i":23,"n":"第二十三条","txt":"招标人在招标文件中要求投标人提交投标保证金的，投标保证金不得超过招标项目估算价的2%。投标保证金有效期应当与投标有效期一致。 依法必须进行招标的项目的境内投标单位，以现金或者支票形式提交的投标保证金应当从其基本账户转出。 投标保证金可以是银行出具的银行保函或不可撤销信用证、转账支票、银行即期汇票，也可以是招标文件要求的其他合法担保形式。 联合体投标的，应当以联合体共同投标协议中约定的投标保证金缴纳方式予以提交，可以是联合体中的一方或者共同提交投标保证金，以一方名义提交投标保证金的，对联合体各方均具有约束力。 招标人不得挪用投标保证金。"},{"i":24,"n":"第二十四条","txt":"招标人或招标机构应当在资格预审文件或招标文件开始发售之日前将资格预审文件或招标文件发售稿上传招标网存档。"},{"i":25,"n":"第二十五条","txt":"依法必须进行招标的项目的资格预审公告和招标公告应当在符合法律规定的媒体和招标网上发布。"},{"i":26,"n":"第二十六条","txt":"招标人应当确定投标人编制投标文件所需的合理时间。依法必须进行招标的项目，自招标文件开始发售之日起至投标截止之日止，不得少于20日。 招标文件的发售期不得少于5个工作日。 招标人发售的纸质招标文件和电子介质的招标文件具有同等法律效力，除另有约定的，出现不一致时以纸质招标文件为准。"},{"i":27,"n":"第二十七条","txt":"招标公告规定未领购招标文件不得参加投标的，招标文件发售期截止后，购买招标文件的潜在投标人少于3个的，招标人可以依照本办法重新招标。重新招标后潜在投标人或投标人仍少于3个的，可以依照本办法第四十六条第二款有关规定执行。"},{"i":28,"n":"第二十八条","txt":"开标前，招标人、招标机构和有关工作人员不得向他人透露已获取招标文件的潜在投标人的名称、数量以及可能影响公平竞争的有关招标投标的其他信息。"},{"i":29,"n":"第二十九条","txt":"招标人可以对已发出的资格预审文件或者招标文件进行必要的澄清或者修改。澄清或者修改的内容可能影响资格预审申请文件或者投标文件编制的，招标人或招标机构应当在提交资格预审文件截止时间至少3日前，或者投标截止时间至少15日前，以书面形式通知所有获取资格预审文件或者招标文件的潜在投标人，并上传招标网存档；不足3日或者15日的，招标人或招标机构应当顺延提交资格预审申请文件或者投标文件的截止时间。该澄清或者修改内容为资格预审文件或者招标文件的组成部分。澄清或者修改的内容涉及到与资格预审公告或者招标公告内容不一致的，应当在原资格预审公告或者招标公告发布的媒体和招标网上发布变更公告。 因异议或投诉处理而导致对资格预审文件或者招标文件澄清或者修改的，应当按照前款规定执行。"},{"i":30,"n":"第三十条","txt":"招标人顺延投标截止时间的，至少应当在招标文件要求提交投标文件的截止时间3日前，将变更时间书面通知所有获取招标文件的潜在投标人，并在招标网上发布变更公告。"},{"i":31,"n":"第三十一条","txt":"除不可抗力原因外，招标文件或者资格预审文件发出后，不予退还；招标人在发布招标公告、发出投标邀请书后或者发出招标文件或资格预审文件后不得终止招标。 招标人终止招标的，应当及时发布公告，或者以书面形式通知被邀请的或者已经获取资格预审文件、招标文件的潜在投标人。已经发售资格预审文件、招标文件或者已经收取投标保证金的，招标人应当及时退还所收取的资格预审文件、招标文件的费用，以及所收取的投标保证金及银行同期存款利息。"},{"i":32,"n":"第三十二条","txt":"投标人是响应招标、参加投标竞争的法人或其他组织。 与招标人存在利害关系可能影响招标公正性的法人或其他组织不得参加投标；接受委托参与项目前期咨询和招标文件编制的法人或其他组织不得参加受托项目的投标，也不得为该项目的投标人编制投标文件或者提供咨询。 单位负责人为同一人或者存在控股、管理关系的不同单位，不得参加同一招标项目包投标，共同组成联合体投标的除外。 违反前三款规定的，相关投标均无效。"},{"i":33,"n":"第三十三条","txt":"投标人应当根据招标文件要求编制投标文件，并根据自己的商务能力、技术水平对招标文件提出的要求和条件在投标文件中作出真实的响应。投标文件的所有内容在投标有效期内应当有效。"},{"i":34,"n":"第三十四条","txt":"投标人对加注星号（“”）的重要技术条款（参数）应当在投标文件中提供技术支持资料。 技术支持资料以制造商公开发布的印刷资料、检测机构出具的检测报告或招标文件中允许的其他形式为准，凡不符合上述要求的，应当视为无效技术支持资料。"},{"i":35,"n":"第三十五条","txt":"投标人应当提供在开标日前3个月内由其开立基本账户的银行开具的银行资信证明的原件或复印件。"},{"i":36,"n":"第三十六条","txt":"潜在投标人或者其他利害关系人对资格预审文件有异议的，应当在提交资格预审申请文件截止时间2日前向招标人或招标机构提出，并将异议内容上传招标网；对招标文件有异议的，应当在投标截止时间10日前向招标人或招标机构提出，并将异议内容上传招标网。招标人或招标机构应当自收到异议之日起3日内作出答复，并将答复内容上传招标网；作出答复前，应当暂停招标投标活动。"},{"i":37,"n":"第三十七条","txt":"招标人编制的资格预审文件、招标文件的内容违反法律、行政法规的强制性规定，违反公开、公平、公正和诚实信用原则，影响资格预审结果或者潜在投标人投标的，依法必须进行招标的项目的招标人应当在修改资格预审文件或者招标文件后重新招标。"},{"i":38,"n":"第三十八条","txt":"投标人在招标文件要求的投标截止时间前，应当在招标网免费注册，注册时应当在招标网在线填写招投标注册登记表，并将由投标人加盖公章的招投标注册登记表及工商营业执照（复印件）提交至招标网；境外投标人提交所在地登记证明材料（复印件），投标人无印章的，提交由单位负责人签字的招投标注册登记表。投标截止时间前，投标人未在招标网完成注册的不得参加投标，有特殊原因的除外。"},{"i":39,"n":"第三十九条","txt":"投标人在招标文件要求的投标截止时间前，应当将投标文件送达招标文件规定的投标地点。投标人可以在规定的投标截止时间前书面通知招标人，对已提交的投标文件进行补充、修改或撤回。补充、修改的内容应当作为投标文件的组成部分。投标人不得在投标截止时间后对投标文件进行补充、修改。"},{"i":40,"n":"第四十条","txt":"投标人应当按照招标文件要求对投标文件进行包装和密封。投标人在投标截止时间前提交价格变更等相关内容的投标声明的，应与开标一览表一并或者单独密封，并加施明显标记，以便在开标时一并唱出。"},{"i":41,"n":"第四十一条","txt":"未通过资格预审的申请人提交的投标文件，以及逾期送达或者不按照招标文件要求密封的投标文件，招标人应当拒收。 招标人或招标机构应当如实记载投标文件的送达时间和密封情况，并存档备查。"},{"i":42,"n":"第四十二条","txt":"招标文件允许联合体投标的，两个以上法人或者其他组织可以组成一个联合体，以一个投标人的身份共同投标。 联合体各方均应当具备承担招标项目的相应能力；国家有关规定或者招标文件对投标人资格条件有规定的，联合体各方均应当具备规定的相应资格条件。由同一专业的单位组成的联合体，按照资质等级较低的单位确定资质等级。 联合体各方应当签订共同投标协议，明确约定各方拟承担的工作和责任，并将共同投标协议连同投标文件一并提交招标人。联合体中标的，联合体各方应当共同与招标人签订合同，就中标项目向招标人承担连带责任。 联合体各方在同一招标项目包中以自己名义单独投标或者参加其他联合体投标的，相关投标均无效。"},{"i":43,"n":"第四十三条","txt":"投标人应当按照招标文件的要求，在提交投标文件截止时间前将投标保证金提交给招标人或招标机构。 投标人在投标截止时间前撤回已提交的投标文件，招标人或招标机构已收取投标保证金的，应当自收到投标人书面撤回通知之日起5日内退还。 投标截止后投标人撤销投标文件的，招标人可以不退还投标保证金。招标人主动要求延长投标有效期但投标人拒绝的，招标人应当退还投标保证金。"},{"i":44,"n":"第四十四条","txt":"投标人发生合并、分立、破产等重大变化的，应当及时书面告知招标人。投标人不再具备资格预审文件、招标文件规定的资格条件或者其投标影响招标公正性的，其投标无效。"},{"i":45,"n":"第四十五条","txt":"禁止招标投标法实施条例第三十九条、第四十条、第四十一条、第四十二条所规定的投标人相互串通投标、招标人与投标人串通投标、投标人以他人名义投标或者以其他方式弄虚作假的行为。"},{"i":46,"n":"第四十六条","txt":"开标应当在招标文件确定的提交投标文件截止时间的同一时间公开进行；开标地点应当为招标文件中预先确定的地点。开标由招标人或招标机构主持，邀请所有投标人参加。 投标人少于3个的，不得开标，招标人应当依照本办法重新招标；开标后认定投标人少于3个的应当停止评标，招标人应当依照本办法重新招标。重新招标后投标人仍少于3个的，可以进入两家或一家开标评标；按国家有关规定需要履行审批、核准手续的依法必须进行招标的项目，报项目审批、核准部门审批、核准后可以不再进行招标。 认定投标人数量时，两家以上投标人的投标产品为同一家制造商或集成商生产的，按一家投标人认定。对两家以上集成商或代理商使用相同制造商产品作为其项目包的一部分，且相同产品的价格总和均超过该项目包各自投标总价60%的，按一家投标人认定。 对于国外贷款、援助资金项目，资金提供方规定当投标截止时间到达时，投标人少于3个可直接进入开标程序的，可以适用其规"},{"i":47,"n":"第四十七条","txt":"开标时，由投标人或者其推选的代表检查投标文件的密封情况，也可以由招标人委托的公证机构检查并公证；经确认无误后，由工作人员当众拆封，宣读投标人名称、投标价格和投标文件的其他主要内容。 招标人在招标文件要求提交投标文件的截止时间前收到的所有投标文件，开标时都应当当众予以拆封、宣读。 投标人的开标一览表、投标声明（价格变更或其他声明）都应当在开标时一并唱出，否则在评标时不予认可。投标总价中不应当包含招标文件要求以外的产品或服务的价格。"},{"i":48,"n":"第四十八条","txt":"投标人对开标有异议的，应当在开标现场提出，招标人或招标机构应当当场作出答复，并制作记录。"},{"i":49,"n":"第四十九条","txt":"招标人或招标机构应当在开标时制作开标记录，并在开标后3个工作日内上传招标网存档。"},{"i":50,"n":"第五十条","txt":"评标由招标人依照本办法组建的评标委员会负责。依法必须进行招标的项目，其评标委员会由招标人的代表和从事相关领域工作满8年并具有高级职称或者具有同等专业水平的技术、经济等相关领域专家组成，成员人数为5人以上单数，其中技术、经济等方面专家人数不得少于成员总数的2/3。"},{"i":51,"n":"第五十一条","txt":"依法必须进行招标的项目，机电产品国际招标评标所需专家原则上由招标人或招标机构在招标网上从国家、地方两级专家库内相关专业类别中采用随机抽取的方式产生。任何单位和个人不得以明示、暗示等任何方式指定或者变相指定参加评标委员会的专家成员。但技术复杂、专业性强或者国家有特殊要求，采取随机抽取方式确定的专家难以保证其胜任评标工作的特殊招标项目，报相应主管部门后，可以由招标人直接确定评标专家。 抽取评标所需的评标专家的时间不得早于开标时间3个工作日；同一项目包评标中，来自同一法人单位的评标专家不得超过评标委员会总人数的1/3。 随机抽取专家人数为实际所需专家人数。一次招标金额在1000万美元以上的国际招标项目包，所需专家的1/2以上应当从国家级专家库中抽取。 抽取工作应当使用招标网评标专家随机抽取自动通知系统。除专家不能参加和应当回避的情形外，不得废弃随机抽取的专家。 机电产品国际招标评标专家及专家"},{"i":52,"n":"第五十二条","txt":"与投标人或其制造商有利害关系的人不得进入相关项目的评标委员会，评标专家不得参加与自己有利害关系的项目评标，且应当主动回避；已经进入的应当更换。主管部门的工作人员不得担任本机构负责监督项目的评标委员会成员。 依法必须进行招标的项目的招标人非因招标投标法、招标投标法实施条例和本办法规定的事由，不得更换依法确定的评标委员会成员。更换评标委员会的专家成员应当依照本办法第五十一条规定进行。"},{"i":53,"n":"第五十三条","txt":"评标委员会成员名单在中标结果确定前应当保密，如有泄密，除追究当事人责任外，还应当报相应主管部门后及时更换。 评标前，任何人不得向评标专家透露其即将参与的评标项目招标人、投标人的有关情况及其他应当保密的信息。 招标人和招标机构应当采取必要的措施保证评标在严格保密的情况下进行。任何单位和个人不得非法干预、影响评标的过程和结果。 泄密影响中标结果的，中标无效。"},{"i":54,"n":"第五十四条","txt":"招标人应当向评标委员会提供评标所必需的信息，但不得向评标委员会成员明示或者暗示其倾向或者排斥特定投标人。 招标人应当根据项目规模和技术复杂程度等因素合理确定评标时间。超过1/3的评标委员会成员认为评标时间不够的，招标人应当适当延长。 评标过程中，评标委员会成员有回避事由、擅离职守或者因健康等原因不能继续评标的，应当于评标当日报相应主管部门后按照所缺专家的人数重新随机抽取，及时更换。被更换的评标委员会成员作出的评审结论无效，由更换后的评标委员会成员重新进行评审。"},{"i":55,"n":"第五十五条","txt":"评标委员会应当在开标当日开始进行评标。有特殊原因当天不能评标的，应当将投标文件封存，并在开标后48小时内开始进行评标。评标委员会成员应当依照招标投标法、招标投标法实施条例和本办法的规定，按照招标文件规定的评标方法和标准，独立、客观、公正地对投标文件提出评审意见。招标文件没有规定的评标方法和标准不得作为评标的依据。 评标委员会成员不得私下接触投标人，不得收受投标人给予的财物或者其他好处，不得向招标人征询确定中标人的意向，不得接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求，不得有其他不客观、不公正履行职务的行为。"},{"i":56,"n":"第五十六条","txt":"采用最低评标价法评标的，在商务、技术条款均实质性满足招标文件要求时，评标价格最低者为排名第一的中标候选人；采用综合评价法评标的，在商务、技术条款均实质性满足招标文件要求时，综合评价最优者为排名第一的中标候选人。"},{"i":57,"n":"第五十七条","txt":"在商务评议过程中，有下列情形之一者，应予否决投标： （一）投标人或其制造商与招标人有利害关系可能影响招标公正性的； （二）投标人参与项目前期咨询或招标文件编制的； （三）不同投标人单位负责人为同一人或者存在控股、管理关系的； （四）投标文件未按招标文件的要求签署的； （五）投标联合体没有提交共同投标协议的； （六）投标人的投标书、资格证明材料未提供，或不符合国家规定或者招标文件要求的； （七）同一投标人提交两个以上不同的投标方案或者投标报价的，但招标文件要求提交备选方案的除外； （八）投标人未按招标文件要求提交投标保证金或保证金金额不足、保函有效期不足、投标保证金形式或出具投标保函的银行不符合招标文件要求的； （九）投标文件不满足招标文件加注星号（“”）的重要商务条款要求的； （十）投标报价高于招标文件设定的最高投标限价的； （十一）投标有效期不足的； （十二）投标人有串通投标、弄虚"},{"i":58,"n":"第五十八条","txt":"对经资格预审合格、且商务评议合格的投标人不能再因其资格不合格否决其投标，但在招标周期内该投标人的资格发生了实质性变化不再满足原有资格要求的除外。"},{"i":59,"n":"第五十九条","txt":"技术评议过程中，有下列情形之一者，应予否决投标： （一）投标文件不满足招标文件技术规格中加注星号（“”）的重要条款（参数）要求，或加注星号（“”）的重要条款（参数）无符合招标文件要求的技术资料支持的； （二）投标文件技术规格中一般参数超出允许偏离的最大范围或最多项数的； （三）投标文件技术规格中的响应与事实不符或虚假投标的； （四）投标人复制招标文件的技术规格相关部分内容作为其投标文件中一部分的； （五）存在招标文件中规定的否决投标的其他技术条款的。"},{"i":60,"n":"第六十条","txt":"采用最低评标价法评标的，价格评议按下列原则进行： （一）按招标文件中的评标依据进行评标。计算评标价格时，对需要进行价格调整的部分，要依据招标文件和投标文件的内容加以调整并说明。投标总价中包含的招标文件要求以外的产品或服务，在评标时不予核减； （二）除国外贷款、援助资金项目外，计算评标总价时，以货物到达招标人指定到货地点为依据； （三）招标文件允许以多种货币投标的，在进行价格评标时，应当以开标当日中国银行总行首次发布的外币对人民币的现汇卖出价进行投标货币对评标货币的转换以计算评标价格。"},{"i":61,"n":"第六十一条","txt":"采用综合评价法评标时，按下列原则进行： （一）评标办法应当充分考虑每个评价指标所有可能的投标响应，且每一种可能的投标响应应当对应一个明确的评价值，不得对应多个评价值或评价值区间，采用两步评价方法的除外。 对于总体设计、总体方案等难以量化比较的评价内容，可以采取两步评价方法：第一步，评标委员会成员独立确定投标人该项评价内容的优劣等级，根据优劣等级对应的评价值算术平均后确定该投标人该项评价内容的平均等级；第二步，评标委员会成员根据投标人的平均等级，在对应的分值区间内给出评价值。 （二）价格评价应当符合低价优先、经济节约的原则，并明确规定评议价格最低的有效投标人将获得价格评价的最高评价值，价格评价的最大可能评价值和最小可能评价值应当分别为价格最高评价值和零评价值。 （三）评标委员会应当根据综合评价值对各投标人进行排名。综合评价值相同的，依照价格、技术、商务、服务及其他评价内容的优先次序，根据"},{"i":62,"n":"第六十二条","txt":"招标文件允许备选方案的，评标委员会对有备选方案的投标人进行评审时，应当以主选方案为准进行评标。备选方案应当实质性响应招标文件要求。凡提供两个以上备选方案或者未按要求注明主选方案的，该投标应当被否决。凡备选方案的投标价格高于主选方案的，该备选方案将不予采纳。"},{"i":63,"n":"第六十三条","txt":"投标人应当根据招标文件要求和产品技术要求列出供货产品清单和分项报价。投标人投标报价缺漏项超出招标文件允许的范围或比重的，为实质性偏离招标文件要求，评标委员会应当否决其投标。缺漏项在招标文件允许的范围或比重内的，评标时应当要求投标人确认缺漏项是否包含在投标价中，确认包含的，将其他有效投标中该项的最高价计入其评标总价，并依据此评标总价对其一般商务和技术条款（参数）偏离进行价格调整；确认不包含的，评标委员会应当否决其投标；签订合同时以投标价为准。"},{"i":64,"n":"第六十四条","txt":"投标文件中有含义不明确的内容、明显文字或者计算错误，评标委员会认为需要投标人作出必要澄清、说明的，应当书面通知该投标人。投标人的澄清、说明应当采用书面形式在评标委员会规定的时间内提交，并不得超出投标文件的范围或者改变投标文件的实质性内容。 投标人的投标文件不响应招标文件加注星号（“”）的重要商务和技术条款（参数），或加注星号（“”）的重要技术条款（参数）未提供符合招标文件要求的技术支持资料的，评标委员会不得要求其进行澄清或后补。 评标委员会不得暗示或者诱导投标人作出澄清、说明，不得接受投标人主动提出的澄清、说明。"},{"i":65,"n":"第六十五条","txt":"评标委员会经评审，认为所有投标都不符合招标文件要求的，可以否决所有投标。 依法必须进行招标的项目的所有投标被否决的，招标人应当依照本办法重新招标。"},{"i":66,"n":"第六十六条","txt":"评标完成后，评标委员会应当向招标人提交书面评标报告和中标候选人名单。中标候选人应当不超过3个，并标明排序。 评标委员会的每位成员应当分别填写评标委员会成员评标意见表（见附件2），评标意见表是评标报告必不可少的一部分。评标报告应当由评标委员会全体成员签字。对评标结果有不同意见的评标委员会成员应当以书面形式说明其不同意见和理由，评标报告应当注明该不同意见。评标委员会成员拒绝在评标报告上签字又不说明其不同意见和理由的，视为同意评标结果。 专家受聘承担的具体项目评审工作结束后，招标人或者招标机构应当在招标网对专家的能力、水平、履行职责等方面进行评价，评价结果分为优秀、称职和不称职。"},{"i":67,"n":"第六十七条","txt":"依法必须进行招标的项目，招标人或招标机构应当依据评标报告填写《评标结果公示表》，并自收到评标委员会提交的书面评标报告之日起3日内在招标网上进行评标结果公示。评标结果应当一次性公示，公示期不得少于3日。 采用最低评标价法评标的，《评标结果公示表》中的内容包括“中标候选人排名”、“投标人及制造商名称”、“评标价格”和“评议情况”等。每个投标人的评议情况应当按商务、技术和价格评议三个方面在《评标结果公示表》中分别填写，填写的内容应当明确说明招标文件的要求和投标人的响应内容。对一般商务和技术条款（参数）偏离进行价格调整的，在评标结果公示时，招标人或招标机构应当明确公示价格调整的依据、计算方法、投标文件偏离内容及相应的调整金额。 采用综合评价法评标的，《评标结果公示表》中的内容包括“中标候选人排名”、“投标人及制造商名称”、“综合评价值”、“商务、技术、价格、服务及其他等大类评价项目的评价值”和"},{"i":68,"n":"第六十八条","txt":"评标结果进行公示后，各方当事人可以通过招标网查看评标结果公示的内容。招标人或招标机构应当应投标人的要求解释公示内容。"},{"i":69,"n":"第六十九条","txt":"投标人或者其他利害关系人对依法必须进行招标的项目的评标结果有异议的，应当于公示期内向招标人或招标机构提出，并将异议内容上传招标网。招标人或招标机构应当在收到异议之日起3日内作出答复，并将答复内容上传招标网；作出答复前，应当暂停招标投标活动。 异议答复应当对异议问题逐项说明，但不得涉及其他投标人的投标秘密。未在评标报告中体现的不满足招标文件要求的其他方面的偏离不能作为答复异议的依据。 经原评标委员会按照招标文件规定的方法和标准审查确认，变更原评标结果的，变更后的评标结果应当依照本办法进行公示。"},{"i":70,"n":"第七十条","txt":"招标人根据评标委员会提出的书面评标报告和推荐的中标候选人确定中标人。招标人也可以授权评标委员会直接确定中标人。国有资金占控股或者主导地位的依法必须进行招标的项目，以及使用国外贷款、援助资金的项目，招标人应当确定排名第一的中标候选人为中标人。排名第一的中标候选人放弃中标、因不可抗力不能履行合同、不按招标文件要求提交履约保证金，或者被查实存在影响中标结果的违法行为等情形，不符合中标条件的，招标人可以按照评标委员会提出的中标候选人名单排序依次确定其他中标候选人为中标人，也可以重新招标。"},{"i":71,"n":"第七十一条","txt":"评标结果公示无异议的，公示期结束后该评标结果自动生效并进行中标结果公告；评标结果公示有异议，但是异议答复后10日内无投诉的，异议答复10日后按照异议处理结果进行公告；评标结果公示有投诉的，相应主管部门做出投诉处理决定后，按照投诉处理决定进行公告。"},{"i":72,"n":"第七十二条","txt":"依法必须进行招标的项目，中标人确定后，招标人应当在中标结果公告后20日内向中标人发出中标通知书，并在中标结果公告后15日内将评标情况的报告（见附件3）提交至相应的主管部门。中标通知书也可以由招标人委托其招标机构发出。 使用国外贷款、援助资金的项目，异议或投诉的结果与报送资金提供方的评标报告不一致的，招标人或招标机构应当按照异议或投诉的结果修改评标报告，并将修改后的评标报告报送资金提供方，获其不反对意见后向中标人发出中标通知书。"},{"i":73,"n":"第七十三条","txt":"中标结果公告后15日内，招标人或招标机构应当在招标网完成该项目包招标投标情况及其相关数据的存档。存档的内容应当与招标投标实际情况一致。"},{"i":74,"n":"第七十四条","txt":"中标候选人的经营、财务状况发生较大变化或者存在违法行为，招标人认为可能影响其履约能力的，应当在发出中标通知书前由原评标委员会按照招标文件规定的方法和标准审查确认。"},{"i":75,"n":"第七十五条","txt":"中标通知书对招标人和中标人具有法律效力。中标通知书发出后，招标人改变中标结果的，或者中标人放弃中标项目的，应当依法承担法律责任。"},{"i":76,"n":"第七十六条","txt":"招标人和中标人应当自中标通知书发出之日起30日内，依照招标投标法、招标投标法实施条例和本办法的规定签订书面合同，合同的标的、价款、质量、履行期限等主要条款应当与招标文件和中标人的投标文件的内容一致。招标人或中标人不得拒绝或拖延与另一方签订合同。 招标人和中标人不得再行订立背离合同实质性内容的其他协议。 招标人最迟应当在书面合同签订后5日内向中标人和未中标的投标人退还投标保证金及银行同期存款利息。"},{"i":77,"n":"第七十七条","txt":"招标文件要求中标人提交履约保证金的，中标人应当按照招标文件的要求提交。履约保证金不得超过中标合同金额的10%。"},{"i":78,"n":"第七十八条","txt":"中标产品来自关境外的，由招标人按照国家有关规定办理进口手续。"},{"i":79,"n":"第七十九条","txt":"中标人应当按照合同约定履行义务，完成中标项目。中标人不得向他人转让中标项目，也不得将中标项目肢解后分别向他人转让。"},{"i":80,"n":"第八十条","txt":"依法必须进行招标的项目，在国际招标过程中，因招标人的采购计划发生重大变更等原因，经项目主管部门批准，报相应的主管部门后，招标人可以重新组织招标。"},{"i":81,"n":"第八十一条","txt":"招标人或招标机构应当按照有关规定妥善保存招标委托协议、资格预审公告、招标公告、资格预审文件、招标文件、资格预审申请文件、投标文件、异议及答复等相关资料，以及与评标相关的评标报告、专家评标意见、综合评价法评价原始记录表等资料，并对评标情况和资料严格保密。"},{"i":82,"n":"第八十二条","txt":"投标人或者其他利害关系人认为招标投标活动不符合法律、行政法规及本办法规定的，可以自知道或者应当知道之日起10日内向相应主管部门投诉。就本办法第三十六条规定事项进行投诉的，潜在投标人或者其他利害关系人应当在自领购资格预审文件或招标文件10日内向相应的主管部门提出；就本办法第四十八条规定事项进行投诉的，投标人或者其他利害关系人应当在自开标10日内向相应的主管部门提出；就本办法第六十九条规定事项进行投诉的，投标人或者其他利害关系人应当在自评标结果公示结束10日内向相应的主管部门提出。 就本办法第三十六条、第四十八条、第六十九条规定事项投诉的，应当先向招标人提出异议，异议答复期间不计算在前款规定的期限内。就异议事项投诉的，招标人或招标机构应当在该项目被网上投诉后3日内，将异议相关材料提交相应的主管部门。"},{"i":83,"n":"第八十三条","txt":"投诉人应当于投诉期内在招标网上填写《投诉书》（见附件4）（就异议事项进行投诉的，应当提供异议和异议答复情况及相关证明材料），并将由投诉人单位负责人或单位负责人授权的人签字并盖章的《投诉书》、单位负责人证明文件及相关材料在投诉期内送达相应的主管部门。境外投诉人所在企业无印章的，以单位负责人或单位负责人授权的人签字为准。 投诉应当有明确的请求和必要的证明材料。投诉有关材料是外文的，投诉人应当同时提供其中文译本，并以中文译本为准。 投诉人应保证其提出投诉内容及相应证明材料的真实性及来源的合法性，并承担相应的法律责任。"},{"i":84,"n":"第八十四条","txt":"主管部门应当自收到书面投诉书之日起3个工作日内决定是否受理投诉，并将是否受理的决定在招标网上告知投诉人。主管部门应当自受理投诉之日起30个工作日内作出书面处理决定（见附件5），并将书面处理决定在招标网上告知投诉人；需要检验、检测、鉴定、专家评审的，以及监察机关依法对与招标投标活动有关的监察对象实施调查并可能影响投诉处理决定的，所需时间不计算在内。使用国外贷款、援助资金的项目，需征求资金提供方意见的，所需时间不计算在内。 主管部门在处理投诉时，有权查阅、复制有关文件、资料，调查有关情况，相关单位和人员应当予以配合。必要时，主管部门可以责令暂停招标投标活动。 主管部门在处理投诉期间，招标人或招标机构应当就投诉的事项协助调查。"},{"i":85,"n":"第八十五条","txt":"有下列情形之一的投诉，不予受理： （一）就本办法第三十六条、第四十八条、第六十九条规定事项投诉，其投诉内容在提起投诉前未按照本办法的规定提出异议的； （二）投诉人不是投标人或者其他利害关系人的； （三）《投诉书》未按本办法有关规定签字或盖章，或者未提供单位负责人证明文件的； （四）没有明确请求的，或者未按本办法提供相应证明材料的； （五）涉及招标评标过程具体细节、其他投标人的商业秘密或其他投标人的投标文件具体内容但未能说明内容真实性和来源合法性的； （六）未在规定期限内在招标网上提出的； （七）未在规定期限内将投诉书及相关证明材料送达相应主管部门的。"},{"i":86,"n":"第八十六条","txt":"在评标结果投诉处理过程中，发现招标文件重要商务或技术条款（参数）出现内容错误、前后矛盾或与国家相关法律法规不一致的情形，影响评标结果公正性的，当次招标无效，主管部门将在招标网上予以公布。"},{"i":87,"n":"第八十七条","txt":"招标人对投诉的内容无法提供充分解释和说明的，主管部门可以自行组织或者责成招标人、招标机构组织专家就投诉的内容进行评审。 就本办法第三十六条规定事项投诉的，招标人或招标机构应当从专家库中随机抽取3人以上单数评审专家。评审专家不得作为同一项目包的评标专家。 就本办法第六十九条规定事项投诉的，招标人或招标机构应当从国家级专家库中随机抽取评审专家，国家级专家不足时，可由地方级专家库中补充，但国家级专家不得少于2/3。评审专家不得包含参与该项目包评标的专家，并且专家人数不得少于评标专家人数。"},{"i":88,"n":"第八十八条","txt":"投诉人拒绝配合主管部门依法进行调查的，被投诉人不提交相关证据、依据和其他有关材料的，主管部门按照现有可获得的材料对相关投诉依法作出处理。"},{"i":89,"n":"第八十九条","txt":"投诉处理决定作出前，经主管部门同意，投诉人可以撤回投诉。投诉人申请撤回投诉的，应当以书面形式提交给主管部门，并同时在网上提出撤回投诉申请。已经查实投诉内容成立的，投诉人撤回投诉的行为不影响投诉处理决定。投诉人撤回投诉的，不得以同一的事实和理由再次进行投诉。"},{"i":90,"n":"第九十条","txt":"主管部门经审查，对投诉事项可作出下列处理决定： （一）投诉内容未经查实前，投诉人撤回投诉的，终止投诉处理； （二）投诉缺乏事实根据或者法律依据的，以及投诉人捏造事实、伪造材料或者以非法手段取得证明材料进行投诉的，驳回投诉； （三）投诉情况属实，招标投标活动确实存在不符合法律、行政法规和本办法规定的，依法作出招标无效、投标无效、中标无效、修改资格预审文件或者招标文件等决定。"},{"i":91,"n":"第九十一条","txt":"商务部在招标网设立信息发布栏，包括下列内容： （一）投诉汇总统计，包括年度内受到投诉的项目、招标人、招标机构名称和投诉处理结果等； （二）招标机构代理项目投诉情况统计，包括年度内项目投诉数量、投诉率及投诉处理结果等； （三）投标人及其他利害关系人投诉情况统计，包括年度内项目投诉数量、投诉率及不予受理投诉、驳回投诉、不良投诉（本办法第九十六条第四项的投诉行为）等； （四）违法统计，包括年度内在招标投标活动过程中违反相关法律、行政法规和本办法的当事人、项目名称、违法情况和处罚结果。"},{"i":92,"n":"第九十二条","txt":"主管部门应当建立投诉处理档案，并妥善保存。"},{"i":93,"n":"第九十三条","txt":"招标人对依法必须进行招标的项目不招标或化整为零以及以其他任何方式规避国际招标的，由相应主管部门责令限期改正，可以处项目合同金额0.5%以上1%以下的罚款；对全部或者部分使用国有资金的项目，可以通告项目主管机构暂停项目执行或者暂停资金拨付；对单位直接负责的主管人员和其他直接责任人员依法给予处分。"},{"i":94,"n":"第九十四条","txt":"招标人有下列行为之一的，依照招标投标法、招标投标法实施条例的有关规定处罚： （一）依法应当公开招标而采用邀请招标的； （二）以不合理的条件限制、排斥潜在投标人的，对潜在投标人实行歧视待遇的，强制要求投标人组成联合体共同投标的，或者限制投标人之间竞争的； （三）招标文件、资格预审文件的发售、澄清、修改的时限，或者确定的提交资格预审申请文件、投标文件的时限不符合规定的； （四）不按照规定组建评标委员会，或者确定、更换评标委员会成员违反规定的； （五）接受未通过资格预审的单位或者个人参加投标，或者接受应当拒收的投标文件的； （六）违反规定，在确定中标人前与投标人就投标价格、投标方案等实质性内容进行谈判的； （七）不按照规定确定中标人的； （八）不按照规定对异议作出答复，继续进行招标投标活动的； （九）无正当理由不发出中标通知书，或者中标通知书发出后无正当理由改变中标结果的； （十）无正当理由"},{"i":95,"n":"第九十五条","txt":"招标人有下列行为之一的，给予警告，并处3万元以下罚款；该行为影响到评标结果的公正性的，当次招标无效： （一）与投标人相互串通、虚假招标投标的； （二）以不正当手段干扰招标投标活动的； （三）不履行与中标人订立的合同的； （四）除本办法第九十四条第十二项所列行为外，其他泄漏应当保密的与招标投标活动有关的情况、材料或信息的； （五）对主管部门的投诉处理决定拒不执行的； （六）其他违反招标投标法、招标投标法实施条例和本办法的行为。"},{"i":96,"n":"第九十六条","txt":"投标人有下列行为之一的，依照招标投标法、招标投标法实施条例的有关规定处罚： （一）与其他投标人或者与招标人相互串通投标的； （二）以向招标人或者评标委员会成员行贿的手段谋取中标的； （三）以他人名义投标或者以其他方式弄虚作假，骗取中标的； （四）捏造事实、伪造材料或者以非法手段取得证明材料进行投诉的。 有前款所列行为的投标人不得参与该项目的重新招标。"},{"i":97,"n":"第九十七条","txt":"投标人有下列行为之一的，当次投标无效，并给予警告，并处3万元以下罚款： （一）虚假招标投标的； （二）以不正当手段干扰招标、评标工作的； （三）投标文件及澄清资料与事实不符，弄虚作假的； （四）在投诉处理过程中，提供虚假证明材料的； （五）中标通知书发出之前与招标人签订合同的； （六）中标的投标人不按照其投标文件和招标文件与招标人签订合同的或提供的产品不符合投标文件的； （七）其他违反招标投标法、招标投标法实施条例和本办法的行为。 有前款所列行为的投标人不得参与该项目的重新招标。"},{"i":98,"n":"第九十八条","txt":"中标人有下列行为之一的，依照招标投标法、招标投标法实施条例的有关规定处罚： （一）无正当理由不与招标人订立合同的，或者在签订合同时向招标人提出附加条件的； （二）不按照招标文件要求提交履约保证金的； （三）不履行与招标人订立的合同的。 有前款所列行为的投标人不得参与该项目的重新招标。"},{"i":99,"n":"第九十九条","txt":"招标机构有下列行为之一的，依照招标投标法、招标投标法实施条例的有关规定处罚： （一）与招标人、投标人串通损害国家利益、社会公共利益或者他人合法权益的； （二）在所代理的招标项目中投标、代理投标或者向该项目投标人提供咨询的； （三）参加受托编制标底项目的投标或者为该项目的投标人编制投标文件、提供咨询的； （四）泄漏应当保密的与招标投标活动有关的情况和资料的。"},{"i":100,"n":"第一百条","txt":"招标机构有下列行为之一的，给予警告，并处3万元以下罚款；该行为影响到整个招标公正性的，当次招标无效： （一）与招标人、投标人相互串通、搞虚假招标投标的； （二）在进行机电产品国际招标机构登记时填写虚假信息或提供虚假证明材料的； （三）无故废弃随机抽取的评审专家的； （四）不按照规定及时向主管部门报送材料或者向主管部门提供虚假材料的； （五）未在规定的时间内将招标投标情况及其相关数据上传招标网，或者在招标网上发布、公示或存档的内容与招标公告、招标文件、投标文件、评标报告等相应书面内容存在实质性不符的； （六）不按照本办法规定对异议作出答复的，或者在投诉处理的过程中未按照主管部门要求予以配合的； （七）因招标机构的过失，投诉处理结果为招标无效或中标无效，6个月内累计2次，或一年内累计3次的； （八）不按照本办法规定发出中标通知书或者擅自变更中标结果的； （九）其他违反招标投标法、招标投标法"},{"i":101,"n":"第一百零一条","txt":"评标委员会成员有下列行为之一的，依照招标投标法、招标投标法实施条例的有关规定处罚： （一）应当回避而不回避的； （二）擅离职守的； （三）不按照招标文件规定的评标方法和标准评标的； （四）私下接触投标人的； （五）向招标人征询确定中标人的意向或者接受任何单位或者个人明示或者暗示提出的倾向或者排斥特定投标人的要求的； （六）暗示或者诱导投标人作出澄清、说明或者接受投标人主动提出的澄清、说明的； （七）对依法应当否决的投标不提出否决意见的； （八）向他人透露对投标文件的评审和比较、中标候选人的推荐以及与评标有关的其他情况的。"},{"i":102,"n":"第一百零二条","txt":"评标委员会成员有下列行为之一的，将被从专家库名单中除名，同时在招标网上予以公告： （一）弄虚作假，谋取私利的； （二）在评标时拒绝出具明确书面意见的； （三）除本办法第一百零一条第八项所列行为外，其他泄漏应当保密的与招标投标活动有关的情况和资料的； （四）与投标人、招标人、招标机构串通的； （五）专家1年内2次被评价为不称职的； （六）专家无正当理由拒绝参加评标的； （七）其他不客观公正地履行职责的行为，或违反招标投标法、招标投标法实施条例和本办法的行为。 前款所列行为影响中标结果的，中标无效。"},{"i":103,"n":"第一百零三条","txt":"除评标委员会成员之外的其他评审专家有本办法第一百零一条和第一百零二条所列行为之一的，将被从专家库名单中除名，同时在招标网上予以公告。"},{"i":104,"n":"第一百零四条","txt":"招标网承办单位有下列行为之一的，商务部予以警告并责令改正；情节严重的或拒不改正的，商务部可以中止或终止其委托服务协议；给招标投标活动当事人造成损失的，应当承担赔偿责任；构成犯罪的，依法追究刑事责任： （一）超出商务部委托范围从事与委托事项相关活动的； （二）利用承办商务部委托范围内事项向有关当事人收取费用的； （三）无正当理由拒绝或者延误潜在投标人于投标截止时间前在招标网免费注册的； （四）泄露应当保密的与招标投标活动有关情况和资料的； （五）在委托范围内，利用有关当事人的信息非法获取利益的； （六）擅自修改招标人、投标人或招标机构上传资料的； （七）与招标人、投标人、招标机构相互串通、搞虚假招标投标的； （八）其他违反招标投标法、招标投标法实施条例及本办法的。"},{"i":105,"n":"第一百零五条","txt":"主管部门在处理投诉过程中，发现被投诉人单位直接负责的主管人员和其他直接责任人员有违法、违规或者违纪行为的，应当建议其行政主管机关、纪检监察部门给予处分；情节严重构成犯罪的，移送司法机关处理。"},{"i":106,"n":"第一百零六条","txt":"主管部门不依法履行职责，对违反招标投标法、招标投标法实施条例和本办法规定的行为不依法查处，或者不按照规定处理投诉、不依法公告对招标投标当事人违法行为的行政处理决定的，对直接负责的主管人员和其他直接责任人员依法给予处分。 主管部门工作人员在招标投标活动监督过程中徇私舞弊、滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任。"},{"i":107,"n":"第一百零七条","txt":"出让或者出租资格、资质证书供他人投标的，依照法律、行政法规的规定给予行政处罚；构成犯罪的，依法追究刑事责任。"},{"i":108,"n":"第一百零八条","txt":"依法必须进行招标的项目的招标投标活动违反招标投标法、招标投标法实施条例和本办法的规定，对中标结果造成实质性影响，且不能采取补救措施予以纠正的，招标、投标、中标无效，应当依照本办法重新招标或者重新评标。 重新评标应当由招标人依照本办法组建新的评标委员会负责。前一次参与评标的专家不得参与重新招标或者重新评标。依法必须进行招标的项目，重新评标的结果应当依照本办法进行公示。 除法律、行政法规和本办法规定外，招标人不得擅自决定重新招标或重新评标。"},{"i":109,"n":"第一百零九条","txt":"本章规定的行政处罚，由相应的主管部门决定。招标投标法、招标投标法实施条例已对实施行政处罚的机关作出规定的除外。"},{"i":110,"n":"第一百一十条","txt":"不属于工程建设项目，但属于固定资产投资项目的机电产品国际招标投标活动，按照本办法执行。"},{"i":111,"n":"第一百一十一条","txt":"与机电产品有关的设计、方案、技术等国际招标投标，可参照本办法执行。"},{"i":112,"n":"第一百一十二条","txt":"使用国外贷款、援助资金进行机电产品国际招标的，应当按照本办法的有关规定执行。贷款方、资金提供方对招标投标的具体条件和程序有不同规定的，可以适用其规定，但违背中华人民共和国的国家安全或社会公共利益的除外。"},{"i":113,"n":"第一百一十三条","txt":"机电产品国际招标投标活动采用电子招标投标方式的，应当按照本办法和国家有关电子招标投标的规定执行。"},{"i":114,"n":"第一百一十四条","txt":"本办法所称“单位负责人”，是指单位法定代表人或者法律、行政法规规定代表单位行使职权的主要负责人。"},{"i":115,"n":"第一百一十五条","txt":"本办法所称“日”为日历日，期限的最后一日是国家法定节假日的，顺延到节假日后的次日为期限的最后一日。"},{"i":116,"n":"第一百一十六条","txt":"本办法中CIF、CIP、DDP等贸易术语，应当根据国际商会（ICC）现行最新版本的《国际贸易术语解释通则》的规定解释。"},{"i":117,"n":"第一百一十七条","txt":"本办法由商务部负责解释。"},{"i":118,"n":"第一百一十八条","txt":"本办法自2014年4月1日起施行。《机电产品国际招标投标实施办法》（商务部2004年第13号令）同时废止。 　　附件： 　　1、机电产品范围.doc 　　2、评标委员会成员评标意见表.doc 　　3、评标情况的报告.doc 　　4、投诉书.doc 　　5、投诉处理决定书.doc"}],"jidianchanpinzidongjinkouxukeshishibanfa":[{"i":1,"n":"第一条","txt":"为了对部分自由进口的机电产品的进口情况进行监测和统计，根据《中华人民共和国对外贸易法》、《中华人民共和国货物进出口管理条例》、《货物自动进口许可管理办法》及《机电产品进口管理办法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于将列入自动进口许可的机电产品（含相应的旧机电产品，下同）进口到中华人民共和国关境内的行为。"},{"i":3,"n":"第三条","txt":"商务部负责全国机电产品自动进口许可的管理工作，会同海关总署等有关部门制定、调整并公布实行自动进口许可的机电产品目录。 商务部委托各省、自治区、直辖市、计划单列市、新疆生产建设兵团、沿海开放城市、经济特区机电产品进出口办公室和国务院有关部门机电产品进出口办公室（简称为地方、部门机电办）负责有关机电产品自动进口许可管理和《中华人民共和国自动进口许可证》（以下简称自动进口许可证，式样格式见附件1）的签发工作。 商务部、海关总署在各自的职责范围内，对申请、使用机电产品自动进口许可证的活动进行监督检查。"},{"i":4,"n":"第四条","txt":"一般贸易（包括外商投资企业进口内销料件）、易货贸易、租赁、援助与赠送、捐赠等方式进口，以及我国驻外机构或者境外企业在境外购置需调回自用的属于自动进口许可机电产品目录的产品均需申请《中华人民共和国自动进口许可证》（以下简称《自动进口许可证》）。"},{"i":5,"n":"第五条","txt":"进口属于自动进口许可的机电产品，进口单位在办理海关手续前，应当向商务部或其委托的机构申请《自动进口许可证》。 凡申请进口法律、行政法规规定应当招标的机电产品，进口单位应当在签订合同之前进行招标。"},{"i":6,"n":"第六条","txt":"进口单位申请《自动进口许可证》，应当提供以下材料： （一）机电产品进口申请表（见附件2）； （二）营业执照复印件 （三）进口订货合同； （四）如属于下列情况的，还应提供以下材料： 1、进口国家实行强制性认证的机电产品的，应提供《中国国家强制性产品认证证书》或《免予办理强制性产品认证证明》； 2、投资项目下进口机电产品的，应提供项目投资主管机构出具的项目审批、核准或者备案文件（复印件）； 3、进口旧机电产品的，应提供检验机构出具的装运前报告； 4、进口旧机电产品用于翻新（含再制造，下同）的，应提供可从事翻新业务的相关证明材料； 5、进口采用国际招标方式采购的机电产品，应提供机电产品国际招标中标通知书。 6、上述规定的材料可通过国家政务服务系统联网查询的，可不再提交。 （五）商务部规定的其他需要提交的材料。 进口单位应当对所提交的申请材料的真实性负责，经营活动应遵守国家法律、行政法规的规定"},{"i":7,"n":"第七条","txt":"进口《自动进口许可机电产品目录》的机电产品，还应当符合下列法律、行政法规的规定： （一）符合《中华人民共和国标准化法》有关保障人体健康和人身财产安全的标准、强制执行标准的规定； （二）符合《中华人民共和国环境保护法》等环境保护法律、行政法规的规定； （三）符合《中华人民共和国大气污染防治法》等大气环境保护法律、行政法规的规定； （四）符合《中华人民共和国认证认可条例》的有关规定； （五）进口烟草加工机械应符合《中华人民共和国烟草专卖法》及《中华人民共和国烟草专卖法实施细则》的有关规定； （六）进口计量器具应符合《中华人民共和国计量法》和《中华人民共和国进口计量器具监督管理办法》的有关规定； （七）进口无线电发射设备应符合《中华人民共和国无线电管理条例》的有关规定； （八）进口卫星电视接收设备应符合《卫星电视地面接收设施管理规定》的有关规定； （九）进口电子游戏机产品应符合《娱乐场所管理"},{"i":8,"n":"第八条","txt":"机电产品《自动进口许可证》的申请程序如下： （一）进口列入《自动进口许可机电产品目录》的产品，进口单位应当向商务部或地方、部门机电办申请办理自动进口许可手续。 （二）申请可通过书面形式或网上申请方式提交。 1、书面申请程序：申请进口单位可到发证机构领取或从商务部授权网站下载（可复印）《机电产品进口申请表》，与其他相关书面材料一并提交到相应的主管机构。 2、网上申请程序：申请进口单位登录商务部授权网站，进入全国机电产品进口单证管理系统，按要求如实在线填写《机电产品进口申请表》并提交相应的主管机构。"},{"i":9,"n":"第九条","txt":"机电产品《自动进口许可证》的签发程序如下： （一）进口属于地方、部门机电办办理的机电产品，地方或者部门机电办自收到内容正确、形式完备的《机电产品进口申请表》和相关材料后，应当立即签发《自动进口许可证》；在特殊情况下，最长不超过10个工作日。 （二）进口属于商务部办理的机电产品，地方、部门机电办收到齐备的申请材料后3个工作日内将核实后的电子数据转报商务部。商务部在收到相应数据后，应当立即签发《自动进口许可证》；在特殊情况下，最长不超过10个工作日。"},{"i":10,"n":"第十条","txt":"申请进口单位所提交的材料不实的，商务部及地方、部门机电办可不予签发机电产品《自动进口许可证》。"},{"i":11,"n":"第十一条","txt":"进口单位凭加盖自动进口许可证专用章的《自动进口许可证》向银行办理售付汇手续，向海关办理通关手续。 进口列入《自动进口许可机电产品目录》的旧机电产品的，进口单位须持《自动进口许可证》和其他必要材料按海关规定办理通关手续。"},{"i":12,"n":"第十二条","txt":"机电产品《自动进口许可证》实行“一批一证”或“非一批一证”管理。 “一批一证”是指同一份《自动进口许可证》不得分批次累计报关使用。 “非一批一证”是指同一份《自动进口许可证》在有效期内可以分批次累计报关使用，但累计使用不得超过6次。海关在《自动进口许可证》原件“海关验放签注栏”内以正楷字体批注后，海关留存复印件，最后一次使用后，海关留存正本。"},{"i":13,"n":"第十三条","txt":"商务部根据海关留存的《自动进口许可证》使用记录，对《自动进口许可证》项下机电产品的进口情况进行统计。"},{"i":14,"n":"第十四条","txt":"《自动进口许可证》在公历年内有效，有效期为6个月。实际用汇额低于或不超过原定用汇额10%的，不需变更《自动进口许可证》。 在有效期内，需要变更《自动进口许可证》中有关项目内容的，进口单位应当持原《自动进口许可证》到原签发机构申请办理变更换证手续。对交货期较长的产品，在有效期内需要延期的，进口单位应当持原《自动进口许可证》到原签发机构申请办理延期手续。"},{"i":15,"n":"第十五条","txt":"《自动进口许可证》如有遗失，进口单位应当立即向原发证机构书面报告挂失。原发证机构收到挂失报告后，经核实后决定是否补发。"},{"i":16,"n":"第十六条","txt":"进口单位已申领的《自动进口许可证》，如未使用或确定不需要使用时，应当及时交回原发证机构。"},{"i":17,"n":"第十七条","txt":"有下列进口属于自动进口许可的机电产品情形之一的，适用本办法： （一）外商投资企业进口用于国内销售或加工后国内销售的； 外商投资企业在外商投资数额之外以自有资金进口新机电产品以及进口旧机电产品的； 外商投资企业在投资额内进口新机电产品，经过使用，未到海关监管年限，企业要求提前解除监管并在境内自用或转内销的，参照进口时的状态办理相关手续； （二）加工贸易项下进口的作价设备及加工贸易项下进口机电产品用于内销、内销产品或者留作自用的； 加工贸易项下进口的不作价设备在海关监管期内，原设备使用单位申请提前解除监管或监管期已满但设备不再由原单位使用的； （三）从海关特殊监管区域和海关保税监管场所进入（境内）区外的； （四）租赁贸易、补偿贸易等贸易方式进口机电产品的； （五）无偿援助、捐赠或经济往来赠送等方式进口机电产品的； （六）其他法律、行政法规有规定的。"},{"i":18,"n":"第十八条","txt":"有下列进口属于自动进口许可机电产品情形之一的，不适用本办法： （一）外商投资企业在投资总额内作为投资和自用进口的新机电产品的； （二）加工贸易项下进口的不作价设备监管期满后留在原企业使用的；加工贸易项下为复出口而进口的； （三）从境外进入海关特殊监管区域或海关保税监管场所及海关特殊监管区域或海关保税监管场所之间进出的； 从（境内）区外进入海关特殊监管区域或海关保税监管场所，供区内（场所内）企业使用和供区内（场所内）基础设施建设项目所需的机器设备转出区外（场所外）的； （四）由海关监管，暂时进口后复出口或暂时出口后复进口的； （五）进口货样和广告品、实验品，每批次价值不超过5000元人民币的； （六）其他法律、行政法规另有规定的。"},{"i":19,"n":"第十九条","txt":"本办法由商务部、海关总署负责解释。"},{"i":20,"n":"第二十条","txt":"本细则自二○○八年五月一日起施行。原《机电产品自动进口管理实施细则》（外经贸部、海关总署2001年第25号令）同时废止。 附件1：《中华人民共和国自动进口许可证》式样 附件2：机电产品进口申请表"}],"jidianchanpinjinkouguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进对外贸易健康发展，贯彻国家产业政策，维护市场秩序，依据《中华人民共和国对外贸易法》、《中华人民共和国海关法》及《中华人民共和国货物进出口管理条例》等相关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称机电产品（含旧机电产品），是指机械设备、电气设备、交通运输工具、电子产品、电器产品、仪器仪表、金属制品等及其零部件、元器件。机电产品的具体范围见附件。 本办法所称旧机电产品是指具有下列情形之一的机电产品： （一）已经使用（不含使用前测试、调试的设备），仍具备基本功能和一定使用价值的； （二）未经使用，但超过质量保证期（非保修期）的； （三）未经使用，但存放时间过长，部件产生明显有形损耗的； （四）新旧部件混装的； （五）经过翻新的。"},{"i":3,"n":"第三条","txt":"本办法适用于将机电产品进口到中华人民共和国关境内的行为。"},{"i":4,"n":"第四条","txt":"进口机电产品应当符合我国有关安全、卫生和环境保护等法律、行政法规和技术标准等的规定。"},{"i":5,"n":"第五条","txt":"商务部负责全国机电产品进口管理工作。国家机电产品进出口办公室设在商务部。 各省、自治区、直辖市、计划单列市、新疆生产建设兵团、沿海开放城市、经济特区机电产品进出口办公室和国务院有关部门机电产品进出口办公室（简称为地方、部门机电办）受商务部委托，负责本地区、本部门机电产品进口管理工作。"},{"i":6,"n":"第六条","txt":"国家对机电产品进口实行分类管理，即分为禁止进口、限制进口和自由进口三类。 基于进口监测需要，对部分自由进口的机电产品实行自动进口许可。"},{"i":7,"n":"第七条","txt":"有下列情形之一的机电产品，禁止进口： （一）为维护国家安全、社会公共利益或者公共道德，需要禁止进口的； （二）为保护人的健康或者安全，保护动物、植物的生命或者健康，保护环境，需要禁止进口的； （三）依照其他法律、行政法规的规定，需要禁止进口的； （四）根据中华人民共和国所缔结或者参加的国际条约、协定的规定，需要禁止进口的。"},{"i":8,"n":"第八条","txt":"商务部会同海关总署等相关部门制定、调整并公布《禁止进口机电产品目录》。 国家根据旧机电产品对国家安全、社会公共利益以及安全、卫生、健康、环境保护可能产生危害的程度，将超过规定制造年限的旧机电产品，合并列入上述目录。"},{"i":9,"n":"第九条","txt":"有下列情形之一的机电产品，限制进口： （一）为维护国家安全、社会公共利益或者公共道德，需要限制进口的； （二）为保护人的健康或者安全，保护动物、植物的生命或者健康，保护环境，需要限制进口的； （三）为建立或者加快建立国内特定产业，需要限制进口的； （四）为保障国家国际金融地位和国际收支平衡，需要限制进口的； （五）依照其他法律、行政法规的规定，需要限制进口的； （六）根据中华人民共和国所缔结或者参加的国际条约、协定的规定，需要限制进口的。"},{"i":10,"n":"第十条","txt":"商务部会同海关总署制定、调整并公布《限制进口机电产品目录》。限制进口的机电产品，实行配额、许可证管理。 商务部、海关总署在各自的职责范围内，对申请、使用机电产品进口配额、许可证的活动进行监督检查。"},{"i":11,"n":"第十一条","txt":"国家限制进口的旧机电产品称为重点旧机电产品。 商务部会同海关总署制定、调整并公布《重点旧机电产品进口目录》。 重点旧机电产品进口实行进口许可证管理。"},{"i":12,"n":"第十二条","txt":"《限制进口机电产品目录》及《重点旧机电产品进口目录》至迟应当在实施前21天公布。在紧急情况下，应当不迟于实施之日公布。"},{"i":13,"n":"第十三条","txt":"实行配额管理的限制进口机电产品，依据国务院颁布的有关进口货物配额管理办法的规定实施管理。"},{"i":14,"n":"第十四条","txt":"实行进口许可证管理的机电产品，地方、部门机电办核实进口单位的申请材料后，向商务部提交。商务部审核申请材料，并在20日内决定是否签发《中华人民共和国进口许可证》（以下简称《进口许可证》）。进口单位持《进口许可证》按海关规定办理通关手续。 进口重点旧机电产品，进口单位持《进口许可证》和其他必要材料按海关规定办理通关手续。"},{"i":15,"n":"第十五条","txt":"商务部会同海关总署制定并公布《机电产品进口许可管理实施办法》，商务部会同海关总署制定并公布《重点旧机电产品进口管理办法》。"},{"i":16,"n":"第十六条","txt":"为了监测机电产品进口情况，国家对部分自由进口的机电产品实行自动进口许可。"},{"i":17,"n":"第十七条","txt":"商务部会同海关总署等有关部门制定、调整并公布实行自动进口许可的机电产品目录。 实行自动进口许可的机电产品目录至迟应当在实施前21天公布。 商务部、海关总署在各自的职责范围内，对申请、使用机电产品自动进口许可证的活动进行监督检查。"},{"i":18,"n":"第十八条","txt":"进口实行自动进口许可的机电产品，进口单位应当在办理海关报关手续前，向商务部或地方、部门机电办申领《中华人民共和国自动进口许可证》（以下简称《自动进口许可证》），并持《自动进口许可证》按海关规定办理通关手续。 进口属于自动进口许可的旧机电产品（不含重点旧机电产品），进口单位持自动进口许可证和其他必要材料按海关规定办理通关手续。"},{"i":19,"n":"第十九条","txt":"商务部会同海关总署制定并公布《机电产品自动进口许可实施办法》。"},{"i":20,"n":"第二十条","txt":"商务部负责对全国机电产品进口情况进行统计、分析与监测。 地方、部门机电办应当依照国家统计制度的规定，及时向商务部报送本地区、本部门机电产品进口统计数据和资料。"},{"i":21,"n":"第二十一条","txt":"经监测，如机电产品进口出现异常情况，商务部应当及时通知有关部门，并依法进行调查。"},{"i":22,"n":"第二十二条","txt":"商务部及地方、部门机电办可以对限制进口的机电产品的进口情况依法进行检查。进口单位应当配合与协助检查，检查部门应当为进口单位保守商业秘密。"},{"i":23,"n":"第二十三条","txt":"进口单位不得从事下列行为： （一）进口属于禁止进口管理的机电产品，或者未经批准、许可进口属于限制进口管理的机电产品； （二）超出批准、许可的范围进口属于限制进口管理的机电产品； （三）伪造、变造或者买卖机电产品进口证件（包括《进口许可证》、《自动进口许可证》，下同）； （四）以欺骗或者其他不正当手段获取机电产品进口证件； （五）非法转让机电产品进口证件； （六）未按法定程序申请进口； （七）其他违反法律、行政法规有关进口机电产品规定的行为。"},{"i":24,"n":"第二十四条","txt":"进口单位有第二十三条规定的行为之一并构成犯罪的，依法追究刑事责任，尚不构成犯罪的，由公安、海关等具有行政处罚权的行政机关依法对相关当事人作出处理。"},{"i":25,"n":"第二十五条","txt":"进口单位对国家行政机关作出的有关行政决定或行政处罚决定不服的，可依法申请行政复议或者提起行政诉讼。"},{"i":26,"n":"第二十六条","txt":"进口管理工作人员玩忽职守、徇私舞弊、滥用职权的，根据情节轻重，由相应的行政主管部门按有关规定给予处罚；构成犯罪的，依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"下列情形，从以下规定： （一）加工贸易项下进口的作价设备，适用本办法。 （二）加工贸易项下进口外商提供的不作价设备，除旧加工设备需要办理入境检验检疫手续外，免于办理机电产品进口证件。海关监管不作价设备，监管期限为5年。监管期满后，设备留在原企业继续使用的，经企业申请海关可解除监管，企业免于办理机电产品进口证件和入境检验检疫手续；监管期内，原设备使用单位申请提前解除监管，或监管期满后设备不再由原企业使用的，适用本办法。 加工贸易项下进口机电产品用于内销、内销产品或者留作自用的，适用本办法。 （三）外商投资企业进口机电产品用于国内销售或用于加工后国内销售的和外商投资额外以自有资金进口新机电产品，以及进口旧机电产品的，适用本办法。 外商投资企业在投资额内进口新机电产品，经过使用，未到海关监管年限，企业要求提前解除监管并在境内自用或转内销的，适用本办法，并参照进口时的状态办理相关手续，海关凭相"},{"i":28,"n":"第二十八条","txt":"有下列情形之一的,不适用本办法： （一）外商投资企业在投资总额内作为投资和自用进口新机电产品的； （二）加工贸易项下为复出口而进口机电产品的； （三）由海关监管，暂时进口后复出口或暂时出口后复进口的； （四）进口机电产品货样、广告物品、实验品的，每批次价值不超过5000元人民币的； （五）其他法律、行政法规另有规定的。"},{"i":29,"n":"第二十九条","txt":"依据我国法律、法规或者我国与有关国际金融组织、外国政府贷款国达成的协议的规定，经国际招标后中标的机电产品的进口依照本办法执行。"},{"i":30,"n":"第三十条","txt":"列入《禁止进口货物目录》的旧机电产品，在符合环境保护、安全生产的条件下，经商务部同意，可以进境维修（含再制造）并复出境。 我国驻外机构或者境外企业（中方控股）在境外购置的机电产品需调回自用的，如涉及《禁止进口货物目录》的旧机电产品，在境外购置时若为新品的，经商务部同意，可调回自用。"},{"i":31,"n":"第三十一条","txt":"本办法所称维修，是指通过维护、修理、检测、升级或其他维修处置，使原产品（件）局部受损功能恢复或原有功能升级的生产活动。 本办法所称再制造，是指将主体部分不具备原设计性能但具备循环再生价值的原产品（件）完全拆解，经采用专门的工艺、技术对拆解的零部件进行修复、加工，产业化组装生产出再生成品，恢复或超过原产品（件）性能的生产活动。 本办法所称翻新，是指将主体部分不具备设计性能的原产品（件）通过维护、修理、检测、升级或其他处置，使原件局部受损性能恢复或原有功能升级等；或者将主体部分不具备设计性能的原产品（件）中可利用部分与新的原料、配件一同重新投入进行拆解、修复、加工或组装，恢复原产品（件）基本的使用功能或超过原件性能的活动。"},{"i":32,"n":"第三十二条","txt":"机电产品各类进口管理证件，包括纸质证件或电子证书，可按规定通过提交纸质或电子材料的方式申请。"},{"i":33,"n":"第三十三条","txt":"本办法由商务部、海关总署负责解释。以往有关规定凡与本办法不一致的，以本办法为准。"},{"i":34,"n":"第三十四条","txt":"本办法自二OO八年五月一日起施行。原《机电产品进口管理办法》（外经贸部、海关总署、质检总局2001年第10号令）、《机电产品自动进口许可管理实施细则》（外经贸部2001年第25号令）、《关于加强旧机电产品进口的通知》（国经贸机〔1997〕877号）、《关于加强旧机电产品进口管理的补充通知》（国经贸机〔1998〕555号）、《关于进一步明确加工贸易项下外商提供的不作价进口设备解除海关监管有关问题的通知》（署法发2001年420号）、《关于进一步明确加工贸易项下外商提供的不作价进口设备解除海关监管有关问题的通知》（署法发2002年348号）、《关于“不作价设备”解除监管问题的紧急通知》（署法发〔2002〕1号）、《海关总署办公厅关于明确加工贸易项下进口旧机电产品管理有关问题的通知》（署办法〔2002〕211号）、《关于重申进口旧机电产品有关管理的通知》（国质检联2001年42号）、《关于进"}],"jidianchanpinjinkoupeieguanlishishixize":[{"i":1,"n":"第一条","txt":"为规范机电产品进口配额管理，依据《中华人民共和国货物进出口管理条例》和《机电产品进口管理办法》，制定本细则。"},{"i":2,"n":"第二条","txt":"本细则适用于进口单位将配额机电产品进口到中华人民共和国关境内的行为。"},{"i":3,"n":"第三条","txt":"中华人民共和国对外贸易经济合作部（简称为外经贸部）负责会同海关总署制定、调整和公布机电产品进口配额目录，编制全国年度机电产品进口配额计划并组织实施。"},{"i":4,"n":"第四条","txt":"外经贸部采用电子网络系统或者其他方式，与海关等有关行政管理部门进行数据交换、核查和反馈，负责对全国机电产品进口配额的执行情况进行检查、监督。 各省、自治区、直辖市和计划单列市、沿海开放城市、经济特区外经贸主管机构和国务院有关部门机电产品进出口办公室（简称为地方外经贸主管机构、部门机电办），负责对本地区、本部门机电产品进口配额的执行情况进行检查、监督并向外经贸部报告。"},{"i":5,"n":"第五条","txt":"外经贸部应当于每年7月31日前公布下一年度全国机电产品进口配额总量。 外经贸部可以根据需要对年度机电产品配额总量进行调整，并在实施前21天予以公布。"},{"i":6,"n":"第六条","txt":"申请机电产品进口配额的资格与条件： （一）申请进口单位应当在近三年内没有逃汇、套汇、骗取出口退税、走私等违法、违规行为； （二）申请进口单位应当具有所申请配额产品的经营权； （三）申请进口单位应当具有连续三年进口、销售所申请配额产品的实际有效业绩； （四）申请进口单位应当具有与所申请配额数量相适应的生产、销售、维修、服务和配件供应能力； （五）申请进口单位应当具有良好的财务状况； （六）新增的申请进口单位，可不具备本条（三）项规定的条件； （七）申请自用的可不具备本条（二）、（三）、（四）、（五）项规定的资格与条件，但是应当提交合理的申请理由和适当的配额申请数量。"},{"i":7,"n":"第七条","txt":"进口配额的申请与分配时间： （一）每年8月1日至8月31日，申请进口单位向外经贸部提交下一年度机电产品进口配额申请，逾期不予接受申请； （二）每年10月31日前，外经贸部进行配额分配，向获得配额的申请进口单位签发《机电产品进口配额证明》。"},{"i":8,"n":"第八条","txt":"进口配额的再分配时间： （一）持有配额的进口单位最迟于每年9月1日前，应当将当年不能用完的配额许可证交回外经贸部； （二）外经贸部应当于每年9月1日起的10个工作日内，对交回的配额许可证所载明的配额进行再分配。"},{"i":9,"n":"第九条","txt":"进口配额的分配原则： （一）保障科研、教育、文化、卫生及其他社会公益事业进口自用的需要； （二）优先考虑生产、销售、服务能力强的进口单位的申请； （三）考虑申请进口单位近三年进口该配额产品的实际有效业绩； （四）考虑将年度配额总量的一定比例分配给新增的申请进口单位； （五）上一年度配额全部用完的，如提出要求应当适当增加下一年度配额量；上一年度配额未全部用完，并且在规定期限内没有交回未用完配额的，应当扣减下一年度配额量。 （六）对某些进口配额采用招标方式分配，具体管理办法由外经贸部制定和公布。"},{"i":10,"n":"第十条","txt":"申请《机电产品进口配额证明》的程序： 进口属于配额管理的机电产品，申请进口单位应当如实填写《机电产品进口申请表》（如附件一）一式二份，提供申请报告及其他有关文件，向相关的地方外经贸主管机构、部门机电办办理核实手续。未设立机电办的部门，申请进口单位应当向本单位工商注册地或者法人登记地的地方外经贸主管机构办理核实手续。 经相关的地方外经贸主管机构、部门机电办核实，申请进口单位应当在规定的配额申请期限内持相关文件和《机电产品进口申请表》向外经贸部申领《机电产品进口配额证明》（如附件二）。"},{"i":11,"n":"第十一条","txt":"进口单位持外经贸部签发的《机电产品进口配额证明》申领《进口配额许可证》，申领有效期为《机电产品进口配额证明》签发当年，在有效期内未申领《进口配额许可证》的，《机电产品进口配额证明》失效。"},{"i":12,"n":"第十二条","txt":"《机电产品进口配额证明》一式五联。第一联（蓝色，有防伪底纹）为申领《进口配额许可证》凭证，第二联（白底绿色）为订货凭证，第三联（深红色，有防伪底纹）为海关备案凭证，第四联（白底红色）为银行售、付汇凭证，第五联（白底黑色）为配额管理机关存档。"},{"i":13,"n":"第十三条","txt":"进口单位领取《机电产品进口配额证明》后，在有效期内因特殊原因需要变更《机电产品进口配额证明》中的进口单位、贸易方式、产品用途、产品名称、数量、金额（变化幅度超过10%的）以及设备状态等项目内容的，应当持原《机电产品进口配额证明》到原发证机关申请办理变更、换证手续；原发证机关应当收回旧证，并在换发的新证的备注栏打印\"换证\"字样。实际用汇额不超过原定用汇额10%的，不需变更《机电产品进口配额证明》。进口单位持《机电产品进口配额证明》申领《进口配额许可证》时，不得变更《机电产品进口配额证明》中的进口单位、贸易方式、产品用途、产品名称、数量、金额（变化幅度超过10%的）以及设备状态等项目内容。"},{"i":14,"n":"第十四条","txt":"《机电产品进口配额证明》如有遗失，应当立即向原进口配额管理机关、原许可证管理机关和报关口岸海关三方同时挂失。如无不良后果，进口单位可向外经贸部申请补发。"},{"i":15,"n":"第十五条","txt":"未按本细则规定申请办理《机电产品进口配额证明》及《进口配额许可证》，先行对外签约的，外经贸部不予补办进口配额证明，海关等行政主管部门依据法律、行政法规的规定作出处理。"},{"i":16,"n":"第十六条","txt":"有下列情形之一的，也适用本细则： （一）进口配额产品的零部件，构成整机特征的； （二）加工贸易项下进口配额产品用于生产内销产品或留作自用的； （三）外商投资企业进口配额产品用于生产内销产品或内销的； （四）租赁贸易、补偿贸易等贸易方式进口配额产品的； （五）以无偿援助、捐赠或者经济往来赠送等方式进口配额产品的； （六）我国驻外机构或者境外施工企业在境外购置配额产品，需调回自用的； （七）其他法律、行政法规另有规定的。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，不适用本细则： （一）加工贸易项下进口复出口的； （二）将配额产品进口到我国保税区、出口加工区并用于复出口的； （三）由海关监管，暂时进口配额产品的； （四）外商投资企业投资和自用进口配额产品的； （五）其他法律、行政法规另有规定的。"},{"i":18,"n":"第十八条","txt":"本细则由外经贸部负责解释。过去有关规定凡与本细则不一致的，以本细则为准。"},{"i":19,"n":"第十九条","txt":"本细则自二○○二年一月一日起施行。"}],"minyonghangkonglingbujianchukoufenleiguanlibanfa":[{"i":1,"n":"第一条","txt":"为完善两用物项和技术出口管制，便利民用航空零部件出口，依据《中华人民共和国对外贸易法》和《中华人民共和国导弹及相关物项和技术出口管制条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称民用航空零部件，是指受《中华人民共和国导弹及相关物项和技术出口管制条例》管制、用于民用航空用途的物项（名称及海关编码见《两用物项和技术进出口许可证管理办法》附件1《两用物项和技术进出口许可证管理目录》中\"导弹及相关物项和技术出口管制清单所列物项和技术\"部分）。"},{"i":3,"n":"第三条","txt":"民用航空零部件的出口实行许可证件分类管理制度。 以\"修理物品\"（代码：1300）、\"暂时进出货物\"（代码：2600）、\"保税仓库货物\"（代码：1233）、\"租赁不满一年\"（代码：1500）和\"租赁贸易\"（代码：1523）出口的民用航空零部件，实行出口许可批件管理。 以前款规定的海关监管方式以外的其他方式出口的民用航空零部件，仍按照《两用物项和技术进出口许可证管理办法》（商务部、海关总署2005年第29号令）的规定实行两用物项和技术出口许可证管理。"},{"i":4,"n":"第四条","txt":"民用航空零部件出口经营者（以下简称出口经营者）申请《出口许可批件》，应向商务部提出，并提交以下材料： （一）出口许可申请书； （二）拟出口的民用航空零部件名称（包括所含型号）、生产国和生产商的说明； （三）出口用途、报关口岸、进口国（地区）的情况说明； （四）出口经营者遵守国家出口管制法律法规及相关规定的保证文书； （五）《中华人民共和国导弹及相关物项和技术出口管制条例》要求提交的其他文件。"},{"i":5,"n":"第五条","txt":"商务部收到齐备有效的申请材料后予以受理，对符合条件的申请，在《中华人民共和国导弹及相关物项和技术出口管制条例》规定的审查时限内，颁发《出口许可批件》。 《出口许可批件》应包括载明出口经营者、海关监管方式、进口国（地区）、民用航空零部件名称及海关编码（包括所含型号）、批件有效期和报关口岸（样式见附件）。"},{"i":6,"n":"第六条","txt":"出口经营者凭《出口许可批件》，在批件有效期内可多次办理海关通关手续，报关次数及出口数量不限。"},{"i":7,"n":"第七条","txt":"海关凭商务部颁发的《出口许可批件》原件办理本办法第三条第二款所列民用航空器零部件出口验放手续，并留存《出口许可批件》复印件与报关单一并归档。《出口许可批件》原件退出口经营者或其代理人。"},{"i":8,"n":"第八条","txt":"出口经营者在《出口许可批件》有效期截止后30日内，将其在该《出口许可批件》项下出口的民用航空零部件的出口时间、型号、数量、贸易方式、进口国（地区）、进口商、最终用户、最终用途和报关口岸等有关情况报商务部。"},{"i":9,"n":"第九条","txt":"民用航空零部件出口的有关合同、发票、帐册、单据、记录、文件、业务函电、录音录像制品和其他资料，出口经营者应至少保存5年，以备商务部抽查。"},{"i":10,"n":"第十条","txt":"出口经营者违反本办法规定的，商务部给予警告，处3万元以下罚款。必要时，可依据《中华人民共和国对外贸易法》和相关法律法规，责令其限期改正，撤销其《出口许可批件》，并可在3年内不受理其《出口许可批件》申请，或者禁止其在1年以上3年以下的期限内从事有关货物的出口经营活动。 出口经营者违反相关出口管制法律法规的，依照有关规定进行处罚。"},{"i":11,"n":"第十一条","txt":"本办法由商务部和海关总署按照各自职责负责解释。"},{"i":12,"n":"第十二条","txt":"本办法自公布之日起30日后施行。"}],"qichemaoyizhengce":[{"i":1,"n":"第一条","txt":"为建立统一、开放、竞争、有序的汽车市场，维护汽车消费者合法权益，推进我国汽车产业健康发展，促进消费，扩大内需，特制定本政策。"},{"i":2,"n":"第二条","txt":"国家鼓励发展汽车贸易，引导汽车贸易业统筹规划，合理布局，调整结构，积极运用现代信息技术、物流技术和先进的经营模式，推进电子商务，提高汽车贸易水平，实现集约化、规模化、品牌化及多样化经营。"},{"i":3,"n":"第三条","txt":"为创造公平竞争的汽车市场环境，发挥市场在资源配置中的基础性作用，坚持按社会主义市场经济规律，进一步引入竞争机制，扩大对内对外开放，打破地区封锁，促进汽车商品在全国范围内自由流通。"},{"i":4,"n":"第四条","txt":"引导汽车贸易企业依法、诚信经营，保证商品质量和服务质量，为消费者提供满意的服务。"},{"i":5,"n":"第五条","txt":"为提高我国汽车贸易整体水平， 国家鼓励具有较强的经济实力、先进的商业经营管理经验和营销技术以及完善的国际销售网络的境外投资者投资汽车贸易领域。"},{"i":6,"n":"第六条","txt":"充分发挥行业组织、认证机构、检测机构的桥梁纽带作用，建立和完善独立公正、规范运作的汽车贸易评估、咨询、认证、检测等中介服务体系，积极推进汽车贸易市场化进程。"},{"i":7,"n":"第七条","txt":"积极建立、完善相关法规和制度，加快汽车贸易法制化建设。设立汽车贸易企业应当具备法律、行政法规规定的有关条件，国务院商务主管部门会同有关部门研究制定和完善汽车品牌销售、二手车流通、汽车配件流通、报废汽车回收等管理办法、规范及标准， 依法管理、规范汽车贸易的经营行为，维护公平竞争的市场秩序。"},{"i":8,"n":"第八条","txt":"通过本政策的实施， 基本实现汽车品牌销售和服务，形成多种经营主体与经营模式并存的二手车流通发展格局，汽车及二手车销售和售后服务功能完善、体系健全；汽车配件商品来源、质量和价格公开、透明，假冒伪劣配件商品得到有效遏制，报废汽车回收拆解率显著提高，形成良好的汽车贸易市场秩序。"},{"i":9,"n":"第九条","txt":"到2010年，建立起与国际接轨并具有竞争优势的现代汽车贸易体系，拥有一批具有竞争实力的汽车贸易企业， 贸易额有较大幅度增长，贸易水平显著提高，对外贸易能力明显增强，实现汽车贸易与汽车工业的协调发展。"},{"i":10,"n":"第十条","txt":"境内外汽车生产企业凡在境内销售自产汽车的，应当尽快建立完善的汽车品牌销售和服务体系，确保消费者在购买和使用过程中得到良好的服务， 维护其合法权益。汽车生产企业可以按国家有关规定自行投资或授权汽车总经销商建立品牌销售和服务体系。"},{"i":11,"n":"第十一条","txt":"实施汽车品牌销售和服务。自2005年4月1日起，乘用车实行品牌销售和服务；自2006年12月1日起，除专用作业车外，所有汽车实行品牌销售和服务。 从事汽车品牌销售活动应当先取得汽车生产企业或经其授权的汽车总经销商授权。汽车（包括二手车）经销商应当在工商行政管理部门核准的经营范围内开展汽车经营活动。"},{"i":12,"n":"第十二条","txt":"汽车供应商应当制订汽车品牌销售和服务网络规划。为维护消费者的利益，汽车品牌销售和与其配套的配件供应、售后服务网点相距不得超过150公里。"},{"i":13,"n":"第十三条","txt":"汽车供应商应当加强品牌销售和服务网络的管理，规范销售和服务，在国务院工商行政管理部门备案并向社会公布后，要定期向社会公布其授权和取消授权的汽车品牌销售和服务企业名单，对未经品牌授权或不具备经营条件的经销商不得提供汽车资源。汽车供应商有责任及时向社会公布停产车型，并采取积极措施在合理期限内保证配件供应。"},{"i":14,"n":"第十四条","txt":"汽车供应商和经销商应当通过签订书面合同明确双方的权利和义务。汽车供应商要对经销商提供指导和技术支持，不得要求经销商接受不平等的合作条件，以及强行规定经销数量和进行搭售，不应随意解除与经销商的合作关系。"},{"i":15,"n":"第十五条","txt":"汽车供应商应当按国家有关法律法规以及向消费者的承诺，承担汽车质量保证义务，提供售后服务。 汽车经销商应当在经营场所向消费者明示汽车供应商承诺的汽车质量保证和售后服务，并按其授权经营合同的约定和服务规范要求，提供相应的售后服务。 汽车供应商和经销商不得供应和销售不符合机动车国家安全技术标准、未获国家强制性产品认证、未列入《道路机动车辆生产企业及产品公告》的汽车。进口汽车未按照《中华人民共和国进出口商品检验法》及其实施条例规定检验合格的，不准销售使用。"},{"i":16,"n":"第十六条","txt":"国家鼓励二手车流通。建立竞争机制，拓展流通渠道，支持有条件的汽车品牌经销商等经营主体经营二手车，以及在异地设立分支机构开展连锁经营。"},{"i":17,"n":"第十七条","txt":"积极创造条件，简化二手车交易、转移登记手续，提高车辆合法性与安全性的查询效率，降低交易成本，统一规范交易发票；强化二手车质量管理，推动二手车经销商提供优质售后服务。"},{"i":18,"n":"第十八条","txt":"加快二手车市场的培育和建设，引导二手车交易市场转变观念，强化市场管理，拓展市场服务功能。"},{"i":19,"n":"第十九条","txt":"实施二手车自愿评估制度。除涉及国有资产的车辆外，二手车的交易价格由买卖双方商定，当事人可以自愿委托具有资格的二手车鉴定评估机构进行评估，供交易时参考。除法律、行政法规规定外，任何单位和部门不得强制或变相强制对交易车辆进行评估。"},{"i":20,"n":"第二十条","txt":"积极规范二手车鉴定评估行为。二手车鉴定评估机构应当本着\"\"客观、真实、公正、公开\"\"的原则，依据国家有关法律法规，开展二手车鉴定评估经营活动，出具车辆鉴定评估报告，明确车辆技术状况（包括是否属事故车辆等内容）。"},{"i":21,"n":"第二十一条","txt":"二手车经营、拍卖企业在销售、拍卖二手车时，应当向买方提供真实情况，不得有隐瞒和欺诈行为。所销售和拍卖的车辆必须具有机动车号牌、《机动车登记证书》、《机动车行驶证》、有效的机动车安全技术检验合格标志、车辆保险单和交纳税费凭证等。"},{"i":22,"n":"第二十二条","txt":"二手车经营企业销售二手车时，应当向买方提供质量保证及售后服务承诺。在产品质量责任担保期内的，汽车供应商应当按国家有关法律法规以及向消费者的承诺，承担汽车质量保证和售后服务。"},{"i":23,"n":"第二十三条","txt":"从事二手车拍卖和鉴定评估经营活动应当经省级商务主管部门核准。"},{"i":24,"n":"第二十四条","txt":"国家鼓励汽车配件流通采取特许、连锁经营的方式向规模化、品牌化、网络化方向发展，支持配件流通企业进行整合，实现结构升级，提高规模效应及服务水平。"},{"i":25,"n":"第二十五条","txt":"汽车及配件供应商和经销商应当加强质量管理，提高产品质量及服务质量。 汽车及配件供应商和经销商不得供应和销售不符合国家法律、行政法规、强制性标准及强制性产品认证要求的汽车配件。"},{"i":26,"n":"第二十六条","txt":"汽车及配件供应商应当定期向社会公布认可和取消认可的特许汽车配件经销商名单。 汽车配件经销商应当明示所销售的汽车配件及其它汽车用品的名称、生产厂家、价格等信息，并分别对原厂配件、经汽车生产企业认可的配件、报废汽车回用件及翻新件予以注明。汽车配件产品标识应当符合《产品质量法》的要求。"},{"i":27,"n":"第二十七条","txt":"加快规范报废汽车回用件流通，报废汽车回收拆解企业对按有关规定拆解的可出售配件，必须在配件的醒目位置标明“报废汽车回用件”。"},{"i":28,"n":"第二十八条","txt":"国家实施汽车强制报废制度。根据汽车安全技术状况和不同用途， 修订现行汽车报废标准， 规定不同的强制报废标准。"},{"i":29,"n":"第二十九条","txt":"报废汽车所有人应当将报废汽车及时交售给具有合法资格的报废汽车回收拆解企业。"},{"i":30,"n":"第三十条","txt":"地方商务主管部门要按《报废汽车回收管理办法》（国务院令第307号）的有关要求，对报废汽车回收拆解行业统筹规划，合理布局。 从事报废汽车回收拆解业务，应当具备法律法规规定的有关条件。国务院商务主管部门应当将符合条件的报废汽车回收拆解企业向社会公告。"},{"i":31,"n":"第三十一条","txt":"报废汽车回收拆解企业必须严格按国家有关法律、法规开展业务，及时拆解回收的报废汽车。拆解的发动机、前后桥、变速器、方向机、车架“五大总成”应当作为废钢铁，交售给钢铁企业作为冶炼原料。"},{"i":32,"n":"第三十二条","txt":"各级商务主管部门要会同公安机关建立报废汽车回收管理信息交换制度，实现报废汽车回收过程实时控制，防止报废汽车及其“五大总成”流入社会。"},{"i":33,"n":"第三十三条","txt":"为合理和有效利用资源， 国家适时制定报废汽车回收利用的管理办法。"},{"i":34,"n":"第三十四条","txt":"完善老旧汽车报废更新补贴资金管理办法，鼓励老旧汽车报废更新。"},{"i":35,"n":"第三十五条","txt":"报废汽车回收拆解企业拆解的报废汽车零部件及其它废弃物、有害物（如油、液、电池、有害金属等）的存放、转运、处理等必须符合《环境保护法》、《大气污染防治法》等法律、法规的要求，确保安全、无污染（或使污染降至最低）。"},{"i":36,"n":"第三十六条","txt":"自2005年1月1日起，国家实施汽车自动进口许可管理，所有汽车进口口岸保税区不得存放以进入国内市场为目的的汽车。"},{"i":37,"n":"第三十七条","txt":"国家禁止以任何贸易方式进口旧汽车及其总成、配件和右置方向盘汽车（用于开发出口产品的右置方向盘样车除外）。"},{"i":38,"n":"第三十八条","txt":"进口汽车必须获得国家强制性产品认证证书，贴有认证标志，并须经检验检疫机构抽查检验合格，同时附有中文说明书。"},{"i":39,"n":"第三十九条","txt":"禁止汽车及相关商品进口中的不公平贸易行为。国务院商务主管部门依法对汽车产业实施反倾销、反补贴和保障措施，组织有关行业协会建立和完善汽车产业损害预警系统， 并开展汽车产业竞争力调查研究工作。汽车供应商和经销商有义务及时准确地向国务院有关部门提供相关信息。"},{"i":40,"n":"第四十条","txt":"鼓励发展汽车及相关商品的对外贸易。支持培育和发展国家汽车及零部件出口基地，引导有条件的汽车供应商和经销商采取多种方式在国外建立合资、合作、独资销售及服务网络，优化出口商品结构，加大开拓国际市场的力度。"},{"i":41,"n":"第四十一条","txt":"利用中央外贸发展基金支持汽车及相关商品对外贸易发展。"},{"i":42,"n":"第四十二条","txt":"汽车及相关商品的出口供应商和经销商应当根据出口地区相关法规建立必要的销售和服务体系。"},{"i":43,"n":"第四十三条","txt":"加强政府间磋商，支持汽车及相关商品出口供应商参与反倾销、反补贴和保障措施的应诉，维护我国汽车及相关商品出口供应商的合法权益。"},{"i":44,"n":"第四十四条","txt":"汽车行业组织要加强行业自律，建立竞争有序的汽车及相关商品对外贸易秩序。"},{"i":45,"n":"第四十五条","txt":"设立外商投资汽车贸易企业，除符合相应的资质条件外，还应当符合外商投资有关法律法规，并经省级商务主管部门初审后报国务院商务主管部门审批。"},{"i":46,"n":"第四十六条","txt":"加快发展和扩大汽车消费信贷，支持有条件的汽车供应商建立面向全行业的汽车金融公司，引导汽车金融机构与其他金融机构建立合作机制，使汽车消费信贷市场规模化、专业化程度显著提高，风险管理体系更加完善。"},{"i":47,"n":"第四十七条","txt":"完善汽车保险市场， 鼓励汽车保险品种向个性化与多样化方向发展，提高汽车保险服务水平，初步实现汽车保险业专业化、集约化经营。"},{"i":48,"n":"第四十八条","txt":"各地政府制定的与汽车贸易相关的各种政策、制度和规定要符合本政策要求并做到公开、透明，不得对非本地生产和交易的汽车在流通、服务、使用等方面实施歧视政策， 坚决制止强制或变相强制本地消费者购买本地生产汽车，以及以任何方式干预经营者选择国家许可生产、销售的汽车的行为。"},{"i":49,"n":"第四十九条","txt":"本政策自发布之日起实施，由国务院商务主管部门负责解释。 附：汽车贸易政策使用术语说明 一、“汽车贸易”包括新车销售、二手车流通、汽车配件流通、汽车报废与报废汽车回收、汽车对外贸易等方面。 二、除涉及汽车品牌销售外，本政策所称“汽车”包括低速载货汽车、三轮汽车（原农用运输车）、挂车和摩托车。 三、“二手车”是指从办理完注册登记手续到达到国家强制报废标准之前进行交易并转移所有权的汽车。 四、“供应商”是指汽车或汽车配件生产企业及其总经销商。 五、“经销商”是指汽车或配件零售商。"}],"qichexiaoshouguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进汽车市场健康发展，维护公平公正的市场秩序，保护消费者合法权益，根据国家有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事汽车销售及其相关服务活动，适用本办法。 从事汽车销售及其相关服务活动应当遵循合法、自愿、公平、诚信的原则。"},{"i":3,"n":"第三条","txt":"本办法所称汽车，是指《汽车和挂车类型的术语和定义》(GB/T 3730.1)定义的汽车，且在境内未办理注册登记的新车。"},{"i":4,"n":"第四条","txt":"国家鼓励发展共享型、节约型、社会化的汽车销售和售后服务网络，加快城乡一体的汽车销售和售后服务网络建设，加强新能源汽车销售和售后服务网络建设，推动汽车流通模式创新。"},{"i":5,"n":"第五条","txt":"在境内销售汽车的供应商、经销商，应当建立完善汽车销售和售后服务体系，保证相应的配件供应，提供及时、有效的售后服务，严格遵守家用汽车产品“三包”、召回等规定，确保消费者合法权益。"},{"i":6,"n":"第六条","txt":"本办法所称供应商，是指为经销商提供汽车资源的境内生产企业或接受境内生产企业转让销售环节权益并进行分销的经营者以及从境外进口汽车的经营者。 本办法所称经销商，是指获得汽车资源并进行销售的经营者。 本办法所称售后服务商，是指汽车销售后提供汽车维护、修理等服务活动的经营者。"},{"i":7,"n":"第七条","txt":"国务院商务主管部门负责制定全国汽车销售及其相关服务活动的政策规章，对地方商务主管部门的监督管理工作进行指导、协调和监督。 县级以上地方商务主管部门依据本办法对本行政区域内汽车销售及其相关服务活动进行监督管理。"},{"i":8,"n":"第八条","txt":"汽车行业协会、商会应当制定行业规范，提供信息咨询、宣传培训等服务，开展行业监测和预警分析，加强行业自律。"},{"i":9,"n":"第九条","txt":"供应商、经销商销售汽车、配件及其他相关产品应当符合国家有关规定和标准，不得销售国家法律、法规禁止交易的产品。"},{"i":10,"n":"第十条","txt":"经销商应当在经营场所以适当形式明示销售汽车、配件及其他相关产品的价格和各项服务收费标准，不得在标价之外加价销售或收取额外费用。"},{"i":11,"n":"第十一条","txt":"经销商应当在经营场所明示所出售的汽车产品质量保证、保修服务及消费者需知悉的其他售后服务政策，出售家用汽车产品的经销商还应当在经营场所明示家用汽车产品的“三包”信息。"},{"i":12,"n":"第十二条","txt":"经销商出售未经供应商授权销售的汽车，或者未经境外汽车生产企业授权销售的进口汽车，应当以书面形式向消费者作出提醒和说明，并书面告知向消费者承担相关责任的主体。 未经供应商授权或者授权终止的，经销商不得以供应商授权销售汽车的名义从事经营活动。"},{"i":13,"n":"第十三条","txt":"售后服务商应当向消费者明示售后服务的技术、质量和服务规范。"},{"i":14,"n":"第十四条","txt":"供应商、经销商不得限定消费者户籍所在地，不得对消费者限定汽车配件、用品、金融、保险、救援等产品的提供商和售后服务商，但家用汽车产品“三包”服务、召回等由供应商承担费用时使用的配件和服务除外。 经销商销售汽车时不得强制消费者购买保险或者强制为其提供代办车辆注册登记等服务。"},{"i":15,"n":"第十五条","txt":"经销商向消费者销售汽车时，应当核实登记消费者的有效身份证明，签订销售合同，并如实开具销售发票。"},{"i":16,"n":"第十六条","txt":"供应商、经销商应当在交付汽车的同时交付以下随车凭证和文件，并保证车辆配置表述与实物配置相一致： （一）国产汽车的机动车整车出厂合格证； （二）使用国产底盘改装汽车的机动车底盘出厂合格证； （三）进口汽车的货物进口证明和进口机动车检验证明等材料； （四）车辆一致性证书，或者进口汽车产品特殊认证模式检验报告； （五）产品中文使用说明书； （六）产品保修、维修保养手册； （七）家用汽车产品“三包”凭证。"},{"i":17,"n":"第十七条","txt":"经销商、售后服务商销售或者提供配件应当如实标明原厂配件、质量相当配件、再制造件、回用件等，明示生产商（进口产品为进口商）、生产日期、适配车型等信息，向消费者销售或者提供原厂配件以外的其他配件时，应当予以提醒和说明。 列入国家强制性产品认证目录的配件，应当取得国家强制性产品认证并加施认证标志后方可销售或者在售后服务经营活动中使用，依据国家有关规定允许办理免于国家强制性产品认证的除外。 本办法所称原厂配件，是指汽车生产商提供或认可的，使用汽车生产商品牌或其认可品牌，按照车辆组装零部件规格和产品标准制造的零部件。 本办法所称质量相当配件，是指未经汽车生产商认可的，由配件生产商生产的，且性能和质量达到原厂配件相关技术标准要求的零部件。 本办法所称再制造件，是指旧汽车零部件经过再制造技术、工艺生产后，性能和质量达到原型新品要求的零部件。 本办法所称回用件，是指从报废汽车上拆解或维修车辆上替换的能"},{"i":18,"n":"第十八条","txt":"供应商、经销商应当建立健全消费者投诉制度，明确受理消费者投诉的具体部门和人员，并向消费者明示投诉渠道。投诉的受理、转交以及处理情况应当自收到投诉之日起7个工作日内通知投诉的消费者。"},{"i":19,"n":"第十九条","txt":"供应商采取向经销商授权方式销售汽车的，授权期限（不含店铺建设期）一般每次不低于3年，首次授权期限一般不低于5年。双方协商一致的，可以提前解除授权合同。"},{"i":20,"n":"第二十条","txt":"供应商应当向经销商提供相应的营销、宣传、售后服务、技术服务等业务培训及技术支持。 供应商、经销商应当在本企业网站或经营场所公示与其合作的售后服务商名单。"},{"i":21,"n":"第二十一条","txt":"供应商不得限制配件生产商（进口产品为进口商）的销售对象，不得限制经销商、售后服务商转售配件，有关法律法规规章及其配套的规范性文件另有规定的除外。 供应商应当及时向社会公布停产或者停止销售的车型，并保证其后至少10年的配件供应以及相应的售后服务。"},{"i":22,"n":"第二十二条","txt":"未违反合同约定被供应商解除授权的，经销商有权要求供应商按不低于双方认可的第三方评估机构的评估价格收购其销售、检测和维修等设施设备，并回购相关库存车辆和配件。"},{"i":23,"n":"第二十三条","txt":"供应商发生变更时，应当妥善处理相关事宜，确保经销商和消费者的合法权益。 经销商不再经营供应商产品的，应当将客户、车辆资料和维修历史记录在授权合同终止后30日内移交给供应商，不得实施有损于供应商品牌形象的行为；家用汽车产品经销商不再经营供应商产品时，应当及时通知消费者，在供应商的配合下变更承担“三包”责任的经销商。供应商、承担“三包”责任的经销商应当保证为消费者继续提供相应的售后服务。"},{"i":24,"n":"第二十四条","txt":"供应商可以要求经销商为本企业品牌汽车设立单独展区，满足经营需要和维护品牌形象的基本功能，但不得对经销商实施下列行为： （一）要求同时具备销售、售后服务等功能； （二）规定整车、配件库存品种或数量，或者规定汽车销售数量，但双方在签署授权合同或合同延期时就上述内容书面达成一致的除外； （三）限制经营其他供应商商品； （四）限制为其他供应商的汽车提供配件及其他售后服务； （五）要求承担以汽车供应商名义实施的广告、车展等宣传推广费用，或者限定广告宣传方式和媒体； （六）限定不合理的经营场地面积、建筑物结构以及有偿设计单位、建筑单位、建筑材料、通用设备以及办公设施的品牌或者供应商； （七）搭售未订购的汽车、配件及其他商品； （八）干涉经销商人力资源和财务管理以及其他属于经销商自主经营范围内的活动； （九）限制本企业汽车产品经销商之间相互转售。"},{"i":25,"n":"第二十五条","txt":"供应商制定或实施营销奖励等商务政策应当遵循公平、公正、透明的原则。 供应商应当向经销商明确商务政策的主要内容，对于临时性商务政策，应当提前以双方约定的方式告知；对于被解除授权的经销商，应当维护经销商在授权期间应有的权益，不得拒绝或延迟支付销售返利。"},{"i":26,"n":"第二十六条","txt":"除双方合同另有约定外, 供应商在经销商获得授权销售区域内不得向消费者直接销售汽车。"},{"i":27,"n":"第二十七条","txt":"供应商、经销商应当自取得营业执照之日起90日内通过国务院商务主管部门全国汽车流通信息管理系统备案基本信息。供应商、经销商备案的基本信息发生变更的，应当自信息变更之日起30日内完成信息更新。 本办法实施以前已设立的供应商、经销商应当自本办法实施之日起90日内按前款规定备案基本信息。 供应商、经销商应当按照国务院商务主管部门的要求，及时通过全国汽车流通信息管理系统报送汽车销售数量、种类等信息。"},{"i":28,"n":"第二十八条","txt":"经销商应当建立销售汽车、用户等信息档案，准确、及时地反映本区域销售动态、用户要求和其他相关信息。汽车销售、用户等信息档案保存期不得少于10年。"},{"i":29,"n":"第二十九条","txt":"县级以上地方商务主管部门应当依据职责，采取“双随机”办法对汽车销售及其相关服务活动实施日常监督检查。 监督检查可以采取下列措施： （一）进入供应商、经销商从事经营活动的场所进行现场检查； （二）询问与监督检查事项有关的单位和个人，要求其说明情况； （三）查阅、复制有关文件、资料，检查相关数据信息系统及复制相关信息数据； （四）依据国家有关规定采取的其他措施。"},{"i":30,"n":"第三十条","txt":"县级以上地方商务主管部门应当会同有关部门建立企业信用记录，纳入全国统一的信用信息共享交换平台。对供应商、经销商有关违法违规行为依法作出处理决定的，应当录入信用档案，并及时向社会公布。"},{"i":31,"n":"第三十一条","txt":"供应商、经销商应当配合政府有关部门开展走私、盗抢、非法拼装等嫌疑车辆调查，提供车辆相关信息。"},{"i":32,"n":"第三十二条","txt":"违反本办法第十条、第十二条、第十四条、第十七条第一款、第二十一条、第二十三条第二款、第二十四条、第二十五条、第二十六条有关规定的，由县级以上地方商务主管部门责令改正，并可给予警告或3万元以下罚款。"},{"i":33,"n":"第三十三条","txt":"违反本办法第十一条、第十五条、第十八条、第二十条第二款、第二十七条、第二十八条有关规定的，由县级以上地方商务主管部门责令改正，并可给予警告或1万元以下罚款。"},{"i":34,"n":"第三十四条","txt":"县级以上商务主管部门的工作人员在汽车销售及其相关服务活动监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"省级商务主管部门可结合本地区实际情况制定本办法的实施细则，并报国务院商务主管部门备案。"},{"i":36,"n":"第三十六条","txt":"供应商通过平行进口方式进口汽车按照平行进口相关规定办理。"},{"i":37,"n":"第三十七条","txt":"本办法自2017年7月1日起施行。"}],"xiranyeguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为规范洗染服务行为，维护经营者和消费者的合法权益，防止环境污染，促进洗染行业健康发展，根据国家有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事洗染经营活动，适用本办法。 本办法所称洗染，是指从事衣物洗涤、熨烫、染色、织补以及皮革制品和裘皮服装的清洗、保养等服务的经营行为。"},{"i":3,"n":"第三条","txt":"商务部对全国洗染行业进行指导、协调、监督和管理，地方各级商务主管部门负责本行政区域内洗染行业指导、协调、监督和管理工作。 工商行政管理部门负责洗染企业的登记注册,依法监管服务产品质量和经营行为，依法查处侵害消费者合法权益的违法行为。 环保部门负责对洗染企业开设和经营过程中影响环境的行为进行监督管理，依法查处其环境违法行为。"},{"i":4,"n":"第四条","txt":"开设洗染店、水洗厂应在安全、卫生、环保、节水、节能等方面符合国家相关法律规定和标准要求。 新建或改建、扩建洗染店应当使用具有净化回收干洗溶剂功能的全封闭式干洗机。 逐步淘汰开启式干洗机。现有洗染店使用开启式干洗机的，必须进行改装，增加压缩机制冷回收系统，强制回收干洗溶剂；使用开启式石油衍生溶剂干洗机和烘干机的，还须配备防火、防爆的安全装置。"},{"i":5,"n":"第五条","txt":"新建或改、扩建洗染店、水洗厂应依法进行环境影响评价，并经环保部门验收合格后，方可投入使用。 从事洗染经营活动的经营者，应当依法进行工商登记，领取营业执照。 经营者应当在取得营业执照后60日内，向登记注册地工商行政管理部门的同级商务主管部门办理备案。"},{"i":6,"n":"第六条","txt":"经营者应当具有固定的营业场所，配备与经营规模相适应并符合国家有关规定的专用洗染、保管、污染防治等设施设备。"},{"i":7,"n":"第七条","txt":"洗染店不得使用不符合国家有关规定的干洗溶剂。干洗溶剂储存、使用、回收场所应具备防渗漏条件，属于危险化学品的，应符合危险化学品管理的有关规定。 鼓励水洗厂使用无磷、低磷洗涤用品。"},{"i":8,"n":"第八条","txt":"洗染业污染物的排放应当达到国家或地方规定的污染物排放标准的要求。新的行业污染物排放标准出台后，应执行新的行业排放标准。 干洗中产生的含有干洗溶剂的残渣、废水应进行妥善收集、处理，属于危险废物的，应依法委托持有危险废物经营许可证的单位进行处理、处置。 外排废水排入城市污水管网进行集中处理的，应当符合相应污水处理厂对进水水质的要求。有废水处理设施的，应对产生的污泥进行无害化处理。 不得将不符合排放标准的废水直接排放到河流、湖泊、雨水管线、渗坑、渗井等。 洗染店、水洗厂的厂界噪声应当符合《工业企业厂界噪声标准》（GB12348-90）相应区域的规定标准。"},{"i":9,"n":"第九条","txt":"经营者应当制定符合有关法律法规要求的安全生产、环境保护和卫生管理制度，为员工提供有效的防护用品，定期对员工进行安全、环保和卫生教育、培训。"},{"i":10,"n":"第十条","txt":"从业人员应当信守职业道德，遵守国家法律法规；洗染技术人员应当具备相应的专业技能，鼓励洗染技术人员取得国家有关部门颁发的资格证书或有关组织及机构颁发的培训合格证书，持证上岗。"},{"i":11,"n":"第十一条","txt":"经营者应当在营业场所醒目位置上悬挂营业执照，明示服务项目、服务价格以及投诉电话等。"},{"i":12,"n":"第十二条","txt":"经营者在经营过程中应遵循诚实信用原则，对消费者提出或询问的有关问题，做出真实明确的答复，不得欺骗和误导消费者，不得从事下列欺诈行为： （一）虚假宣传； （二）利用储值卡进行消费欺诈； （三）以\"水洗\"、\"单烫\"冒充干洗等欺骗行为； （四）故意掩饰在加工过程中使衣物损伤的事实； （五）其他违反法律、行政法规的欺诈行为。"},{"i":13,"n":"第十三条","txt":"经营者在接收衣物时应当对衣物状况进行认真检验，履行下列责任： （一）提示消费者检查衣袋内是否有遗留物品，确认衣物附件、饰物是否齐全； （二）提示消费者易损、易腐蚀及贵重饰物或附件，明确服务责任； （三）将衣物的新旧、脏净、破损程度和织物面料质地、性能变化程度的洗染效果向消费者说明； （四）对确实不易洗染或有不能除净的牢固性污渍，应当告知消费者，确认洗染效果。"},{"i":14,"n":"第十四条","txt":"经营者可以根据消费者意愿实行保值清洗，即由经营者和消费者协商一致做出书面清洗约定，约定清洗费用、保值额和服务内容。 对实行保值清洗的衣物，因经营者责任造成损坏、丢失的，或者清洗后直接影响衣物原有质量而无法恢复的，经营者应当根据与消费者约定的保值额予以赔偿。"},{"i":15,"n":"第十五条","txt":"经营者在提供服务时应当向消费者开具服务单据。服务单据应包括：衣物名称、数量、颜色、破损或缺件状况，服务内容，价格，送取日期，保管期，双方约定事宜，争议解决方式等内容。"},{"i":16,"n":"第十六条","txt":"经营者应当执行洗染行业服务规范、操作规程和质量标准，并指定专人负责洗染质量检验工作。"},{"i":17,"n":"第十七条","txt":"经营者应当规范各工序衣物交接手续，防止丢失或损坏；对于脏、净衣物的存放和收付应当分离。"},{"i":18,"n":"第十八条","txt":"医疗卫生单位的纺织品洗涤应在专门洗涤厂区、专用洗涤设备进行加工，并严格进行消毒处理。 经消毒、洗涤后的纺织品应符合国家有关卫生要求。"},{"i":19,"n":"第十九条","txt":"因经营者责任，洗染后的衣物未能达到洗染质量要求或不符合与消费者事先约定要求的，或者造成衣物损坏、丢失的，经营者应当根据不同情况给予重新加工、退还洗染费或者赔偿损失。 非经营者过错，由于洗涤标识误导或衣物制作及质量不符合国家和行业标准要求，造成未能达到洗染质量标准的，经营者不承担责任。"},{"i":20,"n":"第二十条","txt":"商务主管部门应当通过制定行业发展规划、促进政策、标准和综合协调、指导行业协会工作等方式，规范洗染市场秩序，促进行业发展。 商务主管部门引导和支持成立洗染质量鉴定委员会，开展洗染质量鉴定工作；引导相关行业组织制定洗染行业消费纠纷争议的解决办法，维护经营者和消费者合法权益。"},{"i":21,"n":"第二十一条","txt":"洗染行业协会应当接受商务主管部门的业务指导，加强行业自律；开展倡导诚信经营、组织实施标准、提供信息咨询、开展技术培训、调解服务纠纷、反映经营者建议和要求等促进行业发展工作。"},{"i":22,"n":"第二十二条","txt":"经营者违反本办法规定，法律法规有规定的，从其规定；没有规定的，由商务、工商、环保部门依据本办法第三条规定的职能责令改正，有违法所得的，可处违法所得3倍以下罚款，但最高不超过3万元；没有违法所得的，可处1万元以下罚款；并可予以公告。"},{"i":23,"n":"第二十三条","txt":"各省、自治区、直辖市商务主管部门可以依据本办法，结合本行政区域内的洗染行业实际情况，会同有关部门制定相关的实施办法。"},{"i":24,"n":"第二十四条","txt":"本办法下列用语的定义 全封闭式干洗机：是指以四氯乙烯或石油衍生溶剂作为干洗溶剂，配置溶剂回收制冷系统，在除臭过程中，机器内气体和工作场所气体不进行交换，不直接外排废气的干洗机。 开启式干洗机：是指以四氯乙烯或石油衍生溶剂作为干洗溶剂，采用水冷回收系统，在打开装卸门之前，通过吸入新鲜空气排出机器内干洗溶剂气体混合物进行除臭过程的干洗机。 染色：仅指洗染店对服装的复染或改染服务。"},{"i":25,"n":"第二十五条","txt":"本办法自2007年7月1日起实施。"}],"xiranyeguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范洗染服务行为，维护经营者和消费者的合法权益，防止环境污染，促进洗染行业健康发展，根据国家有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事洗染经营活动，适用本办法。 本办法所称洗染，是指从事衣物洗涤、熨烫、染色、织补以及皮革制品和裘皮服装的清洗、保养等服务的经营行为。"},{"i":3,"n":"第三条","txt":"商务部对全国洗染行业进行指导、协调、监督和管理，地方各级商务主管部门负责本行政区域内洗染行业指导、协调、监督和管理工作。 工商行政管理部门负责洗染企业的登记注册，依法监管服务产品质量和经营行为，依法查处侵害消费者合法权益的违法行为。 环保部门负责对洗染企业开设和经营过程中影响环境的行为进行监督管理，依法查处其环境违法行为。"},{"i":4,"n":"第四条","txt":"开设洗染店、水洗厂应在安全、卫生、环保、节水、节能等方面符合国家相关法律规定和标准要求。 新建或改建、扩建洗染店应当使用具有净化回收干洗溶剂功能的全封闭式干洗机。 逐步淘汰开启式干洗机。现有洗染店使用开启式干洗机的，必须进行改装，增加压缩机制冷回收系统，强制回收干洗溶剂；使用开启式石油衍生溶剂干洗机和烘干机的，还须配备防火、防爆的安全装置。"},{"i":5,"n":"第五条","txt":"新建或改、扩建洗染店、水洗厂应依法进行环境影响评价，并经环保部门验收合格后，方可投入使用。 从事洗染经营活动的经营者，应当依法进行工商登记，领取营业执照。 经营者应当在取得营业执照后60日内，向登记注册地工商行政管理部门的同级商务主管部门办理备案。"},{"i":6,"n":"第六条","txt":"经营者应当具有固定的营业场所，配备与经营规模相适应并符合国家有关规定的专用洗染、保管、污染防治等设施设备。"},{"i":7,"n":"第七条","txt":"洗染店不得使用不符合国家有关规定的干洗溶剂。干洗溶剂储存、使用、回收场所应具备防渗漏条件，属于危险化学品的，应符合危险化学品管理的有关规定。 鼓励水洗厂使用无磷、低磷洗涤用品。"},{"i":8,"n":"第八条","txt":"洗染业污染物的排放应当达到国家或地方规定的污染物排放标准的要求。新的行业污染物排放标准出台后，应执行新的行业排放标准。 干洗中产生的含有干洗溶剂的残渣、废水应进行妥善收集、处理，属于危险废物的，应依法委托持有危险废物经营许可证的单位进行处理、处置。 外排废水排入城市污水管网进行集中处理的，应当符合相应污水处理厂对进水水质的要求。有废水处理设施的，应对产生的污泥进行无害化处理。 不得将不符合排放标准的废水直接排放到河流、湖泊、雨水管线、渗坑、渗井等。 洗染店、水洗厂的厂界噪声应当符合《工业企业厂界噪声标准》（GB12348-90）相应区域的规定标准。"},{"i":9,"n":"第九条","txt":"经营者应当制定符合有关法律法规要求的安全生产、环境保护和卫生管理制度，为员工提供有效的防护用品，定期对员工进行安全、环保和卫生教育、培训。"},{"i":10,"n":"第十条","txt":"从业人员应当信守职业道德，遵守国家法律法规；洗染技术人员应当具备相应的专业技能，鼓励洗染技术人员取得国家有关部门颁发的资格证书或有关组织及机构颁发的培训合格证书，持证上岗。"},{"i":11,"n":"第十一条","txt":"经营者应当在营业场所醒目位置上悬挂营业执照，明示服务项目、服务价格以及投诉电话等。"},{"i":12,"n":"第十二条","txt":"经营者在经营过程中应遵循诚实信用原则，对消费者提出或询问的有关问题，做出真实明确的答复，不得欺骗和误导消费者，不得从事下列欺诈行为： （一）虚假宣传； （二）利用储值卡进行消费欺诈； （三）以\"水洗\"、\"单烫\"冒充干洗等欺骗行为； （四）故意掩饰在加工过程中使衣物损伤的事实； （五）其他违反法律、行政法规的欺诈行为。"},{"i":13,"n":"第十三条","txt":"经营者在接收衣物时应当对衣物状况进行认真检验，履行下列责任： （一）提示消费者检查衣袋内是否有遗留物品，确认衣物附件、饰物是否齐全； （二）提示消费者易损、易腐蚀及贵重饰物或附件，明确服务责任； （三）将衣物的新旧、脏净、破损程度和织物面料质地、性能变化程度的洗染效果向消费者说明； （四）对确实不易洗染或有不能除净的牢固性污渍，应当告知消费者，确认洗染效果。"},{"i":14,"n":"第十四条","txt":"经营者可以根据消费者意愿实行保值清洗，即由经营者和消费者协商一致做出书面清洗约定，约定清洗费用、保值额和服务内容。 对实行保值清洗的衣物，因经营者责任造成损坏、丢失的，或者清洗后直接影响衣物原有质量而无法恢复的，经营者应当根据与消费者约定的保值额予以赔偿。"},{"i":15,"n":"第十五条","txt":"经营者在提供服务时应当向消费者开具服务单据。服务单据应包括：衣物名称、数量、颜色、破损或缺件状况，服务内容，价格，送取日期，保管期，双方约定事宜，争议解决方式等内容。"},{"i":16,"n":"第十六条","txt":"经营者应当执行洗染行业服务规范、操作规程和质量标准，并指定专人负责洗染质量检验工作。"},{"i":17,"n":"第十七条","txt":"经营者应当规范各工序衣物交接手续，防止丢失或损坏；对于脏、净衣物的存放和收付应当分离。"},{"i":18,"n":"第十八条","txt":"医疗卫生单位的纺织品洗涤应在专门洗涤厂区、专用洗涤设备进行加工，并严格进行消毒处理。 经消毒、洗涤后的纺织品应符合国家有关卫生要求。"},{"i":19,"n":"第十九条","txt":"因经营者责任，洗染后的衣物未能达到洗染质量要求或不符合与消费者事先约定要求的，或者造成衣物损坏、丢失的，经营者应当根据不同情况给予重新加工、退还洗染费或者赔偿损失。 非经营者过错，由于洗涤标识误导或衣物制作及质量不符合国家和行业标准要求，造成未能达到洗染质量标准的，经营者不承担责任。"},{"i":20,"n":"第二十条","txt":"商务主管部门应当通过制定行业发展规划、促进政策、标准和综合协调、指导行业协会工作等方式，规范洗染市场秩序，促进行业发展。 商务主管部门引导和支持成立洗染质量鉴定委员会，开展洗染质量鉴定工作；引导相关行业组织制定洗染行业消费纠纷争议的解决办法，维护经营者和消费者合法权益。"},{"i":21,"n":"第二十一条","txt":"洗染行业协会应当接受商务主管部门的业务指导，加强行业自律；开展倡导诚信经营、组织实施标准、提供信息咨询、开展技术培训、调解服务纠纷、反映经营者建议和要求等促进行业发展工作。"},{"i":22,"n":"第二十二条","txt":"经营者违反本办法规定，法律法规有规定的，从其规定；没有规定的，由商务、工商、环保部门依据本办法第三条规定的职能责令改正，有违法所得的，可处违法所得3倍以下罚款，但最高不超过3万元；没有违法所得的，可处1万元以下罚款；并可予以公告。"},{"i":23,"n":"第二十三条","txt":"各省、自治区、直辖市商务主管部门可以依据本办法，结合本行政区域内的洗染行业实际情况，会同有关部门制定相关的实施办法。"},{"i":24,"n":"第二十四条","txt":"本办法下列用语的定义 全封闭式干洗机：是指以四氯乙烯或石油衍生溶剂作为干洗溶剂，配置溶剂回收制冷系统，在除臭过程中，机器内气体和工作场所气体不进行交换，不直接外排废气的干洗机。 开启式干洗机：是指以四氯乙烯或石油衍生溶剂作为干洗溶剂，采用水冷回收系统，在打开装卸门之前，通过吸入新鲜空气排出机器内干洗溶剂气体混合物进行除臭过程的干洗机。 染色：仅指洗染店对服装的复染或改染服务。"},{"i":25,"n":"第二十五条","txt":"本办法自2007年7月1日起实施。"}],"hainanziyoumaoyigangkuajingfuwumaoyitebieguanlicuob4278a":[],"shenghuobixupinshichanggongyingyingjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了有效监测、及时控制和消除因突发事件引发的生活必需品市场异常波动，满足居民日常基本生活需要，维护正常的社会秩序，促进社会主义市场经济持续稳定健康发展，依据《中华人民共和国突发事件应对法》、《中华人民共和国传染病防治法》、《中华人民共和国国防法》、《中华人民共和国价格法》、《中华人民共和国防震减灾法》和《突发公共卫生事件应急条例》等有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称生活必需品市场异常波动（以下简称市场异常波动），是指因突然发生的自然灾害、事故灾难、公共卫生事件、社会安全事件或其他事件，造成肉类、蔬菜、蛋品、奶制品、边销茶和卫生清洁用品等生活必需品市场供求关系突变，在较大范围内导致价格异常波动或商品脱销、滞销的状态。"},{"i":3,"n":"第三条","txt":"本办法规定的市场异常波动按照影响范围大小，分为四级：一级市场异常波动是指全国或跨省、自治区、直辖市的市场异常波动；二级市场异常波动是指发生在一个省、自治区、直辖市较大范围或一个计划单列市、省会城市的市场异常波动；三级市场异常波动是指发生在一个设区的市较大范围的市场异常波动；四级市场异常波动是指发生在一个县内的市场异常波动。"},{"i":4,"n":"第四条","txt":"生活必需品市场供应应急管理工作应当遵循统一协调、分级负责、分类管理、做好预案、科学监测、及时反应、处置得力的原则。"},{"i":5,"n":"第五条","txt":"商务部成立由部长担任总指挥、分管部领导担任副总指挥的商务部应对市场异常波动指挥部，负责对全国市场异常波动应急管理工作的统一领导、组织和协调。 县级以上地方商务主管部门要成立由主要负责人担任总指挥、分管负责人担任副总指挥的应对市场异常波动指挥部，负责领导、指挥本行政区域内市场异常波动应急管理工作。"},{"i":6,"n":"第六条","txt":"县级以上商务主管部门应当建立严格的市场异常波动防范和处置责任制，加强市场异常波动信息交流和区域合作，加强生活必需品市场供应应急管理培训，建立完善市场异常波动监测系统和必要的应急措施及手段，并保证经费。"},{"i":7,"n":"第七条","txt":"县级以上商务主管部门，可对参加市场异常波动应急处理作出贡献的单位和人员，给予表彰和奖励。"},{"i":8,"n":"第八条","txt":"商务部制定全国和跨省、自治区、直辖市生活必需品市场供应应急预案。 县级以上地方商务主管部门，根据全国和跨省、自治区、直辖市生活必需品市场供应应急预案，会同有关部门，结合本地实际，制定本行政区域的生活必需品市场供应应急预案，并报上一级商务主管部门备案。 县级以上地方商务主管部门应要求有关经营生活必需品的大型批发、零售企业制定与当地生活必需品市场供应应急预案相衔接的应急方案并向其备案。"},{"i":9,"n":"第九条","txt":"生活必需品市场供应应急预案应当包括以下主要内容： （一）应对市场异常波动指挥部的组成，及相关部门的具体职责和分工； （二）市场日常监测机构的运行，监测数据的综合评价、预警标准及市场异常波动的报告、通报制度； （三）应对市场异常波动具体程序及拟采取的措施； （四) 应对市场异常波动的生活必需品货源组织、投放及销售网络； （五）相关保障工作，如新闻发布、应急知识的宣传普及、市场监管、人力、资金、交通运输及保障应急预案落到实处的各项具体措施等； （六）应对市场异常波动的值班制度和联络方式。"},{"i":10,"n":"第十条","txt":"生活必需品市场供应应急预案应当根据市场变化和实施中发现的问题及时修订、补充。"},{"i":11,"n":"第十一条","txt":"各级商务主管部门要增强对市场异常波动的防范意识和应对能力，防范市场异常波动的发生。"},{"i":12,"n":"第十二条","txt":"各省、自治区、直辖市、计划单列市、省会城市商务主管部门，应当根据生活必需品市场供应应急预案的要求，建立完善生活必需品、应急设施、设备等物资储备制度。"},{"i":13,"n":"第十三条","txt":"商务部负责建立完善全国生活必需品数据库，掌握生活必需品生产能力、价格、库存等基本信息。"},{"i":14,"n":"第十四条","txt":"县级以上地方商务主管部门应当完善以大型批发、零售企业为主体的应急设施、设备、生活必需品等物资投放网络。积极协调有关部门，建立健全紧急调运机制，确保运输畅通。"},{"i":15,"n":"第十五条","txt":"商务部负责建立全国统一的生活必需品市场监测预警体系，实现信息共享。 县级以上地方商务主管部门，应当定期开展市场调查，及时掌握市场总需求、总供给(现有库存、本地生产能力、外地可采购能力)和销售、价格变化情况；指导列入全国生活必需品市场监测预警范围的样本企业准确、及时填报信息。"},{"i":16,"n":"第十六条","txt":"商务部根据国民经济发展状况和居民生活消费需求的变化，负责确定和调整需要监测的生活必需品品种。 县级以上地方商务主管部门可根据当地居民消费实际情况，适当增加监测的生活必需品品种，并报商务部备案。"},{"i":17,"n":"第十七条","txt":"监测预警工作应当根据市场异常波动的特点，科学分析、综合评价监测数据，掌握市场运行情况。 对早期发现的潜在隐患以及可能发生的市场异常波动，县级以上地方商务主管部门应及时向本级人民政府和上一级商务主管部门做出预警报告，并向有关主管部门通报。"},{"i":18,"n":"第十八条","txt":"商务部负责建立全国市场异常波动应急报告制度和市场异常波动信息报告系统。 县级以上地方商务主管部门监测到市场异常波动或接到市场异常波动报告，应当在2个小时之内向本级人民政府报告，同时向上一级商务主管部门报告。 有下列情形之一的，各省、自治区、直辖市（以下简称省级）商务主管部门，应当在接到报告1个小时之内，向商务部报告： （一）发生地震、泥石流、海啸、冰冻雨雪、洪水、干旱等严重自然灾害，造成市场异常波动的； （二）发生群体性疾病、水源污染等公共卫生事件或动植物疫情，造成市场异常波动的； （三）核泄漏、战争、恐怖袭击等引发公众恐慌，造成市场异常波动的。"},{"i":19,"n":"第十九条","txt":"大型批发、零售企业等有关单位发现有本办法第十八条第三款规定情形之一的，应当在1小时内向发生地县级以上商务主管部门报告。"},{"i":20,"n":"第二十条","txt":"各级商务主管部门监测到市场异常波动或接到市场异常波动报告，应当依照本办法规定报告的同时，立即组织力量进行调查核实、确证，采取必要的控制措施，并及时报告调查情况。"},{"i":21,"n":"第二十一条","txt":"商务部对发生的一级或二级市场异常波动，应当立即向国务院报告，及时向国务院有关部门和军队有关部门通报，并分别向各地或相关省级商务主管部门通报。"},{"i":22,"n":"第二十二条","txt":"在市场异常波动消除之前，地方各级商务主管部门均需执行24小时零报告制度。"},{"i":23,"n":"第二十三条","txt":"任何单位和个人对市场异常波动信息，不得隐瞒、缓报、谎报、漏报或者授意他人隐瞒、缓报、谎报、漏报。"},{"i":24,"n":"第二十四条","txt":"商务部负责建立全国市场异常波动的信息发布制度，负责向社会发布全国和跨省、自治区、直辖市的市场异常波动和应急处置工作的信息。 县级以上地方商务主管部门负责向社会发布本行政区域内市场异常波动和应急处置工作的信息。 信息发布应当及时、准确、全面。"},{"i":25,"n":"第二十五条","txt":"市场异常波动发生后，县级以上商务主管部门应当对市场异常波动进行综合评估，初步判断市场异常波动的级别，提出是否启动生活必需品市场供应应急预案的建议。"},{"i":26,"n":"第二十六条","txt":"启动全国或跨省、自治区、直辖市的生活必需品市场供应应急预案，由商务部报国务院批准后实施。启动地方各级生活必需品市场供应应急预案，由地方各级商务主管部门报本级人民政府批准后实施，并向上一级商务主管部门报告。"},{"i":27,"n":"第二十七条","txt":"市场异常波动发生后，地方各级商务主管部门，应当及时协调有关部门保证应急处置所需生活必需品的生产、运输。 针对下列突发事件，发生地县级以上商务主管部门应会同有关部门重点做好以下商品的市场供应： （一）发生地震、泥石流、海啸等局部性地质类灾害，要重点做好方便食品、瓶装饮用水、防寒衣被、照明用品、帐篷、净水器、卫生清洁用品等市场供应； （二）发生冰冻雨雪、洪水、干旱等大范围气象灾害，要重点做好耐储存蔬菜、粮食、肉类、鸡蛋、方便食品、照明用品、防寒衣被等市场供应； （三）发生群体性疾病、动物疫情等易扩散公共卫生事件，要重点做好卫生清洁用品、防护用品、粮食、食用油、食盐、畜禽产品、方便食品等市场供应； （四）发生核泄漏等事故灾难，要重点做好粮食、食用油、食盐、方便食品、瓶装饮用水、防辐射用品的市场供应。"},{"i":28,"n":"第二十八条","txt":"针对生活必需品脱销或价格大幅上涨的市场异常波动状况，发生地县级以上商务主管部门会同有关部门可采取如下措施： （一） 及时发布市场信息，正确引导市场预期； （二） 督促流通企业组织货源，通过企业供应链采购、动用商业库存，增加市场供应； （三） 开展紧缺物资跨区域调运，进行异地生活必需品余缺调剂； （四） 组织投放政府储备物资，按照规定程序和权限，先投放地方储备物资，后投放中央储备物资； （五） 当国内生活必需品产量不足时，省级商务主管部门可报请商务部，迅速组织进口； （六） 定量、限量销售，或实行统一发放、分配； （七） 依法征用，保障人民群众基本生活需要。"},{"i":29,"n":"第二十九条","txt":"针对生活必需品中鲜活农产品滞销的市场异常波动状况，发生地县级以上商务主管部门会同有关部门可采取如下措施： （一） 及时发布市场信息，引导生产经营； （二） 组织开展形式多样的产销对接活动； （三） 引导农产品加工企业扩大加工规模，增加采购数量； （四） 指导有储存条件的企业增加商业库存，必要时建立临时性政府储备； （五） 支持出口企业开拓国际市场，扩大滞销农产品出口。 鲜活农产品出现严重滞销情形时，发生地县级以上商务主管部门可倡导大型批发、零售企业履行社会责任, 采取积极有效的救助措施。"},{"i":30,"n":"第三十条","txt":"根据市场异常波动应急处置的需要，地方各级商务主管部门会同有关部门报本级人民政府批准后，有权统一紧急征集生活必需品、交通工具以及相关设施。有关单位和个人应当予以配合，不得以任何理由予以拒绝。 对组织企业调运投放物资产生的相关费用，以及紧急调集、征用的物资和进口商品企业的损失等，按照有关规定给予补助或补偿。"},{"i":31,"n":"第三十一条","txt":"重大突发事件造成商业网点严重损毁，影响市场供应的，发生地县级以上商务主管部门应迅速组织建立临时性商业网点，保障生活必需品供应渠道畅通。"},{"i":32,"n":"第三十二条","txt":"市场异常波动消除后，发生地县级以上商务主管部门应当报请本级人民政府批准后停止执行依据本办法规定采取的应急处置措施，并通报上一级商务主管部门。"},{"i":33,"n":"第三十三条","txt":"应急处置工作结束后，发生地县级以上商务主管部门应就本次突发事件对相关生活必需品中远期市场供应的影响做出研判，提出工作建议，及时向本级人民政府和上一级商务主管部门报告，同时通报有关主管部门，并做好后续监测工作，及时向社会公布相关信息。"},{"i":34,"n":"第三十四条","txt":"商务部对全国市场异常波动应急处置工作进行督察和指导，地方各级商务主管部门应当予以配合。 省级商务主管部门对本行政区域内市场异常波动应急处置工作进行督察和指导。"},{"i":35,"n":"第三十五条","txt":"商务部应当对各省、自治区、直辖市生活必需品市场供应应急预案制定和落实情况进行检查。 省级商务主管部门负责对本行政区域内县级以上商务主管部门生活必需品市场供应应急预案制定和落实情况进行检查。"},{"i":36,"n":"第三十六条","txt":"省级以上商务主管部门建立市场异常波动举报制度，公布报告、举报电话。任何单位和个人有权向商务主管部门报告市场异常波动隐患，有权举报不履行市场异常波动应急处置职责，或者不按照规定履行职责的情况。接到报告、举报的商务主管部门，应当立即组织对市场异常波动隐患、不履行或者不按照规定履行市场异常波动应急处置职责的情况进行调查处置。 对报告、举报市场异常波动有功的单位和个人，可予以奖励。"},{"i":37,"n":"第三十七条","txt":"县级以上地方商务主管部门有下列行为之一的，由上级商务主管部门责令改正，通报批评，对其主要负责人建议有关单位依法给予降级或者撤职的行政处分；造成严重危害后果的，建议依法给予开除的行政处分；构成犯罪的，提请司法机关依法追究刑事责任： （一）未按照规定履行报告职责，隐瞒、缓报、谎报、漏报或授意他人隐瞒、缓报、谎报、漏报市场异常波动的； （二）未按照规定完成市场异常波动应急处理所需要的设施、设备和商品等物资供应和储备的； （三）未按照规定履行市场监测职责的； （四）未按照规定及时采取控制措施的； （五）在应急处置工作中玩忽职守，失职、渎职的； （六）对上级商务主管部门的督察、指导不予配合，或者采取其他方式阻碍、干涉的。"},{"i":38,"n":"第三十八条","txt":"生活必需品销售和储运单位及其人员有下列行为之一的，由县级以上地方人民政府有关主管部门根据情节，依法责令改正、没收违法所得、罚款、警告；造成严重危害后果，构成犯罪的，提请司法机关依法追究刑事责任： （一）未按照规定履行市场异常波动报告职责，隐瞒、缓报、谎报或者漏报的； （二）未按照规定报送监测资料的； （三）购进、销售假冒伪劣商品及囤积居奇、哄抬物价的； （四）未按照规定及时采取组织货源等预防控制措施的； （五）拒绝服从商务主管部门调遣的； （六）拒绝、阻碍或者不配合现场调查、资料收集及监督检查的。"},{"i":39,"n":"第三十九条","txt":"本办法由商务部负责解释。"},{"i":40,"n":"第四十条","txt":"本办法自2012年2月1日起施行。《突发事件生活必需品应急管理暂行办法》（商务部令2003年第7号）同时废止。"}],"baiyinchukouguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"本办法所称白银系指银粉、未锻造银及银的半制成品（具体管理名录见附件）。"},{"i":2,"n":"第二条","txt":"人民银行库存白银的出口仍按现行规定办理。"},{"i":3,"n":"第三条","txt":"国家对白银出口实行配额许可证管理，具体按照外经贸部《关于出口商品配额编报、下达和组织实施暂行办法的实施细则》（〔1998〕外经贸管发第980号）执行。"},{"i":4,"n":"第四条","txt":"经外经贸部核定具有白银出口经营资格的企业方可经营白银一般贸易出口。按照优胜劣汰的原则，外经贸部每年对白银一般贸易出口企业核定一次并予以公布。"},{"i":5,"n":"第五条","txt":"外经贸部授权配额许可证事务局核发白银出口许可证。海关凭出口许可证验放。"},{"i":6,"n":"第六条","txt":"外经贸部授权的发证机关，要严格审核企业白银出口经营资格和配额数量，审核企业的出口合同，核发出口许可证。"},{"i":7,"n":"第七条","txt":"加工贸易企业进口本办法第一条所列以外的含白银商品，需要加工复出口白银，由企业提出申请，其加工贸易业务由企业注册地省级外经贸主管部门审批。海关凭《加工贸易业务批准证》办理合同登记备案手续。考虑到白银生产的特殊性，外经贸主管部门在批准证的备注栏内注明“复出口白银以进口料件商检后核定的数量为准”。 加工贸易进口料件进口后180天内，省级外经贸主管部门需将企业加工出口白银的数量、进口料件商检证明、企业加工工艺及单耗情况等报外经贸部，同时抄报国家有色金属工业局。外经贸部征求国家有色局意见后，办理批复手续。如批复的白银进口含量、单耗、应加工出口数量等与原审批、备案情况不一致的，外经贸部将批件抄送备案主管海关，企业需办理相应的合同变更手续，海关按修改后的单耗予以监管核销。企业凭外经贸部批件到配额许可证事务局申领出口许可证。海关凭出口许可证验放。"},{"i":8,"n":"第八条","txt":"对违反本办法及其他有关出口管理规定的出口企业，一经查实，将根据情节轻重，处以扣减出口配额、直至取消其白银出口经营权的处罚。"},{"i":9,"n":"第九条","txt":"凡以前的有关规定与本办法不一致的，以本办法为准。"},{"i":10,"n":"第十条","txt":"本办法自2000年1月1日起执行。在此日期之前已向海关办理了白银加工贸易合同备案手续的仍按原规定执行。"}],"zhixiaoqiyebaozhengjincunjiaoshiyongguanlibanfa-2":[{"i":1,"n":"第一条","txt":"根据《直销管理条例》第三十四条第二款规定，制定本办法。"},{"i":2,"n":"第二条","txt":"企业申请直销应提交其在指定银行开设的保证金专门账户凭证，金额为2000万元人民币。保证金为现金。"},{"i":3,"n":"第三条","txt":"直销企业与指定银行签订的保证金专门账户协议应包括下述内容： （一）指定银行根据商务部和国家工商行政管理总局（以下简称工商总局）的书面决定支付保证金； （二）直销企业不得违反《直销管理条例》擅自动用保证金，不得以保证金对外担保或者违反《直销管理条例》规定用于清偿债务； （三）指定银行应及时向商务部和工商总局通报保证金账户情况，商务部和工商总局可以查询直销企业保证金账户； （四）直销企业和指定银行的权利义务及争议解决方式。 企业在申请设立时应提交与指定银行签署的开设保证金专门账户协议。"},{"i":4,"n":"第四条","txt":"直销企业开始从事直销经营活动3个月后，保证金金额按月进行调整。直销企业于次月15日前将其上月销售额的有效证明文件向指定银行出具，并通过直销行业管理网站向商务部和工商总局备案。直销企业对出具的证明文件的真实性、完整性负责，指定银行应当对证明文件进行形式审查。 直销企业保证金金额保持在直销企业上月直销产品销售收入的15％水平。账户余额最低为2000万元人民币，最高不超过1亿元人民币。 根据直销企业月销售额，如需调增保证金金额的，直销企业应当在向指定银行递交月销售额证明文件后5日内将款项划转到其指定银行保证金账户；如需调减保证金金额的，按企业与指定银行签订的协议办理。"},{"i":5,"n":"第五条","txt":"出现下列情形之一，商务部和工商总局共同决定，可以使用保证金： （一）无正当理由，直销企业不向直销员支付报酬，或者不向直销员、消费者支付退货款的； （二）直销企业发生停业、合并、解散、转让、破产等情况，无力向直销员支付报酬或者无力向直销员和消费者支付退货款的； （三）因直销产品问题给消费者造成损失，依法应当进行赔偿，直销企业无正当理由拒绝赔偿或者无力赔偿的。"},{"i":6,"n":"第六条","txt":"直销员或消费者根据《直销管理条例》和本办法第五条规定要求使用保证金的，应当持法院生效判决书或调解书，向省级商务主管部门或工商行政管理部门提出申请，省级商务主管部门或工商行政管理部门接到申请后10个工作日内将申请材料报送商务部和工商总局。 直销员除持法院生效判决书、调解书外，还应出示其身份证、直销员证及其与直销企业签订的推销合同。消费者除持法院生效判决书、调解书外，还应出示其身份证、售货凭证或发票。 商务部和工商总局接到申请材料后60个工作日内做出是否使用保证金支付赔偿的决定，并书面通知指定银行、直销企业和保证金使用申请人。 直销员违反《禁止传销条例》有关规定的，其申请不予受理。"},{"i":7,"n":"第七条","txt":"根据本办法规定支付保证金后，直销企业应当自支付之日起30日内将其保证金专门账户的金额补足到本办法第四条第二款规定的水平。"},{"i":8,"n":"第八条","txt":"直销企业保证金使用情况应当及时通过商务部和工商总局直销行业管理网站向社会披露。"},{"i":9,"n":"第九条","txt":"直销企业不再从事直销活动的，凭商务部和工商总局出具的书面凭证，可以向指定银行取回保证金。 企业申请直销未获批准的，凭商务部出具的书面凭证到指定银行办理保证金退回手续。"},{"i":10,"n":"第十条","txt":"直销企业违反本办法规定的，按照《直销管理条例》第五十一条予以处罚。"},{"i":11,"n":"第十一条","txt":"商务部和工商总局共同负责直销保证金的日常监管工作。"},{"i":12,"n":"第十二条","txt":"本办法由商务部、工商总局负责解释。"},{"i":13,"n":"第十三条","txt":"本办法自2005年12月1日起施行。"}],"zhixiaoqiyebaozhengjincunjiaoshiyongguanlibanfa":[{"i":1,"n":"第一条","txt":"根据《直销管理条例》第三十四条第二款规定，制定本办法。"},{"i":2,"n":"第二条","txt":"企业申请直销应提交其在指定银行开设的保证金专门账户凭证，金额为2000万元人民币。保证金为现金。"},{"i":3,"n":"第三条","txt":"直销企业与指定银行签订的保证金专门账户协议应包括下述内容： （一）指定银行根据商务部和国家工商行政管理总局（以下简称工商总局）的书面决定支付保证金； （二）直销企业不得违反《直销管理条例》擅自动用保证金，不得以保证金对外担保或者违反《直销管理条例》规定用于清偿债务； （三）指定银行应及时向商务部和工商总局通报保证金账户情况，商务部和工商总局可以查询直销企业保证金账户； （四）直销企业和指定银行的权利义务及争议解决方式。 企业在申请设立时应提交与指定银行签署的开设保证金专门账户协议。"},{"i":4,"n":"第四条","txt":"直销企业开始从事直销经营活动3个月后，保证金金额按月进行调整。直销企业于次月15日前将其上月销售额的有效证明文件向指定银行出具，并通过直销行业管理网站向商务部和工商总局备案。直销企业对出具的证明文件的真实性、完整性负责，指定银行应当对证明文件进行形式审查。 直销企业保证金金额保持在直销企业上月直销产品销售收入的15％水平。账户余额最低为2000万元人民币，最高不超过1亿元人民币。 根据直销企业月销售额，如需调增保证金金额的，直销企业应当在向指定银行递交月销售额证明文件后5日内将款项划转到其指定银行保证金账户；如需调减保证金金额的，按企业与指定银行签订的协议办理。"},{"i":5,"n":"第五条","txt":"出现下列情形之一，商务部和工商总局共同决定，可以使用保证金： （一）无正当理由，直销企业不向直销员支付报酬，或者不向直销员、消费者支付退货款的； （二）直销企业发生停业、合并、解散、转让、破产等情况，无力向直销员支付报酬或者无力向直销员和消费者支付退货款的； （三）因直销产品问题给消费者造成损失，依法应当进行赔偿，直销企业无正当理由拒绝赔偿或者无力赔偿的。"},{"i":6,"n":"第六条","txt":"直销员或消费者根据《直销管理条例》和本办法第五条规定要求使用保证金的，应当持法院生效判决书或调解书，向省级商务主管部门或工商行政管理部门提出申请，省级商务主管部门或工商行政管理部门接到申请后10个工作日内将申请材料报送商务部和工商总局。 直销员除持法院生效判决书、调解书外，还应出示其身份证、直销员证及其与直销企业签订的推销合同。消费者除持法院生效判决书、调解书外，还应出示其身份证、售货凭证或发票。 商务部和工商总局接到申请材料后60个工作日内做出是否使用保证金支付赔偿的决定，并书面通知指定银行、直销企业和保证金使用申请人。 直销员违反《禁止传销条例》有关规定的，其申请不予受理。"},{"i":7,"n":"第七条","txt":"根据本办法规定支付保证金后，直销企业应当自支付之日起30日内将其保证金专门账户的金额补足到本办法第四条第二款规定的水平。"},{"i":8,"n":"第八条","txt":"直销企业保证金使用情况应当及时通过商务部和工商总局直销行业管理网站向社会披露。"},{"i":9,"n":"第九条","txt":"直销企业不再从事直销活动的，凭商务部和工商总局出具的书面凭证，可以向指定银行取回保证金。 企业申请直销未获批准的，凭商务部出具的书面凭证到指定银行办理保证金退回手续。"},{"i":10,"n":"第十条","txt":"直销企业违反本办法规定的，按照《直销管理条例》第五十一条予以处罚。"},{"i":11,"n":"第十一条","txt":"商务部和工商总局共同负责直销保证金的日常监管工作。"},{"i":12,"n":"第十二条","txt":"本办法由商务部、工商总局负责解释。"},{"i":13,"n":"第十三条","txt":"本办法自2005年12月1日起施行。"}],"zhixiaoqiyexinxibaobeipiluguanlibanfa-2":[{"i":1,"n":"第一条","txt":"根据《直销管理条例》第二十八条规定，制定本办法。"},{"i":2,"n":"第二条","txt":"直销企业应建立完备的信息报备和披露制度，并接受政府相关部门的监管检查和社会公众的监督。"},{"i":3,"n":"第三条","txt":"商务部和国家工商行政管理总局（以下简称工商总局）直销行业管理网站向社会公布下列内容： （一）有关法律、法规及规章； （二）直销产品范围公告； （三）直销企业名单及其直销产品名录； （四）直销企业省级分支机构名单及其从事直销的地区、服务网点； （五）直销企业保证金使用情况； （六）直销员证、直销培训员证式样； （七）直销企业、直销培训员及直销员违规及处罚情况； （八）其它需要公布的信息。"},{"i":4,"n":"第四条","txt":"直销企业通过其建立的中文网站向社会披露信息。直销企业建立的中文网站是直销企业信息报备和披露的重要组成部分，并应在取得直销经营许可证之日起3个月内与直销行业管理网站链接。"},{"i":5,"n":"第五条","txt":"直销企业设立后应真实、准确、及时、完整地向社会公众披露以下信息： （一）直销企业直销员总数，各省级分支机构直销员总数、名单、直销员证编号、职业及与直销企业解除推销合同人员名单； （二）直销企业及其分支机构名称、地址、联系方式及负责人，服务网点名称、地址、联系方式及负责人； （三）直销产品目录、零售价格、产品质量及标准说明书，以及直销产品的主要成分、适宜人群、使用注意事项等应当让消费者事先知晓的内容。 根据国家相关规定直销产品应符合国家认证、许可或强制性标准的，直销企业应披露其取得相关认证、许可或符合标准的证明文件； （四）直销员计酬、奖励制度； （五）直销产品退换货办法、退换货地点及退换货情况； （六）售后服务部门、职能、投诉电话、投诉处理程序； （七）直销企业与直销员签订的推销合同中关于直销企业和直销员的权利、义务，直销员解约制度，直销员退换货办法，计酬办法及奖励制度，法律责任及其他"},{"i":6,"n":"第六条","txt":"直销企业设立后，每月15日前须通过直销行业管理网站向商务部、工商总局报备以下上月内容： （一）保证金存缴情况； （二）直销员直销经营收入及纳税明细情况； 1、直销员按月直销经营收入及纳税金额； 2、直销员直销经营收入金额占直销员本人直接向消费者销售产品收入的比例。 （三）企业每月销售业绩及纳税情况； （四）直销培训员备案； （五）其他需要报备的内容。"},{"i":7,"n":"第七条","txt":"直销企业应于每年4月份以企业年报的方式公布本办法第五条所列内容。"},{"i":8,"n":"第八条","txt":"直销企业及直销员所使用的产品说明和任何宣传材料须与直销企业披露的信息内容一致。"},{"i":9,"n":"第九条","txt":"直销企业未按照《直销管理条例》和本办法进行信息披露，或直销企业披露的信息存在虚假、严重误导性陈述或重大遗漏的，按照《直销管理条例》第五十条规定予以处罚。"},{"i":10,"n":"第十条","txt":"本办法由商务部和工商总局负责解释。"},{"i":11,"n":"第十一条","txt":"本办法自2005年12月1日起实施。"}],"zhixiaoqiyexinxibaobeipiluguanlibanfa":[{"i":1,"n":"第一条","txt":"根据《直销管理条例》第二十八条规定，制定本办法。"},{"i":2,"n":"第二条","txt":"直销企业应建立完备的信息报备和披露制度，并接受政府相关部门的监管检查和社会公众的监督。"},{"i":3,"n":"第三条","txt":"商务部和国家工商行政管理总局（以下简称工商总局）直销行业管理网站向社会公布下列内容： （一）有关法律、法规及规章； （二）直销产品范围公告； （三）直销企业名单及其直销产品名录； （四）直销企业省级分支机构名单及其从事直销的地区、服务网点； （五）直销企业保证金使用情况； （六）直销员证、直销培训员证式样； （七）直销企业、直销培训员及直销员违规及处罚情况； （八）其它需要公布的信息。"},{"i":4,"n":"第四条","txt":"直销企业通过其建立的中文网站向社会披露信息。直销企业建立的中文网站是直销企业信息报备和披露的重要组成部分，并应在取得直销经营许可证之日起3个月内与直销行业管理网站链接。"},{"i":5,"n":"第五条","txt":"直销企业设立后应真实、准确、及时、完整地向社会公众披露以下信息： （一）直销企业直销员总数，各省级分支机构直销员总数、名单、直销员证编号、职业及与直销企业解除推销合同人员名单； （二）直销企业及其分支机构名称、地址、联系方式及负责人，服务网点名称、地址、联系方式及负责人； （三）直销产品目录、零售价格、产品质量及标准说明书，以及直销产品的主要成分、适宜人群、使用注意事项等应当让消费者事先知晓的内容。 根据国家相关规定直销产品应符合国家认证、许可或强制性标准的，直销企业应披露其取得相关认证、许可或符合标准的证明文件； （四）直销员计酬、奖励制度； （五）直销产品退换货办法、退换货地点及退换货情况； （六）售后服务部门、职能、投诉电话、投诉处理程序； （七）直销企业与直销员签订的推销合同中关于直销企业和直销员的权利、义务，直销员解约制度，直销员退换货办法，计酬办法及奖励制度，法律责任及其他"},{"i":6,"n":"第六条","txt":"直销企业设立后，每月15日前须通过直销行业管理网站向商务部、工商总局报备以下上月内容： （一）保证金存缴情况； （二）直销员直销经营收入及纳税明细情况； 1、直销员按月直销经营收入及纳税金额； 2、直销员直销经营收入金额占直销员本人直接向消费者销售产品收入的比例。 （三）企业每月销售业绩及纳税情况； （四）直销培训员备案； （五）其他需要报备的内容。"},{"i":7,"n":"第七条","txt":"直销企业应于每年4月份以企业年报的方式公布本办法第五条所列内容。"},{"i":8,"n":"第八条","txt":"直销企业及直销员所使用的产品说明和任何宣传材料须与直销企业披露的信息内容一致。"},{"i":9,"n":"第九条","txt":"直销企业未按照《直销管理条例》和本办法进行信息披露，或直销企业披露的信息存在虚假、严重误导性陈述或重大遗漏的，按照《直销管理条例》第五十条规定予以处罚。"},{"i":10,"n":"第十条","txt":"本办法由商务部和工商总局负责解释。"},{"i":11,"n":"第十一条","txt":"本办法自2005年12月1日起实施。"}],"zhixiaoyuanyewupeixunguanlibanfa-2":[{"i":1,"n":"第一条","txt":"根据《直销管理条例》第二十一条第三款规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内举办直销员业务培训（以下简称直销培训）及考试活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称直销培训，是指直销企业对本企业拟招募的直销员和本企业的直销员进行国家相关法律法规规章、直销基础知识等各种培训活动。 本办法所称直销员考试是指直销企业对本企业拟招募的直销员的考试。"},{"i":4,"n":"第四条","txt":"直销企业向符合《直销管理条例》规定条件的直销员、直销培训员颁发《直销员证》、《直销培训员证》。 直销企业应在每月15日前将本企业上一个月取得《直销培训员证》的人员名册，通过企业所在地省级商务主管部门向商务部备案。未经备案的人员，不得对直销员开展培训。直销培训员只能接受所属企业指派进行培训。 《直销员证》、《直销培训员证》由直销企业按商务部制定的规范式样印制。"},{"i":5,"n":"第五条","txt":"直销员向消费者推销产品时、直销培训员在进行直销培训活动时，应佩戴《直销员证》、《直销培训员证》。 不得伪造、变造、涂改、出租、出借、转让、出卖《直销员证》、《直销培训员证》。"},{"i":6,"n":"第六条","txt":"直销培训内容以《直销管理条例》、《禁止传销条例》、《合同法》、《消费者权益保护法》、《产品质量法》、《反不正当竞争法》等法律法规中的相关内容、直销员道德规范、直销风险揭示以及营销方面的知识为主。 直销员考试应含有上款所规定的内容。"},{"i":7,"n":"第七条","txt":"直销企业进行直销培训和考试，不得收取任何费用。其他单位和个人，不得以任何名义组织直销培训和考试。"},{"i":8,"n":"第八条","txt":"直销培训不得宣扬迷信邪说、色情、淫秽或者渲染暴力；不得扰乱社会秩序，破坏社会稳定；不得对企业产品进行夸大、虚假宣传，贬低同类其它产品，强迫参加培训的人员购买产品；不得以任何方式宣扬直销员以往的收入情况，宣扬大多数参与者将获得成功；不得从事违反国家宪法、法律法规和国家规定禁止的其它活动。 直销企业不得以召开研讨会、激励会、表彰会等形式变相对直销员进行培训。"},{"i":9,"n":"第九条","txt":"直销企业应在本企业设有服务网点的地区组织直销培训。直销培训不得在政府、军队、学校、医院的场所及居民社区、私人住宅内举办。"},{"i":10,"n":"第十条","txt":"直销企业应于直销培训或考试活动7日前将培训或考试计划（包括培训时间、具体地点、内容、人数及直销培训员、培训资料和考试时间、地点、人数）在直销企业中文网站上公布。"},{"i":11,"n":"第十一条","txt":"直销企业应当对每期直销培训讲授内容进行录音，完整保存参加培训的人员名单、直销员考试试卷。录音资料、直销员考试试卷应妥善保管，至少保存3年。"},{"i":12,"n":"第十二条","txt":"直销企业应当于每年1月底前将上一年度举办的直销培训及考试情况通过企业所在地省级商务、工商主管部门报商务部、国家工商行政管理总局备案。备案内容包括：上一年度举办培训期数（每次培训时间、地点、参加人数、直销培训员、培训资料的名称）、上一年度举办考试次数（每次考试时间、地点、试卷、参加人数、合格人数）。"},{"i":13,"n":"第十三条","txt":"商务部门、工商行政管理部门依照《直销管理条例》和本办法负责对直销培训进行监管；商务部负责制定《直销员证》、《直销培训员证》的规范式样。"},{"i":14,"n":"第十四条","txt":"参加直销培训的人员，如发现直销企业组织的培训、直销培训员讲授的内容违反法律法规或本办法的规定，有权当场指出，并向培训所在地县级以上工商行政管理部门举报。"},{"i":15,"n":"第十五条","txt":"直销企业、直销培训员进行直销培训，违反《直销管理条例》或本办法的，以及直销企业以外的单位和个人组织直销培训的，按照《直销管理条例》第四十六条规定予以查处。"},{"i":16,"n":"第十六条","txt":"直销企业开展直销培训和考试活动，构成违反治安管理行为的，由公安机关依法予以查处；构成犯罪的，依法追究其刑事责任。"},{"i":17,"n":"第十七条","txt":"各级商务、工商、公安机关应建立联系制度，定期通报直销企业培训和查处违规培训情况。"},{"i":18,"n":"第十八条","txt":"本办法自2005年12月1日起施行。"}],"zhixiaoyuanyewupeixunguanlibanfa":[{"i":1,"n":"第一条","txt":"根据《直销管理条例》第二十一条第三款规定，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内举办直销员业务培训（以下简称直销培训）及考试活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称直销培训，是指直销企业对本企业拟招募的直销员和本企业的直销员进行国家相关法律法规规章、直销基础知识等各种培训活动。 本办法所称直销员考试是指直销企业对本企业拟招募的直销员的考试。"},{"i":4,"n":"第四条","txt":"直销企业向符合《直销管理条例》规定条件的直销员、直销培训员颁发《直销员证》、《直销培训员证》。 直销企业应在每月15日前将本企业上一个月取得《直销培训员证》的人员名册，通过企业所在地省级商务主管部门向商务部备案。未经备案的人员，不得对直销员开展培训。直销培训员只能接受所属企业指派进行培训。 《直销员证》、《直销培训员证》由直销企业按商务部制定的规范式样印制。"},{"i":5,"n":"第五条","txt":"直销员向消费者推销产品时、直销培训员在进行直销培训活动时，应佩戴《直销员证》、《直销培训员证》。 不得伪造、变造、涂改、出租、出借、转让、出卖《直销员证》、《直销培训员证》。"},{"i":6,"n":"第六条","txt":"直销培训内容以《直销管理条例》、《禁止传销条例》、《合同法》、《消费者权益保护法》、《产品质量法》、《反不正当竞争法》等法律法规中的相关内容、直销员道德规范、直销风险揭示以及营销方面的知识为主。 直销员考试应含有上款所规定的内容。"},{"i":7,"n":"第七条","txt":"直销企业进行直销培训和考试，不得收取任何费用。其他单位和个人，不得以任何名义组织直销培训和考试。"},{"i":8,"n":"第八条","txt":"直销培训不得宣扬迷信邪说、色情、淫秽或者渲染暴力；不得扰乱社会秩序，破坏社会稳定；不得对企业产品进行夸大、虚假宣传，贬低同类其它产品，强迫参加培训的人员购买产品；不得以任何方式宣扬直销员以往的收入情况，宣扬大多数参与者将获得成功；不得从事违反国家宪法、法律法规和国家规定禁止的其它活动。 直销企业不得以召开研讨会、激励会、表彰会等形式变相对直销员进行培训。"},{"i":9,"n":"第九条","txt":"直销企业应在本企业设有服务网点的地区组织直销培训。直销培训不得在政府、军队、学校、医院的场所及居民社区、私人住宅内举办。"},{"i":10,"n":"第十条","txt":"直销企业应于直销培训或考试活动7日前将培训或考试计划（包括培训时间、具体地点、内容、人数及直销培训员、培训资料和考试时间、地点、人数）在直销企业中文网站上公布。"},{"i":11,"n":"第十一条","txt":"直销企业应当对每期直销培训讲授内容进行录音，完整保存参加培训的人员名单、直销员考试试卷。录音资料、直销员考试试卷应妥善保管，至少保存3年。"},{"i":12,"n":"第十二条","txt":"直销企业应当于每年1月底前将上一年度举办的直销培训及考试情况通过企业所在地省级商务、工商主管部门报商务部、国家工商行政管理总局备案。备案内容包括：上一年度举办培训期数（每次培训时间、地点、参加人数、直销培训员、培训资料的名称）、上一年度举办考试次数（每次考试时间、地点、试卷、参加人数、合格人数）。"},{"i":13,"n":"第十三条","txt":"商务部门、工商行政管理部门依照《直销管理条例》和本办法负责对直销培训进行监管；商务部负责制定《直销员证》、《直销培训员证》的规范式样。"},{"i":14,"n":"第十四条","txt":"参加直销培训的人员，如发现直销企业组织的培训、直销培训员讲授的内容违反法律法规或本办法的规定，有权当场指出，并向培训所在地县级以上工商行政管理部门举报。"},{"i":15,"n":"第十五条","txt":"直销企业、直销培训员进行直销培训，违反《直销管理条例》或本办法的，以及直销企业以外的单位和个人组织直销培训的，按照《直销管理条例》第四十六条规定予以查处。"},{"i":16,"n":"第十六条","txt":"直销企业开展直销培训和考试活动，构成违反治安管理行为的，由公安机关依法予以查处；构成犯罪的，依法追究其刑事责任。"},{"i":17,"n":"第十七条","txt":"各级商务、工商、公安机关应建立联系制度，定期通报直销企业培训和查处违规培训情况。"},{"i":18,"n":"第十八条","txt":"本办法自2005年12月1日起施行。"}],"zhixiaoxingyefuwuwangdiansheliguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范直销行为，加强对直销活动的监管，根据《直销管理条例》（以下简称《条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"申请企业提交的申请材料应包含其在拟从事直销地区的服务网点方案。服务网点方案应符合下列条件： （一）便于满足最终消费者、直销员了解商品性能、价格和退换货等要求； （二）服务网点不得设在居民住宅、学校、医院、部队、政府机关等场所； （三）符合当地县级以上（含县级）人民政府关于直销行业服务网点设立的相关要求。"},{"i":3,"n":"第三条","txt":"商务部以市/县为批准从事直销活动的基本区域单位。对于设区的市，申报企业应在该市的每个城区设立不少于一个服务网点，在该市其它区/县开展直销活动应按本办法申报。 县级以上（含县级）商务主管部门应当根据《条例》第十条第二款对申请企业提交的服务网点方案进行审查。经审查同意的，应当向省级商务主管部门出具该服务网点方案符合本办法第二条相关规定的书面认可函（标准格式见附件一）。"},{"i":4,"n":"第四条","txt":"省级商务主管部门向商务部转报企业申请材料时，应当同时出具对服务网点方案的确认函（标准格式见附件二）。确认函应当包含下列内容： （一）企业服务网点方案经所在地区/县级以上（含县级）商务主管部门认可； （二）该企业在本省拟从事直销业务区域内的服务网点方案符合《条例》第十条第二款规定的条件。"},{"i":5,"n":"第五条","txt":"依法取得直销经营许可证的企业应当于批准文件下发之日起6个月内按其上报并经商务部核准的服务网点方案完成服务网点的设立。6个月内未能按商务部核准的服务网点方案完成服务网点设立的企业，不得在未完成服务网点方案的地区从事直销业务，该企业若要在上述地区开展直销业务，应按《条例》规定另行申报。"},{"i":6,"n":"第六条","txt":"有关省、自治区、直辖市商务主管部门应会同服务网点所在地的区/县级以上（含县级）商务主管部门，根据《条　例》及有关规定对直销企业在该省、自治区、直辖市内已设立的服务网点进行核查，并将全省、自治区、直辖市核查结果一次性报商务部备案。商务部备案后通过直销行业管理网站公布直销企业可从事直销业务的地区及服务网点。直销企业不得在未完成核查和备案前开展直销活动。"},{"i":7,"n":"第七条","txt":"直销企业可根据业务发展需要增加服务网点，在已批准从事直销的地区增加服务网点不需要报批，但应当将增设方案通过省级商务主管部门报商务部备案。商务部备案后通过直销行业管理网站公布直销企业在已批准从事直销的地区增加的服务网点。 地方商务主管部门可根据《条例》第十条第二款要求直销企业在本地区增加服务网点，但应说明理由。 直销企业调整服务网点方案，减少服务网点应报原审批部门批准，并按规定备案。"},{"i":8,"n":"第八条","txt":"违反本办法规定的，按照《条例》第三十九条规定予以处罚。"},{"i":9,"n":"第九条","txt":"相关商务主管部门及其工作人员必须依法履行职责，进行服务网点设立管理工作，违反《条例》及本办法规定的，按照《条例》第三十八条规定予以处罚。"},{"i":10,"n":"第十条","txt":"本办法由商务部负责解释。"},{"i":11,"n":"第十一条","txt":"本办法自2006年 10月20日起实施。 ------------------------------------------------------------------------------ 附件1： 关于XX（申请直销企业名称）服务网点认可函 XX省/直辖市/自治区商务主管部门名称： 经研究，XX（申报直销企业名称）在本县/市/区设立的服务网点方案可便于并满足本县/市/区消费者、直销员了解XX（申报直销企业名称）产品性能、价格和退换货的要求，且服务网点未设在居民住宅、学校、医院、部队、政府机关等场所。 附：XX（申报直销企业名称）申报的服务网点方案 县/市/区商务主管部门（盖章）年 月 日 ------------------------------------------------------------------------------- 附件2： 关于XX（申请直销"}],"jinzhichukouxianzhichukoujishuguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范我国技术出口的管理，根据《中华人民共和国对外贸易法》、《中华人民共和国技术进出口管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"列入《中国禁止出口限制出口技术目录》(另行发布)中禁止出口的技术，不得出口。"},{"i":3,"n":"第三条","txt":"国家对列入《中国禁止出口限制出口技术目录》的限制出口技术实行许可证管理，凡出口国家限制出口技术的，应按本办法履行出口许可手续。"},{"i":4,"n":"第四条","txt":"属于本办法第三条规定的限制出口技术的出口许可由技术出口经营者所在地的省、自治区、直辖市商务主管部门(以下简称“地方商务主管部门”)会同省、自治区、直辖市科技行政主管部门(以下简称“地方科技行政主管部门)管理。"},{"i":5,"n":"第五条","txt":"技术出口经营者出口本办法第三条所规定的限制出口技术前，应填写《中国限制出口技术申请书》(以下简称《申请书》，见附表一)，报送地方商务主管部门履行出口许可手续。 属于国家秘密技术的限制出口技术，在按本办法履行许可手续前，应先按《国家秘密技术出口审查规定》办理保密审查手续，并持保密审查主管部门批准的《国家秘密技术出口保密审查批准书》按本条第一款规定程序办理出口申请。"},{"i":6,"n":"第六条","txt":"地方商务主管部门自收到《申请书》之日起30个工作日内，会同地方科技行政主管部门分别对技术出口项目进行贸易审查和技术审查，并决定是否准予出口。 申请人提供的申请材料不完备、申请内容不清或有其它申请不符合规定的情形，地方商务主管部门可要求申请人对申请材料进行修改或补充。"},{"i":7,"n":"第七条","txt":"地方商务主管部门应在收到《申请书》之日起5个工作日之内，将相关材料转地方科技行政主管部门。地方科技行政主管部门在收到《申请书》之日起15个工作日内，组织专家对申请出口的技术进行技术审查并将审查结果反馈地方商务主管部门，同时报科技部备案。"},{"i":8,"n":"第八条","txt":"限制出口技术的贸易审查应包括以下内容： (一)是否符合我国对外贸易政策，并有利于促进外贸出口； (二)是否符合我国的产业出口政策，并有利于促进国民经济发展； (三)是否符合我国对外承诺的义务。"},{"i":9,"n":"第九条","txt":"限制出口技术的技术审查应包括以下内容： (一)是否危及国家安全； (二)是否符合我国科技发展政策，并有利于科技进步； (三)是否符合我国的产业技术政策，并能带动大型和成套设备、高新技术产品的生产和经济技术合作。"},{"i":10,"n":"第十条","txt":"出口申请获得批准后，由地方商务主管部门颁发由商务部统一印制和编号的《中华人民共和国技术出口许可意向书》(以下简称《技术出口许可意向书》，见附表二)。《技术出口许可意向书》的有效期为3年。 在申请出口信贷、保险意向承诺时，必须出具《技术出口许可意向书》，金融、保险机构凭《技术出口许可意向书》办理有关业务。"},{"i":11,"n":"第十一条","txt":"对没有取得《技术出口许可意向书》的限制出口技术项目，任何单位和个人都不得对外进行实质性谈判，不得做出有关技术出口的具有法律效力的承诺。"},{"i":12,"n":"第十二条","txt":"技术出口经营者在《技术出口许可意向书》有效期内，未签订技术出口合同的，应按本办法第五条规定的程序向地方商务主管部门重新提出出口申请。"},{"i":13,"n":"第十三条","txt":"技术出口经营者签订技术出口合同后，持《技术出口许可意向书》、合同副本、技术资料出口清单(文件、资料、图纸、其他)(见附表四)、签约双方法律地位证明文件到地方商务主管部门申请技术出口许可证。"},{"i":14,"n":"第十四条","txt":"地方商务主管部门对技术出口合同的真实性进行审查，并自收到本办法第十三条规定的文件之日起15个工作日内，对技术出口做出是否许可的决定，对许可出口的技术颁发由商务部统一印制和编号的《中华人民共和国技术出口许可证》(以下简称《技术出口许可证》，见附表三)。"},{"i":15,"n":"第十五条","txt":"限制出口技术的技术出口合同自《技术出口许可证》颁发之日起生效。"},{"i":16,"n":"第十六条","txt":"技术出口经营者到地方商务主管部门领取《技术出口许可证》前，应登录商务部网站上的“技术进出口合同信息管理系统”(网址为：jsjckqy.fwmys.mofcom.gov.cn )，按程序录入合同内容。"},{"i":17,"n":"第十七条","txt":"技术出口经营者获得《技术出口许可证》后，如需更改技术出口内容，应按本办法规定的程序重新履行技术出口许可手续。"},{"i":18,"n":"第十八条","txt":"凡经批准允许出口的国家限制出口技术出口项目，技术出口经营者在办理海关事宜时，应主动出示《技术出口许可证》，海关验核后办理有关放行手续。"},{"i":19,"n":"第十九条","txt":"商务部会同科技部负责对地方商务主管部门和地方科技主管部门的技术出口许可进行监督检查，同时加强对限制出口技术管理的培训和指导。 地方商务主管部门应在每年1月31日前将上年度批准的技术出口许可事项向商务部备案。"},{"i":20,"n":"第二十条","txt":"凡违反本办法规定的，将依据《中华人民共和国技术进出口管理条例》及其他有关法律规定，追究有关当事人和单位的责任。"},{"i":21,"n":"第二十一条","txt":"核技术、核两用品相关技术、化学两用品相关技术、生物两用品相关技术、导弹相关技术和国防军工专有技术的出口不适用本办法。"},{"i":22,"n":"第二十二条","txt":"本办法自公布之日起30日后施行。2002年1月1日起施行的《禁止出口限制出口技术管理办法》(原对外贸易经济合作部、科学技术部2001年第14号令)同时废止。"}],"jinzhijinkouxianzhijinkoujishuguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进我国技术进口的发展，根据《中华人民共和国对外贸易法》、《中华人民共和国技术进出口管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"凡列入《中国禁止进口限制进口技术目录》(另行发布)中禁止进口的技术，不得进口。"},{"i":3,"n":"第三条","txt":"国家对限制进口的技术实行许可证管理，凡进口列入《中国禁止进口限制进口技术目录》中限制进口技术的，应按本办法履行进口许可手续。"},{"i":4,"n":"第四条","txt":"各省、自治区、直辖市商务主管部门(以下简称地方商务主管部门)是限制进口技术的审查机关，负责本行政区域内限制进口技术的许可工作。中 央管理企业，按属地原则到地方商务主管部门办理许可手续。"},{"i":5,"n":"第五条","txt":"技术进口经营者进口本办法第三条所规定的限制进口技术时，应填写《中国限制进口技术申请书》(以下简称《申请书》，见附表1)，报送地方 商务主管部门履行进口许可手续。"},{"i":6,"n":"第六条","txt":"地方商务主管部门自收到《申请书》之日起30个工作日内，对申请进口的技术进行审查，并决定是否准予进口。 申请人提供的申请材料不完备、申请内容不清或有其他申请不符合规定的情形，地方商务主管部门可要求申请人对申请材料进行修改或补充。"},{"i":7,"n":"第七条","txt":"限制进口技术的审查应包括以下内容： （一）是否危及国家安全、社会公共利益或者公共道德； （二）是否危害人的健康或安全和动物、植物的生命或健康； （三）是否破坏环境； （四）是否符合我国对外承诺的义务"},{"i":8,"n":"第八条","txt":"商务主管部门及其工作人员对在技术进口审查中所知悉的商业秘 密负有保密义务。"},{"i":9,"n":"第九条","txt":"进口申请获得批准后，由地方商务主管部门颁发由商务部统一印制和编号的《中华人民共和国技术进口许可意向书》(以下简称《技术进口许可 意向书》，见附表2)。《技术进口许可意向书》的有效期为3年。 技术进口经营者取得《技术进口许可意向书》后，可对外签订技术进口合同。"},{"i":10,"n":"第十条","txt":"技术进口经营者签订技术进口合同后，应持《技术进口许可意向书》、合同副本及其附件、签约双方法律地位证明文件到地方商务主管部门申 请技术进口许可证。"},{"i":11,"n":"第十一条","txt":"地方商务主管部门应自收到本办法第十条所规定的文件之日起10个工作日内，对技术进口合同的真实性进行审查，并决定是否准予许可。"},{"i":12,"n":"第十二条","txt":"技术进口经营者依照本办法第五条向地方商务主管部门提出技术进口申请，履行进口许可手续时，可一并提交已签订的技术进口合同副本及 其附件和签约双方法律地位证明文件。 地方商务主管部门应在收到前款规定的文件之日起40个工作日内，对申请进口的技术进行审查，并对技术进口合同的真实性进行审查，决定是否准予许可。 申请人提供的申请材料不完备、申请内容不清或有其它申请不符合规定的情形，地方商务主管部门可要求申请人对申请材料进行修改或补充。"},{"i":13,"n":"第十三条","txt":"技术进口经许可的，地方商务主管部门向进口经营者颁发由商务部统一印制和编号的《中华人民共和国技术进口许可证》(以下简称《技术进 口许可证》，见附表3)。限制进口技术的进口合同自技术进口许可证颁发之日起生效。"},{"i":14,"n":"第十四条","txt":"技术进口经营者到地方商务主管部门领取技术进口许可证前，应登录商务部网站上的\"技术进出口合同信息管理系统\"(网址： jsjckqy.fwmys.mofcom.gov.cn )，按程序录入合同内容。"},{"i":15,"n":"第十五条","txt":"需经有关部门审批或核准的投资项目，如涉及限制进口技术，技术进口经营者依照本办法第五条或第十二条规定向地方商务主管部门提出技 术进口申请时，应提交有关部门的批准文件。"},{"i":16,"n":"第十六条","txt":"技术进口经营者获得《技术进口许可证》后，如需更改技术进口内容，应按本办法规定的程序重新履行技术进口许可手续。"},{"i":17,"n":"第十七条","txt":"技术进口经营者凭《技术进口许可证》，办理外汇、银行、税务、海关等相关手续。 凡进口《中国禁止进口限制进口技术目录》中限制进口技术的，技术进口经营者应主动向海关出具《技术进口许可证》，海关凭《技术进口许可证》办理验放手续。"},{"i":18,"n":"第十八条","txt":"商务部负责对地方商务主管部门的技术进口许可进行监督检查。 地方商务主管部门应在每年1月31日前将上年度批准的技术进口许可事项向商务部备案。"},{"i":19,"n":"第十九条","txt":"凡违反本办法规定的，将依据《中华人民共和国技术进出口管理条例》，追究有关当事人和单位的责任。"},{"i":20,"n":"第二十条","txt":"国防军工专有技术的进口不适用本办法。"},{"i":21,"n":"第二十一条","txt":"本办法自公布之日起30日后施行。2002年1月1日起施行的《禁止进口限制进口技术管理办法》(对外贸易经济合作部 国家经济贸易委员会 2001年第18号令)同时废止。"}],"fangzhipinchukouzidongxukezanxingbanfa":[{"i":1,"n":"第一条","txt":"为加强对纺织品出口的统计分析和监测，及时向出口经营者发布纺织品出口预警信息，根据《中华人民共和国对外贸易法》，制定本办法。"},{"i":2,"n":"第二条","txt":"商务部是纺织品出口自动许可的管理机关，会同海关总署负责制定、调整《纺织品出口自动许可目录》，并在实施前30天，特殊情况下不迟于实施前21天以商务部公告等形式对外公布。对列入《纺织品出口自动许可目录》的纺织品通过《纺织品出口自动许可证》实施出口自动许可管理。"},{"i":3,"n":"第三条","txt":"商务部授权配额许可证事务局统一管理、指导全国各发证机构（发证机构名单见附件1）的《纺织品出口自动许可证》发证工作，配额许可证事务局对商务部负责。 配额许可证事务局及各地方商务主管部门为《纺织品出口自动许可证》的发证机构，在配额许可证事务局统一管理下，负责授权范围内的发证工作。"},{"i":4,"n":"第四条","txt":"《纺织品出口自动许可证》（证书样本见附件2）和出口自动许可证专用章（样章见附件3）由商务部负责统一监制并发放至发证机构。各发证机构必须指定专人保管，专管专用。"},{"i":5,"n":"第五条","txt":"列入《纺织品出口自动许可目录》的商品，出口经营者在办理海关出口报关手续前，须向发证机构提出自动许可申请并提供以下书面材料： （一）纺织品出口自动许可证申请表（样表见附件4，出口经营者可到发证机构领取或从商务部网站下载打印）； （二）货物出口合同。 首次申请《纺织品出口自动许可证》的出口经营者，除上述材料外，还应向各发证机构提供以下材料的复印件： （一）营业执照； （二）进出口企业资格证书或对外贸易经营者备案登记表或外商投资企业批准证书； （三）企业年检或外商投资企业联合年检合格证明材料（新设企业可不提交）。 上述材料在备案后如发生变化，出口经营者须及时向各发证机构再次提供。 出口经营者应当对所提交材料的真实性负责，并保证其有关经营活动符合国家法律规定。如果发证机构发现上述材料有错误的，可以责令出口经营者作出修改。"},{"i":6,"n":"第六条","txt":"出口经营者可通过网上申请《纺织品出口自动许可证》。网上申请时，出口经营者可登录指定网站，进入相关申领系统，并按要求在线填写纺织品出口自动许可证申请表（电子表格）。 凡通过网上申请的，出口经营者在领取证书时，须向发证机构提供第五条规定的书面材料。"},{"i":7,"n":"第七条","txt":"各发证机构收到内容正确且形式完备的自动许可申请后，应当予以签发《纺织品出口自动许可证》，最多不超过10个工作日。"},{"i":8,"n":"第八条","txt":"海关在办理相关纺织品出口手续时，须验核加盖出口自动许可证专用章的《纺织品出口自动许可证》。"},{"i":9,"n":"第九条","txt":"商务部将定期在政府网站上公布《纺织品出口自动许可目录》所涉商品的信息。"},{"i":10,"n":"第十条","txt":"《纺织品出口自动许可证》实行\"一批一证\"\"一证一关\"，在公历年度内有效，有效期3个月，逾期作废。《纺织品出口自动许可证》不得买卖、转让、涂改、伪造和变卖。"},{"i":11,"n":"第十一条","txt":"《纺织品出口自动许可证》如有遗失，出口经营者应立即向原发证机构和《纺织品出口自动许可证》证面注明的报关口岸海关书面报告挂失，原发证机构收到挂失报告后，经核实无不良后果的，予以重新补发。"},{"i":12,"n":"第十二条","txt":"未申领《纺织品出口自动许可证》，擅自出口纺织品出口自动许可管理货物的，由海关依照有关法律、行政法规的规定处理。"},{"i":13,"n":"第十三条","txt":"伪造、变造、买卖《纺织品出口自动许可证》或者以欺骗等不正当手段获取《纺织品出口自动许可证》的，依照有关法律、行政法规的规定处理。"},{"i":14,"n":"第十四条","txt":"纺织品出口自动许可适用于所有贸易方式下对全球或者重点国家、地区的出口。具体监管方式见附件5。"},{"i":15,"n":"第十五条","txt":"对从境内区外进入保税区、出口加工区等海关特殊监管区域的列入《纺织品出口自动许可目录》的纺织品，按《保税区海关监管办法》（国函〔1997〕48号）和《中华人民共和国海关对出口加工区监管的暂行办法》（国务院令第389号）的规定办理。"},{"i":16,"n":"第十六条","txt":"本办法由商务部负责解释。"},{"i":17,"n":"第十七条","txt":"本办法自2005年3月1日起施行。 附件"}],"wangluolingshoudisanfangpingtaijiaoyiguizezhidingc516ca3":[{"i":1,"n":"第一条","txt":"为了促进网络零售的健康发展，保护依托第三方平台网络零售活动中各主体的合法权益，维护公共利益，加强公共信息服务，根据有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"网络零售第三方平台经营者制定、修改、实施交易规则应当遵守本规定。"},{"i":3,"n":"第三条","txt":"本规定所称交易规则，是指网络零售第三方平台经营者制定、修改、实施的适用于使用平台服务的不特定主体、涉及社会公共利益的公开规则。 本规定所称网络零售第三方平台经营者，是指为其他经营者进行网络零售提供虚拟经营场所及相关服务，且在中华人民共和国境内经营的法人及其他组织。 本规定所称网络零售，是指以互联网为媒介向消费者销售商品或提供经营性服务的行为。"},{"i":4,"n":"第四条","txt":"网络零售第三方平台交易规则的制定、修改、实施应当遵循公开、公平、公正的原则，遵守法律、行政法规，尊重社会公德，不得扰乱社会经济秩序，损害社会公共利益。"},{"i":5,"n":"第五条","txt":"商务部负责建设网络零售第三方平台交易规则备案系统，省、自治区、直辖市商务主管部门（以下称省级商务主管部门）负责网络零售第三方平台交易规则备案等日常管理。"},{"i":6,"n":"第六条","txt":"网络零售第三方平台经营者制定、修改、实施的下列交易规则应按照本规定公示并备案： （一）基本规则，指网络零售经营者和消费者在第三方平台注册的规则及关于交易成立、有效性和履行的基础性规则。 （二）责任及风险分担规则，指网络零售第三方平台经营者对网络零售经营者和消费者承担民事责任或者免除责任的规则及风险分担的规则。 （三）知识产权保护规则，指保护知识产权以及防止假冒伪劣商品的规则。 （四）信用评价规则，指网络零售第三方平台经营者为交易双方提供信用评价服务，以及收集、记录、披露交易双方信用情况的规则。 （五）消费者权益保护规则，指保护消费者知情权、合理退货权、获得赔偿权等合法权益，保护消费者个人信息及交易记录的规则。 （六）信息披露规则，指网络零售第三方平台经营者对网络零售经营者进行实名登记、审核其法定营业资格的规则。 （七）防范和制止违法信息规则，指网络零售第三方平台经营者防范和制止在其平台"},{"i":7,"n":"第七条","txt":"网络零售第三方平台经营者制定或修改的交易规则，应当在网站主页面醒目位置公开征求意见，并应采取合理措施确保交易规则的利益相关方及时、充分知晓并表达意见，通过合理方式公开收到的意见及答复处理意见，征求意见的时间不得少于七日。"},{"i":8,"n":"第八条","txt":"符合下列情形之一的交易规则，可以不公开征求意见： （一）为符合法律法规要求修改的交易规则； （二）根据省级人民政府有关部门要求，为保护消费者权益，需紧急采取措施的交易规则。"},{"i":9,"n":"第九条","txt":"网络零售第三方平台经营者应在交易规则实施前七日在网站醒目位置予以公开，涉及商业秘密的除外。"},{"i":10,"n":"第十条","txt":"网络零售第三方平台经营者制定、修改、实施的交易规则对网络零售经营者和消费者有重大影响的，应制定合理过渡措施。"},{"i":11,"n":"第十一条","txt":"网络零售第三方平台经营者应当主动采取合理的方式保障利益相关方全面、方便地了解所实施的交易规则的内容，并提请其注意有关免除或限制网络零售第三方平台经营者或者利益相关方责任的内容。 网络零售第三方平台经营者应当按照利益相关方的要求，在收到申请之日起七日内以合理方式对交易规则作出说明。"},{"i":12,"n":"第十二条","txt":"网络零售第三方平台经营者应在交易规则实施七日内自行登录网络零售第三方平台交易规则备案系统，提交本规定所列交易规则、征求的公众意见及意见答复处理情况。"},{"i":13,"n":"第十三条","txt":"网络零售第三方平台经营者对其交易规则进行修改时，应按本规定第十二条的要求将修改部分重新备案。"},{"i":14,"n":"第十四条","txt":"商务主管部门通过网络零售第三方平台交易规则备案系统免费提供已备案交易规则的公开查询服务。"},{"i":15,"n":"第十五条","txt":"任何单位和个人可通过网络零售第三方平台交易规则备案系统向网络零售第三方平台经营者所在地省级商务主管部门举报违反本规定的交易规则。 省级商务主管部门确定举报内容属于本部门职责的应依法及时处理，不属于本部门职责的应及时移送相关部门。"},{"i":16,"n":"第十六条","txt":"国家鼓励行业组织开展行业规范自律，对已备案的交易规则提出意见，建立与网络零售第三方平台经营者的互动机制，推进第三方平台交易规则的标准化与规范化。"},{"i":17,"n":"第十七条","txt":"网络零售第三方平台经营者有下列情形之一的，根据举报，所在地省级商务主管部门可以向其提出行政指导建议书： （一）未按本规定第十一条提醒利益相关方注意有关免除或者限制责任内容的； （二）未按本规定备案交易规则的； （三）备案信息不完整、不真实的。"},{"i":18,"n":"第十八条","txt":"网络零售第三方平台经营者未按本规定制定、修改、实施交易规则的，由所在地省级商务主管部门依据职权责令限期改正，拒不改正的，处以警告，并向社会公布。"},{"i":19,"n":"第十九条","txt":"网络零售第三方平台经营者制定、修改、实施交易规则损害社会公共利益，构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"网络零售第三方平台经营者违反本规定第十二条、第十三条，未备案或提交虚假备案信息的，由所在地省级商务主管部门依据职权责令限期改正，拒不改正的，处以警告，并向社会公布。"},{"i":21,"n":"第二十一条","txt":"商务主管部门及其工作人员违反本规定，拒不履行职责，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"本规定施行之日前已经实施的交易规则，网络零售第三方平台经营者应当在本规定施行之日起六十日内进行备案。"},{"i":23,"n":"第二十三条","txt":"本规定自2015年4月1日起施行。"}],"meirongmeifayeguanlizanxingbanfa":[{"i":1,"n":"第一条","txt":"为了促进美容美发业的健康发展，规范美容美发服务行为，维护美容美发经营者和消费者的合法权益，根据国家有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事美容美发经营活动，适用本办法。 本办法所称美容，是指运用手法技术、器械设备并借助化妆、美容护肤等产品，为消费者提供人体表面无创伤性、非侵入性的皮肤清洁、皮肤保养、化妆修饰等服务的经营性行为。 本办法所称美发，是指运用手法技艺、器械设备并借助洗发、护发、染发、烫发等产品，为消费者提供发型设计、修剪造型、发质养护等服务的经营性行为。"},{"i":3,"n":"第三条","txt":"商务部主管全国美容美发业工作，各级商务主管部门在本行政区域内对美容美发业进行指导、协调、监督和管理。"},{"i":4,"n":"第四条","txt":"从事美容美发经营活动的经营者，应当符合下列基本条件： （一）具有承担民事责任的能力; （二）具有固定的经营场所； （三）具有与所经营的服务项目相适应的设施设备； （四）具有取得相应资格证书的专业技术人员。"},{"i":5,"n":"第五条","txt":"美容美发经营者应当具有明确的服务项目范围，并按照其服务项目范围提供服务，同时从事医疗美容服务的，应当符合卫生管理部门的有关规定。"},{"i":6,"n":"第六条","txt":"国家鼓励美容美发经营者采用国际上先进的服务理念、管理方式和经营方式，为消费者提供优质服务。"},{"i":7,"n":"第七条","txt":"国家在美容美发业推行分等定级标准，实行等级评定制度，促进美容美发行业的规范化和专业化。"},{"i":8,"n":"第八条","txt":"美容美发经营者及从业人员应当遵守国家法律、法规和相关的职业道德规范，不得从事色情服务等违法活动。"},{"i":9,"n":"第九条","txt":"美容美发经营者应当执行本行业的专业技术条件、服务规范、质量标准和操作规程。"},{"i":10,"n":"第十条","txt":"从事美容美发服务的美容师、美发师及其他专业技术人员，应当取得国家有关部门颁发的资格证书，其他从业人员应当经过有关专业组织或机构进行的培训并取得合格证书。"},{"i":11,"n":"第十一条","txt":"美容美发经营者应当在经营场所醒目位置上明示营业执照、卫生许可证、服务项目和收费标准等。"},{"i":12,"n":"第十二条","txt":"美容美发经营者在提供服务时应当向消费者说明服务价格。对在服务过程中销售的美容美发用品应当明码标价。对所使用的美容美发用品和器械应当向消费者展示，供消费者选择使用。 美容美发经营者在提供服务后，应当向消费者出具相应的消费凭证或者服务单据。"},{"i":13,"n":"第十三条","txt":"美容美发经营者在提供服务时，应当询问消费者的要求，向消费者提供与服务有关的真实信息，对消费者提出的有关产品、服务等方面的问题，应当做出真实明确的答复，不得欺骗和误导消费者。"},{"i":14,"n":"第十四条","txt":"美容美发服务所使用和销售的各种洗发、护发、染发、烫发和洁肤、护肤、彩妆等用品以及相应器械，应当符合国家有关产品质量和安全卫生的规定和标准，不得使用和销售假冒伪劣产品。"},{"i":15,"n":"第十五条","txt":"美容美发经营场所应当符合有关卫生规定和标准，具有相应的卫生消毒设备和措施；从业人员必须经过卫生部门的健康检查，持健康证明上岗。"},{"i":16,"n":"第十六条","txt":"各级商务主管部门应当加强对本行政区域内的美容美发业的管理与协调，指导当地行业协会（商会），在信息、标准、培训、信用、技术等方面开展服务工作。"},{"i":17,"n":"第十七条","txt":"美容美发行业协会（商会）应当积极为经营者提供服务，维护经营者的合法权益，加强对美容美发行业发展的引导和监督，做好行业自律工作。 美容美发经营者应当向当地美容美发协会（商会）进行企业信息备案登记。"},{"i":18,"n":"第十八条","txt":"各级商务主管部门对于违反本办法的美容美发经营者可以予以警告，令其限期改正；必要时，可以向社会公告。对依据有关法律、法规应予以处罚的，各级商务主管部门可以提请有关部门依法处罚。"},{"i":19,"n":"第十九条","txt":"各省、自治区、直辖市商务主管部门可以依据本办法，结合本行政区域内的美容美发业实际情况，制定有关实施办法。"},{"i":20,"n":"第二十条","txt":"本办法由商务部负责解释。"},{"i":21,"n":"第二十一条","txt":"本办法自2005年1月1日起实施。"}],"huowuchukouxukezhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了合理配置资源，规范出口经营秩序，营造公平透明的贸易环境，履行我国加入的国际公约和条约，维护国家经济利益和安全，根据《中华人民共和国对外贸易法》和《中华人民共和国货物进出口管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"国家实行统一的货物出口许可证制度。国家对限制出口的货物实行出口许可证管理。"},{"i":3,"n":"第三条","txt":"商务部是全国出口许可证的归口管理部门，负责制定出口许可证管理办法及规章制度，监督、检查出口许可证管理办法的执行情况，处罚违规行为。 商务部会同海关总署制定、调整和发布年度《出口许可证管理货物目录》。商务部负责制定、调整和发布年度《出口许可证管理货物分级发证目录》。 《出口许可证管理货物目录》和《出口许可证管理分级发证目录》由商务部以公告形式发布。"},{"i":4,"n":"第四条","txt":"商务部授权配额许可证事务局（以下简称许可证局）统一管理、指导全国各发证机构的出口许可证签发工作，许可证局对商务部负责。"},{"i":5,"n":"第五条","txt":"许可证局及商务部驻各地特派员办事处（以下简称各特办）和各省、自治区、直辖市、计划单列市以及商务部授权的其他省会城市商务厅（局）、外经贸委（厅、局）（以下简称各地方发证机构）为出口许可证发证机构，在许可证局统一管理下，负责授权范围内的发证工作。"},{"i":6,"n":"第六条","txt":"本办法所称出口许可证包括出口配额许可证和出口许可证。凡实行出口配额许可证管理和出口许可证管理的货物，对外贸易经营者（以下简称经营者）应当在出口前按规定向指定的发证机构申领出口许可证，海关凭出口许可证接受申报和验放。"},{"i":7,"n":"第七条","txt":"出口许可证不得买卖、转让、涂改、伪造和变造。"},{"i":8,"n":"第八条","txt":"经营者申领出口许可证时，应当认真如实填写出口许可证申请表（正本）1份，并加盖印章。实行网上申领的，应当认真如实地在线填写电子申请表并传送给相应的发证机构。"},{"i":9,"n":"第九条","txt":"经营者申领出口许可证时，应当向发证机构提交有关出口货物配额或者其他有关批准文件。"},{"i":10,"n":"第十条","txt":"经营者申领出口许可证时，应当向发证机构提交加盖对外贸易经营者备案登记专用章的《对外贸易经营者备案登记表》或者《中华人民共和国进出口企业资格证书》或者外商投资企业批准证书（复印件）。"},{"i":11,"n":"第十一条","txt":"各发证机构按照商务部制定的《出口许可证管理货物目录》和《出口许可证管理分级发证目录》范围，依照下列规定签发出口许可证： （一）实行配额许可证管理的出口货物，凭商务部或者各省、自治区、直辖市、计划单列市以及商务部授权的其他省会城市商务厅（局）、外经贸委（厅、局）（以下简称各地商务主管部门）下达配额的文件和经营者的出口合同（正本复印件）签发出口许可证。 （二）实行配额招标的出口货物，凭商务部发布的中标经营者名单、中标数量、《申领配额招标货物出口许可证证明书》或者《配额招标货物转受让证明书》以及中标经营者的出口合同（正本复印件）签发出口许可证。 （三）易制毒化学品的出口，凭《商务部易制毒化学品出口批复单》和经营者的出口合同（正本复印件）签发出口许可证。 （四）计算机的出口，凭商务部批准的《出口计算机技术审查表》和经营者的出口合同（正本复印件）签发出口许可证。 （五）监控化学品的出口，凭国家履"},{"i":12,"n":"第十二条","txt":"加工贸易项下属于出口许可证管理的货物，发证机构按照商务部制定的《出口许可证管理货物目录》和《出口许可证管理分级发证目录》，凭商务部授权的加工贸易审批机关签发的《加工贸易业务批准证》及本办法第十一条规定的出口批准文件（属于出口配额管理但不使用配额数量的商品凭商务部批件）、海关加工贸易进口报关单和经营者的出口合同（正本复印件）签发出口许可证。 以加工贸易方式出口监控化学品、易制毒化学品、消耗臭氧层物质以及其他国际公约管辖的货物，按照本办法第十一条签发出口许可证。"},{"i":13,"n":"第十三条","txt":"外商投资企业出口属于出口许可证管理的货物，应当按以下规定办理： （一）外商投资企业出口属于出口配额管理的货物，发证机构凭商务部下达的外商投资企业出口配额数量签发许可证；出口配额招标管理的货物，应当附带第十一条第（二）款规定的有关批准文件； （二）涉及第十一条（三）到（七）款及第十二条之情形的，按照相应条款规定办理。"},{"i":14,"n":"第十四条","txt":"我国企业在国外及香港、澳门投资设立的独资、合资和合作企业，需国内供应属于出口许可证管理的货物，发证机构凭商务部批准文件和商务部境外企业批准证书或者商务部境外带料加工装配企业批准证书，按照本办法第十一条签发出口许可证。"},{"i":15,"n":"第十五条","txt":"经商务部批准具有对外经济技术合作经营资格的企业为履行国（境）外承包工程、劳务合作、设计咨询等项目合同出口的设备（含成套设备）、材料、施工器械及人员自用的生活物资属于出口许可证管理的货物，按照本办法第十一条签发出口许可证。"},{"i":16,"n":"第十六条","txt":"出口成套设备需运出境外项目自用属于出口许可证管理的货物，按照本办法第十一条签发出口许可证。"},{"i":17,"n":"第十七条","txt":"偿还国外贷款或者补偿贸易项下属于出口许可证管理的货物，发证机构按商务部制定的《出口许可证管理货物目录》和《出口许可证管理分级发证目录》，凭商务部下达的偿还国外贷款或者补偿贸易的出口配额签发出口许可证。未办理备案登记的法人、其他组织或者个人从事偿还国外贷款或者补偿贸易业务时，应当委托经营者代理出口，并由该经营者办理出口许可证。"},{"i":18,"n":"第十八条","txt":"经营者申领出口许可证时，应当按本办法如实申报，不得弄虚作假，严禁以假合同、假文件等手段骗领出口许可证。"},{"i":19,"n":"第十九条","txt":"各发证机构应当严格按照年度《出口许可证管理货物目录》和《出口许可证管理分级发证目录》的要求，自收到符合规定的申请之日起3个工作日内签发相关出口货物的出口许可证，不得违反规定发证。经营者出口《出口许可证管理货物目录》中的货物，应当到《出口许可证管理分级发证目录》指定的发证机构申领出口许可证。"},{"i":20,"n":"第二十条","txt":"许可证局、各特办和各地方发证机构应当严格按照商务部发布的《出口许可证管理分级发证目录》签发出口许可证。实行网上申领出口许可证的，按照有关程序和规定办理。 （一）许可证局发证范围： 1．按照商务部规定的《出口许可证管理分级发证目录》，签发《出口许可证管理分级发证目录》授权范围内的出口许可证。2．在京的中央管理企业的出口许可证。 （二）各特办发证范围： 1．按照商务部规定的《出口许可证管理分级发证目录》，签发联系地区内经营者、联系地区内中央管理企业及配额由地方管理的在京中央管理企业子公司的出口许可证； 2．按商务部规定的《出口许可证管理分级发证目录》，签发联系地区内经营者配额招标货物出口许可证； 3．签发商务部规定的其他货物的出口许可证。 （三）各地方发证机构发证范围： 1．按商务部规定的《出口许可证管理分级发证目录》签发本地经营者出口许可证； 2．签发商务部规定的其他货物的出口许可证。"},{"i":21,"n":"第二十一条","txt":"各发证机构不得无配额、超配额、越权或者超发证范围签发出口许可证。发证机构的工作人员在履行职责过程中，不得玩忽职守、徇私舞弊或者滥用职权，不得利用职务上的便利索取他人财物，或者非法收受他人财物为他人谋取利益。"},{"i":22,"n":"第二十二条","txt":"出口许可证管理实行\"一证一关\"制、\"一批一证\"制和\"非一批一证\"制。\"一证一关\"指出口许可证只能在一个海关报关；\"一批一证\"指出口许可证在有效期内一次报关使用。 下列情况实行\"非一批一证\"制，签发出口许可证时应在备注栏内注明\"非一批一证\"： （一）外商投资企业出口许可证管理的货物； （二）补偿贸易项下出口许可证管理的货物； （三）其它在《出口许可证管理货物目录》中规定实行\"非一批一证\"的出口许可证管理货物。 \"非一批一证\"指出口许可证在有效期内可以多次报关使用，但最多不超过12次，由海关在\"海关验放签注栏\"内逐批签注出运数。"},{"i":23,"n":"第二十三条","txt":"溢装货物应当为大宗、散装货物。溢装数量按照国际贸易惯例办理，即报关出口的大宗、散装货物的溢装数量不得超过出口许可证所列出口数量的5%。不实行\"一批一证\"制的大宗、散装货物，每批货物出口时，按其实际出口数量进行核扣，最后一批出口货物出口时，其溢装数量按该许可证实际剩余数量并在规定的溢装上限5%内计算。 发证机构在签发此类出口货物许可证时，应当严格按照出口配额数量及批准文件核定的数量签发，并按许可证实际签发数量核扣配额数量，不在出口配额数量或者批准文件核定的数量基础上加上按国际贸易惯例允许的溢装数量签发许可证。"},{"i":24,"n":"第二十四条","txt":"对外经援项目出口实行出口许可证管理的货物免领出口许可证。有关验放凭证的规定，由商务部、海关总署和国家质检总局另行制定和发布。"},{"i":25,"n":"第二十五条","txt":"赴国（境）外参加或者举办展览会运出境外展品、展卖品、小卖品的规定： （一）赴国（境）外参加或者举办展览会所带属于出口许可证管理的非卖展品，免领出口许可证，海关凭出国（境）经济贸易展览会审批部门批准办展的文件和出口货物报关单监管验放。参展单位应当在展览会结束后6个月内，将非卖展品如数运回，由海关核销。在特殊情况下，经海关同意，可以延期。 （二）赴国（境）外参加或者举办展览会带出的展卖品、小卖品，属于出口许可证管理的，参展单位凭出国（境）经济贸易展览会审批部门的批准文件，向《分级发证目录》规定的发证机构申领出口许可证，不占用出口配额。 （三）监控化学品、易制毒化学品、消耗臭氧层物质以及其他国际公约管辖的货物，按正常出口办理，不适用本条第（一）、（二）项规定。"},{"i":26,"n":"第二十六条","txt":"出口货物样品和文化交流或者技术交流需对外提供属于出口许可证管理货物的货样的规定： （一）经营者运出国（境）外属于出口许可证管理货物的货样或者实验用样品，每批货物价值在人民币3万元（含3万元）以下者，免领出口许可证，海关凭经营者填写的出口货样报关单查验放行；超过3万元者，视为正常出口，经营者按规定申领出口许可证。出口许可证备注栏内应当注明\"货样\"字样。 （二）监控化学品、易制毒化学品、消耗臭氧层物质以及其他国际公约管辖的货物对外提供货样，按正常出口办理，不适用本条第（一）项规定。"},{"i":27,"n":"第二十七条","txt":"中国政府根据两国政府间的协议或者临时决定，对外提供捐赠品或者中国政府、组织基于友好关系向对方国家政府、组织赠送的物资，涉及出口许可证管理的货物，凭有关协议或者决定签发出口许可证，不占用出口配额。 其他捐赠，涉及出口许可证管理的，按本办法第十一条签发出口许可证。"},{"i":28,"n":"第二十八条","txt":"出口配额的有效期为当年12月31日前（含12月31日），另有规定者除外，经营者应当在配额有效期内向发证机构申领出口许可证。"},{"i":29,"n":"第二十九条","txt":"各发证机构可自当年12月10日起，根据商务部或者各地方商务主管部门下发的下一年度出口配额签发下一年度的出口许可证，有效期自下一年度1月1日起。"},{"i":30,"n":"第三十条","txt":"出口许可证的有效期最长不得超过6个月，且有效期截止时间不得超过当年12月31日。 以加工贸易方式出口属于配额许可证管理的货物，其出口许可证有效期按《加工贸易业务批准证》核定的出口期限核发，但不得超过当年12月31日。如《加工贸易业务批准证》核定的出口期限超过当年12月31日，经营者应在原出口许可证有效期内向发证机构提出换发新一年出口许可证。发证机构收回原证，在发证系统中对原证进行核销，扣除已使用的数量后，按《加工贸易业务批准证》核定的出口期限重新签发新一年度出口许可证，并在备注栏中注明原证证号。 商务部可视具体情况，调整某些货物出口许可证的有效期和申领时间。 出口许可证应当在有效期内使用，逾期自行失效，海关不予放行。"},{"i":31,"n":"第三十一条","txt":"出口许可证因故在有效期内未使用，经营者应当在出口许可证有效期内向原发证机构提出延期申请，发证机构收回原证，在发证计算机管理系统中注销原证后，重新签发出口许可证，并在备注栏中注明延期使用和原证证号。 出口许可证因故在有效期内未使用完，经营者应当在出口许可证有效期内向原发证机构提出未使用部分的延期申请，发证机构收回原证，在发证系统中对原证进行核销，扣除已使用的数量后，重新签发出口许可证，并在备注栏中注明延期使用和原证证号。 使用当年出口配额领取的出口许可证办理延期，其延期最长不得超过当年12月31日。 未在出口许可证有效期内提出延期申请，出口许可证逾期自行失效，发证机构不再办理延证手续，该出口许可证货物数量视为配额持有者自动放弃。"},{"i":32,"n":"第三十二条","txt":"出口许可证签发后，任何单位和个人不得擅自更改证面内容；如需要对证面内容进行更改，经营者应当在出口许可证有效期内将出口许可证退回原发证机构，重新申领出口许可证。"},{"i":33,"n":"第三十三条","txt":"已领取的出口许可证如遗失，经营者应当立即向许可证证面注明的出口口岸地海关及相关发证机构书面报告，并在全国性经济类报刊中登载\"遗失声明\"，发证机构凭遗失声明，并经核实该证确未通关后，可注销该证，并核发新证。"},{"i":34,"n":"第三十四条","txt":"海关、工商、公安、纪检、法院等单位需要向发证机构查询或者调查出口许可证，应当依法出示有关证件，发证机关方可接受查询。"},{"i":35,"n":"第三十五条","txt":"出口许可证管理货物在发证机构调整时，自调整之日起，原发证机构不得再签发该货物的出口许可证，并将经营者在调整前的申领情况报调整后的发证机构。经营者在调整前申领的许可证在有效期内继续有效。有效期内未使用或者未完全使用的许可证按规定到调整后的发证机构办理延期手续。"},{"i":36,"n":"第三十六条","txt":"商务部授权许可证局对各发证机构进行定期检查。检查的内容为发证机构执行本办法的情况，重点是检查是否有超配额、无配额或者越权越级违章发证以及其他违反本办法的问题。检查的方式，实行各发证机构定期或者不定期自查与许可证局抽查相结合的办法。 许可证局应当将检查的情况向商务部报告。"},{"i":37,"n":"第三十七条","txt":"各发证机构应当按照商务部许可证联网核查的规定及时传送发证数据，以保证经营者顺利报关和海关核查；对海关反馈的核查数据应当认真核对，及时检查许可证的使用情况并找出存在的问题。许可证局应当定期将核对后的海关反馈核查数据报商务部。"},{"i":38,"n":"第三十八条","txt":"对违反本办法第二十一条，超配额，无配额和越权越级发证的发证机构，商务部将视情节轻重给予其警告、暂停或者取消发证权等处分。"},{"i":39,"n":"第三十九条","txt":"对伪造、变造或者买卖出口许可证的经营者，依照刑法关于非法经营罪或者伪造、变造、买卖国家机关公文、证件、印章罪的规定，依法追究刑事责任；尚不够刑事处罚的，依照海关法等相关法律法规的有关规定处罚。 对以欺骗或者其他不正当手段获取出口许可证的，商务部依法收缴其出口许可证。 商务部可以禁止违法行为人自前两款规定的行政处罚决定生效之日或者刑事处罚判决生效之日起一年以上三年以下的期限内从事有关的对外贸易经营活动。在禁止期限内，海关根据商务部依法作出的禁止决定，对该经营者的有关出口货物不予办理报关验放手续，外汇管理部门或者外汇指定银行不予办理有关结汇、售汇手续。"},{"i":40,"n":"第四十条","txt":"超配额，无配额和越权越级发放的许可证无效。对第三十七条、第三十八条所涉出口许可证，一经查实，商务部予以吊销处理。对海关在实际监管或者案件处理过程中发现的涉及上述许可证的问题，发证部门应当给予明确回复。"},{"i":41,"n":"第四十一条","txt":"对违反第二十五条第（一）款有关规定，未将属于出口许可证管理的非卖展品如数运回由海关核销的，由海关通知商务部，商务部和出国（境）经济贸易展览会审批部门视情节轻重给予该组展单位和参展单位警告、暂停审批其出国（境）展览项目一至两年等处分。"},{"i":42,"n":"第四十二条","txt":"对发证机构工作人员违反本办法第二十一条构成犯罪的，依照《中华人民共和国刑法》的有关规定追究其刑事责任。对发证机构工作人员违反本办法尚不构成犯罪的，应当调离工作岗位，并根据《中华人民共和国公务员法》第五十五、第五十六条给予行政处分。"},{"i":43,"n":"第四十三条","txt":"中国关境内其他地区货物进入到保税仓库、保税区和出口加工区的，按照现行有关规定执行。出口监管仓库、保税区、出口加工区的货物出口到境外，按现行规定执行。"},{"i":44,"n":"第四十四条","txt":"边境贸易项下出口许可证管理仍按照现行有关规定执行。"},{"i":45,"n":"第四十五条","txt":"《敏感物项和技术出口许可证》管辖货物不适用本办法。"},{"i":46,"n":"第四十六条","txt":"本办法由商务部负责解释。"},{"i":47,"n":"第四十七条","txt":"本办法自2008年7月1日起施行。原《货物出口许可证管理办法》（商务部令2004年第28号）同时废止。"}],"huowuzidongjinkouxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了对部分货物的进口实行有效监测，规范货物自动进口许可管理，根据《中华人民共和国对外贸易法》和《中华人民共和国货物进出口管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"从事货物进口的对外贸易经营者或者其他单位，将属于《自动进口许可管理货物目录》内的商品，进口到中华人民共和国境内，适用本办法。"},{"i":3,"n":"第三条","txt":"中华人民共和国商务部（以下简称商务部）根据监测货物进口情况的需要，对部分进口货物实行自动许可管理，并至少在实施前21天公布其目录。"},{"i":4,"n":"第四条","txt":"自动进口许可管理货物目录由商务部会同海关总署等有关部门制定、调整和公布。 商务部、海关总署等有关部门在各自的职责范围内，对申请、使用货物自动进口许可证的活动进行监督检查。"},{"i":5,"n":"第五条","txt":"商务部配额许可证事务局、商务部驻有关地方特派员办事处和受商务部委托的各省、自治区、直辖市、计划单列市、新疆生产建设兵团商务主管部门以及地方、部门机电产品进出口办公室或者法律、行政法规规定的机构（以下简称发证机构）负责货物自动进口许可管理和《中华人民共和国自动进口许可证》（以下简称自动进口许可证）的签发工作。 商务部制定和公布货物自动进口许可证分级发证机构名单。"},{"i":6,"n":"第六条","txt":"《自动进口许可证》（样表见附件三）和自动进口许可证专用章（样章见附件四）由商务部负责统一监制并发放至发证机构。各发证机构必须指定专人保管，专管专用。"},{"i":7,"n":"第七条","txt":"进口属于自动进口许可管理的货物，收货人（包括进口商和进口用户）在办理海关报关手续前，应向所在地或相应的发证机构提交自动进口许可证申请，并取得《自动进口许可证》。 凡申请进口法律法规规定应当招标采购的货物，收货人应当依法招标。 海关凭加盖自动进口许可证专用章的《自动进口许可证》办理验放手续。银行凭《自动进口许可证》办理售汇和付汇手续。"},{"i":8,"n":"第八条","txt":"收货人申请自动进口许可证，应当提交以下材料： 1、收货人从事货物进出口的资格证书、备案登记文件或者外商投资企业批准证书或营业执照（复印件）（以上证书、文件仅限公历年度内初次申领者提交）； 2、自动进口许可证申请表（式样见附件五）； 3、货物进口合同； 4、属于委托代理进口的，应当提交委托代理进口协议（正本）； 5、对进口货物用途或者最终用户法律法规有特定规定的，应当提交进口货物用途或者最终用户符合国家规定的证明材料； 6、针对不同商品在《目录》中列明的应当提交的材料； 7、商务部规定的其他应当提交的材料。 收货人应当对所提交材料的真实性负责，并保证其有关经营活动符合国家法律规定。"},{"i":9,"n":"第九条","txt":"收货人可以直接向发证机构书面申请《自动进口许可证》，也可以通过网上申请。 书面申请：收货人可以到发证机构领取或者从相关网站下载《自动进口许可证申请表》（可复印）等有关材料，按要求如实填写，并采用送递、邮寄或者其他适当方式，与本办法规定的其他材料一并递交发证机构。 网上申请：收货人应当先到省级商务主管部门申领用于收货人身份认证的电子认证证书和电子钥匙。申请时，登录相关网站，进入相关申领系统，按要求如实在线填写《自动进口许可证申请表》等资料。同时向发证机构提交本办法规定的有关材料。"},{"i":10,"n":"第十条","txt":"许可申请内容正确且形式完备的，发证机构收到后应当予以签发《自动进口许可证》，最多不超过10个工作日。"},{"i":11,"n":"第十一条","txt":"收货人符合国家关于从事自动进口许可货物有关法律法规要求的，可申请和获得《自动进口许可证》。"},{"i":12,"n":"第十二条","txt":"以下列方式进口自动许可货物的，可以免领《自动进口许可证》。 1、加工贸易项下进口并复出口的（原油、成品油除外）； 2、外商投资企业作为投资进口或者投资额内生产自用的； 3、货样广告品、实验品进口，每批次价值不超过5000元人民币的； 4、暂时进口的海关监管货物； 5、国家法律法规规定其他免领《自动进口许可证》的。"},{"i":13,"n":"第十三条","txt":"进入海关特殊监管区域或保税场所的属自动进口许可管理的货物，不适用本办法。从海关特殊监管区域或保税场所进口自动进口许可管理货物的，除本办法第十二条规定外，仍应当领取自动进口许可证。"},{"i":14,"n":"第十四条","txt":"加工贸易进口自动许可管理货物，应当按有关规定复出口。因故不能复出口而转内销的，按现行加工贸易转内销有关审批程序申领《自动进口许可证》，各商品具体申领规定详见《自动进口许可管理货物目录》。"},{"i":15,"n":"第十五条","txt":"国家对自动进口许可管理货物采取临时禁止进口或者进口数量限制措施的，自临时措施生效之日起，停止签发《自动进口许可证》。"},{"i":16,"n":"第十六条","txt":"收货人已申领的《自动进口许可证》，如未使用，应当在有效期内交回原发证机构，并说明原因。发证机构对收货人交回的《自动进口许可证》予以撤销。 《自动进口许可证》如有遗失，收货人应当立即向原发证机构以及自动进口许可证证面注明的进口口岸地海关书面报告挂失。原发证机构收到挂失报告后，经核实无不良后果的，予以重新补发。 《自动进口许可证》自签发之日起1个月后未领证的，发证机构可予以收回并撤销。"},{"i":17,"n":"第十七条","txt":"海关对散装货物溢短装数量在货物总量正负5%以内的予以免证验放。对原油、成品油、化肥、钢材四种大宗货物的散装货物溢短装数量在货物总量正负3%以内予以免证验放。"},{"i":18,"n":"第十八条","txt":"商务部对《自动进口许可证》项下货物原则上实行\"一批一证\"管理，对部分货物也可实行\"非一批一证\"管理。 \"一批一证\"指：同一份《自动进口许可证》不得分批次累计报关使用。同一进口合同项下，收货人可以申请并领取多份《自动进口许可证》。 \"非一批一证\"指：同一份《自动进口许可证》在有效期内可以分批次累计报关使用，但累计使用不得超过六次。海关在《自动进口许可证》原件\"海关验放签注栏\"内批注后，海关留存复印件，最后一次使用后，海关留存正本。 对\"非一批一证\"进口实行自动进口许可管理的大宗散装商品，每批货物进口时，按其实际进口数量核扣自动进口许可证额度数量；最后一批货物进口时，其溢装数量按该自动进口许可证实际剩余数量并在规定的允许溢装上限内计算。"},{"i":19,"n":"第十九条","txt":"《自动进口许可证》在公历年度内有效，有效期为6个月。"},{"i":20,"n":"第二十条","txt":"《自动进口许可证》需要延期或者变更，一律在原发证机构重新办理，旧证同时撤销，并在新证备注栏中注明原证号。 实行\"非一批一证\"的自动进口许可证需要延期或者变更，核减原证已报关数量后，按剩余数量发放新证。"},{"i":21,"n":"第二十一条","txt":"未申领《自动进口许可证》，擅自进口自动进口许可管理货物的，由海关依照有关法律、行政法规的规定处理、处罚；构成犯罪的，依法追究刑事责任。"},{"i":22,"n":"第二十二条","txt":"伪造、变造、买卖《自动进口许可证》或者以欺骗等不正当手段获取《自动进口许可证》的，依照有关法律、行政法规的规定处罚；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"自动进口许可证发证管理实施细则由商务部依据本办法另行制定。"},{"i":24,"n":"第二十四条","txt":"本办法由商务部、海关总署负责解释。"},{"i":25,"n":"第二十五条","txt":"本办法自2005年1月1日起施行。此前有关管理规定与本办法不一致的，以本办法为准。 附件： 1.附件三：中华人民共和国自动进口许可证样品 2.附件四：自动进口许可证专用章章样 3.附件五：中华人民共和国自动进口许可证申请表式样"}],"huowujinkouxukezhengguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范进口许可证管理，维护货物进口秩序，促进对外贸易健康发展，根据《中华人民共和国对外贸易法》和《中华人民共和国货物进出口管理条例》的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家实行统一的货物进口许可证制度。国家对限制进口的货物实行进口许可证管理。"},{"i":3,"n":"第三条","txt":"商务部是全国进口许可证的归口管理部门，负责制定进口许可证管理办法及规章制度，监督、检查进口许可证管理办法的执行情况，处罚违规行为。 商务部会同海关总署制定、调整和发布年度《进口许可证管理货物目录》。商务部负责制定、调整和发布年度《进口许可证管理货物分级发证目录》。 《进口许可证管理货物目录》和《进口许可证管理分级发证目录》由商务部以公告形式发布。"},{"i":4,"n":"第四条","txt":"商务部授权配额许可证事务局（以下简称许可证局）统一管理、指导全国各发证机构的进口许可证签发工作，许可证局对商务部负责。"},{"i":5,"n":"第五条","txt":"许可证局及商务部驻各地特派员办事处（以下简称各特办）和各省、自治区、直辖市、计划单列市以及商务部授权的其他省会城市商务厅（局）、外经贸委（厅、局）（以下简称各地方发证机构）为进口许可证发证机构，在许可证局统一管理下，负责授权范围内的发证工作。"},{"i":6,"n":"第六条","txt":"进口许可证是国家管理货物进口的法律凭证。凡属于进口许可证管理的货物，除国家另有规定外，对外贸易经营者（以下简称经营者）应当在进口前按规定向指定的发证机构申领进口许可证，海关凭进口许可证接受申报和验放。"},{"i":7,"n":"第七条","txt":"进口许可证适用于《进口许可证管理货物目录》内货物的进口。"},{"i":8,"n":"第八条","txt":"进口许可证不得买卖、转让、涂改、伪造和变造。"},{"i":9,"n":"第九条","txt":"经营者申领进口许可证时，应当认真如实填写进口许可证申请表，并加盖印章。"},{"i":10,"n":"第十条","txt":"经营者应当根据进口货物情况，向发证机构提交本办法第三章进口许可证发证依据所规定的进口批准文件及相关材料。"},{"i":11,"n":"第十一条","txt":"经营者应当提交经年检合格的《企业法人登记营业执照》及加盖对外贸易经营者备案登记专用章的《对外贸易经营者备案登记表》或者进出口企业资格证书。经营者为外商投资企业的，还应当提交外商投资企业批准证书。进口货物属国家实行国营贸易或者有其他资质管理要求的，应当提供商务部或者相关部门的有关文件。"},{"i":12,"n":"第十二条","txt":"各发证机构按照商务部制定的《进口许可证管理货物目录》和《进口许可证管理货物分级发证目录》范围，依下列规定签发进口许可证： （一）对监控化学品，发证机构凭国家履行禁止化学武器公约工作领导小组办公室批准的《监控化学品进口核准单》和进口合同（正本复印件）签发进口许可证。 （二）对易制毒化学品，发证机构凭商务部《易制毒化学品进口批复单》签发进口许可证。 （三）对消耗臭氧层物质，发证机构凭国家消耗臭氧层物质进出口管理办公室批准的《受控消耗臭氧层物质进口审批单》签发进口许可证。 （四）对依照法律、行政法规的规定，其他需要限制进口的商品，发证机构按照国务院商务主管部门或者由其会同国务院其他有关部门签发的许可文件签发进口许可证。"},{"i":13,"n":"第十三条","txt":"加工贸易方式进口监控化学品、易制毒化学品和消耗臭氧层物质需领取进口许可证，发证机构分别按第十二条第（一）、（二）、（三）款规定办理。"},{"i":14,"n":"第十四条","txt":"外商投资企业进口监控化学品、易制毒化学品和消耗臭氧层物质需领取进口许可证，发证机构分别按第十二条第（一）、（二）、（三）款规定办理。"},{"i":15,"n":"第十五条","txt":"经营者申领进口许可证时，应当按本办法规定如实申报，不得弄虚作假，严禁以假文件、假合同等手段骗领进口许可证。"},{"i":16,"n":"第十六条","txt":"发证机构应当严格按照商务部发布的年度《进口许可证管理货物目录》和《进口许可证管理货物分级发证目录》的规定，签发相关商品的进口许可证。经营者进口《进口许可证管理货物目录》中的商品，必须到《进口许可证管理货物分级发证目录》指定的发证机构申领进口许可证。"},{"i":17,"n":"第十七条","txt":"各发证机构应当凭本办法第三章规定的发证依据发放进口许可证，不得越权或者超发证范围签发进口许可证。"},{"i":18,"n":"第十八条","txt":"进口许可证管理实行“一证一关”管理。一般情况下进口许可证为“一批一证”，如要实行“非一批一证”，应当同时在进口许可证备注栏内打印“非一批一证”字样。 “一证一关”指进口许可证只能在一个海关报关；“一批一证”指进口许可证在有效期内一次报关使用；“非一批一证”指进口许可证在有效期内可多次报关使用，但最多不超过十二次，由海关在许可证背面“海关验放签注栏”内逐批签注核减进口数量。 对进口实行许可证管理的大宗、散装货物，溢装数量按照国际贸易惯例办理，即报关进口的大宗、散装货物的溢装数量不得超过进口许可证所列进口数量的5%。不实行“一批一证”制的大宗、散装货物，每批货物进口时，按其实际进口数量进行核扣，最后一批进口货物进口时，其溢装数量按该许可证实际剩余数量并在规定的溢装上限5%内计算。 发证机构在签发此类进口货物许可证时，应当严格按照进口配额数量及批准文件核定的数量签发，并按许可证实际签发数量核"},{"i":19,"n":"第十九条","txt":"申请符合要求的，发证机构应当自收到申请之日起3个工作日内发放进口许可证。特殊情况下，最多不超过10个工作日。"},{"i":20,"n":"第二十条","txt":"进口许可证的有效期为一年。 （一）进口许可证应当在进口管理部门批准文件规定的有效期内签发。 （二）进口许可证当年有效。特殊情况需要跨年度使用时，有效期最长不得超过次年3月31日。 （三）进口许可证应当在有效期内使用，逾期自行失效，海关不予放行。"},{"i":21,"n":"第二十一条","txt":"进口许可证因故在有效期内未使用的，经营者应当在进口许可证有效期内向原发证机构提出延期申请。发证机构应当将原证收回，在进出口许可证计算机管理系统中注销原证后，重新签发进口许可证，并在备注栏中注明延期使用和原证证号。 进口许可证因故在有效期内未使用完的，经营者应当在进口许可证有效期内向原发证机构提出未使用部分的延期申请，发证机构收回原证，在发证系统中对原证进行核销，扣除已使用的数量后，重新签发进口许可证，并在备注栏内注明延期使用和原证证号。 进口许可证只能延期一次，延期最长不超过三个月。 未在进口许可证有效期内提出延期申请的，进口许可证自行失效，发证机构不再受理延证手续，该进口许可证则视为持有者自动放弃。"},{"i":22,"n":"第二十二条","txt":"进口许可证一经签发，不得擅自更改证面内容。如需更改，经营者应当在许可证有效期内提出更改申请，并将许可证交回原发证机构，由原发证机构重新换发许可证。 许可证更改内容如涉及经营者，进口商品税号、数量、金额、价格、原产地、进口用途、外汇来源，贸易方式，报关口岸等栏目，如原批准机构有相应限制，经营者应当提供原批准机构同意更改的文件。"},{"i":23,"n":"第二十三条","txt":"已领取的进口许可证如果丢失，经营者应当立即向许可证证面注明的进口口岸地海关及相关发证机构书面报告挂失，声明作废，并及时向公安机关报案。发证机构收到经营者遗失报告，经核实该证确未通关使用后，可撤销原进口许可证并核发新证。"},{"i":24,"n":"第二十四条","txt":"海关、工商、公安、纪检、法院等单位需要向发证机构查询或者调查进口许可证，应当依法出示有关证件，发证机关应当接受查询。"},{"i":25,"n":"第二十五条","txt":"进口许可证管理商品在调整发证机构时，自调整之日起，原发证机构不得再签发该商品的进口许可证，并将经营者在调整前的申领情况报调整后的发证机构。经营者在调整前申领的许可证在有效期内继续有效。有效期内未使用或者未全部使用的进口许可证，按规定到调整后的发证机构办理延期手续。"},{"i":26,"n":"第二十六条","txt":"商务部授权许可证局对各发证机构进行定期检查。检查的内容为发证机构执行本办法的情况，重点检查是否有越权越级或者无批件发证等违规行为。检查的方式，实行各发证机构定期或者不定期自查与许可证局抽查相结合的办法。许可证局应当将检查情况向商务部报告。"},{"i":27,"n":"第二十七条","txt":"各发证机构应当按照商务部许可证联网核查的规定及时传送发证数据，以保证经营者顺利报关和海关核查；对海关反馈的核查数据应当认真核对，及时检查许可证的使用情况并找出存在的问题。许可证局应当定期将核对后的海关反馈核查数据报商务部。"},{"i":28,"n":"第二十八条","txt":"越权越级或者无有效批件发放的进口许可证无效。对违反规定的发证机构，商务部将视情节轻重给予其警告、暂停或者取消发证权等处分。"},{"i":29,"n":"第二十九条","txt":"对违反本办法，以欺骗或者其他不正当手段骗领进口许可证的，依法收缴其进口许可证，商务部可以在三年内不受理违法行为人提出的进口许可证申请，或者禁止违法行为人在一年以上三年以下的期限内从事有关货物进口经营活动。"},{"i":30,"n":"第三十条","txt":"对伪造、变造或者买卖进口许可证的，依照刑法关于非法经营罪或者伪造、变造、买卖国家机关公文、证件、印章罪的规定，依法追究刑事责任；尚不够刑事处罚的，依照海关法的有关规定处罚；商务部可以禁止违法行为人在一年以上三年以下的期限内从事有关货物进口经营活动。"},{"i":31,"n":"第三十一条","txt":"对第二十八条、二十九条、三十条所涉及进口许可证，一经查实，商务部予以收缴、吊销。对海关在实际监管或者案件处理过程中发现的涉及上述许可证的问题，发证机构应当给予明确答复和积极配合。"},{"i":32,"n":"第三十二条","txt":"对发证机构工作人员出现违规行为但尚未构成犯罪的，应当调离工作岗位，并视情节轻重分别给予行政处分；构成犯罪的，依法移交司法机关追究其刑事责任。"},{"i":33,"n":"第三十三条","txt":"法律、行政法规对保税仓库、保税区和出口加工区的货物进口管理另有规定的，依照其规定办理。"},{"i":34,"n":"第三十四条","txt":"本办法由商务部负责解释。"},{"i":35,"n":"第三十五条","txt":"本办法自2005年1月1日起施行。原对外贸易经济合作部印发的《货物进口许可证管理办法》（对外贸易经济合作部令2001年第22号）同时废止。"}],"bianjingxiaoemaoyijidianchanpinjinkouguanlishishibc66235":[{"i":1,"n":"第一条","txt":"根据《国务院关于边境贸易有关问题的通知》(国发〔1996〕 2号)和《机电产品进口管理暂行办法》，为简化边境小额贸易进口机电产品的管理，特制定本办法 。"},{"i":2,"n":"第二条","txt":"本办法所称边境小额贸易，指沿陆地边境线经国家批准对外开放的边境县(旗)、边境城市辖区内经批准有边境小额贸易经营权的企业，通过国家指定的陆地边境口岸，与毗邻国家边境地区的企业或其他贸 易机构之间进行的贸易活动。 边境地区已开展的除边民互市贸易以外的其他各类边境贸易形式进口机电产品，均统一纳入边境小额贸易管理。 前款所称边民互市贸易，指边境地区边民在边境线20公里以内、经政府批准的开放点或指 定的集市上，在规定的金额或数量范围内进行的商品交换活动。"},{"i":3,"n":"第三条","txt":"有边境小额贸易经营权的企业通过国家指定的陆地边境口岸进口原产于毗邻国家的机电产品，包括配额产品、特定产品和登记产品，均按照本办法管理。 边民通过互市贸易进口的机电产品，每人每日价值在人民币1000元以下的，不纳入本办法管理，按海关有关监管规定办理。"},{"i":4,"n":"第四条","txt":"边境小额贸易进口配额产品的管理 一、各边境省、自治区机电产品进口办公室(以下简称边境省区进口办 )应于每年10月31 日前向国家机电产品进出口办公室(以下简称国家机电进出口办)申报下年度用于本地区边境小额贸易所需进口配额产品。国家机电进出口办经综合平稳纳入全国配额产品进口方案，报国务院审批。 二、国家机电进出口办将国务院批准的边境小额贸易进口配额总量切块，按产品(不含汽车及关键件)专项下达到各边境省区进口办。 国家机电进出口办为保证边境小额贸易正常进行,在全年进口配额下达前,每年底预按排下年度进口配额。当年第三季度视执行情况，对下达的年度进口配额进行一次调整。 三、用于边境小额贸易的配额不得挪做其他贸易用。 四、国家机电进出口办授权各边境省区进口办，在国家下达的边境小额贸易进口配额内，审批本地区边境小额贸易企业通过国家指定的陆地边境口岸进口原产于毗邻国家的配额产品。 五、边境小额贸易企"},{"i":5,"n":"第五条","txt":"边境小额贸易进口特定产品的管理 一、国家机电进出口办授权各边境省区进口办，审批边境小额贸易企业通过国家指定的陆地 边境口岸进口原产于毗邻国家的特定产品。 二、边境小额贸易企业进口的上述特定产品，可不采取招标方式采购。 三 边境小额贸易企业进口特定产品，应按行政隶属关系，向主管省区进口办领取并填写《机电产品进口申请表》(一式二份)，由主管省区进口办审核并签发《机电产品进口证明》(式样见附件二)。 海关凭边境省区进口办签发的《机电产品进口证明》验放。"},{"i":6,"n":"第六条","txt":"边境小额贸易企业进口登记产品，按行政隶属关系，向主管省区进口办领取并填写《机电产品进口申请表》申请登记；主管省区进口办核发《机电产品进口登记表》；海关凭《机电产品进口登记表》验放。"},{"i":7,"n":"第七条","txt":"边境小额贸易进口机电产品所用《进口配额证明》、《机电产品进口证明》和《机电产品进口登记表》的有效期、更改程序及本办法 未规定的有关事项均按国家经贸委、外经贸部、海关总署联合发布的《配额产品进口管理实施细则》、《特定产品进口管理实施细则》和《机电产 品进口登记须知》有关规定执行。"},{"i":8,"n":"第八条","txt":"边境省区进口办要严格执行机电产品进口统计制度，按要求及时传输进口数据。 边境省区进口办应于每月5日前将上月委托发证的存档联和废证退国家机电进出口办备案。 国家机电进出口办对边境小额贸易进口配额产品和特定产品执行情况，定期进行清理检查。"},{"i":9,"n":"第九条","txt":"对于违反本办法越权审批或超配额签发进口证明及许可证等问题的单位，国家机电进出口办和外经贸部将视情节轻重予以通报批评，直至暂停或撤销授予的审批权和发证权。触及法律者，将依法追究刑事责任。 对有违反海关法行为的，海关将依照《中华人民共和国海关法》和《海关行政处罚实施细则》进行处理。"},{"i":10,"n":"第十条","txt":"本办法由国家机电进出口办负责解释。"},{"i":11,"n":"第十一条","txt":"本办法自1996年4月1日起执行。"}],"jinchukouxukezhengshoufeicaiwuguanlibanfa":[{"i":1,"n":"第一条","txt":"为保证国家财政预算收入及时、足额上缴和进出口许可证各签证机构签证工作的正常进行，根据外经贸部《行政性收费财务管理办法》([1997]外经贸计财字第496号)，结合进出口许可证签证业务的特点，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称国家财政预算收入是指进出口货物许可证手续费收入。即经国家的有关部门批准收取的进出口货物许可证(包括进口许可证、出口许可证)、对设限国家出口纺织品出口许可证、原产地证明书、手工制品证书和装船证书(均含改签原证项目、换证、退证、撤证等)费收入(以下简称许可证手续费)。"},{"i":3,"n":"第三条","txt":"根据财政部《关于将部分行政性收费纳入预算管理的规定》([1994]财预字第37号)，签证机构收取的许可证手续费属中央管理的行政性收费，纳入中央财政预算，实行“收支两条线”管理。"},{"i":4,"n":"第四条","txt":"进出口许可证收费实行预算管理。每年由外经贸部配额许可证事务局(以下简称许可证局)编制年度收支预算，经外经贸部报财政部批准后执行。许可证局受财政部和外经贸部的委托对此项收费实行归口统一管理，是许可证收费的执收单位。"},{"i":5,"n":"第五条","txt":"许可证局授权签发许可证的各省、自治区、直辖市、计划单列市外经贸委(厅局)及外经贸部驻各地特派员办事处(以下简称各签证机构)负有收缴许可证手续费的义务，是许可证收费的委托执收单位。"},{"i":6,"n":"第六条","txt":"许可证局负责对各受委托执收单位的许可证收费、业务费支出及财务管理进行指导、监督、检查及审计。"},{"i":7,"n":"第七条","txt":"各签证机构应依据国家有关部门发放的《收费许可证》收取许可证手续费。"},{"i":8,"n":"第八条","txt":"各签证机构应严格按规定的项目和标准收费，不得更改收费项目、变动收费标准。"},{"i":9,"n":"第九条","txt":"各签证机构收取许可证手续费应使用财政部统一监制的《进出口货物许可证专用收费收据》。"},{"i":10,"n":"第十条","txt":"各签证机构收取的许可证手续费应纳入本单位财务部门统—管理。"},{"i":11,"n":"第十一条","txt":"各签证机构应在银行设立许可证手续费专用过渡帐户，并将收取的许可证手续费全部存入该过渡帐户。该帐户只能存入或缴出许可证手续费。"},{"i":12,"n":"第十二条","txt":"各签证机构应于每季度终了十日内，将过渡账户的许可证手续费足额汇缴许可证局(开户银行：北京工商行王府井分理处，帐号：046218—04)，同时填报许可证手续费结算单(见附单)。任何单位不得截留或挪用许可证手续费。"},{"i":13,"n":"第十三条","txt":"各签证机构签证工作及签证管理工作所需业务费主要由各签证机构负责。许可证局对签证工作的业务费给予适当补助。补助款由许可证局作为业务费开支列入预算。"},{"i":14,"n":"第十四条","txt":"许可证局依据财政部核定的业务费支出预算，结合各签证机构上年度签证数量、专用设备配置情况、人员配备情况和专线通讯费等因素，按基本业务费用和专线通讯费用核定各签证机构签证工作业务费补助款。"},{"i":15,"n":"第十五条","txt":"基本业务费用指为保证许可证的发放及管理工作所必需的费用。包括签证工作所必需的办公费，与签证管理工作有直接关系的差旅费、会议费、一般邮政费、电讯费、小额购置费、专用设备保养维修费、附件配件购置费及机房简易维修、装修、改造费等。专线通讯费用指为实行许可证联网核查，由许可证局配置的专用通讯线路费。"},{"i":16,"n":"第十六条","txt":"基本业务费用的核定 基本业务费按下列三项内容进行核定： （一）按各签证机构上年度签证数量每份X元进行核定。 （二）按各签证机构上年度专用设备配置量每台计算机Y元进行核定。 （三）按各签证机构上年度许可证签发及管理工作人员数量每人Z元进行核定。"},{"i":17,"n":"第十七条","txt":"专线通讯费用的核定 根据许可证局与电讯部门签订的专线通讯协议书规定按实际费用开支进行核定。"},{"i":18,"n":"第十八条","txt":"各签证机构业务费补助款按以下公式计算：上年度签证数量×X元＋专用设备配置量×Y元＋工作人员配置量×Z＋专线通讯费用。X、Y、Z系数根据财政部核定的业务费总额确定。"},{"i":19,"n":"第十九条","txt":"许可证局依据财政部核定的业务费支出预算，将核定的各签证机构业务费补助款划入各机构财务部门统—管理的银行帐户。"},{"i":20,"n":"第二十条","txt":"各签证机构必须按国家有关财务制度规定和本办法第十五条所规定的业务费补助款开支范围、用途进行开支。不得将业务费补助款用于与本签证机构签证业务及签证管理工作无关的费用开支。"},{"i":21,"n":"第二十一条","txt":"各签证机构业务费补助款开支的管理实行业务处长负责制。所有补助款开支必须有经办人员和业务主管处长签字方可报销。"},{"i":22,"n":"第二十二条","txt":"凡使用业务费补助款购置固定资产，需事先报请许可证局批准后方可支出。使用业务费补助款购置的固定资产产权属许可证局，并纳入许可证局设备统—管理。"},{"i":23,"n":"第二十三条","txt":"各机构在年度终了后25日内向许可证局报送年度业务费补助款收支情况表(报表格式附后)，并附文字报告。"},{"i":24,"n":"第二十四条","txt":"各签证机构应按工作计划和任务，本着收支平衡、量入为出的原则，区别轻重缓急，提高业务费补助款的使用效率。业务费补助款当年结余可转下年使用。"},{"i":25,"n":"第二十五条","txt":"《进出口货物许可证专用收费收据》由许可证局统一发放和缴销。各签证机构应建立健全收费票据保管、使用、缴销制度。做到保管与使用分开，领用的票据要按类别、顺序登记造册，专人管理，财务部门要定期予以缴销，缴回的票据号与领用的票据原号要相符，交款金额与票据存根金额相符，入账金额与交款金额相符。票据缴销要按票据管理规定上报票据管理部门同意后，造册登记销毁。"},{"i":26,"n":"第二十六条","txt":"各签证机构收取许可证手续费时，借记：银行存款或现金，贷记：应缴预算款；缴款时，借记：应缴预算款，贷记：银行存款。许可证手续费原则上应采用一证一清的收费方式，对少数经常领证且量较大的单位，可采用先记帐，后结算的方式，但结算周期不得超过一个月。"},{"i":27,"n":"第二十七条","txt":"各签证机构收到许可证局拨付的业务费补助款项后，借记：银行存款，贷记：上级补助收入，并专立费用帐进行业务费补助款开支的核算；业务费补助款开支时，借记：基本业务费用——×××或专线通讯费用，贷记：现金或银行存款。"},{"i":28,"n":"第二十八条","txt":"各签证机构所有许可证手续费收入、缴款和业务费补助款收入、支出必须按财务会计规定的程序进行操作。财务人员应实时监督、检查，凡不符合财务会计规定及本办法规定的事项，财务人员有权予以拒绝。"},{"i":29,"n":"第二十九条","txt":"各签证机构所有进出口许可证财务收支的各种原始凭证、记帐凭证、会计帐簿、会计报表等均应定期装订成册，归档备查，并严格按会计档案管理要求进行管理。"},{"i":30,"n":"第三十条","txt":"财务人员调动工作时，要严格按照财务会计人员工作交接程序进行工作交接。保证财务会计工作和财务会计档案资料的连续性和完整性。"},{"i":31,"n":"第三十一条","txt":"对严格执行国家有关财务规章制度及本办法规定，在财务管理工作中成绩显著的机构或个人，将予以表彰和奖励。"},{"i":32,"n":"第三十二条","txt":"对下列行为，视情况分别给予通报批评、不参加年终考评、核减业务费补助款、不予核拨业务费补助款等处罚。 （一）不按《收费许可证》规定的收费项目和标准收取许可证手续费； （二）不使用《进出口货物许可证专用收费收据》收取许可证手续费； （三）不及时、足额上缴许可证手续费； （四）不按规定的范围、用途开支业务费补助款、不上报业务费补助款收支情况表； （五）以不正当手段骗取业务费补助款或将其挪作他用。"},{"i":33,"n":"第三十三条","txt":"对违反国家财务规章制度、违法违纪者，许可证局提请其上级主管部门依法处理，追究刑事责任。"},{"i":34,"n":"第三十四条","txt":"本办法由许可证局负责解释。"},{"i":35,"n":"第三十五条","txt":"本办法自2000年1月1日起执行。"}],"jinchukouxukezhengzhengshuguanliguiding":[{"i":1,"n":"第一条","txt":"为加强对各类进出口许可证证书（以下简称许可证书）的管理，建立健全规章制度，特制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称许可证书是指由商务部监制完成且尚未发放的各类具有许可进、出口性质的证明、文件、原产地证书等。"},{"i":3,"n":"第三条","txt":"商务部配额许可证事务局（以下简称许可证局）受商务部委托，管理各类许可证书，并监督、检查地方商务主管部门和商务部驻各地特派员办事处（以下简称特办）所属进出口许可证签发机构（以下简称发证机构）对本规定的执行情况。"},{"i":4,"n":"第四条","txt":"发证机构对许可证书的管理实行主要领导负责制，并指定专人承担具体管理工作。 发证机构应建立许可证书的内部管理制度，并认真执行。"},{"i":5,"n":"第五条","txt":"为提高许可证书的使用率，发证机构须认真核算下一年度的许可证书需求量，合理上报征订数量。"},{"i":6,"n":"第六条","txt":"许可证书的征订分为年度征订和补充征订。 许可证书一般一年集中征订一次，特殊情况下可安排多次集中征订。商务部每年10月下发通知征订下年度许可证书，发证机构按照通知要求填写《商务部进出口许可证书需求量报送单》（见附件1，以下简称报送单），并报许可证局。 年度征订后如仍有不足，发证机构应至少提前20个工作日向许可证局提出补充征订申请，并按要求填写报送单，并报许可证局。许可证局审核后，根据核实情况予以补充或调剂。"},{"i":7,"n":"第七条","txt":"发证机构上报报送单，须同时在商务部空白证书管理系统（以下简称空白证书管理系统）中填报相关征订信息。"},{"i":8,"n":"第八条","txt":"许可证局本着科学规划、确保用证、节约高效的原则，统一计划、合理安排许可证书的印制工作。"},{"i":9,"n":"第九条","txt":"许可证局应按照中央国家机关政府采购的相关要求，通过规定程序，从中央国家机关定点印刷厂中选择质量信誉好、技术力量强、证书安全有保障的印制单位。 除许可证局委托的印制单位外，其他任何单位和个人不得擅自印制许可证书。"},{"i":10,"n":"第十条","txt":"许可证局负责监督印制单位按其提供的许可证书样式、数量等要求，在规定时间内印制各类许可证书。"},{"i":11,"n":"第十一条","txt":"许可证局根据发证机构报送的各类许可证书的征订数量，结合印制单位实际库存量、发证机构实际使用量、剩余量等情况，制定许可证书印制与发运计划。"},{"i":12,"n":"第十二条","txt":"许可证书一般一年集中印制一次。集中印制数量不能满足实际发证需求的，许可证局可以根据实际情况及时安排追加印制。"},{"i":13,"n":"第十三条","txt":"每批次印制完毕，许可证局应组织检查验收，验收合格后方可入库。许可证局负责在空白证书管理系统中进行入库登记。 经检查不合格的许可证书，印制单位应及时销毁。"},{"i":14,"n":"第十四条","txt":"对年度征订的许可证书，许可证局应在征订通知规定的时限内发运至各发证机构。补充征订的许可证书，应自收到报送单之日起20个工作日内发运至相应的发证机构。"},{"i":15,"n":"第十五条","txt":"许可证局确定发运明细后通知其委托的发运单位组织发运，发运后发运单位应在空白证书管理系统中进行发运登记。"},{"i":16,"n":"第十六条","txt":"发证机构对许可证书实行专人、专柜、专库统一保管。"},{"i":17,"n":"第十七条","txt":"发证机构须在收到许可证书当日组织现场验收。验收工作应由两名以上工作人员同时在场，按货运单数量认真清点无误后予以签收，并填写《商务部进出口许可证书签收单》（一式三份，见附件2），签收单应于次日寄送发运单位和许可证局，签收单须存档三年。"},{"i":18,"n":"第十八条","txt":"发证机构在验收许可证书时，发现有单证不符、包装损坏和许可证书缺失等情况，应立即封存，作出书面检验记录，由验收人员及主要负责同志签字后连同检验记录报许可证局处理。"},{"i":19,"n":"第十九条","txt":"发证机构在验收许可证书后，应将检验无误的证书及时存入专用库房，并按证书的种类、箱号、流水号分类整理，有序存放，同时在空白证书管理系统中进行接收登记。"},{"i":20,"n":"第二十条","txt":"存放许可证书的库房须具备防火、防潮、防盗等安全设施。库房、专柜的钥匙须由专人负责保管。库房内不得存放其他物品，无关人员不得进入库房。"},{"i":21,"n":"第二十一条","txt":"发证机构应建立各类许可证书的进、出库台账登记制度。"},{"i":22,"n":"第二十二条","txt":"发证机构原则上应分设许可证书保管人员与许可证书领用人员。"},{"i":23,"n":"第二十三条","txt":"领取许可证书时，保管人员和领用人员应同时在场对许可证书逐一清点，并填写《商务部进出口许可证书进、出库台账登记表》（见附件3，以下简称登记表），经保管人员和主要负责同志签字后方可使用。登记表应由许可证书保管人员妥善保管。"},{"i":24,"n":"第二十四条","txt":"领取许可证书时，如发现有缺号、错号、纸张缺页、流水号不连续、无防伪标记等印制错误，应立即封箱，报告主要负责同志，并对检验情况进行书面记录，由保管人员及主要负责同志签字后，连同该箱许可证书一同报许可证局处理。"},{"i":25,"n":"第二十五条","txt":"发证机构在启用各类许可证书时，须在空白证书管理系统中进行使用登记。"},{"i":26,"n":"第二十六条","txt":"对印制错误且已发运到发证机构的许可证书，发证机构应退回许可证局，由许可证局按废证予以登记处理。 对库存期间因火烧、水浸、蛀蚀等造成许可证书损毁的，发证机构应立即书面报许可证局，并将受损证书按废证予以登记处理。 对打印错误和签发之日起20个工作日内未领取的许可证书，发证机构应予撤销，并按废证予以登记处理。"},{"i":27,"n":"第二十七条","txt":"对在保管、使用过程中产生的废证，发证机构须在空白证书管理系统中进行废证登记。"},{"i":28,"n":"第二十八条","txt":"地方商务主管部门或特办之间不得擅自相互借用各类许可证书。特殊情况下，确需临时借用许可证书，须由申请使用方向许可证局提出书面申请，许可证局审核并协商双方同意后统一安排调剂，并在空白证书管理系统中登记调剂信息。"},{"i":29,"n":"第二十九条","txt":"同一地方商务主管部门设立的延伸打印终端间的许可证书调剂由该商务主管部门自主安排，并在空白证书管理系统进行相应登记。"},{"i":30,"n":"第三十条","txt":"许可证书在仓储、运输、保管、使用过程中发生遗失的，相关部门均应立即将有关情况书面报许可证局。"},{"i":31,"n":"第三十一条","txt":"发证机构每季度应对许可证书进行清点核对，核查许可证书的种类、数量等出入库登记与实际使用情况是否相符。"},{"i":32,"n":"第三十二条","txt":"发证机构发现许可证书出入库登记与实际使用情况不符的，应立即查找原因，追究相关责任，采取必要防范和整改措施，同时书面报许可证局。"},{"i":33,"n":"第三十三条","txt":"发证机构应于每年一月底前填写上一年度《商务部进出口许可证书使用情况登记表》（见附件4），并报许可证局。"},{"i":34,"n":"第三十四条","txt":"对因改版而过期的空白许可证书，发证机构须在《商务部过期空白进出口许可证书封存/销毁登记表》（见附件5）上登记，经主要负责同志审核无误后封存。 新版许可证书启用当年，经报上级主管部门分管负责同志批准，旧版空白许可证书按保密文件销毁规定予以销毁，并在《商务部过期空白进出口许可证书封存/销毁登记表》上如实登记。有关销毁的请示签批件及销毁清单须留存备查。销毁情况报许可证局。"},{"i":35,"n":"第三十五条","txt":"发证机构应将废证在《商务部进出口许可证书废证封存/销毁登记表》（见附件6）上登记，经主要负责同志审核后封存。废证保存期为两年。 保存期满的许可证书废证，经报上级主管部门分管负责同志批准，按保密文件销毁规定予以销毁，并在《商务部进出口许可证书废证封存/销毁登记表》上如实登记。有关废证销毁的请示签批件及销毁清单须留存备案。销毁情况报许可证局。"},{"i":36,"n":"第三十六条","txt":"许可证局对发证机构执行本规定的情况定期组织检查或抽查，并将检查结果纳入年度考核范围。"},{"i":37,"n":"第三十七条","txt":"许可证局对发证机构检查或抽查内容包括： （一）发证机构许可证书内部管理制度制定与执行情况； （二）许可证书的征订、验收情况； （三）许可证书的保管及专库、专柜的安全措施情况； （四）许可证书的进、出库台账登记情况； （五）许可证书的使用情况； （六）过期空白许可证书和废证的封存/销毁登记情况； （七）按规定在空白证书管理系统进行登记的情况。"},{"i":38,"n":"第三十八条","txt":"对未执行本规定的发证机构，许可证局视情节轻重给予警告或通报批评，并限期整改。 对不执行本规定造成许可证书丢失、被盗的发证机构，商务部将按照《进出口商品许可证发证机构管理办法》的有关规定进行处罚。"},{"i":39,"n":"第三十九条","txt":"本规定由商务部负责解释。"},{"i":40,"n":"第四十条","txt":"本规定自2012年3月5日起施行，原《进出口许可证证书管理规定》（外经贸配字〔1999〕第87号）同时废止。"}],"zhongdianjiujidianchanpinjinkouguanlibanfa":[{"i":1,"n":"第一条","txt":"为维护国家安全、社会公共利益，保护人的健康或者安全，保护动物、植物的生命或者健康，保护环境，依据《中华人民共和国对外贸易法》、《中华人民共和国进出口商品检验法》、《中华人民共和国行政许可法》、《中华人民共和国海关法》以及《中华人民共和国货物进出口管理条例》、《中华人民共和国进出口商品检验法实施条例》等相关法律和行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于将重点旧机电产品进口到中华人民共和国关境内的行为。 境外进入海关特殊监管区域或海关保税监管场所的重点旧机电产品，以及（境内）区外进入海关特殊监管区域后再出区的重点旧机电产品，不适用本办法。 境外进入海关特殊监管区域或海关保税监管场所的重点旧机电产品，再从海关特殊监管区域或海关保税监管场所进入（境内）区外的重点旧机电产品，适用本办法。"},{"i":3,"n":"第三条","txt":"重点旧机电产品是指涉及国家安全、社会公共利益、人的健康或者安全、动植物的生命或者健康、污染环境的旧机电产品。对重点旧机电产品实行限制进口管理。"},{"i":4,"n":"第四条","txt":"《重点旧机电产品进口目录》纳入《进口许可证管理货物目录》，由商务部会同海关总署制定、调整并公布。"},{"i":5,"n":"第五条","txt":"商务部负责全国重点旧机电产品进口管理工作。 商务部、海关总署在各自的职责范围内，对进口重点旧机电产品的活动进行监督检查。"},{"i":6,"n":"第六条","txt":"重点旧机电产品进口实行进口许可证管理。商务部负责重点旧机电产品进口申请的审批工作，商务部配额许可证事务局负责《进口许可证》（见附件1）的发证工作。"},{"i":7,"n":"第七条","txt":"重点旧机电产品进口应由最终用户提出申请。进口重点旧机电产品用于翻新（含再制造）的，应由具备从事翻新业务资质的单位提出申请。"},{"i":8,"n":"第八条","txt":"申请进口重点旧机电产品，申请进口单位应当向商务部提供以下材料： （一）申请进口的重点旧机电产品用途说明。 （二）《机电产品进口申请表》（见附件2）。 （三）营业执照（复印件）。 （四）申请进口的重点旧机电产品的制造年限证明材料。 （五）申请进口单位提供设备状况说明。 （六）其他相关法律、行政法规规定需要提供的文件。"},{"i":9,"n":"第九条","txt":"从事翻新业务进口重点旧机电产品的单位，国家规定有资质要求的，还须提供已取得相关资质证明的书面承诺。"},{"i":10,"n":"第十条","txt":"进口旧船舶的申请进口单位，须提供第八条第一至第三款所列材料以及船舶检验机构出具的《旧船舶进口检验报告》或中华人民共和国渔业船舶检验局出具的《旧渔业船舶进口技术评定书》。"},{"i":11,"n":"第十一条","txt":"进口单位可以通过网上申请或书面申请向商务部提出重点旧机电产品的进口申请。 书面申请程序：（1）申请进口单位可到发证机构领取或从商务部授权网站下载《机电产品进口申请表》（可复印）；（2）按要求如实填写《机电产品进口申请表》（须在规格型号栏中填写设备制造日期，旧船舶类则填写技术评定书号）；（3）同时提供本办法第八条至第十条规定的相关书面材料；（4）地方、部门机电办核实相关材料后报商务部。 网上申请程序：（1）申请进口单位登录商务部授权网站（http://www.chinabidding.com），进入全国机电产品进口单证管理系统；（2）按要求如实在线填写《机电产品进口申请表》（须在规格型号栏中填写设备制造日期，旧船舶类则填写技术评定书号）；（3）地方、部门机电办核实相关信息后报商务部。 网上申请时不能随《机电产品进口申请表》一并提交的本《办法》第八条至第十条规定的相关书面材料，应经相应的地"},{"i":12,"n":"第十二条","txt":"申请进口单位申请材料齐全后，商务部应正式受理，并向申请进口单位出具受理通知单。 商务部如认为申请材料不符合要求的，应在收到申请材料后的5个工作日内一次性告知申请进口单位，要求申请进口单位说明有关情况、补充相关文件或对相关填报内容进行调整。"},{"i":13,"n":"第十三条","txt":"正式受理申请后，商务部如认为有必要，可征求相关部门或行业协会的意见。"},{"i":14,"n":"第十四条","txt":"商务部应当遵循下列要求审核申请： （一）申请进口重点旧机电产品应当符合国家安全和公共利益的要求，符合保护人的健康或者安全、动植物的生命或者健康的要求。 （二）申请进口重点旧机电产品须符合我国有关安全、卫生、环境保护等国家技术规范的强制性要求。 （三）申请进口单位所申请进口的重点旧机电产品应当与其经营范围相符合。 （四）申请进口单位连续3年内无走私罪、走私行为，偷、逃汇，倒卖进口证件等不法行为。 （五）遵守其它法律、行政法规的有关规定。"},{"i":15,"n":"第十五条","txt":"商务部应在正式受理后20日内决定是否批准进口申请。 如需征求相关部门或行业协会意见的，商务部应在正式受理后35日内决定是否批准进口申请。"},{"i":16,"n":"第十六条","txt":"商务部配额许可证事务局凭商务部的批准文件发放《进口许可证》。"},{"i":17,"n":"第十七条","txt":"进口重点旧机电产品经过检验检疫合格后，方可进口。 中华人民共和国海事局及其委托机构负责对进口旧船舶进行检验；中国渔业船舶检验局负责对进口旧渔船进行检验；中国民航总局负责对进口旧飞机进行检验。 海关负责对其他所有进口重点旧机电产品进行检疫，并负责对进口除旧船舶和航空器之外的重点旧机电产品进行检验；"},{"i":18,"n":"第十八条","txt":"《进口许可证》一式四联。 进口单位凭《进口许可证》对外签约，向银行购汇，并持《进口许可证》（\"商品名称\"栏后标注\"（旧）\"字样）和其他必要材料向海关办理通关手续。"},{"i":19,"n":"第十九条","txt":"《进口许可证》实行\"一批一证\"或\"非一批一证\"管理。 \"一批一证\"是指同一份《进口许可证》不得分批次累计报关使用。 \"非一批一证\"是指同一份《进口许可证》在有效期内可以分批次累计报关使用，但累计使用不得超过十二次。海关在《进口许可证》原件（第一联）\"海关验放签注栏\"内以正楷字体批注后，海关留存复印件，最后一次使用后，海关留存正本。"},{"i":20,"n":"第二十条","txt":"《进口许可证》有效期为1年，且当年有效，特殊情况下需要跨年度使用时，有效期最长不得超过次年3月31日。 在有效期内因特殊原因需要变更《进口许可证》中有关项目内容的，进口单位应当持原《进口许可证》到原发证机构申请办理变更换证手续；原发证机构应当收回旧证。实际用汇额不超过原定用汇额10%的，不需变更《进口许可证》。 因特殊原因需要对《进口许可证》延期的，进口单位应当在有效期内到原发证机构申请办理延期换证手续，《进口许可证》只能延期1次，最长可延长3个月。 实行\"非一批一证\"的《进口许可证》需要延期或变更，核减原证已报关数量后，按剩余数量发放新证。"},{"i":21,"n":"第二十一条","txt":"《进口许可证》如有遗失，进口单位应当立即向原发证机关挂失。经原发证机关核实后，如无不良后果，予以重新补发。"},{"i":22,"n":"第二十二条","txt":"本办法由商务部、海关总署负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自二ΟΟ八年五月一日起施行。"}],"jinrongyejingyingzhejizhongshenbaoyingyeejisuanban9ea786-2":[{"i":1,"n":"第一条","txt":"根据《反垄断法》及《国务院关于经营者集中申报标准的规定》（以下简称《规定》），为明确金融业经营者集中的申报标准，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于银行业金融机构、证券公司、期货公司、基金管理公司和保险公司等金融业经营者集中申报营业额的计算。 银行业金融机构包括商业银行、城市信用合作社、农村信用合作社等吸收公众存款的金融机构以及政策性银行。 对金融资产管理公司、信托公司、财务公司、金融租赁公司、汽车金融公司、货币经纪公司以及经银行业监督管理机构批准设立的其他金融机构的营业额计算办法，适用本办法对银行业金融机构的规定。"},{"i":3,"n":"第三条","txt":"银行业金融机构的营业额要素包括以下项目： 一、 利息净收入； 二、 手续费及佣金净收入； 三、 投资收益； 四、 公允价值变动收益； 五、 汇兑收益； 六、 其他业务收入。"},{"i":4,"n":"第四条","txt":"证券公司的营业额要素包括以下项目： 一、 手续费及佣金净收入（包括经纪业务、资产管理业务、承销与保荐业务和财务顾问业务等）； 二、 利息净收入； 三、 投资收益； 四、 汇兑收益； 五、 其他业务收入。"},{"i":5,"n":"第五条","txt":"期货公司的营业额要素包括以下项目： 一、 手续费及佣金净收入； 二、 银行存款利息净收入。"},{"i":6,"n":"第六条","txt":"基金管理公司的营业额要素包括以下项目： 一、 管理费收入； 二、 手续费收入。"},{"i":7,"n":"第七条","txt":"上述经营者集中申报营业额的计算公式为： 营业额＝（营业额要素累加－营业税金及附加）×10％"},{"i":8,"n":"第八条","txt":"保险公司集中申报营业额的计算公式为： 营业额＝（保费收入－营业税金及附加）×10％ 其中，保费收入＝原保险合同保费收入＋分入保费－分出保费"},{"i":9,"n":"第九条","txt":"以上营业额计算办法仅限用于经营者集中申报。"},{"i":10,"n":"第十条","txt":"本办法自发布之日起三十日后生效。"}],"jinrongyejingyingzhejizhongshenbaoyingyeejisuanban9ea786":[{"i":1,"n":"第一条","txt":"根据《反垄断法》及《国务院关于经营者集中申报标准的规定》（以下简称《规定》），为明确金融业经营者集中的申报标准，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于银行业金融机构、证券公司、期货公司、基金管理公司和保险公司等金融业经营者集中申报营业额的计算。 银行业金融机构包括商业银行、城市信用合作社、农村信用合作社等吸收公众存款的金融机构以及政策性银行。 对金融资产管理公司、信托公司、财务公司、金融租赁公司、汽车金融公司、货币经纪公司以及经银行业监督管理机构批准设立的其他金融机构的营业额计算办法，适用本办法对银行业金融机构的规定。"},{"i":3,"n":"第三条","txt":"银行业金融机构的营业额要素包括以下项目： 一、 利息净收入； 二、 手续费及佣金净收入； 三、 投资收益； 四、 公允价值变动收益； 五、 汇兑收益； 六、 其他业务收入。"},{"i":4,"n":"第四条","txt":"证券公司的营业额要素包括以下项目： 一、 手续费及佣金净收入（包括经纪业务、资产管理业务、承销与保荐业务和财务顾问业务等）； 二、 利息净收入； 三、 投资收益； 四、 汇兑收益； 五、 其他业务收入。"},{"i":5,"n":"第五条","txt":"期货公司的营业额要素包括以下项目： 一、 手续费及佣金净收入； 二、 银行存款利息净收入。"},{"i":6,"n":"第六条","txt":"基金管理公司的营业额要素包括以下项目： 一、 管理费收入； 二、 手续费收入。"},{"i":7,"n":"第七条","txt":"上述经营者集中申报营业额的计算公式为： 营业额＝（营业额要素累加－营业税金及附加）×10％"},{"i":8,"n":"第八条","txt":"保险公司集中申报营业额的计算公式为： 营业额＝（保费收入－营业税金及附加）×10％ 其中，保费收入＝原保险合同保费收入＋分入保费－分出保费"},{"i":9,"n":"第九条","txt":"以上营业额计算办法仅限用于经营者集中申报。"},{"i":10,"n":"第十条","txt":"本办法自发布之日起三十日后生效。"}],"zuduanwaiguofalvyucuoshibudangyuwaishiyongbanfa":[{"i":1,"n":"第一条","txt":"为了阻断外国法律与措施不当域外适用对中国的影响，维护国家主权、安全、发展利益，保护中国公民、法人或者其他组织的合法权益，根据《中华人民共和国国家安全法》等有关法律，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于外国法律与措施的域外适用违反国际法和国际关系基本准则，不当禁止或者限制中国公民、法人或者其他组织与第三国（地区）及其公民、法人或者其他组织进行正常的经贸及相关活动的情形。"},{"i":3,"n":"第三条","txt":"中国政府坚持独立自主的对外政策，坚持互相尊重主权、互不干涉内政和平等互利等国际关系基本准则，遵守所缔结的国际条约、协定，履行承担的国际义务。"},{"i":4,"n":"第四条","txt":"国家建立由中央国家机关有关部门参加的工作机制（以下简称工作机制），负责外国法律与措施不当域外适用的应对工作。工作机制由国务院商务主管部门牵头，具体事宜由国务院商务主管部门、发展改革部门会同其他有关部门负责。"},{"i":5,"n":"第五条","txt":"中国公民、法人或者其他组织遇到外国法律与措施禁止或者限制其与第三国（地区）及其公民、法人或者其他组织正常的经贸及相关活动情形的，应当在30日内向国务院商务主管部门如实报告有关情况。报告人要求保密的，国务院商务主管部门及其工作人员应当为其保密。"},{"i":6,"n":"第六条","txt":"有关外国法律与措施是否存在不当域外适用情形，由工作机制综合考虑下列因素评估确认： （一）是否违反国际法和国际关系基本准则； （二）对中国国家主权、安全、发展利益可能产生的影响； （三）对中国公民、法人或者其他组织合法权益可能产生的影响； （四）其他应当考虑的因素。"},{"i":7,"n":"第七条","txt":"工作机制经评估，确认有关外国法律与措施存在不当域外适用情形的，可以决定由国务院商务主管部门发布不得承认、不得执行、不得遵守有关外国法律与措施的禁令（以下简称禁令）。 工作机制可以根据实际情况，决定中止或者撤销禁令。"},{"i":8,"n":"第八条","txt":"中国公民、法人或者其他组织可以向国务院商务主管部门申请豁免遵守禁令。 申请豁免遵守禁令的，申请人应当向国务院商务主管部门提交书面申请，书面申请应当包括申请豁免的理由以及申请豁免的范围等内容。国务院商务主管部门应当自受理申请之日起30日内作出是否批准的决定；情况紧急时应当及时作出决定。"},{"i":9,"n":"第九条","txt":"当事人遵守禁令范围内的外国法律与措施，侵害中国公民、法人或者其他组织合法权益的，中国公民、法人或者其他组织可以依法向人民法院提起诉讼，要求该当事人赔偿损失；但是，当事人依照本办法第八条规定获得豁免的除外。 根据禁令范围内的外国法律作出的判决、裁定致使中国公民、法人或者其他组织遭受损失的，中国公民、法人或者其他组织可以依法向人民法院提起诉讼，要求在该判决、裁定中获益的当事人赔偿损失。 本条第一款、第二款规定的当事人拒绝履行人民法院生效的判决、裁定的，中国公民、法人或者其他组织可以依法申请人民法院强制执行。"},{"i":10,"n":"第十条","txt":"工作机制成员单位应当依照各自职责，为中国公民、法人或者其他组织应对外国法律与措施不当域外适用提供指导和服务。"},{"i":11,"n":"第十一条","txt":"中国公民、法人或者其他组织根据禁令，未遵守有关外国法律与措施并因此受到重大损失的，政府有关部门可以根据具体情况给予必要的支持。"},{"i":12,"n":"第十二条","txt":"对外国法律与措施不当域外适用，中国政府可以根据实际情况和需要，采取必要的反制措施。"},{"i":13,"n":"第十三条","txt":"中国公民、法人或者其他组织未按照规定如实报告有关情况或者不遵守禁令的，国务院商务主管部门可以给予警告，责令限期改正，并可以根据情节轻重处以罚款。"},{"i":14,"n":"第十四条","txt":"国务院商务主管部门工作人员未按照规定为报告有关情况的中国公民、法人或者其他组织保密的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":15,"n":"第十五条","txt":"中华人民共和国缔结或者参加的国际条约、协定规定的外国法律与措施域外适用情形，不适用本办法。"},{"i":16,"n":"第十六条","txt":"本办法自公布之日起施行。"}],"lingshoushanggongyingshanggongpingjiaoyiguanlibanfa09c39-2":[{"i":1,"n":"第一条","txt":"为规范零售商与供应商的交易行为，维护公平交易秩序，保障消费者的合法权益，制定本办法。"},{"i":2,"n":"第二条","txt":"零售商与供应商在中华人民共和国境内从事的相关交易活动适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称零售商是指依法在工商行政管理部门办理登记，直接向消费者销售商品，年销售额（从事连锁经营的企业，其销售额包括连锁店铺的销售额）1000万元以上的企业及其分支机构。 本办法所称供应商是指直接向零售商提供商品及相应服务的企业及其分支机构、个体工商户，包括制造商、经销商和其他中介商。"},{"i":4,"n":"第四条","txt":"零售商与供应商的交易活动应当遵循合法、自愿、公平、诚实信用的原则，不得妨碍公平竞争的市场交易秩序，不得侵害交易对方的合法权益。"},{"i":5,"n":"第五条","txt":"鼓励零售商与供应商在交易中采用商务主管部门和工商行政管理部门推荐的合同示范文本。"},{"i":6,"n":"第六条","txt":"零售商不得滥用优势地位从事下列不公平交易行为： （一）与供应商签订特定商品的供货合同，双方就商品的特定规格、型号、款式等达成一致后，又拒绝接收该商品。但具有可归责于供应商的事由，或经供应商同意、零售商负责承担由此产生的损失的除外； （二）要求供应商承担事先未约定的商品损耗责任； （三）事先未约定或者不符合事先约定的商品下架或撤柜的条件，零售商无正当理由将供应商所供货物下架或撤柜的；但是零售商根据法律法规或行政机关依法作出的行政决定将供应商所供货物下架、撤柜的除外； （四）强迫供应商无条件销售返利，或者约定以一定销售额为销售返利前提，未完成约定销售额却向供应商收取返利的； （五）强迫供应商购买指定的商品或接受指定的服务。"},{"i":7,"n":"第七条","txt":"零售商不得从事下列妨碍公平竞争的行为： （一）对供应商直接向消费者、其他经营者销售商品的价格予以限制； （二）对供应商向其他零售商供货或提供销售服务予以限制。"},{"i":8,"n":"第八条","txt":"零售商不得要求供应商派遣人员到零售商经营场所提供服务，下列情形除外： （一）经供应商同意，并且供应商派遣人员仅从事与该供应商所供商品有关的销售服务工作； （二）与供应商协商一致，就供应商派遣人员的工作内容、劳动时间、工作期限等条件达成一致，且派遣人员所需费用由零售商承担。"},{"i":9,"n":"第九条","txt":"存在下列情形的，供应商有权拒绝退货： （一）零售商因自身原因造成商品污染、毁损、变质或过期要求退货，但不承担由此给供应商造成的损失； （二）零售商以调整库存、经营场所改造、更换货架等事由要求退货，且不承担由此给供应商造成的损失； （三）零售商在商品促销期间低价进货，促销期过后将所剩商品以正常价退货。"},{"i":10,"n":"第十条","txt":"零售商向供应商收取促销服务费的，应当事先征得供应商的同意，订立合同，明确约定提供服务的项目、内容、期限；收费的项目、标准、数额、用途、方式及违约责任等内容。 本办法所称促销服务费是指，依照合同约定，为促进供应商特定品牌或特定品种商品的销售，零售商以提供印制海报、开展促销活动、广告宣传等相应服务为条件，向供应商收取的费用。"},{"i":11,"n":"第十一条","txt":"零售商收取促销服务费后，应当按照合同约定向供应商提供相应的服务，不得擅自中止服务或降低服务标准。零售商未完全提供相应服务的，应当向供应商返还未提供服务部分的费用。"},{"i":12,"n":"第十二条","txt":"零售商应当将所收取的促销服务费登记入账，向供应商开具发票，按规定纳税。"},{"i":13,"n":"第十三条","txt":"零售商不得收取或变相收取以下费用： （一）以签订或续签合同为由收取的费用； （二）要求已经按照国家有关规定取得商品条码并可在零售商经营场所内正常使用的供应商，购买店内码而收取的费用； （三）向使用店内码的供应商收取超过实际成本的条码费； （四）店铺改造、装修时，向供应商收取的未专门用于该供应商特定商品销售区域的装修、装饰费； （五）未提供促销服务，以节庆、店庆、新店开业、重新开业、企业上市、合并等为由收取的费用； （六）其他与销售商品没有直接关系、应当由零售商自身承担或未提供服务而收取的费用。"},{"i":14,"n":"第十四条","txt":"零售商与供应商应按商品的属性在合同中明确约定货款支付的期限，但约定的支付期限最长不超过收货后60天。"},{"i":15,"n":"第十五条","txt":"除合同另有约定或供应商没有提供必要单据外，零售商应当及时与供应商对账。"},{"i":16,"n":"第十六条","txt":"零售商以代销方式销售商品的，供应商有权查询零售商尚未付款商品的销售情况，零售商应当提供便利条件，不得拒绝。"},{"i":17,"n":"第十七条","txt":"零售商不得以下列情形为由延迟支付供应商货款： （一）供应商的个别商品未能及时供货； （二）供应商的个别商品的退换货手续尚未办结； （三）供应商所供商品的销售额未达到零售商设定的数额； （四）供应商未与零售商续签供货合同； （五）零售商提出的其他违反公平原则的事由。"},{"i":18,"n":"第十八条","txt":"供应商供货时，不得从事下列妨碍公平竞争的行为： （一）强行搭售零售商未订购的商品； （二）限制零售商销售其他供应商的商品。"},{"i":19,"n":"第十九条","txt":"鼓励行业协会建立商业信用档案，准确、及时、全面地记载和反映零售商、供应商的信用状况，引导零售商、供应商加强自律，合法经营。"},{"i":20,"n":"第二十条","txt":"鼓励行业协会建立零售商货款结算风险预警机制，对零售商拖欠供应商货款数额较大、期限较长的，应当将有关情况通报商务主管部门，并提示相关的供应商。"},{"i":21,"n":"第二十一条","txt":"各地商务、价格、税务、工商等部门依照法律法规及本办法，在各自的职责范围内对本办法规定的行为进行监督管理。对涉嫌犯罪的，由公安机关依法予以查处。 县级以上商务主管部门应会同同级有关部门对零售商供应商公平交易行为实行动态监测，进行风险预警，及时采取防范措施。"},{"i":22,"n":"第二十二条","txt":"对违反本办法规定的行为任何单位和个人均可向上述部门举报，相关部门接到举报后，应当依法予以查处。"},{"i":23,"n":"第二十三条","txt":"零售商或者供应商违反本办法规定的，法律法规有规定的，从其规定；没有规定的，责令改正；有违法所得的，可处违法所得三倍以下罚款，但最高不超过三万元；没有违法所得的，可处一万元以下罚款；并可向社会公告。"},{"i":24,"n":"第二十四条","txt":"县级以上商务、价格、税务、工商等部门发现零售商涉嫌骗取供应商货款的，应当将其涉嫌犯罪的线索及时移送当地公安机关。公安机关应及时开展调查工作，涉嫌犯罪的，依法立案侦查。"},{"i":25,"n":"第二十五条","txt":"各省、自治区、直辖市可结合本地实际，制定规范零售商供应商公平交易行为的有关规定。"},{"i":26,"n":"第二十六条","txt":"本办法自2006年11月15日起施行。"}],"lingshoushanggongyingshanggongpingjiaoyiguanlibanfa09c39":[{"i":1,"n":"第一条","txt":"为规范零售商与供应商的交易行为，维护公平交易秩序，保障消费者的合法权益，制定本办法。"},{"i":2,"n":"第二条","txt":"零售商与供应商在中华人民共和国境内从事的相关交易活动适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称零售商是指依法在工商行政管理部门办理登记，直接向消费者销售商品，年销售额（从事连锁经营的企业，其销售额包括连锁店铺的销售额）1000万元以上的企业及其分支机构。 本办法所称供应商是指直接向零售商提供商品及相应服务的企业及其分支机构、个体工商户，包括制造商、经销商和其他中介商。"},{"i":4,"n":"第四条","txt":"零售商与供应商的交易活动应当遵循合法、自愿、公平、诚实信用的原则，不得妨碍公平竞争的市场交易秩序，不得侵害交易对方的合法权益。"},{"i":5,"n":"第五条","txt":"鼓励零售商与供应商在交易中采用商务主管部门和工商行政管理部门推荐的合同示范文本。"},{"i":6,"n":"第六条","txt":"零售商不得滥用优势地位从事下列不公平交易行为： （一）与供应商签订特定商品的供货合同，双方就商品的特定规格、型号、款式等达成一致后，又拒绝接收该商品。但具有可归责于供应商的事由，或经供应商同意、零售商负责承担由此产生的损失的除外； （二）要求供应商承担事先未约定的商品损耗责任； （三）事先未约定或者不符合事先约定的商品下架或撤柜的条件，零售商无正当理由将供应商所供货物下架或撤柜的；但是零售商根据法律法规或行政机关依法作出的行政决定将供应商所供货物下架、撤柜的除外； （四）强迫供应商无条件销售返利，或者约定以一定销售额为销售返利前提，未完成约定销售额却向供应商收取返利的； （五）强迫供应商购买指定的商品或接受指定的服务。"},{"i":7,"n":"第七条","txt":"零售商不得从事下列妨碍公平竞争的行为： （一）对供应商直接向消费者、其他经营者销售商品的价格予以限制； （二）对供应商向其他零售商供货或提供销售服务予以限制。"},{"i":8,"n":"第八条","txt":"零售商不得要求供应商派遣人员到零售商经营场所提供服务，下列情形除外： （一）经供应商同意，并且供应商派遣人员仅从事与该供应商所供商品有关的销售服务工作； （二）与供应商协商一致，就供应商派遣人员的工作内容、劳动时间、工作期限等条件达成一致，且派遣人员所需费用由零售商承担。"},{"i":9,"n":"第九条","txt":"存在下列情形的，供应商有权拒绝退货： （一）零售商因自身原因造成商品污染、毁损、变质或过期要求退货，但不承担由此给供应商造成的损失； （二）零售商以调整库存、经营场所改造、更换货架等事由要求退货，且不承担由此给供应商造成的损失； （三）零售商在商品促销期间低价进货，促销期过后将所剩商品以正常价退货。"},{"i":10,"n":"第十条","txt":"零售商向供应商收取促销服务费的，应当事先征得供应商的同意，订立合同，明确约定提供服务的项目、内容、期限；收费的项目、标准、数额、用途、方式及违约责任等内容。 本办法所称促销服务费是指，依照合同约定，为促进供应商特定品牌或特定品种商品的销售，零售商以提供印制海报、开展促销活动、广告宣传等相应服务为条件，向供应商收取的费用。"},{"i":11,"n":"第十一条","txt":"零售商收取促销服务费后，应当按照合同约定向供应商提供相应的服务，不得擅自中止服务或降低服务标准。零售商未完全提供相应服务的，应当向供应商返还未提供服务部分的费用。"},{"i":12,"n":"第十二条","txt":"零售商应当将所收取的促销服务费登记入账，向供应商开具发票，按规定纳税。"},{"i":13,"n":"第十三条","txt":"零售商不得收取或变相收取以下费用： （一）以签订或续签合同为由收取的费用； （二）要求已经按照国家有关规定取得商品条码并可在零售商经营场所内正常使用的供应商，购买店内码而收取的费用； （三）向使用店内码的供应商收取超过实际成本的条码费； （四）店铺改造、装修时，向供应商收取的未专门用于该供应商特定商品销售区域的装修、装饰费； （五）未提供促销服务，以节庆、店庆、新店开业、重新开业、企业上市、合并等为由收取的费用； （六）其他与销售商品没有直接关系、应当由零售商自身承担或未提供服务而收取的费用。"},{"i":14,"n":"第十四条","txt":"零售商与供应商应按商品的属性在合同中明确约定货款支付的期限，但约定的支付期限最长不超过收货后60天。"},{"i":15,"n":"第十五条","txt":"除合同另有约定或供应商没有提供必要单据外，零售商应当及时与供应商对账。"},{"i":16,"n":"第十六条","txt":"零售商以代销方式销售商品的，供应商有权查询零售商尚未付款商品的销售情况，零售商应当提供便利条件，不得拒绝。"},{"i":17,"n":"第十七条","txt":"零售商不得以下列情形为由延迟支付供应商货款： （一）供应商的个别商品未能及时供货； （二）供应商的个别商品的退换货手续尚未办结； （三）供应商所供商品的销售额未达到零售商设定的数额； （四）供应商未与零售商续签供货合同； （五）零售商提出的其他违反公平原则的事由。"},{"i":18,"n":"第十八条","txt":"供应商供货时，不得从事下列妨碍公平竞争的行为： （一）强行搭售零售商未订购的商品； （二）限制零售商销售其他供应商的商品。"},{"i":19,"n":"第十九条","txt":"鼓励行业协会建立商业信用档案，准确、及时、全面地记载和反映零售商、供应商的信用状况，引导零售商、供应商加强自律，合法经营。"},{"i":20,"n":"第二十条","txt":"鼓励行业协会建立零售商货款结算风险预警机制，对零售商拖欠供应商货款数额较大、期限较长的，应当将有关情况通报商务主管部门，并提示相关的供应商。"},{"i":21,"n":"第二十一条","txt":"各地商务、价格、税务、工商等部门依照法律法规及本办法，在各自的职责范围内对本办法规定的行为进行监督管理。对涉嫌犯罪的，由公安机关依法予以查处。 县级以上商务主管部门应会同同级有关部门对零售商供应商公平交易行为实行动态监测，进行风险预警，及时采取防范措施。"},{"i":22,"n":"第二十二条","txt":"对违反本办法规定的行为任何单位和个人均可向上述部门举报，相关部门接到举报后，应当依法予以查处。"},{"i":23,"n":"第二十三条","txt":"零售商或者供应商违反本办法规定的，法律法规有规定的，从其规定；没有规定的，责令改正；有违法所得的，可处违法所得三倍以下罚款，但最高不超过三万元；没有违法所得的，可处一万元以下罚款；并可向社会公告。"},{"i":24,"n":"第二十四条","txt":"县级以上商务、价格、税务、工商等部门发现零售商涉嫌骗取供应商货款的，应当将其涉嫌犯罪的线索及时移送当地公安机关。公安机关应及时开展调查工作，涉嫌犯罪的，依法立案侦查。"},{"i":25,"n":"第二十五条","txt":"各省、自治区、直辖市可结合本地实际，制定规范零售商供应商公平交易行为的有关规定。"},{"i":26,"n":"第二十六条","txt":"本办法自2006年11月15日起施行。"}],"lingshoushangcuxiaoxingweiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了规范零售商的促销行为，保障消费者的合法权益，维护公平竞争秩序和社会公共利益，促进零售行业健康有序发展，根据有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"零售商在中华人民共和国境内开展的促销活动适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称零售商是指依法在工商行政管理部门登记注册，直接向消费者销售商品的企业及其分支机构、个体工商户。 本办法所称促销是指零售商为吸引消费者、扩大销售而开展的营销活动。"},{"i":4,"n":"第四条","txt":"零售商开展促销活动应当遵循合法、公平、诚实信用的原则，遵守商业道德，不得开展违反社会公德的促销活动，不得扰乱市场竞争秩序和社会公共秩序，不得侵害消费者和其他经营者的合法权益。"},{"i":5,"n":"第五条","txt":"零售商开展促销活动应当具备相应的安全设备和管理措施，确保消防安全通道的畅通。对开业、节庆、店庆等规模较大的促销活动，零售商应当制定安全应急预案，保证良好的购物秩序，防止因促销活动造成交通拥堵、秩序混乱、疾病传播、人身伤害和财产损失。"},{"i":6,"n":"第六条","txt":"零售商促销活动的广告和其他宣传，其内容应当真实、合法、清晰、易懂，不得使用含糊、易引起误解的语言、文字、图片或影像。不得以保留最终解释权为由，损害消费者的合法权益。"},{"i":7,"n":"第七条","txt":"零售商开展促销活动，应当在经营场所的显著位置明示促销内容，促销内容应当包括促销原因、促销方式、促销规则、促销期限、促销商品的范围，以及相关限制性条件等。 对不参加促销活动的柜台或商品，应当明示，并不得宣称全场促销；明示例外商品、含有限制性条件、附加条件的促销规则时，其文字、图片应当醒目明确。 零售商开展促销活动后在明示期限内不得变更促销内容，因不可抗力而导致的变更除外。"},{"i":8,"n":"第八条","txt":"零售商开展促销活动，其促销商品（包括有奖销售的奖品、赠品）应当依法纳税。"},{"i":9,"n":"第九条","txt":"零售商开展促销活动应当建立健全内部价格管理档案，如实、准确、完整记录促销活动前、促销活动中的价格资料，妥善保存并依法接受监督检查。"},{"i":10,"n":"第十条","txt":"零售商开展促销活动应当明码标价，价签价目齐全、标价内容真实明确、字迹清晰、货签对位、标识醒目。不得在标价之外加价出售商品，不得收取任何未予明示的费用。"},{"i":11,"n":"第十一条","txt":"零售商开展促销活动，不得利用虚构原价打折或者使人误解的标价形式或价格手段欺骗、诱导消费者购买商品。"},{"i":12,"n":"第十二条","txt":"零售商开展促销活动，不得降低促销商品（包括有奖销售的奖品、赠品）的质量和售后服务水平，不得将质量不合格的物品作为奖品、赠品。"},{"i":13,"n":"第十三条","txt":"零售商开展有奖销售活动，应当展示奖品、赠品，不得以虚构的奖品、赠品价值额或含糊的语言文字误导消费者。"},{"i":14,"n":"第十四条","txt":"零售商开展限时促销活动的，应当保证商品在促销时段内的充足供应。 零售商开展限量促销活动的，应当明示促销商品的具体数量。连锁企业所属多家店铺同时开展限量促销活动的，应当明示各店铺促销商品的具体数量。限量促销的，促销商品售完后应即时明示。"},{"i":15,"n":"第十五条","txt":"零售商开展积分优惠卡促销活动的，应当事先明示获得积分的方式、积分有效时间、可以获得的购物优惠等相关内容。 消费者办理积分优惠卡后，零售商不得变更已明示的前款事项；增加消费者权益的变更除外。"},{"i":16,"n":"第十六条","txt":"零售商不得虚构清仓、拆迁、停业、歇业、转行等事由开展促销活动。"},{"i":17,"n":"第十七条","txt":"消费者要求提供促销商品发票或购物凭证的，零售商应当即时开具，并不得要求消费者负担额外的费用。"},{"i":18,"n":"第十八条","txt":"零售商不得以促销为由拒绝退换货或者为消费者退换货设置障碍。"},{"i":19,"n":"第十九条","txt":"鼓励行业协会建立商业零售企业信用档案，加强自律，引导零售商开展合法、公平、诚实信用的促销活动。"},{"i":20,"n":"第二十条","txt":"单店营业面积在3000平方米以上的零售商，以新店开业、节庆、店庆等名义开展促销活动，应当在促销活动结束后十五日内，将其明示的促销内容，向经营场所所在地的县级以上（含县级）商务主管部门备案。"},{"i":21,"n":"第二十一条","txt":"各地商务、价格、税务、工商等部门依照法律法规及有关规定，在各自职责范围内对促销行为进行监督管理。对涉嫌犯罪的，由公安机关依法予以查处。"},{"i":22,"n":"第二十二条","txt":"对违反本办法规定的行为任何单位和个人均可向上述单位举报，相关单位接到举报后，应当依法予以查处。"},{"i":23,"n":"第二十三条","txt":"零售商违反本办法规定，法律法规有规定的，从其规定；没有规定的，责令改正，有违法所得的，可处违法所得三倍以下罚款，但最高不超过三万元；没有违法所得的，可处一万元以下罚款；并可予以公告。"},{"i":24,"n":"第二十四条","txt":"各省、自治区、直辖市可结合本地实际，制定规范促销行为的有关规定。"},{"i":25,"n":"第二十五条","txt":"本办法由商务部、发展改革委、公安部、税务总局、工商总局负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2006年10月15日起施行。"}],"lingshoushangcuxiaoxingweiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范零售商的促销行为，保障消费者的合法权益，维护公平竞争秩序和社会公共利益，促进零售行业健康有序发展，根据有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"零售商在中华人民共和国境内开展的促销活动适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称零售商是指依法在工商行政管理部门登记注册，直接向消费者销售商品的企业及其分支机构、个体工商户。 本办法所称促销是指零售商为吸引消费者、扩大销售而开展的营销活动。"},{"i":4,"n":"第四条","txt":"零售商开展促销活动应当遵循合法、公平、诚实信用的原则，遵守商业道德，不得开展违反社会公德的促销活动，不得扰乱市场竞争秩序和社会公共秩序，不得侵害消费者和其他经营者的合法权益。"},{"i":5,"n":"第五条","txt":"零售商开展促销活动应当具备相应的安全设备和管理措施，确保消防安全通道的畅通。对开业、节庆、店庆等规模较大的促销活动，零售商应当制定安全应急预案，保证良好的购物秩序，防止因促销活动造成交通拥堵、秩序混乱、疾病传播、人身伤害和财产损失。"},{"i":6,"n":"第六条","txt":"零售商促销活动的广告和其他宣传，其内容应当真实、合法、清晰、易懂，不得使用含糊、易引起误解的语言、文字、图片或影像。不得以保留最终解释权为由，损害消费者的合法权益。"},{"i":7,"n":"第七条","txt":"零售商开展促销活动，应当在经营场所的显著位置明示促销内容，促销内容应当包括促销原因、促销方式、促销规则、促销期限、促销商品的范围，以及相关限制性条件等。 对不参加促销活动的柜台或商品，应当明示，并不得宣称全场促销；明示例外商品、含有限制性条件、附加条件的促销规则时，其文字、图片应当醒目明确。 零售商开展促销活动后在明示期限内不得变更促销内容，因不可抗力而导致的变更除外。"},{"i":8,"n":"第八条","txt":"零售商开展促销活动，其促销商品（包括有奖销售的奖品、赠品）应当依法纳税。"},{"i":9,"n":"第九条","txt":"零售商开展促销活动应当建立健全内部价格管理档案，如实、准确、完整记录促销活动前、促销活动中的价格资料，妥善保存并依法接受监督检查。"},{"i":10,"n":"第十条","txt":"零售商开展促销活动应当明码标价，价签价目齐全、标价内容真实明确、字迹清晰、货签对位、标识醒目。不得在标价之外加价出售商品，不得收取任何未予明示的费用。"},{"i":11,"n":"第十一条","txt":"零售商开展促销活动，不得利用虚构原价打折或者使人误解的标价形式或价格手段欺骗、诱导消费者购买商品。"},{"i":12,"n":"第十二条","txt":"零售商开展促销活动，不得降低促销商品（包括有奖销售的奖品、赠品）的质量和售后服务水平，不得将质量不合格的物品作为奖品、赠品。"},{"i":13,"n":"第十三条","txt":"零售商开展有奖销售活动，应当展示奖品、赠品，不得以虚构的奖品、赠品价值额或含糊的语言文字误导消费者。"},{"i":14,"n":"第十四条","txt":"零售商开展限时促销活动的，应当保证商品在促销时段内的充足供应。 零售商开展限量促销活动的，应当明示促销商品的具体数量。连锁企业所属多家店铺同时开展限量促销活动的，应当明示各店铺促销商品的具体数量。限量促销的，促销商品售完后应即时明示。"},{"i":15,"n":"第十五条","txt":"零售商开展积分优惠卡促销活动的，应当事先明示获得积分的方式、积分有效时间、可以获得的购物优惠等相关内容。 消费者办理积分优惠卡后，零售商不得变更已明示的前款事项；增加消费者权益的变更除外。"},{"i":16,"n":"第十六条","txt":"零售商不得虚构清仓、拆迁、停业、歇业、转行等事由开展促销活动。"},{"i":17,"n":"第十七条","txt":"消费者要求提供促销商品发票或购物凭证的，零售商应当即时开具，并不得要求消费者负担额外的费用。"},{"i":18,"n":"第十八条","txt":"零售商不得以促销为由拒绝退换货或者为消费者退换货设置障碍。"},{"i":19,"n":"第十九条","txt":"鼓励行业协会建立商业零售企业信用档案，加强自律，引导零售商开展合法、公平、诚实信用的促销活动。"},{"i":20,"n":"第二十条","txt":"单店营业面积在3000平方米以上的零售商，以新店开业、节庆、店庆等名义开展促销活动，应当在促销活动结束后十五日内，将其明示的促销内容，向经营场所所在地的县级以上（含县级）商务主管部门备案。"},{"i":21,"n":"第二十一条","txt":"各地商务、价格、税务、工商等部门依照法律法规及有关规定，在各自职责范围内对促销行为进行监督管理。对涉嫌犯罪的，由公安机关依法予以查处。"},{"i":22,"n":"第二十二条","txt":"对违反本办法规定的行为任何单位和个人均可向上述单位举报，相关单位接到举报后，应当依法予以查处。"},{"i":23,"n":"第二十三条","txt":"零售商违反本办法规定，法律法规有规定的，从其规定；没有规定的，责令改正，有违法所得的，可处违法所得三倍以下罚款，但最高不超过三万元；没有违法所得的，可处一万元以下罚款；并可予以公告。"},{"i":24,"n":"第二十四条","txt":"各省、自治区、直辖市可结合本地实际，制定规范促销行为的有关规定。"},{"i":25,"n":"第二十五条","txt":"本办法由商务部、发展改革委、公安部、税务总局、工商总局负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2006年10月15日起施行。"}],"canyinyecujinhejingyingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范餐饮服务经营活动，引导和促进餐饮行业健康有序发展，维护消费者和经营者的合法权益，依据国家有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事餐饮服务经营活动，适用本办法。 本办法所称餐饮服务经营活动，是指通过即时加工制作成品或半成品、商业销售和服务性劳动等，向消费者提供食品和消费场所及设施的经营行为。"},{"i":3,"n":"第三条","txt":"商务部负责全国餐饮行业管理工作，制定政策规划，完善标准体系，开展监测分析，会同相关部门鼓励和引导餐饮服务经营者制止餐饮浪费，配合有关部门做好餐饮业安全生产管理工作，指导督促餐饮服务经营者加强安全管理，促进餐饮业高质量发展。 国家发展和改革委员会根据《中华人民共和国反食品浪费法》和部门职责，加强对全国反食品浪费工作的组织协调，会同国务院有关部门每年分析评估食品浪费情况，整体部署反食品浪费工作。 县级以上地方商务、发展改革等主管部门依法依规在各自职责范围内进行管理。"},{"i":4,"n":"第四条","txt":"国家支持餐饮业健康规范发展，鼓励餐饮服务经营者发展大众化餐饮、社区餐饮、绿色健康餐饮，提升服务品质，创新消费场景，丰富餐饮供给。"},{"i":5,"n":"第五条","txt":"国家鼓励和支持餐饮服务经营者、行业协会、相关研究机构挖掘、传承传统餐饮文化，开展餐饮业发展研究，推进餐饮业与农业生产、食品加工、旅游休闲等产业联动发展。 鼓励和支持有条件的餐饮服务经营者积极开展对外交流合作，弘扬中华优秀餐饮文化。"},{"i":6,"n":"第六条","txt":"国家鼓励餐饮服务经营者进行数字化升级改造，提升数字化经营和管理能力，加快线上线下融合发展。 鼓励和支持餐饮外卖平台与中小餐饮服务经营者加强资源共享与合作，为中小餐饮服务经营者提供服务。"},{"i":7,"n":"第七条","txt":"国家鼓励餐饮服务经营者、行业协会制定餐饮领域企业标准和团体标准，参与国家标准、行业标准、地方标准制修订工作。"},{"i":8,"n":"第八条","txt":"餐饮行业协会应当按照有关法律、法规和规章的规定，发挥行业自律、引导、服务作用，促进餐饮业相关标准的推广实施。开展食品浪费监测，加强分析评估，每年向社会公布有关反食品浪费情况及监测评估结果，为国家机关制定法律、法规、政策、标准和开展有关研究提供支持，接受社会监督。"},{"i":9,"n":"第九条","txt":"餐饮服务经营者应当严格按照法律、法规和规章的有关规定从事经营活动，建立健全各项制度，积极贯彻国家和行业有关经营管理、产品、服务等方面的标准。"},{"i":10,"n":"第十条","txt":"餐饮服务经营者应当建立健全突发事件应急预案、应对机制，明确职责分工，落实责任。发生突发事件时，应当立即启动应急处理工作程序并及时向政府有关部门报告事件情况及处理结果。"},{"i":11,"n":"第十一条","txt":"餐饮服务经营者应当在经营管理中全面贯彻反食品浪费理念，加强服务人员培训，将珍惜粮食、反对浪费纳入服务人员培训内容，减少食品食材过程损耗。 鼓励餐饮服务经营者运用信息化手段分析用餐需求，对食品采购、储存、加工等进行科学管理，提高食材利用率。"},{"i":12,"n":"第十二条","txt":"餐饮服务经营者不得以任何方式诱导、误导消费者超量点餐。 餐饮服务经营者应当在大厅、包间、餐桌等餐饮场所的醒目位置张贴或者摆放反食品浪费标识，引导消费者按需适量点餐，对明显过量点餐的消费者进行提醒。"},{"i":13,"n":"第十三条","txt":"餐饮服务经营者应当提升餐饮供给质量，丰富供餐形式，合理配置小分量、多规格的主食、菜品、饮品等，可以通过在菜单上标注食品主要食材、分量、口味、建议消费人数等方式充实菜单信息，为消费者提供点餐提示。 餐饮服务经营者根据消费者需要配备公勺公筷。鼓励提供分餐服务。 餐饮服务经营者可以对参与“光盘行动”的消费者给予奖励，主动提醒消费者在餐后打包剩余食品，根据消费者需要提供打包服务。"},{"i":14,"n":"第十四条","txt":"提供团体用餐、宴席服务的餐饮服务经营者，应当按照防止食品浪费理念科学设计菜单，合理安排用餐流程和餐台数量，引导消费者根据用餐人数等因素合理订餐，允许消费者在约定时限内合理调整宴会套餐菜品，并由双方协商处理方案。 提供自助餐服务的餐饮服务经营者，应当主动告知消费规则和防止食品浪费要求，建立备餐评估和供餐巡视制度，在取餐区和用餐区分别张贴或者摆放反食品浪费标识，提供不同规格餐具，提醒消费者按需、适量、多次取餐，对有特殊食用要求的食品进行说明。 餐饮服务经营者通过餐饮外卖平台或自有外卖信息系统提供服务的，应当在餐品浏览页面标注食品分量、规格或建议消费人数等信息，主动提示引导消费者防止食品浪费。"},{"i":15,"n":"第十五条","txt":"餐饮服务经营者应当依法履行厨余垃圾源头减量义务，通过完善食材管理、改进烹饪工艺等方式减少厨余垃圾。 餐饮服务经营者不得随意处理厨余垃圾，应按规定由具备条件的企业进行资源化利用。 餐饮服务经营者可以对造成明显浪费的消费者收取处理厨余垃圾的相应费用，收费标准应当在经营场所的显著位置公示。"},{"i":16,"n":"第十六条","txt":"禁止餐饮服务经营者设置最低消费。"},{"i":17,"n":"第十七条","txt":"餐饮服务经营者应当建立健全顾客投诉制度，及时处理消费者投诉并向投诉者反馈处理结果。"},{"i":18,"n":"第十八条","txt":"县级以上地方商务主管部门应当加强餐饮业监测分析，配合有关部门或依据地方人民政府职责分工做好餐饮业安全生产管理工作，可结合实际制定和实施促进餐饮业高质量发展的政策措施，建立健全工作协调机制，完善标准体系，建设培育餐饮业发展促进平台。"},{"i":19,"n":"第十九条","txt":"县级以上地方商务主管部门应当采取措施，发展和培育地方特色餐饮，加强地方特色餐饮宣传推广。"},{"i":20,"n":"第二十条","txt":"县级以上地方商务主管部门发现餐饮服务经营者在生产经营过程中严重浪费食品的，可以对其法定代表人或者主要负责人进行约谈。被约谈的餐饮服务经营者应当立即整改。"},{"i":21,"n":"第二十一条","txt":"违反本办法，餐饮服务经营者未主动对消费者进行防止食品浪费提示提醒的，诱导、误导消费者超量点餐造成明显浪费的，在食品生产经营过程中造成严重食品浪费的，依照《中华人民共和国反食品浪费法》第二十八条规定予以处罚。"},{"i":22,"n":"第二十二条","txt":"商务、发展改革等主管部门工作人员在工作中滥用职权、徇私舞弊的，对负有责任的领导人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"省级商务主管部门可以依据本办法，结合本行政区域内餐饮业发展的实际情况，会同同级发展改革等主管部门制定有关实施细则。"},{"i":24,"n":"第二十四条","txt":"本办法规定的县级以上地方商务主管部门执法职责发生调整的，该相关执法职责由本级人民政府确定的部门实施。"},{"i":25,"n":"第二十五条","txt":"本办法自2025年6月15日起实施。商务部、国家发展改革委令2014年第4号《餐饮业经营管理办法（试行）》同时废止。"}],"canyinyejingyingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范餐饮服务经营活动，引导和促进餐饮行业健康有序发展，维护消费者和经营者的合法权益，依据国家有关法律、法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内从事餐饮经营活动，适用本办法。 本办法所称餐饮经营活动，是指通过即时加工制作成品或半成品、商业销售和服务性劳动等，向消费者提供食品和消费场所及设施的经营行为。"},{"i":3,"n":"第三条","txt":"商务部负责全国餐饮行业管理工作，制定行业规划、政策和标准，开展行业统计，规范行业秩序。地方各级人民政府商务主管部门负责本行政区域内餐饮业行业管理工作。"},{"i":4,"n":"第四条","txt":"国家鼓励餐饮经营者发展特色餐饮、快餐、早餐、团膳、送餐等大众化餐饮，提供标准化菜品，方便消费者自主调味，发展可选套餐，提供小份菜。"},{"i":5,"n":"第五条","txt":"餐饮行业协会应当按照有关法律、法规和规章的规定，发挥行业自律、引导、服务作用，促进餐饮业行业标准的推广实施，指导企业做好节能减排、资源节约和综合利用工作。 餐饮行业协会应通过制定行业公约等方式引导餐饮经营者节约资源、反对浪费。"},{"i":6,"n":"第六条","txt":"餐饮经营者应当严格按照法律、法规和规章的有关规定从事经营活动，建立健全各项制度，积极贯彻国家和行业有关经营管理、产品、服务等方面的标准。"},{"i":7,"n":"第七条","txt":"餐饮经营者应当做好节能减排、资源节约和综合利用工作。 餐饮经营者应当建立节俭消费提醒提示制度，并在醒目位置张贴节约标识，贯彻节约用餐、文明用餐标准。"},{"i":8,"n":"第八条","txt":"餐饮经营者应引导消费者餐前适量点餐，餐后主动帮助打包，对节约用餐的消费者给予表扬和奖励。"},{"i":9,"n":"第九条","txt":"餐饮经营者不得销售不符合国家产品质量及食品安全强制标准的食品。"},{"i":10,"n":"第十条","txt":"餐饮经营者不得随意处置餐厨废弃物，应按规定由具备条件的企业进行资源化利用。"},{"i":11,"n":"第十一条","txt":"餐饮经营者所售食品或提供的服务项目标价，按照国务院价格主管部门制定的有关规定执行。"},{"i":12,"n":"第十二条","txt":"禁止餐饮经营者设置最低消费。"},{"i":13,"n":"第十三条","txt":"提供外送服务的餐饮经营者，应当建立健全相应的服务流程，并明示提供外送服务的时间、外送范围以及收费标准；根据消费者的订单和食品安全的要求，选择适当的交通工具、设备，按时、按质、按量送达消费者，并提供相应的单据。"},{"i":14,"n":"第十四条","txt":"餐饮经营者开展促销活动的，应当明示促销内容，包括促销原因、促销方式、促销规则、促销期限、促销商品的范围，以及相关限制性条件。 餐饮经营者应当在促销活动开始前做好原材料储备及服务准备工作，依照承诺履行相关义务。 促销活动期间，餐饮经营者不得故意拖延提供相关商品或服务，不得以任何形式降低商品质量或服务水平。"},{"i":15,"n":"第十五条","txt":"餐饮经营者应当建立健全顾客投诉制度，明确具体部门或人员受理、处理消费者投诉。投诉的受理、转交以及处理结果应当通知投诉者。"},{"i":16,"n":"第十六条","txt":"餐饮经营者应当建立健全突发事件应急预案、应对机制，明确职责分工，落实责任。发生突发事件时，应当立即启动应急处理工作程序并及时向政府有关部门报告事件情况及处理结果。"},{"i":17,"n":"第十七条","txt":"县级以上地方商务主管部门应当建立或委托相关机构建立经营者及其负责人、高层管理人员信用记录，将其纳入国家统一的信用信息平台，并依法向社会公开严重违法失信行为。餐饮经营者及其负责人、高层管理人员应当按照商务主管部门要求提供与餐饮经营相关的信用信息。 商务主管部门应当将餐饮经营者违反本办法的行为及行政处罚情况进行汇总，建立不良记录档案，并可向社会公布。"},{"i":18,"n":"第十八条","txt":"县级以上地方商务主管部门应当定期对餐饮行业开展反食品浪费相关行为进行监督检查，并给予相应奖励或处罚。"},{"i":19,"n":"第十九条","txt":"县级以上地方商务主管部门应当定期开展本行政区域内的餐饮业行业统计工作。餐饮经营者应当按照商务主管部门要求，及时准确报送相关信息。"},{"i":20,"n":"第二十条","txt":"商务主管部门应当建立、健全举报制度，设立、公布投诉电话。 任何组织和个人对违反本办法的行为，有权向商务主管部门举报。商务主管部门接到举报后，对属于职责范围的，应当在20个工作日内作出处理决定；不属于职责范围的，应当在5个工作日内转交有关部门依法处理。处理过程中，商务主管部门应当对举报人的相关信息进行保密。"},{"i":21,"n":"第二十一条","txt":"商务、价格等主管部门依照法律法规、规章及有关规定，在各自职责范围内对餐饮业经营行为进行监督管理。 对于餐饮经营者违反本办法的行为，法律法规及规章有规定的，商务主管部门可提请有关部门依法处罚；没有规定的，由商务主管部门责令限期改正，其中有违法所得的，可处违法所得3倍以下罚款，但最高不超过3万元；没有违法所得的，可处1万元以下罚款；对涉嫌犯罪的，依法移送司法机关处理。 商务、价格等主管部门应当自作出行政处罚决定之日起20个工作日内，公开行政处罚决定书的主要内容，但行政处罚决定书中涉及国家秘密、商业秘密、个人隐私的内容依法不予公开。"},{"i":22,"n":"第二十二条","txt":"商务、价格等主管部门工作人员在监督管理工作中滥用职权、徇私舞弊的，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"省级商务主管部门可依据本办法，结合本行政区域内餐饮业发展的实际情况，制定有关实施办法。"},{"i":24,"n":"第二十四条","txt":"本办法自2014年11月1日起实施。"}],"mahuangsuleiyizhiduhuaxuepinchukouqiyehedingzanxin2206b4":[{"i":1,"n":"第一条","txt":"为加强对麻黄素类易制毒化学品的出口管理，规范麻黄素类易制毒化学品出口经营秩序，防止其流入非法制毒渠道，根据《易制毒化学品管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称麻黄素类易制毒化学品，是指列入《易制毒化学品管理条例》附表中的麻黄素、伪麻黄素、消旋麻黄素、去甲麻黄素、甲基麻黄素、麻黄浸膏、麻黄浸膏粉等麻黄素类物质及其盐类，包括原料药及其单方制剂。"},{"i":3,"n":"第三条","txt":"麻黄素类易制毒化学品出口由商务部会同国家食品药品监督管理局依据本办法核定的企业经营。 麻黄素类易制毒化学品出口经营企业名单每两年核定一次，由商务部以公告的形式公布。"},{"i":4,"n":"第四条","txt":"商务部负责全国麻黄素类易制毒化学品出口企业核定管理工作。各省、自治区、直辖市及计划单列市商务主管部门（以下简称省级商务主管部门）受商务部委托负责本地区麻黄素类易制毒化学品出口企业核定管理有关工作。"},{"i":5,"n":"第五条","txt":"麻黄素类易制毒化学品出口限定在北京、天津、上海、深圳口岸报关并于同口岸实际离境。其他海关一律不予受理此类产品的出口报关业务。"},{"i":6,"n":"第六条","txt":"申请麻黄素类易制毒化学品出口核定经营资格的企业应具备以下基本条件： （一）　依法办理对外贸易经营者备案登记手续，或者为依法批准设立的外商投资企业； （二）　近3年内未受过刑事处罚，或因进行非法经营活动受过有关部门行政处罚； （三）　已建立健全专门的麻黄素类易制毒化学品出口管理机制并配备专门管理人员； （四） 企业法定代表人及管理人员须具备相关易制毒化学品知识及管理经验； （五）　有相对固定的原料供应渠道。"},{"i":7,"n":"第七条","txt":"核定期限届满前三个月，商务部发出资格核定通知，企业应在通知规定时限内提交符合第六条规定的证明文件报省级商务主管部门。 申请企业为外商投资企业的，还应提交外商投资企业批准证书（副本影印件）及企业合营合同或章程、营业执照（副本影印件）。 省级商务主管部门应自收到企业提交的符合规定的有关材料之日起20日内完成初审工作，经初审合格后将初审意见及有关材料报商务部审定。 商务部自收到初审意见及有关材料之日起20日内会同国家食品药品监督管理局和有关专家根据企业基本情况、国内外禁毒形势、市场状况及外贸秩序等进行综合评定，必要时可进行实地考察，核定出口经营企业并公布名单。"},{"i":8,"n":"第八条","txt":"经核定取得麻黄素类易制毒化学品出口经营资格的企业（以下简称核定企业）申请麻黄素类易制毒化学品出口许可应按照《易制毒化学品管理条　例》和《易制毒化学品进出口管理规定》有关规定办理。"},{"i":9,"n":"第九条","txt":"核定企业中的生产企业只能出口自产麻黄素类易制毒化学品；核定企业中的流通企业只能收购具有麻黄素类易制毒化学品生产、经营许可企业的麻黄素类易制毒化学品用于出口。"},{"i":10,"n":"第十条","txt":"核定企业须建立专门的麻黄素类易制毒化学品出口台帐，详细记录有关出口经营活动，并保留相关记录两年备查。"},{"i":11,"n":"第十一条","txt":"核定企业应当于每年3月31日前向省级商务主管部门及公安部门、食品药品监管部门报告上年度麻黄素类易制毒化学品出口情况。"},{"i":12,"n":"第十二条","txt":"核定企业应接受商务主管部门及食品药品监管部门监督管理。"},{"i":13,"n":"第十三条","txt":"为保护麻黄草资源，保护自然环境，国家禁止出口天然麻黄草。"},{"i":14,"n":"第十四条","txt":"以欺骗或者其他不正当手段获取核定企业资格的，商务部依法撤销其核定企业资格，并可给予警告，或处3万元以下罚款；违法企业在三年内不得再次申请核定企业资格。"},{"i":15,"n":"第十五条","txt":"违反本办法第九至十二条的，商务部责令限期改正，并可处警告或3万元以下罚款；逾期拒不改正的，商务部可撤销核定企业资格。"},{"i":16,"n":"第十六条","txt":"违反《易制毒化学品管理条例》、《易制毒化学品进出口管理规定》和本办法出口易制毒化学品的，依据《易制毒化学品管理条例》和《易制毒化学品进出口管理规定》的有关规定予以处理；商务部可视情节轻重，撤销违法企业的核定企业资格。"},{"i":17,"n":"第十七条","txt":"自本办法施行之日起60日内，原核定麻黄素类易制毒化学品出口经营企业应按照本规定重新进行资格核定。在规定期限内未履行相关手续的，取消原核定资格。"},{"i":18,"n":"第十八条","txt":"本办法自公布之日起30日后施行。《关于加强麻黄素类产品出口管理有关问题的通知》（〔1998〕外经贸管发第573号）同时废止。"}]};
